-- churchApp: import the Nau Mpro hymn book (520 songs) into lyric_songs.
-- Run once in the Supabase SQL editor, after lyric-category-language.sql.
-- The hymns belong to no one account (owner_id stays empty), so every user can read them and nobody can edit them.
-- Skips any song already imported (matched on local_id 'nau-mpro-NNNN'), so it is safe to run twice.

alter table public.lyric_songs alter column owner_id drop not null;

with src as (
  select * from jsonb_to_recordset($json$[{"local_id": "nau-mpro-0001", "title": "MÂT TON NAU BRAH AMOH YÊ-SU", "song_number": "1", "lyrics": "MÂT TON NAU BRAH AMOH YÊ-SU\n\nTC 8, KM 1, KMM 4\n\nVerse 1\nMât ton nau Brah Amoh Yê-su, ăn lĕ rngôch bunuyh tâm rnê.\nChon mon ta năp păn mbah ma Păng, yor lah Păng Brah toyh Ngăn.\nChon mon ta năp păn mbah ma Păng, Yor lah Păng Brah toyh Ngăn.\n\nVerse 2\nMâu dơi he chuêl ôh nau Păng rŏng, mâu dơi chuêl nau Păng yỗ.\nKah gĭt ƀa-ƀơ tâm rnê lah ueh, yor lah Păng Brah toyh Ngăn.\nKah gĭt ƀa-ƀơ tâm rnê lah ueh, Yor lah Păng Brah toyh Ngăn.\n\nVerse 3\nLĕ rngôch mpôl bunuyh tâm neh ntu aơ, tĭng ndỗ Brah Yê-su Krist.\nPăng rklaih dơm dam lĕ rngôch nuyh tih, yor lah Păng Brah toyh Ngăn.\nPăng rklaih dơm dam lĕ rngôch nuyh tih, Yor lah Păng Brah toyh Ngăn.\n\nVerse 4\nYê-su mra ƀư rai lĕ brah mhĭk, mâu ăn păng ƀư ma bunuyh.\nPăng tâm chuai he, klach nau r-mal, yor lah Păng Brah toyh Ngăn.\nPăng tâm chuai he, klach nau rmal, Yor lah Păng Brah toyh Ngăn.\nA-MEN.\n", "category": "Yơk mbah ma Kôranh Brah", "language": "Bunong"}, {"local_id": "nau-mpro-0002", "title": "GÂP TÂM RNÊ PĂNG", "song_number": "2", "lyrics": "GÂP TÂM RNÊ PĂNG\n\nTC 19, KM 2, KMM 9\n\nVerse 1\nKôranh Brah Yê-su ôp gâp pô aơ: \"mâm ƀư may ŭch jêng kloh lĕ?\"\nGâp plỡ lah ma Păng, gâp ŭch lĕ! Mham khlay May rao gâp kloh ngăn.\n\nChorus\nGâp tâm rnê păng, gâp tâm rnê Păng, mât ton ma Biăp Ueh Brah Ndu.\nPăng ƀư brah jêh ma săk jăn Păng, gay tâm rklaih lĕ rngôch nau tih mhĭk he.\n\nVerse 2\nGâp nhhơr lĕ nuih n'hâm ma Yê-su, mâu hôm ŭch tĭng brah mhĭk ôh.\nGâp iăng gŭ đăp rmên ndrel Yê-su. Yor lah Păng yỗ jêh ma gâp.\n\nChorus\nGâp tâm rnê păng, gâp tâm rnê Păng, mât ton ma Biăp Ueh Brah Ndu.\nPăng ƀư brah jêh ma săk jăn Păng, gay tâm rklaih lĕ rngôch nau tih mhĭk he.\n\nVerse 3\nAmoh Yê-su toyh lơn ma lĕ rngôch, gâp rŏng Păng, ŭch tĭng ndỗ ngăn.\nPăng gŭ rêh kêng Brah Ndu Nơm klơ. Kâp mbơh sơm sâm kơl phung he.\n\nChorus\nGâp tâm rnê păng, gâp tâm rnê Păng, mât ton ma Biăp Ueh Brah Ndu.\nPăng ƀư brah jêh ma săk jăn Păng, gay tâm rklaih lĕ rngôch nau tih mhĭk he.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0003", "title": "TÂM RNÊ YÊ-SU", "song_number": "3", "lyrics": "TÂM RNÊ YÊ-SU\n\nTC 20, KM 3, KMM 8\n\nVerse 1\nMât ton Brah Ndu, Nơm Kôranh ta klơ, Hađăch toyh lơn ma lĕ rngôch.\nPăng ăn Kon Păng khĭt yor ma bunyh, ŭch tâm rklaih lĕ phung tih.\n\nChorus\nTâm rnê Yê-su, Tâm rnê Yê-su, Tâm rnê Amoh Brah Yê-su.\nTâm rnê Yê-su, tâm rnê Yê-su, tâm rnê Amoh Brah Yê-su.\n\nVerse 2\nAmoh Păng khlay lơn ma lĕ rngôch amoh, geh nau tâm rnê âk lơn.\nTa năp Brah Ndu, Mbỡ he ta klơ, ntŭk phung tông mpăr yơk mbah.\n\nChorus\nTâm rnê Yê-su, Tâm rnê Yê-su, Tâm rnê Amoh Brah Yê-su.\nTâm rnê Yê-su, tâm rnê Yê-su, tâm rnê Amoh Brah Yê-su.\n\nVerse 3\nNơm Tâm Rklaih jêng mĭt jiăng bunuyh, roh yot yor ma nau tih.\nMay jêng Nơm geh nau dơi tâm rklaih, May khĭt yor ma lĕ rngôch.\n\nChorus\nTâm rnê Yê-su, Tâm rnê Yê-su, Tâm rnê Amoh Brah Yê-su.\nTâm rnê Yê-su, tâm rnê Yê-su, tâm rnê Amoh Brah Yê-su.\n\nVerse 4\nAmoh Păng jêng khlay ir ar ngăn ngên, dơi lơn ma amoh neh ntu.\nDơi lơn ma amoh tâm bri brah yang, Yê-su jêng Hađăch n'ho ro.\n\nChorus\nTâm rnê Yê-su, Tâm rnê Yê-su, Tâm rnê Amoh Brah Yê-su.\nTâm rnê Yê-su, tâm rnê Yê-su, tâm rnê Amoh Brah Yê-su.\nA-MEN.\n", "category": "Yơk mbah ma Kôranh Brah", "language": "Bunong"}, {"local_id": "nau-mpro-0004", "title": "HĂN HOM HE", "song_number": "4", "lyrics": "HĂN HOM HE\n\nTC 22, KM 4, KMM 10\n\nVerse 1\nVăch hom hơi phung tâm kơl, mprơ ndrel ma nau hâk răm.\nĂn lĕ ƀon lan gĭt Nơm Tâm Rklaih, ăn lĕ ƀon lan gĭt Nơm Tâm Rklaih,\njêh ri he gŭ maak răm, yor Yê-su Krist rŏng he.\n\nChorus\nHăn hom he, hăn hom he, phung tâm kơl chroh Yê-su hăn ndrel,\nhe hăn ma Ƀon Brah Ndu leo klơ, geh nau ma-ak răm ngăn ngên.\n\nVerse 2\nMbu nâm mâu năl Yê-su, mâu dơi mprơ tâm rnê Păng.\nKnŏng phung chroh jêh ma Yê-su Krist, knŏng phung chroh jêh ma Yê-su Krist,\ndơi mprơ tâm rnê ma Păng, dơi mprơ tâm rnê ma Păng.\n\nChorus\nHăn hom he, hăn hom he, phung tâm kơl chroh Yê-su hăn ndrel,\nhe hăn ma Ƀon Brah Ndu leo klơ, geh nau ma-ak răm ngăn ngên.\n\nVerse 3\nHe mprơ bâr ngơi ăn nteh, jêh ri mbơh nau mhe mhan.\nYor lah he jêng phung chroh Yê-su, yor lah he jêng phung chroh Yê-su,\nleo hăn tât Ƀon ka-lơ, leo hăn tât Ƀon ka-lơ.\n\nChorus\nHăn hom he, hăn hom he, phung tâm kơl chroh Yê-su hăn ndrel,\nhe hăn ma Ƀon Brah Ndu leo klơ, geh nau ma-ak răm ngăn ngên.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0005", "title": "LĔ RNGÔCH BUNUYH TA NEH NTU TÂM RNÊ", "song_number": "5", "lyrics": "LĔ RNGÔCH BUNUYH TA NEH NTU TÂM RNÊ\n\nTC 5, KM 5, 59, KMM 5\n\nVerse 1\nLĕ rngôch bunuyh ta neh ntu tâm rnê, mât ton Brah Ndu ma nau hâk răm.\nHe tâm rnê Păng mprơ bâr ngơi ueh, nkoch bri lư n'găr Amoh Păng lam ntŭk.\n\nVerse 2\nAy may gĭt Brah Ndu Kôranh Brah ngăn, mâu hôm geh Brah êng ban Păng ôh.\nPăng rhăk njêng lĕ mpô mpa kăl e, jêh ri Păng djôt he tâm ti Păng.\n\nVerse 3\nYor lah Păng jêng Kôranh Brah Ndu ngăn, ăn he rŏng ma Păng lĕ nuih n'hâm.\nPăng yỗ ngăn jêh lĕ nau tih he, nau Păng ngơi mâu geh mâp rgâl ôh.\n\nVerse 4\nVăch lĕ rngôch bunuyh mât ton Brah Ndu, Păng jêng Kôranh Brah toyh ta klơ trôk.\nTâm rnê ma Amoh Brah Yê-su Krist, jêh ri mât ton ma Brah Huêng Ueh.\n", "category": "Yơk mbah ma Kôranh Brah", "language": "Bunong"}, {"local_id": "nau-mpro-0006", "title": "MÂT TON, MÂT TON, MÂT TON", "song_number": "6", "lyrics": "MÂT TON, MÂT TON, MÂT TON\n\nTC 40, KM 6, KMM 11\n\nVerse 1\nMât ton, mât ton, mât ton, Brah Ndu jêng Kôranh Brah he.\nMăng nâm nar hên ŭch mprơ, tâm rnê răm hâu ngăn ngên.\nMât ton, mât ton, mât ton, Brah Ndu jêng Tu Brah ngăn.\nMbỡ Kon, Brah Huêng Ueh, jêng nguay Kôranh Brah dơm.\n\nVerse 2\nMât ton, mât ton, mât ton, Brah Ndu Mbỡ he ta klơ.\nLĕ rngôch phung Tông mpăr mbah, ta năp May răm hâu ngăn.\nMât ton, mât ton mât ton, Brah Ndu jêng Tu nau yỗ.\nMâu blau lôch bôl ôh, May jêng mro mrăng ngăn.\n\nVerse 3\nMât ton, mât ton, mât ton, Brah Ndu jêng Nơm Rklaih he.\nMâu hôm geh Brah kơt May, knŏng May dơm geh nau sŏng.\nMât ton, mât ton, mât ton, Brah Ndu jêng Tu nau rŏng.\nMay ăn jêh Kon, May khĭt ta si tâm rkăng.\n\nVerse 4\nMât ton, mât ton, mât ton, Brah Ndu jêng Kôranh Brah he.\nLĕ bunuyh lam neh ntu, tâm rnê rhơn May hâu ngăn.\nMât ton, mât ton, mât ton, Hên nhhơr nuih n'hâm ma May.\nDăn May iăt hên mprơ, tâm rnê ma May. A-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0007", "title": "SÂM NJŬN TRONG MA GÂP", "song_number": "7", "lyrics": "SÂM NJŬN TRONG MA GÂP\n\nKM 7, KMM 16\n\nVerse 1\nSâm njŭn trong ma gâp, Yê-su ơi, gâp mâu dơi gĭt trong May ôh.\nGâp hươi jêh, dăn May djôt ti gâp, tât tâm Ƀon Ueh May ta klơ.\n\nChorus\nSiăm an huêng gâp, siăm gâp tât kŏ hơm raơm ngăn.\nSiăm an huêng gâp, siăm gâp tât kŏ hơm raơm ngăn.\n\nVerse 2\nPơk an ma gâp tu dak rsang May, gâp kroh ko ji hir dŭt n'hâm.\nĂn gâp ƀă nhêt tu dak rêh May, tât ƀư bah nau ji hir gâp.\n\nChorus\nSiăm an huêng gâp, siăm gâp tât kŏ hơm raơm ngăn.\nSiăm an huêng gâp, siăm gâp tât kŏ hơm raơm ngăn.\n\nVerse 3\nĂp ntil khlay geh tă bah ti May, gâp mâu ŭch kuăl brah êng ôh.\nMay Nơm njêng gâp, May tâm chuai gâp, gâp gŭ rêh yor nau yỗ May.\n\nChorus\nSiăm an huêng gâp, siăm gâp tât kŏ hơm raơm ngăn.\nSiăm an huêng gâp, siăm gâp tât kŏ hơm raơm ngăn.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0008", "title": "Ơ BRAH NDU, MAY KƠL HÊN KĂL-E", "song_number": "8", "lyrics": "Ơ BRAH NDU, MAY KƠL HÊN KĂL-E\n\nTC 44, KM 133, KMM 79\n\nVerse 1\nƠ Brah Ndu, May kơl hên kăl e, May mra kơl hên ƀa-ƀơ.\nDôl geh âk nau uh ah tâm hên, hên dăn nau Brah May kơl.\n\nVerse 2\nTâm dâng n'hâm sưng May ta klơ trôk, phung chroh gŭ nde ƀa-ƀơ.\nKing ma mpang ti May, lah hên duh, jêh ri May mprơh phung rlăng.\n\nVerse 3\nKăl e May Nơm rhăk njêng ăp ntil, mpô mpa, yôk yang, neh ntu.\nMay Brah Ndu jêng êng May Nơm lor, ăt hôm tâm ban ƀa ƀơ.\n\nVerse 4\nMay kơp rbăn năm tâm ban du nar, tâm ban ma bar pe ndâm.\nPô ri lĕ rngôch May gĭt da-dê, bơh kăl e kŏ tât lôch.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0009", "title": "KÔRANH BRAH NDU ƠI", "song_number": "9", "lyrics": "KÔRANH BRAH NDU ƠI\n\nKMM 19\n\nVerse 1\nKôranh Brah Ndu ơi, lah gâp klân treng lĕ rngôch kan.\nMpang ti May ƀư khlay ngăn kŏ gâp hih rhâl.\nGâp saơ phung mănh, gâp tăng jêh nglaih dah tâm trôk.\nNeh ntu klơ trôk, jêng lĕ ndơ mpơl kan May.\n\nChorus\nHuêng gâp rŏng mprơ tâm rnê Brah Ndu Nơm Rklaih.\nMay jêng Nơm toyh Nơm Brah ngăn ngên.\nHuêng gâp rŏng mprơ tâm rnê Brah Ndu Nơm Rklaih.\nMay jêng Nơm Toyh, Nơm Brah ngăn ngên.\n\nVerse 2\nLah gâp klân rvê, Brah Ndu mâu nhhuach Kon Păng ôh.\nMprơh Yê-su khĭt, jêng jêr ma gâp gĭt rbăng.\nTa si tâm rkăng, Yê-su tuy lĕ nau tih gâp.\nPăng nkhŭt mham khlay gay rao kloh nau tih gâp.\n\nChorus\nHuêng gâp rŏng mprơ tâm rnê Brah Ndu Nơm Rklaih.\nMay jêng Nơm toyh Nơm Brah ngăn ngên.\nHuêng gâp rŏng mprơ tâm rnê Brah Ndu Nơm Rklaih.\nMay jêng Nơm Toyh, Nơm Brah ngăn ngên.\n\nVerse 3\nNar Krist lŏ văch, mra geh nau maak răm rhơn ngăn.\nDjôt leo gâp sĭt rlet ma Ƀon Ueh Păng klơ.\nGâp mra păn mbah, chŭn yơk tâm dâng Kôranh Nơm Rklaih.\nJêh ri gâp lah: Brah Ndu jêng Nơm Toyh ngăn.\n\nChorus\nHuêng gâp rŏng mprơ tâm rnê Brah Ndu Nơm Rklaih.\nMay jêng Nơm toyh Nơm Brah ngăn ngên.\nHuêng gâp rŏng mprơ tâm rnê Brah Ndu Nơm Rklaih.\nMay jêng Nơm Toyh, Nơm Brah ngăn ngên.\n", "category": "Brah Ndu", "language": "Bunong"}, {"local_id": "nau-mpro-0010", "title": "YÊ-SU JÊNG MĬT JIĂNG MA LĔ PHUNG TIH", "song_number": "10", "lyrics": "YÊ-SU JÊNG MĬT JIĂNG MA LĔ PHUNG TIH\n\nTC 21, KM 126, KMM 13\n\nVerse 1\nYê-su jêng mĭt jiăng lĕ phung tih, Yê-su Nơm rŏng nuih n'hâm gâp.\nBunuyh janh lơh oh nâu cha-lơi gâp, Ƀiă lah Yê-su kơl an gâp.\n\nChorus\nHa-lê-lu-ya, Nơm tâm rklaih gâp, Ha-lê-lu-ya, mĭt jiăng ngăn.\nPăng chuai gâp, jêh ri chiă uănh gâp ngăn.\nPăng gŭ ndrel ma gâp tât lôch.\n\nVerse 2\nLah rgănh, Yê-su ăn Brah Păng kơl, Gâp dơi gŭ tâm Păng ƀa-ƀơ.\nLah bu ndơm nklỡ ăn gâp cha-lôt, Ƀiă lah Yê-su rdâk an gâp.\n\nChorus\nHa-lê-lu-ya, Nơm tâm rklaih gâp, Ha-lê-lu-ya, mĭt jiăng ngăn.\nPăng chuai gâp, jêh ri chiă uănh gâp ngăn.\nPăng gŭ ndrel ma gâp tât lôch.\n\nVerse 3\nYê-su rthi lah gâp geh nau rngot, Lah nuih n'hâm geh nau klân rvê.\nDôl gâp nhhiăng Păng Nơm vay bonh gâp, Păng rthi gâp, jut lĕ dak măt.\n\nChorus\nHa-lê-lu-ya, Nơm tâm rklaih gâp, Ha-lê-lu-ya, mĭt jiăng ngăn.\nPăng chuai gâp, jêh ri chiă uănh gâp ngăn.\nPăng gŭ ndrel ma gâp tât lôch.\n\nVerse 4\nYê-su leo trong, Yê-su chiă uănh, Geh ntŭk jêr mâu lah bri gỡ.\nGâp mâu klach yor, Păng gŭ dăch gâp, Păng ăn gâp rêh tâm Ƀon Păng.\n\nChorus\nHa-lê-lu-ya, Nơm tâm rklaih gâp, Ha-lê-lu-ya, mĭt jiăng ngăn.\nPăng chuai gâp, jêh ri chiă uănh gâp ngăn.\nPăng gŭ ndrel ma gâp tât lôch.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0011", "title": "NKOCH BRI NAU KHLAY", "song_number": "11", "lyrics": "NKOCH BRI NAU KHLAY\n\nKM 14, KMM 67\n\nVerse 1\nNkoch bri nau khlay Kôranh Brah Yê-su, ntơm nar Păng jŭr ta neh ntu.\nNkoch nau Păng khĭt ta si tâm rkăng, gay ma phung ƀon lan gŭ iăt.\nNkoch bri nâm nau tông mpăr Brah Ndu, munh nchreng ma Păng dôl gŭ deh.\nLah ueh ma Brah Ndu Nơm klơ trôk, ăn nau đăp mpăn tâm neh ntu.\n\nChorus\nNkoch bri nau khlay Kôranh Brah Yê-su, gâp ŭch prăp lơi tâm nuih n'hâm.\nNkoch bri ma gâp lĕ nau rêh Păng, khlay lơn ma lĕ nau nkoch êng.\n\nVerse 2\nNkoch bri ma gâp Sa-tan ndơm Păng, dôl nar Păng gŭ ta ntŭk rdah.\nPuăn jât nar măng Sa-tan ndơm Păng, ƀiă lah Păng dơi đah lĕ rngôch.\nNkoch bri đơ năm Păng gŭ pah kan, nkoch bri Păng dơn lĕ nau rngot.\nMa lĕ nau bu mưch r-mot Păng, mâu geh ngih gŭ kơt o-ach.\n\nChorus\nNkoch bri nau khlay Kôranh Brah Yê-su, gâp ŭch prăp lơi tâm nuih n'hâm.\nNkoch bri ma gâp lĕ nau rêh Păng, khlay lơn ma lĕ nau nkoch êng.\n\nVerse 3\nNkoch nau Păng khĭt ta si tâm rkăng, bu pâng ta nĕ Păng ji ngăn.\nNkoch bri trôm môch ntŭk bu tâp Păng, nkoch bri đŏng nau Păng dâk rêh.\nNkoch nau Păng hao sĭt ta klơ trôk, gŭ tâm ntŭk khlay kêng Mbỡ Nơm.\nĂn he kah gĭt nau Păng rŏng he, nau Păng rŏng he toyh hâu ngăn.\n\nChorus\nNkoch bri nau khlay Kôranh Brah Yê-su, gâp ŭch prăp lơi tâm nuih n'hâm.\nNkoch bri ma gâp lĕ nau rêh Păng, khlay lơn ma lĕ nau nkoch êng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0012", "title": "KÔRANH BRAH JÊNG RMĂK GÂP", "song_number": "12", "lyrics": "KÔRANH BRAH JÊNG RMĂK GÂP\n\nKM 137, KMM 166\n\nVerse 1\nKôranh Brah jêng rmăk gâp, gâp rŏng Păng hâu ngăn.\nBu mâu dơi ntĭt ôh lĕ nau ueh Păng ăn.\nPăng dơn nau khĭt, hoch mham ta ntŭk Kăl-ver,\ngay gâp dơi nsing ma nau Păng rŏng ma gâp.\n\nChorus\nTĭng ndỗ Brah Yê-su ăp nar măng ăp mông.\nMâu geh nau mhĭk ôh lah Păng jêng Kôranh he.\nNau rngot mâu lah maak, kađôi moh ndơ tât.\nYê-su Nơm rmăk ueh gâp jêng Kôranh lĕ rngôch.\n\nVerse 2\nPăng njŭn leo gâp tâm ntŭk geh âk gỡ nse.\nPăng ăn gâp rlu dăch ntŭk geh dak rsang ueh.\nNau ueh, nau yỗ tĭng ndỗ ma gâp ƀa-ƀơ,\nn'hêl ngăn Păng mâu ăn he tăch yơt ndơ ôh.\n\nChorus\nTĭng ndỗ Brah Yê-su ăp nar măng ăp mông.\nMâu geh nau mhĭk ôh lah Păng jêng Kôranh he.\nNau rngot mâu lah maak, kađôi moh ndơ tât.\nYê-su Nơm rmăk ueh gâp jêng Kôranh lĕ rngôch.\n\nVerse 3\nLah gâp ŭch nkhah du, Păng lŏ nkân gâp gŭ.\nNtĭm gâp tĭng trong sŏng tâm Amoh săk Păng Nơm.\nTâm rlŭng geh n'hâm nau khĭt gâp mâu klach ôh,\nyor lah Kôranh Brah ăt Păng gŭ ndrel ma gâp.\n\nChorus\nTĭng ndỗ Brah Yê-su ăp nar măng ăp mông.\nMâu geh nau mhĭk ôh lah Păng jêng Kôranh he.\nNau rngot mâu lah maak, kađôi moh ndơ tât.\nYê-su Nơm rmăk ueh gâp jêng Kôranh lĕ rngôch.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0013", "title": "KƠP GÂP", "song_number": "13", "lyrics": "KƠP GÂP\n\nKM 170, KMM 185\n\nVerse 1\nLah May kơp rĭng lĕ bu-nuyh rŏng May, Kơp gâp, kơp gâp.\nLah May kơp mbu nâm vay nsing ma May, Kơp gâp, kơp gâp.\n\nChorus\nKơp gâp jêng tâm phung oh kon Brah Ndu klơ trôk.\nKơp gâp ăn jêng phung pah kan ma May ƀa-ƀơ.\nKơp gâp ăn jêng phung mât ton tâm rnê ma May, Kơp gâp kơp gâp.\n\nVerse 2\nLah May kơp mbu nâm geh May tâm rklaih, Kơp gâp, kơp gâp.\nLah May kơp mbu nâm mbe mbot Kôranh Brah, Kơp gâp, kơp gâp.\n\nChorus\nKơp gâp jêng tâm phung oh kon Brah Ndu klơ trôk.\nKơp gâp ăn jêng phung pah kan ma May ƀa-ƀơ.\nKơp gâp ăn jêng phung mât ton tâm rnê ma May, Kơp gâp kơp gâp.\n\nVerse 3\nLah May kơp mbu nâm geh nau sŏng srăng, Kơp gâp, kơp gâp.\nLah May kơp mbu nâm chuat tâm trong may, kơp gâp, kơp gâp.\n\nChorus\nKơp gâp jêng tâm phung oh kon Brah Ndu klơ trôk.\nKơp gâp ăn jêng phung pah kan ma May ƀa-ƀơ.\nKơp gâp ăn jêng phung mât ton tâm rnê ma May, Kơp gâp kơp gâp.\n\nVerse 4\nLah May kơp mbu nâm mâu dơi lơi May, Kơp gâp, kơp gâp.\nLah May kơp mbu nâm mra dơn đon Hađăch, kơp gâp, kơp gâp.\n\nChorus\nKơp gâp jêng tâm phung oh kon Brah Ndu klơ trôk.\nKơp gâp ăn jêng phung pah kan ma May ƀa-ƀơ.\nKơp gâp ăn jêng phung mât ton tâm rnê ma May, Kơp gâp kơp gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0014", "title": "MBƠH ĂN HUY NAU MHE MHAN", "song_number": "14", "lyrics": "MBƠH ĂN HUY NAU MHE MHAN\n\nKM 151, KMM 164\n\nVerse 1\nMbơh ăn huy nau mhe mhan ueh. Mbơh ăn huy.\nĂn ntoh lư nau nây ma ăp ƀon, lam n'gor bri.\nMbơh nau Yê-su yỗ ma lĕ bu-nuyh pô aơ:\n\"Yê-su yỗ ay may dơm dam.\"\n\nChorus\n\"Yê-su yỗ ay may, Yê-su yỗ ay may.\nKuăl lĕ rngôch băl mpôl ƀon lan ăn sĭt ma Păng.\nHơi phung tih, sĭt chroh hom.\nKlach lăn gao rlau mông. Yê-su yỗ ay may dơm dam.\"\n\nVerse 2\nMbơh ăn huy nau mhe mhan ueh. Mbơh ăn huy:\n\"Mham Brah Yê-su Krist rao jêh lĕ rngôch nau tih.\nMbah ntŭk ay may gŭ Păng kuăl ay may sĭt lĕ.\nYê-su yỗ ay may dơm dam.\"\n\nChorus\n\"Yê-su yỗ ay may, Yê-su yỗ ay may.\nKuăl lĕ rngôch băl mpôl ƀon lan ăn sĭt ma Păng.\nHơi phung tih, sĭt chroh hom.\nKlach lăn gao rlau mông. Yê-su yỗ ay may dơm dam.\"\n\nVerse 3\nMbơh ăn huy nau mhe mhan ueh. Mbơh ăn huy.\nDăch, ngai ntŭk, găp lĕ, mbơh nau mhe mhan ueh aơ.\nNtĭm trong ma phung tih dơi luh bơh nau rai yot.\n\"Yê-su yỗ ay may dơm dam.\"\n\nChorus\n\"Yê-su yỗ ay may, Yê-su yỗ ay may.\nKuăl lĕ rngôch băl mpôl ƀon lan ăn sĭt ma Păng.\nHơi phung tih, sĭt chroh hom.\nKlach lăn gao rlau mông. Yê-su yỗ ay may dơm dam.\"\n", "category": "Tâm rnê ma Yêsu", "language": "Bunong"}, {"local_id": "nau-mpro-0015", "title": "TÂM NUIH N'HÂM GÂP GEH NAU MPRƠ", "song_number": "15", "lyrics": "TÂM NUIH N'HÂM GÂP GEH NAU MPRƠ\n\nTC 217, KM 52, KMM 113\n\nVerse 1\nTâm nuih n'hâm gâp geh nau mprơ răm ngăn, Yê-su ngơi rah rơch pô aơ:\n\"Lơi klach ôh, gâp gŭ n'hanh ŭch kơl may.\nTâm nau jêr mâu lah nau nơih.\"\n\nChorus\nYê-su, Yê-su, Yê-su Amoh Păng khlay ngăn ngên.\nPăng jêng Nơm gâp rŏng hâu, Yor ri gâp mprơ maak ƀa-ƀơ.\n\nVerse 2\nKăl e nau rêh gâp rai tâm nau tih, nuih n'hâm gâp gŭ rngot hâu ngăn.\nɃiă lah Kôranh Brah Yê-su lĕ rgâl gâp.\nJêh ri aƀaơ gâp maak ƀa-ƀơ.\n\nChorus\nYê-su, Yê-su, Yê-su Amoh Păng khlay ngăn ngên.\nPăng jêng Nơm gâp rŏng hâu, Yor ri gâp mprơ maak ƀa-ƀơ.\n\nVerse 3\nGâp lĕ hơm jêh ma nau yỗ Păng ăn, gâp gŭ rlu tâm mpang ti Păng.\nKnŏng hôm e kâp uănh muh măt Păng dơm,\nPô ri gâp dơi mprơ nau aơ.\n\nChorus\nYê-su, Yê-su, Yê-su Amoh Păng khlay ngăn ngên.\nPăng jêng Nơm gâp rŏng hâu, Yor ri gâp mprơ maak ƀa-ƀơ.\n\nVerse 4\nTơ lah Păng njŭn leo tâm ntŭk, mhĭk blem, geh nau jêr rŏ trong gâp hăn.\nRŏ trong gâp hăn lah geh âk nau mhĭk.\nMâu rvê ôh rlau Yê-su n'hanh.\n\nChorus\nYê-su, Yê-su, Yê-su Amoh Păng khlay ngăn ngên.\nPăng jêng Nơm gâp rŏng hâu, Yor ri gâp mprơ maak ƀa-ƀơ.\n\nVerse 5\nHôm jŏ djễ Păng mra lŏ jŭr văch đŏng, tă bơh ntŭk tâm klơ trôk prêh.\nGâp mra saơ muh măt Păng rhơn răm ngăn.\nPăng ăn gŭ Ƀon Ueh n'ho ro.\n\nChorus\nYê-su, Yê-su, Yê-su Amoh Păng khlay ngăn ngên.\nPăng jêng Nơm gâp rŏng hâu, Yor ri gâp mprơ maak ƀa-ƀơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0016", "title": "DU HUÊ YÊ-SU DƠM GEH NAU UEH", "song_number": "16", "lyrics": "DU HUÊ YÊ-SU DƠM GEH NAU UEH\n\nTC 76, KM 17, KMM 45\n\nVerse 1\nDu huê Yê-su dơm geh nau ueh, ƀa-ƀơ n'ho ro mâu geh rgâl ôh.\nLĕ rngôch nau Brah, nau chrêk ma lơp. Geh tâm Yê-su jêng Nơm Rkaih gâp.\n\nChorus\nYor lah ma gâp Păng dơn nau khĭt, yor lah ma gâp bu djơh pâng Păng.\nYê-su Krist dơn lĕ rngôch nau tih, Păng khĭt ntrok gâp ta si tâm rkăng.\n\nVerse 2\nYê-su bu pâng ta si tâm rkăng, yor nau tih gâp bu pâng ndă Păng.\nNau ji kuet gâp Păng dơn lĕ đŏng. Nuih n'hâm Păng rngot yor ma gâp yơh.\n\nChorus\nYor lah ma gâp Păng dơn nau khĭt, yor lah ma gâp bu djơh pâng Păng.\nYê-su Krist dơn lĕ rngôch nau tih, Păng khĭt ntrok gâp ta si tâm rkăng.\n\nVerse 3\nTi Păng Nơm mâu tăch yơt nau Brah, lĕ nau Păng ton tât ngăn ƀa-ƀơ.\nĂp nar Păng saơ dak măt phung nhĭm. Tâm lĕ rngôch ntŭk jŭm bri văr neh.\n\nChorus\nYor lah ma gâp Păng dơn nau khĭt, yor lah ma gâp bu djơh pâng Păng.\nYê-su Krist dơn lĕ rngôch nau tih, Păng khĭt ntrok gâp ta si tâm rkăng.\n", "category": "Tâm rnê ma Yêsu", "language": "Bunong"}, {"local_id": "nau-mpro-0017", "title": "Ơ UEH HÂU NGĂN", "song_number": "17", "lyrics": "Ơ UEH HÂU NGĂN\n\nTC 79, KM 18, KMM 47\n\nVerse 1\nGâp hih rhâl ngăn gŭ ta năp Păng. Kôranh Yê-su, Ƀon Na-sa-ret.\ngâp mâu gĭt rbăng mâm ƀư Păng rŏng, ma gâp bu-nuyh tih ƀỡ ngăn.\n\nChorus\nƠ ueh hâu ngăn. Ơ khlay ngăn ngên, aơ nau gâp rŏng mprơ ƀa-ƀơ.\nƠ ueh hâu ngăn, Ơ khlay ngăn ngên, nau Kôranh Brah Yê-su rŏng ma gâp.\n\nVerse 2\nChon mon tâm đang Gêt-sê-ma-nê. Păng mbơh sơm kŏ luh mham ngăn.\nYor lah Păng rŏng kon nuyh hâu ngăn, dơn nau khĭt ta si tâm rkăng.\n\nChorus\nƠ ueh hâu ngăn. Ơ khlay ngăn ngên, aơ nau gâp rŏng mprơ ƀa-ƀơ.\nƠ ueh hâu ngăn, Ơ khlay ngăn ngên, nau Kôranh Brah Yê-su rŏng ma gâp.\n\nVerse 3\nPhung Brah ntuh bâr Brah Ndu yỗ Păng. Saơ Păng jŭr tă bơh ntŭk ang.\nPăng lơi ƀon toyh ngih mbâl Păng klơ, rêh tâm nau r-ngit yor gâp.\n\nChorus\nƠ ueh hâu ngăn. Ơ khlay ngăn ngên, aơ nau gâp rŏng mprơ ƀa-ƀơ.\nƠ ueh hâu ngăn, Ơ khlay ngăn ngên, nau Kôranh Brah Yê-su rŏng ma gâp.\n\nVerse 4\nDu nar kăn-ndỡ gâp mra hao sĭt. Saơ muh măt Yê-su ueh ngăn.\nGâp mprơ ƀa-ƀơ nau mprơ ueh aơ, \"yor lah Yê-su rŏng ma gâp.\"\n\nChorus\nƠ ueh hâu ngăn. Ơ khlay ngăn ngên, aơ nau gâp rŏng mprơ ƀa-ƀơ.\nƠ ueh hâu ngăn, Ơ khlay ngăn ngên, nau Kôranh Brah Yê-su rŏng ma gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0018", "title": "MÂU GEH ÔH MĬT JIĂNG TÂM BAN MA YÊ-SU", "song_number": "18", "lyrics": "MÂU GEH ÔH MĬT JIĂNG TÂM BAN MA YÊ-SU\n\nTC 80, KM 19, KMM 48\n\nVerse 1\nMâu geh ôh mĭt jiăng tâm ban ma Yê-su. Mâu geh ôh, mâu geh ro.\nMâu geh nơm dơi ƀư bah lĕ nau tih he. Mâu geh ôh, mâu geh ro.\n\nChorus\nYê-su saơ lĕ nau rngot tâm phung he. Păng mra chông leo he tât ta klơ.\nMâu geh ôh mĭt jiăng tâm ban ma Yê-su. Mâu geh ôh, mâu geh ro.\n\nVerse 2\nMâu geh ôh nơm kuăng lơn ma Brah Yê-su. Mâu geh ôh, mâu geh ro.\nMâu geh nơm rŏng he tâm ban nâm Yê-su. Mâu geh ôh, mâu geh ro.\n\nChorus\nYê-su saơ lĕ nau rngot tâm phung he. Păng mra chông leo he tât ta klơ.\nMâu geh ôh mĭt jiăng tâm ban ma Yê-su. Mâu geh ôh, mâu geh ro.\n\nVerse 3\nMâu geh ôh nơm ueh lơn ma Brah Yê-su. Mâu geh ôh, mâu geh ro.\nMâu geh nau Brah êng tâm ban nau Brah Păng. Mâu geh ôh, mâu geh ro.\n\nChorus\nYê-su saơ lĕ nau rngot tâm phung he. Păng mra chông leo he tât ta klơ.\nMâu geh ôh mĭt jiăng tâm ban ma Yê-su. Mâu geh ôh, mâu geh ro.\n", "category": "Tâm rnê ma Yêsu", "language": "Bunong"}, {"local_id": "nau-mpro-0019", "title": "KHLAY NGĂN", "song_number": "19", "lyrics": "KHLAY NGĂN\n\n\nVerse 1\nKhlay ngăn! Yê-su, Kon Brah Ndu jêng Kôranh he. Brah Yê-su, Yê-su Krist.\nKhay ngăn! Păng deh, lơi Ƀon Ueh, gŭ n'hanh he. Brah Yê-su, Yê-su Krist.\n\nChorus\nYê-su jêng Nơm tâm chuai huêng srĭng he, king he đah lĕ nau ƀỡ, nau tih.\nKhlay ngăn! Yê-su, Kon Brah Ndu, jêng Kôranh he. Brah Yê-su, Yê-su Krist.\n\nVerse 2\nYor Brah Huêng Ueh ăn păng geh nau Brah dơi. Brah Yê-su, Yê-su Krist.\nMâp brah bu ndjơh, Păng dơi mprơh, dơi nkhah lơi. Brah Yê-su, Yê-su Krist.\n\nChorus\nYê-su jêng Nơm tâm chuai huêng srĭng he, king he đah lĕ nau ƀỡ, nau tih.\nKhlay ngăn! Yê-su, Kon Brah Ndu, jêng Kôranh he. Brah Yê-su, Yê-su Krist.\n\nVerse 3\nLĕ ntil nau khlay Yê-su vay nti lah bu. Brah Yê-su, Yê-su Krist.\nLah saơ nơm ji, pah ma ti, ƀư bah bu. Brah Yê-su, Yê-su Krist.\n\nChorus\nYê-su jêng Nơm tâm chuai huêng srĭng he, king he đah lĕ nau ƀỡ, nau tih.\nKhlay ngăn! Yê-su, Kon Brah Ndu, jêng Kôranh he. Brah Yê-su, Yê-su Krist.\n\nVerse 4\nPhung mhĭk phung djơh ăt ŭch lơh, ŭch ntâp Păng. Brah Yê-su, Yê-su Krist.\nBu pâng jâng ti, nđom ta si, ƀư nkhĭt Păng. Brah Yê-su, Yê-su Krist.\n\nChorus\nYê-su jêng Nơm tâm chuai huêng srĭng he, king he đah lĕ nau ƀỡ, nau tih.\nKhlay ngăn! Yê-su, Kon Brah Ndu, jêng Kôranh he. Brah Yê-su, Yê-su Krist.\n\nVerse 5\nKhĭt ôm, Păng mpơl nau Păng kơl, Păng rŏng he. Brah Yê-su, Yê-su Krist.\nDôih dak he jru, ut ra-u, chuai đŏng he. Brah Yê-su, Yê-su Krist.\n\nChorus\nYê-su jêng Nơm tâm chuai huêng srĭng he, king he đah lĕ nau ƀỡ, nau tih.\nKhlay ngăn! Yê-su, Kon Brah Ndu, jêng Kôranh he. Brah Yê-su, Yê-su Krist.\n\nVerse 6\nPe nar Păng rlu, tât Brah Ndu ăn ndâk lơi. Brah Yê-su, Yê-su Krist.\nYê-su Păng dâk, mpông môch jâk Păng nklỡ lơi. Brah Yê-su, Yê-su Krist.\n\nChorus\nYê-su jêng Nơm tâm chuai huêng srĭng he, king he đah lĕ nau ƀỡ, nau tih.\nKhlay ngăn! Yê-su, Kon Brah Ndu, jêng Kôranh he. Brah Yê-su, Yê-su Krist.\n\nVerse 7\nMâu hôm blau khĭt, Păng hao sĭt bri Hađăch Păng. Brah Yê-su, Yê-su Krist.\nDu nar kăn-ndỡ, Păng mra plỡ jêng Hađăch ngăn. Brah Yê-su, Yê-su Krist.\n\nChorus\nYê-su jêng Nơm tâm chuai huêng srĭng he, king he đah lĕ nau ƀỡ, nau tih.\nKhlay ngăn! Yê-su, Kon Brah Ndu, jêng Kôranh he. Brah Yê-su, Yê-su Krist.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0020", "title": "YÊ-SU JÊNG NAU ANG TÂM NEH NTU", "song_number": "20", "lyrics": "YÊ-SU JÊNG NAU ANG TÂM NEH NTU\n\nTC 84, KM 20, KMM 52\n\nVerse 1\nLĕ rngôch bu-nuyh gŭ tâm nau tih jêng nau ngo. Yê-su jêng nau ang tâm neh ntu.\nNau chrêk rmah Păng nchrat ang nâm bu nar nklang bôk. Yê-su jêng nau ang tâm neh ntu.\n\nChorus\nVăch ma nau ang, Păng ŭch sol ang may, Păng nchrang gâp jêh, ang kloh rah vah ngăn.\nKăl e chieh măt, abaơ gâp saơ ang jêh, Yê-su jêng nau ang tâm neh ntu.\n\nVerse 2\nMbu gŭ tâm Yê-su, mâu hôm gŭ tâm ngo ôh. Yê-su jêng nau ang tâm neh ntu.\nHe hăn tâm nau ang ndrel ma Yê-su ƀa-ƀơ. Yê-su jêng nau ang tâm neh ntu.\n\nChorus\nVăch ma nau ang, Păng ŭch sol ang may, Păng nchrang gâp jêh, ang kloh rah vah ngăn.\nKăl e chieh măt, abaơ gâp saơ ang jêh, Yê-su jêng nau ang tâm neh ntu.\n\nVerse 3\nMay gŭ tâm nau ngo măt chieh yor ma nau tih. Yê-su jêng nau ang tâm neh ntu.\nMay pach ma dak mham Păng jêh ri may mra saơ. Yê-su jêng nau ang tâm neh ntu.\n\nChorus\nVăch ma nau ang, Păng ŭch sol ang may, Păng nchrang gâp jêh, ang kloh rah vah ngăn.\nKăl e chieh măt, abaơ gâp saơ ang jêh, Yê-su jêng nau ang tâm neh ntu.\n\nVerse 4\nTâm Ƀon Ueh Brah Ndu klơ, he mâu ŭch nar ôh. Yê-su jêng nau ang tâm neh ntu.\nPăng ŭch sol ang lĕ rngôch bunuyh gŭ tâm nau ngo. Yê-su jêng nau ang tâm neh ntu.\n\nChorus\nVăch ma nau ang, Păng ŭch sol ang may, Păng nchrang gâp jêh, ang kloh rah vah ngăn.\nKăl e chieh măt, abaơ gâp saơ ang jêh, Yê-su jêng nau ang tâm neh ntu.\n", "category": "Tâm rnê ma Yêsu", "language": "Bunong"}, {"local_id": "nau-mpro-0021", "title": "SĬN JÂT MA SĬN MLÂM BIĂP", "song_number": "21", "lyrics": "SĬN JÂT MA SĬN MLÂM BIĂP\n\nTC 87, KM 21, KMM 55\n\nVerse 1\nSĭn jât ma sĭn mlâm biăp tâm n'gar. Gŭ ueh, gŭ ơih r-mên.\nBiă lah du mlâm biăp roh tâm bri, mâu gĭt ntŭk păng gŭ ôh.\nNgai tâm yôk yang, bri brŏng krŏng mbâl, ngai đah Nơm Rmăk, đah ndrung Păng nơm,\nngai đah Nơm Rmăk, đah ndrung Păng Nơm.\n\nVerse 2\n\"Hơi Rmăk, hôm sĭn jât sĭn mlâm biăp. Du mlâm mâu saơ, pha lah.\"\nRmăk biăp plỡ lah: \"Yỗ nđach biăp rĭ, Păng nkhah du ngai đah Gâp.\nGĭt lah păng iăng tâm lok, tâm rting. A-ƀaơ gâp hăn joi păng ăn saơ,\nA-ƀaơ gâp hăn joi păng ăn saơ.\n\nVerse 3\nPăng hăn trong gỡ trong jêr, găp lĕ. Rmăk Ueh ri sâl hăn joi,\nHao yôk, poh leng, jŭr sop, lăp dak, Păng joi ndăng biăp Păng roh.\nPăng miăng chiau meng, păng srâng gŭ iăt, Kŏ saơ biăp roh, veng leo ăn sĭt,\nKŏ saơ biăp roh, veng leo ăn sĭt.\n\nVerse 4\nRmăk Ueh geh sôt tâm jâng, tâm ti, Yor srôih hăn joi biăp Păng.\nɃiă lah Păng răm, Păng mprơ rhơn biăp: \"maak ngăn, gâp saơ biăp roh\".\nTông mpăr Brah Ndu răm rhơn kơt Păng: \"Maak ngăn, Rmăk Ueh veng biăp Păng Nơm.\nMaak ngăn, Rmăk Ueh veng biăp Păng Nơm.\"\n\nVerse 5\nYê-su lah: \"Gâp jêng Rmăk Biăp Ueh. Mbu nâm văch ran ma gâp.\nGâp mâu geh mâp mprơh păng du ôh, Gâp khĭt ta si tâm rkăng.\nGay ăn nau rêh ma mbu nâm chroh, jêh ri ay may mra rêh mro mrăng,\nJêh ri ay may mra rêh mro mrăng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0022", "title": "GÂP NHHƠR JÊH NAU RÊH GÂP MA MAY", "song_number": "22", "lyrics": "GÂP NHHƠR JÊH NAU RÊH GÂP MA MAY\n\nTC 92, KM 22, KMM 59\n\nVerse 1\n\"Gâp hŏ nhhơr jêh nau rêh nâm nđễ nau Yê-su lah.\n\"Gâp nkhŭt jêh mham gay rklaih, ŭch ăn may jêng kon me.\nGâp nhhơr, gâp nhhơr nau rêh ma may. Moh ndơ may nhhơr Gâp đŏng?\n\nVerse 2\nNgih Mbỡ Gâp klơ nchrat ang, Sưng Hađăch gâp chrêk rmah ngăn.\nGâp lơi ngih nây, yor lah tâm rklaih bunuyh tih neh ntu.\nGâp lơi, gâp lơi lĕ yor ma may. Moh ndơ may lơi Gâp đŏng?\n\nVerse 3\nGâp dơn jêh nau khĭt ndrêh, yor may mâu dơi rblang ôh.\nNau Gâp khĭt nĕ gay ŭch rklaih may klach tŭp n'gar ŭnh.\nGâp dơn, gâp dơn jêh yor ma may. Moh may dơn yor Gâp đŏng?\"\nA-MEN.\n", "category": "Yêsu khĭt", "language": "Bunong"}, {"local_id": "nau-mpro-0023", "title": "UĂNH HOM, KÔRANH BRAH", "song_number": "23", "lyrics": "UĂNH HOM, KÔRANH BRAH\n\nTC 93, KM 23, KMM 57\n\nVerse 1\nUănh hom, Kôranh Brah nkhŭt jêh mham Păng, Păng khĭt ta si tâm rkăng.\nTâm rnôk kăl e, bu pâng Kôranh he. Păng khĭt gay rklaih kon bunuyh.\n\nVerse 2\nHe mâu dơi rblang, he mâu blau nkoch, nau nđêh nji Păng sŏk dơn.\nKnŏng he dơi gĭt Yê-su ndă khĭt. Yor nau tih he mâp ƀư.\n\nVerse 3\nPăng khĭt gay kuaih lơi nau tih he, gay ăn he jêng kloh ueh.\nNau tih, Păng rao, Păng njŭn he hao. Ta Ƀon Ueh nar kăn-ndỡ.\n\nVerse 4\nMâu hôm geh nơm êng jêng kloh ueh, gay ma tâm tang phung he.\nKnŏng Păng du huê dơi trok da-dê. Lĕ dôih Brah Ndu ma he.\n\nVerse 5\nYê-su rŏng jêh he hâu ngăn ngên, ăn he plỡ rŏng ma Păng.\nHe jao nau rêh ma Yê-su Krist. Pah kan ma Păng ƀa-ƀơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0024", "title": "TƠ LAH GÂP UĂNH TA SI TÂM RKĂNG", "song_number": "24", "lyrics": "TƠ LAH GÂP UĂNH TA SI TÂM RKĂNG\n\nTC 95, KM 24, KMM 60\n\nVerse 1\nTơ lah gâp uănh ta si tâm rkăng, Ntŭk nây Yê-su khĭt gay chuai gâp.\nGâp mâu hôm rvê ma ndơ neh ntu. Gâp nhhơr lơi lĕ ta jâng Kôranh Brah.\n\nVerse 2\nUănh ntơm bơh bôk Păng tât ta jâng, Păng nkhŭt mham khlay yor Păng rŏng gâp.\nNau rŏng Păng nây tâm pot nau rngot. Păng ŭch tâm rnglăp gâp đah Brah Ndu.\n\nVerse 3\nGâp mâu dơi rblang nau khlay Păng rŏng Mâu dơi ban joi nau Păng yỗ nđach.\nGâp ŭch nhhơr lĕ nuih n'hâm săk jăn. Ma Kôranh Yê-su kŏ tât nar lôch.\n\nVerse 4\nGâp rŏng Păng khĭt ta si tâm rkăng. Păng dơi ăn gâp rêh kơt Păng Nơm.\nGâp mâu dơi chuêl Păng ji hâu ngăn. Gâp nhhơr nuih n'hâm, săk jăn ma Păng.\nA-Men.\n", "category": "Yêsu khĭt", "language": "Bunong"}, {"local_id": "nau-mpro-0025", "title": "GÂP CHROH N'HÊL NGĂN", "song_number": "25", "lyrics": "GÂP CHROH N'HÊL NGĂN\n\nTC 102, KM 25, KMM 66\n\nVerse 1\nMâm ƀư Yê-su nkhŭt mham khlay Păng? Mâm ƀư Păng khĭt rgâl gâp?\nKôranh Brah toyh ngăn nhhơr săk jăn Păng, tâm chuai gâp bơh nau tih.\n\nChorus\nGâp chroh n'hêl ngăn, gâp chroh n'hêl ngăn, Yê-su khĭt tâm rgâl gâp.\nMa mham khlay Păng, Yê-su rklaih gâp, ăn gâp dơi iăng gŭ đăp mpăn ngăn.\n\nVerse 2\nGâp mâu gĭt rbăng mâm ƀư Păng rŏng. Gâp mâu dơi kơp nau yỗ.\nYor nau tih gâp, Mbỡ dong ndă Păng, Mbỡ mâu hôm rmal gâp ôh.\n\nChorus\nGâp chroh n'hêl ngăn, gâp chroh n'hêl ngăn, Yê-su khĭt tâm rgâl gâp.\nMa mham khlay Păng, Yê-su rklaih gâp, ăn gâp dơi iăng gŭ đăp mpăn ngăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0026", "title": "JRU TÂM MÔCH, PĂNG GŬ KHĬT", "song_number": "26", "lyrics": "JRU TÂM MÔCH, PĂNG GŬ KHĬT\n\nTC 103, KM 26, KMM 68\n\nVerse 1\nJru tâm môch Păng gŭ khĭt, Yê-su, Nơm Rklaih gâp.\nTă phung mhĭk nkhĭt Păng dơn, Yê-su, Kôranh gâp.\n\nChorus\nLuh tă ntu môch Păng dâk rêh, Păng dâk tâm mpơl nau Brah nau dơi.\nPăng tâm lơh đah Brah Sa-tan, dơi Yê-su ngăn.\nPăng gŭ rêh ƀa-ƀơ a-ƀaơ jêng Kôranh Brah ngăn.\nPăng dâk rêh, Păng dâk rêh, Ha-lê-lu-ya, Yê-su rêh.\n\nVerse 2\nPăng mâu gŭ khĭt jŏ ôh, Yê-su, Nơm Rklaih gâp.\nPăng hŏ ƀư Brah toyh jêh, Yê-su, Kôranh gâp.\n\nChorus\nLuh tă ntu môch Păng dâk rêh, Păng dâk tâm mpơl nau Brah nau dơi.\nPăng tâm lơh đah Brah Sa-tan, dơi Yê-su ngăn.\nPăng gŭ rêh ƀa-ƀơ a-ƀaơ jêng Kôranh Brah ngăn.\nPăng dâk rêh, Păng dâk rêh, Ha-lê-lu-ya, Yê-su rêh.\n\nVerse 3\nPăng ƀư rai lĕ nau khĭt, Yê-su Nơm Rklaih gâp.\nLôch pe nar Păng lŏ rêh, Yê-su, Kôranh gâp.\n\nChorus\nLuh tă ntu môch Păng dâk rêh, Păng dâk tâm mpơl nau Brah nau dơi.\nPăng tâm lơh đah Brah Sa-tan, dơi Yê-su ngăn.\nPăng gŭ rêh ƀa-ƀơ a-ƀaơ jêng Kôranh Brah ngăn.\nPăng dâk rêh, Păng dâk rêh, Ha-lê-lu-ya, Yê-su rêh.\nA-MEN.\n", "category": "Yêsu dâk rêh", "language": "Bunong"}, {"local_id": "nau-mpro-0027", "title": "KRIST LUH TĂ MA MÔCH NAR AƠ", "song_number": "27", "lyrics": "KRIST LUH TĂ MA MÔCH NAR AƠ\n\nTC 104, KM 27, KMM 69\n\nVerse 1\nKrist luh tă ma môch nar aơ. Ha-lê-lu-ya.\nKôranh toyh he gŭ rêh a-ƀaơ. Ha-lê-lu-ya.\nMpât mprơ hâu ma nau hâk răm. Ha-lê-lu-ya.\nLĕ bu bŭnh bu ranh druh ndăm. Ha-lê-lu-ya.\n\nVerse 2\nKan Yê-su dơi jêng da-dê. Ha-lê-lu-ya.\nNau tâm lơh, dơi Păng du huê. Ha-lê-lu-ya.\nPăng tâm rklaih he bơh nau tih. Ha-lê-lu-ya.\nTâm rnê Brah Yê-su Krist. Ha-lê-lu-ya.\n\nVerse 3\nPăng ƀư Brah ma săk Păng Nơm. Ha-lê-lu-ya.\nPăng gŭ khĭt tâm pe nar dơm. Ha-lê-lu-ya.\nMâu dơi bu nkân Păng tâm môch. Ha-lê-lu-ya.\nYê-su dâk, Păng dơi lĕ rngôch. Ha-lê-lu-ya.\n\nVerse 4\nHe mâu hôm dơi krit dơi klach. Ha-lê-lu-ya.\nYê-su bêng ma nau yỗ nđach. Ha-lê-lu-ya.\nLah he khĭt Păng lŏ ndâk rêh. Ha-lê-lu-ya.\nChông he hao ta ntŭk dŭt prêh. Ha-lê-lu-ya.\n", "category": "Yêsu dâk rêh", "language": "Bunong"}, {"local_id": "nau-mpro-0028", "title": "PĂNG RÊH", "song_number": "28", "lyrics": "PĂNG RÊH\n\nTC 111, KM 28, KMM 72\n\nVerse 1\nKôranh Yê-su lŏ dâk rêh đŏng. Păng gŭ ndrel he nar aơ.\nMâu hôm gâp klân r-vê ôh, mâu hôm gâp klach ma bu.\nMpang ti Păng bêng ma nau yỗ, Bâr Păng Ngơi n'hao nuih gâp.\nTâm mông gâp joi bu kơl gâp, Păng gŭ dăch ro.\n\nChorus\nPăng rêh, Păng rêh, Yê-su gŭ rêh nar aơ.\nPăng hăn ndrel gâp, Păng Ngơi đah gâp, dôl he tĭng ndỗ trong Păng.\nPăng rêh, Păng rêh, ŭch tâm r-klaih gâp. ngăn.\nYor aơ gâp gĭt nau nây jêng ngăn, Păng rêh tâm nuih n'hâm gâp.\n", "category": "Yêsu dâk rêh", "language": "Bunong"}, {"local_id": "nau-mpro-0029", "title": "KÔRANH GƠNH PLỠ", "song_number": "29", "lyrics": "KÔRANH GƠNH PLỠ\n\nTC 121\n\nVerse 1\nKôranh gơnh plỡ, phung chroh gŭ rngeh hỡ. Ndjôt ŭnh kađen, lơi chuêl dak ŭnh ôh.\nNkra ăn nŭm, ăn năn dơi ran Păng, Kâp gâp ngăn, iăt nau mhe mhan Păng.\n\nChorus\nKôranh gơnh plỡ Yê-su gơnh plỡ.\nYê-su plỡ, jêng Kôranh lam neh ntu, bêng nau chrêk r-mah tă Brah Ndu,\nKôranh gơnh plỡ, Yê-su gơnh plỡ.\n\nVerse 2\nRĭ jêng nau Păng ton na-nễ ngăn. Ê-lor Păng hao sĭt Ƀon Ueh Păng.\nN'hêl na-nễ ô klak Păng plỡ tay, Trŭnh bơh trôk du nar kăn-ndỡ taơ.\n\nChorus\nKôranh gơnh plỡ Yê-su gơnh plỡ.\nYê-su plỡ, jêng Kôranh lam neh ntu, bêng nau chrêk r-mah tă Brah Ndu,\nKôranh gơnh plỡ, Yê-su gơnh plỡ.\n\nVerse 3\nHe mra tăng bu uh nŭng Brah Ndu. Saơ Păng trŭnh gay phat dôih neh ntu.\nPhung tâm môch mra luh gay ran Păng, Lĕ phung chroh r-ƀŭn gay rhơn Păng.\n\nChorus\nKôranh gơnh plỡ Yê-su gơnh plỡ.\nYê-su plỡ, jêng Kôranh lam neh ntu, bêng nau chrêk r-mah tă Brah Ndu,\nKôranh gơnh plỡ, Yê-su gơnh plỡ.\n", "category": "Yêsu plỡ văch", "language": "Bunong"}, {"local_id": "nau-mpro-0030", "title": "HĂN MBƠH NAU MHE MHAN UEH", "song_number": "30", "lyrics": "HĂN MBƠH NAU MHE MHAN UEH\n\nTC 135, KM 30, KMM 76\n\nVerse 1\nHăn mbơh nau mhe mhan ueh, mbơh ma lĕ rngôch ƀon lan.\nTâm ntŭk geh âk bunuyh gŭ, rngot klâng yor tĭng Brah Mhĭk.\nƠ phung tâm kơl Yê-su, hăn gơnh oi mbơh nau aơ:\nGeh Brah Huêng Ueh tât jêh.\n\nChorus\nGeh Brah Huêng Ueh tât jêh. Geh Brah Huêng Ueh tât jêh,\nNâm bu Yê-su hŏ ton Ma phung oh mon rĭ dơh.\nHăn mbơh nau mhe mhan ueh, mbơh ma lĕ rngôch ƀon lan,\nGeh Brah Huêng Ueh tât jêh.\n\nVerse 2\nKăl-e ngo klĕng dŭt n'hâm, a-ƀaơ nau ang mpơl jêh.\nMprơh lĕ rngôch nau rngot klâng, ƀư rai lĕ nau tih Mhĭk.\nNar aơ geh nau nchrat ang, tâm ban nâm bu nchrêk mah.\nGeh Brah Huêng Ueh tât jêh.\n\nChorus\nGeh Brah Huêng Ueh tât jêh. Geh Brah Huêng Ueh tât jêh,\nNâm bu Yê-su hŏ ton Ma phung oh mon rĭ dơh.\nHăn mbơh nau mhe mhan ueh, mbơh ma lĕ rngôch ƀon lan,\nGeh Brah Huêng Ueh tât jêh.\n\nVerse 3\nYê-su, Nơm Tâm Chuai he, tâm chuai he dơm dam ngăn.\nLĕ rngôch phung bunuyh tih mhĭk, ăn he chroh gơnh ma Păng,\nÔ klak klach he lăn khĭt, mra dơn nau tâm rmal ngăn.\nGeh Brah Huêng Ueh tât jêh.\n\nChorus\nGeh Brah Huêng Ueh tât jêh. Geh Brah Huêng Ueh tât jêh,\nNâm bu Yê-su hŏ ton Ma phung oh mon rĭ dơh.\nHăn mbơh nau mhe mhan ueh, mbơh ma lĕ rngôch ƀon lan,\nGeh Brah Huêng Ueh tât jêh.\n", "category": "Brah Huêng Ueh", "language": "Bunong"}, {"local_id": "nau-mpro-0031", "title": "Ơ BRAH HUÊNG UEH BRAH NDU ƠI", "song_number": "31", "lyrics": "Ơ BRAH HUÊNG UEH BRAH NDU ƠI\n\nTC 139, KM 31, KMM 78\n\nVerse 1\nƠ Brah Huêng Ueh, Brah Ndu ơi. Lăp tâm nuih n'hâm hên a-ƀaơ.\nJŭr văch nâm bu plŭk tâm mpơl, tâm nuih n'hâm hên dôl mbơh sơm.\n\nVerse 2\nƠ Brah Huêng Ueh, lăp tâm hên. Dăn May ƀư rdỡ nuih n'hâm hên.\nɃư nkhĭt lĕ nau tih mhĭk gâp, gay nuih n'hâm huêng gâp kloh ueh.\n\nVerse 3\nƠ Brah Huêng Ueh, gâp khĭt jêh. Dăn May lŏ ăn gâp rêh đŏng.\nMay ăn ma gâp nau Brah ktang, ƀư rai lĕ rse rvăk brah mhĭk.\n\nVerse 4\nƠ Brah Huêng Ueh, gâp kâp May. Gay mbêng ler tâm nuih n'hâm gâp.\nNkŭm hên nau gĭt mleh ueh maak, ăn hên dơi geh nau đăp mpăn.\n\nVerse 5\nƠ Brah Huêng Ueh, gŭ tâm hên. Dăn May kơl ngăn hên ăp nar.\nNting năr Brah May mra king hên, kŏ tât nar hên lăp tâm trôk.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0032", "title": "MBÊNG HOM GÂP", "song_number": "32", "lyrics": "MBÊNG HOM GÂP\n\nTC 136, KM 128, KMM 77\n\nVerse 1\nMbêng hom gâp, Brah Huêng Ueh ơi, lăp hom tâm nuih n'hâm gâp a-ƀaơ.\nLĕ nau Brah May nglăp tâm huêng gâp, văch hom, ăn mbêng gâp a-ƀaơ.\n\nChorus\nMbêng hom gâp, mbêng hom gâp, Yê-su ơi, văch mbêng hom gâp.\nLĕ nau Brah May nglăp tâm huêng gâp, văch hom, ăn mbêng gâp a-ƀaơ.\n\nVerse 2\nBrah Huêng Ueh, May ăn mbêng gâp, yor gâp mâu dơi gĭt mâm ƀư rblang.\nĂt gâp ŭch May, ăt gâp kâp May, văch hom, ăn mbêng gâp a-ƀaơ.\n\nChorus\nMbêng hom gâp, mbêng hom gâp, Yê-su ơi, văch mbêng hom gâp.\nLĕ nau Brah May nglăp tâm huêng gâp, văch hom, ăn mbêng gâp a-ƀaơ.\n\nVerse 3\nGâp r-dja, huêng gâp rdja đŏng, dăn păn ta năp jâng ueh May dơm.\nGâp vơh vơl May, ơ Brah Ndu ơi, văch hom, ăn mbêng gâp a-ƀaơ.\n\nChorus\nMbêng hom gâp, mbêng hom gâp, Yê-su ơi, văch mbêng hom gâp.\nLĕ nau Brah May nglăp tâm huêng gâp, văch hom, ăn mbêng gâp a-ƀaơ.\n\nVerse 4\nMbêng hom gâp, mprơh lơi nau tih, rao kloh nau tih tâm nuih n'hâm aơ.\nMay lăp gŭ tâm gâp ƀa-ƀơ hỡ, n'ho ma ăn mbêng gâp a-ƀaơ.\n\nChorus\nMbêng hom gâp, mbêng hom gâp, Yê-su ơi, văch mbêng hom gâp.\nLĕ nau Brah May nglăp tâm huêng gâp, văch hom, ăn mbêng gâp a-ƀaơ.\nA-MEN.\n", "category": "Brah Huêng Ueh", "language": "Bunong"}, {"local_id": "nau-mpro-0033", "title": "BRAH HUÊNG UEH NƠM VAY UĂNH", "song_number": "33", "lyrics": "BRAH HUÊNG UEH NƠM VAY UĂNH\n\nTC 138\n\nVerse 1\nBrah Huêng Ueh vay uănh, vay nhhol, sol nau ang tâm nuih n'hâm gâp.\nMprơh lĕ ntil nau ƀỡ nau ngo, n'ho ma ăn gâp saơ kloh rah vah.\n\nVerse 2\nBrah Huêng Ueh, dăn May tâm mpơl, kơl gâp gĭt năl Brah Yê-su.\nNjŭn gâp iăt nau Brah Ndu Ngơi, dơi tĭng ndỗ lĕ nau Kôranh Brah ntăm.\n\nVerse 3\nBrah Huêng Ueh, nơm bêng nau yỗ, đỗ lĕ nau tâm lah tâm djrel.\nKơl phung chroh gŭ ngau đêh rmên, bên tâm rnglăp, bên tâm kơl mbơh sơm.\n\nVerse 4\nBrah Huêng Ueh, dăn nau Brah May, rlay nuih n'hâm gâp ăn dăng, ktang.\nĂn gâp rêh nau dơi, nau jêng, bêng nau Brah, bêng nau kloh, nau ang.\nA-MEN.\n", "category": "Brah Huêng Ueh", "language": "Bunong"}, {"local_id": "nau-mpro-0034", "title": "VĂCH TA YÊ-SU", "song_number": "34", "lyrics": "VĂCH TA YÊ-SU\n\nTC 157, KM 33, KMM 83\n\nVerse 1\nVăch ta Yê-su, hăn ta Yê-su, ran ta Yê-su a-ƀaơ.\nA-ƀaơ ăn may văch ta Yê-su, văch ta Yê-su Krist a-ƀaơ.\n\nVerse 2\nYê-su kuăl may, Yê-su jă may, Yê-su rŏng may a-ƀaơ.\nA-ƀaơ ăn may văch ta Yê-su, văch ta Yê-su Krist a-ƀaơ.\n\nVerse 3\nĂn may iăt Păng, ăn may jăt Păng, ăn may tĭng Păng a-ƀaơ.\nA-ƀaơ ăn may văch ta Yê-su, văch ta Yê-su Krist a-ƀaơ.\n\nVerse 4\nPăng tâm chuai may, tâm r-klaih may, Păng yỗ nđach may a-ƀaơ.\nA-ƀaơ ăn may văch ta Yê-su, văch ta Yê-su Krist a-ƀaơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0035", "title": "YÊ-SU ROM LĔ RNGÔCH BUNUYH TIH", "song_number": "35", "lyrics": "YÊ-SU ROM LĔ RNGÔCH BUNUYH TIH\n\nTC 161, KM 35, KMM 85\n\nVerse 1\nYê-su rom lĕ rngôch bunuyh tih, kkoch bri nau ueh aơ ƀa-ƀơ.\nMbu nâm lơi tĭng trong Sa-tan, jêh ri tĭng ndỗ trong Yê-su.\n\nChorus\nMprơ nkhoch bri ƀa-ƀơ ƀa-ƀơ Yê-su rom lĕ rngôch bunuyh tih.\nPăng rao kloh ma mham khlay Păng. Yê-su rom lĕ rngôch bunuyh tih.\n\nVerse 2\nVăch hom, Yê-su ăn may rlu, chroh ma Păng, nau Păng Ngơi ngăn.\nPăng rŏng may ŭch ƀư kloh may, Yê-su rom lĕ rngôch bunuyh tih.\n\nChorus\nMprơ nkhoch bri ƀa-ƀơ ƀa-ƀơ Yê-su rom lĕ rngôch bunuyh tih.\nPăng rao kloh ma mham khlay Păng. Yê-su rom lĕ rngôch bunuyh tih.\n\nVerse 3\nMâu hôm geh nau tâm rmal ôh, Brah Ndu kơp may jêng kon Păng.\nPăng dơn nau Yê-su ƀư brah, mâu ŭch ôh joi đŏng brah êng.\n\nChorus\nMprơ nkhoch bri ƀa-ƀơ ƀa-ƀơ Yê-su rom lĕ rngôch bunuyh tih.\nPăng rao kloh ma mham khlay Păng. Yê-su rom lĕ rngôch bunuyh tih.\n\nVerse 4\nYê-su rom lĕ rngôch bunuyh tih, Păng rom gâp, mâu mprơh gâp ôh.\nPăng rao kloh nuih n'hâm gâp đŏng, ăn gâp dơi lăp tâm Ƀon Păng.\n\nChorus\nMprơ nkhoch bri ƀa-ƀơ ƀa-ƀơ Yê-su rom lĕ rngôch bunuyh tih.\nPăng rao kloh ma mham khlay Păng. Yê-su rom lĕ rngôch bunuyh tih.\nA-MEN.\n", "category": "Jă bu lăp chroh", "language": "Bunong"}, {"local_id": "nau-mpro-0036", "title": "CHROH MA YÊ-SU", "song_number": "36", "lyrics": "CHROH MA YÊ-SU\n\nTC 162, KM 36, KMM 86\n\nVerse 1\nVăch lĕ rngôch mbu nâm geh nau tih, Yê-su ŭch yỗ ay may.\nChroh hom ma Păng, chroh hom ma Păng, ay may mra klaih ngăn ngên.\n\nChorus\nChroh ma Yê-su. chroh ma Yê-su. Chroh ngăn hom aƀaơ ro.\nPăng ŭch yỗ an, Păng ŭch yỗ an, yỗ an ngăn aƀaơ ro.\n\nVerse 2\nYê-su nkhŭt jêh mham khlay Păng Nơm, gay ăn he ueh săk jăn.\nMbơh hom nau tih ay may ma Păng, jêh ri Păng rao kloh ngăn.\n\nChorus\nChroh ma Yê-su. chroh ma Yê-su. Chroh ngăn hom aƀaơ ro.\nPăng ŭch yỗ an, Păng ŭch yỗ an, yỗ an ngăn aƀaơ ro.\n\nVerse 3\nYê-su jêng trong he njŏ leo klơ, lah tât he mra gŭ rlu.\nCha-lơi gơnh oi nau tih ay may, lơi hôm tông Brah Mhĭk ôh.\n\nChorus\nChroh ma Yê-su. chroh ma Yê-su. Chroh ngăn hom aƀaơ ro.\nPăng ŭch yỗ an, Păng ŭch yỗ an, yỗ an ngăn aƀaơ ro.\n\nVerse 4\nVăch n'hanh hên gơnh tĭng ndỗ Yê-su, he mra hăn hâk răm ngăn.\nLah he tât klơ, Yê-su ăn lăp, gŭ ndrel ma Păng ƀa-ƀơ.\n\nChorus\nChroh ma Yê-su. chroh ma Yê-su. Chroh ngăn hom aƀaơ ro.\nPăng ŭch yỗ an, Păng ŭch yỗ an, yỗ an ngăn aƀaơ ro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0037", "title": "VĂCH HOM AY MAY, TĬNG NDỖ", "song_number": "37", "lyrics": "VĂCH HOM AY MAY, TĬNG NDỖ\n\nTC 165, KM 37, KMM 87\n\nVerse 1\nVăch hom ay may, tĭng ndỗ Kôranh Brah he, tâm ndrom sam-ƀŭt Păng hŏ tâm mpơl jêh.\nAƀaơ Păng gŭ jêh tâm nklang phung he aơ, Păng kuăl ay may sĭt hom.\n\nChorus\nMaak yơh, maak yơh phung tâm kơl gŭ rƀŭn. Nuih n'hâm rao kloh jêh ma mham Yê-su.\nHe gŭ r-ƀŭn gay tâm rnê Yê-su. Geh Păng he dơi gŭ maak.\n\nVerse 2\nMbu moh tăng nau aơ, văch hom ay may, ndrel ma lĕ rngôch phung chroh ta neh ntu.\nChroh ma Yê-su, mprơ tâm rnê ma Păng. Lơi ƀư vât vâng gao mông.\n\nChorus\nMaak yơh, maak yơh phung tâm kơl gŭ rƀŭn. Nuih n'hâm rao kloh jêh ma mham Yê-su.\nHe gŭ r-ƀŭn gay tâm rnê Yê-su. Geh Păng he dơi gŭ maak.\n\nVerse 3\nKôranh Brah Yê-su rklaih lĕ nau tih he, Păng rklaih dơm dam mâu geh nkhôm nkra ôh.\nNau yỗ nđach toyh Păng he mâu dơi ntĭt. Ăn ay may chroh aƀaơ ro.\n\nChorus\nMaak yơh, maak yơh phung tâm kơl gŭ rƀŭn. Nuih n'hâm rao kloh jêh ma mham Yê-su.\nHe gŭ r-ƀŭn gay tâm rnê Yê-su. Geh Păng he dơi gŭ maak.\n", "category": "Jă bu lăp chroh", "language": "Bunong"}, {"local_id": "nau-mpro-0038", "title": "VĂCH HOM, Ơ BUNUYH TIH", "song_number": "38", "lyrics": "VĂCH HOM, Ơ BUNUYH TIH\n\nTC 166, KM 38, KMM 88\n\nVerse 1\nYê-su kuăl may ma nau rŏng, văch hom, ơ bunuyh tih.\nDôl hên kuăl mbơh sơm kơl may, văch hom ơ bunuyh tih.\nA-ƀaơ may dơi gĭt năl Păng, văch hom, ơ bunuyh tih.\nAƀaơ ri may dơi chroh ma Păng, văch hom, ơ bunuyh tih.\n\nVerse 2\nNau tih may anh jêng jâk ngăn, văch hom, ơ bunuyh tih.\nYê-su ŭch chông an, kơl may, văch hom ơ bunuyh tih.\nYê-su mâu mâp ngơi mbruh ôh, văch hom, ơ bunuyh tih.\nYê-su na-nễ mra rom may, văch hom, ơ bunuyh tih.\n\nVerse 3\nMâm ƀư may ƀlao iăt bâr Păng? văch hom, ơ bunuyh tih.\nMâm ƀư may mâu ŭch tông Păng? văch hom ơ bunuyh tih.\nPăng rŏng may ma nau yỗ ngăn, văch hom, ơ bunuyh tih.\nMâm may mâu rŏng ma Păng lĕ, văch hom, ơ bunuyh tih.\n\nVerse 4\nIăt hom Păng rŏng vơl kuăl may, văch hom, ơ bunuyh tih.\nChroh ma Yê-su may mra klaih, văch hom ơ bunuyh tih.\nDôl Yê-su kuăl may sĭt chroh, văch hom, ơ bunuyh tih.\nDôl hên jă may sĭt ma Păng, văch hom, ơ bunuyh tih.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0039", "title": "GÂP SĬT YƠH", "song_number": "39", "lyrics": "GÂP SĬT YƠH\n\nTC 168, KM 39, KMM 90\n\nVerse 1\nGâp nkhah du ngai đah ngih Brah Ndu, aƀaơ gâp lŏ plỡ sĭt.\nJŏ năm jêh gâp jêng dĭk Brah Mhĭk, aƀaơ gâp ŭch sĭt yơh.\n\nChorus\nGâp sĭt yơh, gâp sĭt yơh. Mâu hôm ŭch nkhah du.\nƠ Brah Ndu ơi, dăn May rom gâp, aƀaơ gâp ŭch sĭt yơh.\n\nVerse 2\nGâp rgănh hâu ngăn, yor tĭng Brah Mhĭk, aƀaơ gâp lŏ plỡ sĭt.\nGâp sĭt ma May gay mbơh nau tih, aƀaơ gâp ŭch sĭt yơh.\n\nChorus\nGâp sĭt yơh, gâp sĭt yơh. Mâu hôm ŭch nkhah du.\nƠ Brah Ndu ơi, dăn May rom gâp, aƀaơ gâp ŭch sĭt yơh.\n\nVerse 3\nNuih n'hâm gâp huăr, huêng ngăt gâp hươi, aƀaơ gâp lŏ plỡ sĭt.\nDăn nau Brah May kơl gâp đăp mpăn, aƀaơ gâp ŭch sĭt yơh.\n\nChorus\nGâp sĭt yơh, gâp sĭt yơh. Mâu hôm ŭch nkhah du.\nƠ Brah Ndu ơi, dăn May rom gâp, aƀaơ gâp ŭch sĭt yơh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0040", "title": "GÂP VĂCH NGĂN, KÔRANH BRAH", "song_number": "40", "lyrics": "GÂP VĂCH NGĂN, KÔRANH BRAH\n\nTC 170, KM 40, KMM 91\n\nVerse 1\nGâp tăng bâr May jă gâp, May đă gâp văch ma May\nGay rao kloh gâp ma mham khlay May, mham hoch ta yôk Kăl-ver,\n\nChorus\nGâp văch ngăn, Kôranh Brah, gâp văch ngăn aƀaơ ro.\nRao kloh gâp ma mham khlay May, mham hoch ta yôk Kăl-ver.\n\nVerse 2\nGâp hươi, geh nau tih âk, May ăn gâp lŏ jêng ktang.\nMay rao kloh hom lĕ nau tĭh gâp, kŏ nuih n'hâm gâp kloh ngăn.\n\nChorus\nGâp văch ngăn, Kôranh Brah, gâp văch ngăn aƀaơ ro.\nRao kloh gâp ma mham khlay May, mham hoch ta yôk Kăl-ver.\n\nVerse 3\nBrah Yê-su yơh jă gâp, kuăl gâp sĭt chroh ma Păng.\nAƀaơ ri gâp dơi geh nau rêh ngăn, lăp tâm Ƀon Ueh ta klơ.\n\nChorus\nGâp văch ngăn, Kôranh Brah, gâp văch ngăn aƀaơ ro.\nRao kloh gâp ma mham khlay May, mham hoch ta yôk Kăl-ver.\n\nVerse 4\nMay geh nau rêh n'ho ro, mâu hôm klach khĭt ôm ôh.\nPô ri lĕ nau ton jêng tât ngăn, ma mbu nâm iăt nau May.\n\nChorus\nGâp văch ngăn, Kôranh Brah, gâp văch ngăn aƀaơ ro.\nRao kloh gâp ma mham khlay May, mham hoch ta yôk Kăl-ver.\nA-MEN.\n", "category": "Jă bu lăp chroh", "language": "Bunong"}, {"local_id": "nau-mpro-0041", "title": "BRAH YÊ-SU KRIST KHĬT YOR GÂP", "song_number": "41", "lyrics": "BRAH YÊ-SU KRIST KHĬT YOR GÂP\n\nTC 171, KM 41, KMM 92\n\nVerse 1\nBrah Yê-su Krist khĭt yor gâp, Yê-su yỗ nđach tâm rklaih gâp.\nNkhŭt mham Păng Nơm khlay hâu ngăn, bu ntâp tak ta pŭng vĕ Păng.\nGay ma rao kloh nau tih gâp, yor ri yơh gâp klaih ngăn jêh\n\nVerse 2\nTơ lah gâp geh nau nhhiăng nhĭm, mâu lah gâp ŭch joi brah êng.\nLĕ nau nĕ mâu tâm rklaih ôh, Yê-su dơm dơi tâm rklaih gâp.\nGâp mâu mâp rvăt nau tâm rklaih, gâp nsing ngăn ma Păng ƀa-ƀơ.\n\nVerse 3\nDôl hôm e gâp gŭ ta neh, mâu lah gâp mra dăch hăn khĭt.\nGâp dơi geh nau đăp mpăn ngăn, yor lah Păng geh tu nau rêh.\nGâp nsing ngăn ma Păng ƀa-ƀơ, yor lah Păng khĭt jêh ma gâp.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0042", "title": "TA YÔK KĂL-VER", "song_number": "42", "lyrics": "TA YÔK KĂL-VER\n\nTC 172, KM 42, KMM 93\n\nVerse 1\nJŏ jêh gâp gŭ ngai ma Brah Yê-su, mâu gĭt chrê Păng khĭt ta si tâm rkăng.\nGâp mâu gĭt Păng ŭch tâm rklaih gâp ôh ta yôk Kăl-ver.\n\nChorus\nA-ƀaơ aơ gâp chroh ma Brah Yê-su. Păng sâm yỗ an jêh lĕ nau tih gâp,\nPăng tâm rklaih jêh gâp ma mham Păng Nơm ta yôk Kăl-ver\n\nVerse 2\nUănh tâm ndrom sam-ƀŭt Nau Brah Ndu Ngơi, gâp saơ lĕ bu-nuyh geh âk nau tih.\nGâp ŭch lơi đŏng lĕ nau tih mhĭk gâp ta yôk Kăl-ver.\n\nChorus\nA-ƀaơ aơ gâp chroh ma Brah Yê-su. Păng sâm yỗ an jêh lĕ nau tih gâp,\nPăng tâm rklaih jêh gâp ma mham Păng Nơm ta yôk Kăl-ver\n\nVerse 3\nKôranh Brah Ndu rŏng ngăn ma kon bu-nuyh, Păng ŭch ăn nau rêh mro mrăng ma he.\nKing n'gang he ma lĕ dĭng lĕ nau tih ta yôk Kăl-ver.\n\nChorus\nA-ƀaơ aơ gâp chroh ma Brah Yê-su. Păng sâm yỗ an jêh lĕ nau tih gâp,\nPăng tâm rklaih jêh gâp ma mham Păng Nơm ta yôk Kăl-ver\n\nVerse 4\nGâp ăn jêh nuih n'hâm gâp ma Yê-su, Păng sâm rao kloh ma mham khlay Păng Nơm.\nĂn nuih n'hâm gâp gŭ kloh ueh ngăn ngên ta yôk Kăl-ver.\n\nChorus\nA-ƀaơ aơ gâp chroh ma Brah Yê-su. Păng sâm yỗ an jêh lĕ nau tih gâp,\nPăng tâm rklaih jêh gâp ma mham Păng Nơm ta yôk Kăl-ver\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0043", "title": "GEH CHIH SĂK GÂP LĔ BƠH?", "song_number": "43", "lyrics": "GEH CHIH SĂK GÂP LĔ BƠH?\n\nTC 175, KM 76, KMM 95\n\nVerse 1\nGâp mâu nđơr jêng ndrŏng kuăng ôh, gay âk drăp ndơ, prăk maih.\nGâp ŭch dơn chroh răp jăp ngăn, ŭch lăp tâm Ƀon Ueh May.\nTâm sam-ƀŭt May kơp phung rêh, geh âk râk moh săk bu.\nMbơh ma gâp, ơ Nơm Tâm Rklaih, geh chih săk gâp lĕ bơh?\n\nChorus\nGeh chih săk gâp lĕ bơh? Tâm sam-ƀŭt kơp phung rêh,\nndrom sam-ƀŭt tâm Ƀon Brah Ndu, geh chih săk gâp lĕ bơh?\n\nVerse 2\nKôranh ơi, nau tih gâp âk ngăn, tâm ban choih rgŏ dak mƀŭt.\nɃiă lah mham May khlay lơn đŏng, dơi rao kloh nau tih gâp.\nNau May ton hŏ nchih ngăn jêh, tâm sam-ƀŭt Nau May Ngơi:\n\"Lĕ nau tih mhĭk, nau ƀỡ ƀơch, May rao kloh ƀhiau ăn nglang\".\n\nChorus\nGeh chih săk gâp lĕ bơh? Tâm sam-ƀŭt kơp phung rêh,\nndrom sam-ƀŭt tâm Ƀon Brah Ndu, geh chih săk gâp lĕ bơh?\n\nVerse 3\nTâm Ƀon Ueh May nchrat ang ngăn, nau nchrat ang mâu dơi ntĭt.\nPăng nchrat ral rlau lơn prăk maih, bunuyh nsoh ao nglang kloh ueh.\nBu-nuyh mhĭk mâu dơi lăp ôh, klach ƀư rai nau kloh ueh.\nMbu nâm geh săk bu chih jêh, nơm nây mơ bu ăn lăp.\n\nChorus\nGeh chih săk gâp lĕ bơh? Tâm sam-ƀŭt kơp phung rêh,\nndrom sam-ƀŭt tâm Ƀon Brah Ndu, geh chih săk gâp lĕ bơh?\n", "category": "Nau Brah Ndu yỗ an", "language": "Bunong"}, {"local_id": "nau-mpro-0044", "title": "YÊ-SU TÂM CHUAI GÂP", "song_number": "44", "lyrics": "YÊ-SU TÂM CHUAI GÂP\n\nTC 174, KM 44, KMM 183\n\nVerse 1\nGâp tăng Yê-su lah jêh, \"May hươi; Gâp ŭch kơi may,\nmbơh sơm jêh ri lơi klach. Gâp rklaih lĕ nau tih may.\"\n\nChorus\nYê-su tâm chuai gâp, tâm chuai gâp dơm dam.\nNau tih gâp krăk kher hâu ngăn, ƀiă lah Păng rao kloh jêh.\n\nVerse 2\nGâp nsing ma Kôranh Yê-su, Păng yơh dơi geh nau Brah,\nnuih n'hâm lŏ rgâl jêng rdỡ, Muh măt Păng ăn jêng n'gơch.\n\nChorus\nYê-su tâm chuai gâp, tâm chuai gâp dơm dam.\nNau tih gâp krăk kher hâu ngăn, ƀiă lah Păng rao kloh jêh.\n\nVerse 3\nLah gâp gŭ ta năp Păng, tâm ngih toyh Păng ta klơ,\nmâu prêng yor lah gâp klaih. Yê-su tâm chuai jêh gâp.\n\nChorus\nYê-su tâm chuai gâp, tâm chuai gâp dơm dam.\nNau tih gâp krăk kher hâu ngăn, ƀiă lah Păng rao kloh jêh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0045", "title": "GÂP VĂCH, GÂP VĂCH", "song_number": "45", "lyrics": "GÂP VĂCH, GÂP VĂCH\n\nTC 178, KM 45, KMM 96\n\nVerse 1\nMâu hôm geh nau êng kơl n'gang gâp. Knŏng mham Yê-su yơh dơi kơl gâp.\nPăng rŏng gâp ngăn, kuăl ăn gâp sĭt. Ơ Kon Biăp Ueh, gâp văch, gâp văch.\n\nVerse 2\nMâu hôm geh brah êng gâp dơi nsing. Gay dơi ƀư kloh nuih n'hâm ƀỡ ƀơch.\nKnŏng mham Yê-su, dơi ƀư kloh gâp. Ơ Kon Biăp Ueh, gâp văch, gâp văch.\n\nVerse 3\nNuih n'hâm gâp geh âk nau rŭng răng. Geh âk nau krit, nau klach ƀa-ƀơ.\nNuih n'hâm tâm lơh, ŭch dăch rdja jêh. Ơ Kon Biăp Ueh, gâp văch, gâp văch.\n\nVerse 4\nGeh nau rêh ni, o-ach chieh măt. Ƀiă lah tâm May geh nau ueh maak.\nMay ndrŏng, kloh ueh, geh nau yỗ nđach. Ơ Kon Biăp Ueh, gâp văch, gâp văch.\n\nVerse 5\nGâp jêng tih mhĭk, Mbỡ yỗ an jêh. Tâm rklaih ƀư kloh, rom lăp tâm ngih.\nNau Mbỡ ton jêh, mâu geh mbruh ôh. Ơ Kon Biăp Ueh, gâp văch, gâp văch.\n\nVerse 6\nNuih n'hâm tih gâp, Mbỡ lâm lĕ jêh. Nau tih mhĭk toyh, Păng ƀư rai đŏng.\nNtơm bơh aƀaơ ri, gâp jêng kon May. Ơ Kon Biăp Ueh, gâp văch, gâp văch.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0046", "title": "GEH TU MHAM KHLAY", "song_number": "46", "lyrics": "GEH TU MHAM KHLAY\n\nTC 181, KM 46, KMM 100\n\nVerse 1\nGeh tu mham khlay nkhŭt ăn ma he, luh tă Brah Yê-su Krist.\nJêh ri mbu nâm jŭr ŭm ta nây, kloh ngăn lĕ rngôch nau tih.\nKloh ngăn lĕ rngôch nau tih, kloh ngăn lĕ rngôch nau tih.\nJêh ri mbu nâm jŭr ŭm ta nây, kloh ngăn lĕ rngôch nau tih.\n\nVerse 2\nNtơm bơh gâp saơ mham Yê-su Krist, gâp mâu hôm sŏk mham êng.\nYor lah mham Yê-su Krist khlay lơn, jêh ri dơi rao nau tih.\nJêh ri dơi rao nau tih, jêh ri dơi rao nau tih.\nYor lah mham Yê-su Krist khlay lơn, jêh ri dơi rao nau tih.\n\nVerse 3\nMham Yê-su Krist, Brah hâu ngăn ngên, jêh ri dơi ƀư kloh he.\nHe rŏng dŭt n'hâm ntŭk sôt Yê-su, yor lah Păng tâm rgâl he.\nYor lah Păng tâm rgâl he, yor lah Păng tâm rgâl he.\nHe rŏng dŭt n'hâm ntŭk sôt Yê-su, yor lah Păng tâm rgâl he.\n\nVerse 4\nƠ Yê-su Krist, mham May khlay ngăn, ƀư kloh ƀỡ hên ăn nglang.\nPăm êng mham May dơm dơi tâm chuai, ăn hên tâm rnglăp đah May.\nĂn hên tâm rnglăp đah May, ăn hên tâm rnglăp đah May.\nPăm êng mham May dơm dơi tâm chuai, ăn hên tâm rnglăp đah May.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0047", "title": "KANŎNG PĂM MHAM BRAH YÊ-SU KRIST DƠM", "song_number": "47", "lyrics": "KANŎNG PĂM MHAM BRAH YÊ-SU KRIST DƠM\n\nTC 182, KM 47, KMM 99\n\nVerse 1\nMoh mpa dơi rao nau tih gâp? Knŏng păm mham Brah Yê-su Krist dơm.\nMoh mpa dơi tâm rklaih gâp ngăn? Knŏng păm mham Brah Yê-su Krist dơm.\n\nChorus\nƠ, mham khlay ir ar ngăn, rao gâp ăn jêng kloh ueh.\nMâu hôm mpa khlay êng ôh, knŏng păm mham Brah Yê-su Krist dơm.\n\nVerse 2\nMoh mpa tâm chuai bunuyh lĕ rngôch? Knŏng păm mham Brah Yê-su Krist dơm.\nMoh mpa dơi mprơh lĕ Brah Mhĭk? Knŏng păm mham Brah Yê-su Krist dơm.\n\nChorus\nƠ, mham khlay ir ar ngăn, rao gâp ăn jêng kloh ueh.\nMâu hôm mpa khlay êng ôh, knŏng păm mham Brah Yê-su Krist dơm.\n\nVerse 3\nMoh mpa ăn gâp jêng sŏng srăng? Knŏng păm mham Brah Yê-su Krist dơm.\nMoh mpa ăn gâp gŭ đăp mpăn? Knŏng păm mham Brah Yê-su Krist dơm.\n\nChorus\nƠ, mham khlay ir ar ngăn, rao gâp ăn jêng kloh ueh.\nMâu hôm mpa khlay êng ôh, knŏng păm mham Brah Yê-su Krist dơm.\nA-MEN.\n", "category": "Mham Yêsu", "language": "Bunong"}, {"local_id": "nau-mpro-0048", "title": "GEH NAU BRAH TÂM MHAM", "song_number": "48", "lyrics": "GEH NAU BRAH TÂM MHAM\n\nTC 183, KM 48, KMM 101\n\nVerse 1\nAy may ŭch lĕ dơi klaih ngăn bah nau tih? Geh nau Brah tâm mham, nau Brah tâm mham.\nAy may ŭch lĕ dơi tâm rdâng dah nau ƀai? Geh nau Brah khlay ngăn tâm mham Păng.\n\nChorus\nGeh nau Brah, Brah khlay ir ar hâu ngăn. Tâm mham Kôranh Brah Yê-su.\nGeh nau Brah, Brah khlay ir ar hâu ngăn, tâm mham Brah Yê-su khlay hâu ngăn.\n\nVerse 2\nAy may ŭch lĕ jêng kloh nglang kơt nâm pler? Geh nau Brah tâm mham, nau Brah tâm mham.\nNau tih dơi kloh may geh nau rêh mhe ngăn? Geh nau Brah khlay ngăn tâm mham Păng.\n\nChorus\nGeh nau Brah, Brah khlay ir ar hâu ngăn. Tâm mham Kôranh Brah Yê-su.\nGeh nau Brah, Brah khlay ir ar hâu ngăn, tâm mham Brah Yê-su khlay hâu ngăn.\n\nVerse 3\nAy may ŭch lĕ pah kan ma Kôranh Yê-su? Geh nau Brah tâm mham, nau Brah tâm mham.\nAy may ŭch lĕ tâm rnê Păng ăp nar? Geh nau Brah khlay ngăn tâm mham Păng.\n\nChorus\nGeh nau Brah, Brah khlay ir ar hâu ngăn. Tâm mham Kôranh Brah Yê-su.\nGeh nau Brah, Brah khlay ir ar hâu ngăn, tâm mham Brah Yê-su khlay hâu ngăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0049", "title": "TÂM RNÊ AMOH YÊ-SU", "song_number": "49", "lyrics": "TÂM RNÊ AMOH YÊ-SU\n\nTC 187, KM 49, KMM 102\n\nVerse 1\nTa si tâm rkăng Nơm tâm rklaih gâp khĭt. Ta ntŭk nây gâp dăn ƀư kloh nau tih.\nPô nây mham Yê-su rao gâp ăn nglang. Tâm rnê Yê-su.\n\nChorus\nTâm rnê Yê-su. Tâm rnê Yê-su.\nTa si tâm rkăng Păng rao nau tih gâp. Tâm rnê Yê-su.\n\nVerse 2\nGâp lĕ klaih jêh đah lĕ rngôch nau tih. Yê-su lăp jêh gŭ tâm nuih n'hâm gâp.\nTa si tâm rkăng Yê-su vơt dơn gâp. Tâm rnê Yê-su.\n\nChorus\nTâm rnê Yê-su. Tâm rnê Yê-su.\nTa si tâm rkăng Păng rao nau tih gâp. Tâm rnê Yê-su.\n\nVerse 3\nÔ tu mham khlay ƀư kloh lĕ nau tih. Gâp maak dŭt n'hâm lăp ŭm ntuh ta nây.\nTih iơh mhĭk gâp Păng rao lĕ ăn kloh. Tâm rnê Yê-su.\n\nChorus\nTâm rnê Yê-su. Tâm rnê Yê-su.\nTa si tâm rkăng Păng rao nau tih gâp. Tâm rnê Yê-su.\n\nVerse 4\nMay văch hom ma tu mham khlay nar aơ. Păn ta jâng Yê-su, Nơm tâm rklaih he.\nNgoch tâm mham Păng, ƀư kloh may nar aơ. Tâm rnê Yê-su.\n\nChorus\nTâm rnê Yê-su. Tâm rnê Yê-su.\nTa si tâm rkăng Păng rao nau tih gâp. Tâm rnê Yê-su.\nA-MEN.\n", "category": "Mham Yêsu", "language": "Bunong"}, {"local_id": "nau-mpro-0050", "title": "GÂP GŬ ÊP TA SI TÂM RKĂNG", "song_number": "50", "lyrics": "GÂP GŬ ÊP TA SI TÂM RKĂNG\n\nTC 193, KM 50, KMM 104\n\nVerse 1\nGâp gŭ êp ta si tâm rkăng, kêng tu dak mham khlay hoch,\nLuh bơh ntŭk tâm yôk Kăl-ver, Dơi rao kloh nau tih gâp.\n\nChorus\nSi tâm rkăng, si tâm rkăng, ri gâp ŭch gŭ êp mro.\nTât gâp rgăn kăl tễ dak krong, lăp gŭ tâm Ƀon Ueh klơ.\n\nVerse 2\nSi tâm rkăng May tâm rklaih gâp, lĕ bunuyh tih May yỗ ngăn.\nMay ăn nau Brah May sol ang, Mprơh nau ngo, ăn ang gâp.\n\nChorus\nSi tâm rkăng, si tâm rkăng, ri gâp ŭch gŭ êp mro.\nTât gâp rgăn kăl tễ dak krong, lăp gŭ tâm Ƀon Ueh klơ.\n\nVerse 3\nSi tâm rkăng Biăp Ueh Brah Ndu, lơi dĭng he kah chuêl ôh.\nGâp tĭng mbe gui May ƀa-ƀơ, Mâu hôm geh nau krit ôh.\n\nChorus\nSi tâm rkăng, si tâm rkăng, ri gâp ŭch gŭ êp mro.\nTât gâp rgăn kăl tễ dak krong, lăp gŭ tâm Ƀon Ueh klơ.\n\nVerse 4\nGâp gŭ êp si tâm rkăng mro, kâp gân Yê-su văch đŏng,\nKŏ gâp dơi tât tâm ntŭk ueh, Kăl tễ ri kơh dak krong.\n\nChorus\nSi tâm rkăng, si tâm rkăng, ri gâp ŭch gŭ êp mro.\nTât gâp rgăn kăl tễ dak krong, lăp gŭ tâm Ƀon Ueh klơ.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0051", "title": "ĂN MAY VĂCH MA YÊ-SU", "song_number": "51", "lyrics": "ĂN MAY VĂCH MA YÊ-SU\n\nTC 184, KMM 217\n\nVerse 1\nĂn may văch ma Yê-su jêng Kon Biăp Brah Ndu. Păng mra ăn nuih n'hâm may jêng kloh ueh.\nLah may chroh ma Păng jêng Nơm tâm rklaih may ngăn, Păng mra ăn nuih n'hâm may jêng kloh ueh.\n\nChorus\nMa mham Brah Yê-su Krist nuih n'hâm may jêng kloh ƀhiau lĕ nau tih.\nAo ƀỡ may mra jêng tâm ban nâm pler nglang ngăn, Păng mra ăn nuih n'hâm may jêng kloh ueh.\n\nVerse 2\nMay hăn nsong ƀa-ƀơ lĕ dăch ma Kôranh Yê-su? Păng mra ăn nuih n'hâm may jêng kloh ueh.\nMay mâp dăn Păng lĕ, gay kơl may der nau tih? Păng mra ăn nuih n'hâm may jêng kloh ueh.\n\nChorus\nMa mham Brah Yê-su Krist nuih n'hâm may jêng kloh ƀhiau lĕ nau tih.\nAo ƀỡ may mra jêng tâm ban nâm pler nglang ngăn, Păng mra ăn nuih n'hâm may jêng kloh ueh.\n\nVerse 3\nMay geh ao kloh ueh lĕ tă ma Brah Ndu ăn? Păng mra ăn nuih n'hâm may jêng kloh ueh.\nMay hŏ ndrăp jêh ndơ, gay lăp tâm Ƀon Brah Ndu? Păng mra ăn nuih n'hâm may jêng kloh ueh.\n\nChorus\nMa mham Brah Yê-su Krist nuih n'hâm may jêng kloh ƀhiau lĕ nau tih.\nAo ƀỡ may mra jêng tâm ban nâm pler nglang ngăn, Păng mra ăn nuih n'hâm may jêng kloh ueh.\n\nVerse 4\nĂn may doh lơi lĕ kho ao ƀỡ ƀơch tih mhĭk. Păng mra ăn nuih n'hâm may jêng kloh ueh.\nMham Yê-su dơi tho ăn kloh nau tih lĕ rngôch. Păng mra ăn nuih n'hâm may jêng kloh ueh.\n\nChorus\nMa mham Brah Yê-su Krist nuih n'hâm may jêng kloh ƀhiau lĕ nau tih.\nAo ƀỡ may mra jêng tâm ban nâm pler nglang ngăn, Păng mra ăn nuih n'hâm may jêng kloh ueh.\n", "category": "Mham Yêsu", "language": "Bunong"}, {"local_id": "nau-mpro-0052", "title": "SAƠ JÊH MĬT JIĂNG", "song_number": "52", "lyrics": "SAƠ JÊH MĬT JIĂNG\n\nTC 206, KM 51, KMM 108\n\nVerse 1\nSaơ jêh mĭt jiăng, ueh maak ma gâp, ê gâp chroh Păng, Păng rŏng jêh.\nMa bâr ngơi ueh Păng bonh njung gâp, Yê-su kât gâp ndrel ma Păng.\nGeh nau tâm rnglăp đêh rmên ƀa-ƀơ, nau kât nĕ mâu dơi rlât ôh.\nNuih n'hâm geh jêh Kôranh Brah chiă uănh. Yê-su ăt hôm e n'ho ro.\n\nVerse 2\nGeh jêh mĭt jiăng ueh maak ma gâp, yor gâp, Păng jao săk jăn Păng.\nMa mham khlay Păng jêng ndơ tâm chuai, huêng gâp Păng rao hŏ kloh jêh.\nLĕ rngôch ndơ gâp mâu hôm prăp ôh, ŭch nhhơr ma Kôranh Nơm rklaih gâp.\nSăk jăn, nuih n'hâm, nau mĭn, drăp ndơ, gâp nhhơr lĕ ma Brah Yê-su.\n\nVerse 3\nTât jêh mĭt jiăng ueh maak ma gâp, Yê-su Nơm geh lĕ nau Brah.\nLeo trong ƀa-ƀơ kŏ tât ta klơ, tâm Ƀon Ueh răm gŭ n'ho ro.\nNau chrêk ma lơp, đăp mpăn, nđik rngêt, nau khlay aơ ƀư n'hao nuih gâp.\nNtơm abaơ gŭ njrăng nsrôih lĕ nuih n'hâm, mra geh gŭ maak răm n'ho ro.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0053", "title": "Ơ NAR UEH LƠN", "song_number": "53", "lyrics": "Ơ NAR UEH LƠN\n\nTC 210, KM 53, KMM 109\n\nVerse 1\nƠ nar ueh lơn, nar gâp lăp chroh ma Amoh Yê-su.\nNơm dơi tâm chuai, gâp răm nuih n'hâm, gâp nchah jâng ti.\nNkoch bri nau maak, nkoch dak nau khlay.\n\nChorus\nNar ueh lơn răm r-hơn, Yê-su yỗ yai, tâm chuai đô he.\nĂn dơi gŭ ngau ma nau sŏng srăng, ăn blau mbơh sơm r-nơm ma Păng.\nNar ueh lơn, răm r-hơn, Yê-su yỗ yai, tâm chuai đô he.\n\nVerse 2\nLôch nau tâm ton, tâm kol gŭ n'hanh ma Kôranh Yê-su.\nNâp lơn ma kông, Păng rŏng gâp hâu, Păng jă nhêt ƀŭn.\nLah njŭn gâp hăn, lah đă gâp tông.\n\nChorus\nNar ueh lơn răm r-hơn, Yê-su yỗ yai, tâm chuai đô he.\nĂn dơi gŭ ngau ma nau sŏng srăng, ăn blau mbơh sơm r-nơm ma Păng.\nNar ueh lơn, răm r-hơn, Yê-su yỗ yai, tâm chuai đô he.\n\nVerse 3\nMâu hôm lă lau, mâu hôm glau gle, kăl e gâp mblêng.\nA-ƀaơ sĭt chroh, gâp iăng gŭ ndrel Yê-su n'ho ro.\nPăng tho ăn ueh, Păng jut ăn kloh.\n\nChorus\nNar ueh lơn răm r-hơn, Yê-su yỗ yai, tâm chuai đô he.\nĂn dơi gŭ ngau ma nau sŏng srăng, ăn blau mbơh sơm r-nơm ma Păng.\nNar ueh lơn, răm r-hơn, Yê-su yỗ yai, tâm chuai đô he.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0054", "title": "NTŬK YÊ-SU GŬ, TA NĔ ƀON UEH", "song_number": "54", "lyrics": "NTŬK YÊ-SU GŬ, TA NĔ ƀON UEH\n\nTC 211, KM 54, KMM 110\n\nVerse 1\nNtơm Krist ăn huêng gâp jêng kon me, gâp maak nâm bu tâm Ƀon Brah Ndu.\nGeh Yê-su n'hanh, rêh ni kđôi lĕ, ntŭk Yê-su gŭ, ta nĕ Ƀon Ueh.\n\nChorus\nHa-lê-lu-ya, Krist gŭ tâm gâp, lĕ nau tih gâp Păng hŏ yỗ jêh.\nKđôi moh nau tât klơ neh, dak mƀŭt, ntŭk Yê-su gŭ, ta nĕ Ƀon Ueh.\n\nVerse 2\nBơh jŏ kăl e gâp saơ Ƀon Ueh, Yê-su tâm mpơl muh măt Păng Nơm.\nA-ƀaơ Ƀon Ueh gŭ tâm huêng gâp, ntŭk Yê-su gŭ, ta nĕ Ƀon Ueh.\n\nChorus\nHa-lê-lu-ya, Krist gŭ tâm gâp, lĕ nau tih gâp Păng hŏ yỗ jêh.\nKđôi moh nau tât klơ neh, dak mƀŭt, ntŭk Yê-su gŭ, ta nĕ Ƀon Ueh.\n\nVerse 3\nGâp mâu rvê ôh ta ntŭk gâp gŭ, ta klơ yôk yang mâu lah bri rlŭng.\nChuanh nkơp mâu lah tâm ngih toyh ueh, ntŭk Yê-su gŭ, ta nĕ Ƀon Ueh.\n\nChorus\nHa-lê-lu-ya, Krist gŭ tâm gâp, lĕ nau tih gâp Păng hŏ yỗ jêh.\nKđôi moh nau tât klơ neh, dak mƀŭt, ntŭk Yê-su gŭ, ta nĕ Ƀon Ueh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0055", "title": "NTƠM BƠH PĂNG TÂM CHUAI GÂP", "song_number": "55", "lyrics": "NTƠM BƠH PĂNG TÂM CHUAI GÂP\n\nTC 214, KM 55, KMM 111\n\nVerse 1\nGâp geh nau mprơ ŭch mprơ ƀa-ƀơ, ntơm bơh Păng tâm chuai gâp.\nMât ton Nơm Rklaih Brah Krist Hađăch Toyh, yor lah Păng tâm chuai gâp.\n\nChorus\nNtơm bơh Păng tâm chuai gâp. Ntơm bơh Păng tâm chuai gâp.\nGâp ŭch mprơ tâm rnê ma Păng. Ntơm bơh Păng tâm chuai gâp,\nGâp ŭch mât ton tâm rnê Păng ƀa-ƀơ.\n\nVerse 2\nGâp geh Yê-su ƀư maak gâp jêh, ntơm bơh Păng tâm chuai gâp.\nGâp nđơr ŭch ƀư tĭng nau Păng ntĭm, yor lah Păng tâm chuai gâp.\n\nChorus\nNtơm bơh Păng tâm chuai gâp. Ntơm bơh Păng tâm chuai gâp.\nGâp ŭch mprơ tâm rnê ma Păng. Ntơm bơh Păng tâm chuai gâp,\nGâp ŭch mât ton tâm rnê Păng ƀa-ƀơ.\n\nVerse 3\nHuêng Ueh Brah Ndu sol nuih n'hâm gâp, ntơm bơh Păng tâm chuai gâp.\nMprơh lĕ nau klach, mprơh lĕ brah mhĭk, yor lah Păng tâm chuai gâp.\n\nChorus\nNtơm bơh Păng tâm chuai gâp. Ntơm bơh Păng tâm chuai gâp.\nGâp ŭch mprơ tâm rnê ma Păng. Ntơm bơh Păng tâm chuai gâp,\nGâp ŭch mât ton tâm rnê Păng ƀa-ƀơ.\n\nVerse 4\nNau Păng ƀư maak gâp mâu dơi rblang, ntơm bơh Păng tâm chuai gâp\nGâp nsing ma mham khlay Yê-su dơm, yor lah Păng tâm chuai gâp.\n\nChorus\nNtơm bơh Păng tâm chuai gâp. Ntơm bơh Păng tâm chuai gâp.\nGâp ŭch mprơ tâm rnê ma Păng. Ntơm bơh Păng tâm chuai gâp,\nGâp ŭch mât ton tâm rnê Păng ƀa-ƀơ.\n\nVerse 5\nPăng nkra ngih jêh ma gâp ta klơ, ntơm bơh Păng tâm chuai gâp.\nGâp mra gŭ ndrel n'hanh Păng mro mrăng, yor lah Păng tâm chuai gâp.\n\nChorus\nNtơm bơh Păng tâm chuai gâp. Ntơm bơh Păng tâm chuai gâp.\nGâp ŭch mprơ tâm rnê ma Păng. Ntơm bơh Păng tâm chuai gâp,\nGâp ŭch mât ton tâm rnê Păng ƀa-ƀơ.\n", "category": "Nau maak răm", "language": "Bunong"}, {"local_id": "nau-mpro-0056", "title": "YÊ-SU PĂNG CHUAI LƠI NAU TIH HE", "song_number": "56", "lyrics": "YÊ-SU PĂNG CHUAI LƠI NAU TIH HE\n\nTC 216, KM 56, KMM 112\n\nVerse 1\nYê-su Păng chuai lơi nau tih he, Păng jêng Nơm Tâm Chuai khlay ngăn.\nHe jêng kon me yor Păng chuai jêh, Păng jêng Nơm Tâm Chuai khlay ngăn.\n\nChorus\nƠ Yê-su, Yê-su Krist, Păng jêng Nơm Tâm Chuai khlay ngăn.\nƠ Yê-su, Yê-su Krist, Păng jêng Nơm Tâm Chuai ngăn.\n\nVerse 2\nTâm rnê Krist, mham Păng rao kloh he, Păng jêng Nơm Tâm Chuai khlay ngăn.\nPăng tâm rnglăp huêng he đah Brah Ndu, Păng jêng Nơm Tâm Chuai khlay ngăn.\n\nChorus\nƠ Yê-su, Yê-su Krist, Păng jêng Nơm Tâm Chuai khlay ngăn.\nƠ Yê-su, Yê-su Krist, Păng jêng Nơm Tâm Chuai ngăn.\n\nVerse 3\nPăng rao nau tih gâp tâm nuih n'hâm, Păng jêng Nơm Tâm Chuai khlay ngăn.\nAƀaơ Păng chiă uănh lĕ nuih n'hâm gâp, Păng jêng Nơm Tâm Chuai khlay ngăn.\n\nChorus\nƠ Yê-su, Yê-su Krist, Păng jêng Nơm Tâm Chuai khlay ngăn.\nƠ Yê-su, Yê-su Krist, Păng jêng Nơm Tâm Chuai ngăn.\n\nVerse 4\nKôranh Yê-su chiă uănh lĕ trong gâp, Păng jêng Nơm Tâm Chuai khlay ngăn.\nPăng ăn gâp gŭ đăp rmên ndrel Păng, Păng jêng Nơm Tâm Chuai khlay ngăn.\n\nChorus\nƠ Yê-su, Yê-su Krist, Păng jêng Nơm Tâm Chuai khlay ngăn.\nƠ Yê-su, Yê-su Krist, Păng jêng Nơm Tâm Chuai ngăn.\n\nVerse 5\nGâp jao lĕ nuih n'hâm gâp ma Păng, Păng jêng Nơm Tâm Chuai khlay ngăn.\nNeh ntu mâu dơi geh nau yỗ ôh, Păng jêng Nơm Tâm Chuai khlay ngăn.\n\nChorus\nƠ Yê-su, Yê-su Krist, Păng jêng Nơm Tâm Chuai khlay ngăn.\nƠ Yê-su, Yê-su Krist, Păng jêng Nơm Tâm Chuai ngăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0057", "title": "GÂP KLAIH JÊH", "song_number": "57", "lyrics": "GÂP KLAIH JÊH\n\nKM 139, KMM 106\n\nVerse 1\nA-ƀaơ gâp dơi mprơ n'hanh oh mon Kôranh Brah Yê-su, huêng gâp gŭ rêh ăn đăp mpăn mro mrăng.\nĂn lĕ rngôch bunuyh dơi tăng nau ueh lăng he mprơ aơ:\" Yê-su tâm chuai gâp ma mham khlay Păng.\"\n\nChorus\nGâp klaih jêh, gâp klaih jêh. Yê-su tâm rklaih chiă uănh gâp ƀa-ƀơ,\nHa-lê-lu-ya, pô ri gâp mprơ pô aơ n'hanh ma phung sŏng srăng:\n\"Yê-su tâm chuai gâp ma mham khlay Păng.\"\n\nVerse 2\nGâp gĭt ngăn gâp hŏ geh nau rêh ueh Yê-su ăn, pô ri gâp mâu hôm klach ma nau khĭt.\nGâp sĭt gŭ tâm nau ang Kôranh Brah n'gang an nau ngo. Yê-su tâm chuai gâp ma mham khlay Păng.\n\nChorus\nGâp klaih jêh, gâp klaih jêh. Yê-su tâm rklaih chiă uănh gâp ƀa-ƀơ,\nHa-lê-lu-ya, pô ri gâp mprơ pô aơ n'hanh ma phung sŏng srăng:\n\"Yê-su tâm chuai gâp ma mham khlay Păng.\"\n\nVerse 3\nPăng yỗ nđach gâp mro mrăng, Păng sâm n'ngang gâp rŏ trong, Păng dơi rklaih lĕ rngôch nau bâp, nau iăng.\nNjŭn gâp tâm nklang trong ueh ăn gâp geh nau rêh maak. Yê-su tâm chuai gâp ma mham khlay Păng.\n\nChorus\nGâp klaih jêh, gâp klaih jêh. Yê-su tâm rklaih chiă uănh gâp ƀa-ƀơ,\nHa-lê-lu-ya, pô ri gâp mprơ pô aơ n'hanh ma phung sŏng srăng:\n\"Yê-su tâm chuai gâp ma mham khlay Păng.\"\n\nVerse 4\nLah gâp geh nau uh ah, lơi tâm ƀah đah phung chroh, gâp gŭ dơh dăch ma Yê-su kơl gâp.\nLah mâp phung rlăng kâp dah gâp mbe Brah Yê-su ro. Yê-su tâm chuai gâp ma mham khlay Păng.\n\nChorus\nGâp klaih jêh, gâp klaih jêh. Yê-su tâm rklaih chiă uănh gâp ƀa-ƀơ,\nHa-lê-lu-ya, pô ri gâp mprơ pô aơ n'hanh ma phung sŏng srăng:\n\"Yê-su tâm chuai gâp ma mham khlay Păng.\"\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0058", "title": "HA-LÊ-LU-YA, MÂT TON YÊ-SU", "song_number": "58", "lyrics": "HA-LÊ-LU-YA, MÂT TON YÊ-SU\n\nTC 220, KM 57, KMM 115\n\nVerse 1\nMât ton ma Brah Ndu, May jêng Kôranh Brah Toyh Ngăn,\nMay ăn Kon May, Yê-su, Tâm Rklaih lĕ nau tih.\n\nChorus\nHa-lê-lu-ya, mât ton Yê-su, Ha-lê-lu-ya, A-Men.\nHa-lê-lu-ya, mât ton Yê-su, hên rŏng May hâu ngăn.\n\nVerse 2\nMât ton ma Yê-su. May jêng Nơm ueh hâu ngăn,\nMay khĭt ta si tâm rkăng, ăn nau rêh ma hên.\n\nChorus\nHa-lê-lu-ya, mât ton Yê-su, Ha-lê-lu-ya, A-Men.\nHa-lê-lu-ya, mât ton Yê-su, hên rŏng May hâu ngăn.\n\nVerse 3\nMât ton ma Brah Huêng, jêng Huêng Ueh Brah Ndu Nơm,\nMay gŭ tâm nuih n'hâm hên mprơh lĕ rngôch nau mhĭk.\n\nChorus\nHa-lê-lu-ya, mât ton Yê-su, Ha-lê-lu-ya, A-Men.\nHa-lê-lu-ya, mât ton Yê-su, hên rŏng May hâu ngăn.\n\nVerse 4\nVăch hom lĕ phung tih, tông hom nau Brah Ndu Ngơi,\nJêh ri Păng mra yỗ an, lĕ nau tih phung he.\n\nChorus\nHa-lê-lu-ya, mât ton Yê-su, Ha-lê-lu-ya, A-Men.\nHa-lê-lu-ya, mât ton Yê-su, hên rŏng May hâu ngăn.\n\nVerse 5\nĂn lĕ nau nchrat ang, jêh ri nđâp lĕ nau Brah,\năn prăp tâm Amoh Yê-su, yor lah Păng Kôranh Brah.\n\nChorus\nHa-lê-lu-ya, mât ton Yê-su, Ha-lê-lu-ya, A-Men.\nHa-lê-lu-ya, mât ton Yê-su, hên rŏng May hâu ngăn.\nA-MEN.\n", "category": "Nau maak răm", "language": "Bunong"}, {"local_id": "nau-mpro-0059", "title": "CHUAT TÂM NAU ANG", "song_number": "59", "lyrics": "CHUAT TÂM NAU ANG\n\nKM 157, KMM 181\n\nVerse 1\nHe ŭch hăn chuat tĭng têl jâng Nơm Tâm Rklaih he. He ŭch ngăn tĭng ndỗ Păng ăp nar ƀa-ƀơ,\nŬch nkra nau rêh he kơt nau rêh ueh Yê-su. Maak hâu ngăn, maak răm, lah he tĭng ndỗ Păng.\n\nChorus\nƠ ueh hâu ngăn chuat tĭng têl Nơm Tâm Rklaih he. Chuat tâm nau ang, chuat tâm nau ang.\nƠ ueh hâu ngăn chuat tĭng têl jâng Nơm Tâm Rklaih he. Tĭng ndỗ Păng tâm trong ang.\n\nVerse 2\nHe ŭch hăn dăch lơn ma Nơm chuat pa năp he. Tơ lah Sa-tan ndơm he lơi tâm trong aơ.\nNsing ma ti ktang Yê-su, Păng dơi n'gang an he. Maak hâu ngăn, maak răm nau mprơ tâm rnê Păng.\n\nChorus\nƠ ueh hâu ngăn chuat tĭng têl Nơm Tâm Rklaih he. Chuat tâm nau ang, chuat tâm nau ang.\nƠ ueh hâu ngăn chuat tĭng têl jâng Nơm Tâm Rklaih he. Tĭng ndỗ Păng tâm trong ang.\n\nVerse 3\nHe ŭch hăn chuat tĭng têl jâng Nơm Tâm Rklaih he. Hăn hom gơnh oi dôl Păng Nơm njŭn leo he.\nHe dơi saơ Păng jêng Kôranh Brah geh nau nchrat ang. Maak hâu ngăn, maak răm, he mra gŭ ndrel Păng.\n\nChorus\nƠ ueh hâu ngăn chuat tĭng têl Nơm Tâm Rklaih he. Chuat tâm nau ang, chuat tâm nau ang.\nƠ ueh hâu ngăn chuat tĭng têl jâng Nơm Tâm Rklaih he. Tĭng ndỗ Păng tâm trong ang.\n", "category": "Nau dơh dăch ma Yêsu", "language": "Bunong"}, {"local_id": "nau-mpro-0060", "title": "GÂP NHHƠR NAU RÊH GÂP MA YÊ-SU", "song_number": "60", "lyrics": "GÂP NHHƠR NAU RÊH GÂP MA YÊ-SU\n\nTC 238, KM 60, KMM 117\n\nVerse 1\nGâp nhhơr nau rêh gâp ma Yê-su, Biăp Ueh Brah Ndu khĭt jêh yor gâp.\nGâp ŭch chroh ngăn ma May ƀa-ƀơ, ơ Nơm Tâm Rklaih gâp ơi.\n\nChorus\nGâp rêh ma Nơm khĭt jêh yor gâp. Nuih n'hâm gâp răm dơi gŭ đăp mpăn.\nGâp rêh ma Nơm khĭt jêh yor gâp, ơ Nơm Tâm Rklaih gâp ơi.\n\nVerse 2\nAbaơ ri gâp gĭt May dơn gâp ngăn. May khĭt gay ăn nau rêh ma gâp.\nGâp nsing ma May ƀa-ƀơ tât khĭt, ơ Nơm Tâm Rklaih gâp ơi.\n\nChorus\nGâp rêh ma Nơm khĭt jêh yor gâp. Nuih n'hâm gâp răm dơi gŭ đăp mpăn.\nGâp rêh ma Nơm khĭt jêh yor gâp, ơ Nơm Tâm Rklaih gâp ơi.\n\nVerse 3\nYê-su Krist khĭt ta yôk Kal-ver; Tâm rklaih huêng gâp gay jêng kon me.\nGâp ŭch nhhơr nau rêh gâp ma May, ơ Yê-su Nơm Rklaih gâp.\n\nChorus\nGâp rêh ma Nơm khĭt jêh yor gâp. Nuih n'hâm gâp răm dơi gŭ đăp mpăn.\nGâp rêh ma Nơm khĭt jêh yor gâp, ơ Nơm Tâm Rklaih gâp ơi.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0061", "title": "ÊP KÊNG MAY NƠM", "song_number": "61", "lyrics": "ÊP KÊNG MAY NƠM\n\nTC 240, KM 61, KMM 118\n\nVerse 1\nƠ Brah Ndu ăn gâp văch êp kêng May Nơm. Nuih n'hâm gâp ŭch du ntil: gŭ kêng May Nơm.\nLah geh mâp nau uh ah, tâm ban n'ganh dak klŏng jru. Chiă uănh gâp, gŭ đăp mpăn êp kêng May Nơm.\n\nVerse 2\nƠ Brah Ndu, ăn gâp gŭ êp kêng May Nơm. Lah geh âk nau mhĭk blem, gŭ kêng May Nơm.\nLah geh nau Brah Mhĭk ndơm, njŭn leo gâp tâm trong tih. Ơ Mbỡ ơi, ăn gâp gŭ êp kêng May Nơm.\n\nVerse 3\nGâp ŭch gŭ dăch ƀa-ƀơ êp kêng May Nơm. Njŭn leo gâp tâm trong May, gŭ kêng May Nơm.\nSa-tan ŭch sŏk huêng gâp, ƀiă lah May nơm buay lơi. Chiă uănh gâp, gŭ đăp mpăn êp kêng May Nơm.\n\nVerse 4\nĂn gâp gŭ dăch ƀa-ƀơ êp kêng May Nơm. Gay gâp dơi uănh ntŭk May, gŭ kêng May Nơm.\nŬch iăt phung Brah ntuh bâr, gŭ mprơ tâm rnê ma May. Ăn gâp dơi, gŭ ta nây êp kêng May Nơm.\nA-MEN.\n", "category": "Nau dơh dăch ma Yêsu", "language": "Bunong"}, {"local_id": "nau-mpro-0062", "title": "GÂP JÊNG KON MAY JÊH", "song_number": "62", "lyrics": "GÂP JÊNG KON MAY JÊH\n\nTC 241, KM 132, KMM 119\n\nVerse 1\nGâp jêng kon may jêh, gâp iăt bâr May kuăl, jêh ri gâp gĭt May rŏng gâp.\nDăn May sâm chông gâp tât ta ntŭk ueh uĭn, gâp ŭch gŭ dăch May nơm ngăn.\n\nChorus\nUt gâp êp May, êp May, êp lơn, ơ Yê-su, ta si tâm rkăng ntŭk May khĭt.\nUt gâp êp May, êp May, êp lơn, ơ Yê-su, dăch kêng ntŭk hoch mham khlay May.\n\nVerse 2\nSŏk prăp gâp a-ƀaơ, tâm kan khlay Brah Ndu, dăn Brah Huêng Ueh May kơl gâp.\nĂn gâp uănh ta May, gay iăt nau May ntênh, dĭng gâp dơi geh play ma May.\n\nChorus\nUt gâp êp May, êp May, êp lơn, ơ Yê-su, ta si tâm rkăng ntŭk May khĭt.\nUt gâp êp May, êp May, êp lơn, ơ Yê-su, dăch kêng ntŭk hoch mham khlay May.\n\nVerse 3\nGâp mâu dơi gĭt rbăng, nau May rŏng jru ngăn, njŭn gâp tât Ƀon May ka-lơ.\nĂn gâp iăng gŭ ndrel n'hanh May nơm ƀa-ƀơ, tâm Ƀon Ueh, ƀon Maak ta klơ.\n\nChorus\nUt gâp êp May, êp May, êp lơn, ơ Yê-su, ta si tâm rkăng ntŭk May khĭt.\nUt gâp êp May, êp May, êp lơn, ơ Yê-su, dăch kêng ntŭk hoch mham khlay May.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0063", "title": "GÂP HAO ƀA-ƀƠ", "song_number": "63", "lyrics": "GÂP HAO ƀA-ƀƠ\n\nTC 242, KM 121, KMM 120\n\nVerse 1\nGâp hao ƀa-ƀơ rŏ trong Yê-su, ăp nar gâp dơi tât ta ntŭk ueh.\nLah tât ntŭk ueh, gâp lah pô aơ: \"Ơ Yê-su, kơl gâp hao ƀa-ƀơ\".\n\nChorus\nƠ Yê-su, chông ăn gâp dơi tât, gŭ dăch May Nơm, tât saơ May ngăn.\nMâu ŭch jŭr ôh, ŭch hao ƀa-ƀơ, tât tâm Ƀon Ueh ndrel ma Brah Ndu.\n\nVerse 2\nGâp mâu ŭch gŭ tâm nau tih ôh, mâu hôm ŭch tŭp tâm nau bu ndơm.\nGâp ŭch tĭng groi rŏ trong Yê-su. Lĕ du njăr rêh n'ho ro ƀa-ƀơ.\n\nChorus\nƠ Yê-su, chông ăn gâp dơi tât, gŭ dăch May Nơm, tât saơ May ngăn.\nMâu ŭch jŭr ôh, ŭch hao ƀa-ƀơ, tât tâm Ƀon Ueh ndrel ma Brah Ndu.\n\nVerse 3\nGâp ŭch Huêng Ueh May lăp tâm gâp, ăn nau Brah May kơl gâp ƀa-ƀơ.\nGâp mâu ŭch jêng bu-nuyh rdja ôh. Biă lah ŭch ktang dơi tât ta klơ.\n\nChorus\nƠ Yê-su, chông ăn gâp dơi tât, gŭ dăch May Nơm, tât saơ May ngăn.\nMâu ŭch jŭr ôh, ŭch hao ƀa-ƀơ, tât tâm Ƀon Ueh ndrel ma Brah Ndu.\nA-MEN.\n", "category": "Nau dơh dăch ma Yêsu", "language": "Bunong"}, {"local_id": "nau-mpro-0064", "title": "MÔNG PRĂP MBƠH SƠM", "song_number": "64", "lyrics": "MÔNG PRĂP MBƠH SƠM\n\nTC 251, KM 62, KMM 122\n\nVerse 1\nMông prăp mbơh sơm, aơ mông khlay ngăn, tâm nkhah he đah âk kan neh ntu.\nMông chon kô-mâk tâm dâng jâng Mbỡ, mbơh lĕ nau he ŭch dăn ma Păng.\nDôl he ji kuet, mâu lah klân rvê, he mbơh sơm hom dăn Yê-su kơl.\nDĭng klaih klach geh dăk brah mhĭk sân, yor lah mông aơ he prăp mbơh sơm.\nDĭng klaih, klach geh dăk brah mhĭk sân, yor lah mông aơ he prăp mbơh sơm.\n\nVerse 2\nMông prăp mbơh sơm, aơ mông khlay ngăn, Yê-su kâp iăt nau he mbơhsơm.\nPăng đơn mbơh đŏng ma Mbỡ he klơ, plỡ lah đŏng moh ntil nau he dăn.\nPăng ŭch đă he joi muh măt Păng, chroh nau Păng Ngơi, nsing nau Păng yỗ.\nJêh ri he mbơh lĕ nau rngot klâng, jao lĕ ma Păng dôl he mbơh sơm.\nJêh ri he mbơh lĕ nau rngot klâng, jao lĕ ma Păng dôl he mbơh sơm.\n\nVerse 3\nMông prăp mbơh sơm, aơ mông khlay ngăn, dăn nau Brah Păng mbêng ler tâm he.\nDăn nau rêh mhe, mbăr nau rêh ơm, gay he dơi lăp tâm Ƀon Ueh Păng.\nGŭ rlu, mâu hôm rvê nau khĭt ôm, he mra dơi nsoh ao nglang da-dê.\nDôl gŭ Ƀon Ueh, he maak hâu ngăn, saơ Yê-su ro, mâu hôm mbơh sơm.\nDôl gŭ Ƀon Ueh, he maak hâu ngăn, saơ Yê-su ro, mâu hôm mbơh sơm.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0065", "title": "BRAH YÊ-SU NƠM RŎNG HUÊNG GÂP", "song_number": "65", "lyrics": "BRAH YÊ-SU NƠM RŎNG HUÊNG GÂP\n\nTC 252, KM 65, KMM 121\n\nVerse 1\nBrah Yê-su Nơm rŏng huêng gâp, nâp ngăn ya gâp nsing ta May.\nLah gâp mâp sial dak krit ngăn, ăn gâp mbe gay May mât mơh.\nMay king gâp dơi gŭ đăp mpăn. Dăn May mprơh lơi nau mhĭk blem.\nNjŭn gâp tât ta May ô klak, sak ta trong ueh May ta klơ.\n\nVerse 2\nGâp mâu hôm ŭch joi bu êng, huêng sring gâp Brah Ndu mât jêh.\nLơi ƀât mƀăr gâp, ơ Kôranh Brah, lah gâp nkhah du ngai ma May.\nDăn May kuăl gâp, ơ Yê-su. Brah Ndu đă May tâm chuai gâp.\nMât an gâp tâm ti Brah May, gay dơi klaih ma nau rêh ni.\n\nVerse 3\nYê-su ơi, gâp dăn May kơl, mpơl hom muh măt May ma gâp.\nɃư ktang gâp, yor lah gâp hươi, lơi May klăp ndăng nau tih gâp.\nMay Nơm sŏng kloh ueh ngăn ngên. Hên jêng tih rlau nau vay May.\nÂk nau tih, săk hên jêng rgay, May geh nau yỗ nđach hâu ngăn.\n\nVerse 4\nYê-su ơi, May bêng nau ueh, geh nau sŏng nkŭm lơi tih gâp.\nMham khlay May rao gâp kŏ nglang, rsang tâm nuih n'hâm nâm bu pler.\nGâp rêh yor nau yỗ Brah Ndu. Yê-su Krist jêng Nơm rklaih gâp.\nPăng chiă uănh huêng gâp đăp rmên, hên gŭ maak ăp nar ƀa-ƀơ.\nA-MEN.\n", "category": "Nau mbơh sơm", "language": "Bunong"}, {"local_id": "nau-mpro-0066", "title": "YÊ-SU KRIST JÊNG MĬT JIĂNG UEH HE", "song_number": "66", "lyrics": "YÊ-SU KRIST JÊNG MĬT JIĂNG UEH HE\n\nTC 253, KM 64, KMM 123\n\nVerse 1\nYê-su Krist jêng mĭt jiăng ueh he. Păng sŏk lĕ nau klân, nau rvê.\nPăng đă he mbơh sơm ma Păng mro, ăn Păng gĭt lah geh nau rngot.\nLah he chuêl kuăl mbơh sơm đah Păng, he mâu dơi gŭ đăp mpăn ôh.\nPăng gŭ kâp koh dŏng phung jăt Păng, gay he gŭ đăp rmên ndrel Păng.\n\nVerse 2\nBrah Mhĭk ŭch ndơm phung he ăp nar, gay ma he tŭp tâm nau tih.\nĂt he srôih r-nơm ma Yê-su, đă Păng mprơh Brah Mhĭk ăn ngai.\nYê-su gĭt jêh he geh nau raai, Păng ŭch ăn nau Brah kơl he.\nPăng rŏng he nâm bu mĭt jiăng ueh, jêh ri he rŏng Păng tâm ban.\n\nVerse 3\nLah he anh ndơ jâk, kan jêr ngăn, gah geh nau r-gănh r-gônh.\nHe nkoch gơnh nau nây ma Yê-su, Păng mra ăn he ndjoh n'hâm suan.\nTơ lah phung chiau meng mưch mach he, lah tŭn jot, ƀư mhĭk ma he.\nHe nkoch gơnh nau nây ma Yê-su, Păng king n'gang he ma ti Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0067", "title": "GÂP CHROH MA MAY, YÊ-SU", "song_number": "67", "lyrics": "GÂP CHROH MA MAY, YÊ-SU\n\nTC 255, KM 65, KMM 124\n\nVerse 1\nGâp chroh ma May, Yê-su, jêng ndơ ƀư Brah toyh ngăn, ta si tâm rkăng.\nIăt hom nau gâp mbơh sơm, nkoch lĕ nau tih ma May.\nƠ, ăn gâp jêng kon May, ntơm bơh nar aơ.\n\nVerse 2\nNuih n'hâm gâp rgănh hâu ngăn, mâu dơi geh đăp mpăn ôh, dăn May ƀư ktang.\nĂn nau Brah May ma gâp, gŭ tâm nuih n'hâm ƀa-ƀơ.\nMay khĭt ŭch n'gang gâp ngăn, ma lĕ nau tih.\n\nVerse 3\nLah gâp geh âk nau rngot, May văch dăch kêng gâp đŏng, kah gĭt yỗ gâp.\nJut dak măt gâp ăn kloh, dăn May mprơh lơi nau ngo.\nJêh ri gâp mâu hôm klach, mâu hôm rngot ôh.\n\nVerse 4\nLah gâp hŏ tăch n'hâm jêh, gâp hăn ta May ngăn ro, tâm Ƀon Ueh uĭn.\nMay ƀư ngih jêh ma gâp, tâm Ƀon Brah Ndu ta klơ.\nMay njŭn gâp ta ntŭk nĕ, gâp hâk răm ngăn.\nA-MEN.\n", "category": "Nau mbơh sơm", "language": "Bunong"}, {"local_id": "nau-mpro-0068", "title": "Ơ NƠM RKLAIH ƠI, LƠI ƀÂT GAO GÂP", "song_number": "68", "lyrics": "Ơ NƠM RKLAIH ƠI, LƠI ƀÂT GAO GÂP\n\nTC 256, KM 67, KMM 126\n\nVerse 1\nƠ Nơm Rklaih ơi, lơi ƀât gao gâp. Iăt nau gâp nhhiăng nhĭm.\nDôl geh May veh kơl phung êng ri. Lơi ƀât gao gâp ôh.\n\nChorus\nƠ Nơm Rklaih gâp, iăt nau gâp nhhiăng nhĭm.\nDôl geh May veh kơl phung êng ri, lơi ƀât gao gâp ôh.\n\nVerse 2\nDăch sưng Hađăch nau yỗ May Kôranh Brah. Dăn Brah May kơl gâp.\nGâp chon mon, r-mal nau tih gâp. May yỗ an gâp ƀă.\n\nChorus\nƠ Nơm Rklaih gâp, iăt nau gâp nhhiăng nhĭm.\nDôl geh May veh kơl phung êng ri, lơi ƀât gao gâp ôh.\n\nVerse 3\nGâp nsing knŏng May dơm jêng toyh lơn. Nuih n'hâm gâp joi May.\nDăn May ƀư bah nau ji kuet gâp. Nau yỗ May rklaih gâp.\n\nChorus\nƠ Nơm Rklaih gâp, iăt nau gâp nhhiăng nhĭm.\nDôl geh May veh kơl phung êng ri, lơi ƀât gao gâp ôh.\n\nVerse 4\nMay jêng tu nau yỗ njung bonh gâp. Ăn nuih n'hâm gâp djăng.\nTa neh ntu aơ May gŭ ndrel gâp, Klơ trôk ndrel May đŏng.\n\nChorus\nƠ Nơm Rklaih gâp, iăt nau gâp nhhiăng nhĭm.\nDôl geh May veh kơl phung êng ri, lơi ƀât gao gâp ôh.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0069", "title": "YÊ-SU ĐĂ HE GŬ NJRĂNG MBƠH SƠM", "song_number": "69", "lyrics": "YÊ-SU ĐĂ HE GŬ NJRĂNG MBƠH SƠM\n\nTC 259, KM 68, KMM 127\n\nVerse 1\nYê-su đă he gŭ njrăng mbơh sơm, moh ntil nau tât kđôi lĕ.\nPăng mra ăn Brah Huêng Ueh kơl he, ma mbu nâm dăn nau Brah.\nMa mbu nâm dăn nau Brah.\n\nVerse 2\nYê-su đă he gŭ njrăng mbơh sơm, nâm bu ta-han ka-tang.\nIăt nau Yê-su jêh ri mbơh sơm, mra dơi yor nau mbơh sơm.\nMra dơi yor nau mbơh sơm.\n\nVerse 3\nYê-su đă he gŭ njrăng mbơh sơm, yor mông lĕ dăch tât jêh,\nLơi neh ntu hăn ran tâm Ƀon Ueh, lăp tâm Ngih Mbỡ he klơ.\nLăp tâm Ngih Mbỡ he klơ.\n\nVerse 4\nYê-su đă he gŭ njrăng mbơh sơm, du bông săk he gŭ rêh.\nGŭ njrăng ƀa-ƀơ jêh ri mbơh sơm, kŏ dơi lăp Ngih Mbỡ he.\nKŏ dơi lăp Ngih Mbỡ he.\nA-MEN.\n", "category": "Nau mbơh sơm", "language": "Bunong"}, {"local_id": "nau-mpro-0070", "title": "NSING JÊH RI TÔNG", "song_number": "70", "lyrics": "NSING JÊH RI TÔNG\n\nTC 261, KM 69, KMM 128\n\nVerse 1\nDôl he hăn ndrel Yê-su, tâm nau vay Păng hŏ ntĭm, nau Brah Păng dơi sol ang ta năp he.\nHe kan tĭng nau Păng ŭch, he iăt lĕ nau Păng ngơi, tơ lah he nsing ma Păng jêh ri tông.\n\nChorus\nNsing jêh ri tông, mâu hôm geh trong êng ôh.\nHe dơi gŭ maak tâm Yê-su, lah he nsing jêh ri tông.\n\nVerse 2\nLah he geh nau rêh ni, mâu lah Brah Mhĭk ŭch ndơm, jêh ri he mâu dơi ueh nuih n'hâm ôh.\nHe mbơh sơm ma Yê-su, dăn ăn he gŭ đăp mpăn, tơ lah he nsing ma Păng jêh ri tông.\n\nChorus\nNsing jêh ri tông, mâu hôm geh trong êng ôh.\nHe dơi gŭ maak tâm Yê-su, lah he nsing jêh ri tông.\n\nVerse 3\nMbu nâm lơi trong Brah Mhĭk, jêh ri tĭng ndỗ Yê-su, dơi chuat hăn tâm trong Păng leo ta klơ.\nPăng ăn nau ueh nđơh rngêt, jêh ri mprơh lĕ nau klach, tơ lah he nsing ma Păng jêh ri tông.\n\nChorus\nNsing jêh ri tông, mâu hôm geh trong êng ôh.\nHe dơi gŭ maak tâm Yê-su, lah he nsing jêh ri tông.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0071", "title": "TA KLƠ YÊ-SU NÂM BU LŬ KLÊR", "song_number": "71", "lyrics": "TA KLƠ YÊ-SU NÂM BU LŬ KLÊR\n\nTC 266, KM 70, KMM 129\n\nVerse 1\nYor mham Yê-su gâp klaih ngăn jêh, Păng tâm chuai gâp ta si tâm rkăng.\nGâp mâu hôm ƀư brah lah yang ôh, mâu hôm kuăl brah mhĭk kơt sa-ơm.\n\nChorus\nTa klơ Yê-su nâm bu lŭ klêr, lĕ rngôch ntŭk êng nâm bu neh choih,\nlĕ rngôch ntŭk êng nâm bu neh choih.\n\nVerse 2\nLah geh ngo klĕng gâp mâu klach ôh, yor lah Yê-su gŭ dăch gâp jêh.\nGeh dak lip kđôi, ăt gâp gŭ ueh, Yê-su ăn gâp gŭ ktang ƀa-ƀơ.\n\nChorus\nTa klơ Yê-su nâm bu lŭ klêr, lĕ rngôch ntŭk êng nâm bu neh choih,\nlĕ rngôch ntŭk êng nâm bu neh choih.\n\nVerse 3\nLah geh bu mưch, tâm rmot dŭt n'hâm, gâp gŭ klăk klêm, mâu geh mphar ôh.\nYê-su mprơh ngai lĕ rngôch Brah Mhĭk, Păng sâm king gâp gŭ đăp rmên ngăn.\n\nChorus\nTa klơ Yê-su nâm bu lŭ klêr, lĕ rngôch ntŭk êng nâm bu neh choih,\nlĕ rngôch ntŭk êng nâm bu neh choih.\n\nVerse 4\nGâp ƀư ngih jêh ta klơ lŭ klêr, mâu ŭch ƀư ôh tâm ntŭk neh choih.\nGâp jăt Yê-su mâu tĭng Brah Mhĭk, Yê-su lŭ klêr, Brah Mhĭk neh choih.\n\nChorus\nTa klơ Yê-su nâm bu lŭ klêr, lĕ rngôch ntŭk êng nâm bu neh choih,\nlĕ rngôch ntŭk êng nâm bu neh choih.\nA-MEN.\n", "category": "Nau rnơm ma Kôranh Brah", "language": "Bunong"}, {"local_id": "nau-mpro-0072", "title": "NTƠM NAR GÂP CHROH", "song_number": "72", "lyrics": "NTƠM NAR GÂP CHROH\n\nTC 269, KM 110, KMM 131\n\nVerse 1\nNtơm nar gâp chroh ma Kôranh Brah Yê-su, Brah Ndu hŏ dơn jêh gâp, kơp jêng kon Păng.\nPăng rgâl nau rêh gâp ma Brah Huêng Ueh, Păng rao nau tih gâp ma mham Kon Păng.\n\nChorus\nGâp nđơr ŭch nkoch bri nau aơ ƀa-ƀơ, du bông nau rêh gâp tât nar kăn-ndỡ.\nGâp nđơr ŭch nkoch bri nau aơ ƀa-ƀơ, du bông nau rêh gâp, tât nar kăn-ndỡ\n\nVerse 2\nYê-su Krist jêng Kôranh nau rêh, nau khĭt, pô ri gâp mâu hôm klach ma nau khĭt ôh.\nGâp hŏ geh Kôranh jêh, Amoh Păng Yê-su. lŏ ăn gâp dâk rêh, lăp Ƀon Ueh Păng.\n\nChorus\nGâp nđơr ŭch nkoch bri nau aơ ƀa-ƀơ, du bông nau rêh gâp tât nar kăn-ndỡ.\nGâp nđơr ŭch nkoch bri nau aơ ƀa-ƀơ, du bông nau rêh gâp, tât nar kăn-ndỡ\n\nVerse 3\nGâp gŭ tâm Yê-su jêng Nơm n'gang gâp, Păng ăn gâp gŭ ngau đăp mpăn ueh maak ngăn.\nGâp gŭ kâp gân Păng, tĭng nau Păng ton, vơt leo gâp sĭt ta Ƀon Ueh Păng klơ.\n\nChorus\nGâp nđơr ŭch nkoch bri nau aơ ƀa-ƀơ, du bông nau rêh gâp tât nar kăn-ndỡ.\nGâp nđơr ŭch nkoch bri nau aơ ƀa-ƀơ, du bông nau rêh gâp, tât nar kăn-ndỡ\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0073", "title": "YÊ-SU NJŬN LEO TRONG AƠ UEH UĬN", "song_number": "73", "lyrics": "YÊ-SU NJŬN LEO TRONG AƠ UEH UĬN\n\nTC 271, KM 71, KMM 132\n\nVerse 1\nYê-su njŭn leo trong aơ ueh uĭn, nau aơ bonh leng tâm nuih n'hâm gâp.\nMoh kan gâp pah, mbah rlet gâp hăn, ti Brah Ndu Nơm njŭn gâp ƀa-ƀơ.\n\nChorus\nPăng njŭn trong gâp, Păng njŭn trong gâp, Ma ti Păng nơm njŭn leo trong gâp.\nGâp tĭng ndỗ Păng răp jăp mâu lơi. Yor lah ti Brah njŭn leo trong gâp.\n\nVerse 2\nɃă geh nau ji, jêh ri nau rngot, ƀă geh nau ndrŏng, mâu lah o ach.\nDăch dak r-sang, mâu lah dak rkăl, mbah leo trong hăn Păng sâm njŭn gâp.\n\nChorus\nPăng njŭn trong gâp, Păng njŭn trong gâp, Ma ti Păng nơm njŭn leo trong gâp.\nGâp tĭng ndỗ Păng răp jăp mâu lơi. Yor lah ti Brah njŭn leo trong gâp.\n\nVerse 3\nGâp ŭch Brah Huêng Ueh lăp tâm gâp, ăn nau Brah May kơl gâp ăp năr.\nGâp mâu ŭch hươi, gâp ŭch jêng ktang, gay dơi hao tât Ƀon Ueh ka-lơ.\n\nChorus\nPăng njŭn trong gâp, Păng njŭn trong gâp, Ma ti Păng nơm njŭn leo trong gâp.\nGâp tĭng ndỗ Păng răp jăp mâu lơi. Yor lah ti Brah njŭn leo trong gâp.\n\nVerse 4\nLah lĕ kan jêh ta neh ntu aơ, lah May kuăl gâp hao sĭt kalơ trôk.\nGâp mâu klach khĭt, gâp hăn răm rhơn, yor lah Brah Ndu Nơm njŭn leo gâp.\n\nChorus\nPăng njŭn trong gâp, Păng njŭn trong gâp, Ma ti Păng nơm njŭn leo trong gâp.\nGâp tĭng ndỗ Păng răp jăp mâu lơi. Yor lah ti Brah njŭn leo trong gâp.\nA-MEN.\n", "category": "Nau rnơm ma Kôranh Brah", "language": "Bunong"}, {"local_id": "nau-mpro-0074", "title": "UEH UĬN NGĂN", "song_number": "74", "lyrics": "UEH UĬN NGĂN\n\nTC 277, KM 168, KMM 133\n\nVerse 1\nLah mâp nau đăp mpăn, nau ueh lăng nau rêh gâp. Mâu lah mâp nau rngot, nau rêh ni.\nMoh nau tât ma gâp, ăt May ăn gâp dơi lah: Ueh uĭn ngăn, ueh uĭn ngăn ma huêng gâp.\"\n\nChorus\nUeh uĭn ngăn ma huêng gâp.\nUeh uĭn ngăn, ueh uĭn ngăn ma huêng gâp.\n\nVerse 2\nLah geh nau jêr tât mâu lah brah mhĭk ŭch lơh. Gâp mâu dơi klach ôh, lĕ nau nĕ.\nYor lah Yê-su gĭt jêh ma nau. gâp jêng hươi, Păng ăn jêh nau Brah Păng kơl huêng gâp.\n\nChorus\nUeh uĭn ngăn ma huêng gâp.\nUeh uĭn ngăn, ueh uĭn ngăn ma huêng gâp.\n\nVerse 3\nHe geh nau ueh uĭn ma nau maak răm hâu aơ: Lĕ rngôch nau tih gâp, bu sŏk lơi.\nBu pâng lơi da-dê ta si tâm rkăng Yê-su. Ueh uĭn ngăn, Păng sâm rklaih jêh huêng gâp.\n\nChorus\nUeh uĭn ngăn ma huêng gâp.\nUeh uĭn ngăn, ueh uĭn ngăn ma huêng gâp.\n\nVerse 4\nHơi Kôranh, ăn gơnh tât nar hên mra saơ May đŏng. Tŭk aih tâm ban n'ha rđaih bu klôt.\nTông mpăr mra uh nŭng jêh ri Kôranh Brah mra jŭr. Pô ri yơh, ueh uĭn ngăn ma huêng gâp.\n\nChorus\nUeh uĭn ngăn ma huêng gâp.\nUeh uĭn ngăn, ueh uĭn ngăn ma huêng gâp.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0075", "title": "YÊ-SU KAH GĬT MA GÂP", "song_number": "75", "lyrics": "YÊ-SU KAH GĬT MA GÂP\n\nTC 287, KM 72, KMM 136\n\nVerse 1\nDôl geh âk nau ndơm gŭ jŭm gâp, geh âk lok ngăn tâm nklang trong gâp,\nƀiă lah a-ƀaơ gâp mâu chuêl ôh, Yê-su kah gĭt ma gâp.\n\nChorus\nYê-su kah gĭt ma gâp. Yê-su kah gĭt ma gâp.\nGâp mâu dơi klach, yor Păng gŭ dăch. Yê-su kah gĭt ma gâp.\n\nVerse 2\nTâm neh ntu aơ geh âk nau kơnh, nâm bu bok krăk nkŭm lơi săk jăn,\nnau rêh ni tŭn jot dŭt n'hâm ngăn, Yê-su kah gĭt ma gâp.\n\nChorus\nYê-su kah gĭt ma gâp. Yê-su kah gĭt ma gâp.\nGâp mâu dơi klach, yor Păng gŭ dăch. Yê-su kah gĭt ma gâp.\n\nVerse 3\nNau mhĭk blem, nau uh ah tât jêh, nar ngo klĕng, mâu lah nar kloh ang,\ngâp kah gĭt rvê ƀa-ƀơ nau aơ, Yê-su kah gĭt ma gâp.\n\nChorus\nYê-su kah gĭt ma gâp. Yê-su kah gĭt ma gâp.\nGâp mâu dơi klach, yor Păng gŭ dăch. Yê-su kah gĭt ma gâp.\nA-MEN.\n", "category": "Nau rnơm ma Kôranh Brah", "language": "Bunong"}, {"local_id": "nau-mpro-0076", "title": "GÂP TĂNG BÂR KÔRANH BRAH YÊ-SU LAH", "song_number": "76", "lyrics": "GÂP TĂNG BÂR KÔRANH BRAH YÊ-SU LAH\n\nTC 289, KM 73, KMM 138\n\nVerse 1\nGâp tăng bâr Kôranh Brah Yê-su lah: \"Văch hom, gâp ăn may rlu.\nMbu nâm anh jâk ran hom ma gâp. Gâp ăn may ndjoh n'hâm suan.\"\nGâp văch ma Yê-su, yor lah gâp anh jâk, r-gănh dŭt n'hâm.\nTâm Păng gâp saơ geh âk ntŭk rlu. Păng mra ăn gâp gŭ maak.\n\nChorus\nTâm rnglăp đah Yê-su, tâm rnglăp đah Brah Ndu.\nƠ ueh uĭn ngăn ngên nau tâm rnglăp, Yê-su jêng mĭt jiăng gâp rŏng.\n\nVerse 2\nGâp tăng bâr Kôranh Brah Yê-su lah: \"Nĕ aơ gâp ăn dơm dam.\nGâp ăn dak rêh, mbu nâm ji hir Gŭ nhêt dơi geh nau rêh.\"\nGâp văch ma Yê-su, yor lah gâp Kroh ko, ji hir dŭt n'hâm.\nNau ji hir bah, huêng gâp văch rêh. Abaơ gâp gŭ rêh tâm Păng.\n\nChorus\nTâm rnglăp đah Yê-su, tâm rnglăp đah Brah Ndu.\nƠ ueh uĭn ngăn ngên nau tâm rnglăp, Yê-su jêng mĭt jiăng gâp rŏng.\n\nVerse 3\nGâp tăng bâr Kôranh Brah Yê-su lah: \"Gâp jêng nau ang neh ntu.\nUănh hom ma gâp, may mra saơ ang. Lĕ nar may rêh jêng maak.\"\nKnŏng Kôranh Yê-su dơm geh nau ang. Yor lah Păng bêng nau Brah.\nLĕ nau ang Păng, nđâp ma nau rêh Tĭng gâp ƀa-ƀơ n'ho ro.\n\nChorus\nTâm rnglăp đah Yê-su, tâm rnglăp đah Brah Ndu.\nƠ ueh uĭn ngăn ngên nau tâm rnglăp, Yê-su jêng mĭt jiăng gâp rŏng.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0077", "title": "GŬ RĂP JĂP TÂM YÊ-SU", "song_number": "77", "lyrics": "GŬ RĂP JĂP TÂM YÊ-SU\n\nTC 292, KM 158, KMM 139\n\nVerse 1\nGâp geh nau đăp mpăn ngăn, neh ntu mâu mâp ăn ôh, jêh ri Păng mâu dơi lĕ ƀư rai.\nNđâp lah geh âk nau jêr, gŭ jŭm gâp nâm thŭl tŭk, nau đăp mpăn gâp hôm e gŭ ƀa-ƀơ.\n\nChorus\nGŭ răp jăp tâm Yê-su Păng jêng Kôranh gâp\nGŭ răp jăp tâm Yê-su nau maak hâu ngăn.\nPăng mâu mâp ăn gâp gŭ rngot. Păng ngơi rdỡ pô aơ:\n\"Gâp mâu mâp cha-lơi may.\" Yê-su Kôranh gâp.\n\nVerse 2\nTâm ban lĕ rngôch nau mprơ, ma Nơm Tâm Rklaih bah klơ, tâm nar tât nau đăp mpăn ma gâp.\nLĕ nau jêr du chuăt ngai, nau ngo rgâl jêng nau ang, ơ Kôranh Yê-su, May jêng Nơm khlay ngăn.\n\nChorus\nGŭ răp jăp tâm Yê-su Păng jêng Kôranh gâp\nGŭ răp jăp tâm Yê-su nau maak hâu ngăn.\nPăng mâu mâp ăn gâp gŭ rngot. Păng ngơi rdỡ pô aơ:\n\"Gâp mâu mâp cha-lơi may.\" Yê-su Kôranh gâp.\n\nVerse 3\nAơ gâp geh nau khlay ngăn, gâp prăp Păng tâm nuih n'hâm, dôl hôm e gâp rêh ta neh ntu.\nɃiă lah Păng mra lŏ văch, nar ô klak, nar ueh ngăn, djôt leo gâp gŭ ndrel Păng Nơm ta klơ.\n\nChorus\nGŭ răp jăp tâm Yê-su Păng jêng Kôranh gâp\nGŭ răp jăp tâm Yê-su nau maak hâu ngăn.\nPăng mâu mâp ăn gâp gŭ rngot. Păng ngơi rdỡ pô aơ:\n\"Gâp mâu mâp cha-lơi may.\" Yê-su Kôranh gâp.\nA-MEN.\n", "category": "Nau tâm rnglăp", "language": "Bunong"}, {"local_id": "nau-mpro-0078", "title": "Ơ YÊ-SU GÂP RŎNG MA MAY", "song_number": "78", "lyrics": "Ơ YÊ-SU GÂP RŎNG MA MAY\n\nTC 299, KM 108, KMM 142\n\nVerse 1\nƠ Yê-su, gâp rŏng May, gâp mât ton Amoh May. Yor May, gâp lơi nau tih, jêh ri tông bâr May.\nMay jêng Nơm tâm rklaih gâp May ƀư Brah toyh ngăn. Kăl e gâp mâu rŏng May, a-ƀaơ rŏng âk ngăn\n\nVerse 2\nGâp rŏng ma May, yor May, rŏng lor ma gâp jêh. Jêh ri may yỗ nđach ngăn, ma lĕ rngôch nau tih.\nGâp rŏng yor May khĭt ta si tâm rkăng ji ngăn. Kăl e gâp mâu rŏng May, a-ƀaơ rŏng âk ngăn.\n\nVerse 3\nGĭt lah khĭt, gĭt lah rêh, gâp rŏng May ƀa-ƀơ. Tâm rnê Amoh May tât khĭt, kŏ tât gâp roh n'hâm.\nLah khĭt gâp mâu klach ôh, May ăn gâp rêh đŏng. Kăl e gâp mâu rŏng May, a-ƀaơ rŏng âk ngăn.\n\nVerse 4\nTâm Ƀon Ueh Brah Ndu klơ, gâp ŭch gŭ mro mrăng. Gay mprơ tâm rnê Brah Ndu, n'hanh ma phung tă klaih.\nR-hơn păn mbah ta năp May Nơm, toyh ngăn ngên. Kăl e gâp mâu rŏng May, a-ƀaơ rŏng âk ngăn.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0079", "title": "GÂP RŎNG PĂNG", "song_number": "79", "lyrics": "GÂP RŎNG PĂNG\n\nTC 301, KM 129, KMM 143\n\nVerse 1\nGâp lơi ngăn jêh lĕ rngôch nau tih neh ntu. Mham khlay Yê-su rao kloh jêh nuih n'hâm gâp.\nTa si tâm rkăng gâp păn mbơh lĕ nau tih, jêh ri mham Brah Yê-su ƀư kloh gâp nglang ƀhiau ngăn.\n\nChorus\nGâp rŏng Păng, gâp rŏng Păng, yor lah Păng rŏng gâp lor.\nPăng dơn nau khĭt ntrok an gâp, ta si tâm rkăng.\n\nVerse 2\nKăl e gâp roh hêng tâm nau tih mhĭk blem. Kăl e gâp jêng dĭk tông bâr ma Brah mhĭk.\nKăl e gâp mâu janh dăn ma Brah Ndu ôh, a-ƀaơ mham Yê-su ƀư kloh ngăn jêh nuih n'hâm gâp.\n\nChorus\nGâp rŏng Păng, gâp rŏng Păng, yor lah Păng rŏng gâp lor.\nPăng dơn nau khĭt ntrok an gâp, ta si tâm rkăng.\n\nVerse 3\nBrah Mhĭk kât gâp, aƀaơ Yê-su Nơm doh lơi. Kăl e gâp chieh, aƀaơ ri măt gâp saơ ang.\nKăl e gâp khĭt tâm nau tih mhĭk hâu ngăn, a-ƀaơ gâp nkoch nau ueh aơ: Yê-su rklaih gâp jêh.\n\nChorus\nGâp rŏng Păng, gâp rŏng Păng, yor lah Păng rŏng gâp lor.\nPăng dơn nau khĭt ntrok an gâp, ta si tâm rkăng.\nA-MEN.\n", "category": "Nau tâm rnglăp", "language": "Bunong"}, {"local_id": "nau-mpro-0080", "title": "YÊ-SU GEH NAU YỖ NĐACH TOYH NGĂN", "song_number": "80", "lyrics": "YÊ-SU GEH NAU YỖ NĐACH TOYH NGĂN\n\nTC 304, KMM 304\n\nVerse 1\nYê-su geh nau yỗ nđach toyh ngăn, Păng deh dơn âk nau rêh ni.\nTa si tâm rkăng Yê-su hoch mham, Păng khĭt yor ma nau tih gâp\n\nChorus\nƠ, nau yỗ Păng toyh jru ngăn ngên, nkah nau yỗ Yê-su ƀa-ƀơ.\nTa si tâm rkăng Păng khĭt rgâl gâp, bu pâng Păng ta nây ji ngăn.\n\nVerse 2\nPăng dơn âk nau bu ƀư rmot Păng, Păng jêng sŏng, bu kơp jêng tih.\nBu djôt leo Păng ta si tâm rkăng, Păng dơn lĕ nau bu ƀư ƀai.\n\nChorus\nƠ, nau yỗ Păng toyh jru ngăn ngên, nkah nau yỗ Yê-su ƀa-ƀơ.\nTa si tâm rkăng Păng khĭt rgâl gâp, bu pâng Păng ta nây ji ngăn.\n\nVerse 3\nMham khlay Păng hoch ta si tâm rkăng, gay rao lĕ nau tih mhĭk he.\nPăng văch gay lăp tâm nuih n'hâm he, gơnh ran Păng, lơi ƀư vi vâng.\n\nChorus\nƠ, nau yỗ Păng toyh jru ngăn ngên, nkah nau yỗ Yê-su ƀa-ƀơ.\nTa si tâm rkăng Păng khĭt rgâl gâp, bu pâng Păng ta nây ji ngăn.\n\nVerse 4\nNdrel ma phung hŏ tông jêh bâr Păng, ăn he rom Yê-su jêng Kôranh.\nĂn he ran, nsing ma nau Brah Păng, Păng dâk rêh, lŏ rklaih he đŏng.\n\nChorus\nƠ, nau yỗ Păng toyh jru ngăn ngên, nkah nau yỗ Yê-su ƀa-ƀơ.\nTa si tâm rkăng Păng khĭt rgâl gâp, bu pâng Păng ta nây ji ngăn.\n", "category": "Nau tâm rnglăp", "language": "Bunong"}, {"local_id": "nau-mpro-0081", "title": "HĂN HOM, PHUNG TAHAN YÊ-SU", "song_number": "81", "lyrics": "HĂN HOM, PHUNG TAHAN YÊ-SU\n\nTC 314, KM 74, KMM 144\n\nVerse 1\nHăn hom, ta-han Yê-su, nâm bu hăn tâm lơh; Ma si tâm rkăng Yê-su, hăn pa năp răng dăng.\nYê-su Krist Hađăch jêng Kôranh he, tâm rdâng đah phung rlăng.\nRan hom, hăn tâm lơh đah brah mhĭk, uănh ma Păng hăn lor.\n\nChorus\nHăn hom, ta-han Yê-su, nâm bu hăn tâm lơh.\nMa si tâm rkăng Yê-su, ran hom rlet pa năp.\n\nVerse 2\nNâm bu, ta-han âk ngăn, phung chroh ma Brah Ndu. Oh nâu, he gŭ kơt têl, phung tâm kơl kăl e.\nHe mâu geh tâm nkhah êng êng, he jêng du mpôl âk.\nLĕ phung he tâm rnglăp du ai nau, du ai tâm nau chroh.\n\nChorus\nHăn hom, ta-han Yê-su, nâm bu hăn tâm lơh.\nMa si tâm rkăng Yê-su, ran hom rlet pa năp.\n\nVerse 3\nɃon bri sưng hađăch dơi rai, ƀon bri hađăch dơi tŭp. Ƀiă lah phung chroh ma Krist, hôm gŭ nâp ƀa-ƀơ.\nMpông sâng n'gar ŭnh mâu mâp dơi đah phung chroh ma Krist.\nPăng hŏ ton nau ngăn jêh ma he, Păng mâu ngơi mƀruh ôh.\n\nChorus\nHăn hom, ta-han Yê-su, nâm bu hăn tâm lơh.\nMa si tâm rkăng Yê-su, ran hom rlet pa năp.\nA-MEN.\n", "category": "Nau pah kan", "language": "Bunong"}, {"local_id": "nau-mpro-0082", "title": "GŬ JANH, GŬ JANH YOR YÊ-SU", "song_number": "82", "lyrics": "GŬ JANH, GŬ JANH YOR YÊ-SU\n\nTC 315, KM 75, KMM 146\n\nVerse 1\nGŭ janh, gŭ janh yor Yê-su, ơ phung ta-han Brah Krist.\nNdâk yơr si tâm rkăng ta klơ, lơi ăn may geh nau prêng.\nĂn geh nau dơi rlau lơn đŏng, Păng njŭn âk phung ta han.\nĂn lĕ phung rlăng nchuăt du ngai, Yê-su jêng Kôranh he ngăn.\n\nVerse 2\nGŭ janh, gŭ janh yor Yê-su, kâp iăt păng uh nŭng kuăl.\nHăn hom geh nau tâm lơh toyh, dôl nar geh nau ktang Păng.\nMbu geh nau janh hăn tĭng Păng, tâm lơh đah phung rlăng âk.\nĂn janh rlau lơn đah nau ƀai, tâm rdâng ndrăng janh ma janh.\n\nVerse 3\nGŭ janh, gŭ janh yor Yê-su, gŭ nâp tâm nau ktang Păng.\nKon bunuyh mâu geh dơi kơl ôh, lơi nsing nglay săk may nơm.\nSŏk ma Brah Ndu lĕ ndơ khlay, jêh ri mbơh sơm ƀa-ƀơ.\nMoh ntŭk geh nau jêr tât kđôi, lơi dun ta ntŭk nĕ ôh.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0083", "title": "KUĂL JĂ SĬT", "song_number": "83", "lyrics": "KUĂL JĂ SĬT\n\nTC 328, KM 78, KMM 150\n\nVerse 1\nIăt bâr R-măk Biăp Ueh gŭ kuăl, gŭ tâm bri rdah, tâm bri ngo klĕng.\nPăng kuăl du mlâm kon biăp nkhah du ngai jêh đah ndrung, ngai jêh đah n'gar.\n\nChorus\nKuăl jă sĭt, kuăl jă sĭt. Kuăl păng plỡ sĭt tă roh tâm bri.\nKuăl jă sĭt, kuăl jă sĭt, kuăl biăp nkhah du sĭt ma Yê-su.\n\nVerse 2\nMbu nâm ŭch hăn kơl Rmăk Biăp Ueh, kơl joi kon biăp hiơt tâm bri mhĭk?\nMbu ŭch kơl veng sĭt nglăp tâm n'gar, du mlâm kon biăp nkhah du ngai nĕ?\n\nChorus\nKuăl jă sĭt, kuăl jă sĭt. Kuăl păng plỡ sĭt tă roh tâm bri.\nKuăl jă sĭt, kuăl jă sĭt, kuăl biăp nkhah du sĭt ma Yê-su.\n\nVerse 3\nKhân may tăng biăp roh nter tâm bri, Păng mâu gĭt ntŏ mbah trong hăn sĭt.\nKôranh Brah Nơm hŏ ntênh jêh ma may, \"hăn joi jă leo biăp gâp plỡ sĭt\"\n\nChorus\nKuăl jă sĭt, kuăl jă sĭt. Kuăl păng plỡ sĭt tă roh tâm bri.\nKuăl jă sĭt, kuăl jă sĭt, kuăl biăp nkhah du sĭt ma Yê-su.\n", "category": "Nau pah kan", "language": "Bunong"}, {"local_id": "nau-mpro-0084", "title": "HĂN HOM HE LUH TUCH BA", "song_number": "84", "lyrics": "HĂN HOM HE LUH TUCH BA\n\nTC 325, KM 77, KMM 148\n\nVerse 1\nHăn hom he luh tuch ba, hăn hom he luh tuch ba,\ntuch nau mhe mhan ueh, tuch nau ngơi khlay Brah Ndu.\nGơih pah kan ôi ơm hỡ, srôih pah kan dăch kêng mhaơ,\nôi taơ klak he sĭt đŏng, nsĭt leo âk play ba.\n\nChorus\nNsĭt leo âk play ba, nsĭt leo âk play ba\nHâk răm ngăn he sĭt dŏng nsĭt leo âk play ba.\nNsĭt leo âk play ba.\n\nVerse 2\nHe pah kan mir Kôranh Brah, he pah kan mir Kôranh Brah,\nnar nđat he găp lĕ, mih n'hach sa he găp lĕ.\nLah a-ƀaơ he luh rhal, luh dak măt, tât ji rgănh,\nôi taơ klak he sĭt đŏng nsĭt leo âk play ba.\n\nChorus\nNsĭt leo âk play ba, nsĭt leo âk play ba\nHâk răm ngăn he sĭt dŏng nsĭt leo âk play ba.\nNsĭt leo âk play ba.\n\nVerse 3\nMbơh ma bu nau Yê-su, mbơh ma bu nau Yê-su,\nPăng ntênh jêh ma he, Păng ntênh hăn lam bri neh.\nɃă tâm ntil he tuch mra chăt rêh ueh geh play âk,\nôi taơ klak he sĭt đŏng, nsĭt leo âk play ba.\n\nChorus\nNsĭt leo âk play ba, nsĭt leo âk play ba\nHâk răm ngăn he sĭt dŏng nsĭt leo âk play ba.\nNsĭt leo âk play ba.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0085", "title": "LAH TÂM MÂP MUH MĂT ĐAH YÊ-SU", "song_number": "85", "lyrics": "LAH TÂM MÂP MUH MĂT ĐAH YÊ-SU\n\nTC 333, KM 79, KMM 151\n\nVerse 1\nLah tâm mâp muh măt đah Yê-su, ta năp Păng gâp maak răm ngăn.\nNuih n'hâm gâp bêng ma nau hâk răm, yor Yê-su khĭt tâm rgâl gâp.\n\nChorus\nGâp mra saơ Păng, saơ muh măt Păng, tâm ntŭk prêh lơn ma mănh mbing.\nGâp mra saơ Păng, saơ muh măt Păng, muh măt Yê-su Krist, Kôranh Brah.\n\nVerse 2\nAƀaơ he mâu dơi ntoh saơ Păng ôh, nâm bu nkŭm ma bok ndâp klăk.\nNar ô klak he geh nau ueh uĭn, nau nchrêk rmah, Păng nchrat ang ngăn.\n\nChorus\nGâp mra saơ Păng, saơ muh măt Păng, tâm ntŭk prêh lơn ma mănh mbing.\nGâp mra saơ Păng, saơ muh măt Păng, muh măt Yê-su Krist, Kôranh Brah.\n\nVerse 3\nLah mâp Kôranh Brah he răm rhơn ngăn, lĕ nau ji kôr jêng bah ƀhiau.\nLĕ nau ndâp, nar nây mra mpơl ro, ăp nau jêr, bu mra kuaih lơi.\n\nChorus\nGâp mra saơ Păng, saơ muh măt Păng, tâm ntŭk prêh lơn ma mănh mbing.\nGâp mra saơ Păng, saơ muh măt Păng, muh măt Yê-su Krist, Kôranh Brah.\n\nVerse 4\nƠ Yê-su, dăn May ntĭm nti gâp, ăn gâp dơi gĭt rbăng nau May.\nGay gâp dơi saơ May jêng Nơm Rklaih, Yê-su Krist nơm rŏng gâp âk.\n\nChorus\nGâp mra saơ Păng, saơ muh măt Păng, tâm ntŭk prêh lơn ma mănh mbing.\nGâp mra saơ Păng, saơ muh măt Păng, muh măt Yê-su Krist, Kôranh Brah.\nA-MEN.\n", "category": "Nau pah kan", "language": "Bunong"}, {"local_id": "nau-mpro-0086", "title": "ƀON BRAH NDU GEH NAU ANG", "song_number": "86", "lyrics": "ƀON BRAH NDU GEH NAU ANG\n\nTC 244, KM 159, KMM 156\n\nVerse 1\nɃon Brah Ndu geh nau ang ueh măt uănh. Huêng măt he dơi saơ păng hôm ngai ngăn.\nTa rĭ Mbỡ gŭ kâp gân he ƀa-ƀơ, Păng dôl nkra ntŭk ăn he ueh ngăn ngên.\n\nChorus\nTâm ntŭk rĭ ueh ngăn ngên. Kêng kơh rĭ maak dŭt n'hâm he mâp ndrel.\nTâm ntŭk rĭ ueh ngăn ngên. Ta kơh rĭ ueh ngăn, he tâm mâp ndrel.\n\nVerse 2\nTât ntŭk ri he geh nau rŏng mprơ ndrel. Nau mprơ ueh phung tâm kơl geh nau ang.\nJêh ri he mâu hôm rvê kơt o ach, nuih n'hâm maak, mbung mprơ nau rêh n'ho ro.\n\nChorus\nTâm ntŭk rĭ ueh ngăn ngên. Kêng kơh rĭ maak dŭt n'hâm he mâp ndrel.\nTâm ntŭk rĭ ueh ngăn ngên. Ta kơh rĭ ueh ngăn, he tâm mâp ndrel.\n\nVerse 3\nHe mprơ ndrel gay tâm rnê ma Brah Ndu. Yor lah Păng ăn ma he nau rŏng toyh.\nJêh ri Yê-su Kon Păng khĭt yor he, pô ri yơh he jêng phung klaih ngăn ngên.\n\nChorus\nTâm ntŭk rĭ ueh ngăn ngên. Kêng kơh rĭ maak dŭt n'hâm he mâp ndrel.\nTâm ntŭk rĭ ueh ngăn ngên. Ta kơh rĭ ueh ngăn, he tâm mâp ndrel.\nA-MEN.\n", "category": "Ƀon Ueh klơ", "language": "Bunong"}, {"local_id": "nau-mpro-0087", "title": "LAH BRAH NDU KUĂL AMOH GÂP", "song_number": "87", "lyrics": "LAH BRAH NDU KUĂL AMOH GÂP\n\nTC 336, KM 80, KMM 155\n\nVerse 1\nLah Brah Ndu ăn Brah ntuh bâr Păng uh nŭng kuăl lĕ rngôch phung chroh,\nPăng mra pơk lĕ ndrom sam-ƀŭt kơp amoh phung rêh.\nJêh ri lĕ phung chroh ma Brah Yê-su mra tâm r-ƀŭn ăn nŭm.\nPăng mra kuăl amoh gâp, ăn lăp tâm Ƀon Ueh\n\nVerse 2\nHe pah kan ma Brah Ndu hom ktang lơn kăl e kŏ tât măng aơ,\nnkoch nau mhe mhan ueh aơ ma lĕ rngôch bu-nuyh.\nLah lôch kan jêh ta neh ntu, gâp hăn tâm mâp ma Kôranh Yê-su.\nPăng mra kuăl amoh gâp, ăn lăp tâm Ƀon Ueh\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0088", "title": "NEH NTU MÂU TĂP ƀON GÂP", "song_number": "88", "lyrics": "NEH NTU MÂU TĂP ƀON GÂP\n\n\nVerse 1\nNeh ntu mâu tăp ƀon gâp, ntŭk gâp veh bêch ta trong.\nɃon klơ ri, ntŭk gâp ŭch gŭ rêh ta nây n'ho ro.\nPhung tông mpăr pơk mpông ro, jêh ri gŭ kâp gâp lăp.\n\nChorus\nHuêng gâp mâu hôm iăng gŭ tâm ƀon lan neh ntu aơ.\nƠ Kôranh Brah ơi, gâp gĭt May rŏng gâp jêh.\nɃon Ueh ri ntŭk May gŭ, jêng ntŭk gâp nđơr gŭ lĕ,\nɃon ri hŏ pơk mpông jêh, phung tông mpăr gân kâp ro\nHuêng gâp mâu hôm iăng gŭ tâm ƀon lan neh ntu aơ.\n\nVerse 2\nPhung tông mpăr kâp gân gâp, maak ngăn mâu hôm vĭ vĕ.\nNau tih gâp Yê-su sŏk pâng jêh ta si tâm rkăng.\nNa-nễ Păng mât uănh gâp, yor lah gâp nsing ma Păng.\n\nChorus\nHuêng gâp mâu hôm iăng gŭ tâm ƀon lan neh ntu aơ.\nƠ Kôranh Brah ơi, gâp gĭt May rŏng gâp jêh.\nɃon Ueh ri ntŭk May gŭ, jêng ntŭk gâp nđơr gŭ lĕ,\nɃon ri hŏ pơk mpông jêh, phung tông mpăr gân kâp ro\nHuêng gâp mâu hôm iăng gŭ tâm ƀon lan neh ntu aơ.\n\nVerse 3\nTâm Ƀon Ueh Brah Ndu, geh ngih tơm he gŭ n'ho ro,\nGŭ nsum phung chroh ăp ntŭk, gŭ mprơ Ha-lê-lu-ya.\nHe soh ao nglang da-dê, tâm rnê Kôranh he Yê-su.\n\nChorus\nHuêng gâp mâu hôm iăng gŭ tâm ƀon lan neh ntu aơ.\nƠ Kôranh Brah ơi, gâp gĭt May rŏng gâp jêh.\nɃon Ueh ri ntŭk May gŭ, jêng ntŭk gâp nđơr gŭ lĕ,\nɃon ri hŏ pơk mpông jêh, phung tông mpăr gân kâp ro\nHuêng gâp mâu hôm iăng gŭ tâm ƀon lan neh ntu aơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0089", "title": "TÂM ƀON UEH TA KALƠ", "song_number": "89", "lyrics": "TÂM ƀON UEH TA KALƠ\n\nKM 123, KMM 209\n\nVerse 1\nMâu hôm geh nau tih ôh, tâm Ƀon Ueh ta klơ.\nTâm Ƀon Ueh ta klơ, tâm Ƀon Ueh ta klơ.\nMâu hôm geh nau tih ôh, tâm Ƀon Ueh ta klơ, geh nau maak ƀa-ƀơ.\n\nVerse 2\nMâu hôm geh nau ji ôh, tâm Ƀon Ueh ta klơ.\nTâm Ƀon Ueh ta klơ, tâm Ƀon Ueh ta klơ.\nMâu hôm geh nau ji ôh, tâm Ƀon Ueh ta klơ, geh nau maak ƀa-ƀơ.\n\nVerse 3\nMâu hôm geh nau rngot ôh, tâm Ƀon Ueh ta klơ.\nTâm Ƀon Ueh ta klơ, tâm Ƀon Ueh ta klơ.\nMâu hôm geh nau rngot ôh, tâm Ƀon Ueh ta klơ, geh nau maak ƀa-ƀơ.\n\nVerse 4\nMâu hôm geh nau khĭt ôh, tâm Ƀon Ueh ta klơ.\nTâm Ƀon Ueh ta klơ, tâm Ƀon Ueh ta klơ.\nMâu hôm geh nau khĭt ôh, tâm Ƀon Ueh ta klơ, geh nau maak ƀa-ƀơ.\n\nVerse 5\nMâu hôm geh nau ngo ôh, tâm Ƀon Ueh ta klơ.\nTâm Ƀon Ueh ta klơ, tâm Ƀon Ueh ta klơ.\nMâu hôm geh nau ngo ôh, tâm Ƀon Ueh ta klơ, geh nau maak ƀa-ƀơ.\n\nVerse 6\nPăm geh nau maak mro mrăng, tâm Ƀon Ueh ta klơ.\nTâm Ƀon Ueh ta klơ, tâm Ƀon Ueh ta klơ.\nPăm geh nau maak mro mrăng, tâm Ƀon Ueh ta klơ, geh nau maak ƀa-ƀơ.\n\nVerse 7\nHe gŭ ndrel ma Yê-su, tâm Ƀon Ueh ta klơ.\nTâm Ƀon Ueh ta klơ, tâm Ƀon Ueh ta klơ.\nHe gŭ ndrel ma Yê-su, tâm Ƀon Ueh ta klơ, geh nau maak ƀa-ƀơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0090", "title": "LAH HE TÂT TA ƀON UEH PĂNG", "song_number": "90", "lyrics": "LAH HE TÂT TA ƀON UEH PĂNG\n\nTC 345, KM 81, KMM 157\n\nVerse 1\nHe mprơ nau rŏng khlay ngăn Yê-su, mprơ hom nau Păng yỗ kơl he.\nTâm Ƀon Ueh Păng klơ nchrat ang ngăn, Păng nkra ntŭk ăn rơm ma he.\n\nChorus\nLah he tât ta Ƀon Ueh Păng, nar nây jêng nar maak răm âk hâu ngăn ngên.\nLah he saơ Yê-su Krist, he mra mprơ bâr ngơi ueh ma Păng\n\nVerse 2\nDôl he chuat rŏ trong tâm neh ntu, tŭk nkŭm trôk ngo nau rêh he.\nLah he srôih hăn rŏ lôch trong nây, mâu hôm rngot, mâu hôm rvê ôh.\n\nChorus\nLah he tât ta Ƀon Ueh Păng, nar nây jêng nar maak răm âk hâu ngăn ngên.\nLah he saơ Yê-su Krist, he mra mprơ bâr ngơi ueh ma Păng\n\nVerse 3\nHe srôih gŭ sŏng srăng, gŭ đăp rmên, he pah kan ueh Păng ăp nar.\nRi mơ saơ muh măt Păng ta klơ, mra nkhôm lĕ kan he nar aơ.\n\nChorus\nLah he tât ta Ƀon Ueh Păng, nar nây jêng nar maak răm âk hâu ngăn ngên.\nLah he saơ Yê-su Krist, he mra mprơ bâr ngơi ueh ma Păng\n\nVerse 4\nHe hăn hom gay gơnh tât Ƀon Păng, gơnh saơ nau chrêk rmah ta klơ.\nPăng kâp pơk mpông pêr ăn he mŭt, lăp chuat rŏ trong prăk maih Păng.\n\nChorus\nLah he tât ta Ƀon Ueh Păng, nar nây jêng nar maak răm âk hâu ngăn ngên.\nLah he saơ Yê-su Krist, he mra mprơ bâr ngơi ueh ma Păng\nA-MEN.\n", "category": "Ƀon Ueh klơ", "language": "Bunong"}, {"local_id": "nau-mpro-0091", "title": "YÊ-SU KRIST TÂM RKLAIH HE", "song_number": "91", "lyrics": "YÊ-SU KRIST TÂM RKLAIH HE\n\nTC 349, KM 82, KMM 158\n\nVerse 1\nHe maak ngăn iăt nau mprơ aơ, Yê-su Krist tâm rklaih he.\nNkoch bri nau ueh aơ ăp ntŭk, Yê-su Krist tâm rklaih he.\nNau aơ Yê-su hŏ lah jêh: Hao bri yôk mâu lah rgăn dak,\nleo nau mhe mhan aơ lam bri: Yê-su Krist tâm rklaih he.\n\nVerse 2\nNkoch nau yỗ aơ ăn ăp ntŭk, Yê-su Krist tâm rklaih he.\nĂn bu ranh, kon se gŭ iăt: Yê-su Krist tâm rklaih he.\nMprơ ăn huy lĕ khân ay may. Ăn yôk, dak tăng kloh rah vah,\năn ƀon lan dơi tăng săr lah: Yê-su Krist tâm rklaih he.\n\nVerse 3\nDôl tâm lơh, lơi dĭng chuêl mprơ, Yê-su Krist tâm rklaih he.\nPăng khĭt yor nau tih phung he, Yê-su Krist tâm rklaih he.\nGeh nau rngot, mâu lah nau iăng. Iăng săk jăn mâu lah khĭt ôm,\năn he mprơ huy kơt sa-ơm: Yê-su Krist tâm rklaih ngăn.\nA-MEN.\n", "category": "Nsong mbơh nau Yê-su", "language": "Bunong"}, {"local_id": "nau-mpro-0092", "title": "UĂNH JŬM BRI HE", "song_number": "92", "lyrics": "UĂNH JŬM BRI HE\n\nTC 350, KM 130, KMM 159\n\nVerse 1\nUănh jŭm bri he geh âk ngăn bunuyh, gŭ khĭt ôm krit mƀât tâm nau tih, khân păng mra roh klăk klêm.\nTrong ngo klĕng mâu saơ nau ang ôh, mra roh rai lêk tâm nau khĭt ôm, gŭ tâm n'gar ŭnh mro mrăng, gŭ tâm n'gar ŭnh mro mrăng.\n\nChorus\nGeh âk râk bunuyh bunun khĭt roh rai, Khĭt roh tâm nau ngo klĕng.\nGeh âk nuyh khĭt roh rai. Geh âk bunuyh khĭt roh rai.\n\nVerse 2\nƠ Kôranh Brah, hên mra tông bâr May, hăn mbơh nau mhe mhan May lam ntŭk, ăn Brah Huêng Ueh ma hên.\nĂn hên gĭt yỗ lĕ phung rêh-ni, nti lah ma phung iăng tâm nau tih, yor lah mông mra dăch lôch, yor lah mông mra dăch lôch.\n\nChorus\nGeh âk râk bunuyh bunun khĭt roh rai, Khĭt roh tâm nau ngo klĕng.\nGeh âk nuyh khĭt roh rai. Geh âk bunuyh khĭt roh rai.\n\nVerse 3\nNar nchrat ang Kôranh Brah dăch tât jêh, hôm ƀât lât Păng mra văch jŭr đŏng, nar đăp mpăn mra gơnh tât.\nɃiă lah, ê lor tât nar maak nĕ, mbơh hom nau mhe mhan aơ lam ntŭk, jă bu sĭt chroh ma Păng, jă bu sĭt chroh ma Păng.\n\nChorus\nGeh âk râk bunuyh bunun khĭt roh rai, Khĭt roh tâm nau ngo klĕng.\nGeh âk nuyh khĭt roh rai. Geh âk bunuyh khĭt roh rai.\n\nVerse 4\nÂk rmưn rsen phung bunuyh mra chah rai, khân păng gŭ dăch mpông sâng n'gar ŭnh, bu mâu dơi hăn rklaih ôh.\nKôranh Brah ơi, ăn gâp sơm săk jăn, hăn mbơh nau May yỗ ma khân păng, ê lor khân păng roh hêng, ê lor khân păng roh hêng.\n\nChorus\nGeh âk râk bunuyh bunun khĭt roh rai, Khĭt roh tâm nau ngo klĕng.\nGeh âk nuyh khĭt roh rai. Geh âk bunuyh khĭt roh rai.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0093", "title": "MBAH NÂM NTŬK NGAI VÊCH NGĂN", "song_number": "93", "lyrics": "MBAH NÂM NTŬK NGAI VÊCH NGĂN\n\nTC 355, KM 155, KMM 163\n\nVerse 1\nMbah ntŭk ngai vêch ngăn, gâp mra hăn, gâp mra hăn, ntŭk ngai bu ê mâp hăn mbơh ôh.\nGeh rmưn rbăn bu nuyh ê mâp gĭt nau Yê-su, gâp hăn mbơh nau mhe mhan ueh aơ.\n\nChorus\nMbah ntŭk ngai, ngai vêch ngăn, gâp mra hăn, gâp mra hăn.\nLam neh ntu, lĕ neh ntu. Mbơh ăn gĭt nau Yê-su.\n\nVerse 2\nMbah ntŭk jêr hâu ngăn, Păng kuăl gâp, ăn gâp hăn, lơi chrê ma ntŭk jêr, mâu lah nơih.\nNeh ntu lah ma gâp jêng bunuyh rluk hăn mblêng dơm, mâu mphar, gay ŭch ƀư maak Kôranh Brah.\n\nChorus\nMbah ntŭk ngai, ngai vêch ngăn, gâp mra hăn, gâp mra hăn.\nLam neh ntu, lĕ neh ntu. Mbơh ăn gĭt nau Yê-su.\n\nVerse 3\nGeh phung biăp lĕ roh, Kôranh Brah ŭch gay djôt sĭt, khân păng gŭ iăt bâr Nơm Tâm Rklaih.\nNjuăl gâp hăn rgum lơi lĕ khân păng lam neh ntu, djôt leo khân păng sĭt ma Kôranh Brah.\n\nChorus\nMbah ntŭk ngai, ngai vêch ngăn, gâp mra hăn, gâp mra hăn.\nLam neh ntu, lĕ neh ntu. Mbơh ăn gĭt nau Yê-su.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0094", "title": "GÂP ĐĂ AY MAY HĂN SENG BUNUYH", "song_number": "94", "lyrics": "GÂP ĐĂ AY MAY HĂN SENG BUNUYH\n\nTC 357, KM 188, KMM 221\n\nVerse 1\nGâp đă ay may hăn seng bu-nuyh, hăn seng bu-nuyh hăn seng bu-nuyh.\nGâp đă ay may hăn seng bu-nuyh, lah ay may tĭng gâp, lah ay may tĭng gâp, lah ay may tĭng gâp.\nGâp đă ay may hăn seng bu-nuyh, lah ay may tĭng gâp.\n\nVerse 2\nIăt bâr Brah Ndu, mbơh sơm ăp nar, mbơh sơm ăp nar,\nIăt bâr Brah Ndu, mbơh sơm ăp nar, gay may văch ma toyh, gay may văch ma toyh, gay may văch ma toyh.\nIăt bâr Brah Ndu, mbơh sơm ăp nar, gay may văch ma toyh.\n\nVerse 3\nIăt Yê-su kuăl: \"Văch hom ma gâp, văch hom ma gâp\".\nIăt Yê-su kuăl: \"văch hom ma gâp, gay ma ndjoh n'hâm suan, gay ma ndjoh n'hâm suan, gay ma ndjoh n'hâm suan\".\nIăt Yê-su kuăl: \"Văch hom ma gâp, gay ma ndjoh n'hâm suan\".\n\nVerse 4\nUănh nau gâp ngơi, jêh ri mbơh sơm, jêh ri mbơh sơm.\nUănh nau gâp ngơi, jêh ri mbơh sơm, gay may gĭt nau gâp, ay may gĭt nau gâp, gay may gĭt nau gâp.\nUănh nau gâp ngơi, jêh ri mbơh sơm, gay may gĭt nau gâp.\n", "category": "Nsong mbơh nau Yê-su", "language": "Bunong"}, {"local_id": "nau-mpro-0095", "title": "YÊ-SU RŎNG GÂP", "song_number": "95", "lyrics": "YÊ-SU RŎNG GÂP\n\nTC 363, KM 83, KMM 168\n\nVerse 1\nYê-su rŏng gâp, gâp gĭt ngăn. Ndrom sam-ƀŭt Brah Ndu lah jêh,\nphung kon se jễ jêng kon Păng, khân ôbăl hưt, ƀiă lah Păng ktang.\n\nChorus\nBrah Yê-su rŏng gâp, Brah Yê-su rŏng gâp.\nBrah Yê-su rŏng gâp, sam-ƀŭt Brah Ndu Lah ngăn.\n\nVerse 2\nYê-su rŏng gâp, tât Păng khĭt. Ŭch pơk mpông sâng tâm Ƀon Ueh.\nPăng mra rao lĕ nau tih gâp, ăn gâp lăp tâm Ƀon Ueh Păng.\n\nChorus\nBrah Yê-su rŏng gâp, Brah Yê-su rŏng gâp.\nBrah Yê-su rŏng gâp, sam-ƀŭt Brah Ndu Lah ngăn.\n\nVerse 3\nYê-su rŏng gâp, Păng ŭch gŭ. Ndrel ma gâp ăp nar ƀa-ƀơ.\nLah gâp rŏng ma Păng tât khĭt, Păng mra leo gâp tât ta klơ.\n\nChorus\nBrah Yê-su rŏng gâp, Brah Yê-su rŏng gâp.\nBrah Yê-su rŏng gâp, sam-ƀŭt Brah Ndu Lah ngăn.\n\nVerse 4\nGâp ŭch nkoch bri nau ueh aơ, ăn lĕ rngôch bunuyh lơi nau tih.\nMbu nâm văch chroh ma Yê-su, Păng rao ro ma mham khlay Păng.\n\nChorus\nBrah Yê-su rŏng gâp, Brah Yê-su rŏng gâp.\nBrah Yê-su rŏng gâp, sam-ƀŭt Brah Ndu Lah ngăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0096", "title": "GÂP GEH NAU MPRƠ YÊ-SU HŎ ĂN JÊH", "song_number": "96", "lyrics": "GÂP GEH NAU MPRƠ YÊ-SU HŎ ĂN JÊH\n\nKM 84, KMM 249\n\nVerse 1\nGâp geh nau mprơ Yê-su hŏ ăn jêh, nau mprơ aơ jŭr bah klơ trôk.\nMâu hŏ mâp geh nau mprơ ueh kơt aơ ôh, Păng jêng nau mprơ ueh maak ngăn.\n\nChorus\nTâm nuih n'hâm gâp geh nau mprơ ueh ngăn, geh nau mprơ maak răm ngăn, văch jŭr tă bah klơ trôk.\nTâm nuih n'hâm gâp geh nau mprơ ueh ngăn, geh nau mprơ bêng ma nau n'hao nuih.\n\nVerse 2\nGâp rŏng Krist Nơm khĭt ta si tâm rkăng, lĕ nau tih gâp Păng mƀăr ngai.\nPăng prăp tâm nuih n'hâm gâp nau mprơ ueh maak, Păng gŭ tâm nuih n'hâm mro mrăng.\n\nChorus\nTâm nuih n'hâm gâp geh nau mprơ ueh ngăn, geh nau mprơ maak răm ngăn, văch jŭr tă bah klơ trôk.\nTâm nuih n'hâm gâp geh nau mprơ ueh ngăn, geh nau mprơ bêng ma nau n'hao nuih.\n\nVerse 3\nNau mprơ ueh nĕ mâu dơi rai yot ôh, gâp mra mprơ n'hanh phung Tông mpăr.\nNau mprơ ueh aơ jêng nau mprơ maak ngăn ngên, lĕ kon nuyh khân păng mra mprơ.\n\nChorus\nTâm nuih n'hâm gâp geh nau mprơ ueh ngăn, geh nau mprơ maak răm ngăn, văch jŭr tă bah klơ trôk.\nTâm nuih n'hâm gâp geh nau mprơ ueh ngăn, geh nau mprơ bêng ma nau n'hao nuih.\n", "category": "Kon se druh ndăm munh", "language": "Bunong"}, {"local_id": "nau-mpro-0097", "title": "GÂP RĂM RHƠN YOR LAH GEH MBỠ HE TA KLƠ", "song_number": "97", "lyrics": "GÂP RĂM RHƠN YOR LAH GEH MBỠ HE TA KLƠ\n\nTC 364, KM 85, KMM 169\n\nVerse 1\nGâp răm rhơn yor lah geh Mbỡ he ta klơ, ndrom sam-ƀŭt Păng nchih rŏng ma he hâu ngăn.\nGâp gĭt tâm rĭ Păng nchih âk nau khlay ngăn. Nau khlay nĕ jêng nau Yê-su Krist rŏng he.\n\nChorus\nGâp răm rhơn ngăn yor lah Yê-su rŏng, Yê-su rŏng gâp, Yê-su rŏng gâp.\nGâp răm rhơn ngăn yor lah Yê-su rŏng, Yê-su rŏng gâp ngăn ngên.\n\nVerse 2\nLah gâp chuêl Păng jêh ri nkhah du ƀah ngai, Yê-su rŏng gâp đŏng, mâu geh chuêl gâp ôh.\nɃrâk kah gĭt tâm tôr nau Yê-su rŏng gâp. Gâp plỡ sĭt ma Păng jêh ri mbơh nau tih.\n\nChorus\nGâp răm rhơn ngăn yor lah Yê-su rŏng, Yê-su rŏng gâp, Yê-su rŏng gâp.\nGâp răm rhơn ngăn yor lah Yê-su rŏng, Yê-su rŏng gâp ngăn ngên.\n\nVerse 3\nLah geh bu êng ôp, gâp mbơh ma Păng ro, tâm rnê ma Yê-su, jêh ri gâp lah đŏng.\nBrah Ndu ăn Huêng Păng tâm rnglăp đah huêng gâp. Yor ri gâp gĭt ngăn Yê-su rŏng rhơn gâp.\n\nChorus\nGâp răm rhơn ngăn yor lah Yê-su rŏng, Yê-su rŏng gâp, Yê-su rŏng gâp.\nGâp răm rhơn ngăn yor lah Yê-su rŏng, Yê-su rŏng gâp ngăn ngên.\n\nVerse 4\nGâp chroh ma Yê-su yor Păng Kôranh Brah Toyh, Păng ăn gŭ đêh rmên jêh ri nau đăp mpăn.\nBrah Mhĭk klach nchuăt du, Păng tăng bâr gâp lah: Yê-su rŏng gâp, jêh ri mprơh lơi Brah mhĭk.\n\nChorus\nGâp răm rhơn ngăn yor lah Yê-su rŏng, Yê-su rŏng gâp, Yê-su rŏng gâp.\nGâp răm rhơn ngăn yor lah Yê-su rŏng, Yê-su rŏng gâp ngăn ngên.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0098", "title": "YÊ-SU JÊNG RMĂK UEH NJŬN LEO HÊN", "song_number": "98", "lyrics": "YÊ-SU JÊNG RMĂK UEH NJŬN LEO HÊN\n\nTC 266, KM 86, KMM 167\n\nVerse 1\nYê-su jêng Rmăk Ueh, njŭn leo hên, hên ŭch May chiă uănh ƀa-ƀơ.\nMay chiăp hên tâm ntŭk âk gỡ nse. May nkra ngih ueh ăn hên rlu.\nMât ton Yê-su, mât ton Yê-su, May tâm chuai hên jêng ndơ May.\nMât ton Yê-su mât ton Yê-su, May tâm chuai hên jêng ndơ May.\n\nVerse 2\nHên jêng ndơ May jêh, dăn kơl hên, ăn May chiă uănh lĕ trong hên.\nNjrăng phung biăp May klach lah roh hêt, joi hên lah kah huĭk trong May.\nMât ton Yê-su mât ton Yê-su, iăt hom, lah hên kuăl mbơh sơm.\nMât ton Yê-su mât ton Yê-su, iăt hom, lah hên kuăl mbơh sơm.\n\nVerse 3\nMay ntênh jêh, May mra rom phung hên, bunuyh o-ach mâu lah tih mhĭk.\nMay ŭch yỗ ngăn gay tâm rklaih hên, May ŭch ăn hên jêng kon me.\nMât ton Yê-su mât ton Yê-su, bơh druh ndăm sĭt gơnh ma May.\nMât ton Yê-su mât ton Yê-su, bơh druh ndăm sĭt gơnh ma May.\n\nVerse 4\nƠ druh ndăm, kônh va, sau se he, hăn gơnh oi tĭng joi Yê-su.\nKnŏng Păng dơm jêng Kôranh Nơm Rklaih he, ăn he rŏng ma Păng dŭt n'hâm.\nMât ton Yê-su mât ton Yê-su, May rklaih jêh lĕ nau tih hên.\nMât ton Yê-su mât ton Yê-su, May rklaih jêh lĕ nau tih hên.\n", "category": "Kon se druh ndăm mprơ", "language": "Bunong"}, {"local_id": "nau-mpro-0099", "title": "GÂP JÊNG BIĂP KÔRANH BRAH", "song_number": "99", "lyrics": "GÂP JÊNG BIĂP KÔRANH BRAH\n\nKMM 263\n\nVerse 1\nNtŭk gỡ nse, gâp rlu ta ntŭk rdah, ueh lăng Păng njŭn gâp.\nDôl tŭp jâng nar, gâp ŭch tĭng ndỗ têl Păng.\nNtŭk gỡ ueh jêng ntŭk rlu, ueh lăng phung biăp Kôranh Brah Păng jêng Rmăk gâp.\n\nVerse 2\nNtŭk dak rsang, ntŭk gỡ nse Păng njŭn gâp Kôranh Brah Nơm hăn ndrel gâp.\nTâm yôk prêh ri. Tâm ndrêch ueh ri. Mâu klach ôh, Kôranh Brah Nơm hăn ndrel gâp.\n\nVerse 3\nDôl klong măng, lĕ trong hăn, ăt chuat đŏng, geh Păng njŭn leo.\nMâu klach ôh, geh Păng njŭn leo.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0100", "title": "BAR ĐAH TI GÂP JỄ KĐÔI LĔ", "song_number": "100", "lyrics": "BAR ĐAH TI GÂP JỄ KĐÔI LĔ\n\nTC 370, KMM 170\n\nVerse 1\nBar đah ti gâp jễ kđôi lĕ, gâp ŭch srôih pah kan,\nDŏng ti gâp tâm kan kloh ueh, tĭng nâm Kôranh Brah ŭch.\nBar đah ti, lĕ nuih n'hâm, gâp nhhơr ma Yê-su.\n\nVerse 2\nBar đah jâng gâp jễ kđôi lĕ, ŭch hăn lam ăp ntŭk,\nSâm njŭn gâp tâm trong Păng Nơm, tât tâm Ƀon chrat ang.\nBar đah jâng, lĕ nuih n'hâm, gâp nhhơr ma Yê-su.\n\nVerse 3\nGâp geh trôm mbung huêt kđôi lĕ, ŭch Yê-su dơi dŏng\nNar măng mbơh nau mhe mhan ueh, ma lĕ rngôch bu-nuyh.\nLĕ trôm mbung, lĕ nuih n'hâm, gâp nhhơr ma Yê-su.\n\nVerse 4\nGâp geh trôm tôr huêt kđôi lĕ, kâp iăt nau Păng nti,\nKâp ndjôt prăp Nau Brah Ndu Ngơi, mĭn ma Păng ăp nar.\nLĕ trôm tôr, lĕ nuih n'hâm, gâp nhhơr ma Yê-su.\n", "category": "Kon se druh ndăm munh", "language": "Bunong"}, {"local_id": "nau-mpro-0101", "title": "NAU RŎNG KHLAY NGĂN", "song_number": "101", "lyrics": "NAU RŎNG KHLAY NGĂN\n\nKM 138, KMM 65\n\nVerse 1\nBrah Ndu tâm mpơl nau Păng rŏng ngăn ma he. Ŭch rgâl lơi nau tih mhĭk jêng nau kloh ueh.\nPăng nkra trong nau he dơi tâm rnglăp đah Păng. Mâm ƀư nau rŏng khlay ngăn kơt aơ?\n\nChorus\nNau rŏng nau rŏng khlay ngăn, nau rŏng nau rŏng khlay ngăn.\nBrah Ndu tâm mpơl nau Păng rŏng ngăn ma he. Mâm ƀư nau rŏng khlay ngăn kơt aơ?\n\nVerse 2\nYê-su jêng nơm tâm chuai phung he dơm dam. Păng nhhơr săk nơm tât khĭt ta si tâm rkăng.\nNau Păng rŏng nây, mâu geh nau êng dơi ban. Nau rŏng, Păng dơi tâm chuai he ngăn.\n\nChorus\nNau rŏng nau rŏng khlay ngăn, nau rŏng nau rŏng khlay ngăn.\nBrah Ndu tâm mpơl nau Păng rŏng ngăn ma he. Mâm ƀư nau rŏng khlay ngăn kơt aơ?\n\nVerse 3\nYor he ƀư tih, du der đah trong Brah Ndu, Mbỡ he ăn Kon Păng nơm khĭt luh mham khlay.\nŬch chuai he nơm jêng dĭk mâu geh khlay ôh. He rvê ma nau Păng rŏng ma he.\n\nChorus\nNau rŏng nau rŏng khlay ngăn, nau rŏng nau rŏng khlay ngăn.\nBrah Ndu tâm mpơl nau Păng rŏng ngăn ma he. Mâm ƀư nau rŏng khlay ngăn kơt aơ?\n\nVerse 4\nAbaơ ri Păng ăn he jêng kon Păng ngăn ngên. Păng kơp he khlay, ăn he jêng bunuyh kon me.\nHe mâu hôm nkhah du gŭ ngai đah Păng ôh. Nau yỗ, Păng ut ra-u rom he.\n\nChorus\nNau rŏng nau rŏng khlay ngăn, nau rŏng nau rŏng khlay ngăn.\nBrah Ndu tâm mpơl nau Păng rŏng ngăn ma he. Mâm ƀư nau rŏng khlay ngăn kơt aơ?\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0102", "title": "LAH BU ŬCH NDƠM AY MAY", "song_number": "102", "lyrics": "LAH BU ŬCH NDƠM AY MAY\n\nTC 376, KM 88, KMM 173\n\nVerse 1\nLah bu ŭch ndơm ay may, lơi iăt nau păng ôh.\nɃiă lah hăn ta Yê-su, Păng dơi kơl ay may.\nLơi lĕ nau tih ay may, dăn nau Brah Yê-su.\nUănh ta Păng ƀa-ƀơ hŏ, Păng kơl ay may ngăn.\n\nChorus\nDăn ma Yê-su kơl ay may. Nau Brah Păng dơi mprơh Brah mhĭk.\nPăng ăn ay may gŭ đăp mpăn. Mbơh sơm ƀa-ƀơ ăp nar.\n\nVerse 2\nLơi tĭng ôh nau bunuyh tih, lơi tâm rnglăp đah păng.\nKlach lah păng ƀư tih may, ran ma Yê-su hŏ.\nLơi mĭn ma nau ƀỡ ƀơch, Păng mra kơl ay may.\nUănh ƀa-ƀơ ta Yê-su, Păng kơl, ay may ngăn.\n\nChorus\nDăn ma Yê-su kơl ay may. Nau Brah Păng dơi mprơh Brah mhĭk.\nPăng ăn ay may gŭ đăp mpăn. Mbơh sơm ƀa-ƀơ ăp nar.\n", "category": "Kon se druh ndăm mprơ", "language": "Bunong"}, {"local_id": "nau-mpro-0103", "title": "MÂU HÔM CHA LƠI", "song_number": "103", "lyrics": "MÂU HÔM CHA LƠI\n\nTC 29, KM 124, KMM 17\n\nVerse 1\nGâp hŏ tâm di jêh tĭng ndỗ nau Yê-su. Gâp hŏ tâm di jêh tĭng ndỗ nau Yê-su\nGâp hŏ tâm di jêh tĭng ndỗ nau Yê-su. Mâu hôm cha-lơi. Mâu hôm cha-lơi.\n\nVerse 2\nPa kơi nau ngo klĕng, pa năp nau nchrat ang. Pa kơi nau ngo klĕng, pa năp nau nchrat ang.\nPa kơi nau ngo klĕng, pa năp nau nchrat ang. Mâu hôm cha-lơi. Mâu hôm cha-lơi.\n\nVerse 3\nLah bu cha-lơi Păng. gâp ăt tĭng ndỗ mro. Lah bu cha-lơi Păng, gâp ăt tĭng ndỗ mro.\nLah bu cha-lơi Păng, gâp ăt tĭng ndỗ mro. Mâu hôm cha-lơi. Mâu hôm cha-lơi.\n\nVerse 4\nÔ ueh lăng hâu ngăn hăn n'hêl ma Yê-su. Ô ueh lăng hâu ngăn hăn n'hêl ma Yê-su.\nÔ ueh lăng hâu ngăn hăn n'hêl ma Yê-su. Mâu hôm cha-lơi. Mâu hôm cha-lơi.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0104", "title": "TĬNG NDỖ GÂP", "song_number": "104", "lyrics": "TĬNG NDỖ GÂP\n\nTC 388, KM 167, KMM 176\n\nVerse 1\nGâp tăng Kôranh Brah he Yê-su lah. Tĭng ndỗ Gâp, tĭng ndỗ gâp, tĭng ndỗ Gâp.\nGâp tăng Păng gŭ kuăl he ăp nar: Tĭng ndỗ Gâp, tĭng ndỗ Gâp, tĭng ndỗ Gâp.\nYor May gâp chuat hăn tâm trong jêr. Yor may Gâp nhhơr lĕ nau rêh Gâp.\nDơn jêh nau khĭt ta si tâm rkăng. Tĭng ndỗ Gâp, tĭng ndỗ Gâp, tĭng ndỗ Gâp.\n\nVerse 2\nPăng lah mra yỗ an nau tih may. Tĭng ndỗ Gâp, tĭng ndỗ gâp, tĭng ndỗ Gâp.\nTâm chuai may bơh nau tih ăp ntil. Tĭng ndỗ Gâp, tĭng ndỗ Gâp, tĭng ndỗ Gâp.\nTâm nau rêh may Gâp mra jêng Kôranh. Brah Ndu mra jŭn leo trong ma may.\nJêh ri ƀư maak ma may n'ho ro. Tĭng ndỗ Gâp, tĭng ndỗ Gâp, tĭng ndỗ Gâp.\n\nVerse 3\nJao Gâp lĕ ndô ndơ jâk may anh. Tĭng ndỗ Gâp, tĭng ndỗ gâp, tĭng ndỗ Gâp.\nGâp mra kơl may ăn ndjoh n'hâm suan. Tĭng ndỗ Gâp, tĭng ndỗ Gâp, tĭng ndỗ Gâp.\nLơi klach ôh. Ti Gâp king may jêh. May nsing ma Gâp ăp năm, ăp nar.\nTi Gâp mra jut an dak măt may. Tĭng ndỗ Gâp, tĭng ndỗ Gâp, tĭng ndỗ Gâp.\n", "category": "Kon se druh ndăm mprơ", "language": "Bunong"}, {"local_id": "nau-mpro-0105", "title": "TĬNG NDỖ YÊ-SU", "song_number": "105", "lyrics": "TĬNG NDỖ YÊ-SU\n\nTC 389\n\nVerse 1\nTĭng ndỗ Yê-su, gâp ŭch tĭng ndỗ Yê-su.\nMbah gâp hăn, mbah gâp gŭ, tĭng ndỗ Yê-su mro.\nTĭng ndỗ Yê-su, gâp ŭch tĭng ndỗ Yê-su.\nMbah ntŭk Păng njŭn gâp, gâp ŭch tĭng ndỗ Păng mro.\n", "category": "Kon se druh ndăm munh", "language": "Bunong"}, {"local_id": "nau-mpro-0106", "title": "UEH MAAK NGĂN NAU TÂM KOL", "song_number": "106", "lyrics": "UEH MAAK NGĂN NAU TÂM KOL\n\nTC 402, KM 89, KMM 177\n\nVerse 1\nUeh maak ngăn nau tâm kol kăl e, Brah Ndu nơm tâm kol lor.\nTâm n'gar Ê-đen ndray tât a-ƀaơ, bar hê tâm rnglăp du nglay.\nNting săk Kôranh Brah Ndu nơm njêng nguay, tâm rŏng ndrel kŏ tât khĭt.\nKon sau bĭk âk kơt choih kơt mănh, gay ƀư maak ma Brah Ndu.\n\nVerse 2\nTa ƀon Ka-na kăl e tâm kol, Kon Brah Ndu hăn rƀŭn nsum.\nSông sa ƀư maak ma ur sai mhe, lĕ rngôch maak ndrel tâm ngih.\nDăn ma Brah Ndu gŭ ndrel khân păng, ăn nau ueh lăng bar hê.\nĂn kah gĭt lĕ nau khân păng ton gay maak răm ma Yê-su.\n\nVerse 3\nNdrom sam-ƀŭt nau Brah Ndu hŏ nchih, Brah Huêng Ueh nti n'hêl jêh.\nSai ma ur jêng du nglay săk jăn, ăn geh nau rŏng đăp rmên.\nKơt Brah Krist rŏng phung chroh ma păng, sai ma ur jêng nguay dơm.\nTâm kơl, tâm rŏng tât lôch nau rêh, ƀư maak ma Brah Huêng Ueh.\n", "category": "Nau tâm kol ur sai", "language": "Bunong"}, {"local_id": "nau-mpro-0107", "title": "MAAK YƠH, BRAH NDU TÂM RNGLĂP", "song_number": "107", "lyrics": "MAAK YƠH, BRAH NDU TÂM RNGLĂP\n\nTC 407, KM 134, KMM 178\n\nVerse 1\nMaak yơh, Brah Ndu tâm rnglăp. Nuih n'hâm he tâm nau rŏng.\nTâm dơh tâm dăch lĕ mpôl phung chroh, nâm bu he gŭ n'hanh Păng.\n\nVerse 2\nTa năp sưng Mbỡ ta klơ. He vay tâm rƀŭn mbơh sơm.\nTâm rnglăp jêng nguay, tâm kơl du ai, yor he jêng du nglay săk.\n\nVerse 3\nTâm juh nau he klân rvê. Tâm kơl mbu nâm rêh ni.\nMbu nâm tâm he mâp geh nau rngot, he nhĭm rngot ndrel ma Păng.\n\nVerse 4\nLah he tâm nkhah gŭ ngai. He vay klâng ngăn ƀa-ƀơ.\nɃiă lah he hôm tâm rnglăp nuih n'hâm, kâp gân nar he mâp tay.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0108", "title": "KÔRANH BRAH MÂT MƠH HE", "song_number": "108", "lyrics": "KÔRANH BRAH MÂT MƠH HE\n\nTC 408, KM 90, KMM 179\n\nVerse 1\nDăn Kôranh Brah gŭ ndrel phung he ƀa-ƀơ,\nNjŭn leo trong, chiă uănh nau rêh he, Păng mât mơh tâm ban phung biăp Păng.\nMât mơh tât nar he tâm mâp đŏng taơ.\n\nChorus\nKôranh Brah mât he, Kôranh Brah mât mơh he, tât nar he mâp Brah Yê-su.\nKôranh Brah mât he Kôranh Brah mât mơh he, mât mơh tât nar he tâm mâp đŏng taơ.\n\nVerse 2\nDăn Kôranh Brah gŭ ndrel phung he ƀa-ƀơ,\nKing he đah nau brah mhĭk lơh he, siăm ăp nar ma Nau Păng Ngơi khlay.\nMât mơh tât nar he tâm mâp đŏng taơ.\n\nChorus\nKôranh Brah mât he, Kôranh Brah mât mơh he, tât nar he mâp Brah Yê-su.\nKôranh Brah mât he Kôranh Brah mât mơh he, mât mơh tât nar he tâm mâp đŏng taơ.\nA-MEN.\n", "category": "Nau mprơ ê lor nkhah du", "language": "Bunong"}, {"local_id": "nau-mpro-0109", "title": "MÂT TON PĂNG", "song_number": "109", "lyrics": "MÂT TON PĂNG\n\nTC 413\n\nVerse 1\nMprơ hom tâm rnê Amoh Yê-su, chon mon păn mbah ma Păng,\nchon mon păn mbah ma Păng. Tâm rnê ma Păng jêng Kôranh toyh ngăn.\n\nChorus\nMât ton Păng. Mât ton, mât ton, mât ton tâm rnê Kô-ranh Brah toyh ngăn.\nMât ton, tâm rnê Kôranh Brah toyh ngăn.\n\nVerse 2\nƠ phung klaih ngăn tă bah Brah Mhĭk, Brah Ndu lĕ tâm rklaih yơh,\nBrah Ndu lĕ tâm rklaih yơh. Mprơ munh tâm rnê lah ueh ma Păng.\n\nChorus\nMât ton Păng. Mât ton, mât ton, mât ton tâm rnê Kô-ranh Brah toyh ngăn.\nMât ton, tâm rnê Kôranh Brah toyh ngăn.\n\nVerse 3\nHơi lĕ bu-nuyh ta neh ntu aơ, sĭt hom ma Kôranh Brah toyh,\nsĭt hom ma Kôranh Brah toyh. Yor lah Păng jêng Hađăch toyh dŭt n'hâm.\n\nChorus\nMât ton Păng. Mât ton, mât ton, mât ton tâm rnê Kô-ranh Brah toyh ngăn.\nMât ton, tâm rnê Kôranh Brah toyh ngăn.\n\nVerse 4\nHơi lĕ bu-nuyh tâm lam n'gor bri, chon mon tâm dâng jâng Păng,\nchon mon tâm dâng jâng Păng. Tâm rnê ƀa-ƀơ ma Brah Yê-su.\n\nChorus\nMât ton Păng. Mât ton, mât ton, mât ton tâm rnê Kô-ranh Brah toyh ngăn.\nMât ton, tâm rnê Kôranh Brah toyh ngăn.\n", "category": "Nau mprơ prăp ma phung kâp mprơ", "language": "Bunong"}, {"local_id": "nau-mpro-0110", "title": "NAU YỖ YÊ-SU KRIST KHLAY NGĂN", "song_number": "110", "lyrics": "NAU YỖ YÊ-SU KRIST KHLAY NGĂN\n\nTC 415, KM 154, KMM 180\n\nVerse 1\nNau yỗ Yê-su Krist khlay ngăn, toyh lơn ma lĕ nau tih.\nMâm dơi mpiăt gâp dơi rblang Păng, ăn nau tâm rnê mât ton.\nPăng sŏk lĕ jêh nau jâk gâp. Ăn huêng gâp jêng kon me, yor lah nau yỗ Yê-su Krist khlay ngăn tât ma gâp.\n\nChorus\nƠ khlay ngăn ngên nau yỗ Păng. toyh kuăng hâu ngăn.\nKhlay ngăn nau yỗ Kôranh Brah Yê-su ma gâp, ăn tŏng ma gâp.\nToyh lơn ma lĕ rngôch nau tih mhĭk blem gâp. Toyh ma nau ƀai jêh ri lơn nau janh.\nƠ mprơ hom, tâm r-nê ma Amoh khlay Yê-su, mât ton Păng.\n\nVerse 2\nNau yỗ Yê-su Krist khlay ngăn, ăn jêh ma lĕ rngôch bunuyh.\nMa păng gâp geh nau tâm chuai, klaih jêh bơh nau tih mhĭk.\nPăng rklaih jêh lĕ rngôch rse rvăk. Gay ăn gâp gŭ đăp mpăn, yor lah nau yỗ Yê-su Krist khlay ngăn an ma gâp.\n\nChorus\nƠ khlay ngăn ngên nau yỗ Păng. toyh kuăng hâu ngăn.\nKhlay ngăn nau yỗ Kôranh Brah Yê-su ma gâp, ăn tŏng ma gâp.\nToyh lơn ma lĕ rngôch nau tih mhĭk blem gâp. Toyh ma nau ƀai jêh ri lơn nau janh.\nƠ mprơ hom, tâm r-nê ma Amoh khlay Yê-su, mât ton Păng.\nA-MEN.\n", "category": "Nau mprơ prăp ma phung kâp mprơ", "language": "Bunong"}, {"local_id": "nau-mpro-0111", "title": "NAU NGƠI UEH REH NGĂN NGÊN", "song_number": "111", "lyrics": "NAU NGƠI UEH REH NGĂN NGÊN\n\nTC 154, KM 111, KMM 81\n\nVerse 1\nMprơ nau Brah Ndu ma gâp ƀa-ƀơ Nau Ngơi ueh reh ngăn ngên.\nGâp ŭch iăt ndrom sam-ƀŭt nây mro, Nau Ngơi ueh reh ngăn ngên.\nPăng tâm mpơl nau Brah Ndu. Păng nti lah nau vay gŭ ngau.\n\nChorus\nNau Ngơi ueh ngăn, Nau Ngơi khlay ngăn, Nau Ngơi ueh reh ngăn ngên.\n\nVerse 2\nYê-su lah ma lĕ rngôch bu-nuyh: Nau Ngơi ueh reh ngăn ngên.\nIăt bâr ngơi ueh Păng kuăl ma may, Nau Ngơi ueh reh ngăn ngên.\nPăng ŭch yỗ nau tih may. Jut rao lơi ma mham khlay Păng.\n\nChorus\nNau Ngơi ueh ngăn, Nau Ngơi khlay ngăn, Nau Ngơi ueh reh ngăn ngên.\n\nVerse 3\nMbơh nau mhe mhan Yê-su ma bu, Nau Ngơi ueh reh ngăn ngên.\nĂn me mbỡ ay may chroh ma Păng, Nau Ngơi ueh reh ngăn ngên.\nYê-su jêng nơm rklaih he. Mâu geh nơm êng dơi kơl he.\n\nChorus\nNau Ngơi ueh ngăn, Nau Ngơi khlay ngăn, Nau Ngơi ueh reh ngăn ngên.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0112", "title": "NAU BRAH NDU NGƠI TÂM BAN ŬNH KAĐEN", "song_number": "112", "lyrics": "NAU BRAH NDU NGƠI TÂM BAN ŬNH KAĐEN\n\nTC 152, KM 32, KMM 64\n\nVerse 1\nNau Brah Ndu Ngơi tâm ban ŭnh kađen, sol jâng he klach geh chêh.\nJêng tu nau ueh jŭr văch bơh trôk, nâm dak hoch kêng meng trong.\n\nVerse 2\nMpa khlay siăm huêng ăn he gŭ rêh, jêng Ma-na văch bơh klơ.\nNdơ ntĭm trong chuat njŭn tât klơ trôk, gŭ tâm Ƀon Brah Ndu Nơm.\n\nVerse 3\nNau Brah Ndu Ngơi jêng nau di ngăn, rbăn rmưn năm hôm gŭ ueh.\nTâm sam-ƀŭt êng mâu geh saơ ôh, trong hăn lăp Ƀon Ueh Uĭn.\n\nVerse 4\nDăn Mbỡ sol ang kơl gâp dơi uănh, ăn gĭt rbăng nau May Ngơi.\nDăn Brah Huêng Ueh ƀư rdỡ nuih n'hâm, ăn dơi dơn nau May nti.\nA-MEN.\n", "category": "Nau Brah Ndu Ngơi", "language": "Bunong"}, {"local_id": "nau-mpro-0113", "title": "SIĂM GÂP ƀĂ PIĂNG LET RÊH", "song_number": "113", "lyrics": "SIĂM GÂP ƀĂ PIĂNG LET RÊH\n\nTC 29, KM 124, KMM 17\n\nVerse 1\nSiăm gâp ƀă piăng let rêh, ơ Yê-su ơi.\nMay pă jêh piăng let ta kơh dak mƀŭt dơh.\nTâm ndrom sam-ƀŭt May, gâp ŭch gĭt năl May.\nNuih n'hâm gâp ji ngot ma May, Yê-su ơi.\n\nVerse 2\nĂn gâp gĭt rbăng nau May, ơ Yê-su ơi.\nNâm bu May rblang kăl e ta Ga-li-lê.\nPô ri luh bơh nau ngo, lĕ rse rvăk klaih.\nĂn nau đăp mpăn ma gâp, ơ Yê-su ơi.\n\nVerse 3\nNti gâp nhhơr săk jăn ma May, ơ Yê-su.\nKơt May nti oh mon May ta Ga-li-lê.\nGâp ŭch pă piăng let rêh May ma lĕ bunuyh.\nGay gâp dơi ƀư răm ma May, Yê-su ơi.\nA-MEN.\n", "category": "Nau Brah Ndu Ngơi", "language": "Bunong"}, {"local_id": "nau-mpro-0114", "title": "NĐAƠ, NAR AO JÊH RI ÔI TAƠ", "song_number": "114", "lyrics": "NĐAƠ, NAR AO JÊH RI ÔI TAƠ\n\nTC 77; KM 187, KMM 46\n\nVerse 1\nNđaơ, nar aơ jêh ri ôi taơ, Yê-su mâu geh rgâl ôh.\nLĕ neh ntu dơi rlau lôch ngăn, ƀiă lah Păng hôm ƀa-ƀơ.\nMât ton ma Yê-su, mât ton ma Yê-su,\nLĕ mpô mpa lôch, ƀiă lah Păng ăt hôm. Mât ton ma Yê-su.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0115", "title": "RI GÔ-GÔ-THA", "song_number": "115", "lyrics": "RI GÔ-GÔ-THA\n\nTC 195\n\nVerse 1\nRi Gô-gô-tha ngo klĕng dŭt n'hâm, ntŭk Yê-su sâm khĭt ăn ma gâp.\nTa Gô-gô-tha Păng nkhŭt mham khlay, ăn gâp rêh tay ta Ƀon Ueh Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0116", "title": "SI TÂM RKĂNG", "song_number": "116", "lyrics": "SI TÂM RKĂNG\n\nKM 182, KMM 215\n\nVerse 1\nSi tâm rkăng, si tâm rkăng, ntŭk gâp mhe saơ nau ang.\nYê-su mprơh lơi nau tih gâp du ngai.\nNtŭk nĕ gâp lăp chroh ma Amoh Kôranh Yê-su\nJêh ri tât a-ƀaơ gâp maak ƀa-ƀơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0117", "title": "GŬ RĂP JĂP", "song_number": "117", "lyrics": "GŬ RĂP JĂP\n\nTC 205\n\nVerse 1\nGŭ răp jăp gŭ răp jăp, lăp gŭ âm tâm ntŭk Yê-su.\nPăng nkŭm gâp, Păng nkŭm gâp, yor nau yỗ Mbỡ he Brah Ndu.\nBu ƀư ka-đôi lĕ, ŭch lơh ka-đôi lĕ, ăt Yê-su king n'gang gâp ngăn,\nMâu klach ôh. Mâu klach ôh, Brah Ndu n'hanh lĕ trong gâp hăn.\n", "category": "Nau munh gleh", "language": "Bunong"}, {"local_id": "nau-mpro-0118", "title": "CHUAT NGUAY NGUAY", "song_number": "118", "lyrics": "CHUAT NGUAY NGUAY\n\nTC 291\n\nVerse 1\nChuat nguay nguay, ndrel Yê-su, bu mâu dơi ƀư he ôh.\nChuat nguay nguay, tâm trong Păng, lăng săk jăn tât Ƀon klơ.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0119", "title": "JAO NAU RÊH HE", "song_number": "119", "lyrics": "JAO NAU RÊH HE\n\nTC 381, KM 160, KMM 191\n\nVerse 1\nJao nau rêh he ma Kôranh Yê-su. Mbu nâm chroh hăn pah kan hom.\nJao nau rêh he ma Kôranh Yê-su. Brah Ndu kơp he jêng kon Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0120", "title": "CHROH HOM MA BRAH YÊ-SU KRIST", "song_number": "120", "lyrics": "CHROH HOM MA BRAH YÊ-SU KRIST\n\nTC 440, KM 93, KMM 195\n\nVerse 1\nChroh hom ma Brah Yê-su Krist. Chroh hom ma Brah Yê-su Krist,\nchroh hom ma Brah Yê-su Krist, may mra klaih ngăn ngên.\n\nVerse 2\nIăt hom nau Brah Yê-su Krist. Iăt hom nau Brah Yê-su Krist,\niăt hom nau Brah Yê-su Krist, may mra klaih ngăn ngên.\n\nVerse 3\nMbơh sơm dăn ma Yê-su Krist. Mbơh sơm dăn ma Yê-su Krist,\nmbơh sơm dăn ma Yê-su Krist, may mra klaih ngăn ngên.\n\nVerse 4\nMbơh nau tih ma Yê-su Krist. Mbơh nau tih ma Yê-su Krist,\nmbơh nau tih ma Yê-su Krist, may mra klaih ngăn ngên.\n", "category": "Nau munh gleh", "language": "Bunong"}, {"local_id": "nau-mpro-0121", "title": "TOYH, TOYH TÂM BAN DAK VĂR", "song_number": "121", "lyrics": "TOYH, TOYH TÂM BAN DAK VĂR\n\nTC 442, KM 190, KMM 222\n\nVerse 1\nToyh, toyh tâm ban dak văr, prêh lơn, prêh lơn nâm bu trôk.\nJru, jru nâm bu dak mƀŭt, nau Yê-su rŏng ma gâp.\nGâp mâu jêng bunuyh khlay ôh, ăt Păng chiă uănh gâp mro mrăng.\nNau Păng Ngơi nti gâp, nau rŏng Păng tĭng ndỗ gâp tâm lam bri neh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0122", "title": "NUIH N'HÂM GÂP HÂK", "song_number": "122", "lyrics": "NUIH N'HÂM GÂP HÂK\n\nTC 444\n\nVerse 1\nNuih n'hâm gâp hâk, hâk, hâk, hâk, hâk maak ngăn ngên, Bên gŭ ndrel Păng, ueh lăng dŭt n'hâm.\nYor lah nau Brah Ndu yỗ gâp hâk maak ngăn ngên, bên gŭ ndrel Păng ƀa-ƀơ.\n\nVerse 2\nNau rêh gâp đăp, đăp, đăp, đăp, đăp mpăn ƀa-ƀơ. Ndơ Yê-su ăn dơm dam ma gâp.\nLah bu tâm lơh chiau meng, ăt gâp gŭ đăp mpăn, lăn tâm nau ueh ƀa-ƀơ.\n\nVerse 3\nGâp geh nau rêh, rêh, rêh, rêh, rêh n'ho ro yơh. Dơh gŭ ngau n'hanh Kôranh Brah ƀa-ƀơ.\nYê-su hŏ chuai jêh nau tih gâp ta neh ntu, bu mâu hôm dơi pit gâp.\n\nVerse 4\nÔ klak gâp djăng, djăng, djăng, djăng, djăng ndăng măng nar. Char Brah Ndu de hŏ rơm kăl e.\nTa nây mâu hôm nau rvê nâm bu ta neh ntu, rlu tâm Ƀon Ueh ƀa-ƀơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0123", "title": "LAH KHĬT TA OI MBAH MAY LEO HĂN", "song_number": "123", "lyrics": "LAH KHĬT TA OI MBAH MAY LEO HĂN\n\nTC 445\n\nVerse 1\nLah khĭt ta oi mbah may leo hăn. Ƀon Ueh, mâu lah ƀon mhĭk?\nNau rêh, nau khĭt ăt hôm mro mrăng, ăn may săch gơnh a-ƀaơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0124", "title": "RŎNG MA YÊ-SU NAR MĂNG", "song_number": "124", "lyrics": "RŎNG MA YÊ-SU NAR MĂNG\n\nTC 446, KM 95, KMM 197\n\nVerse 1\nRŏng ma Yê-su nar măng, rŏng âk lơn bơh a-ƀaơ.\nRŏng ma Yê-su ƀa-ƀơ, a-ƀaơ gâp ton n'hêl ngăn.\nRŏng ma Yê-su nar măng, rŏng âk lơn bơh a-ƀaơ, yor lah Păng rŏng gâp jêh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0125", "title": "YÊ-SU, KHLAY HÂU NGĂN AMOH PĂNG", "song_number": "125", "lyrics": "YÊ-SU, KHLAY HÂU NGĂN AMOH PĂNG\n\nTC 447\n\nVerse 1\nYê-su, khlay hâu ngăn Amoh Păng. Yê-su, ăt tâm ban mro mrăng.\nYê-su, jêng kloh ueh sŏng srăng. Ha-lê-lu-ya, gâp nhhơr nau rêh gâp ma Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0126", "title": "HƠI KÔRANH BRAH", "song_number": "126", "lyrics": "HƠI KÔRANH BRAH\n\nTC 451\n\nVerse 1\nHơi Kôranh Brah, gâp kâp May. Gơnh ơi lăp hom tâm gâp.\nƠ Yê-su, dăn May mât uănh tâm nuih n'hâm gâp aơ.\n", "category": "Nau munh gleh", "language": "Bunong"}, {"local_id": "nau-mpro-0127", "title": "HE SRÔIH HĂN NDREL", "song_number": "127", "lyrics": "HE SRÔIH HĂN NDREL\n\nTC 448\n\nVerse 1\nHe srôih hăn ndrel, trong r-hăt Kôranh Brah, lah bu nkhăng, lơi ta iăt nau păng ôh.\nSrôih hăn gay ma tât ntŭk ueh. Rkleh lĕ nau mhĭk blem neh ntu, gay dơi njŏ ndrel ntung si tâm r-kăng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0128", "title": "LƠI KLACH ÔH", "song_number": "128", "lyrics": "LƠI KLACH ÔH\n\nTC 450\n\nVerse 1\nLơi klach ôh, chroh ma Păng Lơi mĭn ma neh ntu, mâu ri may nơm.\nChroh rjăp! Uănh Kôranh Brah, tĭng ndỗ Păng! Păng mra ăn may lăp Ƀon Ueh.\n", "category": "Nau munh gleh", "language": "Bunong"}, {"local_id": "nau-mpro-0129", "title": "GŬ RĂP JĂP, RĂP JĂP", "song_number": "129", "lyrics": "GŬ RĂP JĂP, RĂP JĂP\n\nTC 453, KM 98, KMM 188\n\nVerse 1\nGŭ răp jăp, răp jăp, ăn he mbơh Nau Brah Ndu Ngơi.\nRăp jăp tâm kan he, răp jăp oi lă kan Kôranh Brah.\nGŭ răp jăp, răp jăp, lah bu ndơm lơi ta iăt ôh.\nMoh nau tât găp lĕ, he geh Yê-su n'hanh ăn may gŭ răp jăp ƀa-ƀơ.\n", "category": "Nau munh gleh", "language": "Bunong"}, {"local_id": "nau-mpro-0130", "title": "MÂT TON BRAH NDU, LĔ RNGÔCH", "song_number": "130", "lyrics": "MÂT TON BRAH NDU, LĔ RNGÔCH\n\nKM 104, KMM 230\n\nVerse 1\nMât ton Brah Ndu, lĕ rngôch phung kon se jễ, Kôranh Brah Ndu rŏng ay may.\nMât ton Brah Ndu, lĕ rngôch phung kon se jễ, Kôranh Brah Ndu rŏng ay may.\n\nVerse 2\nRŏng ma Brah Ndu, lĕ rngôch phung kon se jễ, Kôranh Brah Ndu rŏng ay may.\nRŏng ma Brah Ndu, lĕ rngôch phung kon se jễ, Kôranh Brah Ndu rŏng ay may.\n\nVerse 3\nPah kan ma Păng, lĕ rngôch phung kon se jễ, Kôranh Brah Ndu rŏng ay may.\nPah kan ma Păng, lĕ rngôch phung kon se jễ, Kôranh Brah Ndu rŏng ay may.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0131", "title": "PĂNG DOH LƠI RSE RVĂK BRAH MHĬK", "song_number": "131", "lyrics": "PĂNG DOH LƠI RSE RVĂK BRAH MHĬK\n\nKM 120, KMM 207\n\nVerse 1\nPăng doh lơi rse rvăk Brah mhĭk, Păng doh lơi rse rvăk Brah mhĭk, Păng doh lơi rse rvăk Brah mhĭk, jêh ri tâm rklaih may.\n\nVerse 2\nPăng dơi mprơh lĕ rngôch Brah mhĭk, Păng dơi mprơh lĕ rngôch Brah mhĭk, Păng dơi mprơh lĕ rngôch Brah mhĭk, jêh ri tâm rklaih may.\n\nVerse 3\nPăng ƀư bah lĕ nau ji may, Păng ƀư bah lĕ nau ji may, Păng ƀư bah lĕ nau ji may, jêh ri tâm rklaih may.\n\nVerse 4\nPăng dơi chiă uănh may ăp nar, Păng dơi chiă uănh may ăp nar, Păng dơi chiă uănh may ăp nar, jêh ri tâm rklaih may.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0132", "title": "BRAH HUÊNG UEH ƠI", "song_number": "132", "lyrics": "BRAH HUÊNG UEH ƠI\n\n\nVerse 1\nBrah Huêng Ueh ơi, dăn May mon gâp. Gâp rchuăl uk, May Nơm mon glah.\nDăn pah kan, jan đŏng nau rêh gâp, troch mbêng Brah, dŏng kan May Nơm.\nMon gâp, kôr gâp, nsêr gâp, ai gâp, tât May jan gâp di ngăn ngên.\nMon gâp, kôr gâp, nsêr gâp, ai gâp, troch mbêng Brah, dŏng kan May Nơm.\n", "category": "Nau munh gleh", "language": "Bunong"}, {"local_id": "nau-mpro-0133", "title": "TROCH ĂN BÊNG", "song_number": "133", "lyrics": "TROCH ĂN BÊNG\n\nKM 99, KMM 199\n\nVerse 1\nTroch ăn bêng ŭnh kđen gâp, mbêng ŭch kđen gâp, troch ăn bêng ŭnh kđen gâp, Kôranh ơi.\nTroch ăn bêng ŭnh kđen gâp, gâp ŭch ang tâm ƀon lan bu, kŏ tât nar Yê-su văch.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0134", "title": "GÂP GEH ŬCH KAĐEN AƠ", "song_number": "134", "lyrics": "GÂP GEH ŬCH KAĐEN AƠ\n\nKM 105, KMM 267\n\nVerse 1\nGâp geh ŭnh ka-đen, gâp ŭch sol ăn ang ngăn. Gâp geh ŭnh ka-đen, gâp ŭch sol ăn ang ngăn.\nSol ăn ang, sol ăn ang tâm nau ngo.\n\nVerse 2\nMâu ŭch Sa-tan khôm, gâp ŭch sol ăn ang ngăn. Mâu ŭch Sa-tan khôm, gâp ŭch sol ăn ang ngăn.\nSol ăn ang, sol ăn ang tâm nau ngo.\n\nVerse 3\nMâu ŭch nkŭm ŭnh ôh, gâp ŭch sol ăn ang ngăn. Mâu ŭch nkŭm ŭnh ôh, gâp ŭch sol ăn ang ngăn.\nSol ăn ang, sol ăn ang tâm nau ngo.\n\nVerse 4\nŬnh njŭn bunuyh ma Krist, gâp ŭch sol ăn ang ngăn. Ŭnh njŭn bunuyh ma Krist, gâp ŭch sol ăn ang ngăn.\nSol ăn ang, sol ăn ang tâm nau ngo.\n\nVerse 5\nSol tâm kuĭl chiau meng, gâp ŭch sol ăn ang ngăn. Sol tâm kuĭl chiau meng, gâp ŭch sol ăn ang ngăn.\nSol ăn ang, sol ăn ang tâm nau ngo.\n", "category": "Nau munh gleh", "language": "Bunong"}, {"local_id": "nau-mpro-0135", "title": "ĂN PHUNG AY MAY GĬT DA-DÊ", "song_number": "135", "lyrics": "ĂN PHUNG AY MAY GĬT DA-DÊ\n\nKM 178, KMM 214\n\nVerse 1\nĂn phung ay may gĭt da-dê. Ăn phung ay may gĭt da-dê.\nĂn phung ay may gĭt da-dê. Mbu Yê-su jêng.\nPăng jêng Brah toyh lơn ma lĕ rngôch. Păng jêng tu nau rêh mro mrăng.\nPăng jêng ueh lơn ma âk rbăn bunuyh. Ăn lĕ rngôch ăp nơm bunuyh gĭt.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0136", "title": "YÊ-SU ĐĂ GÂP NSONG MBƠH", "song_number": "136", "lyrics": "YÊ-SU ĐĂ GÂP NSONG MBƠH\n\n\nVerse 1\nYê-su đă gâp nsong mbơh nau mhe mhan.\nGâp dơn, gâp hăn, gâp ŭch hăn ro, nuih n'hâm gâp nơm răm rhơn ƀa-ƀơ.\nHăn hom aƀaơ ri, ăp ntŭk bunuyh tih.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0137", "title": "Y-SA-CHÊ", "song_number": "137", "lyrics": "Y-SA-CHÊ\n\nKM 191, KMM 223\n\nVerse 1\nY-Sa-chê jêng du huê nhuat gleh, du huê nhuat gleh ngăn ngên.\nPăng hao ta klơ tơm si, Si-ka-mor gay uănh Kôranh Brah na-nễ.\nLah Yê-su tât tâm ntŭk păng nĕ, Păng n'gơr uănh klơ tơm si.\nPăng lah pô aơ: \"Y-Sachê, jŭr hom may, Gâp ŭch hăn khâl may nar aơ. Gâp ŭch hăn khâl may nar aơ.\"\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0138", "title": "GÂP DJÔT PRĂP NAU MAY NGƠI", "song_number": "138", "lyrics": "GÂP DJÔT PRĂP NAU MAY NGƠI\n\nKM 208, KMM 238\n\nVerse 1\nGâp djôt prăp nau May Ngơi tâm nuih n'hâm, klach lah gâp lŏ ƀư tih đah May.\nKlach lah gâp ƀư tih, klach lah gâp ƀư tih, pô ri gâp djôt prăp nau May Ngơi.\n", "category": "Nau munh gleh", "language": "Bunong"}, {"local_id": "nau-mpro-0139", "title": "DU HUÊ BU KLÂU NDĂM ĐA-VIT", "song_number": "139", "lyrics": "DU HUÊ BU KLÂU NDĂM ĐA-VIT\n\nKM 209, KMM 237\n\nVerse 1\nDu huê bu klâu ndăm Đa-vit, djôt du mlâm phao rse ntô.\nDu huê bu klâu ndăm Đa-vit, păng chroh ma Kôranh Brah kơl.\nDu huê bu klâu ndăm Đa-vit tâm lơh đah nơm rlăng prêh.\nDu huê bu klâu ndăm Đa-vit sŏk prăm mlâm rchuăl lŭ tâm dak.\nPăng klâm lŭ jễ jễ tâm phao ma rse ntô, păng ndăch rse ntô lêr vêr.\nPăng klâm lŭ jễ jễ tâm phao ma rse ntô, păng ndăch rse ntô lêr vêr.\nPăng ndăch lêr vêr, păng ndăch lêr vêr, păng klŭp rchuăl lŭ nây ro,\nLot khuơng geh ta kleng nơm r-lăng, jêh ri păng cha-lôt khĭt ro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0140", "title": "NJRĂNG HỠ", "song_number": "140", "lyrics": "NJRĂNG HỠ\n\nKM 212, KMM 239\n\nVerse 1\nNjrăng hom hỡ, hơi mpang ti, moh kan may ƀư. Njrăng hom hỡ, hơi mpang ti, moh kan may ƀư.\nKôranh Brah uănh he ƀa-ƀơ, Păng saơ lĕ nau he gŭ ngau. Njrăng hom hỡ, hơi mpang ti, moh kan may ƀư.\n\nVerse 2\nNjrăng hom hỡ, hơi trô măt, moh nau may uănh. Njrăng hom hỡ, hơi trô măt, moh nau may uănh.\nKôranh Brah uănh he ƀa-ƀơ, Păng saơ lĕ nau he gŭ ngau. Njrăng hom hỡ, hơi trô măt, moh nau may uănh.\n\nVerse 3\nNjrăng hom hỡ, hơi trôm tôr, moh nau may iăt. Njrăng hom hỡ, hơi trôm tôr, moh nau may iăt.\nKôranh Brah uănh he ƀa-ƀơ, Păng saơ lĕ nau he gŭ ngau. Njrăng hom hỡ, hơi trôm tôr, moh nau may iăt.\n\nVerse 4\nNjrăng hom hỡ, hơi bâr mbung, moh nau may ngơi. Njrăng hom hỡ, hơi bâr mbung, moh nau may ngơi.\nKôranh Brah uănh he ƀa-ƀơ, Păng saơ lĕ nau he gŭ ngau. Njrăng hom hỡ, hơi bâr mbung, moh nau may ngơi.\n\nVerse 5\nNjrăng hom hỡ, hơi jâng jon, moh ntŭk may hăn. Njrăng hom hỡ, hơi jâng jon, moh ntŭk may hăn.\nKôranh Brah uănh he ƀa-ƀơ, Păng saơ lĕ nau he gŭ ngau. Njrăng hom hỡ, hơi jâng jon, moh ntŭk may hăn.\n\nVerse 6\nNjrăng hom hỡ, hơi nuih n'hâm, moh nau may ŭch. Njrăng hom hỡ, hơi nuih n'hâm, moh nau may ŭch.\nKôranh Brah uănh he ƀa-ƀơ, Păng saơ lĕ nau he gŭ ngau. Njrăng hom hỡ, hơi nuih n'hâm, moh nau may ŭch.\n", "category": "Nau munh gleh", "language": "Bunong"}, {"local_id": "nau-mpro-0141", "title": "TÂM NAR AƠ MAAK NGĂN NGÊN", "song_number": "141", "lyrics": "TÂM NAR AƠ MAAK NGĂN NGÊN\n\n\nVerse 1\nTâm nar aơ ma-ak ngăn ngên, hên gĭt Yê-su jŭr deh ta neh ntu.\nTâm nar aơ ma-ak hâu ngăn, rbăn rmưn Tông mpăr munh mprơ tâm rnê Păng.\nTâm nar aơ deh Nơm tâm Rklaih Vaih lơi nau tih, nau ƀỡ ƀơch tâm he.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0142", "title": "HĂN HOM, HE ROM YÊ-SU", "song_number": "142", "lyrics": "HĂN HOM, HE ROM YÊ-SU\n\n\nVerse 1\nHăn hom, he rom Yê-su, hăn hom, he rom Yê-su,\nran mbah Kôranh Yê-su, hăn hom, he rom Yê-su.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0143", "title": "KÂP IĂT PHUNG TÔNG MPĂR BRAH NDU", "song_number": "143", "lyrics": "KÂP IĂT PHUNG TÔNG MPĂR BRAH NDU\n\nTC 53, KM 8, KMM 20\n\nVerse 1\nKâp iăt phung tông mpăr Brah Ndu Mprơ: \"Tâm rnê Kô-ranh Yê-su.\nMât ton ma Ha-đăch mhe deh, ăn bu-nuyh mra geh nau ueh\".\nLĕ mpôl băl tâm lam n'gor bri, mprơ tâm rnê hom kơt phung ri.\nMbơh nau mhe mhan ueh ma bu: Ƀêt-lê-hem bu deh Yê-su.\nKâp iăt phung tông mpăr Brah Ndu mprơ: \"Tâm rnê Kô-ranh Yê-su\".\n\nVerse 2\nYê-su jêng Kon Dul Brah Ndu, mhe jŭr deh jêh ta neh ntu.\nNjêng săk kơt kon se oh bê, jêng tâm ban bu-nuyh da-dê.\nYê-su jêng Kôranh Brah ngăn ngên, May tâm mpơl Brah Ndu ma hên.\nKôranh Brah ngăn đah he gŭ ndrel: Yê-su Krist, Ê-ma-nu-el.\nKâp iăt phung tông mpăr Brah Ndu mprơ: \"Tâm rnê Kô-ranh Yê-su\".\n\nVerse 3\nTâm r-nê Ha-đăch toyh mhe, lĕ oh nâu, kônh va, sau se.\nPăng mra ăn nau rêh n'ho ro, ăn nau ang mprơh lơi nau ngo.\nLĕ phung tih Păng dơi tâm rklaih, jêng kon me, khlay lơn prăk maih.\nNjêng he jêng kon Brah Ndu Nơm, mâu hôm klach nâm bu sa-ơm.\nKâp iăt phung tông mpăr Brah Ndu mprơ: \"Tâm rnê Kô-ranh Yê-su\".\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0144", "title": "MAAK NGĂN PHUNG HE", "song_number": "144", "lyrics": "MAAK NGĂN PHUNG HE\n\nTC 54, KM 10, KMM 21\n\nVerse 1\nMaak ngăn phung he, Kôranh Brah tât jêh, he rom Păng ma nau răm.\nĂn lĕ bu-nuyh dơn Yê-su Krist. Yor lah Păng rŏng ma he, yor lah Păng rŏng ma he, yor lah, yor lah Păng rŏng ma he.\n\nVerse 2\nMaak ngăn phung he, Kôranh Brah tât jêh, mprơ tâm rnê Păng dŭt n'hâm.\nDôl gŭ tâm yôk dak lŭ tâm bri. Ăn lĕ rngôch bunuyh gĭt Păng, ăn lĕ rngôch bunuyh gĭt Păng, ăn lĕ, ăn lĕ rngôch bunuyh gĭt Păng.\n\nVerse 3\nMaak ngăn phung he, Nơm Tâm Chuai tât, Păng Kon Brah Ndu nanễ ngăn.\nPăng ăn nau rêh Păng jao săk Păng. Yor nây he chroh ma Păng, yor nây he chroh ma Păng, yor nây, yor nây he chroh ma Păng.\nA-MEN.\n", "category": "Nau mprơ Nôel", "language": "Bunong"}, {"local_id": "nau-mpro-0145", "title": "Ơ VĂCH LĔ RNGÔCH PHUNG CHROH", "song_number": "145", "lyrics": "Ơ VĂCH LĔ RNGÔCH PHUNG CHROH\n\nTC 55, KM 12, KMM 22\n\nVerse 1\nƠ văch, lĕ rngôch phung chroh, maak jêh ri ma nau răm.\nVăch hom Ƀêt-lê-hem ndrel n'grŭp he hăn uănh.\nUănh Hađăch toyh tât jêh, gŭ tâm n'gar ndrôk ta nây.\n\nChorus\nƠ văch tâm rnê mât ton Păng, ơ văch tâm rnê mât ton Păng,\nơ văch tâm rnê mât ton Păng, Krist Kôranh Brah.\n\nVerse 2\nMprơ hom, phung tông mpăr ueh, mprơ ma răm hâu ngăn ngên.\nƠ mprơ, lĕ rngôch gŭ klơ iăt Brah Ndu Ngơi.\nMprơ ăn nau chrêk rmah, lah ueh ma Mbỡ he klơ.\n\nChorus\nƠ văch tâm rnê mât ton Păng, ơ văch tâm rnê mât ton Păng,\nơ văch tâm rnê mât ton Păng, Krist Kôranh Brah.\n\nVerse 3\nMât ton Kôranh Brah Yê-su, jêng deh nar maak aơ pơ.\nƠ Yê-su hên rnê chrêk rmah May ƀa-ƀơ.\nMay jêng Nau Ngơi Ngăn, jŭr ta aơ kơt săk bunuyh.\n\nChorus\nƠ văch tâm rnê mât ton Păng, ơ văch tâm rnê mât ton Păng,\nơ văch tâm rnê mât ton Păng, Krist Kôranh Brah.\nA-MEN.\n", "category": "Nau mprơ Nôel", "language": "Bunong"}, {"local_id": "nau-mpro-0146", "title": "TÔNG MPĂR UEH BRAH NDU TĂ BƠH KLƠ", "song_number": "146", "lyrics": "TÔNG MPĂR UEH BRAH NDU TĂ BƠH KLƠ\n\nTC 57, KM 14, KMM 23\n\nVerse 1\nTông mpăr ueh Brah Ndu tă bơh klơ, khân păng hăn lam ntŭk neh ntu.\nKhân păng mprơ nau rhăk njêng neh ntu. A-ƀaơ mbơh nau deh Yê-su.\n\nChorus\nVăch mât ton Păng, văch mât ton Păng, mbah Kôranh Brah Krist, Hađăch mhe deh.\n\nVerse 2\nPhung rmăk biăp gŭ tâm mir khân păng, gŭ chiă uănh phung biăp măng nĕ.\nAƀaơ ri Brah Ndu gŭ ndrel n'hanh bunuyh. Phung mănh nchrat ang jêh ta neh.\n\nChorus\nVăch mât ton Păng, văch mât ton Păng, mbah Kôranh Brah Krist, Hađăch mhe deh.\n\nVerse 3\nƠ oh nâu, cha-lơi kan may iơn. rvê ma nau ueh uĭn aơ hŏ.\nJoi hom Nơm Tâm Rklaih lĕ rngôch bunuyh. He saơ jêh mănh Păng nchrat ang.\n\nChorus\nVăch mât ton Păng, văch mât ton Păng, mbah Kôranh Brah Krist, Hađăch mhe deh.\n\nVerse 4\nPhung chroh Yê-su, chon mon mbah Păng, treng uănh ma Păng rhơn răm ngăn.\nÔi taơ klak Kôranh Brah mra jŭr đŏng. He saơ Păng tâm Ƀon Ueh Păng.\n\nChorus\nVăch mât ton Păng, văch mât ton Păng, mbah Kôranh Brah Krist, Hađăch mhe deh.\nA-MEN.\n", "category": "Nau mprơ Nôel", "language": "Bunong"}, {"local_id": "nau-mpro-0147", "title": "TÂM N'GAR NDRÔK", "song_number": "147", "lyrics": "TÂM N'GAR NDRÔK\n\nTC 556, KM 115, KMM 34\n\nVerse 1\nTâm n'gar ndrôk kăl e Păng mâu geh sưng bêch ôh.\nYê-su, kon se jễ lễ bu mhe deh ta nây.\nPhung mănh klơ trôk gŭ nchrat ang măng nĕ.\nYê-su, kon se jễ lễ Păng bêch ta gỡ kro.\n\nVerse 2\nNdrôk gĕ n'gar, rlay Păng ƀiă lah Păng mâu nhĭm ôh.\nPhung biăp jêh ri seh gŭ dăch kêng Păng ta nĕ.\nGâp rŏng Yê-su dăn May uănh gâp ƀă.\nDăn gŭ dăch ta gâp dôl gâp bêch măng ta oi.\nA-MEN.\n", "category": "Nau mprơ Nôel", "language": "Bunong"}, {"local_id": "nau-mpro-0148", "title": "MĂNG UEH UĬN", "song_number": "148", "lyrics": "MĂNG UEH UĬN\n\nTC 59, KM 15, KMM 24\n\nVerse 1\nMăng ueh uĭn, măng ueh lăng, ngo vêt vê, ngo chuê chuăng.\nDu rplay mbing toyh mpơl tă bơh klơ trôk.\nSol ang oh bê hăk bêch tâm n'gar ndrôk.\nPăng jêng Kon Brah Ndu Nơm. Păng jêng Kon Brah Ndu Nơm.\n\nVerse 2\nMăng ueh uĭn, măng ueh lăng, phung Tông mpăr Ueh Brah Ndu.\nJŭr mbơh ma lĕ phung rmăk biăp tâm ndrêch.\nJêh ri nkoch mbơh nau mhe mhan ueh aơ.\n\"Yê-su lĕ văch măng aơ, Yê-su văch jêh măng aơ\".\n\nVerse 3\nMăng ueh uĭn, măng ueh lăng, Kon Brah Ndu jŭr bơh klơ.\nLĕ rngôch bu-nuyh ndal ran yơk mbah Păng.\nMprơ rnê hom ka-tang \"Ha-lê-lu-ya, Yê-su Krist Nơm Rklaih văch,\nBrah Yê-su hŏ văch jêh\".\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0149", "title": "Ơ ƀON ƀÊT-LÊ-HEM", "song_number": "149", "lyrics": "Ơ ƀON ƀÊT-LÊ-HEM\n\nTC 61, KM 113, KMM 26\n\nVerse 1\nƠ Ƀêt-lê-hem ƀon jễ nây, lĕ rngôch bu-nuyh hăk bêch.\nDôl ngo klĕng Brah Yê-su Krist văch, jêng du huê kon jễ ueh.\nBu saơ du găr mănh toyh, jêh ri mbơh nar ueh uĭn tât.\nLĕ phung njêh văch mbah Păng hâk răm, Brah Yê-su Nơm Tâm Rklaih.\n\nVerse 2\nMa-ri deh ma Brah Yê-su, tâm n'gar ndrôk hăt, ƀỡ ƀơch.\nɃiă lah Tông mpăr Brah Ndu gŭ uănh, jêh ri mprơ rnê ma Păng:\n\"Tâm rnê ma Brah Ndu ta klơ\", lĕ rngôch khân păng lah n'grŭp\"\n\"Ta neh ntu ăn geh nau đăp mpăn ma lĕ phung Brah Ndu rŏng\".\n\nVerse 3\nƠ Kon jễ ueh Bêt-lê-hem, dăn May lăp gŭ tâm hên.\nMprơh lơi lĕ rngôch nau tih mhĭk blem, gŭ ndrel ma hên ƀa-ƀơ.\nHên nkoch bri ma nau deh May, mbơh ăn lĕ rngôch bunuyh gĭt.\nBrah Ndu ăn Kon Păng jŭr ta aơ, tâm rklaih hên bơh nau tih.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0150", "title": "Ơ MĂNG GEH BRAH", "song_number": "150", "lyrics": "Ơ MĂNG GEH BRAH\n\nTC 66, KM 119, KMM 29\n\nVerse 1\nƠ măng ueh uĭn, klơ trôk geh mănh toyh ang nchrang, măng aơ bu deh ma du huê Nơm Tâm Rklaih.\nHŏ jŏ năm jêh neh ntu gŭ tâm nau tih mhĭk. Tât Păng tâm mpơl nau Păng ŭch yỗ ma he.\nPô ri neh ntu gŭ maak răm iăt nau ueh aơ, yor lah măng aơ tât jêh nau chrêk ma lơp.\n\nChorus\nChon mon kô-mâk, iăt hom phung brah ntuh bâr mprơ.\nƠ măng ueh uĭn, măng đăp mpăn măng khlay ngăn ngên.\nƠ măng geh Brah, măng aơ bu deh Yê-su.\n\nVerse 2\nGay he ran Păng, he ran ta ntŭk nau ang Păng, ntŭk jễ, hăt ngăn tâm hip gỡ kro n'gar ndrôk.\nGeh mănh toyh nchrat gay sol phung njêh dơi joi Păng. Pe nuyh phung njêh văch ngai ngăn bơh bri lơ.\nKon se oh bê gŭ bêch ta gỡ bu siăm ndrôk, Păng mra jêng Nơm Tâm rklaih he bơh nau tih.\n\nChorus\nChon mon kô-mâk, iăt hom phung brah ntuh bâr mprơ.\nƠ măng ueh uĭn, măng đăp mpăn măng khlay ngăn ngên.\nƠ măng geh Brah, măng aơ bu deh Yê-su.\n", "category": "Nau mprơ Nôel", "language": "Bunong"}, {"local_id": "nau-mpro-0151", "title": "DÔL PHUNG RMĂK BIĂP GŬ TA NEH AƠ", "song_number": "151", "lyrics": "DÔL PHUNG RMĂK BIĂP GŬ TA NEH AƠ\n\nTC 64, KM 114, KMM 28\n\nVerse 1\nDôl phung rmăk biăp gŭ ta neh aơ, chiăp uănh phung biăp tâm măng.\nTông mpăr ueh jŭr ngơi ma khân păng. Geh nau nchrat ang tâm mplơl, geh nau nchrat ang tâm mpơl.\n\nVerse 2\n\"Lơi klach\", păng lah, yor lah khân păng, mâu gĭt ôh moh nau tât.\n\"Gâp mbơh nau mhe mhan ueh hâu ngăn. Ƀư maak ma lĕ bu-nuyh, ƀư maak ma lĕ bu-nuyh.\n\nVerse 3\n\"Tâm Ƀon Ƀêt-lê-hem ri nar aơ, khân may dơi hăn uănh Păng.\nKon se jễ lễ gŭ tâm n'gar ndrôk. Păng yơh jêng Kon Brah Ndu, Păng yơh jêng Kon Brah Ndu.\"\n\nVerse 4\nTông mpăr lŏ mprơ jăng jai hăn sĭt, \"mât ton tâm rnê Brah Ndu.\nTa neh ntu ăn geh nau đăp mpăn. Ma lĕ phung Brah Ndu rŏng, ma lĕ phung Brah Ndu rŏng.\"\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0152", "title": "BRAH NDU KLƠ TRÔK GEH NAU RŎNG TOYH", "song_number": "152", "lyrics": "BRAH NDU KLƠ TRÔK GEH NAU RŎNG TOYH\n\nTC 68, KM 11, KMM 30\n\nVerse 1\nBrah Ndu klơ trôk geh nau rŏng, âk hâu ngăn ngên, mâu dơi kơp.\nMprơh Kon Păng jŭr ta neh ntu, mâu geh hôm rvê ntŭk nchrat ang.\nɃon Ƀêt-lê-hem, bu deh Păng, lâng bêch tâm hip gỡ kro ndrôk.\nTâm ndrêch geh nau ang mpơl ndal, phung rmăk biăp klach ŭch hăn du.\n\nVerse 2\nUănh tâm trôk geh ndơ nchrat ang, geh Tông mpăr Ueh Brah Ndu ngơi.\nĐăp mpăn ueh maak ma neh ntu, Nơm tâm Rklaih jŭr ŭch sol ang.\nƠ phung rmăk biăp, lơi klach ôh, Păng tât mbơh nau mhe mhan ueh.\nHăn hom ta Ƀon Ƀêt-lê-hem ri ŭch joi Nơm Tâm R-klaih.\n\nVerse 3\nGeh du rplay mbing nchrat pa lơ, phung njêh saơ mpơl ka-lơ trôk.\nDjôt leo mah khlay, dak ƀâu kah, dak si tăng ŭch nhhơr ma Păng.\nChuat hăn groi tĭng ndỗ mănh toyh, tât joi ntŭk Kon Brah Ndu gŭ.\nNhhơr ndơ khlay yơk mbah Yê-su, yor lah Păng yơh jêng Kôranh Brah.\n\nVerse 4\nMăng nĕ jêng măng maak ueh uĭn, an ma phung he maak da-dê,\nTâm rnê Krist văch jêng kon bunuyh, njŭn leo bunuyh tât ma nau ang.\nA-ƀaơ he mbơh nau mhe mhan, gay rlay phung hôm e hăk bêch.\nGay njrăng rngeh nau ueh maak aơ, munh mprơ gay ma rlay phung chroh.\n", "category": "Nau mprơ Nôel", "language": "Bunong"}, {"local_id": "nau-mpro-0153", "title": "NÔ-EL, NÔ-EL", "song_number": "153", "lyrics": "NÔ-EL, NÔ-EL\n\nTC 73, KM 16, KMM 31\n\nVerse 1\nTông mpăr Brah Ndu mbơh nau kăl e. Phung rmăk chiăp biăp tâm ndrêch măng nĕ.\nNô-el, păng lah, Nô-el tât jêh, nar Yê-su Krist văch ta neh ntu.\n\nChorus\nNô-el, Nô-el, Nô-el, Nô-el. Deh jêh Ha-đăch Toyh I-sra-el.\n\nVerse 2\nRmăk biăp n'gơr uănh tâm trôk ta klơ. Saơ mănh toyh nchrat ang ta neh ntu.\nPăng nchrat ang ngăn măng jêh ri nar, gay mpơl ngih Mari deh Brah Yê-su.\n\nChorus\nNô-el, Nô-el, Nô-el, Nô-el. Deh jêh Ha-đăch Toyh I-sra-el.\n\nVerse 3\nGeh pe nuyh njêh gŭ tâm bri ngai. Khân Păng saơ mănh toyh nchrang bri lơ.\nKhân păng tĭng joi ŭch uănh nau khlay, gay uănh oh bê Ƀon Ƀêt-lê-hem.\n\nChorus\nNô-el, Nô-el, Nô-el, Nô-el. Deh jêh Ha-đăch Toyh I-sra-el.\n\nVerse 4\nLĕ rngôch khân păng tât ta n'gar ndrôk. Saơ Yê-su Krist jêng Brah Nơm Rklaih.\nKhân păng chon mon păn mbah oh bê, mât ton Brah Ndu, ăn Kon Păng jŭr.\n\nChorus\nNô-el, Nô-el, Nô-el, Nô-el. Deh jêh Ha-đăch Toyh I-sra-el.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0154", "title": "HÊN PE NUYH NJÊH VĂCH TĂ BAH LƠ", "song_number": "154", "lyrics": "HÊN PE NUYH NJÊH VĂCH TĂ BAH LƠ\n\nKM 118, KMM 36\n\nVerse 1\nHên pe nuyh njêh văch tă bah lơ, bah ntŭk ngai djôt leo ndơ khlay.\nNsong tĭng trong tâm yôk, tâm bri, yor tĭng groi du găr mănh toyh.\n\nChorus\nHơi, mănh toyh ơi, sol ăn ang hên. Ntĭm trong hăn ma hên ƀa-ƀơ.\nNjŭn leo hên ta ngih bu deh Păng. Hên ŭch yơk, ŭch mbah Hađăch mhe.\n\nVerse 2\nGâp hăn nhhơr drăp mah khlay hâu ngăn, ăn Ha-đăch ta Ƀêt-lê-hem.\nPăng chiă uănh lĕ rngôch neh ntu, mâu mâp geh r-lau lôch ôh.\n\nChorus\nHơi, mănh toyh ơi, sol ăn ang hên. Ntĭm trong hăn ma hên ƀa-ƀơ.\nNjŭn leo hên ta ngih bu deh Păng. Hên ŭch yơk, ŭch mbah Hađăch mhe.\n\nVerse 3\nDak ƀâu kah aơ gâp nhhơr ma May, Păng ntĭt nâm nau brah ta klơ.\nNau mbơh sơm hao tât ma Păng, ŭch mât ton tâm rnê Yê-su.\n\nChorus\nHơi, mănh toyh ơi, sol ăn ang hên. Ntĭm trong hăn ma hên ƀa-ƀơ.\nNjŭn leo hên ta ngih bu deh Păng. Hên ŭch yơk, ŭch mbah Hađăch mhe.\n\nVerse 4\nGăp nhhơr dak si tăng aơ ma May, Păng ntĭt nâm bu nau May khĭt.\nNkhŭt dak mham ta si tâm rkăng, bu mra tâp May tâm trôm môch.\n\nChorus\nHơi, mănh toyh ơi, sol ăn ang hên. Ntĭm trong hăn ma hên ƀa-ƀơ.\nNjŭn leo hên ta ngih bu deh Păng. Hên ŭch yơk, ŭch mbah Hađăch mhe.\n\nVerse 5\nRăm r-hơn ngăn hên rom Păng tât, Kôranh toyh lơn lĕ phung kôranh êng.\nHa-lê-lu-ya! Ha-lê-lu-ya! Mprơ hom tâm rnê ma Păng.\n\nChorus\nHơi, mănh toyh ơi, sol ăn ang hên. Ntĭm trong hăn ma hên ƀa-ƀơ.\nNjŭn leo hên ta ngih bu deh Păng. Hên ŭch yơk, ŭch mbah Hađăch mhe.\nA-MEN.\n", "category": "Nau mprơ Nôel", "language": "Bunong"}, {"local_id": "nau-mpro-0155", "title": "HE IĂT BRAH NTUH BÂR BRAH NDU", "song_number": "155", "lyrics": "HE IĂT BRAH NTUH BÂR BRAH NDU\n\nKMM 38\n\nVerse 1\nHe iăt Brah ntuh bâr Brah Ndu, mprơ mbơh nau bu deh Yê-su.\nPăng jŭr văch ta neh ntu aơ, gay tâm rklaih lĕ nau tih he.\n\nChorus\nMât ton Păng. Brah Ndu Nơm ta klơ ri.\nMât ton Păng, Brah Ndu Nơm ta klơ ri.\n\nVerse 2\nPhung rmăk biăp khăn păng gŭ klach, mâm ƀư phung Brah ntuh bâr mprơ?\nMoh nâm nau ueh khân păng geh, khân păng mprơ nau bâr ngơi ueh?\n\nChorus\nMât ton Păng. Brah Ndu Nơm ta klơ ri.\nMât ton Păng, Brah Ndu Nơm ta klơ ri.\n\nVerse 3\nHăn uănh ta Ƀon Ƀêt-lê-hem, uănh nơm Brah ntuh bâr tâm rnê.\nChon kô-mâk mbah yơk ma Păng, Yê-su Krist Hađăch Toyh mhe deh.\n\nChorus\nMât ton Păng. Brah Ndu Nơm ta klơ ri.\nMât ton Păng, Brah Ndu Nơm ta klơ ri.\n\nVerse 4\nBu deh Păng tâm hip gỡ kro, Yê-su Kôranh ma trôk, ma neh.\nĂn he kơt phung Brah ntuh bâr, ran rhơn Păng bêng nau răm ngăn.\n\nChorus\nMât ton Păng. Brah Ndu Nơm ta klơ ri.\nMât ton Păng, Brah Ndu Nơm ta klơ ri.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0156", "title": "NTŬK ƀÊT-LÊ-HEM TÂM YU-ĐA", "song_number": "156", "lyrics": "NTŬK ƀÊT-LÊ-HEM TÂM YU-ĐA\n\nTC 75\n\nVerse 1\nNtŭk Ƀêt-lê-hem tâm Yu-đa, klong măng Brah Yê-su jŭr deh.\nLơi ntŭk chrêk ma lơp ƀon Păng, jŭr gay tâm rklaih phung bunuyh tih.\n\nChorus\nNô-el, măng ueh maak, Yê-su ŭch joi he.\nNô-el măng ueh maak. Jêng măng ueh maak ma he.\n\nVerse 2\nKăl e phung Tông mpăr hâk răm, mbơh nau mhe mhan ueh ma bunuyh.\nA-ƀaơ he tĭng kơt pô nây, ăn neh ntu năl Kôranh Brah Nơm.\n\nChorus\nNô-el, măng ueh maak, Yê-su ŭch joi he.\nNô-el măng ueh maak. Jêng măng ueh maak ma he.\n\nVerse 3\nPhung kon se he mprơ n'grŭp n'grŭp, maak tâm rƀŭn jŭm si Nô-el.\nNkah ndrăng nơm nau Yê-su deh, ŭch khĭt tâm chuai nau tih he.\n\nChorus\nNô-el, măng ueh maak, Yê-su ŭch joi he.\nNô-el măng ueh maak. Jêng măng ueh maak ma he.\n", "category": "Nau mprơ Nôel", "language": "Bunong"}, {"local_id": "nau-mpro-0157", "title": "RI UĂNH NTŬK ƀÊT-LÊ-HEM", "song_number": "157", "lyrics": "RI UĂNH NTŬK ƀÊT-LÊ-HEM\n\n\nVerse 1\nRi uănh ntŭk Ƀêt-lê-hem. Tâm hip gỡ ƀỡ ngăn.\nKon se Yê-su deh văch, jan rup săk tâm ban he.\nTrôk prêh ri lĕ phung mănh, gŭ nchŏng uănh ta Păng.\nKon se Yê-su deh văch, bêch tâm hip gỡ ndrôk.\n\nVerse 2\nDăn Yê-su, Brah chrêk lơp. Kơl gâp nau ueh lăng.\nNjŭn gâp tât ti Brah Nơm, gay ma gâp gŭ ueh lăng.\nĂn njŭn gâp tât ƀon klơ, dăch sưng Kôranh Brah ngăn.\nGâp mra mât ton Yê-su, mprơ ma Păng ƀa-ƀơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0158", "title": "MAAK NGĂN NGÊN, HE MPRƠ KATANG", "song_number": "158", "lyrics": "MAAK NGĂN NGÊN, HE MPRƠ KATANG\n\n\nVerse 1\nMaak ngăn ngên, he mprơ ktang, măng Nô-el kuăl n'hanh. Kôranh Brah jŭr gay tâm rklaih phung bu-nuyh tih mhĭk.\nMăng aơ Kôranh Brah Krist jŭr deh. Ăn lĕ rngôch he mât ton Păng, nuih n'hâm maak rŏng ma Păng âk.\nMaak ngăn ngên, he mprơ ktang, măng Nô-el kuăl n'hanh. Kôranh Brah jŭr gay tâm rklaih phung bu-nuyh tih mhĭk.\n\nVerse 2\nUeh ngăn ngên, he mprơ ktang, măng Nô-el kuăl n'hanh. Kôranh Brah jŭr gay tâm rklaih phung bu-nuyh tih mhĭk.\nTơm si Nô-el dâk rơt gơt. Ăn he mprơ tâm rnê Yê-su, nuih n'hâm maak răm rhơn hâu ngăn.\nUeh ngăn ngên, he mprơ ktang, măng Nô-el kuăl n'hanh. Kôranh Brah jŭr gay tâm rklaih phung bu-nuyh tih mhĭk.\n\nVerse 3\nRăm ngăn ngên, he mprơ ktang, măng Nô-el kuăl n'hanh. Kôranh Brah jŭr gay tâm rklaih phung bu-nuyh tih mhĭk.\nMăng aơ he rŏng ma Yê-su. Ntơm nar aơ tât nar ka-ndỡ, nuih n'hâm he mâu geh chuêl Păng.\nRăm ngăn ngên, he mprơ ktang, măng Nô-el kuăl n'hanh. Kôranh Brah jŭr gay tâm rklaih phung bu-nuyh tih mhĭk.\n", "category": "Nau mprơ Nôel", "language": "Bunong"}, {"local_id": "nau-mpro-0159", "title": "KLƠ GEH MĂNH NCHRAT", "song_number": "159", "lyrics": "KLƠ GEH MĂNH NCHRAT\n\nTC 505, KM 13, KMM 33\n\nVerse 1\nKlơ geh mănh nchrat, bunuyh bêch lêr khêr, phung rmăk biăp saơ nau ang tâm mpơl.\nTâm nuih n'hâm klach râm nsâr re bre, geh Brah ntuh bâr văch ma khăn păng.\n\nChorus\nHa-lê-lu-ya mprơ bâr ngơi huy. Yê-su, Kôranh Brah jŭr ta neh ntu,\njŭr bơh Brah Ndu gay rklaih bunuyh tih, ơ oh nâu he, mprơ maak Nô-el.\n\nVerse 2\nPăng hŏ tât jêh ta Ƀon Đa-vit, ơ phung rmăk biăp, gơnh ơi hăn uănh,\nDu huê oh bê ntâk nkŭm bok nglang, Păng kon Brah Ndu, văch khâl phung he.\n\nChorus\nHa-lê-lu-ya mprơ bâr ngơi huy. Yê-su, Kôranh Brah jŭr ta neh ntu,\njŭr bơh Brah Ndu gay rklaih bunuyh tih, ơ oh nâu he, mprơ maak Nô-el.\n\nVerse 3\nBrah ntuh bâr lah: \"Ăn nau đăp mpăn, ma kon bu-nuyh tâm lam neh ntu\".\nRmưn rsen Tông mpăr, munh mprơ nchreng ndrel, tâm rnê Brah Ndu ăn Kon Păng deh.\n\nChorus\nHa-lê-lu-ya mprơ bâr ngơi huy. Yê-su, Kôranh Brah jŭr ta neh ntu,\njŭr bơh Brah Ndu gay rklaih bunuyh tih, ơ oh nâu he, mprơ maak Nô-el.\n\nVerse 4\nPăng jêng Kon Brah Ndu nơm kalơ trôk, jŭr ta neh ntu. kơt nglay săk bunuyh.\nBu druh H'Ma-ri sâm deh ma Păng, Păng Kon Brah Ndu jêng nâm kon bunuyh.\n\nChorus\nHa-lê-lu-ya mprơ bâr ngơi huy. Yê-su, Kôranh Brah jŭr ta neh ntu,\njŭr bơh Brah Ndu gay rklaih bunuyh tih, ơ oh nâu he, mprơ maak Nô-el.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0160", "title": "MAAK YƠH NÔ-EL", "song_number": "160", "lyrics": "MAAK YƠH NÔ-EL\n\nTC 506, KM 9, KMM 32\n\nVerse 1\nMaak yơh Nô-el, măng bu deh ma Kôranh Brah. Tông mpăr Brah Ndu mprơ mbơh nau mhe mhan ueh.\nMaak yơh Nô-el măng bu deh ma Kôranh Brah. Măng nĕ Kôranh Brah văch joi gay rklaih lĕ rngôch bunuyh tih.\n\nChorus\nMaak răm yơh, maak răm yơh. Maak yơh, Kôranh Brah Nơm toyh,\nPăng yỗ ma phung ƀon lan, Păng jŭr bơh Ƀon Brah Ndu.\n\nVerse 2\nMaak yơh Nô-el Kon Brah Ndu jŭr nar aơ. Ta Ƀêt-lê-hem tâm ndrung n'gar ndrôk Păng bêch.\nMaak yơh Nô-el Kon Brah Ndu jŭr nar aơ. Maak yơh, Păng lơi Ƀon nchrat ang Păng jŭr ta neh ntu.\n\nChorus\nMaak răm yơh, maak răm yơh. Maak yơh, Kôranh Brah Nơm toyh,\nPăng yỗ ma phung ƀon lan, Păng jŭr bơh Ƀon Brah Ndu.\n\nVerse 3\nMaak yơh Nô-el măng aơ ueh nchrat ang ngăn. Maak ta neh ntu, yor nau nchrat ang Brah Ndu.\nMaak yơh Nô-el măng ueh geh nau nchrat ang. Măng aơ ueh uĭn yor lah bunuyh dơi geh nau yỗ nđach.\n\nChorus\nMaak răm yơh, maak răm yơh. Maak yơh, Kôranh Brah Nơm toyh,\nPăng yỗ ma phung ƀon lan, Păng jŭr bơh Ƀon Brah Ndu.\n", "category": "Nau mprơ Nôel", "language": "Bunong"}, {"local_id": "nau-mpro-0161", "title": "AMOH UEH LƠN MA LĔ RNGÔCH", "song_number": "161", "lyrics": "AMOH UEH LƠN MA LĔ RNGÔCH\n\nTC 458\n\nVerse 1\nKăl e tât aƀaơ ê geh nơm nkoch, mbơh Kôranh Brah Nơm rmơih rmên ngăn\nBrah Ndu hŏ ăn Kon Păng jŭr deh, hih rhâl ngăn! mbu nơm dơi gĭt\n\nChorus\nHe rŏng mprơ ma Brah Krist Hađăch toyh, ŭch nkoch mbơh Amoh Yê-su mro.\nJêh ri ŭch tông Amoh Kôranh Yê-su; Răm maak hâu ngăn, maak mro mrăng.\n\nVerse 2\nNar Yê-su khĭt ta si tâm rkăng, bu chih Amoh Păng ta kđar yông,\nnây jêng Yê-su geh rmưn bunuyh uănh, jêng Kôranh ngăn! Ơ Kôranh Brah gâp.\n\nChorus\nHe rŏng mprơ ma Brah Krist Hađăch toyh, ŭch nkoch mbơh Amoh Yê-su mro.\nJêh ri ŭch tông Amoh Kôranh Yê-su; Răm maak hâu ngăn, maak mro mrăng.\n\nVerse 3\nAƀaơ Păng dôl gŭ ta klơ Ƀon Ueh, nau Brah bơh klơ, mbu dơi rlau,\nPăng rŏng ma phung kâp gân nau maak, Păng Ha-đăch toyh Amoh Yê-su.\n\nChorus\nHe rŏng mprơ ma Brah Krist Hađăch toyh, ŭch nkoch mbơh Amoh Yê-su mro.\nJêh ri ŭch tông Amoh Kôranh Yê-su; Răm maak hâu ngăn, maak mro mrăng.\n\nVerse 4\nNsing ma Amoh Păng, moh ndơ gâp hăn, Păng mra ăn nau Brah kăn-dỡ,\nntơm bơh nđaơ, tât ta mro mrăng ngăn, Yê-su mâu blau trơn rgâl ôh.\n\nChorus\nHe rŏng mprơ ma Brah Krist Hađăch toyh, ŭch nkoch mbơh Amoh Yê-su mro.\nJêh ri ŭch tông Amoh Kôranh Yê-su; Răm maak hâu ngăn, maak mro mrăng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0162", "title": "VĂCH MA HÊN HAĐĂCH TOYH LƠN", "song_number": "162", "lyrics": "VĂCH MA HÊN HAĐĂCH TOYH LƠN\n\nTC 1\n\nVerse 1\nVăch ma hên Hađăch toyh lơn, kơl hên mprơ tâm rnê ma May.\nKơl hên mât ton, Mbỡ hên Nơm chrêk ma lơp, May dơi đah lĕ rngôch brah.\nvăch mât mơh hên ƀa-ƀơ ơ Brah Ndu hên.\n\nVerse 2\nVăch ma hên Nau Ngơi rêh, djôt đao Brah khlay dăng tâm lơh.\niăt hên mbơh sơm, văch ăn nau ueh ma hên, ăn nau ngơi May njêng hên.\ndăn Brah Huêng Ueh May gŭ tâm nuih n'hâm hên.\n\nVerse 3\nVăch ma hên Brah Bonh Leng, ăn ngăn nau May mbơh ma hên.\nĂp nar ƀa-ƀơ, May Nơm geh lĕ nau Brah, lăp tâm nuih n'hâm lĕ rngôch.\nlơi cha lơi hên dơm dam, ơ Brah Huêng Ueh.\n\nVerse 4\nMa May Nơm Brah Tâm Pe, hên ŭch tâm rnê mât ton May.\nNtơm aƀaơ jăt năp tâm mpơl nau chrêk ma lơp, pô ri ăn huêng gĭt rbăng.\nɃon bri Hađăch May mât uănh mâu blau lôch ôh.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0163", "title": "TÂM RNÊ MA NƠM TÂM CHUAI", "song_number": "163", "lyrics": "TÂM RNÊ MA NƠM TÂM CHUAI\n\nTC 11\n\nVerse 1\nGâp ŭch mprơ ma Nơm tâm chuai gâp. Jêh ri nau rŏng toyh Păng ăn.\nDơn rêh ni ta si tâm rkăng dơn nau rak rtăp ăn gâp kon me.\n\nChorus\nƠ mprơ ma Nơm tâm chuai jêh gâp. Păng chuai gâp ma mham Păng Nơm.\nSi tâm rkăng Păng ăn nau yỗ an. Trok jêh rnon ăn gâp kon me.\n\nVerse 2\nGâp ŭch nkoch bri nau khlay ir aơ. Nau tâm rklaih gâp hŏ roh jêh.\nMa nau rŏng toyh jêh ri nau yỗ, Păng ăn gâp klaih bơh nau tih.\n\nChorus\nƠ mprơ ma Nơm tâm chuai jêh gâp. Păng chuai gâp ma mham Păng Nơm.\nSi tâm rkăng Păng ăn nau yỗ an. Trok jêh rnon ăn gâp kon me.\n\nVerse 3\nGâp mât ton ma Nơm tâm chuai gâp. Gay nkoch bri ma nau Brah Păng.\nYor nau Păng dơi jêh đah neh ntu, nđâp nau khĭt jêh ri ndrung ŭnh.\n\nChorus\nƠ mprơ ma Nơm tâm chuai jêh gâp. Păng chuai gâp ma mham Păng Nơm.\nSi tâm rkăng Păng ăn nau yỗ an. Trok jêh rnon ăn gâp kon me.\n\nVerse 4\nGâp mra mprơ ma Nơm tâm chuai gâp. Jêh ri nau rŏng toyh Păng ăn.\nPăng ăn gâp gŭ tâm nau rêh Păng, Păng njêng gâp jêng Kon Brah Ndu.\n\nChorus\nƠ mprơ ma Nơm tâm chuai jêh gâp. Păng chuai gâp ma mham Păng Nơm.\nSi tâm rkăng Păng ăn nau yỗ an. Trok jêh rnon ăn gâp kon me.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0164", "title": "RGÂL MHE NUIH N'HÂM GÂP", "song_number": "164", "lyrics": "RGÂL MHE NUIH N'HÂM GÂP\n\nTC 441\n\nVerse 1\nYor Păng gâp geh nau rgâl, ntơm aƀaơ kloh nglang nâm pler;\nDăn nhhơr săk jăn aơ ma Kôranh Brah. Tông tĭng nâm nau Păng ŭch.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0165", "title": "RNÊ KÔRANH BRAH AP-RA-HAM", "song_number": "165", "lyrics": "RNÊ KÔRANH BRAH AP-RA-HAM\n\nTC 3\n\nVerse 1\nRnê Kôranh Brah Ap-ra-ham, Yê-hô-va phung ta han.\nKnŏng May dơm jêng Kôranh Brah ƀa-ƀơ bêng ma nau rŏng.\nNeh ntu klơ trôk mpơl jêh, Păng jêng Nơm gŭ n'ho ro.\nHên chon kô-mâk rnê Brah toyh lơn, chrêk rmah n'ho ro.\n\nVerse 2\nVăch lĕ rngôch bunuyh mât ton, yơk mbah Pe Ha-đăch Brah.\nRnê ma Brah Ndu Mbỡ, Kon, jêh ri ma Brah Huêng Ueh.\nBrah Ap-ram jêng Brah gâp, gâp jêng kon Ap-ra-ham.\nMprơ huy ma Pe Hađăch Brah nau dơi dŭt prêh klơ lơn.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0166", "title": "NAR HŎ DĂCH MĂNG", "song_number": "166", "lyrics": "NAR HŎ DĂCH MĂNG\n\nTC 36\n\nVerse 1\nNar hŏ dăch măng ndâp yỗ ri, lĕ dak rlai rngân đăp mpăn ngăn.\nMănh mbing nchrat rêp ƀlêp klơ ri, ŭch mprơ tâm rnê Brah nau rŏng mât ton ma Păng.\n\nChorus\nKloh ueh, kloh ueh, kloh ueh Brah khư he yơk! Bơh tâm trôk tât lam neh ntu, trôk nđâp neh ntu mprơ n'grŭp ndrel ma Brah toyh ngăn.\n\nVerse 2\nTâm trôk dŭt prêh ka-lơ ri, ntŭk Kôranh Brah gŭ ueh hâu ngăn.\nDăn Păng rƀŭn phung biăp nhhơt mlêng, ut r'u gay ma sâm nti ăn mâu hôm gŭ ngai.\n\nChorus\nKloh ueh, kloh ueh, kloh ueh Brah khư he yơk! Bơh tâm trôk tât lam neh ntu, trôk nđâp neh ntu mprơ n'grŭp ndrel ma Brah toyh ngăn.\n\nVerse 3\nDôl klong măng geh nau rngot rvê, Păng bonh phung he ma nau rŏng.\nUeh geh nau chrêk ma lơp ngăn, tâm Ƀon Ueh chrêk rmah sol ang kloh Ueh hâu ngăn.\n\nChorus\nKloh ueh, kloh ueh, kloh ueh Brah khư he yơk! Bơh tâm trôk tât lam neh ntu, trôk nđâp neh ntu mprơ n'grŭp ndrel ma Brah toyh ngăn.\n\nVerse 4\nDăch tât mông cha-lơi neh ntu, lĕ mănh mbing jêng nâm bu ngo.\nkâp gân nau ang dôl ơm ôi, nau ngo nây hŏ roh rai jêh, rêh tâm Ƀon Ueh.\n\nChorus\nKloh ueh, kloh ueh, kloh ueh Brah khư he yơk! Bơh tâm trôk tât lam neh ntu, trôk nđâp neh ntu mprơ n'grŭp ndrel ma Brah toyh ngăn.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0167", "title": "YÊ-SU UEH LƠN", "song_number": "167", "lyrics": "YÊ-SU UEH LƠN\n\nTC 13\n\nVerse 1\nYê-su Nơm ueh lơn, Kôranh mât uănh lĕ rngôch ndơ, May jêng Brah Ndu jêng nâm Kon bunuyh,\nMay dơm Nơm gâp rŏng. May dơm Nơm gâp yơk, tâm May huêng gâp geh nau răm rhơn.\n\nVerse 2\nUănh gỡ nse jêng ueh, jêh ri bri krŏng ueh ngăn, bêng ma âk ntil kao ueh ƀâu kah,\nYê-su Nơm ueh lơn. Yê-su Nơm kloh lơn, Nơm dơi ăn nuih n'hâm rngot mprơ maak.\n\nVerse 3\nNar luh nchrat ang ngăn, nau khlay nchrat lơ hâu lơn, jêh ri mănh mbing rêp ƀlêp tâm trôk,\nYê-su nchrat ang lơn. Yê-su nchrat ang lơn, ma lĕ rngôch tông mpăr ueh tâm trôk.\n\nVerse 4\nNơm tâm rklaih ueh lơn, Kôranh Brah ma lĕ rngôch ndơ, jêng Kon Brah Ndu, jêng nâm kon bunuyh\nnau yơk chrêk ma lơp. Nau mât ton tâm rnê, ma May ƀa-ƀơ jêh ri n'ho ro.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0168", "title": "TÂM DÂNG NĂR PĂNG", "song_number": "168", "lyrics": "TÂM DÂNG NĂR PĂNG\n\nTC 48\n\nVerse 1\nTâm dâng năr Păng gâp dơi gŭ ma nau đăp mpăn, nđâp khay ngo klĕng, nau ndơm djơh mhĭk kđôi lĕ.\nĂt gâp nsing ma Păng, gâp gĭt Păng mât mơh gâp. Păng hŏ chuai jêh gâp, Gâp hŏ jêng kon Păng,\n\nChorus\nNsing tâm năr Krist nting năr ueh uĭn, mâu dơi rlet ôh nau rŏng Păng.\nhuêng gâp gŭ nsing tâm năr Brah Ndu mro, geh đăp mpăn ueh maak n'ho ro.\n\nVerse 2\nTâm dâng năr Păng jêng ntŭk krap tâm nôk rêh ni, nuih n'hâm maak ngăn sĭt tâm nau đăp mpăn Păng.\nN'hêl ngăn neh ntu mâu geh nau dơi ƀư bah gâp. Ta nây gâp saơ nau bonh nđâp nau răm maak.\n\nChorus\nNsing tâm năr Krist nting năr ueh uĭn, mâu dơi rlet ôh nau rŏng Păng.\nhuêng gâp gŭ nsing tâm năr Brah Ndu mro, geh đăp mpăn ueh maak n'ho ro.\n\nVerse 3\nTâm dâng năr Păng geh nau đăp mpăn hâu ngăn ngên, ta nây gâp krap kŏ tât lôch nau rlong uănh.\nPăng jêng ntŭk nde king nau djơh mhĭk mâu dơi ƀư. Gŭ tâm Brah Yê-su geh đăp mpăn ƀa-ƀơ.\n\nChorus\nNsing tâm năr Krist nting năr ueh uĭn, mâu dơi rlet ôh nau rŏng Păng.\nhuêng gâp gŭ nsing tâm năr Brah Ndu mro, geh đăp mpăn ueh maak n'ho ro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0169", "title": "BRAH NDU MRA MÂT MƠH MAY", "song_number": "169", "lyrics": "BRAH NDU MRA MÂT MƠH MAY\n\nTC 49\n\nVerse 1\nLơi hih rhâl đah nau tât ma may, Brah Ndu mra mât mơh may.\nTâm dâng năr Păng tâm nau Păng rŏng, Brah Ndu mra mât mơh may.\n\nChorus\nBrah Ndu mra mât mơh may, tâm lĕ rngôch khay năm may gŭ rêh\nPăng mra mât mơh ƀa-ƀơ, N'hêl Kôranh Brah mra mât mơh ngăn.\n\nVerse 2\nNđâp nar may geh nau jâk kan jêr, Brah Ndu mra mât mơh may.\nlah geh nau mhĭk blem gŭ ta trong, Brah Ndu mra mât mơh may.\n\nChorus\nBrah Ndu mra mât mơh may, tâm lĕ rngôch khay năm may gŭ rêh\nPăng mra mât mơh ƀa-ƀơ, N'hêl Kôranh Brah mra mât mơh ngăn.\n\nVerse 3\nPăng mra ăn lĕ rngôch ndơ may ŭch, Brah Ndu mra mât mơh may.\nnsing ma Păng jêh ri may mra maak, Brah Ndu mra mât mơh may.\n\nChorus\nBrah Ndu mra mât mơh may, tâm lĕ rngôch khay năm may gŭ rêh\nPăng mra mât mơh ƀa-ƀơ, N'hêl Kôranh Brah mra mât mơh ngăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0170", "title": "TÂT JÊH MĂNG NCHRAT ANG", "song_number": "170", "lyrics": "TÂT JÊH MĂNG NCHRAT ANG\n\nTC 60\n\nVerse 1\nTât jêh dôl klong măng nây nchrat ang, du nau mprơ maak ueh reh.\nbơh phung Tông mpăr văch ta neh ntu. Nôk kreh gong rêng ndrel n'grŭp;\nNau đăp mpăn tâm rnglăp lĕ rngôch bunuyh, bơh Ƀon Brah Ndu klơ trôk.\nLĕ neh ntu gŭ tâm nau klăk klêm, ŭch iăt nau tông mpăr mprơ.\n\nVerse 2\nTât ta nar aơ khân păng ăt văch, tông mpăr Brah Ndu bơh trôk.\nĂt geh nau mprơ ueh nây bơh klơ. Ngloh tât neh ntu ntŭk rngot;\nTa neh ntu aơ bêng nau uh ah, tông mpăr lĭ năr gay nkŭm.\nNeh ntu geh âk nau nteh drơu drơu, tăng phung tông mpăr ueh mprơ.\n\nVerse 3\nPô-nây mbu sâm anh nau jâk jêr, păm knŏng săk jăn Yê-su.\nLăp dak, hao sop; poh yôk âk ntil. Rgănh rgônh âk tỡ ƀa-ƀơ;\nTơ lah plỡ nklân mông khlay hŏ lăn, ntŭk Păng gŭ ăn gơnh hom.\nAy may lơi rdja tâm nau rêh ni, kâp iăt phung tông mpăr mprơ.\n\nVerse 4\nɃư ăn di tĭng nau hŏ lah jêh, Ƀon bri Hađăch Păng gơnh tât.\nNdah hŏ geh nar khay chuat rlau jêh. Phung mom ndăm mâu mbrơi ôh;\nNôk nây mơ saơ nau ueh maak ngăn, nchrat ang ma lĕ rngôch bunuyh.\nĂn lĕ bu-nuyh sŏk dơn da dê, nau mprơ tông mpăr khlay ngăn.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0171", "title": "MÂU GEH JRÔ TÂM NGIH NJƯH", "song_number": "171", "lyrics": "MÂU GEH JRÔ TÂM NGIH NJƯH\n\nTC 63\n\nVerse 1\nMâu geh jrô tâm ngih njưh, Mâu geh ôh sưng bêch! Geh knŏng ntŭk tâm n'gar ndrôk, ăn Yê-su dâm bôk!\nmâu geh bunuyh tâm rnê Păng, mâu geh nuih n'hâm rŏng; Pư nau ueh knŏng rngot dơm; Mâu geh jrô tâm ngih njưh.\n\nChorus\nMâm may mâu prăp ntŭk ma Yê-su? Rom hom Păng aƀaơ ro.\nKlach lah may tât ta Ƀon Ueh Păng, mâu geh jrô prăp ma May.\n\nVerse 2\nMâu geh bunuyh nhhơr nau rêh, Mâu ŭch pah kan Păng! Khân păng mâu ŭch dêh rhêt, mâu geh nau chroh ngăn,\nmâu mĭn ma nơm tâm rklaih, mâu geh rngot nau tih; Ŭch ma nau Păng yỗ ngăn; Mâu geh jrô tâm ngih njưh.\n\nChorus\nMâm may mâu prăp ntŭk ma Yê-su? Rom hom Păng aƀaơ ro.\nKlach lah may tât ta Ƀon Ueh Păng, mâu geh jrô prăp ma May.\n\nVerse 3\nMâu geh bunuyh gĭt năl Hađăch, Mâu geh nơm rom Păng! Ntŭk geh dak ƀâu kah ăn? Knŏng saơ đao mhĭk blem!\nmâu geh bunuyh joi nau yỗ, mâu geh nơm yơk Păng; Mbu chrê ma Păng rêh ni? Mâu geh jrô tâm ngih njưh.\n\nChorus\nMâm may mâu prăp ntŭk ma Yê-su? Rom hom Păng aƀaơ ro.\nKlach lah may tât ta Ƀon Ueh Păng, mâu geh jrô prăp ma May.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0172", "title": "CHRÊK LƠP, CHRÊK LƠP!", "song_number": "172", "lyrics": "CHRÊK LƠP, CHRÊK LƠP!\n\nTC 373\n\nVerse 1\nTâm Ƀon Ueh phung kon se rƀŭn n'hanh, ueh maak ngăn jŭm sưng kloh,\nNau Kôranh Brah yỗ, nuih n'hâm nglang ƀhiau; răm rhơn mprơ tâm Ƀon Ueh.\nMprơ yor: \"Chrêk lơp, chrêk lơp, Mbỡ kloh ueh khư nau chrêk lơp!\"\n\nVerse 2\nPhung kon se jễ nsoh ao ueh reh, rbăn nau chrêk lơp rêp ƀlêp,\nMaak gŭ rêh chrêk rmah tâm Ƀon Mbỡ, rbăn nau mprơ tâm Ƀon Ueh.\nMprơ yor: \"Chrêk lơp, chrêk lơp, Mbỡ kloh ueh khư nau chrêk lơp!\"\n\nVerse 3\nYor Yê-su Krist hoch jêh mham khlay, ƀư ăn nuyh tih dơi kloh,\nKon se jễ chroh, nau Kôranh Brah yỗ, ta neh ntu tâm Ƀon Ueh.\nMprơ yor: \"Chrêk lơp, chrêk lơp, Mbỡ kloh ueh khư nau chrêk lơp!\"\n\nVerse 4\nKon se kăl-e rŏng ma Kôranh Brah, măng nâm nar joi nau kloh,\nNgăn yơh muh măt Kon Biêp nâm kao, ueh maak mprơ tâm Ƀon Ueh.\nMprơ yor: \"Chrêk lơp, chrêk lơp, Mbỡ kloh ueh khư nau chrêk lơp!\"\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0173", "title": "NGIH HAĐĂCH MA LA", "song_number": "173", "lyrics": "NGIH HAĐĂCH MA LA\n\nTC 82 (Tĭng Nau Mprơ Ơm 45:8)\n\nVerse 1\nUănh ao Kôranh Brah bêng n'hôl ƀâu kah ngăn, yor nhom jêh ma dak miêr.\nN'hôl ƀâu kah tât tâm trôm nuih n'hâm gâp, nâm bu ta klơ gơl yôk.\n\nChorus\nLơi sưng Ha-đăch văch ŭch jêng nâm bunuyh dơn nau rêh ni hâu ngăn.\nYor ma nau rŏng toyh ngăn Kôranh Brah mâu chrê lơi Ƀon Hađăch.\n\nVerse 2\nUănh ao Kôranh Brah păng nhom dak ƀâu kah, Păng mâp âk nau jêr jŏt.\nDôl gâp mĭn ma si tâm rkăng Păng tuy an gâp saơ ma nau nanễ.\n\nChorus\nLơi sưng Ha-đăch văch ŭch jêng nâm bunuyh dơn nau rêh ni hâu ngăn.\nYor ma nau rŏng toyh ngăn Kôranh Brah mâu chrê lơi Ƀon Hađăch.\n\nVerse 3\nUănh ao Kôranh Brah nhom ma dak si kah, nơm ji Păng ƀư bah ro.\nDôl jâng gâp mbĭr Yê-su rđâng kuăn gâp, klaih tă bơh nau tih mhĭk.\n\nChorus\nLơi sưng Ha-đăch văch ŭch jêng nâm bunuyh dơn nau rêh ni hâu ngăn.\nYor ma nau rŏng toyh ngăn Kôranh Brah mâu chrê lơi Ƀon Hađăch.\n\nVerse 4\nNsoh ao chrêk ma lơp Yê-su plỡ tay, maak răm hom Kon Brah Ndu.\nNsoh ao nglang da-dê gay lăp Ƀon Ueh, chrêk rmah rêh maak n'ho ro.\n\nChorus\nLơi sưng Ha-đăch văch ŭch jêng nâm bunuyh dơn nau rêh ni hâu ngăn.\nYor ma nau rŏng toyh ngăn Kôranh Brah mâu chrê lơi Ƀon Hađăch.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0174", "title": "KLONG MĂNG TA GƠL YÔK Ô-LI-VE", "song_number": "174", "lyrics": "KLONG MĂNG TA GƠL YÔK Ô-LI-VE\n\nTC 89\n\nVerse 1\nKlong măng ta gơl yôk Ô-li-ve, Nơm rklaih tâm lơh êng ma nau klach\nKlong măng ta n'gar Gêt-sê-ma-nê, Nơm Tâm Rklaih gŭ mbơh sơm rêh ni.\n\nVerse 2\nKlong măng Kôranh Brah gŭ nhhiăng nhĭm, yor lah nau tih bu Păng hoch mham\nnđâp oh mon Păng rŏng âk hâu ngăn mâu saơ ôh nau Kôranh Brah Păng nhhiăng nhĭm.\n\nVerse 3\nKlong măng yor Păng anh nau tih bunuyh, tât mham Păng hoch dơn \"Nau nđêh nji\"\nnđâp lah Yê-su dơn nau ji ngăn, yor ma nau rŏng Păng lơi Ƀon Ueh.\n\nVerse 4\nKlong măng ngơt rngơi tông mpăr klơ trôk, mprơ tâm rnê hom ma nau răm rhơn\nta neh ntu mâu geh nơm gĭt rbăng, ƀư nau maak ma Kôranh Brah Yê-su.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0175", "title": "GÊT-SÊ-MA-NÊ", "song_number": "175", "lyrics": "GÊT-SÊ-MA-NÊ\n\nTC 96\n\nVerse 1\nGêt-sê-ma-nê măng ngo vêt vê, nau mĭn gâp kah gĭt rvê,\ndak rhal nâm mham êng Păng tâm lơh, Yê-su mâu rdja nuih ôh.\n\nChorus\nGêt-sê-ma-nê! Gêt-sê-ma-nê! Nau mĭn gâp kah gĭt mro,\nuănh ma Yê-su dôl klong măng Păng, mbơh sơm ma lĕ nuih n'hâm.\n\nVerse 2\nDôl gŭ du huê, klong măng ngo klĕng, ƀât lât ta nây gâp kah,\nyor ma nau tih gâp Krist nđêh nji tuy an lĕ nau tih gâp.\n\nChorus\nGêt-sê-ma-nê! Gêt-sê-ma-nê! Nau mĭn gâp kah gĭt mro,\nuănh ma Yê-su dôl klong măng Păng, mbơh sơm ma lĕ nuih n'hâm.\n\nVerse 3\nLah nuih n'hâm gâp dun Brah Yê-su, mâu geh chăt nkŭr jŭr kao,\ndăn ăn dơi saơ Gêt-sê-ma-nê, ntŭk Brah Krist khĭt ntrok gâp.\n\nChorus\nGêt-sê-ma-nê! Gêt-sê-ma-nê! Nau mĭn gâp kah gĭt mro,\nuănh ma Yê-su dôl klong măng Păng, mbơh sơm ma lĕ nuih n'hâm.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0176", "title": "BRAH YÊ-SU NDĂ TUY SI TÂM RKĂNG", "song_number": "176", "lyrics": "BRAH YÊ-SU NDĂ TUY SI TÂM RKĂNG\n\nTC 100\n\nVerse 1\nBrah Yê-su ndă tuy si tâm rkăng, yor nuyh djơh mhĭk Păng sân săk jăn,\nnhhơr lĕ nau yỗ ăn nau kon me, tâm rnê Yê-su Nơm rŏng he.\n\nChorus\nRklaih bunuyh Păng tuy si tâm rkăng. Gay rgâl gâp Păng sân săk jăn.\nGâp mâu gĭt nau Păng rŏng gâp, ma nau Păng yỗ khlay jru ngăn.\n\nVerse 2\nƠ Kôranh Brah mâm ƀư May n'hŭch ir nđêh nji hâu ngăn bu mưch rmot May,\nta si tâm rkăng, May maak bu pâng, yor gay chuai gâp ma mham May.\n\nChorus\nRklaih bunuyh Păng tuy si tâm rkăng. Gay rgâl gâp Păng sân săk jăn.\nGâp mâu gĭt nau Păng rŏng gâp, ma nau Păng yỗ khlay jru ngăn.\n\nVerse 3\nMa mham May hoch nuih n'hâm gâp kloh ăn nau ueh lăng ƀa-ƀơ n'ho ro,\ngâp nhhơr săk jăn, huêng ma Yê-su, nkoch Amoh Kôranh Nơm Tâm Rklaih he.\n\nChorus\nRklaih bunuyh Păng tuy si tâm rkăng. Gay rgâl gâp Păng sân săk jăn.\nGâp mâu gĭt nau Păng rŏng gâp, ma nau Păng yỗ khlay jru ngăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0177", "title": "HA-LÊ-LU-YA KÔRANH BRAH LĔ RÊH JÊH", "song_number": "177", "lyrics": "HA-LÊ-LU-YA KÔRANH BRAH LĔ RÊH JÊH\n\nTC 106\n\nVerse 1\nHa-lê-lu-ya! Ha-lê-lu-ya! Ha-lê-lu-ya!\nLĕ rngôch nau brah tâm lơh lôch jêh. Kôranh Brah rêh geh nau lư n'găr\nMprơ hom he ma nau răm maak đăp mpăn. Ha-lê-lu-ya!\n\nVerse 2\nHa-lê-lu-ya! Ha-lê-lu-ya! Ha-lê-lu-ya!\nPhung brah mhĭk ƀư rŭng răng, mhĭk blem. Nau Brah khân Păng Brah Krist ƀư\nrai jêh he tâm rnê ma nau răm maak. Ha-lê-lu-ya!\n\nVerse 3\nHa-lê-lu-ya! Ha-lê-lu-ya! Ha-lê-lu-ya!\nLĕ rngôch djơh mhĭk rngot rvê rlau jêh. Păng luh bơh môch dơi đah nau\nkhĭt Yê-su jêng Kôranh khlay ir ar ngăn. Ha-lê-lu-ya!\n\nVerse 4\nHa-lê-lu-ya! Ha-lê-lu-ya! Ha-lê-lu-ya!\nRse rvăk brah mhĭk lĕ nklỡ mpông pêr. Tâm Ƀon Ueh mâu geh nau bu\nbuay he mprơ huy mbơh ma Yê-su dơi. Ha-lê-lu-ya!\n\nVerse 5\nHa-lê-lu-ya! Ha-lê-lu-ya! Ha-lê-lu-ya!\nƠ Brah Yê-su yor ntŭk sôt May. Mpôch nau khĭt hên dơi sŏk lĕ\njêh hên dơi rêh ngăn, hên mprơ tâm rnê. Ha-lê-lu-ya!\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0178", "title": "YÊ-SU PLỠ VĂCH", "song_number": "178", "lyrics": "YÊ-SU PLỠ VĂCH\n\nTC 119\n\nVerse 1\nNăng ai bơh ơm ôi, nau ang du nar mra tâm mpơl.\nLĕ nau ndâp dơi ntoh, ƀư rai lĕ nau ngo neh ntu.\nYê-su mra plỡ văch. Djôt ndrel nau chrêk rmah Păng, rhơn phung chroh klaih jêh bơh neh ntu.\n\nChorus\nƠ ndah jŏ Yê-su Krist plỡ văch? Gâp mprơ tâm rnê Amoh Păng:\n\"Yê-su chrêk rmah Ha-lê-lu-ya! Ha-lê-lu-ya A-men, Ha-lê-lu-ya A-Men\".\n\nVerse 2\nMbu nơm dơi gĭt mông, nar nklang bôk mâu lah n'gul măng.\nTrôk neh ntu hôm ngo, kon bu-nuyh bêch tâm neh ntu.\nɃât lât bơh klơ trôk. Mpơl nau Brah chrêk rmah Păng, rhơn phung chroh klaih jêh bơh neh ntu.\n\nChorus\nƠ ndah jŏ Yê-su Krist plỡ văch? Gâp mprơ tâm rnê Amoh Păng:\n\"Yê-su chrêk rmah Ha-lê-lu-ya! Ha-lê-lu-ya A-men, Ha-lê-lu-ya A-Men\".\n\nVerse 3\nRmưn rsen mpôl phung chroh, jŭm bri văr neh ntu mprơ ktang.\nRmưn rsen tông mpăr ueh, dâk kêng sưng Ha-đăch dêh rhêt.\nYê-su mra plỡ văch. Bêng nau chrêk rmah nchrat ang, rhơn phung chroh klaih jêh bơh neh ntu.\n\nChorus\nƠ ndah jŏ Yê-su Krist plỡ văch? Gâp mprơ tâm rnê Amoh Păng:\n\"Yê-su chrêk rmah Ha-lê-lu-ya! Ha-lê-lu-ya A-men, Ha-lê-lu-ya A-Men\".\n\nVerse 4\nƠ maak răm hâu ngăn, nau khĭt ôm mâu hôm geh ôh.\nNau rêh ni, ji kuet, nau nhhiăng nhĭm, nau rngot rai jêh.\nNar Yê-su plỡ văch. Bêng nau chrêk rmah klơ trôk, rhơn phung chroh klaih jêh bơh neh ntu.\n\nChorus\nƠ ndah jŏ Yê-su Krist plỡ văch? Gâp mprơ tâm rnê Amoh Păng:\n\"Yê-su chrêk rmah Ha-lê-lu-ya! Ha-lê-lu-ya A-men, Ha-lê-lu-ya A-Men\".\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0179", "title": "HA-LÊ-LU-YA KÔRANH BRAH PLỠ VĂCH", "song_number": "179", "lyrics": "HA-LÊ-LU-YA KÔRANH BRAH PLỠ VĂCH\n\nTC 120\n\nVerse 1\nRi Yê-su hŏ khĭt yor kon bunuyh, aƀaơ dôl gŭ tâm trôk plỡ văch.\nRmưn rsen phung chroh văch ndrel ma Păng, mât ton ma Kôranh Brah Nơm klơ.\nHa-lê-lu-ya Păng văch jêng Ha-đăch neh ntu. Ha-lê-lu-ya păng văch jêng Ha-đăch neh ntu.\n\nVerse 2\nLĕ neh ntu mra saơ Păng n'hêl nanễ, khư nau chrêk rmah jêh ri Brah.\nPhung rlăng kăl e ntâp Păng ma tak, mưch rmot Păng jêh ri pâng Păng.\nKhân păng nhĭm nhhiăng vơl vơh saơ Kôranh Brah plỡ văch. Khân păng nhĭm nhhiăng vơl vơh saơ Kôranh Brah plỡ văch.\n\nVerse 3\nLĕ rngôch ndơ rhăk njêng nđâp dak mƀŭt, trôk neh ntu mra rai roh đŏng.\nPhung rlăng păng mra klach hâu ngăn ngên, yor lah tăng bâr nŭng kuăl rƀŭn.\nVăch pa năp ngih Kôranh phat dôih lĕ rngôch bunuyh tih. Văch pa năp ngih Kôranh phat dôih lĕ rngôch bunuyh tih.\n\nVerse 4\nA-men lĕ rngôch bunuyh mbah ma Păng, Păng gŭ tâm nau chrêk ma lơp.\nƠ Kôranh Brah ma nau Brah khlay ngăn, mât uănh neh ntu tât n'ho ro.\nƠ văch gơnh oi Kôranh Brah Nơm klơ văch gơnh oi. Ơ văch gơnh oi Kôranh Brah Nơm klơ, văch gơnh oi.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0180", "title": "BRAH YÊ-SU VĂCH JÊH", "song_number": "180", "lyrics": "BRAH YÊ-SU VĂCH JÊH\n\n\nVerse 1\nBrah Yê-su văch jêh, drŏh lơi nau chrêk rmah Păng.\nYor Păng rŏng tâm rklaih bunuyh. Rgăn n'gar ndrôk ntŭk ƀỡ ƀơch.\nDơn nau bu gơm mưch mâu geh ôh ŭch rlăm uănh.\nNơm dơn nau krit ma yor may. Jêh ri gâp,\n\nChorus\nKôranh Brah Nơm gâp rŏng khư ăn gâp klach yơk!\nMa yor huêng gâp rêh jêh n'ho tâm Păng.\nNđâp Păng rhăk neh ntu Păng mâp ntrok gâp dơn nau krĭt dơm dam, jêng bôk nau rêh gâp.\n\nVerse 2\nPăng rŏng mâu blau dŭt, nau yỗ khư he tâm rnê,\nma yor n'dâr nau ngo nkŭm. Âk rmưn rsen bunuyh roh jêh.\nPăng sâm săk ŭch cha lơi nau chrêk rmah tâm trôk.\nDơn nau bêk khĭt ma yor may. Jêh ri gâp,\n\nChorus\nKôranh Brah Nơm gâp rŏng khư ăn gâp klach yơk!\nMa yor huêng gâp rêh jêh n'ho tâm Păng.\nNđâp Păng rhăk neh ntu Păng mâp ntrok gâp dơn nau krĭt dơm dam, jêng bôk nau rêh gâp.\n\nVerse 3\nMprơ maak răm hom he, mprơ nteh hom lam neh ntu.\nBu deh jêh ma Kôranh Brah. Geh săk jăn nâm bu he.\nTâm rnê Kon Brah Ndu Păng jŭr deh ntŭk ƀỡ ƀơch.\nLơi Ƀon Ueh Păng ma yor may. Jêh ri gâp,\n\nChorus\nKôranh Brah Nơm gâp rŏng khư ăn gâp klach yơk!\nMa yor huêng gâp rêh jêh n'ho tâm Păng.\nNđâp Păng rhăk neh ntu Păng mâp ntrok gâp dơn nau krĭt dơm dam, jêng bôk nau rêh gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0181", "title": "KÂP GÂN NAU YỖ YÊ-SU", "song_number": "181", "lyrics": "KÂP GÂN NAU YỖ YÊ-SU\n\nTC 203\n\nVerse 1\nNgăn may ŭch kâp gân nau yỗ Yê-su mbêng ler may ma nau Brah tâm nuih n'hâm, nau rêh lĕ bơh?\nPô nây ăn may tông nâm bu nau ngơi lah jêh tâm sam-ƀŭt aơ, ăn ma lĕ rngôch bunuyh gĭt Păng.\n\nChorus\nN'hêl na-nễ Păng mra mbêng ler may ma nau Brah Păng, nâm tâm sam-ƀŭt Păng lah jêh, sŏk dơn hom, lĕ nau Ngơi Păng.\nN'hêl nễ nau Brah Păng mra gŭ tâm nuih n'hâm may mro, nau rêh mra geh nau ƀŭn ro.\n\nVerse 2\nƠ phung chroh nar aơ gơnh nhhơr ma Kôranh Brah nuih n'hâm kloh sŏng srăng, hŏ rao jêh ma mham Yê-su.\nChon mon êp kêng Păng ay may lơi nhhuach nhhơr ăn ma Păng, kâp uănh, Păng mra mbêng, may ma nau Brah.\n\nChorus\nN'hêl na-nễ Păng mra mbêng ler may ma nau Brah Păng, nâm tâm sam-ƀŭt Păng lah jêh, sŏk dơn hom, lĕ nau Ngơi Păng.\nN'hêl nễ nau Brah Păng mra gŭ tâm nuih n'hâm may mro, nau rêh mra geh nau ƀŭn ro.\n\nVerse 3\nPăng ăn nau rêh n'ho ro mâu blau rai yot mâu blau lôch bôl ôh, nau Ngơi Păng mâu blau rgâl ôh.\nPăng ăn nđâp nau Brah, nau dơi nâm bu Nau Ngơi tâm sam-ƀŭt aơ, gay tâm rklaih lĕ rngôch phung he.\n\nChorus\nN'hêl na-nễ Păng mra mbêng ler may ma nau Brah Păng, nâm tâm sam-ƀŭt Păng lah jêh, sŏk dơn hom, lĕ nau Ngơi Păng.\nN'hêl nễ nau Brah Păng mra gŭ tâm nuih n'hâm may mro, nau rêh mra geh nau ƀŭn ro.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0182", "title": "YÊ-SU MRA MÂT MƠH", "song_number": "182", "lyrics": "YÊ-SU MRA MÂT MƠH\n\nTC 351\n\nVerse 1\nLah ăp ntŭk geh nau nchrat ang aƀaơ, kan dỡ Krist plỡ văch mât mơh mro;\nɃon Bri Hađăch Păng puăn njŏnh chon mbah, ntŭk hôm khay pôch mâu lah bŏng khay.\n\nVerse 2\nMbơh sơm ƀa-ƀơ pa-năp sưng Hađăch, nhhơr âk nau mprơ chrêk rmah yơk\nPăng tâm Amoh Krist nđâp ndơ nhhơr ơm ôi, nhhơr ndơ ƀâu kah tât Ƀon Ueh klơ.\n\nVerse 3\nLĕ phung ƀon lan lam bri neh ntu, nau rŏng bơh Krist mprơ răm rhơn\nphung kon se jễ ma nau ngơi rdỡ mbơh, nau yỗ Kôranh Brah ma nau răm maak.\n\nVerse 4\nBunuyh bu krŭng mprơ maak rse rvăk klah, tâm Krist mât uănh nau yỗ dŭt n'hâm\nnơm rgănh rgônh dơi gŭ rlu n'ho ro, phung kon o-ach dơi gŭ ueh maak.\n\nVerse 5\nLĕ rngôch phung bunuyh lam bri neh ntu, yơk tâm rnê Hađăch kloh ueh n'ho ro\nTông mpăr ueh klơ trôk mprơ tâm rnê, bunuyh ta neh ntu mprơ bâr huy \"Amen!\"\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0183", "title": "MPRƠ MA NAU VAY YÊ-HÔ-VA", "song_number": "183", "lyrics": "MPRƠ MA NAU VAY YÊ-HÔ-VA\n\nTC 155\n\nVerse 1\nNau vay Yê-hô-va jêng khlay ngăn. Păng ăn dâk rêh jêh huêng gâp.\nNau vay Yê-hô-va mbơh n'hêl nễ. Păng ăn gĭt mĭn ma phung rluk.\n\nChorus\nMâu geh nau neh ntu jêng khlay lơn. Ma nau Yê-hô-va hŏ ngơi.\nGâp răm maak gĭt rbăng nau vay May. Nau Brah Ndu Ngơi ueh ngăn ngên.\n\nVerse 2\nNau Yê-hô-va lah jêng di ngăn. Păng ƀư maak nuih n'hâm phung he.\nNau vay Yê-hô-va jêng kloh rsang. Păng ƀư ang nau mĭn nuih n'hâm.\n\nChorus\nMâu geh nau neh ntu jêng khlay lơn. Ma nau Yê-hô-va hŏ ngơi.\nGâp răm maak gĭt rbăng nau vay May. Nau Brah Ndu Ngơi ueh ngăn ngên.\n\nVerse 3\nGâp hŏ nti nau vay Yê-hô-va. Gâp prăp tâm nuih n'hâm nau mĭn.\nNau Yê-hô-va Ngơi jêng Brah ngăn. Hŏ ƀư kloh nuih n'hâm huêng gâp.\n\nChorus\nMâu geh nau neh ntu jêng khlay lơn. Ma nau Yê-hô-va hŏ ngơi.\nGâp răm maak gĭt rbăng nau vay May. Nau Brah Ndu Ngơi ueh ngăn ngên.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0184", "title": "KANŎNG YÊ-SU JÊNG NTŬK NAU RÊH", "song_number": "184", "lyrics": "KANŎNG YÊ-SU JÊNG NTŬK NAU RÊH\n\nTC 156\n\nVerse 1\nKnŏng Yê-su Krist jêng ntŭk nau rêh, he nkoch mbơh lư Amoh Yê-su.\nMprơ tâm rnê hom ma Păng ƀa-ƀơ, păm Păng klơ geh nau ang nchrat.\n\nChorus\nYê-su jêng Nơm tâm rklaih, lư Amoh Păng jêng Hađăch toyh khlay ngăn ngên.\nPăng sâm ntĭm nti he âk nau gŭ rêh, tâm rnê Amoh Kôranh Brah dŭt toyh.\n\nVerse 2\nKnŏng Yê-su Krist jêng Kôranh Brah he, Păng anh lĕ nau tih phung he.\nPăng n'hŭch êng săk jêng bunuyh dĭk bu, gay lư n'găr Amoh Brah Yê-su.\n\nChorus\nYê-su jêng Nơm tâm rklaih, lư Amoh Păng jêng Hađăch toyh khlay ngăn ngên.\nPăng sâm ntĭm nti he âk nau gŭ rêh, tâm rnê Amoh Kôranh Brah dŭt toyh.\n\nVerse 3\nKnŏng Yê-su Krist dơm geh nau Brah, Păng dơi rao kloh nau tih he.\nma mham Păng hoch ta si tâm rkăng, nuih n'hâm maak rŏng mprơ hâu ngăn.\n\nChorus\nYê-su jêng Nơm tâm rklaih, lư Amoh Păng jêng Hađăch toyh khlay ngăn ngên.\nPăng sâm ntĭm nti he âk nau gŭ rêh, tâm rnê Amoh Kôranh Brah dŭt toyh.\n\nVerse 4\nKnŏng Yê-su Krist lư Amoh lam bri, dơn nau nđêh nji yor phung he.\nTa ntŭk bu pâng Păng klơ dŭt prêh, mham hoch lam săk dơi dâk rêh.\n\nChorus\nYê-su jêng Nơm tâm rklaih, lư Amoh Păng jêng Hađăch toyh khlay ngăn ngên.\nPăng sâm ntĭm nti he âk nau gŭ rêh, tâm rnê Amoh Kôranh Brah dŭt toyh.\n\nVerse 5\nKnŏng Yê-su Krist geh nau dăng ktang, ăn nau nchrat ang ma lĕ he.\nDăn mbêng ler tâm nuih n'hâm phung hên, ma mham hoch ta si tâm rkăng.\n\nChorus\nYê-su jêng Nơm tâm rklaih, lư Amoh Păng jêng Hađăch toyh khlay ngăn ngên.\nPăng sâm ntĭm nti he âk nau gŭ rêh, tâm rnê Amoh Kôranh Brah dŭt toyh.\n\nVerse 6\nKnŏng Yê-su he kâp gân ƀa-ƀơ, tĭng nteh bâr nŭng Păng jŭr văch.\nPăng dôl gŭ dăch kêng he mro mrăng, n'ho jêng Hađăch lam bri neh ntu.\n\nChorus\nYê-su jêng Nơm tâm rklaih, lư Amoh Păng jêng Hađăch toyh khlay ngăn ngên.\nPăng sâm ntĭm nti he âk nau gŭ rêh, tâm rnê Amoh Kôranh Brah dŭt toyh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0185", "title": "YÊ-SU KUĂL LĔ RNGÔCH BUNUYH", "song_number": "185", "lyrics": "YÊ-SU KUĂL LĔ RNGÔCH BUNUYH\n\nTC 160\n\nVerse 1\nYê-su dôl geh nau yỗ ŭch kuăl lĕ rngôch bunuyh, kuăl ay may sĭt hom aƀaơ ro;\nPăng dôl kâp ta mpông Ƀon Ueh gay vơt he mro, Păng kâp gân gay vơt he ro.\n\nChorus\nSĭt gơnh lơi iăng mbu hŏt rgănh gơnh ran ma Păng.\nYê-su dôl geh nau yỗ ŭch kuăl lĕ rngôch bunuyh, geh lĕ mbu nơm ŭch sĭt aƀaơ\n\nVerse 2\nMâm Yê-su kuăl sĭt ƀiă lah ăt hôm vât vâng? kuăl ay may sĭt gơnh aƀaơ ro;\nMâm ƀư hôm vât vâng dĭng ê dơn nau yỗ aƀaơ, Păng kâp he bơh jŏ ngăn jêh.\n\nChorus\nSĭt gơnh lơi iăng mbu hŏt rgănh gơnh ran ma Păng.\nYê-su dôl geh nau yỗ ŭch kuăl lĕ rngôch bunuyh, geh lĕ mbu nơm ŭch sĭt aƀaơ\n\nVerse 3\nNâm bu rvah drăng khâng nar khlay mâu kâp he ôh, sĭt hom he geh nau tâm rklaih?\nNau tih mhĭk nchueng jŭm, ƀât lât mâu gĭt năn njrăng, mâm phung tih dơi der rêh ni.\n\nChorus\nSĭt gơnh lơi iăng mbu hŏt rgănh gơnh ran ma Păng.\nYê-su dôl geh nau yỗ ŭch kuăl lĕ rngôch bunuyh, geh lĕ mbu nơm ŭch sĭt aƀaơ\n\nVerse 4\nMa nau rŏng jru khlay Păng tâm rklaih lĕ nau tih, yor nau Păng yỗ jêh ma he;\nPăng ăt rŏng nđâp lah he ƀỡ ƀơch bêng tih mhĭk, yor nsing na-nễ dơi jêng kloh.\n\nChorus\nSĭt gơnh lơi iăng mbu hŏt rgănh gơnh ran ma Păng.\nYê-su dôl geh nau yỗ ŭch kuăl lĕ rngôch bunuyh, geh lĕ mbu nơm ŭch sĭt aƀaơ\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0186", "title": "ĂN PĂNG LĂP", "song_number": "186", "lyrics": "ĂN PĂNG LĂP\n\nTC 167\n\nVerse 1\nGeh du huê gŭ êp kêng mpông. Ăn Păng lăp. Păng gŭ kâp ta aơ jŏ jêh. Ăn Păng lăp.\nJă Păng lăp ê lor Păng hăn, yor Păng lăp ro yor lah Yê-su Krist jêng Kon Brah Ndu Nơm. Ăn Păng lăp.\n\nVerse 2\nPơk hom nuih n'hâm may ma Păng. Ăn Păng lăp. Lah may vât vâng Păng mra hăn. Ăn Păng lăp.\nĂn Păng lăp jêng mĭt jiăng may, Păng Nơm mra sâm king huêng may, Păng mra mât mơh may n'ho ro. Ăn Păng lăp.\n\nVerse 3\nPăng ŭch tăng bâr may a-ƀơ. Ăn Păng lăp. A-ƀaơ ăn may săch ngăn Păng. Ăn Păng lăp.\nPăng gŭ kâp ta meng mpông may, Păng ăn đŏng nau maak ma may, Amoh Păng nây may mra tâm rnê. Ăn Păng lăp.\n\nVerse 4\nĂn Păng lăp tâm nuih n'hâm aƀaơ. Ăn Păng lăp. Păng mra ƀư ma may nau maak. Ăn Păng lăp.\nPăng mra yỗ an nau tih may, lah kan neh ntu hŏ lĕ jêh, Păng mra chông leo may ta klơ. Ăn Păng lăp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0187", "title": "RI, MPÔNG TÂM RKLAIH", "song_number": "187", "lyrics": "RI, MPÔNG TÂM RKLAIH\n\nTC 179\n\nVerse 1\nRi, mpông tâm rklaih he lăp đăp mpăn. Mâu khăch gŭ goh mpông nar măng ôh;\nYor lah mpông nây lĕ ơm pơk jêh. Dôl kâp gân ay may lăp gơnh oi.\n\nChorus\nRi, dak krong rêh hoch mro puăn yăn, bunuyh văch nhêt mâu khăch rvăt;\nTu dak nây hŏ luh jêh bơh klơ trôk, jă ay may nhêt hom n'hanh ma gâp.\n\nVerse 2\nMâu kâp he dăn nau dăng ktang mơ. Mông aơ ma nuih n'hâm rnơm lăp hom;\nTông ma Brah Ndu Păng ăn Huêng Brah. Ăn nuih n'hâm kloh ueh maak mro mrăng.\n\nChorus\nRi, dak krong rêh hoch mro puăn yăn, bunuyh văch nhêt mâu khăch rvăt;\nTu dak nây hŏ luh jêh bơh klơ trôk, jă ay may nhêt hom n'hanh ma gâp.\n\nVerse 3\nLơi mĭn ôh Kôranh Brah mâu iăt he. Nuih n'hâm lơi vĭ mâu lah vât vâng;\nYor Kôranh Brah lah mbu nsing ma Păng. Dăn dĭng geh, joi hom dĭng saơ ro.\n\nChorus\nRi, dak krong rêh hoch mro puăn yăn, bunuyh văch nhêt mâu khăch rvăt;\nTu dak nây hŏ luh jêh bơh klơ trôk, jă ay may nhêt hom n'hanh ma gâp.\n\nVerse 4\nĂn he rgâl nau dăn jêng nau mprơ. Dơn hom mâm nau Yê-su ntăm jêh;\nMbu nơm dŏng mbơh sơm ma Amoh gâp. Mra bêng nau ueh, nau yỗ klơ trôk.\n\nChorus\nRi, dak krong rêh hoch mro puăn yăn, bunuyh văch nhêt mâu khăch rvăt;\nTu dak nây hŏ luh jêh bơh klơ trôk, jă ay may nhêt hom n'hanh ma gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0188", "title": "YÊ-SU GÂP VĂCH", "song_number": "188", "lyrics": "YÊ-SU GÂP VĂCH\n\nTC 180, KMM 122, Mrô hđăp 97\n\nVerse 1\nKlaih bơh rse rvăk rêh ni ji nglâng ngăn, Yê-su gâp văch, Yê-su gâp văch;\nlăp ntŭk đăp mpăn geh nau nchrat ang ngăn, Yê-su gâp văch tĭng May;\ngâp ji kuet tât ma May dơi ƀư bah, gâp ndĭt trơi ƀiă lah ăt May kơl an,\nlĕ nau tih mhĭk dăn ma May yỗ an, Yê-su gâp văch tĭng May.\n\nVerse 2\nLuh bơh nau ngo djơh mhĭk ƀỡ ƀơch ngăn, Yê-su gâp văch, Yê-su gâp văch;\nta si tâm rkăng Păng bêng nau chrat ang, Yê-su gâp văch tĭng May;\nta ntŭk nđêh nji tâm May bêng nau rŏng, mprơh lĕ djơh mhĭk tĭng May đăp mpăn mro,\nmâu hôm rngot rvê tĭng nau mprơ ơm lah, Yê-su gâp văch tĭng May.\n\nVerse 3\nLuh bơh nau rêh bu mưch rmot hâu ngăn; Yê-su gâp văch, Yê-su gâp văch;\nnau rŏng May jru ngăn prêh nâm klơ trôk, Yê-su gâp văch tĭng May;\ntă bơh nau mhĭk nuih n'hâm bêng nau yỗ, nđâp lah hươi rdja ăt geh nau kâp gân,\nnâm bu plŭk kloh mpăr hao klơ Ƀon Ueh, Yê-su gâp văch tĭng May.\n\nVerse 4\nLuh bơh trôm môch krit klach râm sâr ngăn, Yê-su gâp văch, Yê-su gâp văch;\ntâm Ƀon Ueh Păng klơ geh nau ang nchrang, Yê-su gâp văch tĭng May;\nluh bơh neh ntu bêng nau tih djơh mhĭk, tâm n'gar biăp Kôranh Brah geh nau rêh mro,\nuănh muh măt Păng nchrat ang lơp rêp ƀlêp, Yê-su găp văch tĭng May.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0189", "title": "KRONG DƠI RAO NAU TIH MHĬK", "song_number": "189", "lyrics": "KRONG DƠI RAO NAU TIH MHĬK\n\nTC 192\n\nVerse 1\nRi gâp saơ dak krong jru huy ngăn, dơi jut rao nau tih gâp;\nYê-su chuai gâp ma mham khlay Păng hoch tă bơh si tâm rkăng.\n\nChorus\nUănh ueh dak krong ri jut nau tih, gâp ŭm ta nây dơi jêng kloh ro;\ntâm rnê Yê-su ma mham khlay Păng, gâp ŭch jêng kloh gay dơi kloh ro.\n\nVerse 2\nNtơm bơh gâp chuat tĭng trong nau ang, cha lơi nau tih neh ntu;\naƀaơ Păng ăn nuih n'hâm gâp đăp mpăn yor Păng gŭ êp gâp ngăn.\n\nChorus\nUănh ueh dak krong ri jut nau tih, gâp ŭm ta nây dơi jêng kloh ro;\ntâm rnê Yê-su ma mham khlay Păng, gâp ŭch jêng kloh gay dơi kloh ro.\n\nVerse 3\nGâp gĭt ma mham Brah Păng khlay ngăn ta neh ntu nâm klơ trôk;\nknŏng Yê-su dơm jêng Nơm tâm rklaih, yor Păng khĭt rgâl gâp jêh.\n\nChorus\nUănh ueh dak krong ri jut nau tih, gâp ŭm ta nây dơi jêng kloh ro;\ntâm rnê Yê-su ma mham khlay Păng, gâp ŭch jêng kloh gay dơi kloh ro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0190", "title": "NTŬK HE NSING", "song_number": "190", "lyrics": "NTŬK HE NSING\n\n\nVerse 1\nTâm Păng jêng ntŭk he nsing. Păng văch gay rklaih tâm huêng rngot jêr.\nNđâp nau rêh đêh nji nuih n'hâm aơ âk tỡ nhop kro n'gân nau chroh tâm Păng.\nNsing nâp tâm Păng mro hơi nuih n'hâm rngot ji kâp gân tâm Kôranh he jêng ntŭk he nsing\n\nVerse 2\nNđâp lah nau rêh roh rai. Nau Păng jêng bâr mprơ tâm nuih n'hâm.\nPăng ăt văch êp gâp nđâp lah âk tỡ gâp krit kir vĭ trong tâm n'gul măng.\nBâr rdỡ rbăn nkah nti kơl gâp dơi nâp rjăp kâp gân tâm Kôranh he jêng ntŭk he nsing, n'gân nau chroh tâm Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0191", "title": "NAU RĂP-JĂP MAY TOYH LƠN", "song_number": "191", "lyrics": "NAU RĂP-JĂP MAY TOYH LƠN\n\nTC 43\n\nVerse 1\nNau răp-jăp May toyh lơn, Brah Ndu jêng Mbỡ gâp. Mâu geh rai lôch ôh, May jêng mro mrăng ngăn\nmâu rgâl ôh, nau rŏng May mâu blau lôch bôl. Ntơm sa ơm nar aơ ôi taơ May hôm n'ho ro\n\nChorus\nNau răp-jăp May toyh ngăn! Nau răp-jăp May toyh ngăn! Ăp ôi gâp saơ nau yỗ May mhe ƀa-ƀơ.\nLĕ ndơ gâp pưt, May Nơm ăn rmeh ler ma gâp. Nau răp-jăp May toyh lơn tâm gâp ngăn ngên.\n\nVerse 2\nYăn vai, yăn puh jêh ri, yăn kao nđâp yăn mih. Khay mănh mbing nar ndăch ƀa-ƀơ ta klơ trôk\nndăch ndrel ma lĕ rngôch ndơ gay mbơh ma bu-nuyh, Păng bêng nau rŏng, nau yỗ răp-jăp n'ho ro.\n\nChorus\nNau răp-jăp May toyh ngăn! Nau răp-jăp May toyh ngăn! Ăp ôi gâp saơ nau yỗ May mhe ƀa-ƀơ.\nLĕ ndơ gâp pưt, May Nơm ăn rmeh ler ma gâp. Nau răp-jăp May toyh lơn tâm gâp ngăn ngên.\n\nVerse 3\nNuih n'hâm gâp maak hâu ngăn, nau tih dơi tâm rklaih. Yor nau yỗ Mbỡ Păng mât uănh têk ndrêng he\ngay geh ktang mhe, nđâp nau kâp gân nar kăn-dỡ, nuih n'hâm gâp rhơn ƀa-ƀơ maak răm hâu ngăn\n\nChorus\nNau răp-jăp May toyh ngăn! Nau răp-jăp May toyh ngăn! Ăp ôi gâp saơ nau yỗ May mhe ƀa-ƀơ.\nLĕ ndơ gâp pưt, May Nơm ăn rmeh ler ma gâp. Nau răp-jăp May toyh lơn tâm gâp ngăn ngên.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0192", "title": "PĂNG PƯ NCHÔNG GÂP", "song_number": "192", "lyrics": "PĂNG PƯ NCHÔNG GÂP\n\n\nVerse 1\nDôl mâp nau tât nuih n'hâm âk nau rŭng răng. Dôl geh nau rngot nuih n'hâm geh nau jâk jêr. Jêh nây gâp ăt gŭ kâp gân tâm nau klăk klêm. Kŏ tât Kôranh Brah gŭ ndrel bonh leng huêng gâp.\n\nChorus\nPăng pư nchông gâp gay dơi gŭ tâm ntŭk prêh ka-lơ. Păng pư nchông gâp dơi rgăn phŭt sial toyh kuăng. Gâp dăng ktang dôl mbe tâm săng nglik Kôranh Brah. Păng pư nchông gâp rlau lơn ma gâp ŭch.\nPăng pư nchông gâp gay dơi gŭ tâm ntŭk prêh klơ. Păng pư nchông gâp dơi rgăn phŭt sial toyh kuăng. Gâp dăng ktang dôl mbe tâm săng nglik Kôranh Brah. Păng pư nchông gâp rlau lơn ma nau gâp ŭch.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0193", "title": "PHUNG CHROH YÊ-SU MPRƠ HOM", "song_number": "193", "lyrics": "PHUNG CHROH YÊ-SU MPRƠ HOM\n\n\nVerse 1\nPhung chroh Yê-su mprơ hom. Ha-lê-lu-ya, A-men.\nMât ton ma Hađăch toyh lơn. Ha-lê-lu-ya, A-men.\nVăch ma nuih n'hâm ma-ak. Păn ta năp păng răm rhơn.\nPăng khư ma lĕ nau yơk. Ha-lê-lu-ya, A-men.\n\nVerse 2\nNhhơr lĕ nuih n'hâm ma Păng. Ha-lê-lu-ya, A-men.\nRŏng hom ma Krist Kôranh Brah. Ha-lê-lu-ya, A-men.\nPăng jêng mĭt jiăng ueh ngăn. Nơm njŭn leo he ăp nar.\nNau rŏng Păng gŭ ƀa-ƀơ. Ha-lê-lu-ya, A-men.\n\nVerse 3\nMât ton Yê-su Kôranh Brah. Ha-lĕ-lu-ya, A-men.\nTât ma nar hao Ƀon Ueh. Ha-lê-lu-ya, A-men.\nTa nây he gŭ ma Păng. Tâm nau nchrat ang đăp mpăn.\nMprơ tâm rnê Păng ƀa-ƀơ. Ha-lê-lu-ya, A-men.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0194", "title": "KÔRANH BRAH RŎNG MA BUNUYH", "song_number": "194", "lyrics": "KÔRANH BRAH RŎNG MA BUNUYH\n\n\nVerse 1\nRŏng ma yor nau rŏng ma kon bunuyh, Păng hŏ jŭr deh ntŭk o-ach, dơn nau krit jêr bu mưch rmot ma yor phung he.\nRŏng yor rŏng phung lă lêng nhhơt nhhang, nau rŏng Brah Mbỡ ăn Yê-su, dơn nau khĭt ta si tâm rkăng ntrok ăn ma he.\n\nChorus\nƠ nau rŏng Yê-su jru rlau dak mƀŭt djôt nau khlay mpơl ma lĕ rngôch bu-nuyh.\nYor rŏng phung ƀon lan Kôranh Brah maak dơn nau nđêh nji, gay kuaih lĕ tih neh ntu.\n\nVerse 2\nHơi mĭt jiăng ăn may plỡ sĭt hom, A-ƀaơ tăng nau Brah Yê-su, Păng dôl kuăl may kâp gân may, sĭt hom ma Păng.\nLơi hôm iăng huêng tâm ntŭk măng ngo, nau rêh mra jêr krit mbât ngăn, mâu geh mâp nau đăp mpăn ôh ăn ma huêng may.\n\nChorus\nƠ nau rŏng Yê-su jru rlau dak mƀŭt djôt nau khlay mpơl ma lĕ rngôch bu-nuyh.\nYor rŏng phung ƀon lan Kôranh Brah maak dơn nau nđêh nji, gay kuaih lĕ tih neh ntu.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0195", "title": "YÊ-SU MÂU GEH RGÂL", "song_number": "195", "lyrics": "YÊ-SU MÂU GEH RGÂL\n\nTC 204\n\nVerse 1\nYê-su mâu rgâl ôh, Yê-su mâu rgâl ôh\ntrôk neh ntu rlau lôch, Yê-su ăt hôm Păng mâu rgâl ôh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0196", "title": "MBU HƯƠI RDJA", "song_number": "196", "lyrics": "MBU HƯƠI RDJA\n\nTC 286\n\nVerse 1\nMbu hươi rdja nuih n'hâm ri, tâm jŭm bri văr neh; Văch chon ta sưng nau yỗ, dăn nau ueh lăng;\nMprơ nau nđêh nji tâm nuih n'hâm kloh nau rêh ni. Ta neh ntu nau ji hâu ngăn, dơi ƀư bah.\n\nVerse 2\nMbu hươi rdja gơnh oi nsing ta aơ, ueh maak ngăn; Bunuyh hiơt roh hêng dơi saơ jêh trong sĭt hom;\nNơm bonh leng ma nau rdỡ rbăn lah rah vah jêh. Ta neh ntu nau ji hâu ngăn, dơi ƀư bah.\n\nVerse 3\nNtŭk aơ jêng piăng let Brah, jêng tu dak nau rêh; Tu hoch tă bơh Kôranh Brah, kloh rsang, ueh reh;\nVăch hom nau nhêt sa toyh, ăn kah gĭt chih amoh. Ta neh ntu nau ji hâu ngăn, dơi ƀư bah.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0197", "title": "YOR NAU RŎNG YÊ-SU JŬR VĂCH", "song_number": "197", "lyrics": "YOR NAU RŎNG YÊ-SU JŬR VĂCH\n\nTC 208\n\nVerse 1\nYor ma nau rŏng Yê-su jŭr văch, gay tâm rklaih jêh ri n'hao huêng gâp, bơh ntu nau tih ƀỡ ƀơch hâu ngăn, Kôranh Brah yỗ nchông an gâp.\n\nChorus\nPăng nchông an gâp, bơh ntŭk brŏng jru, ti Păng ut r'u rklaih an huêng gâp; bơh ntŭk nau ngo n'hao klơ ntŭk prêh, tâm rnê Yê-su Nơm Tâm Rklaih gâp.\n\nVerse 2\nPăng kuăl gâp ta nôk ê năl Păng, nuih n'hâm ơm gâp bêng nau janh ƀai, ntơm gâp chroh ma nau ngơi khlay Păng, Kôranh Brah yỗ nchông an gâp.\n\nChorus\nPăng nchông an gâp, bơh ntŭk brŏng jru, ti Păng ut r'u rklaih an huêng gâp; bơh ntŭk nau ngo n'hao klơ ntŭk prêh, tâm rnê Yê-su Nơm Tâm Rklaih gâp.\n\nVerse 3\nRi Păng nhhơ ti hôm têl sôt rmanh, ta ndăr kleng Păng têl tôt môk lok, ngăn yơh gâp aơ ngâm tâm nau ngo, nau Păng rŏng nchông an gâp.\n\nChorus\nPăng nchông an gâp, bơh ntŭk brŏng jru, ti Păng ut r'u rklaih an huêng gâp; bơh ntŭk nau ngo n'hao klơ ntŭk prêh, tâm rnê Yê-su Nơm Tâm Rklaih gâp.\n\nVerse 4\nNuih n'hâm gâp aƀaơ geh nau răm maak, gŭ klơ Ƀon Ueh geh nau đăp mpăn, nđâp lah gâp blau nkoch ngơi âk ntil, tâm nau Yê-su kơl gâp.\n\nChorus\nPăng nchông an gâp, bơh ntŭk brŏng jru, ti Păng ut r'u rklaih an huêng gâp; bơh ntŭk nau ngo n'hao klơ ntŭk prêh, tâm rnê Yê-su Nơm Tâm Rklaih gâp.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0198", "title": "HĂN HOM KÔRANH BRAH DÔL KUĂL", "song_number": "198", "lyrics": "HĂN HOM KÔRANH BRAH DÔL KUĂL\n\n\nVerse 1\nYor Kôranh Brah rŏng gâp ŭch tĭng ndỗ Păng, mbah ntŭk Păng kuăl gâp ŭch hăn ro.\nNau rêh geh âk ntil kuăn tâm nuih n'hâm, tĭng Kôranh Brah gâp mƀăr lĕ nau rngot.\nPăng yơh ăn gâp dơi geh nau chrêk rmah jêh ri geh âk nau rŏng mơih rmên.\nYor Kôranh Brah rŏng gâp ŭch tĭng ndỗ Păng, Mbah ntŭk Păng kuăl gâp ŭch hăn ro.\n\nVerse 2\nNđâp geh âk nau o-ach tâm nau rêh, mâu lah geh nau rêh ni tŭn jot.\nUănh Kôranh Brah gâp bêng ma nau kâp gân, tĭng ndỗ Păng mâu geh nau klach ôh,\nYor Kôranh Brah anh lĕ rngôch nau tih gâp, anh lĕ ntrok gâp ta-si-tâm rkăng.\nYor Kôranh Brah rŏng gâp ŭch tĭng ndỗ Păng. Mbah ntŭk Păng kuăl gâp ŭch hăn ro.\n\nVerse 3\nChuat tĭng ndỗ Păng tât Gêt-sê-ma-nê, ntŭk Kôranh Brah hŏ dơn jêh nau jêr.\nChuat tĭng ndỗ Păng tât yôk Gô-gô-tha, nuih n'hâm ŭch dơn khĭt ndrel ma Păng.\nYor Kôranh Brah rŏng nau tih gâp rai jêh, yor Kôranh Brah hŏ tâm chuai jêh gâp,\nŬch nhhơr lĕ săk jăn ma Kôranh Brah Nơm, Dăn May sŏk dơn rom gâp aƀaơ ro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0199", "title": "GÂP AƠ ƠM TIH RNƠM NAU YỖ RKLAIH", "song_number": "199", "lyrics": "GÂP AƠ ƠM TIH RNƠM NAU YỖ RKLAIH\n\nTC 218\n\nVerse 1\nLĕ rngôch rbăn nau aơ yor geh Kôranh Brah klơ, ntơm chroh ma Kôranh Brah nau ueh mâu blau ntĭt,\nnau sư nau rlau nkoch nâm n'hi săk nơm. Gâp nơm aơ dơi tâm chuai bơh nau yỗ!\n\nChorus\nGâp aơ ơm tih rnơm nau yỗ rklaih! Aơ gâp ơm tih rnơm nau yỗ rklaih!\nNây jêng noi tơm gâp chrêk rmah Amoh Mbỡ ta klơ, nsing nau yỗ dơm dơi tâm chuai nau tih.\n\nVerse 2\nKăl e brŭt moih rluk mâl huêng lĕ roh rai, gâp gŭ ngai Kôranh Brah chuat tĭng trong hiơt mblêng,\naƀaơ rnơm Yê-su joi njŭn trong sŏng srăng. Gâp nơm aơ dơi tâm chuai bơh nau yỗ!\n\nChorus\nGâp aơ ơm tih rnơm nau yỗ rklaih! Aơ gâp ơm tih rnơm nau yỗ rklaih!\nNây jêng noi tơm gâp chrêk rmah Amoh Mbỡ ta klơ, nsing nau yỗ dơm dơi tâm chuai nau tih.\n\nVerse 3\nKăl e mham Yê-su hŏ rao nau tih he, nsing nau yỗ dơm dĭng dơi klaih bơh nau khĭt,\ngâp klach chrêk rmah Păng yor nau tih kât. A-ƀaơ aơ dơi tâm chuai bơh nau yỗ!\n\nChorus\nGâp aơ ơm tih rnơm nau yỗ rklaih! Aơ gâp ơm tih rnơm nau yỗ rklaih!\nNây jêng noi tơm gâp chrêk rmah Amoh Mbỡ ta klơ, nsing nau yỗ dơm dơi tâm chuai nau tih.\n\nVerse 4\nĂn he maak lĕ phung tih Kôranh Brah rŏng aơ, hăn mbơh âk ngăn nau rŏng Kôranh Brah bêng ler,\nsŏk dơn răm maak lĕ nuih n'hâm nsong mbơh. Gâp aƀaơ aơ dơi tâm chuai bơh nau yỗ!\n\nChorus\nGâp aơ ơm tih rnơm nau yỗ rklaih! Aơ gâp ơm tih rnơm nau yỗ rklaih!\nNây jêng noi tơm gâp chrêk rmah Amoh Mbỡ ta klơ, nsing nau yỗ dơm dơi tâm chuai nau tih.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0200", "title": "GEH DU HUÊ KÔRANH VĂCH MA YÊ-SU", "song_number": "200", "lyrics": "GEH DU HUÊ KÔRANH VĂCH MA YÊ-SU\n\nTC 222\n\nVerse 1\nGeh du huê Kôranh văch ma Yê-su klong măng. Păng ŭch gĭt trong ăn geh nau rêh tă bơh klơ.\nBrah Yê-su plỡ lah ma nau kloh rah vah ngăn: \"Ăn may plỡ deh mhe hom\n\nChorus\nĂn deh mhe hom nar aơ. Ăn gơnh hom nar aơ ro.\nGâp mbơh ma may nau ngăn mâu geh ngơi mƀruh ôh. Ăn deh mhe hom aƀaơ ro.\"\n\nVerse 2\nƠ lĕ rngôch bu-nuyh gơnh iăt nau ngơi aơ. Brah Yê-su lah Păng jêng Nơm ntĭm nti he ngăn.\nBâr Brah Yê-su aơ lơi ta may mưch rmot ôh. \"Ăn may plỡ deh mhe hom\n\nChorus\nĂn deh mhe hom nar aơ. Ăn gơnh hom nar aơ ro.\nGâp mbơh ma may nau ngăn mâu geh ngơi mƀruh ôh. Ăn deh mhe hom aƀaơ ro.\"\n\nVerse 3\nAƀaơ mbu ŭch gŭ rlu đăp mpăn tâm huêng Păng. Mprơ hom ma nau yỗ phung hŏ geh nau rklaih jêh.\nNar kăn dỡ may ŭch sŏk dơn nau rêh n'ho ro. \"Ăn may plỡ deh mhe hom\n\nChorus\nĂn deh mhe hom nar aơ. Ăn gơnh hom nar aơ ro.\nGâp mbơh ma may nau ngăn mâu geh ngơi mƀruh ôh. Ăn deh mhe hom aƀaơ ro.\"\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0201", "title": "AƠ NAU MPRƠ GÂP ŬCH MPRƠ ƀA-ƀƠ", "song_number": "201", "lyrics": "AƠ NAU MPRƠ GÂP ŬCH MPRƠ ƀA-ƀƠ\n\nTC 219\n\nVerse 1\nAơ nau gâp rŏng mprơ ƀa-ƀơ kăl e Yê-su khĭt rgâl gâp jêh;\nyor nau rŏng Păng cha lơi Ƀon Ueh, Gô-gô-tha Păng tâm chuai gâp.\n\nChorus\nGâp ŭch mprơ…… mprơ ndrel n'grŭp n'ho ro kăl e Yê-su…… khĭt rgâl gâp jêh……\ngâp mra mprơ ma phung kloh ueh klơ, kơh dak mƀŭt nâm nar nchrat ang……\n\nVerse 2\nPăng joi gâp, dôl gŭ ngai ma păng, nâm kon biăp nter hiơt tâm bri;\nPăng chông ut r'u gâp ma ti Păng, yor nau yỗ Păng njŭn gâp sĭt.\n\nChorus\nGâp ŭch mprơ…… mprơ ndrel n'grŭp n'ho ro kăl e Yê-su…… khĭt rgâl gâp jêh……\ngâp mra mprơ ma phung kloh ueh klơ, kơh dak mƀŭt nâm nar nchrat ang……\n\nVerse 3\nLah ji kuet, Yê-su mât mơh gâp, tơ lah geh nau hŏt rgănh âk;\nnuih n'hâm klach bar đah măt nâm chieh, yor Păng kơl, săm gâp saơ ang.\n\nChorus\nGâp ŭch mprơ…… mprơ ndrel n'grŭp n'ho ro kăl e Yê-su…… khĭt rgâl gâp jêh……\ngâp mra mprơ ma phung kloh ueh klơ, kơh dak mƀŭt nâm nar nchrat ang……\n\nVerse 4\nGeh âk râk nau ngo, nchueng jŭm gâp, nau tĭng groi gâp mâu cha lơi;\nyor geh Yê-su hăn ndrel gâp mro, nsing ma Păng đăp mpăn ngăn ro.\n\nChorus\nGâp ŭch mprơ…… mprơ ndrel n'grŭp n'ho ro kăl e Yê-su…… khĭt rgâl gâp jêh……\ngâp mra mprơ ma phung kloh ueh klơ, kơh dak mƀŭt nâm nar nchrat ang……\n\nVerse 5\nPăng njŭn gâp tât ta kơh dak ri, tâm lĕ nau jâk jêr rêh ni;\nPăng têk ndrêng gâp hăn njŏ trong Păng, ndrel ma phung geh nau rŏng toyh.\n\nChorus\nGâp ŭch mprơ…… mprơ ndrel n'grŭp n'ho ro kăl e Yê-su…… khĭt rgâl gâp jêh……\ngâp mra mprơ ma phung kloh ueh klơ, kơh dak mƀŭt nâm nar nchrat ang……\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0202", "title": "ĂN TĬNG NAU MBỠ", "song_number": "202", "lyrics": "ĂN TĬNG NAU MBỠ\n\nTC 237\n\nVerse 1\nGâp tĭng nau Mbỡ ŭch, tông ma May dơm, Mbỡ jêng Nơm mon glah, gâp jêng rchuăl uk.\nGâp tĭng nau May ŭch, dăn May mon gâp. Gâp knŏng gŭ klăk klêm, kâp tông bâr May.\n\nVerse 2\nGâp tĭng nau Mbỡ ŭch, tông ma May dơm, dăn May sek uănh gâp, rlong gâp, đăp gâp.\nDăn rao kloh nuih n'hâm rsang nglang nâm pler. Gâp chon ta jâng May nau dêh rhêt ngăn.\n\nVerse 3\nGâp tĭng nau Mbỡ ŭch, tông ma May dơm, dôl sôt rmanh lêt rgănh, May gơnh ndrêng gâp.\nLĕ nau Brah neh ntu klơ trôk mbah May. Dăn nto ti May bi gâp gay đăp mpăn.\n\nVerse 4\nGâp tĭng nau Mbỡ ŭch, tông ma May dơm, dăn May mât uănh săk jăn huêng srĭng gâp.\nMbêng ma Brah Huêng Ueh, ăn bu dơi saơ. Knŏng Yê-su Krist dơm mât nuih n'hâm aơ.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0203", "title": "SI TÂM RKĂNG ƠM JÊH RI NÂP", "song_number": "203", "lyrics": "SI TÂM RKĂNG ƠM JÊH RI NÂP\n\n\nVerse 1\nTa klơ yôk ngai đah aơ hôm du mlâm si tâm rkăng. Hôm nau mbên ma nau ji jêh ri prêng.\nƠ gâp rŏng hâu ngăn ngên, si nây ơm jêh ri nâp yor lah nơm lơn ueh khĭt ta klơ Păng.\n\nChorus\nPô ri gâp prăp si tâm rkăng ơm nâp kŏ tât nar gâp mra hao rlet ta klơ\ngâp mra kuăn rdâng ta si tâm rkăng nây tât nar gâp cha-lơi Păng dơn đon Hađăch.\n\nVerse 2\nƠ si tâm rkăng ơm nây, neh ntu tâm rmot hâu ngăn. Ƀiă lah gâp rŏng ma Păng âk hâu ngăn.\nYor lah Kon Ƀiăp Brah Ndu, cha-lơi nau chrêk rmah klơ njôt leo Păng rlet ma ntŭk kal ver ngo.\n\nChorus\nPô ri gâp prăp si tâm rkăng ơm nâp kŏ tât nar gâp mra hao rlet ta klơ\ngâp mra kuăn rdâng ta si tâm rkăng nây tât nar gâp cha-lơi Păng dơn đon Hađăch.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0204", "title": "VAH HOM PLŬNG", "song_number": "204", "lyrics": "VAH HOM PLŬNG\n\nTC 223\n\nVerse 1\nRi ngăn nau yỗ Kôranh Brah toyh nâm bu dak mƀŭt rsang ngăn lơ vơ mâu dơi ntĭt ôh.\nNcho duk ndrel phung vah hăn ta nây kloh ro tâm nau yỗ Păng toyh jru ngăn ngên.\n\nChorus\nHăn vah leo tâm klŏng jru rhuăt lĕ rse nkân jŏ jêh hơi\nbăl vah ơi, vah hăn ndrel tâm ntŭk jru ntŭk geh nau yỗ toyh ngăn.\n\nVerse 2\nÂk bunuyh yor vât vâng nar aơ hôm gŭ păn thơ nkhơng uănh dak mƀŭt lơ vơ klơ kơh.\nÊ geh nơm janh rlong lăp ntŭk klŏng jru chuat hom tâm nau yỗ tât ta ntŭk jru.\n\nChorus\nHăn vah leo tâm klŏng jru rhuăt lĕ rse nkân jŏ jêh hơi\nbăl vah ơi, vah hăn ndrel tâm ntŭk jru ntŭk geh nau yỗ toyh ngăn.\n\nVerse 3\nÂk bunuyh lăp ta nây ŭch gay geh nau kâp gân ƀiă lah ăt hôm ndĕ ndŏ n'gŏ kơh.\nDak mƀŭt njach rbuh rdu âk ndơ ƀỡ ƀơch nsŭn bôk duk đŭng đưt bôk vah ƀlôn ƀlơ.\n\nChorus\nHăn vah leo tâm klŏng jru rhuăt lĕ rse nkân jŏ jêh hơi\nbăl vah ơi, vah hăn ndrel tâm ntŭk jru ntŭk geh nau yỗ toyh ngăn.\n\nVerse 4\nVah ndrel hom bơh dak ơ mpôl băl vah ơi duk ntŭk dak geh nau tâm rklaih toyh ngăn.\nHô tâm nau rŏng Păng saơ ntŭk jru ngăn ngên geh nau maak ƀa-ƀơ gŭ tâm Păng.\n\nChorus\nHăn vah leo tâm klŏng jru rhuăt lĕ rse nkân jŏ jêh hơi\nbăl vah ơi, vah hăn ndrel tâm ntŭk jru ntŭk geh nau yỗ toyh ngăn.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0205", "title": "GÂP NHHƠR GÂP NƠM", "song_number": "205", "lyrics": "GÂP NHHƠR GÂP NƠM\n\nTC 229\n\nVerse 1\nƠ Kôranh Brah gâp nhhơr jêh lĕ gâp nơm ma May. Ôi Yê-su gâp nhhơr jêh lĕ ndơ gâp ma May.\nDơn jêh lĕ rngôch ndơ tâm nơng. Nhhơr jêh ma lĕ nuih n'hâm gâp. May tâm chuai jêh gâp pô ri: gâp jao ma Păng.\n\nVerse 2\nƠ Kôranh Brah gâp nhhơr jêh lĕ nau rêh nau blau. Jêh ndơ May ăn ma gâp, gâp mra dŏng ma May.\nTơ-lah May mra ngơi ma gâp. Gâp mra tĭng ndỗ May nau maak. A-ƀaơ lơn jêh ri ƀa-ƀơ tông bâr Kôranh Brah.\n\nVerse 3\nƠ Kôranh Brah gâp nhhơr jêh lĕ prăk jêh ri maih. May Nơm ăn jêh ma gâp, nau ndrŏng mâu dơi kơp.\nLĕ rngôch mpa jêng ndơ May rgănh. Ma yor May tâm chuai jêh gâp. Gâp mra gŭ tâm êp ma May ơ Krist Kôranh Brah.\n\nVerse 4\nƠ Kôranh Brah gâp nhhơr jêh lĕ gâp nơm ma May. Ơ Kôranh Brah gâp nhhơr jêh, gâp nơm ma Yê-su.\nĂn May mra gŭ rêh tâm gâp. Nau tŏng bêng jêh gŭ tâm May. Gâp ŭch ma Krist gŭ tâm gâp lĕ rngôch ma Păng.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0206", "title": "NAU RÊH GÂP NHHƠR MA KÔRANH BRAH", "song_number": "206", "lyrics": "NAU RÊH GÂP NHHƠR MA KÔRANH BRAH\n\nTC 236\n\nVerse 1\nNau rêh gâp nhhơr ma Kôranh Brah. Knŏng he ƀư maak ma Yê-su;\nAơ mpang ti gâp nhhơr ma May, gơih kơl ƀư ăp ntil kan May.\nNjăr rêh gâp nhhơr ma May, gay tâm rnê kơl kan klơ trôk.\n\nVerse 2\nAơ mpang jâng gâp nhhơr ma May. Hăn aơ ri gay rnê Kon May;\nAơ bâr mprơ gâp gay nhhơr đŏng, mprơ ƀa-ƀơ tâm rnê Yê-su.\nNjăr rêh gâp nhhơr ma May, gay tâm rnê kơl kan klơ trôk.\n\nVerse 3\nAơ bâr mbung nhhơr gay nkoch mbơh. Ăn lam bri tăng nau Mhe mhan;\nNhhơr lĕ prăk maih ma Kôranh Brah, gay dŏng nkoch mbơh nau kan May.\nNjăr rêh gâp nhhơr ma May, gay tâm rnê kơl kan klơ trôk.\n\nVerse 4\nNau gâp ŭch nhhơr lĕ nau aơ. Mâu tĭng ôh nau gâp nơm ŭch;\nDăn May mât uănh nuih n'hâm gâp, sâm rgâl gâp jêng ntŭk May gŭ.\nNjăr rêh gâp nhhơr ma May, gay tâm rnê kơl kan klơ trôk.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0207", "title": "NJŬN LEO TA YÔK KĂL VER", "song_number": "207", "lyrics": "NJŬN LEO TA YÔK KĂL VER\n\nTC 239\n\nVerse 1\nTâm rnê Yê-su jêng Kôranh Hađăch toyh, geh nau chrat ang Kôranh Brah.\nTa yôk kăl-ver Păng njŭn tât ro, lơi dĭng chuêl nau aơ ôh.\nNuih n'hâm lơi chuêl Gêt-sê-ma-nê, nuih n'hâm lơi chuêl Păng dơn nau jêr\ndu huê Yê-su dơm geh nau ueh dơn hao klơ yôk kăl-ver.\n\nVerse 2\nNtĭm gâp trôm môch ntŭk bu tâp Păng, ntŭk âk bu-nuyh nhhiăng nhim.\nGeh phung Tông Mpăr Ueh nsoh ao nglang, gŭ njrăng ăn Păng đăp mpăn.\nNuih n'hâm lơi chuêl Gêt-sê-ma-nê, nuih n'hâm lơi chuêl Păng dơn nau jêr\ndu huê Yê-su dơm geh nau ueh dơn hao klơ yôk kăl-ver.\n\nVerse 3\nTĭng têl Ma-ri hăn tât ơm ôi, nhhơr ndơ ƀâu kah ma Păng.\nKôranh Brah ntĭm môch tă Păng dâk rêh, njŭn leo ta yôk kăl-ver.\nNuih n'hâm lơi chuêl Gêt-sê-ma-nê, nuih n'hâm lơi chuêl Păng dơn nau jêr\ndu huê Yê-su dơm geh nau ueh dơn hao klơ yôk kăl-ver.\n\nVerse 4\nKôranh Brah ơi gâp ŭch tĭng ndỗ May, tuy si tâm rkăng ăp nar.\nƠ Kôranh Brah ơi gâp ŭch dơn ndrel, yor gâp May hŏ dơn jêh.\nNuih n'hâm lơi chuêl Gêt-sê-ma-nê, nuih n'hâm lơi chuêl Păng dơn nau jêr\ndu huê Yê-su dơm geh nau ueh dơn hao klơ yôk kăl-ver.\nA-Men.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0208", "title": "AMOH NƠM KHLAY LƠN JÊNG YÊ-SU", "song_number": "208", "lyrics": "AMOH NƠM KHLAY LƠN JÊNG YÊ-SU\n\nTC 249\n\nVerse 1\nMaak ngăn he dơi gŭ êp ma ntŭk Amoh Nơm khlay ngăn jêng Yê-su, nau Ngơi Păng ăn nuih n'hâm gâp maak, ngăn tông bâr ma Kôranh Yê-su.\nTông mpăr ueh mprơ klơ trôk ri, nđâp phung chroh kloh ueh lam bri, mprơ nsum n'grŭp tâm rnê Yê-su, knŏng Păng dơm jêng Yê-su.\n\nVerse 2\nLĕ nau tih mhĭk Păng dơi yỗ an ngăn gơnh tông bâr Kôranh Yê-su, gâp nđơr ngăn chuat tâm trong Ƀon Ueh, gŭ ndrel ma Kôranh Brah Yê-su.\nTông mpăr ueh mprơ klơ trôk ri, nđâp phung chroh kloh ueh lam bri, mprơ nsum n'grŭp tâm rnê Yê-su, knŏng Păng dơm jêng Yê-su.\n\nVerse 3\nKon Biăp Brah Ndu dơi tâm rvê gâp dơn nau chroh ma Amoh Yê-su, ma Amoh Păng nuih n'hâm gâp răm maak, gâp rŏng ngăn nau ueh Yê-su.\nTông mpăr ueh mprơ klơ trôk ri, nđâp phung chroh kloh ueh lam bri, mprơ nsum n'grŭp tâm rnê Yê-su, knŏng Păng dơm jêng Yê-su.\n\nVerse 4\nLĕ nau tih mhĭk ƀỡ ƀơch mƀăr ngai yor he nsing nau dơi Yê-su, gâp maak gŭ iăt nau mprơ ueh nây, Amoh Nơm toyh lơn jêng Yê-su.\nTông mpăr ueh mprơ klơ trôk ri, nđâp phung chroh kloh ueh lam bri, mprơ nsum n'grŭp tâm rnê Yê-su, knŏng Păng dơm jêng Yê-su.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0209", "title": "NTŬK LŬ NÂP ĐĂP MPĂN", "song_number": "209", "lyrics": "NTŬK LŬ NÂP ĐĂP MPĂN\n\nTC 267\n\nVerse 1\nKnŏng geh Yê-su dơm jêng Nơm Tâm chuai gâp ngăn. Nơm Tâm chuai ngăn ƀa ƀơ n'ho ro.\nTa klơ lŭ nâp Păng ăn huêng srĭng gâp gŭ mpăn, ta nây gâp saơ tu nau rêh mhe.\n\nChorus\nYê-su ăn huêng gâp gŭ ta klơ lŭ nâp ngăn. Gui n'hâm Păng păn, ta klơ neh sơh ma nau rŏng Păng,\nnkŭm gâp tâm nau đăp mpăn ngăn, ti Yê-su dơm king gâp đăp mpăn. Tâm ti Brah Păng dơi đăp rmên ngăn.\n\nVerse 2\nKnŏng Brah Yê-su dơm jêng Nơm Tâm chuai gâp ngăn. Păng chuai jêh lĕ nau tih mhĭk gâp.\nKôranh Brah kuăn huêng gâp mâu ăn mpât n'gơ phit klach, ntop ăn nau Brah May ma gâp mro.\n\nChorus\nYê-su ăn huêng gâp gŭ ta klơ lŭ nâp ngăn. Gui n'hâm Păng păn, ta klơ neh sơh ma nau rŏng Păng,\nnkŭm gâp tâm nau đăp mpăn ngăn, ti Yê-su dơm king gâp đăp mpăn. Tâm ti Brah Păng dơi đăp rmên ngăn.\n\nVerse 3\nNuih n'hâm gâp bêng ma nau răm rhơn mât ton Păng. Nơm tâm chuai gâp ma nau khlay ngăn.\nĂp mnĭt mông Păng nkhŭt ăn he âk nau ueh uĭn, nhhơr dak nau rêh hoch bêng rmeh ler.\n\nChorus\nYê-su ăn huêng gâp gŭ ta klơ lŭ nâp ngăn. Gui n'hâm Păng păn, ta klơ neh sơh ma nau rŏng Păng,\nnkŭm gâp tâm nau đăp mpăn ngăn, ti Yê-su dơm king gâp đăp mpăn. Tâm ti Brah Păng dơi đăp rmên ngăn.\n\nVerse 4\nLah tât ta Ƀon Ueh klơ gâp mra nsoh ao nglang. Kâp vơt Kôranh Brah jŭr văch bơh klơ.\nNdrel ma phung tông mpăr mprơ tâm rnê mât ton Păng, Nơm tâm chuai ma nau rŏng hâu ngăn.\n\nChorus\nYê-su ăn huêng gâp gŭ ta klơ lŭ nâp ngăn. Gui n'hâm Păng păn, ta klơ neh sơh ma nau rŏng Păng,\nnkŭm gâp tâm nau đăp mpăn ngăn, ti Yê-su dơm king gâp đăp mpăn. Tâm ti Brah Păng dơi đăp rmên ngăn.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0210", "title": "GÂP RŎNG NGĂN NSING MA BRAH YÊ-SU", "song_number": "210", "lyrics": "GÂP RŎNG NGĂN NSING MA BRAH YÊ-SU\n\nTC 268\n\nVerse 1\nGâp rŏng ngăn nsing ma Brah Yê-su! Nuih n'hâm gâp knŏng rŏng Păng dơm;\nrlu mpăn tâm lĕ nau Păng hŏ ton, chroh rjăp tĭng Păng hŏ lah jêh.\n\nChorus\nYê-su, Yê-su, gâp nsing ma May, gâp gĭt May jêng Kôranh Brah ngăn,\nYê-su, Yê-su, Nơm khlay ueh ngăn. Nau yỗ May kơl gâp âk lơn.\n\nVerse 2\nGâp rŏng ngăn nsing ma Brah Yê-su! Yor mham May chuai tih mhĭk gâp;\nyor nau chroh gâp dơn rmal nau tih, gay jêng kloh n'ho bah ji kuet.\n\nChorus\nYê-su, Yê-su, gâp nsing ma May, gâp gĭt May jêng Kôranh Brah ngăn,\nYê-su, Yê-su, Nơm khlay ueh ngăn. Nau yỗ May kơl gâp âk lơn.\n\nVerse 3\nGâp rŏng ngăn nsing ma Brah Yê-su! Mƀăr lĕ nau rngot rvê djơh mhĭk;\nPăng ăn gâp răm maak rêh đăp mpăn, ta neh ntu tâm ban klơ trôk.\n\nChorus\nYê-su, Yê-su, gâp nsing ma May, gâp gĭt May jêng Kôranh Brah ngăn,\nYê-su, Yê-su, Nơm khlay ueh ngăn. Nau yỗ May kơl gâp âk lơn.\n\nVerse 4\nGâp rŏng ngăn mbên nsing Brah Yê-su! Păng jêng mĭt jiăng bơh kăl e;\nchroh rjăp Păng mra ăn gŭ êp Păng, tâm rnôk aơ mâu lah kăn dỡ.\n\nChorus\nYê-su, Yê-su, gâp nsing ma May, gâp gĭt May jêng Kôranh Brah ngăn,\nYê-su, Yê-su, Nơm khlay ueh ngăn. Nau yỗ May kơl gâp âk lơn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0211", "title": "YÊ-SU JÊNG TU MAAK MA NUIH N'HÂM", "song_number": "211", "lyrics": "YÊ-SU JÊNG TU MAAK MA NUIH N'HÂM\n\nTC 280\n\nVerse 1\nYê-su jêng tu maak ma nuih n'hâm, Păng dơi sol ang nau rêh n'ho ro,\nma nau Brah Păng aơ gâp mâu rvê, nuih n'hâm dăn Yê-su ăn nau maak\n\nVerse 2\nTu nau ngơi ngăn mâu blau rgâl ôh, chuai mbu rmal nau tih gơnh kuăn Păng,\nPăng mơih rmên ngăn ma mbu nơm dăn, mbu nơm dơi mâp Păng ueh maak mro.\n\nVerse 3\nYê-su jêng piăng let ma nau rêh, nuih n'hâm gâp hŏ mâp chŏk sa jêh,\nnhêt dak ntŭk păng dak Brah tă klơ, nuih n'hâm gâp lơ maak gŭ êp Păng.\n\nVerse 4\nNđâp lah nuih n'hâm gâp hôm vĭ vĕ, rngot rvê ăn he ăt nsing ma Păng,\nmaak ngăn gâp iăt nau Brah Ndu Ngơi, nuih n'hâm gâp rŏng ma Păng mâu lơi.\n\nVerse 5\nYê-su ơm gŭ êp kêng gâp mro, nau rêh gâp đăp mpăn ueh maak mro,\nmprơh lĕ nau ngo nau tih mhĭk kray, gay Brah Huêng Ueh sol lĕ bu nuyh.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0212", "title": "NTŬK NDE DÔL PHŬT SIAL", "song_number": "212", "lyrics": "NTŬK NDE DÔL PHŬT SIAL\n\nTC 282\n\nVerse 1\nYor Yê-su king nâm bu lŭ klêr, ntŭk gâp gŭ nde tâm nôk phŭt sial,\nđăp mpăn ngăn tâm lĕ nau rêh ni, ntŭk gâp nde krap tâm nôk phŭt sial.\n\nChorus\nƠ Yê-su jêng lŭ klêr nklang âk nau rêh ni bri brŏng krŏng mbâl ngo klĕng râm sâr\nơ Yê-su jêng lŭ klêr nklang âk nau rêh ni ntŭk nde nây nuih n'hâm mâu rngot ôh.\n\nVerse 2\nNar măng Yê-su king gâp đăp mpăn, ntŭk gâp gŭ nde tâm nôk phŭt sial,\ngâp nsing ngăn mâu ngai đah lŭ nây, ntŭk gâp nde krap tâm nôk phŭt sial.\n\nChorus\nƠ Yê-su jêng lŭ klêr nklang âk nau rêh ni bri brŏng krŏng mbâl ngo klĕng râm sâr\nơ Yê-su jêng lŭ klêr nklang âk nau rêh ni ntŭk nde nây nuih n'hâm mâu rngot ôh.\n\nVerse 3\nPhŭt sial chuănh đỗ jŭm gâp kđôi lĕ, ntŭk gâp gŭ nde tâm nôk phŭt sial,\ngŭ nde tâm Păng nuih n'hâm đăp mpăn, ntŭk gâp nde krap tâm nôk phŭt sial.\n\nChorus\nƠ Yê-su jêng lŭ klêr nklang âk nau rêh ni bri brŏng krŏng mbâl ngo klĕng râm sâr\nơ Yê-su jêng lŭ klêr nklang âk nau rêh ni ntŭk nde nây nuih n'hâm mâu rngot ôh.\n\nVerse 4\nĐăp mpăn ngăn nsing ta klơ lŭ klêr, ntŭk gâp gŭ nde tâm nôk phŭt sial,\nêp Yê-su nuih n'hâm gâp răm maak, ntŭk gâp nde krap tâm nôk phŭt sial.\n\nChorus\nƠ Yê-su jêng lŭ klêr nklang âk nau rêh ni bri brŏng krŏng mbâl ngo klĕng râm sâr\nơ Yê-su jêng lŭ klêr nklang âk nau rêh ni ntŭk nde nây nuih n'hâm mâu rngot ôh.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0213", "title": "CHUAT NGUAY NGUAY", "song_number": "213", "lyrics": "CHUAT NGUAY NGUAY\n\nTC 291\n\nVerse 1\nUeh reh ngăn, tĭng têl jâng Yê-su, nar măng chuat, chuat hăn răp jăp,\nsol tĭng têl, jâng Păng ăn n'hêl nễ, du ai chuat, tĭng Păng tât lôch.\n\nChorus\nChuat nguay nguay ndrel Yê-su, bu mâu dơi ƀư he ôh.\nChuat nguay nguay tâm trong Păng, lăng săk jăn tât Ƀon klơ.\n\nVerse 2\nChuat hăn ndrel, Yê-su đăp mpăn ngăn, nsing ƀa-ƀơ ma Brah Yê-su,\nta ntŭk Păng, leo hăn tĭng tât nĕ, ueh ngăn mâu, geh nơm rlăng ôh.\n\nChorus\nChuat nguay nguay ndrel Yê-su, bu mâu dơi ƀư he ôh.\nChuat nguay nguay tâm trong Păng, lăng săk jăn tât Ƀon klơ.\n\nVerse 3\nHăn ndrel Yê-su lơi n'gĭl chiau meng, ăp mông mnĭt hôm maak tĭng Păng,\npoh lam yôk, nđâp lah n'hâm gâp hươi, dŭt n'hâm gâp dơi chuat tĭng Păng.\n\nChorus\nChuat nguay nguay ndrel Yê-su, bu mâu dơi ƀư he ôh.\nChuat nguay nguay tâm trong Păng, lăng săk jăn tât Ƀon klơ.\n\nVerse 4\nDăn gŭ êp, lơn kêng Brah Yê-su, nar măng chuat, chuat hăn đăp mpăn,\nuănh n'hêl nễ, têl jâng Păng dĭng hăn, chuat ndrel n'grŭp tĭng ndỗ Yê-su.\n\nChorus\nChuat nguay nguay ndrel Yê-su, bu mâu dơi ƀư he ôh.\nChuat nguay nguay tâm trong Păng, lăng săk jăn tât Ƀon klơ.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0214", "title": "JÊNG TAHAN JANH KATANG", "song_number": "214", "lyrics": "JÊNG TAHAN JANH KATANG\n\n\nVerse 1\nJêng tahan janh ktang, Phung he dơi tâm lơh đah brah mhĭk nđâp lah nter huy: 'Yê-su jêng Nơm rklaih hên'.\nYê-su mâu rlu kơl he tâm lơh đah phung rlăng tât he geh đon Hađăch.\nNhhơr lĕ nau rêh druh ndăm gay tâm lơh ăn Brah he Yê-su.\nGay njŭn sĭt ma Păng, phung vĭ hiơt trong. Mâu mra jêng hươi yor lah geh Yê-su leo.\nPăng gai phung he, nđâp ƀư ktang he. Yor nau rŏng he njŭn bunuyh ma Păng.\nNsing ma Brah Ndu dơi tâm lơh đah Satan. Pit in phung ƀon lan. Hôm gŭ tâm rêh ni. gay leo khân păng tât ta ntŭk ang.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0215", "title": "NGƠI NDREL MA YÊ-SU BAR PE TONG", "song_number": "215", "lyrics": "NGƠI NDREL MA YÊ-SU BAR PE TONG\n\nTC 452\n\nVerse 1\nNgơi ndrel ma Yê-su bar pe tong jêng răm maak ngăn, lah ngơi ndrel ma Yê-su bar pe tong jêng răm maak,\ntơ lah gâp tâm rnê Kôranh Brah. Tâm ăp lĕ lam ntŭk. Tơ lah ngơi ma Yê-su bar pe tong maak hâu ngăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0216", "title": "ĂP MÔNG MNĬT", "song_number": "216", "lyrics": "ĂP MÔNG MNĬT\n\nTC 293\n\nVerse 1\nKôranh Brah khlay, lơn ma lĕ rngôch, gŭ êp May nuih n'hâm gâp đăp mpăn ngăn\nma mham khlay gâp ŭch chroh mro, dăn May mât mơh gâp gŭ êp May ro.\n\nChorus\nĂp mông mnĭt, ăp mông mnĭt, mham khlay May chuai nau tih gâp;\nmât ton Kôranh Brah bêng nau rŏng, kât nâp nuih n'hâm gâp, gŭ êp kêng May.\n\nVerse 2\nNđâp lah neh ntu bêng nau ngo, May njŭn leo trong ma gâp ơ Yê-su;\nbơh jŏ jêh May njŭn leo gâp yor nsing ma May gâp geh nau tâm rklaih.\n\nChorus\nĂp mông mnĭt, ăp mông mnĭt, mham khlay May chuai nau tih gâp;\nmât ton Kôranh Brah bêng nau rŏng, kât nâp nuih n'hâm gâp, gŭ êp kêng May.\n\nVerse 3\nRŏng Yê-su geh nau ueh nôk gâp cha lơi ngai neh ntu chuat rgăn krong\ntât Ƀon Ueh geh nau chrat ang huêng gâp gŭ bêng nau rŏng tâm Brah Ndu.\n\nChorus\nĂp mông mnĭt, ăp mông mnĭt, mham khlay May chuai nau tih gâp;\nmât ton Kôranh Brah bêng nau rŏng, kât nâp nuih n'hâm gâp, gŭ êp kêng May.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0217", "title": "KA-LEP UĂNH KÔRANH BRAH", "song_number": "217", "lyrics": "KA-LEP UĂNH KÔRANH BRAH\n\nTC 311\n\nVerse 1\nSaơ lĕ bunuyh toyh nhuat toyh, Ka-lep uănh Kôranh Brah khân păng uh ah rdja nuih,\npăng chroh ma Brah Ndu. Nau Ngơi nây păng tông ngăn, mâu phit mâu lĕ klach. Mâm ƀư nau Ngơi Giê-hô-va mâu khư ma he?\n\nChorus\nGâp mâu mâp cha-lơi may, chuat hom ma nau nănh,\ndu huê mprơh rbăn bunuyh, bar pe hê dơi đah rsen.\n\nVerse 2\nĂn ăp nơm tông bâr ngăn, nâm bu Ka-lep nây ăn he jêng nâm bu păng,\nƀư nau Kôranh Brah ntăm. Pô nây nau ueh uĭn Brah, Ndu mbêng ler tâm he. Păng mra ăn nau dơi ma mbu nơm tông bâr păng.\n\nChorus\nGâp mâu mâp cha-lơi may, chuat hom ma nau nănh,\ndu huê mprơh rbăn bunuyh, bar pe hê dơi đah rsen.\n\nVerse 3\nLah tông du n'gul vah dơm, mâu geh nau ueh uĭn mbu nơm mra tĭng ndỗ nây,\ngâp ăn nau ueh uĭn. Ueh uĭn nau mĭn tâm huêng, săk jăn nđâp nuih n'hâm. Ndrŏng đah ndơ ndơn Brah Ndu, prăp ăn tâm Ƀon Ueh.\n\nChorus\nGâp mâu mâp cha-lơi may, chuat hom ma nau nănh,\ndu huê mprơh rbăn bunuyh, bar pe hê dơi đah rsen.\n\nVerse 4\nKnŏng pah kan Yê-hô-va, ƀư maak knŏng ma Păng gay ntrâng ƀư du ntil kan,\nmâu joi nau nơm ŭch. Dôl ran ƀa-ƀơ pa năp, tât ta ntŭk tâm nal. Ƀư kan ma lĕ nuih n'hâm ma nơm he rŏng ngăn.\n\nChorus\nGâp mâu mâp cha-lơi may, chuat hom ma nau nănh,\ndu huê mprơh rbăn bunuyh, bar pe hê dơi đah rsen.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0218", "title": "PAH KAN GƠNH OI MĂNG DĂCH TÂT", "song_number": "218", "lyrics": "PAH KAN GƠNH OI MĂNG DĂCH TÂT\n\nTC 319\n\nVerse 1\nPah kan gơnh oi măng dăch tât pah kan ntơm nar dôl luh\npah kan nôk dak ngom ê sơh dôl kao si dang ueh.\nSrôih pah kan tât nar nklang bôk gơih nđơr dôl trôk hôm duh,\npah kan gơnh oi măng dăch tât lĕ nau kan rĭng jêh.\n\nVerse 2\nPah kan gơnh oi măng dăch tât pah kan dôl nar hôm prêh\npah kan lĕ nuih n'hâm ƀa-ƀơ mông rlu dăch tât jêh.\nNar khay năm lôch ngăch dŭt n'hâm ăn he ƀư âk kan ueh,\npah kan gơnh oi măng dăch tât lĕ nau kan rĭng jêh.\n\nVerse 3\nPah kan gơnh oi măng dăch tât pah kan dôl trôk ê măng.\nPah kan dôl nar ê hŏ nhâp nar lĕ hŏ nhâp jêh.\nPah kan dôl măng ntơm dăch tât ngăch prăl hom măng tât yơh,\npah kan gơnh oi măng dăch tât lĕ nau kan rĭng jêh.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0219", "title": "KƠL PHUNG DÔL HƯƠI RDJA", "song_number": "219", "lyrics": "KƠL PHUNG DÔL HƯƠI RDJA\n\nTC 323\n\nVerse 1\nKơl rklaih bunuyh dôl hươi rdja, dôl gŭ tâm nau tih, yor nau Păng yỗ kon bunuyh klaih bơh nau ƀai.\nPăng nkhŭt mham yor phung tih, kơl phung huăr r-gănh nkoch Amoh Yê-su ăn nau yỗ ma phung tih.\n\nChorus\nGay kơl phung dôl hươi rdja rklaih bunuyh bơh nau khĭt;\nYê-su bêng ma nau yỗ, ăn nau rêh mhe.\n\nVerse 2\nNđâp lah he dun nau Păng, ăt Păng rŏng ma he, răm maak mbu nơm rmal nau tih dơn Amoh Păng.\nĂn chroh răp jăp ma Păng, gŭ sŏng ta năp Păng, gay Păng yỗ ma mbu n'hêl nễ dơn Amoh Păng.\n\nChorus\nGay kơl phung dôl hươi rdja rklaih bunuyh bơh nau khĭt;\nYê-su bêng ma nau yỗ, ăn nau rêh mhe.\n\nVerse 3\nSa-tan ŭch ndơm âk bunuyh, king ndâp lơi nau ang, geh jêh nau yỗ Kôranh Brah nsing hom ma Păng.\nTâm ti nau rŏng Kôranh Brah mra geh nau đăp mpăn, sa-ơm ay may hươi rdja aƀaơ dơi jêng ktang\n\nChorus\nGay kơl phung dôl hươi rdja rklaih bunuyh bơh nau khĭt;\nYê-su bêng ma nau yỗ, ăn nau rêh mhe.\n\nVerse 4\nKơl rklaih phung hươi rdja aơ, Kôranh Brah maak hâu ngăn, pah kan ma nau rŏng mra geh nau nkhôm âk.\nNđâp lah geh nau jâk jêr, mâu lah tâm trong huêt, nkoch nau Krist khĭt lam ntŭk gay tâm chuai he.\n\nChorus\nGay kơl phung dôl hươi rdja rklaih bunuyh bơh nau khĭt;\nYê-su bêng ma nau yỗ, ăn nau rêh mhe.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0220", "title": "KLŬP RSE TÂM RKLAIH", "song_number": "220", "lyrics": "KLŬP RSE TÂM RKLAIH\n\nTC 324\n\nVerse 1\nKlŭp lơi rse ăn gơnh tâm nklang dak rbuh ri, geh du huê oh nâu lĕ rmok tâm dak klŏng.\nDu huê jiăng he, ơ mbu nơm nănh janh dơi klŭp rse gay tâm rklaih bơh păng nau khĭt tâm dak.\n\nChorus\nKlŭp rse ăn gơnh oi. Klŭp rse ăn gơnh oi.\nDak rdu jêh păng ngâm ƀlôn ƀlơ dak klŏng jru ngăn klŭp hom rse ăn gơnh oi, du huê hŏ ngâm jêh nar aơ.\n\nVerse 2\nKlŭp rse ăn gơnh oi ma ti ktang ăn ngăch, mâm ƀư gŭ uănh dơm mâu chrê păng khĭt rmok?\nUănh păng ngâm rmok jêh ăn he hăn gơnh oi klŭp rse gay rklaih phung hŏ ngâm tâm nau tih mhĭk.\n\nChorus\nKlŭp rse ăn gơnh oi. Klŭp rse ăn gơnh oi.\nDak rdu jêh păng ngâm ƀlôn ƀlơ dak klŏng jru ngăn klŭp hom rse ăn gơnh oi, du huê hŏ ngâm jêh nar aơ.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0221", "title": "SOL HOM NÂM N'GÂNG ŬNH", "song_number": "221", "lyrics": "SOL HOM NÂM N'GÂNG ŬNH\n\nTC 327\n\nVerse 1\nNau yỗ toyh Kôranh Brah Mbỡ sol ang, tă Nau Ngơi nâm chrat n'gâng ŭnh;\nPăng ăn he ŭch ma ŭnh ang mro, gay sol lam dak mƀŭt thŭl ngo.\n\nChorus\nLĕ nau rêh sol hom nâm n'gâng ŭnh, sol ang tâm nklang ntŭk ngo klĕng\nn'ho sol trong ma mpôl vah duk ri, dôl chuat nau krit klach bri măng.\n\nVerse 2\nNau tih gâp ngo nâm bri klong măng, yor nau ngo nkŭm lơi nau ang;\nâk rbăn bunuyh tring tring klơ dak mƀŭt, măt uănh hom ma ŭnh ang ri.\n\nChorus\nLĕ nau rêh sol hom nâm n'gâng ŭnh, sol ang tâm nklang ntŭk ngo klĕng\nn'ho sol trong ma mpôl vah duk ri, dôl chuat nau krit klach bri măng.\n\nVerse 3\nŬnh klu klâm, mbu năn yơr hom prêh, tâm dak mƀŭt âk bu nuyh phŭt;\nLĕ khân păng n'gơr ta kơh vah duk, khân păng klaih jêh bơh nau ngo.\n\nChorus\nLĕ nau rêh sol hom nâm n'gâng ŭnh, sol ang tâm nklang ntŭk ngo klĕng\nn'ho sol trong ma mpôl vah duk ri, dôl chuat nau krit klach bri măng.\n\nVerse 4\nNau rêh may yor Kôranh Brah mât uănh, mra geh nau dơi bơh nau krit;\ndơi ăn ma may geh nau brah sol ang, ma bunuyh gŭ tâm nau tih.\n\nChorus\nLĕ nau rêh sol hom nâm n'gâng ŭnh, sol ang tâm nklang ntŭk ngo klĕng\nn'ho sol trong ma mpôl vah duk ri, dôl chuat nau krit klach bri măng.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0222", "title": "NAR AƠ BRAH YÊ-SU PLỠ VĂCH MÂM ƀƯ", "song_number": "222", "lyrics": "NAR AƠ BRAH YÊ-SU PLỠ VĂCH MÂM ƀƯ\n\nTC 128\n\nVerse 1\nBrah Yê-su mra plỡ văch lơi vĭ vĕ, mâm lah Păng văch nar aơ?\nPăng văch mât uănh ma nau Brah nau rŏng. Mâu lah Păng văch nar aơ?\nPăng mra văch vơt dơn phung Păng săch, lĕ rngôch mbu nơm nuih n'hâm kloh ueh.\nGŭ ăp ntŭk lam bri ta neh ntu, Mâu lah mra văch nar aơ.\n\nChorus\nUeh maak, răm maak Aƀaơ gâp mra dơi nau maak,\nUeh ngăn khlay ngăn! Yơk ma Hađăch Krist klơ trôk;\nUeh ngăn, răm ngăn nkra nau Yê-su plỡ văch.\nmaak ngăn maak ngăn nar kăn dỡ Păng mra văch.\n\nVerse 2\nRnôk nây nau brah Sa-tan rai lôch lĕ, ăn tât gơnh oi aƀaơ ro?\nMâu hôm geh nau rngot, jêh ri nau rvê. Ăn tât gơnh oi aƀaơ ro.\nBunuyh khĭt tâm Yê-su mra dâk rêh, mra mâp Yê-su ta klơ trôk ri.\nNdah he mra saơ nau chrêk rmah nây? Mâu lah mra văch nar aơ.\n\nChorus\nUeh maak, răm maak Aƀaơ gâp mra dơi nau maak,\nUeh ngăn khlay ngăn! Yơk ma Hađăch Krist klơ trôk;\nUeh ngăn, răm ngăn nkra nau Yê-su plỡ văch.\nmaak ngăn maak ngăn nar kăn dỡ Păng mra văch.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0223", "title": "NTŬK ƀON PHUNG CHROH GŬ", "song_number": "223", "lyrics": "NTŬK ƀON PHUNG CHROH GŬ\n\nTC 348\n\nVerse 1\nRi tâm Ƀon phung chroh gŭ nchrat ang. Jêng Ƀon rlu đăp mpăn ngăn ngên nanễ\njêng ngih Krist hăn lor dôl nkra, prăp ăn gâp răm maak rbăn năm.\n\nChorus\nRi uănh êp kơh krong Yur dan. Bêng tơm si rêh nse ueh uĭn. Ntŭk gâp dơi gŭ rlu ueh mpăn, lăp ta aơ gâp rlu.\nRi bunuyh hŏt rgănh maak hâu ngăn. Khân păng dơi rlu gŭ maak ngăn mbơh sơm hŏt rgănh aƀaơ gŭ mpăn, lăp ta aơ may rlu.\n\nVerse 2\nPăng hŏ hăn nkra ntŭk ma phung he. Jêng du ntŭk nđăp mpăn mro mrăng\nta aơ ntŭk yỗ nđach, ntŭk ueh lăng, ntŭk đăp mpăn, răm maak rbăn năm.\n\nChorus\nRi uănh êp kơh krong Yur dan. Bêng tơm si rêh nse ueh uĭn. Ntŭk gâp dơi gŭ rlu ueh mpăn, lăp ta aơ gâp rlu.\nRi bunuyh hŏt rgănh maak hâu ngăn. Khân păng dơi rlu gŭ maak ngăn mbơh sơm hŏt rgănh aƀaơ gŭ mpăn, lăp ta aơ may rlu.\n\nVerse 3\nLăp ntŭk aơ mâu ji mâu djơh mhĭk. Ueh ngăn ngên mâu geh mhĭk blem.\njêng ntŭk rgum ma Hađăch toyh mbah yơk. gâp maak ndô đon Hađăch n'ho ro.\n\nChorus\nRi uănh êp kơh krong Yur dan. Bêng tơm si rêh nse ueh uĭn. Ntŭk gâp dơi gŭ rlu ueh mpăn, lăp ta aơ gâp rlu.\nRi bunuyh hŏt rgănh maak hâu ngăn. Khân păng dơi rlu gŭ maak ngăn mbơh sơm hŏt rgănh aƀaơ gŭ mpăn, lăp ta aơ may rlu.\n\nVerse 4\nLăp ta aơ mprơ maak bâr ngơi huy. Dak kăch nau khĭt mâu hôm ôh;\ntroh ndrel hom hơi phung ƀon lan kloh, he răm maak ôi la ja nse.\n\nChorus\nRi uănh êp kơh krong Yur dan. Bêng tơm si rêh nse ueh uĭn. Ntŭk gâp dơi gŭ rlu ueh mpăn, lăp ta aơ gâp rlu.\nRi bunuyh hŏt rgănh maak hâu ngăn. Khân păng dơi rlu gŭ maak ngăn mbơh sơm hŏt rgănh aƀaơ gŭ mpăn, lăp ta aơ may rlu.\n\nVerse 5\nPhung aơ kon chrêk rmah mprơ nau maak. mprơ nau dơi dôl hăn rŏ trong;\nri Ƀon Ueh klơ dôl pơk vơt he, ăn he dơi chuat lăp ta nây.\n\nChorus\nRi uănh êp kơh krong Yur dan. Bêng tơm si rêh nse ueh uĭn. Ntŭk gâp dơi gŭ rlu ueh mpăn, lăp ta aơ gâp rlu.\nRi bunuyh hŏt rgănh maak hâu ngăn. Khân păng dơi rlu gŭ maak ngăn mbơh sơm hŏt rgănh aƀaơ gŭ mpăn, lăp ta aơ may rlu.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0224", "title": "ÂK ƀON LAN GŬ LŬNG NTER", "song_number": "224", "lyrics": "ÂK ƀON LAN GŬ LŬNG NTER\n\n\nVerse 1\nIăt bâr bunuyh ƀon lan, lŭng nter tâm nau tih nđêh nji ngăn.\nPhung Bu-nâr Bu-nong vơl joi kâp gân ma nau tâm rklaih.\nPhung oh nâu he tâm yôk yang. Lŭng nter yor ma nđêh nji.\nKay lŏng he nhhơr hom nuih n'hâm, gay hăn tâm rklaih khân păng.\n\nVerse 2\nN'gor Chin đah Drôn êp n'gor he, Lao Thi-ƀêt, Mông-Gôl Chi.\nUănh bơh n'gor nđôch đah neh ntu Konar-Phi ta nklang kô dak.\nMiên indô Thai nđâp n'gor Ma-lai âk râk ngăn mpôl bu nuyh.\nPhung kon ƀon lan joi vơh vơl gŭ kâp gân nau tâm rklaih.\n\nVerse 3\nNgai đah he hôm rbăn rmưn bunuyh, ê-hŏ klaih hôm vĭ vĕ.\nPhung bu năch njêh chăt jêng jêh, tâm mpơl lĕ nau blau mĭn.\nLư n'gor My lĕ yach hao jêh âk bunuyh sŏk dơn Kôranh Brah\nHôm geh âk tâm n'gor chiau meng, ăt hôm rêh tâm nau ngo.\n\nVerse 4\nBrah Huêng Ueh sol tâm nuih n'hâm gâp, he geh nau mĭn gĭt rbăng,\nmâm dĭng mâu nhhơr ăn prêh klơ, sol njŭn an phung hiơt trong,\nntŭk yơn nau yỗ, nau yỗ ngăn, leo hom nau yỗ an gơnh.\nKŏ tât ăp nơm chiau meng, sŏk dơn Kôranh Brah Yê-su.\n\nVerse 5\nUănh mpôl nsong nti nau mhe mhan ueh, hao yôk rgăn dak sop.\nbrŏng, bơh ƀon jễ n'hot ma ƀon toyh, rgŏ dak mƀŭt bri krŏng.\nmbâl, tât ta nar Yê-su plỡ văch chông leo sĭt phung biăp.\nPăng. Mprơ ndrel n'grŭp hao ta kalơ trôk, văch râng nau rƀŭn toyh.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0225", "title": "MA LĔ NUIH N'HÂM RĂP JĂP", "song_number": "225", "lyrics": "MA LĔ NUIH N'HÂM RĂP JĂP\n\nTC 378\n\nVerse 1\nN'hêl nễ ma lĕ nuih n'hâm hên ŭch gŭ răp jăp. Yor ma nau yỗ May nơm dơm hên mra dơi.\nƠ Hađăch nau rêh hên nhhơr prêh klơ bok pla may. Ktang ma nau Brah ma hên tâm lơh bơh May.\n\nChorus\nMprơ hom bâr ăn huy, lơi dĭng gŭ klăk klêm. Mprơ ma lĕ nuih n'hâm, maak hom. Yor kon me.\nMprơ hom bâr ăn huy, gŭ răp jăp n'ho ro, Ơ Hađăch nau yỗ, nuih n'hâm hên ŭch gŭ rjăp.\n\nVerse 2\nN'hêl nễ ma lĕ nuih n'hâm hên ŭch tông bâr May. Ŭch nhhơr hên nơm ƀaƀơ ma ha đăch chrêk rmah.\nYor ma nau rŏng hên duh nđơr ƀư maak ma May. Răm rhơn hên mprơ tâm rnê ma nau May yỗ.\n\nChorus\nMprơ hom bâr ăn huy, lơi dĭng gŭ klăk klêm. Mprơ ma lĕ nuih n'hâm, maak hom. Yor kon me.\nMprơ hom bâr ăn huy, gŭ răp jăp n'ho ro, Ơ Hađăch nau yỗ, nuih n'hâm hên ŭch gŭ rjăp.\n\nVerse 3\nN'hêl nễ ma lĕ nuih n'hâm, ơ Nơm Tâm Rklaih hên. Dŏng nau Brah toyh May mât uănh jêng Hađăch hên.\nĂn May jêng Kôranh ma nau hên ŭch jêh ri rŏng. Hên kơp hên nơm jêng ndơ May hŏ ăp jêh.\n\nChorus\nMprơ hom bâr ăn huy, lơi dĭng gŭ klăk klêm. Mprơ ma lĕ nuih n'hâm, maak hom. Yor kon me.\nMprơ hom bâr ăn huy, gŭ răp jăp n'ho ro, Ơ Hađăch nau yỗ, nuih n'hâm hên ŭch gŭ rjăp.\n\nVerse 4\nNau yỗ Yê-su njŭn leo he dăch tât ntŭk rlu. Bok pla sol ang rêp ƀlêp ta klơ trôk ri.\nHơi oh nâu he n'grŭp ndrel n'gơr măt ta klơ trôk. Njêng jêng nau mprơ n'hanh ma nau rŏng n'ho ro.\n\nChorus\nMprơ hom bâr ăn huy, lơi dĭng gŭ klăk klêm. Mprơ ma lĕ nuih n'hâm, maak hom. Yor kon me.\nMprơ hom bâr ăn huy, gŭ răp jăp n'ho ro, Ơ Hađăch nau yỗ, nuih n'hâm hên ŭch gŭ rjăp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0226", "title": "ƀAP-TEM TÂM YÊ-SU", "song_number": "226", "lyrics": "ƀAP-TEM TÂM YÊ-SU\n\nTC 397\n\nVerse 1\nDu ai Ƀap-tem khĭt tâm Yê-su, gâp ŭch dơn khĭt ntơm aƀaơ.\nRêh ndrel Yê-su klaih bơh brah mhĭk, gŭ ndrel Păng klơ trôk ri.\n\nVerse 2\nNđâp lah gŭ pa ma Mbỡ măng nar, Păng geh nau nchrat ang ngăn.\nPăng jêng Kôranh toyh lơn ma lĕ rngôch, jêng Kôranh dŭt toyh aƀaơ ri.\n\nVerse 3\nNơm geh nau yỗ nuih n'hâm kloh ueh, mâp âk jêh nau rêh ni.\nSrôih bun âk ndơ khlay Păng klơ trôk, nuih n'hâm tĭng ndỗ Păng mro.\n\nVerse 4\nNau rêh hên blau đŏt bơh nau ngo, yor geh Păng ntop n'hâm suan.\nMa nau Brah Păng ăn hên yach hao, geh nau nkhôm nkra maak ngăn.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0227", "title": "NAU ANG TÂM NUIH N'HÂM", "song_number": "227", "lyrics": "NAU ANG TÂM NUIH N'HÂM\n\nTC 460\n\nVerse 1\nRi nau nchrat ang mâu dơi blau ntĭt, ma nau Brah Păng sol ang.\nAƀaơ nuih n'hâm gâp kloh ueh, ang rsang, yor geh Yê-su tho rao.\n\nChorus\nNau ang klu klâm! Nau nchrat ang ngăn! Lư nau rêh rdỡ rbăn ma nuih n'hâm gâp.\nDôl Yê-su toh yoi mbung gơm rum jêng nau ang sol tâm nuih n'hâm.\n\nVerse 2\nNgih nti mprơ nuih n'hâm gâp dôl nti, mprơ ndrel tâm rnê Kôranh Brah.\nÂk nau mprơ ueh Brah Krist ŭch iăt, nđâp lah gâp mâu lot mprơ.\n\nChorus\nNau ang klu klâm! Nau nchrat ang ngăn! Lư nau rêh rdỡ rbăn ma nuih n'hâm gâp.\nDôl Yê-su toh yoi mbung gơm rum jêng nau ang sol tâm nuih n'hâm.\n\nVerse 3\nAƀaơ geh yăn kao nuih n'hâm ueh mhe, yor Kôranh Brah gŭ êp gâp.\nRhơn nau đăp mpăn, ntơm dôl gŭ ngau, kao nau yỗ dang ang nchrat.\n\nChorus\nNau ang klu klâm! Nau nchrat ang ngăn! Lư nau rêh rdỡ rbăn ma nuih n'hâm gâp.\nDôl Yê-su toh yoi mbung gơm rum jêng nau ang sol tâm nuih n'hâm.\n\nVerse 4\nDu njăr rêh gâp geh nau maak ngăn, tông yơk kâp gân, mât ton.\nYor nau Păng yỗ gâp mâu dơi kơp, tât kăn-dỡ saơ Ƀon Ueh.\n\nChorus\nNau ang klu klâm! Nau nchrat ang ngăn! Lư nau rêh rdỡ rbăn ma nuih n'hâm gâp.\nDôl Yê-su toh yoi mbung gơm rum jêng nau ang sol tâm nuih n'hâm.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0228", "title": "YÊ-SU JÊNG MĬT JIĂNG SOL ANG HE", "song_number": "228", "lyrics": "YÊ-SU JÊNG MĬT JIĂNG SOL ANG HE\n\nTC 368\n\nVerse 1\nYê-su jêng mĭt jiăng sol ang he ƀa-ƀơ, nâm bu ŭnh ka-đen sol ang tâm ntŭk ngo klĕng,\nntŭk neh ntu vêt vê aơ ăn sol ang, ta ngih gâp, gâp sol ang, ntŭk may, may sol.\n\nVerse 2\nYê-su jêng mĭt jiăng sol ang Amoh Kôranh Brah, lah ŭnh kđen klu klâm Yê-su klơ trôk sol ang;\npuh gơnh djễ hom ŭnh kđen dĭng ang mro, ta ngih gâp, gâp sol ang, ntŭk may, may sol;\n\nVerse 3\nYê-su jêng mĭt jiăng sol ang ma lĕ bunuyh, kơl lĕ phung rngot rvê tâm ntŭk vêt vê ngo klĕng,\nntŭk neh ntu tih mhĭk ăn geh sol mro, ta ngih gâp, gâp sol ang, ntŭk may, may sol.\n\nVerse 4\nYê-su jêng mĭt jiăng sol ang he mro mrăng, leo bunuyh tih sĭt ma Păng gơnh lơi hom trong ngo;\nhe sol ang ƀaƀơ yor Păng ntop an pring ta ngih gâp, gâp sol ang, ntŭk may, may sol.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0229", "title": "DĂN KÔRANH BRAH DŎNG", "song_number": "229", "lyrics": "DĂN KÔRANH BRAH DŎNG\n\nTC 362\n\nVerse 1\nTông hom ma bâr mơih rmên tĭng Kôranh Brah lah: geh lĕ nơm ŭch kơl kan gâp a-ƀaơ?\nMbu ŭch hăn têk ndrêng bunuyh hươi rdja, vât vâng, mbu maak knŏng khân păng gĭt nau di aƀaơ.\n\nChorus\nKŭnh dăn Păng ăn nau dơi nuih n'hâm ŭch yơk ma nau Kôranh Brah kuăl.\nKŭnh dăn Păng maak dŏng mprơ, ôp: ơ geh gâp aơ dăn May dŏng ro.\n\nVerse 2\nKăl e Kôranh Brah ntăm jêh ma tông mpăr Păng tât ăn Ê-sai dơi jêng kloh ueh mro,\ntăng bâr nkoch mbơh, mbu yor ma gâp văch ro, tông mpăr ơh: Geh knŏng gâp, dŏng hom ro.\n\nChorus\nKŭnh dăn Păng ăn nau dơi nuih n'hâm ŭch yơk ma nau Kôranh Brah kuăl.\nKŭnh dăn Păng maak dŏng mprơ, ôp: ơ geh gâp aơ dăn May dŏng ro.\n\nVerse 3\nGeh âk bunuyh hươi rdja yor tih mhĭk tĭng jot, iăt hom bâr khân Păng nter kuăl măng nar;\nHơi oh nâu, ăn he ndrel ran rklaih khân păng, gơnh hom yơh: Geh knŏng gâp, dŏng hom ro.\n\nChorus\nKŭnh dăn Păng ăn nau dơi nuih n'hâm ŭch yơk ma nau Kôranh Brah kuăl.\nKŭnh dăn Păng maak dŏng mprơ, ôp: ơ geh gâp aơ dăn May dŏng ro.\n\nVerse 4\nNar aơ ôi taơ, jêh aơ, yan riu nsĭt nglĕ dŭt phung he mra nsĭt ba tâm jay grau grau\nkâp uănh geh nau gơm rhơn ntŭk Kôranh Brah he kâp iăt bâr Kôranh Brah rnê gâp jêh.\n\nChorus\nKŭnh dăn Păng ăn nau dơi nuih n'hâm ŭch yơk ma nau Kôranh Brah kuăl.\nKŭnh dăn Păng maak dŏng mprơ, ôp: ơ geh gâp aơ dăn May dŏng ro.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0230", "title": "DU NAU NCHRAT ANG", "song_number": "230", "lyrics": "DU NAU NCHRAT ANG\n\nTC 371\n\nVerse 1\nYê-su nti gâp măng nar nchrat ang, yor Păng sol ang lam ntŭk.\nLĕ ntil nau ƀư maak ma Păng, ta ngih nti ntŭk păng pâl rlưn.\n\nChorus\nDu nau nchrat ang nâm nar Kôranh Brah ŭch gâp sol ăn chrat ang.\nDu nar nchrat ang nâm nar, ăp nar ƀư chrêk rmah Amoh Păng.\n\nVerse 2\nYê-su nơm sâm nti gâp gŭ rêh, rŏng ma phung chiau meng he.\nMâu lah nti, sông sa, ngơi pâl rlưn, mpơl he jêng kon Brah Ndu.\n\nChorus\nDu nau nchrat ang nâm nar Kôranh Brah ŭch gâp sol ăn chrat ang.\nDu nar nchrat ang nâm nar, ăp nar ƀư chrêk rmah Amoh Păng.\n\nVerse 3\nĂp nar mbơh sơm nsing ma Yê-su mât mơh ntĭm nti nau rêh.\nTâm mpơl ma bu saơ lĕ nau rŏng, nđâp nau yỗ toyh Kôranh Brah.\n\nChorus\nDu nau nchrat ang nâm nar Kôranh Brah ŭch gâp sol ăn chrat ang.\nDu nar nchrat ang nâm nar, ăp nar ƀư chrêk rmah Amoh Păng.\n\nVerse 4\nTon geh nau nchrat ang yor Yê-su, dơi sol ang tâm lam ntŭk.\nGâp ton ƀư lĕ kan gâp dơi ƀư, jêh ri gŭ ndrel Kôranh Brah.\n\nChorus\nDu nau nchrat ang nâm nar Kôranh Brah ŭch gâp sol ăn chrat ang.\nDu nar nchrat ang nâm nar, ăp nar ƀư chrêk rmah Amoh Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0231", "title": "NHHƠR HOM MA PĂNG", "song_number": "231", "lyrics": "NHHƠR HOM MA PĂNG\n\nTC 374\n\nVerse 1\nYê-su khĭt jêh ta si tâm rkăng. Gay tâm rklaih tă bơh nau tih.\nNhhơr hom nuih n'hâm ma nau rŏng jêh, jao ma Păng lĕ ndơ khlay lơn.\n\nChorus\nNhhơr hom ma Păng lĕ ndơ khlay lơn. Nhhơr hom n'hâm suan dôl hôm mom.\nĂp nar nsong mbơh nau mhe mhan ueh. Njŭn âk bunuyh chroh ma Păng.\n\nVerse 2\nPăng mâu kah chuêl ôh nau jêr may. Păng ăn jêh kon Păng ma he.\nPah kan hom he ma lĕ nau rŏng, gơnh nhhơr ma Păng ndơ khlay lơn.\n\nChorus\nNhhơr hom ma Păng lĕ ndơ khlay lơn. Nhhơr hom n'hâm suan dôl hôm mom.\nĂp nar nsong mbơh nau mhe mhan ueh. Njŭn âk bunuyh chroh ma Păng.\n\nVerse 3\nPăng dơn nau ji ta si tâm rkăng. Yor lah gay geh nau tâm rklaih.\nNhhơr hom nuih n'hâm huêng may ma Păng, Păng ŭch ndơ ueh lơn may nhhơr.\n\nChorus\nNhhơr hom ma Păng lĕ ndơ khlay lơn. Nhhơr hom n'hâm suan dôl hôm mom.\nĂp nar nsong mbơh nau mhe mhan ueh. Njŭn âk bunuyh chroh ma Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0232", "title": "RĂM MAAK NGĂN PHUNG DRUH NDĂM HE MPRƠ", "song_number": "232", "lyrics": "RĂM MAAK NGĂN PHUNG DRUH NDĂM HE MPRƠ\n\nTC 382\n\nVerse 1\nRăm maak ngăn phung druh ndăm he mprơ nteh kŏ tât tâm ntŭk Ƀon Ueh, tâm rnê Amoh Yê-su khlay ir ar ngăn,\nri Kon Biăp Brah Ndu kăl e hoch mham yor gay chuai bunuyh tih mhĭk, yor ri Păng anh nau tih mhĭk neh ntu.\n\nChorus\nYê-su khĭt kăl e yor gay chuai he, Aƀaơ Păng gŭ pa ma Kôranh Brah ƀa-ƀơ.\nKăn dỡ taơ Yê-su jŭr văch, Păng ƀư Hađăch lam bri neh ntu. Mât ton Brah Yê-su he maak mprơ ndrel.\n\nVerse 2\nGŭ êp Yê-su dăn Păng rgâl phung he, Kôranh Brah ăn nau rêh mhe, ăn nau yỗ ma he tâm dôl rêh ni,\nn'ho dăn Kôranh Brah yỗ an lĕ nau tih mhĭk dôl gŭ tâm nau ngo, nau yỗ Kôranh Brah ăn he kah gĭt mro.\n\nChorus\nYê-su khĭt kăl e yor gay chuai he, Aƀaơ Păng gŭ pa ma Kôranh Brah ƀa-ƀơ.\nKăn dỡ taơ Yê-su jŭr văch, Păng ƀư Hađăch lam bri neh ntu. Mât ton Brah Yê-su he maak mprơ ndrel.\n\nVerse 3\nJêh nây mâu jŏ Yê-su mra plỡ văch, lĕ n'gor saơ Păng răm maak, Amoh Yê-su lư n'găr lam bri neh ntu,\nPăng jêng Hađăch tâm lĕ rngôch Ha-đăch Amoh Păng khlay ngăn, chrat ang ngăn, văch gơnh hom hên dôl kâp gân May aƀaơ.\n\nChorus\nYê-su khĭt kăl e yor gay chuai he, Aƀaơ Păng gŭ pa ma Kôranh Brah ƀa-ƀơ.\nKăn dỡ taơ Yê-su jŭr văch, Păng ƀư Hađăch lam bri neh ntu. Mât ton Brah Yê-su he maak mprơ ndrel.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0233", "title": "MAAK GŬ ÊP YÊ-SU", "song_number": "233", "lyrics": "MAAK GŬ ÊP YÊ-SU\n\nTC 380\n\nVerse 1\nYê-su Krist rŏng gâp, Păng lơi Ƀon Ueh, gay chuai gâp, yor nây gâp nsing ma Păng, ton ăn gâp tĭng Yê-su hăn lam ntŭk, ơ gŭ êp Yê-su gâp maak n'ho ro.\n\nChorus\nNuih n'hâm maak maak ngăn ơ Kôranh gâp êp kêng May, maak ngăn ngên! Gâp maak ngăn! maak ngăn ơ gŭ êp Yê-su gâp maak mro mrăng.\n\nVerse 2\nDăn kơp gâp jêng oh mon May klơ trôk, tâm nau rêh gâp knŏng maak nsing ta May, yor nau yỗ May jru rlau ma dak mƀŭt, ơ gŭ êp Yê-su gâp maak n'ho ro.\n\nChorus\nNuih n'hâm maak maak ngăn ơ Kôranh gâp êp kêng May, maak ngăn ngên! Gâp maak ngăn! maak ngăn ơ gŭ êp Yê-su gâp maak mro mrăng.\n\nVerse 3\nNđâp lah nau janh ktang njŭn gâp kđôi lĕ, nđâp lah nau khĭt nkrit nhhu gâp kđôi lĕ, ăt gâp đăp mpăn yor geh Kôranh Brah, ơ gŭ êp Yê-su gâp maak n'ho ro.\n\nChorus\nNuih n'hâm maak maak ngăn ơ Kôranh gâp êp kêng May, maak ngăn ngên! Gâp maak ngăn! maak ngăn ơ gŭ êp Yê-su gâp maak mro mrăng.\n\nVerse 4\nNđâp lah gâp geh nau nđêh nji kuet lte, nau rêh jâk jêr mâu geh nơm nsing ndăl, ăt nau yỗ bơh Brah Huêng Ueh kơl gâp, ơ gŭ êp Yê-su gâp maak n'ho ro.\n\nChorus\nNuih n'hâm maak maak ngăn ơ Kôranh gâp êp kêng May, maak ngăn ngên! Gâp maak ngăn! maak ngăn ơ gŭ êp Yê-su gâp maak mro mrăng.\n\nVerse 5\nGeh Kôranh Brah kuăl, gâp nhhơr săk jăn, nuih n'hâm, pah kan Păng, nuih n'hâm gâp maak hâu ngăn! nđâp lah jêr ăt maak tâm Krist, ơ gŭ êp Yê-su gâp maak n'ho ro.\n\nChorus\nNuih n'hâm maak maak ngăn ơ Kôranh gâp êp kêng May, maak ngăn ngên! Gâp maak ngăn! maak ngăn ơ gŭ êp Yê-su gâp maak mro mrăng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0234", "title": "RÊH TÂM YÊ-SU", "song_number": "234", "lyrics": "RÊH TÂM YÊ-SU\n\nTC 381\n\nVerse 1\nRêh tâm Yê-su lĕ nau rêh Păng sâm chuai jêh lĕ nau mĭn, nau ngơi nau gâp ŭch tâm ăp nar jêh ri ăp mông Păng chuai huêng gâp.\n\nVerse 2\nĂn ti gâp ƀư tĭng Păng ŭch, ăn jâng gâp chuat tâm trong Păng ăn tôr gâp iăt knŏng Yê-su dơm, ăn mpiăt gâp mprơ tâm r-nê Păng\n\nVerse 3\nNtơm bơh măt gâp saơ Brah Yê-su, gâp lơi lĕ rngôch ndơ pa kơi. Păng sâm rle măt huêng nuih n'hâm gâp, uănh ta ntŭk bu hŏ pâng Păng.\n\nVerse 4\nƠ khlay ngăn ngên, khlay ir ar ngăn, Yê-su jêng nau chrêk ma lơp gâp tăng Păng kuăl ma bâr rdỡ rbăn, ăn gâp rlu tâm dâng nar Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0235", "title": "MÂU YOR MA PRĂK MAIH", "song_number": "235", "lyrics": "MÂU YOR MA PRĂK MAIH\n\nTC 190\n\nVerse 1\nNau tâm chuai gâp mâu yor r-văt ma prăk maih ôh; Nau ndrŏng ta neh ntu mâu dơi ôh rvăt huêng gâp; Knŏng ma mham Brah Yê-su ta si tâm rkăng yơh dơi; Jêng nau tâm chuai khlay ngăn, tâm mham Brah Yê-su.\n\nChorus\nNau Tâm chuai he mâu yor prăk maih ôh. Yor nau yỗ dơi tâm chuai he. Ta si tâm rkăng Brah Yê-su hoch mham yor nau rŏng, Păng khĭt trok he.\n\nVerse 2\nNau tâm chuai gâp mâu yor r-văt ma prăk maih ôh; He kon sau A-Đam; Deh tâm nau ƀỡ ƀơch ngăn; Knŏng ma mham Brah Yê-su ta si tâm rkăng yơh dơi; Jêng nau tâm chuai khlay ngăn, tâm mham Brah Yê-su.\n\nChorus\nNau Tâm chuai he mâu yor prăk maih ôh. Yor nau yỗ dơi tâm chuai he. Ta si tâm rkăng Brah Yê-su hoch mham yor nau rŏng, Păng khĭt trok he.\n\nVerse 3\nNau tâm chuai gâp mâu yor r-văt ma prăk maih ôh; Nau vay ơm ŭch kuăn gâp plỡ sĭt ma Mbỡ Nơm; Knŏng ma mham Brah Yê-su ta si tâm rkăng yơh dơi; Jêng nau tâm chuai khlay ngăn, bah lĕ nau klach krit.\n\nChorus\nNau Tâm chuai he mâu yor prăk maih ôh. Yor nau yỗ dơi tâm chuai he. Ta si tâm rkăng Brah Yê-su hoch mham yor nau rŏng, Păng khĭt trok he.\n\nVerse 4\nNau tâm chuai gâp mâu yor r-văt ma prăk maih ôh; Pô nây bu mâu dơi lăp ôh Ƀon Ueh Brah Ndu; Knŏng ma mham Brah Yê-su ta si tâm rkăng yơh dơi; Jêng nau tâm chuai khlay ngăn, tâm mham Brah Yê-su.\n\nChorus\nNau Tâm chuai he mâu yor prăk maih ôh. Yor nau yỗ dơi tâm chuai he. Ta si tâm rkăng Brah Yê-su hoch mham yor nau rŏng, Păng khĭt trok he.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0236", "title": "LĂP TÂM NUIH N'HÂM", "song_number": "236", "lyrics": "LĂP TÂM NUIH N'HÂM\n\nTC 449\n\nVerse 1\nLăp tâm nuih n'hâm gâp tâm nuih n'hâm, ngo n'ho dơi jêng ang, Brah Yê-su, lăp hom nar aơ, lăp hom ƀa-ƀơ, lăp tâm nuih n'hâm gâp Brah Yê-su.\n\nVerse 2\nLĕ nuih n'hâm gâp aơ sŏk hom nuih n'hâm gâp a-ƀaơ aơ, Brah Yê-su, sŏk hom nar aơ, sŏk lĕ săk jăn, sŏk lĕ nau rêh gâp Brah Yê-su.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0237", "title": "LAH YÊ-SU TÂT", "song_number": "237", "lyrics": "LAH YÊ-SU TÂT\n\nTC 386\n\nVerse 1\nBu nuyh chieh măt gŭ êng du huê ta meng trong, gay dăn ndơ sa, âk phung bunuyh rgăn ta nây. Ô băl rngot êng, mâu geh du huê nơm kơl păng, Brah Yê-su tât ta nây mprơh nau ngo păng.\n\nChorus\nLah Yê-su tât, brah mhĭk roh lĕ nau brah păng. Lah Yê-su tât, Păng jut lơi lĕ dak măt. Păng mprơh nau rngot mbêng he ma nau chrêk ma lơp, lĕ ndơ tâm rgâl lah Brah Yê-su gŭ ndrel.\n\nVerse 2\nPhung brah mhĭk mprơh lơi păng du ngai đah băl mpôl, gŭ êng tâm môch, păng geh âk nau rêh ni. Ô băl sôt săk dơn nau nđêh nji brah mhĭk lơn, Brah Yê-su tât gay ăn păng jêng kon me.\n\nChorus\nLah Yê-su tât, brah mhĭk roh lĕ nau brah păng. Lah Yê-su tât, Păng jut lơi lĕ dak măt. Păng mprơh nau rngot mbêng he ma nau chrêk ma lơp, lĕ ndơ tâm rgâl lah Brah Yê-su gŭ ndrel.\n\nVerse 3\nGeh du huê bu klâu phŭng sa nter hâu ngăn ngên, geh đŏng ta nây phung têk jêh ri phung mlo. Âk geh bunuyh rngot hâu ngăn ngên ăp ntil nau ji, Brah Yê-su tât ta nây ƀư bah khân păng.\n\nChorus\nLah Yê-su tât, brah mhĭk roh lĕ nau brah păng. Lah Yê-su tât, Păng jut lơi lĕ dak măt. Păng mprơh nau rngot mbêng he ma nau chrêk ma lơp, lĕ ndơ tâm rgâl lah Brah Yê-su gŭ ndrel.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0238", "title": "PHUNG HE NÂM BU BIĂP HIƠT", "song_number": "238", "lyrics": "PHUNG HE NÂM BU BIĂP HIƠT\n\nTC 438 (Ê-sai 53:6)\n\nVerse 1\nLĕ rngôch he jêng nâm bu biăp hiơt, dah tĭng trong êng. Lĕ rngôch he jêng nâm bu biăp jêh, Brah Yê-su tât jêh. Yê-su tât jêh, joi gay tâm rklaih bunuyh roh hêt. Lĕ rngôch huêng bunuyh roh rai.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0239", "title": "GÂP NHHƠR LĔ MA MAY", "song_number": "239", "lyrics": "GÂP NHHƠR LĔ MA MAY\n\nTc 282\n\nVerse 1\nGâp nhhơr lĕ rngôch ma Kôranh Brah Yê-su, gâp nhhơr lĕ săk jăn aơ.\nRŏng ƀa-ƀơ kâp gân knŏng ma Kôranh Brah, rêh tâm nau yỗ May yơh.\n\nChorus\nGâp nhhơr lĕ ma may, Gâp nhhơr lĕ ma May\nƠ Yê-su nuih n'hâm săk jăn gâp, nhhơr lĕ rngôch ma May.\nA-Men.\n\nVerse 2\nGâp nhhơr lĕ rngôch ma Kôranh Brah Yê-su gâp chon ta năp may yơh,\nUănh nau maak neh ntu ƀỡ ƀơch tih mhĭk, dăn May rom gâp aƀaơ ro.\n\nChorus\nGâp nhhơr lĕ ma may, Gâp nhhơr lĕ ma May\nƠ Yê-su nuih n'hâm săk jăn gâp, nhhơr lĕ rngôch ma May.\nA-Men.\n\nVerse 3\nGâp nhhơr lĕ rrngôch ma Kôranh Brah Yê-su, nau rêh gâp nhhơr ma May.\nDăn nau rŏng brah ktang mbêng ler ƀa-ƀơ, bơh May nkhŭt ăn ma gâp.\n\nChorus\nGâp nhhơr lĕ ma may, Gâp nhhơr lĕ ma May\nƠ Yê-su nuih n'hâm săk jăn gâp, nhhơr lĕ rngôch ma May.\nA-Men.\n\nVerse 4\nGâp nhhơr lĕ rngôch ma Kôranh Brah Yê-su, gĭt năl ŭnh nau brah May,\nBơh nau may tâm rklaih gâp maak hâu ngăn, amoh May chrêk rmah n'ho ro.\n\nChorus\nGâp nhhơr lĕ ma may, Gâp nhhơr lĕ ma May\nƠ Yê-su nuih n'hâm săk jăn gâp, nhhơr lĕ rngôch ma May.\nA-Men.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0240", "title": "NHÊT SA TÂM ÊP", "song_number": "240", "lyrics": "NHÊT SA TÂM ÊP\n\nTC 400\n\nVerse 1\nNhêt sa tâm êp Păng nkra lor, ăn ma oh mon kăl e. n'ho ma ăp rnôk dơi nkah gĭt. Păng nkhĭt ntrok ăn yor he.\n\nChorus\nNkah rvê Păng khĭt hoch mham yor he ăn he mbơh nau Yê-su khĭt.\n\nVerse 2\nSi tâm rkăng Păng dơn nđêh nji, oh mon nđâp Mbỡ du ngai. Bêk prêng nđêh nji mâu đơh rđêng. săk rai mham Păng hoch jêh.\n\nChorus\nNkah rvê Păng khĭt hoch mham yor he ăn he mbơh nau Yê-su khĭt.\n\nVerse 3\nDjôt piăng let nkah săk Păng rai, ma yor nau tih phung he. Djôt kchok he nkah mham Păng hoch. Ăn nau tâm rklaih âk bunuyh.\n\nChorus\nNkah rvê Păng khĭt hoch mham yor he ăn he mbơh nau Yê-su khĭt.\n\nVerse 4\nDăn Kôranh Brah yỗ lĕ nau tih, hŏ rlau jêh nau vay Păng. Dăn mham khlay rao ăn kloh ƀhiau khư râng nhêt sa tâm êp.\n\nChorus\nNkah rvê Păng khĭt hoch mham yor he ăn he mbơh nau Yê-su khĭt.\n\nVerse 5\nNhêt sa tâm êp nar ueh maak, nar tâm nkol Kon Biăp kloh. Nuih n'hâm kâp gân Păng plỡ văch. Nôk dŭt lôch ma nau tih.\n\nChorus\nNkah rvê Păng khĭt hoch mham yor he ăn he mbơh nau Yê-su khĭt.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0241", "title": "TÂM RNÊ MA PE HAĐĂCH BRAH", "song_number": "241", "lyrics": "TÂM RNÊ MA PE HAĐĂCH BRAH\n\nTC 420\n\nVerse 1\nTâm rnê ma Brah Mbỡ! Amoh Păng jêng Nơm rhăk ăp ntil ndơ, geh nau dơi chiă uănh, nau rŏng Păng jru huy mâu hôm blau ntĭt.\n\nVerse 2\nTâm rnê ma Brah Kon! lư n'găr, nau dơi tâm ban Brah Mbỡ; Păng jŭr ta neh ntu, nhhơr săk jăn khĭt ntrok gay rklaih kon bunuyh;\nnhhơr dơm ăn he, Păng khĭt ta si tâm rkăng krit ngăn, khĭt tâp tâm môch tât pe nar; yor Huêng Brah Mbỡ ăn, Păng dâk rêh chrêk rmah ngăn.\nntrok ăn he dôl vơh vơl gŭ mpeh bah ma Brah Mbỡ. Dăch plỡ tay bêng chrêk rmah vơt sŏk phung oh mon mông nây. Lĕ he mra mprơ nteh huy.\n\nVerse 3\nMra dơi chiă uănh ndrel Păng âk rmưn năm gŭ rƀŭn jŭm Păng nơm Gâp tâm rnê ƀa-ƀơ ma Brah Huêng Ueh, jêng Amoh Brah tâl pe (Brah lit rnam) Mra njŭn leo gâp tâm trong sŏng.\nBrah Mbỡ Brah Kon ndrel Huêng Ueh êng ngăn. Amoh pe Brah jêng nguay n'ho ro, nau dơi tâm ban. Khư rnê Păng mro mrăng....\n\nVerse 4\nHuêng gâp bêng nau maak ngăn yor pe Hađăch Brah Ndu hŏ ăn jêh Tâm nau ngơi êng ngăn nây bơh nau Brah Ndu hŏ ơm mbơh jêh (Hôm mro mrăng)\nDi ngăn mâu geh trong rlet ôh. Păng siăm piăng let du bông nau rêh gâp. Ơ lĕ rngôch phung mpôl băl he, mprơ ndrel n'grŭp gay tâm rnê Pe Hađăch Brah.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0242", "title": "DĂN KÔRANH BRAH ƀƯ ANG MĂT GÂP", "song_number": "242", "lyrics": "DĂN KÔRANH BRAH ƀƯ ANG MĂT GÂP\n\nTC 432 (Nau Mprơ Ơm 119:18,89,105)\n\nVerse 1\nƠ Brah Ndu Nau Ngơi May gŭ nâp ngăn n'ho ro tâm trôk, gŭ nâp ngăn n'ho ro tâm trôk. Nau Ngơi May jêng n'gâng ŭnh. Sol ăn ang ma jâng gâp. Jêng nau ang ma trong rlong gâp hăn sang ƀa-ƀơ ma trong gâp.\n\nChorus\nDăn ƀư ang măt gâp, dăn ƀư ang măt gâp, gay dơi saơ lĕ ntil khlay tâm nau vay Brah Ndu.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0243", "title": "DĂN NJŬN GÂP SĬT MA GÔ-GÔ-THA", "song_number": "243", "lyrics": "DĂN NJŬN GÂP SĬT MA GÔ-GÔ-THA\n\n\nVerse 1\nDăn mbỡ njŭn gâp sĭt ma yôk kăl-e... Klơ Gô-gô-tha Kôranh Brah khĭt Ta si tâm rkăng.\nNtŭk Brah Yê-su nơm kuăl gâp, nau mơih rmên ngăn...\nNuih n'hâm gâp mâu geh chuêl ôh lĕ nau Păng rŏng,\nNtơm bơh nar mông gâp nkhah du ngai đah Kôranh Brah... Ăp nar gŭ iăng hêng tâm nau tih mhĭk hâu ngăn...\nKlơ yôk Gô-tha Yê-su hŏ yỗ lĕ nau tih. Nau Kôranh Brah rŏng njŭn leo gâp dơi tât ntŭk rlu.\n\nVerse 2\nDăn Mbỡ njŭn gâp sĭt ma yôk kal-e... Gay gâp gŭ rvê nau May khĭt Ta si tâm rkăng.\nSâm njêng nuih n'hâm gâp gĭt rŏng ŭnh nau Brah May...\nNhĭm luh dak măt mƀăr lơi lĕ rngôch nau tih mhĭk,\nÔ! tâm ntŭk ri Brah Yê-su laih ti rklaih gâp... Sôt rmanh pŭng vĕ mham khlay hoch ŭch ƀư mhe gâp...\nSâm njŭn leo gâp rgăn neh ntu sĭt ma ngih Mbỡ. Nuih n'hâm gâp chrê ƀa-ƀơ ma yôk Gô-gô-tha.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0244", "title": "MÂU GEH NTŬK KLOH ĂN MA YÊ-SU", "song_number": "244", "lyrics": "MÂU GEH NTŬK KLOH ĂN MA YÊ-SU\n\n\nVerse 1\nMâu geh ntŭk kloh ma Yê-su văch jŭr ta neh ntu, H'-ma-ri lâng bêch Păng tâm hip bu siăm ndrôk.\nPhung mănh rêp ƀiêp ka-lơ trôk, uănh ma Păng măng nây. Yê-su Kon Se Jễ gŭ bênh tâm gỡ kro ndrôk.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0245", "title": "KƠL GÂP NJŬN HUÊNG BUNUYH", "song_number": "245", "lyrics": "KƠL GÂP NJŬN HUÊNG BUNUYH\n\n\nVerse 1\nNjŭn gâp ma du huê nar aơ. Ơ Kôranh Brah nti gâp moh mra ngơi.\nMĭt jiăng gâp roh tâm nau tih. Mâu gĭt saơ trong tâm rklaih.\nknŏng djễ bunuyh chrê ma khân ô băl, kanŏng djê bunuyh mbơh sơm.\nĂn Brah Huêng Ueh mbêng tâm gâp kơl gâp njŭn du huê chroh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0246", "title": "VĂCH HOM, Ê-MA-NU-EL", "song_number": "246", "lyrics": "VĂCH HOM, Ê-MA-NU-EL\n\n\nVerse 1\nVăch hom! văch hom! Ê-ma-nu-el. Tâm chuai phung ƀon I-sra-el jêng dĭk, dôl gŭ nhĭm êng tâm ntŭk bu mprơh.\nKŏ tât nar Kon Brah Ndu tâm mpơl.\n\nChorus\nMaak hom! maak hom! Ê-ma-nu-el. Mra văch ma may ơ I-sra-el.\n\nVerse 2\nVăch hom! văch hom! bu deh ma may. Ƀư maak nuih n'hâm jêh ri nau mĭn hên, veng mprơh lơi lĕ nau ngo mhĭk nkŭm.\nDôl klong măng jêh ri dôl du mpăr.\n\nChorus\nMaak hom! maak hom! Ê-ma-nu-el. Mra văch ma may ơ I-sra-el.\n\nVerse 3\nVăch hom! văch hom! lĕ băl mpôl bunuyh. Rŏng lĕ rngôch phung ƀon lan du nuih n'hâm, n'hŭch lơi nau kơnh nđâp nau tâm lơh.\nĂn neh ntu bêng ma nau đăp mpăn.\n\nChorus\nMaak hom! maak hom! Ê-ma-nu-el. Mra văch ma may ơ I-sra-el.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0247", "title": "GÂP JÊNG BUNUYH TIH", "song_number": "247", "lyrics": "GÂP JÊNG BUNUYH TIH\n\nTC 466\n\nVerse 1\nNau ueh jŭr tă klơ, uănh gâp bunuyh tih mhĭk. Nuih n'hâm gâp ƀỡ ƀơch, Kôranh Brah rao kloh jêh.\nDơn khĭt ta si rkăng hoch mham hâu ngăn. Nau tih gâp âk ir ngăn, Păng rao kloh.\n\nChorus\nGâp deh tâm neh ntu, bunuyh ƀỡ ƀơch, bêng rluk mâl, tih mhĭk, mâu blau kơp.\nGâp mâu khư jêng khlay, mƀruh nchơt, geh nau kơnh, mâm ƀư Kôranh Brah ŭch uănh, Păng jêng ueh.\n\nVerse 2\nKăl-e nau tih nkŭm, krăk kher ƀỡ nuih n'hâm. Yor ri ngai đah Păng, tĭng ndỗ trong rai yot.\nAƀaơ rnơm nau kloh ueh, njŭn sĭt trong sŏng. Yỗ ăn ro nau tih mhĭk, Păng yỗ jêh.\n\nChorus\nGâp deh tâm neh ntu, bunuyh ƀỡ ƀơch, bêng rluk mâl, tih mhĭk, mâu blau kơp.\nGâp mâu khư jêng khlay, mƀruh nchơt, geh nau kơnh, mâm ƀư Kôranh Brah ŭch uănh, Păng jêng ueh.\n\nVerse 3\nDôl hôm tih gâp nhĭm, jêh ri gâp nhĭm êng. Aƀaơ yor Yê-su rklaih, ƀư kloh jêh nau tih.\nHuêng mprơ tâm rnê mro, Brah Ndu nau rŏng. Gâp vơh vơl yor tih gâp, mham May hoch.\n\nChorus\nGâp deh tâm neh ntu, bunuyh ƀỡ ƀơch, bêng rluk mâl, tih mhĭk, mâu blau kơp.\nGâp mâu khư jêng khlay, mƀruh nchơt, geh nau kơnh, mâm ƀư Kôranh Brah ŭch uănh, Păng jêng ueh.\n\nVerse 4\nGâp ƀư tih ƀỡ ƀơch, mâu dơi blau kơp ôh. Yor nau yỗ Kôranh Brah, yỗ an hoch mham khlay,\nNtrok nau tih lôch jêh, ta si tâm rkăng. Ma phung he geh nau rnơm, Păng yỗ ro.\n\nChorus\nGâp deh tâm neh ntu, bunuyh ƀỡ ƀơch, bêng rluk mâl, tih mhĭk, mâu blau kơp.\nGâp mâu khư jêng khlay, mƀruh nchơt, geh nau kơnh, mâm ƀư Kôranh Brah ŭch uănh, Păng jêng ueh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0248", "title": "DƠN TUY SI TÂM RKĂNG", "song_number": "248", "lyrics": "DƠN TUY SI TÂM RKĂNG\n\n\nVerse 1\nUănh hom mbu nơm dơn jêh tuy si tâm rkăng, chuat jâng kŏ tât cha lôt ta neh.\nMbu nơm dơn nau bu dong ma mâng sôt lĕ, Kôranh Brah Yê-su tuy si tâm rkăng.\n\nChorus\nƠ kon maak dơn tuy ndrel đah Gâp, iăt hom nau rŏng Gâp ŭch kuăl may,\nyor may Gâp maak dơn kan tuy si tâm rkăng ŭch khĭt trok ăn khân may.\n\nVerse 2\nUănh hom bơh bôk Gâp têl bu ndô đon lok, ta pŭng vĕ têl bu ntâp ma tak.\nUănh hom bar đanh ti têl bu pâng ka-đĭn, Gâp dơn nau jêr ma yor rŏng may.\n\nChorus\nƠ kon maak dơn tuy ndrel đah Gâp, iăt hom nau rŏng Gâp ŭch kuăl may,\nyor may Gâp maak dơn kan tuy si tâm rkăng ŭch khĭt trok ăn khân may.\n\nVerse 3\nAƀaơ gâp ŭch tông bâr ƀư tĭng nâm Mbỡ ŭch, maak dơn tuy si tâm rkăng nar.\nDơn tuy kŏ tât Brah Yê-su Krist plỡ văch, Păng tâm rnê he kon ueh măt Gâp.\n\nChorus\nƠ kon maak dơn tuy ndrel đah Gâp, iăt hom nau rŏng Gâp ŭch kuăl may,\nyor may Gâp maak dơn kan tuy si tâm rkăng ŭch khĭt trok ăn khân may.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0249", "title": "YOR NAU TIH GÂP", "song_number": "249", "lyrics": "YOR NAU TIH GÂP\n\n\nVerse 1\nNơm tâm rklaih rŏng ma gâp, kŏ tât khĭt luh mham khlay mbu nơm gĭt Kôranh Brah dơn yor nau tih gâp.\nBơh nau ƀỡ ƀơch tâm gâp, mâu dơi klaih bơh brah mhĭk jŭm gâp geh âk nau tih rêh tâm neh ntu\n\nChorus\nHa đăch Yê-su Nơm Tâm Rklaih tâm Yê-su gâp dơi klaih jêh rŏng gâp Yê-su hŏ ntrok khĭt chuai nau tih gâp.\n\nVerse 2\nGâp nkah ƀa-ƀơ gô-tha, geh nau ngo klĕng dŭt n'hâm Kôranh Brah Păng dơn nau khĭt yor nau tih gâp.\nBơh ntơm nau nđêh nji ngăn, mbu nơm gĭt nau Păng rŏng bu ntâp ta pŭng vĕ Păng kŏ tât tăch n'hâm.\n\nChorus\nHa đăch Yê-su Nơm Tâm Rklaih tâm Yê-su gâp dơi klaih jêh rŏng gâp Yê-su hŏ ntrok khĭt chuai nau tih gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0250", "title": "NAU TIH RAI JÊH TA YÔK GÔ-GÔ-THA", "song_number": "250", "lyrics": "NAU TIH RAI JÊH TA YÔK GÔ-GÔ-THA\n\n\nVerse 1\nNeh ntu aơ nau tih mhĭk hâu ngăn, nau rŭng răng klân rvê\n\nChorus\nNau tih rai jêh ta yôk Gô-gô-tha. Yê-su gŭ ndrel ma he.\nNau tih rai jêh ta yôk Gô-gô-tha, Gô-gô-tha, Gô-gô-tha\nNau tih rai jêh ta yôk Gô-gô-tha. Yê-su gŭ ndrel ma he.\n\nVerse 2\nMƀăr nau rngot ma yôk Gô-gô-tha, Kôranh Brah anh lĕ jêh\n\nChorus\nNau tih rai jêh ta yôk Gô-gô-tha. Yê-su gŭ ndrel ma he.\nNau tih rai jêh ta yôk Gô-gô-tha, Gô-gô-tha, Gô-gô-tha\nNau tih rai jêh ta yôk Gô-gô-tha. Yê-su gŭ ndrel ma he.\n\nVerse 3\nYê-su gĭt lĕ nau rŭng răng he, Kôranh Brah mât ƀa-ƀơ\n\nChorus\nNau tih rai jêh ta yôk Gô-gô-tha. Yê-su gŭ ndrel ma he.\nNau tih rai jêh ta yôk Gô-gô-tha, Gô-gô-tha, Gô-gô-tha\nNau tih rai jêh ta yôk Gô-gô-tha. Yê-su gŭ ndrel ma he.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0251", "title": "TÂM N'GAR Ê-ĐEN KĂL E", "song_number": "251", "lyrics": "TÂM N'GAR Ê-ĐEN KĂL E\n\n\nVerse 1\nRnôk nây tâm n'ngar Ê-đen kăl e Kôranh Brah tâm rnglăp bar hê. Rnôk nây geh rbăn phung sĭm mpăr hơk maak răm r-hơn klơ trôk.\n\nChorus\nMât ton ma bar hê ăt rŏng ƀa-ƀơ. Mât ton bar hê tâm nau rŏng ueh maak.\nRêh đăp mpăn tâm Kôranh Brah ma nau rŏng n'hêl ngăn. Nđâp mâp âk nau jêr ăt mâu dơi tâm nkhah ôh.\n\nVerse 2\nKon bunuyh ntơm bơh nar nây geh jêh nau rŏng tâm n'ngar Ê-đen. Lĕ nar, năm, khay rlau jêh nau rŏng rdỡ rbân ma-ak ƀa-ƀơ.\n\nChorus\nMât ton ma bar hê ăt rŏng ƀa-ƀơ. Mât ton bar hê tâm nau rŏng ueh maak.\nRêh đăp mpăn tâm Kôranh Brah ma nau rŏng n'hêl ngăn. Nđâp mâp âk nau jêr ăt mâu dơi tâm nkhah ôh.\n\nVerse 3\nTâm âk ntŭk rgăn jêh pô ri tâm ntŭk nay geh âk ntŭk rgâl. Ƀiă lah geh âk nuih n'hâm rŭng răng tâm nau rŏng ăt răp jăp.\n\nChorus\nMât ton ma bar hê ăt rŏng ƀa-ƀơ. Mât ton bar hê tâm nau rŏng ueh maak.\nRêh đăp mpăn tâm Kôranh Brah ma nau rŏng n'hêl ngăn. Nđâp mâp âk nau jêr ăt mâu dơi tâm nkhah ôh.\n\nVerse 4\nTâm nar trôk ueh maak aơ jêng nar maak răm Kôranh Brah săch jêh. Nau rŏng khân păng bar hê ton jêh ta nklang ntŭk ma nau yơk.\n\nChorus\nMât ton ma bar hê ăt rŏng ƀa-ƀơ. Mât ton bar hê tâm nau rŏng ueh maak.\nRêh đăp mpăn tâm Kôranh Brah ma nau rŏng n'hêl ngăn. Nđâp mâp âk nau jêr ăt mâu dơi tâm nkhah ôh.\n\nVerse 5\nMprơ hom nau mprơ rdơ rbân tâm nar Kôranh Brah rnglăp jêh khân păng. Mprơ maak hom ma khân păng ndrel n'grŭp tâm nau rdâk njêng maak aơ.\n\nChorus\nMât ton ma bar hê ăt rŏng ƀa-ƀơ. Mât ton bar hê tâm nau rŏng ueh maak.\nRêh đăp mpăn tâm Kôranh Brah ma nau rŏng n'hêl ngăn. Nđâp mâp âk nau jêr ăt mâu dơi tâm nkhah ôh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0252", "title": "TÂM NKOL PHUNG RMĂK BIĂP", "song_number": "252", "lyrics": "TÂM NKOL PHUNG RMĂK BIĂP\n\n\nVerse 1\nUănh phung biăp chuat ran dăch n'hor dak rsang tâm ndrêch gỡ rse đăp mpăn. Nơm rmăk kâp gân geh băl mpôl kơl ndrel ta trong.\nTâm rnglăp tâm nau mĭn nau rŏng ndrel n'grŭp chiă uănh phung biăp Kôranh Brah, Nơm rmăk kâp gân geh du huê Nơm kơl n'hêl ngăn.\n\nChorus\nMprơ hom he yor nau ueh maak Kôranh Brah ăn, rŏng mâu rlu tâm Kôranh Brah bơh nar aơ.\nTâm rnglăp n'hêl ngăn tâm nau brah ktang Kôranh Brah, ăn he rŏng nâm bu Nơm Rmăk Biăp Ueh.\n\nVerse 2\nNar găn rlau jêh he tăng bâr phung biăp mprơ maak tâm ndrêch gỡ rse. Phung biăp âk râk tĭng dak n'hor joi kao tâm bri.\nMa nau maak khân păng lŏ sĭt tâm ndrêch gỡ rse nkra ntŭk nghih Mbỡ, jêh ri kơl tâm pă nkra ma nau tâm kol ngăn.\n\nChorus\nMprơ hom he yor nau ueh maak Kôranh Brah ăn, rŏng mâu rlu tâm Kôranh Brah bơh nar aơ.\nTâm rnglăp n'hêl ngăn tâm nau brah ktang Kôranh Brah, ăn he rŏng nâm bu Nơm Rmăk Biăp Ueh.\n\nVerse 3\nUănh hom tâm ntŭk ndrêch gỡ rse nđâp thŭl tŭk nglang ueh ta klơ trôk. Hâk maak geh bar hê băl rŏng lăp nghih Brah Ndu.\nBơh ngai phung biăp tâm rnglăp mât ton ma bar hê ur sai mhe nglăp, leo ndơ nhhơr ma ur sai nơm rmăk biăp rŏng ngăn.\n\nChorus\nMprơ hom he yor nau ueh maak Kôranh Brah ăn, rŏng mâu rlu tâm Kôranh Brah bơh nar aơ.\nTâm rnglăp n'hêl ngăn tâm nau brah ktang Kôranh Brah, ăn he rŏng nâm bu Nơm Rmăk Biăp Ueh.\n\nVerse 4\nPhung kon biăp nar aơ mât ton bar hê dôl chuat hăn tâm neh ntu. Pah kan n'hêl ngăn ma Kôranh Brah tâm nau sŏng srăng.\nLĕ nar gŭ rêh ta neh ntu ƀư maak chrat ang Amoh Brah Ndu Mbỡ, tâm nau rŏng Kôranh Brah hăn rklaih biăp ngai đah n'gar.\n\nChorus\nMprơ hom he yor nau ueh maak Kôranh Brah ăn, rŏng mâu rlu tâm Kôranh Brah bơh nar aơ.\nTâm rnglăp n'hêl ngăn tâm nau brah ktang Kôranh Brah, ăn he rŏng nâm bu Nơm Rmăk Biăp Ueh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0253", "title": "NAR NÔ-EL RĂM MAAK", "song_number": "253", "lyrics": "NAR NÔ-EL RĂM MAAK\n\n\nVerse 1\nBêng ma nau răm maak tâm nar Nô-el, Brah Ndu Nơm Tâm Rklaih gâp.\nYor lah nau rŏng, nau yỗ May toyh hâu ngăn, tât jêh ma nau rêh gâp.\n\nChorus\nGâp răm maak, răm maak, răm maak tâm Kôranh Brah. Jêng bôk nau răm maak, răm ma-ak răm ma-ak.\nYor lah Kon Brah Ndu jŭr văch jêh.\n\nVerse 2\nBêng ma nau răm maak tâm nar Nô-el, phung tông mpăr ueh Brah Ndu.\nPhung rmăk biăp jêh ri phung ha-đăch bri ngai, mprơ tâm rnê ma Yê-su.\n\nChorus\nGâp răm maak, răm maak, răm maak tâm Kôranh Brah. Jêng bôk nau răm maak, răm ma-ak răm ma-ak.\nYor lah Kon Brah Ndu jŭr văch jêh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0254", "title": "NAU NGƠI KÔRANH BRAH NÂP NGĂN", "song_number": "254", "lyrics": "NAU NGƠI KÔRANH BRAH NÂP NGĂN\n\nTC 151\n\nVerse 1\nNđâp lah phung rlăng rdâng lơh hâu ngăn, nau Brah Ndu Ngơi nâp lơn, yor geh nau Brah toyh Păng nkŭm king, yor nây mâu dơi roh yot.\nÂk nau janh ƀai brah mhĭk ka đôi dơi ta han Krist ƀư rai, Păng n'ho mâu blau mpât n'gơ djễ ro, Păng nâp nâm akô dak mro.\n\nChorus\nNau Ngơi Păng nâp rjăp ro. Nâp mro mrăng mâu blau rgâl ôh, lư n'găr lam bri neh ntu. Nau Brah Păng gŭ ăp ntŭk.\nNau Ngơi Kôranh Brah gŭ nâp, rgăn nđâp lah âk brah mhĭk ndơm rkhŭk trôk, neh ntu, mra lêk nâm thŭl tŭk Nau Brah Ndu Ngơi hôm mro.\n\nVerse 2\nNđâp lah phung rlăng rdâng ma ndơ janh, nau Branh Ndu ngơi lơ thanh, geh bunuyh đing ma nau Branh Ndu Ngơi, nâm bu hăr pănh mưt pla.\nNau Brah Ndu Ngơi nâp nâm bu lŭ klêr bu mưch rmot kđôi lĕ; phung Kon Kôranh Brah mra geh; nau nkhôm, knŏng Nau Ngơi Păng hôm mro.\n\nChorus\nNau Ngơi Păng nâp rjăp ro. Nâp mro mrăng mâu blau rgâl ôh, lư n'găr lam bri neh ntu. Nau Brah Păng gŭ ăp ntŭk.\nNau Ngơi Kôranh Brah gŭ nâp, rgăn nđâp lah âk brah mhĭk ndơm rkhŭk trôk, neh ntu, mra lêk nâm thŭl tŭk Nau Brah Ndu Ngơi hôm mro.\n\nVerse 3\nDu ai nkoch nau mhe mhan ueh gay lam bu nuyh gĭt da dê, yor ma nau rŏng toyh Kôranh Brah Mbỡ, Geh Kon Kôranh Brah rklaih he.\nNau janh ka tang Brah Huêng Ueh chrêk rmah ƀư Sa-tan rai lêk, nđâp lah neh ntu geh nau rgâl trơn, nau Brah Ndu Ngơi ăt kơn.\n\nChorus\nNau Ngơi Păng nâp rjăp ro. Nâp mro mrăng mâu blau rgâl ôh, lư n'găr lam bri neh ntu. Nau Brah Păng gŭ ăp ntŭk.\nNau Ngơi Kôranh Brah gŭ nâp, rgăn nđâp lah âk brah mhĭk ndơm rkhŭk trôk, neh ntu, mra lêk nâm thŭl tŭk Nau Brah Ndu Ngơi hôm mro.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0255", "title": "MAAK HOM AY MAY Ơ PHUNG OH NÂU", "song_number": "255", "lyrics": "MAAK HOM AY MAY Ơ PHUNG OH NÂU\n\n\nVerse 1\nMaak hom khân may, hơi phung oh nâu lơi geh nuih n'hâm uh ah. Ta ƀon Ƀêt-lê-hem hŏ deh jêh Brah Krist Nơm Tâm Rklaih he. Văch ăn kon me klaih bơh brah Sa-tan, lĕ rngôch nkhah du jêh.\n\nChorus\nMa… nau mhe mhan ueh dơi bonh leng bunuyh, gay maak lĕ rngôch. Ma… nau mhe mhan ueh dơi bonh leng bunuyh.\n\nVerse 2\nBrah Ndu Mbỡ he prơh hăn bơh kalơ du huê tông mpăr ueh Păng. Păng trŭnh hăn tât ma phung rmăk biăp gay mbơh nau mhe mhan ueh. Ăn gĭt bu deh du huê kon Brah Ndu, tâm ƀon Ƀet-lê-hem.\n\nChorus\nMa… nau mhe mhan ueh dơi bonh leng bunuyh, gay maak lĕ rngôch. Ma… nau mhe mhan ueh dơi bonh leng bunuyh.\n\nVerse 3\nTơ lah phung rmăk biăp tăng nau nây khân păng bêng ma nau maak. Jêh ri khân păng cha lơi lĕ phung biăp tâm yôk ntŭk gŭ bêch. Rmăk biăp nây hăn ta Ƀet-lê-hem, gay joi oh bê mhe deh.\n\nChorus\nMa… nau mhe mhan ueh dơi bonh leng bunuyh, gay maak lĕ rngôch. Ma… nau mhe mhan ueh dơi bonh leng bunuyh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0256", "title": "MAAK NÔ-EL", "song_number": "256", "lyrics": "MAAK NÔ-EL\n\n\nVerse 1\nMaak yơh Nô-el, Maak yơh Nô-el, jêng nar maak hâu ngăn. Tâm n'gar ndrôk mâu geh ueh ôh, Oh bê Yê-su gŭ bêch.\nMaak yơh Nô-el, Maak yơh Nô-el, nteh teng neng ntoh rvah. Mprơ du nau maak ăn he iăt, Yê-su gŭ ta aơ.\n\nVerse 2\nMaak yơh Nô-el, Maak yơh Nô-el, geh sial nđik ji kăt. Nôk teh teng neng phung chroh gŭ, mprơ mât ton Păng lam ntŭk.\nMaak yơh Nô-el, Maak yơh Nô-el, tâm nar maak rhơn răm. Brah Ndu rŏng ngăn ma neh ntu, tât ăn kon Păng nơm.\n\nVerse 3\nMaak yơh Nô-el, Maak yơh Nô-el, bu deh jêh ma Krist. Mhơh nau mhe aơ ma neh ntu, Păng jêng nau rêh jêng trong.\nMaak yơh Nô-el, Maak yơh Nô-el, ƀhĭt vri ang rhơn răm. Phung tông mpăr ueh jŭr văch jêh, Nơm Tâm Rklaih tât ngăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0257", "title": "VĂCH HOM Ơ PHUNG ƀON LAN", "song_number": "257", "lyrics": "VĂCH HOM Ơ PHUNG ƀON LAN\n\n\nVerse 1\nVăch hom ơ phung ƀon lan iăt du nau khlay ngăn. Kăl e Brah Ndu rŏng he njuăl Kon Păng du huê. Deh Tâm n'gar ndrôk ƀỡ ƀơch ta ƀon Ƀet-lê-hem. Uănh H'Ma-ri gŭ deh dôl klong măng ji kăt ngăn.\n\nVerse 2\nvăch hom ơ phung ƀon lan geh phung rmăk biăp văch. Yor ma khân păng dôl gŭ rngeh măng tâm bri rdah. Phung tông mpăr Ueh mbơh ntơih nơm tâm rklaih tât jêh. Phung rmăk biăp hăn uănh Yê-su tâm n'gar ndrôk nây.\n\nVerse 3\nVăch hom ơ phung ƀon lan geh pe nuyh phung njêh. Văch ro bơh n'gor păng djôt ndơ nhhơr ma Oh Bê. Yor lah khân păng gĭt mănh tâm mpơl nchrat tâm trôk. Kuăl khân păng hăn răn mbah ma Ha-đăch toyh nây.\n\nVerse 4\nVăch hom ơ phung ƀon lan iăt nau khlay hâu ngăn. Sa-ơm Yê-su khĭt gay tâm chuai nau tih he. Gay ăn nau rêh ma mbu nơm ŭch chroh ma Păng. Văch hom phung ƀon lan hăn ran mbah ma Amoh Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0258", "title": "Ơ YÊ-SU BUAY SIAL", "song_number": "258", "lyrics": "Ơ YÊ-SU BUAY SIAL\n\n\nVerse 1\nƠ Yê-su uănh ta sial dak mƀŭt, dak dôl rƀuh ŭch ƀư rai he. Ndâr tŭk krăk tâm trôk jêh ri mih hâu, hên klach rmok tâm dak jru aơ.\nMay mâu geh chrê ma he khĭt bơh? Mâm dĭng May hăk bêch hêng? Hên mâu blâu ƀư ôh lah may mâu kah rngăl, sâm kơl ăn hên gơnh aƀơ ro.\n\nChorus\nSial jêh ri dak rƀuh ma tông bâr Gâp, r-ngân yơh, đăp mpăn ngăn. gĭt lah geh nau rƀuh, gĭt lah geh nglaih ktang, gĭt lah geh brah mhĭk, gĭt lah geh bunuyh mhĭk,\ndak mâu dơi ƀư rai phung geh Yê-su gŭ. Yor lah Păng jêng Nơm rhăk dak nđâp neh ntu. \"Lĕ rngôch khân păng mra tông bâr Gâp ngơi. R-ngân yơh, đăp mpăn ngăn. Lĕ rngôch khân păng mra tông bâr Gâp ngơi. R-ngân lĕ yơh\"\n\nVerse 2\nƠ Yê-su mâu hôm geh mhĭk blem, ntơm bơh May lah: \"R-ngân yơh\" Nau May Ngơi ăn nuih n'hâm gâp ueh jêh, mâu hôm klach krit ôh aƀaơ ri.\nGŭ ƀa-ƀơ ndrel gâp ơ Yê-su. Lơi cha lơi gâp gŭ êng. Ma yor lah gâp mâu dơi gŭ rêh êng ôh, nôk dôl May gŭ ngai đah gâp.\n\nChorus\nSial jêh ri dak rƀuh ma tông bâr Gâp, r-ngân yơh, đăp mpăn ngăn. gĭt lah geh nau rƀuh, gĭt lah geh nglaih ktang, gĭt lah geh brah mhĭk, gĭt lah geh bunuyh mhĭk,\ndak mâu dơi ƀư rai phung geh Yê-su gŭ. Yor lah Păng jêng Nơm rhăk dak nđâp neh ntu. \"Lĕ rngôch khân păng mra tông bâr Gâp ngơi. R-ngân yơh, đăp mpăn ngăn. Lĕ rngôch khân păng mra tông bâr Gâp ngơi. R-ngân lĕ yơh\"\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0259", "title": "BRAH NDU JÊNG MPÊR VĂR JŬM HE", "song_number": "259", "lyrics": "BRAH NDU JÊNG MPÊR VĂR JŬM HE\n\nTC 41\n\nVerse 1\nBrah Ndu he jêng mpêr văr jŭm he, Mpêr nâp ngăn mâu dơi rlâm ôh. brah mhĭk ntuh he ta nklang dak lip, ma nau ji gay ŭch khĭt he.\nnơm rlăng kăl e ăt hôm, bu kan ŭch đêh nji he, păng blau plach jêh ri ktang, păng ŭch tâm rmot ƀư rai, mâu geh ôh nuyh nâm bu păng.\n\nVerse 2\nLah nsing rnơm ma n'hâm ktang he nơm, nanễ he mâu dơi ôh jêng roh. he geh đŏng bunuyh sŏng gŭ êp he, bu nuyh Brah Ndu hŏ săch jêh.\nbu ôp mbu jêng nơm nây, Păng yơh jêng Yê-su Krist, Amoh Păng Kôranh Brah Kôranh tahan, ƀa-ƀơ n'ho ro tâm ban, Păng dơm dơi ma nau tâm lơh.\n\nVerse 3\nNeh ntu aơ bêng nau phung Brah mhĭk, khân păng ngroh ƀư roh lơi he. he mâu klach yor nau Brah Ndu ton, ăn nau na-nễ dơi tâm he.\nkon hađăch nau ngo vay nuih, he mâu n'ngơ ôh đah păng, păng ji nuih ma he kđôi, păng lĕ geh nau phat dôih, nau Krist dơi ƀư cha lôt păng.\n\nVerse 4\nNau Krist Ngơi Brah lơn ma lĕ rngôch, mprơh lĕ nau brah ta neh ntu. Brah Huêng Ueh nau brah păng ma he, Păng nơm gŭ ndrel kâp kơl he.\nndơ ueh mĭt jiăng rlau lôch, nau rêh aơ rlau lôch đŏng, bu dơi nkhĭt săk jăn aơ, Nau Ngơi Brah Ndu ăt hôm, Ƀon bri hađăch Păng gŭ n'ho ro.\nA-men.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0260", "title": "BRAH NDU RŎNG BUNUYH HÂU NGĂN", "song_number": "260", "lyrics": "BRAH NDU RŎNG BUNUYH HÂU NGĂN\n\n\nVerse 1\nBrah Ndu rŏng bunuyh âk ngăn, tât Păng jao Kon Păng Nơm. Abăl jŭr jêh ta neh ntu, lơi lĕ nau chrêk r-mah nđâp Ƀon Ueh Păng nơm trôk srôih sram văch ŭch jêng bunuyh, Ăn bu deh tâm n'gar vang ndrôk.\n\nVerse 2\nBrah Ndu rŏng bunuyh ăk ngăn, tât Păng jao Kon Păng Nơm. Ăn khĭt ta si tâm rkăng, tâm rklaih he bơh nau tih, ŭch he gŭ rêh n'ho ro tâm Ƀon Ueh Păng ta klơ, khlay lơn nau rŏng mâu jêh dŭt.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0261", "title": "NAU BRAH NDU RŎNG", "song_number": "261", "lyrics": "NAU BRAH NDU RŎNG\n\n\nVerse 1\nNau Brah Ndu rŏng jêng toyh hâu ngăn, mpiăt mâu dơi rblang mâu dơi chih lĕ nau nây prêh lơn ma lĕ mănh mbing jru lơn dak mƀŭt mâu dơi ntĭt ôh.\nphung he jêng bunuyh tih mhĭk hâu ngăn, Brah Ndu Nơm ăn Kon Păng, khĭt tâm rgâl he, jêh ri tâm rklaih, bơh ăp ntil nau tih mhĭk.\n\nChorus\nBrah Ndu ndrŏng ma nau rŏng, nau yỗ, mâu hôm dơi kơt ban ôh.\nnau rŏng Păng gŭ ƀa-ƀơ n'ho ro. phung kloh ndrel tông mpăr mê.\n\nVerse 2\nTơ lah dak ôch nâm bu dak mƀŭt, jêh ri lĕ rngôch ja jêng mâng chih tơ lah klơ trôk dơi jêng n'ha rđaih, jêh ri bu-nuyh ăt mâu dơi chih.\nkhân păng chih nau rŏng bơh Brah Ndu, dak krăk nây mra suăt ro, lĕ rngôch n'ha rđaih mâu hôm dơi tŏng, lah he mdơh nau Păng rŏng.\n\nChorus\nBrah Ndu ndrŏng ma nau rŏng, nau yỗ, mâu hôm dơi kơt ban ôh.\nnau rŏng Păng gŭ ƀa-ƀơ n'ho ro. phung kloh ndrel tông mpăr mê.\n\nVerse 3\nNar mra rlau lôch neh ntu tâm ban sưng ƀon bri hađăch neh ntu mra rai phung tih gŭ klach saơ Yê-su văch, ŭch dăn yôk yang brôi lơi ăn ndâp.\nnau rŏng Brah Ndu mra gŭ n'ho ro Păng văch tâm rklaih phung chroh, njŭn leo khân păng, tât tâm Ƀon Ueh, phung kloh ndrel phung tông mpăr.\n\nChorus\nBrah Ndu ndrŏng ma nau rŏng, nau yỗ, mâu hôm dơi kơt ban ôh.\nnau rŏng Păng gŭ ƀa-ƀơ n'ho ro. phung kloh ndrel tông mpăr mê.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0262", "title": "KÔRANH BRAH PRƠH GÂP", "song_number": "262", "lyrics": "KÔRANH BRAH PRƠH GÂP\n\n\nVerse 1\nGâp saơ rmưn rsen bunuyh ta ntŭk yôk ngai. Gŭ tâm nau rêh ni kuăl gâp hăn kơl. Jâk jêh ma nau rngot tât mâu dơi anh ôh.\n\nChorus\nMa nau maak gâp lah Kôranh Brah prơh gâp.\nĐă hăn hom gâp, ơ Kôranh Brah prơh gâp. Ma nau maak gâp vơl Păng prơh hom gâp tât ntŭk rmưn rsen bunuyh khĭt nau rêh ni.\nMa nau maak gâp lah. Kôranh Brah prơh gâp.\n\nVerse 2\nMbỡ mễ hŏ khĭt jêh tâm nau ngo klĕng. Joi rvơ tâm nau ngo. gay joi nau ang, Mâu geh măt uănh ma nau yỗ jêh ri chrê.\n\nChorus\nMa nau maak gâp lah Kôranh Brah prơh gâp.\nĐă hăn hom gâp, ơ Kôranh Brah prơh gâp. Ma nau maak gâp vơl Păng prơh hom gâp tât ntŭk rmưn rsen bunuyh khĭt nau rêh ni.\nMa nau maak gâp lah. Kôranh Brah prơh gâp.\n\nVerse 3\nOh nâu oh nur noi deh tâm mpôl he. Mâu tâm kơl gŭ khĭt pưt nau kâp gân. Gay ŭch hăn mbơh n'ho njŭn leo khân păng sĭt.\n\nChorus\nMa nau maak gâp lah Kôranh Brah prơh gâp.\nĐă hăn hom gâp, ơ Kôranh Brah prơh gâp. Ma nau maak gâp vơl Păng prơh hom gâp tât ntŭk rmưn rsen bunuyh khĭt nau rêh ni.\nMa nau maak gâp lah. Kôranh Brah prơh gâp.\n\nVerse 4\nKrist jêng Kôranh Rmăk Biăp nơm njŭn leo trong. Hăn joi nơm roh jêh hiơt trong hiơt bri. Păng saơ khân păng nhĭm, gŭ iăt nau mbơh sơm.\n\nChorus\nMa nau maak gâp lah Kôranh Brah prơh gâp.\nĐă hăn hom gâp, ơ Kôranh Brah prơh gâp. Ma nau maak gâp vơl Păng prơh hom gâp tât ntŭk rmưn rsen bunuyh khĭt nau rêh ni.\nMa nau maak gâp lah. Kôranh Brah prơh gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0263", "title": "MAAK NÔ-EL, MAAK NÔ-EL", "song_number": "263", "lyrics": "MAAK NÔ-EL, MAAK NÔ-EL\n\n\nChorus\nMaak Nô-el, Maak Nô-el ma lĕ rngôch ay may! ăn ay may răm rhơn tâm ban lĕ yor nkah nau Păng rŏng he.\nPăng mât mơh he jêh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0264", "title": "Ơ KÔRANH BRAH KAH GĬT HOM MA HÊN", "song_number": "264", "lyrics": "Ơ KÔRANH BRAH KAH GĬT HOM MA HÊN\n\n\nVerse 1\nHên phung rmăk biăp gŭ chiă biăp măng aơ nuih n'hâm hên nkah ma May. Ơ Brah Ndu jŭr khâl hom ma hên ƀă hên ŭch saơ muh măt May.\n\nVerse 2\nHên jêng tâm ban biăp mâu geh rmăk ôh hên dơn May jêng rmăk hên. Hên ŭch May tâm rklaih hên bơh nau tih hên gŭ kâp May a-ƀaơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0265", "title": "MPRƠ HOM NÔ-EL", "song_number": "265", "lyrics": "MPRƠ HOM NÔ-EL\n\n\nVerse 1\nDôl klong măng ƀât lât geh nau ang chrang. Phung tông mpăr ueh kâp mprơ.\nUeh maak đăp mpăn ngăn ma lam neh ntu. Ma bu nơm dơn rom Păng.\n\nChorus\nMprơ maak răm hom, mprơ hom Nô-el. Mprơ maak răm hom, mprơ hom Nô-el. Kon Brah Ndu jŭr jêh tă bơh trôk.\n\nVerse 2\nVăch hom êp hađăch ma phung tông mpăr ueh. Văch êp gay yơk mbah Păng.\nMât ton tâm rnê hom ma lĕ nuih n'hâm. Jêh ri kreh gong jêng may.\n\nChorus\nMprơ maak răm hom, mprơ hom Nô-el. Mprơ maak răm hom, mprơ hom Nô-el. Kon Brah Ndu jŭr jêh tă bơh trôk.\n\nVerse 3\nKon Brah Ndu hăk bêch tâm hip gỡ ndrôk. Lâng rlu tâm ngih o-ach.\nMe Păng gŭ mât ma nau rŏng rdỡ rbăn. Yor lah Păng jêng hađăch toyh.\n\nChorus\nMprơ maak răm hom, mprơ hom Nô-el. Mprơ maak răm hom, mprơ hom Nô-el. Kon Brah Ndu jŭr jêh tă bơh trôk.\n\nVerse 4\nBi may lĕ prăp đŏng ntŭk ma Păng gŭ. Păng jêng du huê hađăch ngăn.\nĂn Păng njêng nuih n'hâm jêng sưng bêch Păng. Nuih n'hâm he geh hađăch nây.\n\nChorus\nMprơ maak răm hom, mprơ hom Nô-el. Mprơ maak răm hom, mprơ hom Nô-el. Kon Brah Ndu jŭr jêh tă bơh trôk.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0266", "title": "OH BÊ JỄ LÂNG BÊCH", "song_number": "266", "lyrics": "OH BÊ JỄ LÂNG BÊCH\n\n\nVerse 1\nOh Bê hăk bêch tâm hip gỡ kro, gay rŏng may! Nơm hŏ lơi nau chrêk rmah ta klơ, gâp rŏng May!\nPhung Hađăch tĭng mănh tât ma may lah: Gâp rŏng May! \"Phung rmăk biăp tăng tông mpăr Ueh mprơ gâp rŏng may.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0267", "title": "DU NAR", "song_number": "267", "lyrics": "DU NAR\n\nTC 85\n\nVerse 1\nDu nar tông mpăr Brah Ndu tâm rnê Brah Yê-su. Nar nây ta neh ntu geh âk bunuyh tih mhĭk Yê-su jŭr deh tă bơh bu ur druh deh Păng, gŭ ndrel ma bunuyh, jêng tâm ntĭt nau rêh gâp.\n\nChorus\nBrah Yê-su rŏng gâp. Păng khĭt gay rklaih gâp. Brah Yê-su sŏk lĕ nau tih gâp mƀăr ngai. Păng ăn gâp jêng kon me.\nDơi gŭ rêh sŏng srăng. du nar Păng văch đŏng, bêng ma nau chrêk rmah.\n\nVerse 2\nGeh du nar bu njŭn Păng ta klơ yôk kal-ver. Nar nây bu Pâng Păng ta klơ si tâm rkăng. Ta nây Păng nđêh nji bunuyh joi nau tâm rmot Păng, khĭt yor nau tih he Păng jêng nơm tâm chuai.\n\nChorus\nBrah Yê-su rŏng gâp. Păng khĭt gay rklaih gâp. Brah Yê-su sŏk lĕ nau tih gâp mƀăr ngai. Păng ăn gâp jêng kon me.\nDơi gŭ rêh sŏng srăng. du nar Păng văch đŏng, bêng ma nau chrêk rmah.\n\nVerse 3\nGeh du nar bu djôt săk Păng tâp tâm trôm môch. Nar nây Păng gŭ rlu jêh ri bêch đăp mpăn. Tông mpar ueh jŭr hăn gŭ kâp uănh ta môch Păng, nđâp mĭt jiăng rŏng ăt lơi Păng tâm ntŭk nây.\n\nChorus\nBrah Yê-su rŏng gâp. Păng khĭt gay rklaih gâp. Brah Yê-su sŏk lĕ nau tih gâp mƀăr ngai. Păng ăn gâp jêng kon me.\nDơi gŭ rêh sŏng srăng. du nar Păng văch đŏng, bêng ma nau chrêk rmah.\n\nVerse 4\nGeh du nar môch rdâl kŏ mâu dơi nkân păng ôh. Geh du mlâm lŭ ntĭl mpông môch hŏ pơk jêh. Yê-su dâk rêh Păng dơi jêh ngăn đah nau khĭt, Păng hao jêh klơ trôk jêng Kôranh Brah n'ho ro.\n\nChorus\nBrah Yê-su rŏng gâp. Păng khĭt gay rklaih gâp. Brah Yê-su sŏk lĕ nau tih gâp mƀăr ngai. Păng ăn gâp jêng kon me.\nDơi gŭ rêh sŏng srăng. du nar Păng văch đŏng, bêng ma nau chrêk rmah.\n\nVerse 5\nGeh du nar bu uh nŭng kuăl Kôranh Brah lŏ văch. Nar nây trôk mra nchrang yor nau chrêk rmah Păng. Tâm nar nây he mra saơ Phung hŏ khĭt lor jêh, Ơ tâm rnê ma Yê-su Nơm Tâm R'klaih gâp.\n\nChorus\nBrah Yê-su rŏng gâp. Păng khĭt gay rklaih gâp. Brah Yê-su sŏk lĕ nau tih gâp mƀăr ngai. Păng ăn gâp jêng kon me.\nDơi gŭ rêh sŏng srăng. du nar Păng văch đŏng, bêng ma nau chrêk rmah.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0268", "title": "HA-LÊ-LU-YA! YÊ-SU VĂCH", "song_number": "268", "lyrics": "HA-LÊ-LU-YA! YÊ-SU VĂCH\n\n\nVerse 1\nKăl e dôl măng phung tông mpăr ueh mprơ. Đăp mpăn ma phung bunuyh Tâm rnê Ha-đăch chrêk ma lơp. Yê-su Kôranh Brah,\nkăl e dôl măng phung tông mpăr ueh mprơ. Nau ueh maak Brah Ndu ăn neh ntu. Ƀon Ƀêt-lê-hem măng nây Yê-su Krist jŭr văch lam jŭm ntŭk nar aơ, mât ton tâm rnê Păng.\n\nChorus\nSân săk jăn yor phung he, nau rŏng Păng mâu rgâl. Văch hom he leo nhhơr ndơ ma Ha-đăch đăp mpăn.\nHa-lê-lu-ya! Ha-lê-lu-ya! Ha-lê-lu-ya! A-men! Ha-lê-lu-ya! Ha-lê-lu-ya! Ha-lê-lu-ya! A-men. A… Men.\n\nVerse 2\nMăng aơ he maak mât ton Nơm Tâm rklaih. jŭr văch tâm rklaih bunuyh Tâm rnê hom ma nơm tâm rklaih. Yê-su Kôranh Brah,\nmăng aơ ăp ntŭk bêng nau yơk tâm rnê. Rmưn rsen nau mprơ mhe mât ton Hađăch. Păng rŏng neh ntu lơi sưng hađăch chrêk ma lơp jŭr ta neh ntu djơh mhĭk, dơn nau rêh nđêh nji.\n\nChorus\nSân săk jăn yor phung he, nau rŏng Păng mâu rgâl. Văch hom he leo nhhơr ndơ ma Ha-đăch đăp mpăn.\nHa-lê-lu-ya! Ha-lê-lu-ya! Ha-lê-lu-ya! A-men! Ha-lê-lu-ya! Ha-lê-lu-ya! Ha-lê-lu-ya! A-men. A… Men.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0269", "title": "MĂNG RĂM MAAK MA NEH NTU", "song_number": "269", "lyrics": "MĂNG RĂM MAAK MA NEH NTU\n\n\nVerse 1\nKăl e ta klong măng đăp mpăn, mănh rêp ƀlêp tâm trôk, lĕ rngôch ndơ klăk klêm. Geh phung tông mpăr ueh mpăr ndăng, mbơh du nau mhe mhan ma lĕ rngôch neh ntu.\nMât ton Kôranh Brah ta klơ lơn, Nơm rŏng ma lĕ rngôch đăp mpăn ma neh ntu. Tâm ƀon Ƀêt-lê-hem măng aơ tâm n'gar ndrôk jễ lễ Păng văch ma neh ntu.\n\nChorus\nYor lah bơh Brah Ndu, Păng rŏng ma neh ntu hâu ngăn, Yor lĕ rngôch neh ntu ăt chuat tâm trong ngo ƀa-ƀơ.\nYor rŏng ma phung he Yê-su Krist Păng văch măng aơ. khĭt yor nau tih he ntrok ma lĕ rngôch nau rêh ni.\nMăng aơ mănh rêp ƀlêp tâm trôk, geh du phung rmăk biăp gŭ rngeh mât phung biăp. khân păng saơ nau ang toyh nchrat nđâp rmưn rsen tông mpăr mbơh nau mhe mhan aơ.\nMăng aơ tâm dâng si Nô-el, geh rmưn rsen nau mprơ nhhơr ma Brah Yê-su. Măng aơ măng Nô-el hâk răm he mprơ tâm rnê păng Nơm văch ma neh ntu.\n\nVerse 2\nKăl e tĭng mănh toyh ang chrang phung hađăch bơh ngai văch, gay joi hađăch mhe deh. Njưh ta Ƀêt-lê-hem ƀon jễ, ntŭk mănh toyh ang nchrang khân păng joi Yê-su.\nDeh ta ntŭk n'gar ndrôk jễ lễ, khân păng saơ Yê-su ăt hăk bêch đăp mpăn. Maih khlay nhhơr ma Brah Yê-su dak si tăng nhhơr ma Păng nđâp dak ƀâu kah.\n\nChorus\nYor lah bơh Brah Ndu, Păng rŏng ma neh ntu hâu ngăn, Yor lĕ rngôch neh ntu ăt chuat tâm trong ngo ƀa-ƀơ.\nYor rŏng ma phung he Yê-su Krist Păng văch măng aơ. khĭt yor nau tih he ntrok ma lĕ rngôch nau rêh ni.\nMăng aơ mănh rêp ƀlêp tâm trôk, geh du phung rmăk biăp gŭ rngeh mât phung biăp. khân păng saơ nau ang toyh nchrat nđâp rmưn rsen tông mpăr mbơh nau mhe mhan aơ.\nMăng aơ tâm dâng si Nô-el, geh rmưn rsen nau mprơ nhhơr ma Brah Yê-su. Măng aơ măng Nô-el hâk răm he mprơ tâm rnê păng Nơm văch ma neh ntu.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0270", "title": "MPRƠ HOM HE DU NAU MPRƠ MAAK", "song_number": "270", "lyrics": "MPRƠ HOM HE DU NAU MPRƠ MAAK\n\n\nVerse 1\nMprơ hom he du nau mprơ maak. Mât ton Brah Ndu! Phung tông mpăr mprơ jêh du tỡ, mât ton Brah Ndu!\nMât ton ma Brah Ndu Nơm klơ Păng gŭ lam trôk nđâp neh ntu. Phung kon bunuyh ŭch mprơ pô aơ. Mât ton ma Brah Ndu! Mât ton ma Brah Ndu.\n\nChorus\niăt lĕ rngôch tông mpăr Brah Ndu mprơ, Mât ton ma Hađăch toyh mhe deh.\nĂn nau đăp mpăn ngăn ta neh ntu, Bunuyh tih tâm rnglăp ma Brah Ndu.\nĂn lĕ rngôch mpôl băl tâm neh ntu, Mrơ ndrel n'grup ma phung tông mpăr nây.\nMbơh nau mhe mhan ueh pô aơ: Krist văch ta ƀon Ƀêt-lê-hem iăt lĕ rngôch tông mpăr Brah Ndu, mât ton ma Hađăch toyh mhe deh.\n\nVerse 2\niăt lĕ rngôch phung tông mpăr mprơ. Mât ton Brah Ndu! khân păng mprơ ndrel n'grŭp tâm trôk, mât ton Brah Ndu!\nMbơh nau mhe mhan ueh pô aơ Yê-su Hađăch mhe tât ta nây. Păng rao nau tih ma mham Păng Mât ton ma Brah Ndu! Mât ton ma Brah Ndu.\n\nChorus\niăt lĕ rngôch tông mpăr Brah Ndu mprơ, Mât ton ma Hađăch toyh mhe deh.\nĂn nau đăp mpăn ngăn ta neh ntu, Bunuyh tih tâm rnglăp ma Brah Ndu.\nĂn lĕ rngôch mpôl băl tâm neh ntu, Mrơ ndrel n'grup ma phung tông mpăr nây.\nMbơh nau mhe mhan ueh pô aơ: Krist văch ta ƀon Ƀêt-lê-hem iăt lĕ rngôch tông mpăr Brah Ndu, mât ton ma Hađăch toyh mhe deh.\n\nVerse 3\nLĕ rngôch bunuyh mprơ nau ueh aơ. Mât ton Brah Ndu! khân păng tĭng nau mprơ tâm trôk, mât ton Brah Ndu!\nkhân păng mprơ đah tông mpăr ueh Lor ma khân păng ntơm du sĭt. Mât ton ma Hađăch toyh mhe deh. Mât ton ma Brah Ndu! Mât ton ma Brah Ndu.\n\nChorus\niăt lĕ rngôch tông mpăr Brah Ndu mprơ, Mât ton ma Hađăch toyh mhe deh.\nĂn nau đăp mpăn ngăn ta neh ntu, Bunuyh tih tâm rnglăp ma Brah Ndu.\nĂn lĕ rngôch mpôl băl tâm neh ntu, Mrơ ndrel n'grup ma phung tông mpăr nây.\nMbơh nau mhe mhan ueh pô aơ: Krist văch ta ƀon Ƀêt-lê-hem iăt lĕ rngôch tông mpăr Brah Ndu, mât ton ma Hađăch toyh mhe deh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0271", "title": "NAU MPRƠ NÔ-EL", "song_number": "271", "lyrics": "NAU MPRƠ NÔ-EL\n\n\nVerse 1\nGeh du măng phung Tông mpăr Ueh jŭr bơh trôk ta klơ. Mbơh ma phung rmăk biăp gŭ chiă uănh biăp khân păng. Geh du huê Nơm Tâm Rklaih mhe deh ma may măng nễ ƀon Ƀet-lê-hem aơ, lâng bêch tâm hĭp gỡ ndrôk.\n\nVerse 2\nA-ƀaơ tâm Ƀon Brah Ndu Yê-su Amoh Nơm dêh rhêt. Jêng Nơm chiă uănh neh ntu Păng mbơh sơm ma he. Nar kăn dỡ Păng mra uănh njŭn leo lĕ rngôch phung păng hăn gŭ ndrel ma păng tâm Ƀon Ueh Brah Ndu mro.\n\nVerse 3\nƠ Nơm Tâm Rklaih măng aơ hên ŭch gŭ ta năp May. Ŭch yơk tâm rnê ma May ơ Hađăch khlay ngăn ngên. Hên ŭch mprơ ndrel ma phung tông mpăr ueh tâm trôk mprơ ma bâr ktang mât ton nau chrêk rmah ma Amoh May.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0272", "title": "GEH NAU MPRƠ TÂM SIAL NDĂNG", "song_number": "272", "lyrics": "GEH NAU MPRƠ TÂM SIAL NDĂNG\n\n\nVerse 1\nGeh nau mprơ tâm sial ndăng, geh du rplay mbing klơ trôk. du huê bu druh mbơh sơm, geh Oh bê jễ mhe deh.\nJêh ri mănh nchrang ta nây ro, tông mpăr Brah Ndu mprơ. Yor lah ntŭk hip gỡ kro ndrôk, yơk mbah Kon Brah Ndu.\n\nVerse 2\nGeh nau maak toyh tâm trôk, yor lah nau deh khlay ngăn. geh du huê Kon bu klâu, jêng Kôranh Brah ma neh ntu.\nDu rplay mbing dơi sol chrat ang, tông mpăr Brah Ndu mprơ. Yor lah ntŭk hip gỡ kra ndrôk, yơk mbah Kon Brah Ndu.\n\nVerse 3\nDôl lĕ rngôch băl mpôl bunuyh, dơi sol ang ma mănh nây. jêh ri nau mprơ bơh trôk, lư jŭm bri lam neh ntu.\nLĕ rngôch nuih n'hâm bunuyh jêng ang, dôl tông mpăr ueh mprơ. Tâm lĕ rngôch rnôk bu-nuyh lah: Yê-su jêng hađăch he.\n\nVerse 4\nHe maak gŭ tâm nau ang, he tăng đŏng nau mprơ nây. tât jêh ta nôk klong măng, bơh phung tông mpăr ta klơ.\nĂn he mbơh nau mhe mhan ueh, tĭng nâm khân păng mbơh. Jêh ri păn mbah tâm n'gar ndrôk, Nơm Tâm Rklaih neh ntu.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0273", "title": "DU NAU MPRƠ MA NÔ-EL", "song_number": "273", "lyrics": "DU NAU MPRƠ MA NÔ-EL\n\n\nVerse 1\nNơm tâm rklaih he Yê-su, văch tâm ƀon Ƀêt-lê-hem bu ndruh deh ma Păng tâm hĭp gỡ ndrung n'gar ndrôk.\nTông mpăr ueh bơh trôk mprơ hâk răm mbơh nau Păng tât jêh ri njŭn phung rmăk biăp, hăn mbơh Păng tâm n'ngar ndrôk.\n\nVerse 2\nƠ Nơm Tâm Rklaih hên nhhơr lĕ nuih n'hâm hên ma May, hên mbah ma May Nơm jêng Hađăch khlay lơn ma hên.\nTâm lam ntŭk jŭm văr trôk bâr phung tông mpăr Ueh mprơ ri nuih n'hâm he tâm rnglăp, ŭch mprơ ndrel ma khân păng.\n\nVerse 3\nYê-su aơ kăl e bơh lâng bêch tâm hĭp gỡ ndrôk aƀaơ aơ jêng Hađăch chrêk ma lơp mbơh sơm ma hên.\nDu nar Păng mra lŏ văch djôt leo phung chroh ma phung gŭ ndrel ma Păng n'ho ro, jêh ri mra ndơn ndơ Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0274", "title": "PĂNG CHA LƠI JÊH SƯNG HAĐĂCH", "song_number": "274", "lyrics": "PĂNG CHA LƠI JÊH SƯNG HAĐĂCH\n\n\nVerse 1\nPăng lơi jêh sưng Hađăch Păng tâm trôk, Păng drŏh nau Păng jêng Hađăch ma Mbỡ Păng.\nPăng mâu ŭch djôt prăp nau nây ôh, ma Yor Păng geh nau rŏng hâu ma he.\nĂn he kơt nĕ mĭn tâm ban Păng. Lơi trong he nơm ŭch văch gơnh hom păn mbah yơk ngăn ma Păng yor Păng jêng Hađăch ma he.\n\nVerse 2\nKăl e nŏh n'gar ndrôk rom jêh Păng, hĭp gỡ o ach jêng sưng bêch ma he.\nPhung rmăk biăp hăn mbah ma Păng jêh phung hađăch n'gor ngai nhhơr ndơ khlay ma Păng\nĂn he rom Păng tâm nuih n'hâm he. Lơi dun nau Păng rŏng ma phung he ôh gay ăn he nhhơr nuih n'hâm săk jăn tông bâr Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0275", "title": "KƠP LĔ NAU UEH BRAH NDU ĂN", "song_number": "275", "lyrics": "KƠP LĔ NAU UEH BRAH NDU ĂN\n\nTC 674\n\nVerse 1\nLah geh nau jêr nâm bu sial ktang gŭ jŭm may, mâu lah may roh lĕ rngôch nau khlay ndâp rnôk aơ. Dăn may kơp nkoch hom lĕ nau ueh Brah Ndu ăn, jêh ri Păng mra nkhŭt âk nau ueh uĭn ma may.\n\nChorus\nkơp nkoch bri nau ueh Brah Ndu ăn jêh kơp lĕ nau ueh păng ăn ma ăp nơm. Ơ may mra saơ lĕ kan ti Brah Ndu. Na-nễ may mra saơ lĕ kan khlay Păng ƀư jêh.\n\nVerse 2\nAy may geh rdja nuih n'hâm lĕ ma yor nau jêr? mâu lah si tâm rkăng may dôl tuy jâk lơn đŏng? Dăn may kơp nkoch hom lĕ nau ueh Brah Ndu ăn, nau đing roh, jêh ri may mra mprơ nau răm maak.\n\nChorus\nkơp nkoch bri nau ueh Brah Ndu ăn jêh kơp lĕ nau ueh păng ăn ma ăp nơm. Ơ may mra saơ lĕ kan ti Brah Ndu. Na-nễ may mra saơ lĕ kan khlay Păng ƀư jêh.\n\nVerse 3\nAy may kâp gân ndơ ndrŏng tâm neh ntu aơ lĕ? tâm trôk Mbỡ hŏ prăp ăn jêh ma he ndơ khlay. Dăn may kơp nkoch hom lĕ nau ueh Brah Ndu ăn, lĕ ndơ khlay Brah Ndu ton ăn mâu geh rvăt ôh.\n\nChorus\nkơp nkoch bri nau ueh Brah Ndu ăn jêh kơp lĕ nau ueh păng ăn ma ăp nơm. Ơ may mra saơ lĕ kan ti Brah Ndu. Na-nễ may mra saơ lĕ kan khlay Păng ƀư jêh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0276", "title": "YÊ-SU ĂN DAK MA PĂNG", "song_number": "276", "lyrics": "YÊ-SU ĂN DAK MA PĂNG\n\n\nVerse 1\nYê-su ăn dak ma Păng mâu di bơh dak ntu ôh. Păng ăn dak rêh ma păng Păng hăn mbơh ma bu ro\ntâm dôl hăn păng mprơ. Plỡ sĭt păng njŭn leo. Âk lơn bunuyh ma dak rêh, mâu di bơh dak ntu ôh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0277", "title": "MAY LƠI JÊH SƯNG HAĐĂCH", "song_number": "277", "lyrics": "MAY LƠI JÊH SƯNG HAĐĂCH\n\n\nVerse 1\nMay lơi jêh sưng hađăch nđâp đon chrêk rmah May, gay văch ta neh ntu yỗ gâp. Yor lah tâm ƀon Ƀêt-le-hem mâu saơ ôh, du ntŭk ueh deh mễ ma May.\n\nChorus\nƠ văch ma nuih n'hâm gâp Yê-su geh ntŭk tâm nuih n'hâm gâp ma May.\n\nVerse 2\nKlơ trôk rvang prăp ăn phung tông mpăr ueh mprơ, mât ton tâm rnê hađăch Yê-su. Yor lah ma nau dêh rhêt May jêng o ach, deh ma May tâm ntŭk n'gar ndrôk.\n\nChorus\nƠ văch ma nuih n'hâm gâp Yê-su geh ntŭk tâm nuih n'hâm gâp ma May.\n\nVerse 3\nPhung mpik geh ntŭk rlu, phung sĭm och geh rsuăn, tâm ntŭk nhhâm geh âk si krŏng. Yor May bêch ta neh ơ kon Brah Ndu Nơm, tâm bri rdah n'gor Ga-li-lê.\n\nChorus\nƠ văch ma nuih n'hâm gâp Yê-su geh ntŭk tâm nuih n'hâm gâp ma May.\n\nVerse 4\nƠ Kôranh Brah May văch ma nau May ngơi rêh, gay kon me lĕ băl mpôl bunuyh. Yor lah đah nau hŏ mưch jêh đon hađăch lok, khân păng njŭn may ntŭk kăl ver.\n\nChorus\nƠ văch ma nuih n'hâm gâp Yê-su geh ntŭk tâm nuih n'hâm gâp ma May.\n\nVerse 5\nTrôk mra rvang lah tât phung tông mpăr ueh mprơ, nay May plỡ văch ma nau dơi. Yor nây gâp kâp gân tăng bâr May kuăl lah: Geh ntŭk ma may tâm Ƀon ueh.\n\nChorus\nƠ văch ma nuih n'hâm gâp Yê-su geh ntŭk tâm nuih n'hâm gâp ma May.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0278", "title": "AMOH PĂNG", "song_number": "278", "lyrics": "AMOH PĂNG\n\n\nVerse 1\nA-moh Păng chrêk ma-lơp mra jêng Nơm khlay lơn. A-moh khlay Păng mra dơi jêng Kôranh tâm chră.\nBrah Ndu Nơm Brah Nơm gŭ rêh bơh ơm lor lơn. Kon Hađăch đăp mpăn ƀa-ƀơ n'ho.... ro.\nBrah Ndu Nơm Brah Nơm mâu mâp mra lôch dŭt ôh. Yê-su I-ma-nu-el Nơm Tâm Rklaih.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0279", "title": "YÊ-SU KRIST JÊNG TRONG", "song_number": "279", "lyrics": "YÊ-SU KRIST JÊNG TRONG\n\n\nVerse 1\nYê-su Krist jêng trong njŏ, Yê-su jêng nau ngơi ngăn.\nYê-su jêng nau rêh mro, Jêh ri Păng tâm r-klaih gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0280", "title": "YÊ-SU GŬ TA NĂP PI-LAT", "song_number": "280", "lyrics": "YÊ-SU GŬ TA NĂP PI-LAT\n\n\nVerse 1\nYê-su gŭ dâk tâm ngih toyh Pi-lat. Lĕ rngôch bunuyh ndơm jêh ma nây lơi Păng.\nNĕ aơ iăt hom nau bu ôp ma may moh may mra ƀư ma Yê-su:\nMoh may mra ƀư ma Yê-su? Mâu dơi dun Păng ƀa-ƀơ. kăn-dỡ nuih n'hâm may mra ôp may, moh Păng mra ƀư ma gâp.\n\nVerse 2\nMay ŭch dun Yê-su tâm ban Pê-trôih. Ŭch gŭ ndrel ma phung rlăng ngai bâr Păng.\nMâu janh tĭng ndỗ Yê-su tât may khĭt moh may mra ƀư ma Yê-su:\nMoh may mra ƀư ma Yê-su? Mâu dơi dun Păng ƀa-ƀơ. kăn-dỡ nuih n'hâm may mra ôp may, moh Păng mra ƀư ma gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0281", "title": "MÂM GÂP DJÔT TI DƠM MÂP KÔRANH BRAH?", "song_number": "281", "lyrics": "MÂM GÂP DJÔT TI DƠM MÂP KÔRANH BRAH?\n\nTC 839\n\nVerse 1\nNar kăn dỡ gâp sĭt ndrel Kôranh Brah mâm gâp djôt ti dơm mâp Păng?\nÂk ntil kan lah he lơi ƀa-ƀơ, mâm he mâu geh nhhơr ma Păng?\n\nChorus\nvăch ma nơm chuai gâp nham Păng hoch, mâm gâp djôt ti dơm mâp Păng?\nnar kăn dỡ gâp sĭt ndrel Kôranh Brah mâm mâu geh ndơ nhhơr ma Păng?\n\nVerse 2\nGâp mâu klach nau khĭt tât ma gâp lah Yê-su hŏ rklaih gâp jêh.\nLah gâp djôt ti dơm mâp Kôranh Brah? Blau nkoch đŏng đah Nơm rŏng he!\n\nChorus\nvăch ma nơm chuai gâp nham Păng hoch, mâm gâp djôt ti dơm mâp Păng?\nnar kăn dỡ gâp sĭt ndrel Kôranh Brah mâm mâu geh ndơ nhhơr ma Păng?\n\nVerse 3\nBunuyh ơi gơih gơnh ƀư ăp ntil kan nâm bu dôl rnôk hôm e nar.\nMăng tât gơnh he lôch mông nar kan, ăn he srôih mĭn rklaih huêng nuyh.\n\nChorus\nvăch ma nơm chuai gâp nham Păng hoch, mâm gâp djôt ti dơm mâp Păng?\nnar kăn dỡ gâp sĭt ndrel Kôranh Brah mâm mâu geh ndơ nhhơr ma Păng?\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0282", "title": "NDƠ KHLAY LƠN BRAH NDU ĂN", "song_number": "282", "lyrics": "NDƠ KHLAY LƠN BRAH NDU ĂN\n\n\nVerse 1\nGâp geh jêh Nơm rklaih khlay lơn hâu ngăn ngên, Păng jêng Kon Brah Ndu jŭr gŭ jêh ma bunuyh.\nJêng nau ang ma bunuyh chuat tâm nau ngo klêng, Păng jêng ndơ khlay lơn Brah Ndu ăn.\n\nVerse 2\nGeh du ntil êng jêng khlay lơn ma lĕ rngôch, nđâp ndơ nây ndrel jêh Brah Ndu jao ma bunuyh.\nNau Păng Ngơi chih jêh mbơh nau Brah Ndu rŏng, Păng tâm mpơl nau ngăn ma neh ntu.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0283", "title": "NGĂN YÊ-SU", "song_number": "283", "lyrics": "NGĂN YÊ-SU\n\n\nVerse 1\nNgăn Yê-su Kôranh Brah gâp, jêng du huê Nơm khlay ndâp. Ngăn Yê-su jêng Nơm khlay hâu ngăn ngên.\nMăt saơ jêh, tôr tăng jêh, tĭng nâm chih ndrom săm-ƀŭt Păng. Ngăn Yê-su jêng Nơm khlay hâu ngăn ngên.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0284", "title": "HA-LÊ-LU-YA TÂM RNÊ SI TÂM RKĂNG", "song_number": "284", "lyrics": "HA-LÊ-LU-YA TÂM RNÊ SI TÂM RKĂNG\n\nTC 194\n\nVerse 1\nRnê si tâm rkăng đăp mpăn. Ha-lê-lu-ya! Ha-lê-lu-ya! dơi rdâng đah lĕ phŭt sial. Ha-lê-lu-ya! Ha-lê-lu-ya!\nphŭt sial khôm bơh n'gar ŭnh, neh ntu tâm rmot ngăn ngên. Ƀĭa lah Păng mâu chôt ôh. Ha-lê-lu-ya, si tâm rkăng.\n\nChorus\nHa-lê-lu-ya, Ha-lê-lu-ya, ăp nar mprơ rnê si tâm rkăng, Ha-lê-lu-ya, Ha lê-lu-ya, geh nau dơi ƀa-ƀơ tâm he.\n\nVerse 2\nSi tâm rkăng ăt hôm mro, Ha-lê-lu-ya! Ha-lê-lu-ya! ntŭk aơ nchrat ang nau yỗ. Ha-lê-lu-ya! Ha-lê-lu-ya!\nPăng khĭt gay tâm rklaih he, ri ăn he mbơh Amoh Păng. Nau dơi bơh si tâm rkăng. Ha-lê-lu-ya, si tâm rkăng.\n\nChorus\nHa-lê-lu-ya, Ha-lê-lu-ya, ăp nar mprơ rnê si tâm rkăng, Ha-lê-lu-ya, Ha lê-lu-ya, geh nau dơi ƀa-ƀơ tâm he.\n\nVerse 3\nNtŭk aơ rnon he trok jêh, Ha-lê-lu-ya! Ha-lê-lu-ya! nau tih he Păng anh jêh. Ha-lê-lu-ya! Ha-lê-lu-ya!\nHe rnê jŭm si tâm rkăng, yor Biăp Kon hŏ nhhơr jêh. Păng jêng Ha-đăch nau rêh. Ha-lê-lu-ya, si tâm rkăng.\n\nChorus\nHa-lê-lu-ya, Ha-lê-lu-ya, ăp nar mprơ rnê si tâm rkăng, Ha-lê-lu-ya, Ha lê-lu-ya, geh nau dơi ƀa-ƀơ tâm he.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0285", "title": "NHHƠR LĔ MAY NƠM ĐŎNG", "song_number": "285", "lyrics": "NHHƠR LĔ MAY NƠM ĐŎNG\n\n\nVerse 1\nMay ŭch geh nau đăp mpăn, nđâp nau chroh văch ma toyh, nđâp nau gơih đah nau duh nđơr mbơh sơm. Huêng may mâu geh nau rlu, nau mât ton mâu geh roh knŏng nhhơr lĕ ta ka-lơ nơng ƀư brah.\n\nChorus\nMay hŏ mâp nhhơr may nơm đŏng ta klơ nơng ƀư brah? Nuih n'hâm may Brah Huêng Ueh mât mơh.\nKnŏng Păng dơm dơi mât ton nau đăp mpăn nđâp nau rlu, lah may jao săk jăn nđâp huêng ma Păng.\n\nVerse 2\nMay ŭch hăn ndrel Kôranh Brah tâm nau ang, nau Păng ngơi gay dơi geh nau maak đăp mpăn ăp nar. May mra tĭng nau Păng ŭch rklaih bơh nau mhĭk blem, ta ka-lơ nơng nhhơr hom săk jăn may nơm.\n\nChorus\nMay hŏ mâp nhhơr may nơm đŏng ta klơ nơng ƀư brah? Nuih n'hâm may Brah Huêng Ueh mât mơh.\nKnŏng Păng dơm dơi mât ton nau đăp mpăn nđâp nau rlu, lah may jao săk jăn nđâp huêng ma Păng.\n\nVerse 3\nNa-nễ he mâu dơi gĭt moh Kô-ranh Brah nkhŭt ăn, ma nau ueh he mâp dăn jêh bơh saơm. Kŏ lĕ săk jăn nđâp huêng srĭng Păng mât mơh uănh treng, jao May Nơm ta kalơ nơng prăp ƀư brah.\n\nChorus\nMay hŏ mâp nhhơr may nơm đŏng ta klơ nơng ƀư brah? Nuih n'hâm may Brah Huêng Ueh mât mơh.\nKnŏng Păng dơm dơi mât ton nau đăp mpăn nđâp nau rlu, lah may jao săk jăn nđâp huêng ma Păng.\n\nVerse 4\nMbu dơi rblang lĕ nau rŏng Păng mra njuăl văch bơh trôk, bơh nây lĕ nuih n'hâm he hâk răm ngăn. Ma nau tâm rnglăp ueh he mra sŏk dơn ta jâng Păng, knŏng lah he nhhơr lĕ rngôch ta klơ nơng.\n\nChorus\nMay hŏ mâp nhhơr may nơm đŏng ta klơ nơng ƀư brah? Nuih n'hâm may Brah Huêng Ueh mât mơh.\nKnŏng Păng dơm dơi mât ton nau đăp mpăn nđâp nau rlu, lah may jao săk jăn nđâp huêng ma Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0286", "title": "GEH KANŎNG DU MBLAH TRONG NGĂN", "song_number": "286", "lyrics": "GEH KANŎNG DU MBLAH TRONG NGĂN\n\n\nVerse 1\nGeh knŏng du mblah ntŭk trong n'hêl ngăn. Phung srôih hăn ntŭk khân may ngăn. Ta du mblah ntŭk tâm neh ntu mhe. Brah Ndu Nơm nkra jêh ma he.\nmbah ntŭk trong dăp jêh ri yôk gôl ta-ri ntŭk gŭ ta klơ nĕ dơh, ta rĭ ntŭk gŭ ta klơ trôk ri ơ oh nâu, văch ndrel ma hên. Ta aơ ntŭk gŭ ta klơ ta nây ơ oh nâu, văch ndrel ma hên.\n\nVerse 2\nTâm ntŭk neh ntu mhe nkra nây yơh. Phung srôih hăn moh khân may ŭch. Du rplay đon Hađăch mâu geh blau rai. Brah Krist dơn jêh ma phung he.\nTa ri gŭ ndrel ma Păng ƀa-ƀơ mâu hôm nhhiăng nhĭm jêh ri krit rngot, mâu hôm nhhiăng nhĭm jêh ri krit rngot ơ oh nâu, văch ndrel ma hên. Mâu hom nhhiăng nhĭm jêh ri krit rngot ơ oh nâu, văch ndrel ma hên.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0287", "title": "LAH GÂP UĂNH TA SI TÂM RKĂNG", "song_number": "287", "lyrics": "LAH GÂP UĂNH TA SI TÂM RKĂNG\n\n\nVerse 1\nLah gâp treng uănh rlet si tâm rkăng, ta ntŭk nây Hađăch chrêk ma lơp khĭt.\nLĕ rngôch ndơ neh ntu jêng dơm dam, jêh ri gâp tâm rmot ma nau sưr.\n\nChorus\nTa si tâm rkăng yơh păng hoch mham Păng ntŭk bu pâng păng ta si tâm rkăng. Păng khĭt dâh rêh jêh gŭ tâm nuih n'hâm gâp. Bêng jêh ma nau đăp mpăn nau rŏng.\n\nVerse 2\nGâp mâu hôm tâm rnê ma gâp nơm, klaih jêh yor bơh Brah Krist tâm rklaih.\nLĕ rngôch ndơ mâu khlay ƀư maak gâp, gâp jao lĕ jêh ma mham Yê-su.\n\nChorus\nTa si tâm rkăng yơh păng hoch mham Păng ntŭk bu pâng păng ta si tâm rkăng. Păng khĭt dâh rêh jêh gŭ tâm nuih n'hâm gâp. Bêng jêh ma nau đăp mpăn nau rŏng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0288", "title": "(SONG 288 — PAGE MISSING)", "song_number": "288", "lyrics": "(SONG 288 — PAGE MISSING)\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0289", "title": "NHHƠR HE NƠM MA KÔRANH BRAH", "song_number": "289", "lyrics": "NHHƠR HE NƠM MA KÔRANH BRAH\n\n\nVerse 1\nYor lah nau rŏng Brah Ndu nhhơr Kon Păng Nơm. Mâu geh nhhuach ôh njêng rup săk nâm bunuyh. Păng nti nau khlay jêh ri Păng dơn nau jêr kŏ tât khĭt jêng Nơm tâm Rklaih he.\n\nVerse 2\nPhung he hŏ chroh geh jêh nau Păng tâm rklaih. ma mham khlay Păng he geh nau kloh ueh. A-ƀaơ ri ăn he nhhơr lĕ nuih n'hâm săk jăn, huêng nau mĭn he ma Kôranh Brah.\n\nVerse 3\nGâp hŏ tăng jêh nau khlay Kôranh Brah Yê-su. Pô ri gâp chroh jêh ri tông bâr Păng. Yor lah ŭch jêng phung Păng răp-jăp n'ho-ro nar aơ gâp dơn jêh nau Ƀap-tem\n\nVerse 4\nGâp hŏ rom jêh Păng jêng Kôranh nau rêh gâp. Ma mham Păng yơh ƀư kloh nau tih gâp. Ƀap-tem ma dak tâm ntĭt ma gâp khĭt jêh, ma nau tih, dâk rêh tâm nau sŏng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0290", "title": "NAR KĂN-DỠ HE MRA SAƠ HAĐĂCH", "song_number": "290", "lyrics": "NAR KĂN-DỠ HE MRA SAƠ HAĐĂCH\n\n\nVerse 1\nNar kăn-dỡ he mra saơ ngăn Ha-đăch. Nar kăn-dỡ he mra saơ ngăn Ha-đăch.\nhe mra saơ ngăn Ha-đăch ăn Păng jêng Nơm Kôranh ma lĕ rngôch Kôranh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0291", "title": "JANH NÂM BU ĐA-NIEL", "song_number": "291", "lyrics": "JANH NÂM BU ĐA-NIEL\n\n\nVerse 1\nGŭ răp-jăp ma nau Brah Ndu! tông lĕ nau Păng nti, Geh nau yơk ma mbu nơm ŭch jêng nâm bu Y-Đa-niel!\n\nChorus\nJanh năm bu Y-Đa-niel, janh gŭ êng du huê, rnơm nau chroh ma Brah Yê-su janh hăn mbơh ma bu.\n\nVerse 2\nGeh âk ngăn bu-nuyh roh jêh, yor lah mâu gŭ janh, Mâu gĭt nsing ma Brah Ndu ôh nâm bu Y-Đa-niel gĭt!\n\nChorus\nJanh năm bu Y-Đa-niel, janh gŭ êng du huê, rnơm nau chroh ma Brah Yê-su janh hăn mbơh ma bu.\n\nVerse 3\nGeh nau jêr jêh ri nau ndơm; Păng mra tât tâm he Ƀiă lah he geh jêh nau dơi nâm bu Y-Đa-niel geh!\n\nChorus\nJanh năm bu Y-Đa-niel, janh gŭ êng du huê, rnơm nau chroh ma Brah Yê-su janh hăn mbơh ma bu.\n\nVerse 4\nMbơh ƀa-ƀơ nau mhe mhan ueh, Brah Ndu ăn nau dơi, Cha lơi lĕ Brah mhĭk ŭch ndơm nau nâm bu Y-Đa-niel lơi!\n\nChorus\nJanh năm bu Y-Đa-niel, janh gŭ êng du huê, rnơm nau chroh ma Brah Yê-su janh hăn mbơh ma bu.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0292", "title": "GÂP GĬT KÔRANH BRAH NKRA JÊH", "song_number": "292", "lyrics": "GÂP GĬT KÔRANH BRAH NKRA JÊH\n\n\nVerse 1\nGâp gĭt Kôranh Brah hŏ nkra jêh trong ma gâp. Gâp gĭt Kôranh Brah hŏ nkra jêh trong ma gâp,\nnau gâp ngơi, gâp ƀư gâp gơm. Ma yor Păng gâp njrăng ƀa-ƀơ gâp gĭt Kôranh Brah hŏ nkra jêh trong ma gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0293", "title": "NAU BRAH NDU RŎNG RLAU LƠN LĔ RNGÔCH", "song_number": "293", "lyrics": "NAU BRAH NDU RŎNG RLAU LƠN LĔ RNGÔCH\n\nTC 224\n\nVerse 1\nNau Brah Ndu rŏng rlau lơn lĕ rngôch nau maak jŭr văch tâm neh ntu, ma nau dêh rhêt May gŭ tâm hên, nau May yỗ hŏ bêng ler jêh.\nYê-su May jêng jêh nau dơi kơl, May jêng nau rŏng mâu rmal ôh. Ăn ma hên djôt nau May tâm rklaih, lăp gŭ tâm nuih n'hâm ƀa-ƀơ.\n\nVerse 2\nVăch hom Nơm Brah lơn tâm rklaih hên ăn phung hên dơn nau rêh May; ƀât lât ro ăn May sĭt ma hên, lơi cha lơi ngih brah May ôh.\nma May hên ŭch mât ton ƀa-ƀơ, pah kan nâm bu phung ta-han. Mbơh sơm tâm rnê May mâu rlu ôh, chrêk rmah tâm nau May rŏng jêh.\n\nVerse 3\nMƀăr ăn ngai lĕ rngôch nau tih njêng tâm hên gay dơi jêng kloh ueh; ăn hên saơ nau May tâm rklaih toyh, ăn hên jêng mhe ngăn tâm May\nhên geh nau rgâl tâm nau chrêk rmah, tât hên geh ntŭk gŭ klơ trôk. Tât hên dơn đon hađăch ta năp May, ma nau tâm rnê, rŏng khlay ngăn.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0294", "title": "NJUĂL NAU TÂM RLAY", "song_number": "294", "lyrics": "NJUĂL NAU TÂM RLAY\n\n\nVerse 1\nƠ Mbỡ tâm trôk, hên phung kon May, rƀŭn rom Kôranh Brah lŏ rêh jêh. Nhhơr nuih n'hâm hên vơl dăn ma May, ƀư rêh hên ma nau May Ngơi.\n\nChorus\nNjuăl nau tâm rlay, njuăl nau tâm rlay yor May gŭ ndrel ơ Kôranh Brah Njuăl nau tâm rlay, njuăl nau tâm rlay, ƀư rêh hên ma nau May Ngơi.\n\nVerse 2\nSial phŭt bơh trôk, leo nau ueh uĭn, njŭn ma hên yor nau May rŏng. Ăn hên gĭt Brah Huêng May gŭ ndrel, ƀư rêh hên ma nau May Ngơi.\n\nChorus\nNjuăl nau tâm rlay, njuăl nau tâm rlay yor May gŭ ndrel ơ Kôranh Brah Njuăl nau tâm rlay, njuăl nau tâm rlay, ƀư rêh hên ma nau May Ngơi.\n\nVerse 3\nMa nau rdja rgănh, hên gŭ tâm lơh, mâu tăp ma săk ma mham ôh. Kơl hên Kôranh Brah hên rdja râm sâr, ƀư rêh hên ma nau May Ngơi\n\nChorus\nNjuăl nau tâm rlay, njuăl nau tâm rlay yor May gŭ ndrel ơ Kôranh Brah Njuăl nau tâm rlay, njuăl nau tâm rlay, ƀư rêh hên ma nau May Ngơi.\n\nVerse 4\nɃư ktang hên năm bu rêt rse bŭt, jêng Nơm veng nđâp chiă uănh hên. Sâm mbêng hên ma Brah Huêng Ueh May, ƀư rêh hên ma nau May Ngơi.\n\nChorus\nNjuăl nau tâm rlay, njuăl nau tâm rlay yor May gŭ ndrel ơ Kôranh Brah Njuăl nau tâm rlay, njuăl nau tâm rlay, ƀư rêh hên ma nau May Ngơi.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0295", "title": "NAU MPRƠ ƠM 90", "song_number": "295", "lyrics": "NAU MPRƠ ƠM 90\n\n\nVerse 1\nƠ Kôranh Brah sâm nti phung hên, gĭt kơp lĕ nar phung hên... Yor nau rêh ndah âk jŏ năm! ăn ma phung hên gĭt njrăng ngăn.\nKan khlay ndâp... May ƀư May ăn! gỡ nse kao măng nar tâm ban đŏng. Du rbăn năm tâm ban du nar. Mâu êng ôh ta năp măt may.\n\nVerse 2\nƠ Kôranh Brah sâm mât mơh lĕ nau rêh phung hên ăp nar... Yor hăr ŭnh brah mhĭk lơh hên, ơ Kôranh Brah sâm kơl phung hên.\nMâu hôm đŏng... Geh nơm êng ôh! ăn ma phung hên dơi nsing rjăp ngăn. Dôl ma phung hên gŭ kâp gân. Nar mông May mra plỡ văch tay.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0296", "title": "GŬ DĂCH KÔRANH BRAH", "song_number": "296", "lyrics": "GŬ DĂCH KÔRANH BRAH\n\nTC 703\n\nVerse 1\nTâm Yê-su dơi geh nau đăp mpăn! yor lah nau rŏng Păng ăn. lĕ rngôch nau tih du ngai bơh gâp. Gâp dơi hăn dăch Kôranh Brah.\n\nChorus\nYê-su jêng Nơm tâm rklaih gâp. Brah Ndu Nơm njuăl jêh Păng. Kôranh Brah gâp ăt kâp gân may. Njŭn leo uănh gâp ƀa-ƀơ.\n\nVerse 2\nMâm dơi geh nau rdỡ rbăn ueh uĭn! knŏng ma nau yỗ Yê-su. dơi tâm mâp đah Kôranh Brah Yê-su. Hăn dăch kêng Păng ăp nar.\n\nChorus\nYê-su jêng Nơm tâm rklaih gâp. Brah Ndu Nơm njuăl jêh Păng. Kôranh Brah gâp ăt kâp gân may. Njŭn leo uănh gâp ƀa-ƀơ.\n\nVerse 3\nLĕ rngôch nau tih gâp Păng rao jêh! yor lah nau rŏng Păng ăn. dơi geh nau maak jêh ri đăp mpăn. Gŭ tâm Kôranh Brah ƀa-ƀơ.\n\nChorus\nYê-su jêng Nơm tâm rklaih gâp. Brah Ndu Nơm njuăl jêh Păng. Kôranh Brah gâp ăt kâp gân may. Njŭn leo uănh gâp ƀa-ƀơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0297", "title": "TÂM NĂM UEH AƠ", "song_number": "297", "lyrics": "TÂM NĂM UEH AƠ\n\n\nVerse 1\nTâm năm ueh aơ, gay geh nơm Tâm Rklaih, tâm năm ueh aơ. gay geh ntŭk nsing nâp, ăn gĭt n'hêl ngăn, ăn gĭt n'hêl ngăn. May geh nau nsing ta klơ he nâp ngăn ngên.\n\nChorus\nKnŏng êng Yê-su dơm jêng lŭ nâp ngăn. Knŏng êng Yê-su dơm jêng lŭ nâp ngăn.\n\nVerse 2\nTâm năm ueh aơ, ŭnh nau Brah Ndu Ngơi, tâm năm ueh aơ. lơi ăn he gŭ dơm. ăn gĭt n'hêl ngăn, ăn gĭt n'hêl ngăn. May geh nau nsing ta klơ he nâp ngăn ngên.\n\nChorus\nKnŏng êng Yê-su dơm jêng lŭ nâp ngăn. Knŏng êng Yê-su dơm jêng lŭ nâp ngăn.\n\nVerse 3\nTâm năm ueh aơ, gay geh Nơm Tâm Rklaih tâm năm ueh aơ. gay geh ntŭk nsing nâp, ăn gĭt n'hêl ngăn, ăn gĭt n'hêl ngăn. Gâp geh nau nsing ta klơ lŭ nâp ngăn ngên.\n\nChorus\nKnŏng êng Yê-su dơm jêng lŭ nâp ngăn. Knŏng êng Yê-su dơm jêng lŭ nâp ngăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0298", "title": "NAU ANG ƀON UEH", "song_number": "298", "lyrics": "NAU ANG ƀON UEH\n\nTC 294\n\nVerse 1\nTrong gâp tât Ƀon Ueh, geh măt nar sol ang rgăn yôk bri ntŭk ngai vêch bơh brong jru. Nau Brah Yê su ton gâp hăn ndrel ma May. Ơ nau ton ueh reh, khlay lơn hâu ngăn.\n\nChorus\nTâm Ƀon Ueh Brah Ndu, nau ang nchrat nar măng nau ang khlay ngăn nây, mra nkŭm gâp ƀa-ƀơ Ha-lê-lu-ya, gâp geh nau răm maak. ƀa-ƀơ gâp geh Păng, tâm rnê Yê-su!\n\nVerse 2\nNđâp âk djơh mhĭk tĭng ntŭk ngo nkŭm ƀa-ƀơ mâu dơi rƀŭn Yê-su Nơm njŭn rŏng gâp. Păng jêng nau ang nchrat bêng ma chrêk ma lơp. Gâp hôm êp ma Păng, mâu mâp nkhah ôh.\n\nChorus\nTâm Ƀon Ueh Brah Ndu, nau ang nchrat nar măng nau ang khlay ngăn nây, mra nkŭm gâp ƀa-ƀơ Ha-lê-lu-ya, gâp geh nau răm maak. ƀa-ƀơ gâp geh Păng, tâm rnê Yê-su!\n\nVerse 3\nSak ta trong sâng ang bêng ma nau maak răm ŭch gơnh lăp Ƀon Ueh ntŭk âk chrêk rmah. Ơ nuih n'hâm gâp răm yor dăch tât Ƀon Ueh. Uănh nau rŏng bơh trôk, ơ maak hâu ngăn.\n\nChorus\nTâm Ƀon Ueh Brah Ndu, nau ang nchrat nar măng nau ang khlay ngăn nây, mra nkŭm gâp ƀa-ƀơ Ha-lê-lu-ya, gâp geh nau răm maak. ƀa-ƀơ gâp geh Păng, tâm rnê Yê-su!\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0299", "title": "UĂNH MA KON BIĂP BRAH NDU", "song_number": "299", "lyrics": "UĂNH MA KON BIĂP BRAH NDU\n\n\nVerse 1\nTơ lah may ŭh klaih ngăn bơh nau tih mhĭk. Uănh ma Kon Biăp Brah Ndu! Păng khĭt tâm chuai may ta klơ yôk kal-ver. Uănh ma Kon Biăp Brah Ndu.\n\nChorus\nUănh ma Kon Biăp Brah Ndu, uănh ma Kon Biăp Brah Ndu. Knŏng Păng yơh dơi tâm rklaih may bơh nau tih, uănh ma Kon Biăp Brah Ndu.\n\nVerse 2\nTơ lah Sa-tan ŭch ndơm gay ăn may tŭp. Uănh ma Kon Biăp Brah Ndu! Păng ăn nau Brah dơi Mprơh brah mhĭk nơm rlăng. Uănh ma Kon Biăp Brah Ndu.\n\nChorus\nUănh ma Kon Biăp Brah Ndu, uănh ma Kon Biăp Brah Ndu. Knŏng Păng yơh dơi tâm rklaih may bơh nau tih, uănh ma Kon Biăp Brah Ndu.\n\nVerse 3\nMâm ƀư nau may rja, trong Kôranh Brah jêr lĕ? Uănh ma Kon Biăp Brah Ndu! Nau păng rŏng hŏ bêng ler jêh ăn may mprơ. Uănh ma Kon Biăp Brah Ndu.\n\nChorus\nUănh ma Kon Biăp Brah Ndu, uănh ma Kon Biăp Brah Ndu. Knŏng Păng yơh dơi tâm rklaih may bơh nau tih, uănh ma Kon Biăp Brah Ndu.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0300", "title": "GÂP GŬ RVÊ NAU BRAH NDU NGƠI", "song_number": "300", "lyrics": "GÂP GŬ RVÊ NAU BRAH NDU NGƠI\n\n\nVerse 1\nGâp gŭ rvê nau Brah Ndu Ngơi, tâm nau nây gâp tăng bâr Păng. Lah gâp hŏ nti jêh ri tông. Gâp dơi gŭ ma-ak ăp nar.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0301", "title": "RMĂK BIĂP UEH", "song_number": "301", "lyrics": "RMĂK BIĂP UEH\n\n\nVerse 1\nRmăk phung biăp jur jêh ta neh ntu, đah năr ngăch bơh nau Păng hŏ lơi đon Ha-đăch Păng Ta klơ. Gay tâm mpơl nau Păng rŏng.\n\nChorus\nTăng bâr Păng kuăl ma bâr huy ngăn. Bâr Păng ngloh tă bơh âk yôk lŭ rdâk râng gâng. Tăng bâr Păng kuăl, Păng kuăl ma bâr rdỡ rbân! Păng jêng rmăk phung biăp, jêng rmăk phung biăp.\n\nVerse 2\nDôl măng phŭt sial, Păng joi biăp Păng, Păng rgăn ntŭk dak toyh ngăn, Păng hao jêh yôk lŭ rdâk râng gâng. Gay joi săm rklaih nuyh roh.\n\nChorus\nTăng bâr Păng kuăl ma bâr huy ngăn. Bâr Păng ngloh tă bơh âk yôk lŭ rdâk râng gâng. Tăng bâr Păng kuăl, Păng kuăl ma bâr rdỡ rbân! Păng jêng rmăk phung biăp, jêng rmăk phung biăp.\n\nVerse 3\nNtŭk lơp blip ta nay geh nglaih chong, Bu tăng n'gôr nteh tâm trôk, Ƀiă lah bâr Yê-su lah ma gâp. Păng leo gâp sĭt ta vâl.\n\nChorus\nTăng bâr Păng kuăl ma bâr huy ngăn. Bâr Păng ngloh tă bơh âk yôk lŭ rdâk râng gâng. Tăng bâr Păng kuăl, Păng kuăl ma bâr rdỡ rbân! Păng jêng rmăk phung biăp, jêng rmăk phung biăp.\n\nVerse 4\nPô ri ăn hom ma sial khôm ktang, bâr ntênh nau mhe mhan ueh, phung tông mpăr Ueh răm jŭm sưng Hađăch. Yor, ma nuyh tih klaih jêh.\n\nChorus\nTăng bâr Păng kuăl ma bâr huy ngăn. Bâr Păng ngloh tă bơh âk yôk lŭ rdâk râng gâng. Tăng bâr Păng kuăl, Păng kuăl ma bâr rdỡ rbân! Păng jêng rmăk phung biăp, jêng rmăk phung biăp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0302", "title": "KÔRANH BRAH Ơ KÔRANH BRAH", "song_number": "302", "lyrics": "KÔRANH BRAH Ơ KÔRANH BRAH\n\n\nVerse 1\nGâp geh ngih tâm Ƀon Brah Ndu, nchrat ang lơn nâm bu nar. Gâp geh ngih tâm Ƀon Brah Ndu nchrat ang lơn nâm bu nar Gâp geh ngih tâm Ƀon Brah Ndu nchrat ang lơn nâm bu nar. Ntŭk ngai lơn tâm trôk. (lơn tâm trôk)\n\nChorus\nKôranh Brah, ơ Kôranh Brah ăn May kah gĭt ma gâp Kôranh Brah, ơ Kôranh Brah ăn May kah gĭt ma gâp. Kôranh Brah, ơ Kôranh Brah ăn May kah gĭt ma gâp ntŭk ngai lơn tâm trôk ri.\n\nVerse 2\nGâp dơn jêh Yê-su tâm rklaih gâp, ăn may dơn Păng đŏng. Gâp dơn jêh Yê-su tâm rklaih gâp, ăn may dơn Păng đŏng. Gâp dơn jêh Yê-su tâm rklaih gâp, ăn may dơn Păng đŏng. Dôl aƀaơ Păng kuăl may. (Păng kuăl may)\n\nChorus\nKôranh Brah, ơ Kôranh Brah ăn May kah gĭt ma gâp Kôranh Brah, ơ Kôranh Brah ăn May kah gĭt ma gâp. Kôranh Brah, ơ Kôranh Brah ăn May kah gĭt ma gâp ntŭk ngai lơn tâm trôk ri.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0303", "title": "YÊ-HÔ-VA JÊNG RMĂK UEH GÂP", "song_number": "303", "lyrics": "YÊ-HÔ-VA JÊNG RMĂK UEH GÂP\n\nTC 742\n\nVerse 1\nYê-hô-va jêng rmăk ueh gâp, njŭn gâp rlu ntŭk nse. Rgŏ dak ntŭk đăp mpăn ƀư ăn ktang huêng gâp. Ăn rlu êp dak đăp mpăn.\n\nVerse 2\nPăng ntop nau rêh mhe huêng gâp, njŭn gâp hăn trong sŏng srăng, yor Amoh khlay Păng gâp mâu pưt ndơ ôh. Knŏng Păng mât mơh huêng gâp.\n\nVerse 3\nGeh gui nau khĭt gŭ êp gâp, gâp mâu uh ah mâu lah klach. Păng gŭ ndrel bonh leng nuih n'hâm gâp. Yor Păng mât mơh đăp mpăn.\n\nVerse 4\nNau yỗ ueh bơh Mbỡ klơ dơm, gâp lăp tâm ntŭk rlu. Tâm Amoh Yê-hô-va gâp răm maak đăp mpăn. Tâm ngih Mbỡ gâp Kôranh Brah.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0304", "title": "NCHRANG ANG TÂM NTŬK HE GŬ", "song_number": "304", "lyrics": "NCHRANG ANG TÂM NTŬK HE GŬ\n\n\nVerse 1\nNchrang ang tâm ntŭk he gŭ, nchrang ang tâm ntŭk he gŭ. He nchrang ƀư ang tâm ntŭk nau ngo, hăn mbơh A-moh Yê-su he.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0305", "title": "BRAH YÊ-SU NJŬN LEO GÂP", "song_number": "305", "lyrics": "BRAH YÊ-SU NJŬN LEO GÂP\n\n\nVerse 1\nBrah Yê-su njŭn leo gâp. Du nhuat chuat du tỡ huêng gâp bêng ma nau răm. Gŭ tâm nau rŏng Păng. Moh gâp rvê ir ôi taơ? Păng ntĭm trong ma gâp. Brah Yê-su njŭn leo gâp. du nhuat chuat du tỡ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0306", "title": "RLAU LƠN ĐŎNG", "song_number": "306", "lyrics": "RLAU LƠN ĐŎNG\n\n\nVerse 1\nYor ma May jêng Nơm ueh ngăn ngên. Gâp ŭch tâm rnê rlau lơn đŏng. ăn Brah Huêng Ueh May nti ăn gâp. Blau rŏng ma May rlau lơn đŏng.\n\nChorus\nRlau lơn rlau lơn đŏng gâp rŏng ma May Kôranh Brah Ndu rlau lơn đŏng, rlau lơn đŏng. Rlau lơn đŏng gâp rŏng ma May Kôranh Brah rlau lơn đŏng.\n\nVerse 2\nNau ueh uĭn May gŭ nchueng jŭm gâp. Gâp mbah yơk ma nau May yỗ. May mât mơh gâp ma nau n'hêl nễ. Gâp rŏng ma May rlau lơn đŏng.\n\nChorus\nRlau lơn rlau lơn đŏng gâp rŏng ma May Kôranh Brah Ndu rlau lơn đŏng, rlau lơn đŏng. Rlau lơn đŏng gâp rŏng ma May Kôranh Brah rlau lơn đŏng.\n\nVerse 3\nDôl geh sial vănh blông dak mƀŭt rbuh. May kơl gâp rgăn jêh đăp mpăn. May Nơm njŭn gâp kŏ tât đăp mpăn. Gâp rŏng ma May rlau lơn đŏng.\n\nChorus\nRlau lơn rlau lơn đŏng gâp rŏng ma May Kôranh Brah Ndu rlau lơn đŏng, rlau lơn đŏng. Rlau lơn đŏng gâp rŏng ma May Kôranh Brah rlau lơn đŏng.\n\nVerse 4\nTât lĕ rnôk gâp gŭ ta neh ntu. Kŏ gâp tât ta Ƀon Ueh May. Aơ nau gâp vơl gay ma May dơn. Ăn gâp rŏng May rlau lơn đŏng.\n\nChorus\nRlau lơn rlau lơn đŏng gâp rŏng ma May Kôranh Brah Ndu rlau lơn đŏng, rlau lơn đŏng. Rlau lơn đŏng gâp rŏng ma May Kôranh Brah rlau lơn đŏng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0307", "title": "PAH KAN HOM DÂK HĂN HOM", "song_number": "307", "lyrics": "PAH KAN HOM DÂK HĂN HOM\n\n\nVerse 1\nDâk hăn hom, pah kan hom. He hŏ jêng ndơ Kôranh Brah, ăn he tĭng ndỗ trong Păng gay njŭn he tâm nau rêh. Yê-su hăn ndrel ma he. Lơi klach ôh ran ƀa-ƀơ. Păng mât he jêh ri ntĭng tur Păng ƀư ktang he ƀa-ƀơ.\n\nChorus\nDâk hăn hom, pah kan hom. Ăn he njrăng Gŭ mbơh sơm. Ƀât lât Kôranh Brah mra văch ngăn yơh.\n\nVerse 2\nDâk hăn hom, pah kan hom. Gay ăn nuih n'hâm phung rngot, rvê ngai đah Brah Ndu Păng gay saơ tay nau kâp gân. He sâm mplăch ăn măt chieh. Khân păng uănh si tâm rkăng. Ăn he ntrôl khân păng dơn Amoh Yê-su Nơm ăn kon me.\n\nChorus\nDâk hăn hom, pah kan hom. Ăn he njrăng Gŭ mbơh sơm. Ƀât lât Kôranh Brah mra văch ngăn yơh.\n\nVerse 3\nDâk hăn hom, pah kan hom. Păng kuăl lĕ rngôch phung he, mâu dơi ăn ƀlao, Mâu đŏng rhơn yor ba dum tâm mir. Gay ƀư kan ma Kôranh Brah. Lơi mĭn ma he nơm ôh. Hăn ăn tât ntŭk tâm nal Kôranh he ŭch ma he pô nây.\n\nChorus\nDâk hăn hom, pah kan hom. Ăn he njrăng Gŭ mbơh sơm. Ƀât lât Kôranh Brah mra văch ngăn yơh.\n\nVerse 4\nDâk hăn hom, pah kan hom. Mâu hôm gĭt hŏt rgănh ôh, yor ma Nơm Tâm Chuai he, ăn he yơr bok pla klơ. Gŭ răp jăp ăn tât lôch. Ăn he gĭt nau blau srôih. Nau rlu, Kôranh Brah hŏ gŭ kâp he jêh bêng ma nau ang.\n\nChorus\nDâk hăn hom, pah kan hom. Ăn he njrăng Gŭ mbơh sơm. Ƀât lât Kôranh Brah mra văch ngăn yơh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0308", "title": "HÂK MAAK HĂN HOM", "song_number": "308", "lyrics": "HÂK MAAK HĂN HOM\n\n\nVerse 1\nHa-lê-lu-ya, Ha-lê-lu-ya, răm rhơn he nsong mbơh. Ha-lê-lu-ya, Ha-lê-lu-ya, nuih n'hâm đăp mpăn mro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0309", "title": "GÂP JÊNG KON HAĐĂCH TOYH LƠN", "song_number": "309", "lyrics": "GÂP JÊNG KON HAĐĂCH TOYH LƠN\n\n\nVerse 1\nMbỡ gâp klơ jêng ndrŏng, geh âk ngih âk mir, Păng djôt nau rŏng lĕ rngôch neh ntu tâm ti Păng. Lŭ rsang chăng êr nchrat ang n'hanh chrêk ma lơp. Hip Păng bêng ma ndơ mâu dơi kơp nau Păng ndrŏng.\n\nChorus\nGâp jêng jêh Kon Hađăch Kon Hađăch toyh lơn. Tâm Yê-su Nơm tâm rklaih gâp, jêng Kon Brah Ndu Nơm.\n\nVerse 2\nYê-su Kon Brah Ndu, Nơm Tâm Rklaih neh ntu, sak nsong ta neh ntu aơ geh âk nau rêh ni. Ƀiă lah a-ƀơ aơ Păng jêng Hađăch ta klơ. Păng mra ăn ma gâp du mlâm ngih ueh ngăn ngên.\n\nChorus\nGâp jêng jêh Kon Hađăch Kon Hađăch toyh lơn. Tâm Yê-su Nơm tâm rklaih gâp, jêng Kon Brah Ndu Nơm.\n\nVerse 3\nGĭt lah gŭ ngih bok, Mâu lah ngih jễ lễ, moh hôm gâp rvê? gâp mra geh âk ngih prăk maih. Abaơ gâp jêng bu năch gŭ ƀlât ta neh ntu Ƀiă lah mât ton Păng gâp jêng Kon Hađăch toyh lơn.\n\nChorus\nGâp jêng jêh Kon Hađăch Kon Hađăch toyh lơn. Tâm Yê-su Nơm tâm rklaih gâp, jêng Kon Brah Ndu Nơm.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0310", "title": "AƠ JÊNG NAU KHLAY NGĂN", "song_number": "310", "lyrics": "AƠ JÊNG NAU KHLAY NGĂN\n\n\nVerse 1\nMay mâu dơi dun ôh nau pô-aơ. Brah Ndu jêng Mbỡ gâp Nơm. Kôranh Brah nau dơi nđâp nau khlay ngăn gay tâm mpơl ta klơ trôk.\n\nChorus\nAơ jêng nau khlay ngăn. Păng dơm phung mănh ta klơ trôk. Aơ jêng nau khlay ngăn, Păng n'gân rplay neh tâm đôr hŏng, ƀiă lah Păng rklaih huêng gâp. Păng rao lĕ tih gâp, aơ jêng nau khlay ngăn bơh nau rŏng, nau yỗ.\n\nVerse 2\nBơh nau chrêk ma lơp Păng sol ang. Na-nễ he mâu dil uănh. Nau dơi nđâp nau khlay ngăn Kôranh Brah ăn gâp nau rêh n'ho ro.\n\nChorus\nAơ jêng nau khlay ngăn. Păng dơm phung mănh ta klơ trôk. Aơ jêng nau khlay ngăn, Păng n'gân rplay neh tâm đôr hŏng, ƀiă lah Păng rklaih huêng gâp. Păng rao lĕ tih gâp, aơ jêng nau khlay ngăn bơh nau rŏng, nau yỗ.\n\nVerse 3\nNau Brah Ndu Ngơi mbơh nau Păng dơi. Nđâp nau njêh tâm lĕ rnôk. Jêh ri phung sĭm jễ nđâp kao ueh ăt mbơh lĕ nau khlay nây.\n\nChorus\nAơ jêng nau khlay ngăn. Păng dơm phung mănh ta klơ trôk. Aơ jêng nau khlay ngăn, Păng n'gân rplay neh tâm đôr hŏng, ƀiă lah Păng rklaih huêng gâp. Păng rao lĕ tih gâp, aơ jêng nau khlay ngăn bơh nau rŏng, nau yỗ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0311", "title": "JÊNG KON HAĐĂCH TOYH TÂM TRÔK", "song_number": "311", "lyrics": "JÊNG KON HAĐĂCH TOYH TÂM TRÔK\n\nTC 848\n\nVerse 1\nJêng Kon Hađăch toyh tâm trôk, Păng geh nau rŏng mâu lôch. Mbỡ gâp geh nau rŏng rmeh ler mâu rgâl. Mbah ntŭk gâp mra leo hăn. Trong phŭt sial nau rêh ni. Ti Brah Ndu mra njŭn leo gâp đăp mpăn.\n\nChorus\nGâp rŏng Yê-su ƀa-ƀơ. Gâp jêng Kon Hađăch ta klơ. Tâm ti Brah Ndu gâp mâu hôm gŭ êng. Aƀơ aơ, gâp dôl gŭ kâp. Nar nây tăng Yê-su kuăl. Hăn Ƀon Ueh gŭ ntŭk sưng Hađăch chrêk rmah.\n\nVerse 2\nJêng Kon Hađăch toyh tâm trôk, nau ton ơm bơh kăl e. Phung he ndrel ngrŭp rêh maak tâm ngih Mbỡ. Nar maak nây mra tât ngăn. Jêng nar tăng Yê-su kuăl. Hăn Ƀon Ueh gŭ rêh ndrel Păng ƀa-ƀơ.\n\nChorus\nGâp rŏng Yê-su ƀa-ƀơ. Gâp jêng Kon Hađăch ta klơ. Tâm ti Brah Ndu gâp mâu hôm gŭ êng. Aƀơ aơ, gâp dôl gŭ kâp. Nar nây tăng Yê-su kuăl. Hăn Ƀon Ueh gŭ ntŭk sưng Hađăch chrêk rmah.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0312", "title": "MBU NƠM GŬ MPEH YÊ-SU", "song_number": "312", "lyrics": "MBU NƠM GŬ MPEH YÊ-SU\n\n\nVerse 1\nMbu nơm gŭ mpeh Yê-su? Mbu yơk mbah ma Hađăch klơ? Mbu nhhơr nau rêh tâm rklaih bunuyh gŭ tâm nau khĭt. Mbu dơi lơi neh ntu aơ ran tâm lơh phung rlăng. Mbu nơm ton tât ta ntŭk Brah Ndu prơh đă hăn.\n\nChorus\nMa nau rŏng Păng kuăl he. Ma nau yỗ Păng ăn. Dâk hom phung tahan Brah Hađăch klơ rêh maak ma Păng.\n\nVerse 2\nMbu lơi lĕ nau lư n'găr. Ŭch tĭng ndỗ Kôranh Brah ton, ran hăn tĭng phung ta han Hađăch Chrêk Rmah kŏ khĭt. Yor nau tih lĕ rngôch he Hađăch Yê-su khĭt jêh. Mbu nơm ton nhhơr nau rêh, lah tăng Kôranh Brah kuăl.\n\nChorus\nMa nau rŏng Păng kuăl he. Ma nau yỗ Păng ăn. Dâk hom phung tahan Brah Hađăch klơ rêh maak ma Păng.\n\nVerse 3\nNau tâm lơh hôm e jŏ. Phung rlăng ƀa-ƀơ ŭch dơi. Ƀiă lah phung ta han Hađăch klơ ran ŭch tâm lơh. Mâu klach khĭt tâm rnglăp rdâng bok pla du ai rjăp. Yor nau na-nễ ton nhhơr nau rêh ăn ma Păng.\n\nChorus\nMa nau rŏng Păng kuăl he. Ma nau yỗ Păng ăn. Dâk hom phung tahan Brah Hađăch klơ rêh maak ma Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0313", "title": "NTŬK TÂM LƠH", "song_number": "313", "lyrics": "NTŬK TÂM LƠH\n\nTC 377\n\nVerse 1\nAƀaơ gâp jêng ta han Krist, dơi ŭch lăp tât lôch nau rêh. Nđâp lah tâm lơh jŏ nar mâu lah âk nau jêr kđôi lĕ. Dŏng ao loih rêt se bŭt, rŭn rduh tâm lơh ma đao Brah. Lah may joi mra saơ gâp tâm ntŭk rđâng tâm lơh.\n\nChorus\nNteh jâng grĭp grĭp phung ta han he chuat hăn, mprơh phung rlăng rai jêh, nau mprơ ma bâr huy, Nteh jâng grĭp grĭp phung ta han he chuat ndăng. Ntuh bâr mprơ dơi ntŭk tâm lơh.\nɃŭn ma gâp dơi lăp phung ta han kloh ueh Yê-hô-va phung ta han kơl gâp dơi dăng. Ƀŭn ma gâp dơi lăp ndrel phung ta-han tâm lơh. Gay joi gâp may hăn hom tâm ntŭk rđŭng tâm lơh.\n\nVerse 2\nNau rŏng Kôranh Brah Yê-su, hao jêh tât ta bôl dŭt trôk. Lĕ nuih n'hâm hăn nsong mbơh ma lĕ rngôch bunuyh ntơm rai lôch. Nđâp phung rlăng ktang kđôi lĕ, nkêh hăr rlăng, rŭn rduh bah năp. Lah may joi mra saơ gâp tâm ntŭk rđâng tâm lơh.\n\nChorus\nNteh jâng grĭp grĭp phung ta han he chuat hăn, mprơh phung rlăng rai jêh, nau mprơ ma bâr huy, Nteh jâng grĭp grĭp phung ta han he chuat ndăng. Ntuh bâr mprơ dơi ntŭk tâm lơh.\nɃŭn ma gâp dơi lăp phung ta han kloh ueh Yê-hô-va phung ta han kơl gâp dơi dăng. Ƀŭn ma gâp dơi lăp ndrel phung ta-han tâm lơh. Gay joi gâp may hăn hom tâm ntŭk rđŭng tâm lơh.\n\nVerse 3\nAơ gâp ôp ma oh nâu, ŭch jêng ta-han si tâm rkăng. nguay n'hanh phung tahan Brah Krist răp jăp ndrel Yê-su Hađăch he. Lor ma nar Kôranh Brah văch, tĭng ndỗ gâp lăp hom nar aơ. Lah may joi mra saơ gâp tâm ntŭk rđâng tâm lơh.\n\nChorus\nNteh jâng grĭp grĭp phung ta han he chuat hăn, mprơh phung rlăng rai jêh, nau mprơ ma bâr huy, Nteh jâng grĭp grĭp phung ta han he chuat ndăng. Ntuh bâr mprơ dơi ntŭk tâm lơh.\nɃŭn ma gâp dơi lăp phung ta han kloh ueh Yê-hô-va phung ta han kơl gâp dơi dăng. Ƀŭn ma gâp dơi lăp ndrel phung ta-han tâm lơh. Gay joi gâp may hăn hom tâm ntŭk rđŭng tâm lơh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0314", "title": "ĂP MNĬT", "song_number": "314", "lyrics": "ĂP MNĬT\n\nTC 295\n\nVerse 1\nGâp kơp gâp nơm hŏ khĭt ndrel ma Kôranh Brah. Păng ăn ma gâp nau rêh jêh ri nau Brah. Uănh ma Yê-su tât geh nau chrêk rmah, ăp mnĭt ăp mông, gâp hŏ jêng ndơ Kôranh Brah ngăn.\n\nChorus\nĂp mnĭt ăp mông Yê-su rŏng mât mơh gâp. Ăp mnĭt ăp mông ăn nau rêh mhe bơh klơ. Nau chroh ma Yê-su tât geh nau chrêk rmah, Ăp mnĭt ăp mông gâp hŏ jêng ndơ Kôranh Brah.\n\nVerse 2\nPăng mâu cha lơi gâp dôl geh nau rlong uănh. Kôranh Brah mâu mâp dun ôh lĕ nau jâk jêr. Păng mâu lĕ dơi chuêl ma gâp, dôl geh nau rngot, ăp mnĭt ăp mông Păng mât gâp ƀa-ƀơ.\n\nChorus\nĂp mnĭt ăp mông Yê-su rŏng mât mơh gâp. Ăp mnĭt ăp mông ăn nau rêh mhe bơh klơ. Nau chroh ma Yê-su tât geh nau chrêk rmah, Ăp mnĭt ăp mông gâp hŏ jêng ndơ Kôranh Brah.\n\nVerse 3\nPăng treng uănh gâp dôl nuih n'hâm gâp nđêng ji. Păng saơ hoch dak măt jêh ri tăng gâp nhĭm. Bơh sưng hađăch Păng saơ gâp geh nau djơh mhĭk ăp mnĭt ăp mông Păng ăt mĭn rvê ma gâp.\n\nChorus\nĂp mnĭt ăp mông Yê-su rŏng mât mơh gâp. Ăp mnĭt ăp mông ăn nau rêh mhe bơh klơ. Nau chroh ma Yê-su tât geh nau chrêk rmah, Ăp mnĭt ăp mông gâp hŏ jêng ndơ Kôranh Brah.\n\nVerse 4\nPăng gĭt saơ jêh lĕ nau hươi rdja tâm gâp. Mâu geh du ntil Yê-su mâu blau ƀư bah. Ăp mnĭt ăp mông dôl nau rngot mâu lah maak, Yê-su nơm tâm rklaih gŭ ndrel gâp ƀa-ƀơ.\n\nChorus\nĂp mnĭt ăp mông Yê-su rŏng mât mơh gâp. Ăp mnĭt ăp mông ăn nau rêh mhe bơh klơ. Nau chroh ma Yê-su tât geh nau chrêk rmah, Ăp mnĭt ăp mông gâp hŏ jêng ndơ Kôranh Brah.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0315", "title": "TA KƠH ĐAH RI", "song_number": "315", "lyrics": "TA KƠH ĐAH RI\n\n\nVerse 1\nTa kơh đah ri ntŭk neh ntu mhe, geh du nau rêh bêng ma chrêk rmah. Ta nây yơh gŭ Nơm Tâm Rklaih gâp, nau uh ah du mâu rngot rvê ôh.\n\nVerse 2\nLĕ drăp ndơ khlay mâu dơi kơp ôh, nau rŏng toyh Păng prăp ăn ta klơ. Mông gâp lơi neh ntu djơh mhĭk aơ, gâp gĭt Păng ăn lĕ ndơ ueh uĭn.\n\nVerse 3\nYor Kôranh Brah dăp tâm rnê ma Păng, nau Păng mât mơh ăn gâp kon me. Moh gâp hôm rvê jao lĕ ma Păng, nau rgănh rgônh jâk Păng anh ăn jêh.\n\nVerse 4\nNuih n'hâm huêng gâp bêng nau đăp mpăn, gâp răm rhơn mprơ, Ha-lê-lu-ya. Ma nau Brah Păng, Păng njŭn leo gâp, tât ta ntŭk maak bêng ma chrêk rmah.\n\nVerse 5\nNơm tâm rklaih ơi! Sâm nti gâp bă, nau rêh gâp aơ, ăn di đah May. Dôl rgăn rnôk aơ hăn ran bah năp, lor ma gâp tât ta Ƀon Ueh May.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0316", "title": "NƠM BRAH TA N'GOR GA-LI-LÊ", "song_number": "316", "lyrics": "NƠM BRAH TA N'GOR GA-LI-LÊ\n\n\nVerse 1\nDu nar gâp gŭ mĭn ma n'gor Ga-li-lê, dak mƀŭt ri ntŭk Krist hăn kăl-e. Gâp saơ rmưn rsen bunuyh ŭch tăng nau Păng ngơi. Nơm Brah lơn tâm n'gor Ga-li-lê. Geh du huê măt chieh geh bơh nar păng deh. Ƀât lât ro păng plỡ saơ nau ang. Phung rvĕn dơi chuat hăn, phung mlo plỡ dơi tăng Nơm Brah lơn tâm n'gor Ga-li-lê.\n\nChorus\nGâp mra rŏng ƀa-ƀơ, Nơm nây gâp gĭt ngăn, Păng bêng nau yỗ, nau ueh hâu ngăn. Gâp sŏk dơn Păng jêng Nơm Tâm Rklaih gâp, Nơm Brah tâm n'gor Ga-li-lê.\n\nVerse 2\nBu djôt ma Păng bu-nuyh geh nau tih mhĭk, knŏng du huê Păng dơm geh nau yỗ. Phung bunuyh ji dơi bah phung khĭt dơi dak rêh. Nơm Brah lơn tâm n'gor Ga-li-lê. Phung jêr phung rngot klân, bu-nuyh brah mhĭk lơh. Văch ma Păng geh nau răm ma-ak. Na-nễ Păng dơi nkra djôt lĕ ntil kan ueh, Nơm Brah lơn tâm n'gor Ga-li-lê.\n\nChorus\nGâp mra rŏng ƀa-ƀơ, Nơm nây gâp gĭt ngăn, Păng bêng nau yỗ, nau ueh hâu ngăn. Gâp sŏk dơn Păng jêng Nơm Tâm Rklaih gâp, Nơm Brah tâm n'gor Ga-li-lê.\n\nVerse 3\nNau ngơi Păng buay sial mâu hôm ăn dak rƀŭh, sial dak nây lơi rngân đăp mpăn ro. Pô nây dak, sial tông ro ma yor Păng buay. Nơm Brah lơn tâm n'gor Ga-li-lê. Nau đăp mpăn hôm mât uănh tâm nuih n'hâm gâp. Jêng du nau sâm bonh leng an gâp. Păng djôt nau rêh gâp tâm ti nau Brah Păng, Nơm Brah lơn tâm n'gor Ga-li-lê.\n\nChorus\nGâp mra rŏng ƀa-ƀơ, Nơm nây gâp gĭt ngăn, Păng bêng nau yỗ, nau ueh hâu ngăn. Gâp sŏk dơn Păng jêng Nơm Tâm Rklaih gâp, Nơm Brah tâm n'gor Ga-li-lê.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0317", "title": "MOH GÂP ĂN MAY KÔRANH BRAH", "song_number": "317", "lyrics": "MOH GÂP ĂN MAY KÔRANH BRAH\n\n\nVerse 1\nMoh gâp ăn ma May Kôranh Brah? May Nơm khĭt ăn ma gâp gâp mâu ŭch ăn djễ ôh ndơ gâp geh, ƀiă lah gâp ăn lĕ ma May.\n\nChorus\nYê-su Kôranh Brah Nơm rklaih gâp. Moh gâp ăn ma May Kôranh Brah. May hŏ ăn lĕ ma gâp. May hŏ lơi ngih May ta klơ gay khĭt ta ntŭk kăl-ver. May hŏ ăn lĕ ma gâp. Mâu di ôh du kŏ n'gul nuih n'hâm gâp. Gâp ŭch ăn lĕ ma May.\n\nVerse 2\nMoh gâp ăn ma May Kôranh Brah? May hŏ sâm chuai huêng gâp. Ndơ gâp ăn jễ ƀiă lah gâp jao lĕ, gay ma May jêng Kôranh gâp ngăn.\n\nChorus\nYê-su Kôranh Brah Nơm rklaih gâp. Moh gâp ăn ma May Kôranh Brah. May hŏ ăn lĕ ma gâp. May hŏ lơi ngih May ta klơ gay khĭt ta ntŭk kăl-ver. May hŏ ăn lĕ ma gâp. Mâu di ôh du kŏ n'gul nuih n'hâm gâp. Gâp ŭch ăn lĕ ma May.\n\nVerse 3\nMoh gâp ăn ma May Kôranh Brah? Nơm ăn lĕ rngôch ndơ Brah. Gâp mâu geh têm du ntil ndơ gâp geh, gâp ŭch nhhơr lĕ ma May ro.\n\nChorus\nYê-su Kôranh Brah Nơm rklaih gâp. Moh gâp ăn ma May Kôranh Brah. May hŏ ăn lĕ ma gâp. May hŏ lơi ngih May ta klơ gay khĭt ta ntŭk kăl-ver. May hŏ ăn lĕ ma gâp. Mâu di ôh du kŏ n'gul nuih n'hâm gâp. Gâp ŭch ăn lĕ ma May.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0318", "title": "PHUNG BUNUYH CHUAT TÂM NAU NGO", "song_number": "318", "lyrics": "PHUNG BUNUYH CHUAT TÂM NAU NGO\n\n\nVerse 1\nPhung bunuyh chuat hăn tâm nau ngo klĕng, phung bunuyh chuat hăn tâm nau ngo klĕng. Phung bunuyh chuat hăn tâm nau ngo klĕng....\nPhung bunuyh chuat hăn tâm nau ngo klĕng phung bunuyh chuat hăn tâm nau ngo klĕng saơ jêh nau ang toyh saơ lĕ jêh nau ang toyh.\nPhung bunuyh chuat hăn tâm nau ngo klĕng, phung bunuyh chuat hăn tâm nau ngo klĕng saơ jêh nau ang toyh ngăn.\nPhung bunuyh chuat hăn tâm nau ngo klĕng, phung bunuyh chuat hăn tâm nau ngo klĕng, phung bunuyh chuat hăn tâm nau ngo klĕng....\nPhung bunuyh chuat hăn tâm nau ngo klĕng, phung bunuyh chuat hăn tâm nau ngo klĕng, phung bunuyh chuat hăn tâm nau ngo klĕng, saơ jêh nau ang toyh, saơ jêh nau ang toyh.\nnau ang toyh.... Saơ jêh nau ang toyh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0319", "title": "SĬM, KAO JÊH RI BUNUYH", "song_number": "319", "lyrics": "SĬM, KAO JÊH RI BUNUYH\n\n\nVerse 1\nLêp lơp, lêp lơp sĭm mpăr nsong klơ trôk, ăt mâu mâp tăm mir mâu lĕ muih kăl. Mâm he jêng bunuyh khlay lơn ma phung sĭm. Moh ŭch rngot rvê, mâu hôm uh ăh lĕ!\n\nChorus\nƠ Kôranh Brah dăn May njŭn leo lĕ nau rêh bêng ma đăp mpăn. Jao ma May lĕ nar bah năp nuih n'hâm gâp bêng ma răm rhơn.\n\nVerse 2\nNeh kao, dak maak bêng ma kao lêr êr, kho kloh ao ueh đêh brai mâu prot rui. Ao Hađăch khư rman mâu ban đah kao ueh. Moh hôm ŭch mĭn rêh khlay lơn kao si\n\nChorus\nƠ Kôranh Brah dăn May njŭn leo lĕ nau rêh bêng ma đăp mpăn. Jao ma May lĕ nar bah năp nuih n'hâm gâp bêng ma răm rhơn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0320", "title": "NAU ANG CHRAT TÂM NTŬK NÂY", "song_number": "320", "lyrics": "NAU ANG CHRAT TÂM NTŬK NÂY\n\n\nVerse 1\nNau ang chrat tâm ntŭk nây phung sĭm ndrau maak tâm nau ang ueh. Ndâr ntŭk ngo mâu hôm geh ôh. Ta ntŭk Krist gŭ rêh n'ho ro.\n\nChorus\nTa ntŭk moh ntŭk? Ta ntŭk ueh uĭn gŭ đăp mpăn ngăn tâm Ƀon Ueh ntŭk bunuyh rêh nau rêh mhe. Rnôk ueh ri Krist gŭ rêh n'ho ro.\n\nVerse 2\nLĕ ntŭk nau ngo mâu hôm geh ntŭk nây lĕ kan mra lôch jêh. Rnôk nây nuih n'hâm gŭ nâp rjăp. Rnôk nau dơi chrêk rmah n'ho ro.\n\nChorus\nTa ntŭk moh ntŭk? Ta ntŭk ueh uĭn gŭ đăp mpăn ngăn tâm Ƀon Ueh ntŭk bunuyh rêh nau rêh mhe. Rnôk ueh ri Krist gŭ rêh n'ho ro.\n\nVerse 3\nNau tih ơm Păng yỗ ăn jêh bôk mpông pơk gŭ kâp phung he. Ntŭk ndâr ngo klĕng nĕ roh jêh. Rnôk phung tông mpăr gŭ kâp gân.\n\nChorus\nTa ntŭk moh ntŭk? Ta ntŭk ueh uĭn gŭ đăp mpăn ngăn tâm Ƀon Ueh ntŭk bunuyh rêh nau rêh mhe. Rnôk ueh ri Krist gŭ rêh n'ho ro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0321", "title": "HE JÊNG TAHAN KRIST", "song_number": "321", "lyrics": "HE JÊNG TAHAN KRIST\n\nTC 829\n\nVerse 1\nBêng ma hâk maak chuat ndrel ma Kôranh Brah. Rŏ trong Ƀon ueh tâm lơh đah Sa-tan. Nsing ma Yê-su he hăn rlet pa năp, dơi đah phung rlăng he mprơ bâr huy.\n\nChorus\nChuat hăn hâk răm, mâu klach nau jêr jŏk. Yê-su, Yê-su njŭn he tâm lĕ trong. Jêng ta-han Krist du ai hăn tâm lơh. Nau mprơ dơi tâm lơh nhhơr Kôranh Brah.\n\nVerse 2\nÂk phung ƀon lan hôm e tâm nau jêr. Chuat tâm nau ngo mâu hôm dơi gĭt trong. Kay lŏng he ran tâm lơh ăn Yê-su, sŏk sĭt khân păng rlet ta ntŭk ang.\n\nChorus\nChuat hăn hâk răm, mâu klach nau jêr jŏk. Yê-su, Yê-su njŭn he tâm lĕ trong. Jêng ta-han Krist du ai hăn tâm lơh. Nau mprơ dơi tâm lơh nhhơr Kôranh Brah.\n\nVerse 3\nNsing ma Yê-su he dơi đah Sa-tan. Hâk răm mât ton tâm rnê ma Kôranh Brah. Kâp nau nkhôm toyh Păng ăn nar kăn dỡ, dơi gŭ êp Ƀon Ueh Kôranh Brah klơ.\n\nChorus\nChuat hăn hâk răm, mâu klach nau jêr jŏk. Yê-su, Yê-su njŭn he tâm lĕ trong. Jêng ta-han Krist du ai hăn tâm lơh. Nau mprơ dơi tâm lơh nhhơr Kôranh Brah.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0322", "title": "BRAH NDU RHĂK LĔ MPÔ MPA", "song_number": "322", "lyrics": "BRAH NDU RHĂK LĔ MPÔ MPA\n\n\nVerse 1\nBrah Ndu rhăk lĕ mpô mpa, Brah Ndu rhăk lĕ mpô mpa. Phung sĭm blau ndrau, phung ka blau re, Brah Ndu njêng lĕ mpô mpa.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0323", "title": "HA-LÊ-LU-YA", "song_number": "323", "lyrics": "HA-LÊ-LU-YA\n\n\nVerse 1\nHa-lê-lu-ya, Ha-lê-lu-ya, Ha-lê-lu-ya, Ha-lê-lu-ya, Ha-lê-lu-ya, Ha-lê-lu-ya, Ha-lê-lu-ya, Ha-lê-lu-ya,\nHa-lê-lu-ya. Ha-lê-lu-ya, Ha-lê-lu-ya, Ha-lê-lu-ya.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0324", "title": "GÂP HĂN TA ƀON BRAH NDU KLƠ RI", "song_number": "324", "lyrics": "GÂP HĂN TA ƀON BRAH NDU KLƠ RI\n\n\nVerse 1\nGâp hăn ta Ƀon Brah Ndu klơ trôk, ta nây gâp gŭ n'ho ro Brah Ndu kuăl gâp jêh ri rom gâp yor lah Yê-su răng gâp.\n\nChorus\nGâp hăn ta Ƀon Brah Ndu klơ ri Yê-su njŭn leo gâp ta nây. Mbu nơm ŭch hăn ndrel ma gâp, tâm Ƀon Ueh Brah Ndu klơ ri.\n\nVerse 2\nɃon Brah Ndu klơ mâu geh ngo ôh, yor lah Yê-su nau ang. Lĕ rngôch geh nau kloh ueh da-dê he mâu hôm geh rngot ôh.\n\nChorus\nGâp hăn ta Ƀon Brah Ndu klơ ri Yê-su njŭn leo gâp ta nây. Mbu nơm ŭch hăn ndrel ma gâp, tâm Ƀon Ueh Brah Ndu klơ ri.\n\nVerse 3\nMâu geh nau jêr nau ngo nkŭm ôh, tâm Ƀon Ueh Brah Ndu klơ. Lĕ nau ji kuet, khĭt ôm hŏ rai jêh ăn he gŭ maak mro.\n\nChorus\nGâp hăn ta Ƀon Brah Ndu klơ ri Yê-su njŭn leo gâp ta nây. Mbu nơm ŭch hăn ndrel ma gâp, tâm Ƀon Ueh Brah Ndu klơ ri.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0325", "title": "DU NAR KĂN DỠ", "song_number": "325", "lyrics": "DU NAR KĂN DỠ\n\n\nVerse 1\nDu nar kăn-dỡ gâp mra dâk hăn, ma Ƀon Brah Ndu ta klơ trôk prêh. gâp ŭch mprơ ngăn nau aơ ƀa-ƀơ. Yor lah gâp kah rngăl tâm ngih Păng.\n\nChorus\nGâp mra saơ Brah Yê-su n'hêl ngăn. Jêh ri lah ueh ma Păng ƀa-ƀơ. Gâp mra saơ Brah Yê-su n'hêl ngăn. Jêh ri lah ueh ma Păng ƀa-ƀơ.\n\nVerse 2\nNđâp lah sa-ơm săk jăn blau ôm, ƀiă lah gâp mra geh săk jăn mhe. Jêh ri gâp mra geh tâm Ƀon Ueh. Du mlâm ngih ueh Yê-su nkra ăn.\n\nChorus\nGâp mra saơ Brah Yê-su n'hêl ngăn. Jêh ri lah ueh ma Păng ƀa-ƀơ. Gâp mra saơ Brah Yê-su n'hêl ngăn. Jêh ri lah ueh ma Păng ƀa-ƀơ.\n\nVerse 3\nDu nar kăn-dỡ lah lĕ lôch kan, Păng kuăl gâp lăp jêh ri lah ueh. Yor lah gâp nâp tâm Păng ƀa-ƀơ. Pô ri Păng rom gâp tâm ngih Păng.\n\nChorus\nGâp mra saơ Brah Yê-su n'hêl ngăn. Jêh ri lah ueh ma Păng ƀa-ƀơ. Gâp mra saơ Brah Yê-su n'hêl ngăn. Jêh ri lah ueh ma Păng ƀa-ƀơ.\n\nVerse 4\nTât nar gâp hăn gâp ŭch hăn mbơh, ma lĕ rngôch nuyh ăn lơi nau tih. Pô-ri mơ khân păng dơi klaih đŏng. Nâm bu gâp gŭ răm maak ƀa-ƀơ.\n\nChorus\nGâp mra saơ Brah Yê-su n'hêl ngăn. Jêh ri lah ueh ma Păng ƀa-ƀơ. Gâp mra saơ Brah Yê-su n'hêl ngăn. Jêh ri lah ueh ma Păng ƀa-ƀơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0326", "title": "TÂT KHĬT ĂT HE HÔM JÊNG SŎNG", "song_number": "326", "lyrics": "TÂT KHĬT ĂT HE HÔM JÊNG SŎNG\n\n\nVerse 1\nTât khĭt hên ăt mra jêng sŏng ta năp May tât khĭt. May mra jêng Hađăch ma lĕ rngôch phung hên. Pa dih ma May, Yê-su May kuăl hên n'hêl ngăn, hên mra sân săk, hăn tâm lơh yor nau chroh.\n\nChorus\nTât geh nau khĭt bâr he nter ma nau tâm lơh. Nter gay kon me, bơh phung hŏ tâm rklaih jêh. Kŏ tât geh nau khĭt hên mra ăn bok ma May. mham hoch ta si tâm rkăng, ơ Krist dâk rêh.\n\nVerse 2\nƠ Yê-su, tâm May mra geh nau rêh răm rhơn. Lĕ rngôch trong ndrel ma May nâm bu nơih dơm. Kon Biăp Brah Ndu, mâu di ƀơh hên tĭng ndỗ May tât ma nau khĭt, ơ Nơm khĭt jêh ma hên.\n\nChorus\nTât geh nau khĭt bâr he nter ma nau tâm lơh. Nter gay kon me, bơh phung hŏ tâm rklaih jêh. Kŏ tât geh nau khĭt hên mra ăn bok ma May. mham hoch ta si tâm rkăng, ơ Krist dâk rêh.\n\nVerse 3\nTông ma nau Brah May kŏ tât ma nau hên khĭt. Hên ŭch rêh jêh ri khĭt tông nau vay May. May dơm jêng Nơm ntrôl ăn ma nau tông bâr May dơn nau rêh ni, khĭt nđâp ta si tâm rkăng.\n\nChorus\nTât geh nau khĭt bâr he nter ma nau tâm lơh. Nter gay kon me, bơh phung hŏ tâm rklaih jêh. Kŏ tât geh nau khĭt hên mra ăn bok ma May. mham hoch ta si tâm rkăng, ơ Krist dâk rêh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0327", "title": "KAN BRAH NDU", "song_number": "327", "lyrics": "KAN BRAH NDU\n\n\nVerse 1\nĂn he jik hom, ăn lĕ yor lah yăn tuch tăm tât jêh. Brah Ndu ntơm djrah ma dak mih, gay ăn hon ndơ he tuch. Kôranh Brah dơm mra mât mơh mbo ba nđâp lĕ ndơ tâm mir. Mâu geh ntil ndơ mâu hon. Păng mra ăn nau đăp mpăn ngăn.\n\nChorus\nBrah Ndu Nơm jêng Brah Nơm nkhŭt ăn nau ueh ƀa-ƀơ. Tâm rnê Brah Ndu mât ton ma Păng. Nau rŏng Păng khlay hâu ngăn.\n\nVerse 2\nKôranh Brah Ndu jêng Nơm rhăk lĕ rngôch ndơ tâm neh ntu aơ. Păng sâm nsoh ma kao nau ueh, dôl măng mănh nchrat rêp ƀlêp. Dak rlai ăt tông bâr Păng. Păng dơm mât lĕ rngôch mpô mpa. Păng ăt kơl he ƀa-ƀơ. Kâp nkhŭt nau ueh uĭn bơh klơ.\n\nChorus\nBrah Ndu Nơm jêng Brah Nơm nkhŭt ăn nau ueh ƀa-ƀơ. Tâm rnê Brah Ndu mât ton ma Păng. Nau rŏng Păng khlay hâu ngăn.\n\nVerse 3\nĂn he mprơ tâm rnê Păng, Lah ueh ma Păng yor nau ueh. Păng ăn ma he lĕ rngôch ntil, kŏ tât mbo ba dơi dŭm. Kơl he rek nsĭt ăn gơnh. Ăn nâp nau ka-tang ăp nar. Tâm rnê ăn hâu Kôranh he. Mbỡ ma nau rŏng mât mơh hên.\n\nChorus\nBrah Ndu Nơm jêng Brah Nơm nkhŭt ăn nau ueh ƀa-ƀơ. Tâm rnê Brah Ndu mât ton ma Păng. Nau rŏng Păng khlay hâu ngăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0328", "title": "DÔL SRIH MA BRAH HUÊNG UEH", "song_number": "328", "lyrics": "DÔL SRIH MA BRAH HUÊNG UEH\n\n\nVerse 1\nDôl srih ma Brah Huêng Ueh, jêh nây srih ăp nar. Dôl srih ntil nau blau yỗ, Srih tĭng rlong tât lôch. Dôl srih ma Brah Huêng Ueh. Dôl srih ma Kôranh Brah kan he ƀư mra jêng ueh, Kôranh Brah mra nkhôm he.\n\nChorus\nDôl srih ma Brah Huêng Ueh, srih kŏ tât nhâp nar, mâu rdja nuih mâu plỡ rŭch, pah kan tât lôch ro.\n\nVerse 2\nDôl srih ma Brah Huêng Ueh he mbơh sơm dôl hăn. Bơh ntil he hŏ srih jêh Ba mra hon tât prêh. Dôl srih ma nau rnơm ngăn. Brah Ndu mra ăn mih he mra saơ ta năp he, Ba dŭm nâm bu maih.\n\nChorus\nDôl srih ma Brah Huêng Ueh, srih kŏ tât nhâp nar, mâu rdja nuih mâu plỡ rŭch, pah kan tât lôch ro.\n\nVerse 3\nDôl srih ma Brah Huêng Ueh ma nau nsing hôm jễ. Dôl he hôm hươi kđôi lĕ klăp lah ma dak măt. He srih ntơm ôi tât măng. Tât he ƀư jêh kan ri mơ he mra nsĭt play, nau răm rhơn n'ho ro.\n\nChorus\nDôl srih ma Brah Huêng Ueh, srih kŏ tât nhâp nar, mâu rdja nuih mâu plỡ rŭch, pah kan tât lôch ro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0329", "title": "LĔ NDƠ MBƠH", "song_number": "329", "lyrics": "LĔ NDƠ MBƠH\n\n\nVerse 1\nLĕ ndơ mbơh Păng jêng khlay ngăn. Lĕ ndơ mbơh Păng jêng khlay ngăn. Neh ntu, dak krong tâm trôk ta klơ. Lĕ ndơ mbơh Păng jêng khlay ngăn ngên.\n\nVerse 2\nGâp gĭt ngăn Păng jêng khlay ngăn. Gâp gĭt ngăn Păng jêng khlay ngăn. Păng khlay, Păng ƀư maak nuih n'hâm gâp. Ngăn gâp gĭt Păng jêng khlay hâu ngăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0330", "title": "NAU CHRÊK MA LƠP PĂNG", "song_number": "330", "lyrics": "NAU CHRÊK MA LƠP PĂNG\n\n\nVerse 1\nNau chrêk ma lơp Păng. Nau chrêk ma lơp Păng, sol ang tâm nuih n'hâm gâp ma nau Brah. Nau chrêk ma lơp Păng. Nau chrêk ma lơp Păng. Ha-lê-ya Yê-su sol ang gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0331", "title": "HĂN HOM AY MAY LAM NEH NTU", "song_number": "331", "lyrics": "HĂN HOM AY MAY LAM NEH NTU\n\n\nVerse 1\nMbah ntŭk ngai ngăn geh âk bunuyh gŭ tâm nau tih, rmưn rsen bu-nuyh dơn nau rai yot n'ho ro. Mbu nơm ŭch hăn mbơh nau tâm rklaih ma khân păng uănh ma Yê-su mâu prêng ôh moh mra tât.\n\nChorus\nLĕ rngôch nau Brah ăn jêh ma gâp lĕ rngôch nau Brah ăn jêh ma gâp. Hăn hom ay may lam neh ntu mbơh nau mhe mhan ueh. Abaơ aơ Gâp gŭ ndrel ma ay may.\n\nVerse 2\nUănh hom jŭm bri mpông pêr hŏ pơk jêh ăn he, phung ta han Krist đâk jêh ri lăp hom he. Lơi lĕ nau tih du ai tâm rnglăp lĕ rngôch he djôt nau mhe mhan ueh ƀư rai lĕ nau tih.\n\nChorus\nLĕ rngôch nau Brah ăn jêh ma gâp lĕ rngôch nau Brah ăn jêh ma gâp. Hăn hom ay may lam neh ntu mbơh nau mhe mhan ueh. Abaơ aơ Gâp gŭ ndrel ma ay may.\n\nVerse 3\nBâr Brah Ndu kuăl mâm ƀư ay may ŭch khĭt lĕ? lơi tĭng nau khĭt, plỡ hom dơn tâm Amoh Păng. Ma yor lah Kôranh Brah gŭ ndrel ma he n'ho ro hăn mbơh hom nau tâm rklaih ma lĕ rngôch bunuyh.\n\nChorus\nLĕ rngôch nau Brah ăn jêh ma gâp lĕ rngôch nau Brah ăn jêh ma gâp. Hăn hom ay may lam neh ntu mbơh nau mhe mhan ueh. Abaơ aơ Gâp gŭ ndrel ma ay may.\n\nVerse 4\nBrah Ndu n'hŭch nar tơ lah phung bơh mpôl băl bunuyh, tâm rnê Brah Ndu ma yor phung he dơi jêh. Jêng jêh kon me, gŭ răm maak tâm nau tâm rklaih mprơ Ha-lê-lu-ya! Kôranh Brah yơh jêng Hađăch.\n\nChorus\nLĕ rngôch nau Brah ăn jêh ma gâp lĕ rngôch nau Brah ăn jêh ma gâp. Hăn hom ay may lam neh ntu mbơh nau mhe mhan ueh. Abaơ aơ Gâp gŭ ndrel ma ay may.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0332", "title": "HĂN HOM", "song_number": "332", "lyrics": "HĂN HOM\n\n\nVerse 1\nKôranh Brah Yê-su hŏ mâp ntăm jêh pô aơ: Hăn hom nsong mbơh Amoh Gâp. Nar aơ Yê-su ăt đă ma gâp hăn mbơh iăt hom bâr Păng kuăl may.\n\nChorus\nHăn hom hăn hom iăt hom Brah Yê-su dôl kuăl. Hăn hom hăn hom hăn hom nsong mbơh Amoh Yê-su.\n\nVerse 2\nKôranh Brah Yê-su hŏ ăn jêh nau ntăm aơ: Hăn hom nsong mbơh Amoh Gâp. Ma mbu nơm dơn nau Brah tâm A-moh Păng mra klaih bơh dĭk brah mhĭk.\n\nChorus\nHăn hom hăn hom iăt hom Brah Yê-su dôl kuăl. Hăn hom hăn hom hăn hom nsong mbơh Amoh Yê-su.\n\nVerse 3\nKôranh Brah Yê-su ăn jêh ma he ŭch ma neh ntu dơi gĭt rbăng nau. Păng nkhŭt jêh mham khlay Păng Nơm ma he, nau rŏng Păng toyh hâu ngăn ngên.\n\nChorus\nHăn hom hăn hom iăt hom Brah Yê-su dôl kuăl. Hăn hom hăn hom hăn hom nsong mbơh Amoh Yê-su.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0333", "title": "LƠI KLACH ÔH", "song_number": "333", "lyrics": "LƠI KLACH ÔH\n\nTC 450\n\nVerse 1\nLơi klach ôh knŏng ăn may chroh. Lơi klach ôh knŏng ăn may chroh. Lĕ rngôch ndơ Păng dơi ƀư da-dê ma mbu nơm chroh.\nMay uănh ma Nơm Tâm Rklaih, Păng ăt jêng ktang ƀa-ƀơ. Lĕ rngôch ndơ Păng dơi ƀư da-dê ma mbu nơm chroh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0334", "title": "GEH DU MLÂM KON BIĂP", "song_number": "334", "lyrics": "GEH DU MLÂM KON BIĂP\n\n\nVerse 1\nGeh du mlâm kon biăp roh tâm yôk nhhiăng ƀe-hĕ. Geh du mlâm kon biăp roh tâm yôk nhhiăng ƀe-hĕ. Păng rngot êng geh nau klach, nau djơh mhĭk ngai bơh n'gar Păng. Geh du mlâm kon biăp roh tâm yôk, ngai bơh rmăk biăp ueh Păng.\n\nVerse 2\nPhung rmăk biăp hăn uănh tâm hang yôk, joi biăp păng. Phung rmăk biăp hăn uănh tâm hang yôk, joi biăp păng. Yor păng rŏng, jêh păng uănh, ta aơ ta ri tâm lam yôk. Pô ri rmăk biăp hăn uănh tâm yôk, jêh ri păng saơ biăp păng.\nPăng saơ du mlâm kon biăp Păng ut leo sĭt tâm n'gar Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0335", "title": "HÔ-SA-NA, Ơ HÔ-SA-NA!", "song_number": "335", "lyrics": "HÔ-SA-NA, Ơ HÔ-SA-NA!\n\n\nVerse 1\nHô-sa-na ơ Hô-sa-na, phung kon se mprơ nteh huy. Ta n'gŏ trong jêh ri tâm ngih Brah Ndu bu dơi tăng nau mprơ nây. Mprơ ma Yê-su Nơm mât ton phung jễ, khân păng gŭ ta ntang ntơh Păng. Phung kon se mprơ nau tâm rnê Păng ăn nau ueh jêh ri nau maak.\n\nVerse 2\nBơh yôk Ô-liu khân păng groi gay hăn ndrel lĕ rngôch bunuyh. Khân păng vŭk n'gĭng n'ha si tơm play đung jêh ri mprơ bâr nter huy. Păng Kôranh Brah ma bunuyh ma tông mpăr ueh ƀiă lah ncho ta klơ seh jễ. Yê-su geh nau maak yor ma nây, geh phung kon se gŭ jŭm Păng.\n\nVerse 3\nHô-sa-na, tâm ntŭk klơ trôk, he mprơ du nau mprơ ơm. Brah Yê-su Krist jêng Nơm Tâm Chuai he Kôranh Brah jêng Ha-đăch he. Ơ ăn he mât ton ma Păng ƀa-ƀơ, ma nuih n'hâm ma nau rêh he. He dơi geh nau răm ma-ak mro yor ma Păng gŭ êp ndrel he.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0336", "title": "NAU ANG CHRAT", "song_number": "336", "lyrics": "NAU ANG CHRAT\n\n\nVerse 1\nNtŭk njưh kŭm păn bu ndâk nâp jêh, bunuyh ntŭng mâu dơi lôk trôm ƀư rai. Nđâp lah phŭt chuănh dak rbuh rpuh dŭt hô kđôi lĕ, ăn he rduh ran ro gay mbơh Amoh Nơm Tâm Rklaih ma âk rbăn huêng bunuyh, hôm gŭ tâm nau ngo tât păng dơi klaih mâm ƀư.\n\nChorus\nNau chrêk rmah nau chrêk ma lơp sol ang mro ntŭk ngo klĕng. sol ăn ang hom kŏ tât geh nau đăp mpăn ro. Sol ang sol ang hom mro mrăng gŭ sol ang mro. Sol ang sol ang sol ang mro mrăng gŭ sol mro.\n\nVerse 2\nĂn ntŭk nây tât geh nau sol ang, gay dơi njŭn âk bunuyh hăn ta nây. Nđâp lah ndâr tŭk krăk ŭch nkŭm nau chrêk rmah nây, yor tă Yê-su gâp klaih jêh Păng ntĭm ăn trong gâp hăn rlet nau ang, gay ma nau ngo mâu hôm dơi nkŭm nau chrêk rmah.\n\nChorus\nNau chrêk rmah nau chrêk ma lơp sol ang mro ntŭk ngo klĕng. sol ăn ang hom kŏ tât geh nau đăp mpăn ro. Sol ang sol ang hom mro mrăng gŭ sol ang mro. Sol ang sol ang sol ang mro mrăng gŭ sol mro.\n\nVerse 3\nYor ma nau lơp bơh nau chrêk rmah, yor lah Mbỡ rŏng Păng gŭ n'ho ro. Ăn ma gâp nau sân săk mâu chrê moh nau tât, hŏ jao ăn ăp ma Kôranh Brah gâp Tâm âk mnĭt mông ơm vay ndăch mro lơi ƀư roh dơm dam ôh nau mbơh Amoh Yê-su\n\nChorus\nNau chrêk rmah nau chrêk ma lơp sol ang mro ntŭk ngo klĕng. sol ăn ang hom kŏ tât geh nau đăp mpăn ro. Sol ang sol ang hom mro mrăng gŭ sol ang mro. Sol ang sol ang sol ang mro mrăng gŭ sol mro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0337", "title": "TƠ LAH MAY GĬT", "song_number": "337", "lyrics": "TƠ LAH MAY GĬT\n\n\nVerse 1\nLah ay may gĭt n'hêl na-nễ nau tâm rklaih, hăn mbơh hom ma bu ƀă. Lah ay may gĭt n'hêl na-nễ nau tâm rklaih, hăn mbơh hom gay ô băl klaih đŏng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0338", "title": "KÔRANH BRAH JÊNG TOYH", "song_number": "338", "lyrics": "KÔRANH BRAH JÊNG TOYH\n\n\nVerse 1\nKôranh Brah jêng toyh, Ăn he mât ton ma Păng, Kôranh Brah jêng toyh, Ăn he mât ton ma Păng, Kôranh Brah jêng toyh ăn he mât ton ma Păng, Păng gĭt moh ndơ toyh lơn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0339", "title": "YÊ-SU RŎNG MA PHUNG KON SE", "song_number": "339", "lyrics": "YÊ-SU RŎNG MA PHUNG KON SE\n\n\nVerse 1\nYê-su rŏng ma phung kon se jễ. Lĕ rngôch phung kon se neh ntu, phung krăk êr mâu lah nglang, chăng. Lĕ rngôch khlay ta năp Yê-su. Păng rŏng ma kon se lĕ rngôch tâm neh ntu aơ.\n\nVerse 2\nYê-su khĭt ma phung kon se jễ. Lĕ rngôch phung kon se neh ntu, phung krăk êr mâu lah nglang, chăng. Lĕ rngôch khlay ta năp Yê-su, Păng khĭt ma kon se lĕ rngôch tâm neh ntu aơ.\n\nVerse 3\nYê-su rêh ma phung kon se jễ. Lĕ rngôch phung kon se neh ntu, phung krăk êr mâu lah nglang, chăng. Lĕ rngôch khlay ta năp Yê-su. Păng rêh ma kon se lĕ rngôch tâm neh ntu aơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0340", "title": "HA-LÊ-LU-YA!", "song_number": "340", "lyrics": "HA-LÊ-LU-YA!\n\nTC 538\n\nVerse 1\nHa-lê-lu! Ha-lê-lu! Ha-lê-lu! Ha-lê-lu-ya! mât ton Kôranh Brah. Ha-lê-lu! Ha-lê-lu! Ha-lê-lu! Ha-lê-lu-ya! mât ton Kôranh Brah.\nMât ton Kôranh Brah, Ha-lê-lu-ya! Mât ton Kôranh Brah Ha-lê-lu-ya! Mât ton Kôranh Brah, Ha-lê-lu-ya! Mât ton Kôranh Brah.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0341", "title": "ƀAƀƠ DÔL ĂP NAR", "song_number": "341", "lyrics": "ƀAƀƠ DÔL ĂP NAR\n\n\nVerse 1\nɃa-ƀơ dôl ăp nar, Yê-su njŭn trong gâp. Gâp tăng bâr Păng lah, lơi klach ôh, Gâp gŭ ndrel. Nau ngo luh du ngai lĕ lah gâp tăng bâr Păng kuăl, Na-nễ Păng mât uănh gâp ƀa-ƀơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0342", "title": "HAĐĂCH KLOH UEH", "song_number": "342", "lyrics": "HAĐĂCH KLOH UEH\n\nTC 340\n\nVerse 1\nMăt gâp treng uănh ma Ha-đăch kloh ueh, ta ntŭk Ƀon Ueh nchrat ang ƀa-ƀơ. Nâm bu bok krăk klôn lơi jêh ri nau ngo klĕng, păng njêng nâm nar ang ƀhiau.\n\nChorus\nGâp mra maak ngăn, nkoch tay nau aơ, gay lĕ bunuyh maak răm ndrel; Ha-lê-lu-ya, Ha-lê-lu-ya! tâm rnê Kon Biăp hoch mham khlay; Ha-lê-lu-ya, Ha-lê-lu-ya, Ha-lê-lu-ya!\n\nVerse 2\nNtơm gâp chroh ma Nơm jêng Kôranh toyh lơn, tâm nuih n'hâm gâp geh nau răm maak. Aơ Kon Biăp jêng nau ang ntŭk kloh ueh, geh nđâp nau Brah klơ trôk sol ang.\n\nChorus\nGâp mra maak ngăn, nkoch tay nau aơ, gay lĕ bunuyh maak răm ndrel; Ha-lê-lu-ya, Ha-lê-lu-ya! tâm rnê Kon Biăp hoch mham khlay; Ha-lê-lu-ya, Ha-lê-lu-ya, Ha-lê-lu-ya!\n\nVerse 3\nMông tâm mâp geh nau maak mâu blau nkoch, mông Păng vơt kon sau lăp tâm ngih. Uănh Kon Biăp gŭ nklang Amoh Brah chrat ang, lĕ phung chroh geh nau răm rhơn ngăn. Gâp mra saơ Păng bêng nau nchrat ang, kăl-e Kon Biăp sân săk.\n\nChorus\nGâp mra maak ngăn, nkoch tay nau aơ, gay lĕ bunuyh maak răm ndrel; Ha-lê-lu-ya, Ha-lê-lu-ya! tâm rnê Kon Biăp hoch mham khlay; Ha-lê-lu-ya, Ha-lê-lu-ya, Ha-lê-lu-ya!\n\nVerse 4\nRi phung gŭ rƀŭn yơk mbah jŭm Kôranh Brah, mbu nơm ngai ê hŏ năl Hađăch he. Măt n'gĭl uănh năl Păng ro jêng Brah Krist, yor ta jâng Păng hôm têl khap kđĭn.\n\nChorus\nGâp mra maak ngăn, nkoch tay nau aơ, gay lĕ bunuyh maak răm ndrel; Ha-lê-lu-ya, Ha-lê-lu-ya! tâm rnê Kon Biăp hoch mham khlay; Ha-lê-lu-ya, Ha-lê-lu-ya, Ha-lê-lu-ya!\n\nVerse 5\nKăn dỡ taơ gâp mra saơ muh măt Păng, Kôranh Brah n'ho njêng kơt rup Păng nơm. Uănh săk jăn he bêng nau tih mhĭk ngăn, ƀât lât Yê-su rgâl jêng nchrat ang.\n\nChorus\nGâp mra maak ngăn, nkoch tay nau aơ, gay lĕ bunuyh maak răm ndrel; Ha-lê-lu-ya, Ha-lê-lu-ya! tâm rnê Kon Biăp hoch mham khlay; Ha-lê-lu-ya, Ha-lê-lu-ya, Ha-lê-lu-ya!\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0343", "title": "KÔRANH BRAH YÊ-SU", "song_number": "343", "lyrics": "KÔRANH BRAH YÊ-SU\n\n\nVerse 1\nKôranh Brah Yê-su gŭ ta nklang he. Muh măt Păng treng uănh ma phung he. Ay may tăng lĕ bâr rdỡ rbăn Păng. Gâp ŭch mât ton lĕ rngôch. Gâp ŭch mât ton lĕ rngôch.\n\nVerse 2\nKôranh Brah Yê-su gŭ ta nklang he. Muh măt Păng treng uănh ma phung he. Ay may tăng lĕ bâr rdỡ rbăn Păng. Gâp ŭch tâm rklaih lĕ rngôch. Gâp ŭch tâm rklaih lĕ rngôch.\n\nVerse 3\nKôranh Brah Yê-su gŭ ta nklang he. Muh măt Păng treng uănh ma phung he. Ay may tăng lĕ bâr rdỡ rbăn Păng. Ơ Gâp rŏng ma lĕ rngôch. Ơ Gâp rŏng ma lĕ rngôch.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0344", "title": "DĂN KÔRANH BRAH KAH GĬT MA GÂP", "song_number": "344", "lyrics": "DĂN KÔRANH BRAH KAH GĬT MA GÂP\n\nTC 428\n\nVerse 1\nLah geh phŭt sial klôn rdu gâp, nôk gâp gŭ rngloi êng du huê. Lah ŭnh hit găn tâm puăn njônh, nđâp lah âk nau ndơm nsŭk nsôr.\n\nChorus\nƠ Kôranh Brah iăt hom bâr gâp kuăl aơ, May kah gĭt ma gâp rêh ni.\n\nVerse 2\nLah chuat lăn jêh nau rêh ni, dăn May king dak thăng, sial ktang. Nôk bêng nau krit kir rêh ni, tơ lah dăch ngâm tâm dâng dak.\n\nChorus\nƠ Kôranh Brah iăt hom bâr gâp kuăl aơ, May kah gĭt ma gâp rêh ni.\n\nVerse 3\nLah phung djơh mhĭk tŭn jot gâp, nau tih krăk kher ŭch klôn gâp. Nklang nau rêh mâu lah nau khĭt, lah gâp chuat tât mpông nau khĭt.\n\nChorus\nƠ Kôranh Brah iăt hom bâr gâp kuăl aơ, May kah gĭt ma gâp rêh ni.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0345", "title": "MBU NƠM DƠI NJÊNG", "song_number": "345", "lyrics": "MBU NƠM DƠI NJÊNG\n\n\nVerse 1\nMbu nơm dơi njêng kao si? Gâp mâu dơi, bi may dơi lĕ? Mbu nơm dơi njêng kao si? Knŏng Brah Ndu Nơm dơm dơi.\n\nVerse 2\nMbu nơm dơi sol ang nar? Gâp mâu dơi, bi may dơi lĕ? Mbu nơm dơi sol ang nar? Knŏng Brah Ndu Nơm dơm dơi.\n\nVerse 3\nMbu nơm dơi njêng tŭp mih? Gâp mâu dơi, bi may dơi lĕ? Mbu nơm dơi njêng tŭp mih? Knŏng Brah Ndu Nơm dơm dơi.\n\nVerse 4\nMbu nơm dơi njêng tơm n'ho? Gâp mâu dơi, bi may dơi lĕ? Mbu nơm dơi njêng tơm n'ho? Knŏng Brah Ndu Nơm dơm dơi.\n\nVerse 5\nMbu nơm dơi njêng kô-kim? Gâp mâu dơi, bi may dơi lĕ? Mbu nơm dơi njêng kô-kim? Knŏng Brah Ndu Nơm dơm dơi.\n\nVerse 6\nMbu nơm dơi njêng nuih n'hâm? Gâp mâu dơi, bi may dơi lĕ? Mbu nơm dơi njêng nuih n'hâm? Knŏng Brah Ndu Nơm dơm dơi.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0346", "title": "MBU NƠM RŎNG MA YÊ-SU", "song_number": "346", "lyrics": "MBU NƠM RŎNG MA YÊ-SU\n\n\nVerse 1\nMbu nơm rŏng ma Yê-su hăn tât ta Păng, mbu nơm rŏng ma Yê-su dơi rŏng ma Păng. Mbu nơm rŏng ma Yê-su dơi rŏng ma Păng. Păng mâu mâp mprơh bu ôh.\nYê-su Yê-su Păng blau bonh nuih n'hâm rngot Yê-su Yê-su Păng blau bonh nuih n'hâm rngot. Yê-su Yê-su Păng blau bonh nuih n'hâm rngot Păng ăn may kon me.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0347", "title": "MAY ŬCH GĬT LĔ", "song_number": "347", "lyrics": "MAY ŬCH GĬT LĔ\n\n\nVerse 1\nMay ŭch gĭt lĕ, mâm ƀư gâp rŏng Yê-su, rŏng Yê-su, rŏng Yê-su. May ŭch gĭt lĕ, mâm ƀư gâp rŏng Yê-su, gâp nkoch bri ma may pô aơ, yor Yê-su ƀư brah ma săk jăn Păng Tâm Rklaih gâp jêh. May ŭch gĭt lĕ, Mâm ƀư gâp rŏng Yê-su, Yê-su Krist khĭt tâm rgâl gâp.\n\nVerse 2\nMay ŭch gĭt lĕ, mâm ƀư gâp tĭng Yê-su, tĭng Yê-su, tĭng Yê-su. May ŭch gĭt lĕ, mâm ƀư gâp tĭng Yê-su, gâp nkoch bri ma may pô aơ, yor Yê-su ƀư brah ma săk jăn Păng Tâm Rklaih gâp jêh. May ŭch gĭt lĕ, Mâm ƀư gâp tĭng Yê-su, Yê-su Krist khĭt tâm rgâl gâp.\n\nVerse 3\nMay ŭch gĭt lĕ, mâm ƀư gâp rnê Yê-su, rnê Yê-su, rnê Yê-su. May ŭch gĭt lĕ, mâm ƀư gâp rnê Yê-su, gâp nkoch bri ma may pô aơ, yor Yê-su ƀư brah ma săk jăn Păng Tâm Rklaih gâp jêh. May ŭch gĭt lĕ, Mâm ƀư gâp rnê Yê-su, Yê-su Krist khĭt tâm rgâl gâp.\n\nVerse 4\nMay ŭch gĭt lĕ, mâm ƀư gâp tông Yê-su, tông Yê-su, tông Yê-su. May ŭch gĭt lĕ, mâm ƀư gâp tông Yê-su, gâp nkoch bri ma may pô aơ, yor Yê-su ƀư brah ma săk jăn Păng Tâm Rklaih gâp jêh. May ŭch gĭt lĕ, Mâm ƀư gâp tông Yê-su, Yê-su Krist khĭt tâm rgâl gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0348", "title": "Ơ YÊ-SU KƠL GÂP", "song_number": "348", "lyrics": "Ơ YÊ-SU KƠL GÂP\n\n\nVerse 1\nƠ Yê-su kơl gâp ăn nau ueh, nau gâp nti bơh nau May Ngơi. Chih tâm nuih n'hâm gâp gŭ ƀa-ƀơ. Lĕ nau ngăn gâp nti nar aơ.\nĂp nar gŭ êp gâp ăn nau ueh. Ăn gâp sĭt tâm rƀŭn ta aơ. Ơ Kôranh Brah mât uănh lĕ rngôch hên, tâm Amoh Nơm Tâm Rklaih A-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0349", "title": "TƠ LAH NAU RÊH HE", "song_number": "349", "lyrics": "TƠ LAH NAU RÊH HE\n\nTC 780, TVCHH 254\n\nVerse 1\nTơ lah nau rêh he bêng ma nau rŭng răng, nau klân rvê ntŭn jot roh lĕ nau maak. Lah he uănh ma bu ƀiă lah mâu rŏng ôh, lah he đing jêh ri roh lĕ nau chroh. Bơh abaơ ro ăn he mbơh lĕ ma Yê-su! Mbơh ma Păng lĕ nau tih tâm nuih n'hâm. Kôranh Brah Nơm ŭch tăng moh nau he vơl dăn, Păng yỗ ăn jêh ri lâm lĕ nau tih.\n\nVerse 2\nTơ lah he nkhah du ƀư tĭng he nơm ŭch, jêh ri gŭ kâp gân nar he mra khĭt. Tơ lah he mâu tông ma nau Brah Ndu Ngơi, chuat tĭng trong neh ntu tih mhĭk hâu ngăn. Bơh abaơ ro ăn he mbơh lĕ ma Yê-su! Nuih n'hâm he bêng ma nau tih djơh mhĭk. Kôranh Brah rŏng ma mbu nơm ŭch kuăl mbơh sơm, gĭt dêh rhêt rom Kôranh Brah ƀư Ha-đăch.\n\nVerse 3\nTơ lah may mâp âk nau rêh ni jêr jŏt, tơ lah nuih n'hâm may roh lĕ nau chroh. Tơ la may joi trong ŭch ƀư rklaih nau rêh, tơ lah tôr may tăng nau nti neh ntu. Bơh abaơ ro Yê-su yor ti gay djôt may! Păng kuăl may sĭt ma Păng rmal nau tih. Kôranh Brah Yê-su kăl-e yor may săk Păng, nkhŭt mham khlay rao kloh lĕ nau tih mhĭk.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0350", "title": "TOYH, TOYH NÂM BU DAK KRONG", "song_number": "350", "lyrics": "TOYH, TOYH NÂM BU DAK KRONG\n\n\nVerse 1\nToyh, toyh nâm bu dak krong. Prêh, prêh nâm bu ta kalơ trôk. Jru, jru nâm bu dak mƀŭt, nau Yê-su rŏng ma gâp. Gâp mâu jêng nơm khlay ôh, ăt Păng gŭ mât uănh ƀa-ƀơ. Ndrom sam ƀŭt Păng sâm nti gâp, nau rŏng tĭng gâp mbah ntŭk gâp hăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0351", "title": "DRUH NDĂM BRAH KRIST", "song_number": "351", "lyrics": "DRUH NDĂM BRAH KRIST\n\nTC 873\n\nVerse 1\nHe jêng phung druh ndăm Krist, hăn hom ma nau răm maak. Nđâp lah trong jêr jâk kđôi lĕ he mâu dơi plỡ ôh. Yê-su jêng Nơm he uănh lơi hôm tĭng nau rai yot, Maak hâu ngăn tơ lah Ê-li pơk ăn trong dak.\n\nChorus\nHăn hom phung druh ndăm tĭng ndỗ Yê-su, gŭ tâm Păng he geh âk nau ueh uĭn, nau Brah ktang Păng hŏ ăn jêh ma phung he, Ha-lê-lu-ya, Brah Krist njŭn leo he đăp mpăn.\n\nVerse 2\nHe jêng phung druh ndăm Krist, mâu geh klach nau jâk jêr. Nđâp lah trong brah mhĭk ndơm âk ntil nau jêr rŏ trong. Sŏk đao dau Kôranh Brah he hăn tâm lâh đah Sa-tan, Nâm bu Y-pôl kăl-e mâu klach đah phung rlăng.\n\nChorus\nHăn hom phung druh ndăm tĭng ndỗ Yê-su, gŭ tâm Păng he geh âk nau ueh uĭn, nau Brah ktang Păng hŏ ăn jêh ma phung he, Ha-lê-lu-ya, Brah Krist njŭn leo he đăp mpăn.\n\nVerse 3\nHe jêng phung druh ndăm Krist, nsing ma Păng tâm lĕ trong. Uănh nau Brah Ndu Ngơi, mbơh sơm ma Mbỡ he Nơm ueh. gay Păng njŭn he ƀa-ƀơ chuat hăn tâm trong ta klơ, H'Rut, Đa-vit, Ê-tiên gay ntĭt ăn ma he.\n\nChorus\nHăn hom phung druh ndăm tĭng ndỗ Yê-su, gŭ tâm Păng he geh âk nau ueh uĭn, nau Brah ktang Păng hŏ ăn jêh ma phung he, Ha-lê-lu-ya, Brah Krist njŭn leo he đăp mpăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0352", "title": "BRAH NDU GĬT TRONG RGĂN NTŬK BRI RDAH", "song_number": "352", "lyrics": "BRAH NDU GĬT TRONG RGĂN NTŬK BRI RDAH\n\n\nVerse 1\nBrah Ndu gĭt trong hăn rgăn tâm ntŭk bri rdah. Knŏng Păng ŭch gâp tĭng ndỗ ndrel Păng, Brah... Ndrel Păng. Păng ăn nau ktang ma ăp phung tĭng ndỗ jêh ri moh ndơ gâp ŭch ôi taơ, Brah Ndu gĭt lĕ trong rgăn tâm ntŭk bri rdah. Knŏng Păng ŭch gâp tĭng ndỗ ndrel Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0353", "title": "MAAK NGĂN! MAAK NGĂN!", "song_number": "353", "lyrics": "MAAK NGĂN! MAAK NGĂN!\n\n\nVerse 1\nMaak ngăn! maak ngăn! maak ngăn! Tâm lĕ trong gâp hăn, maak ngăn mbu nơm tâm rklaih ma lĕ nau rêh gâp. Kôranh Brah rklaih jêh gâp mâm gâp hôm geh nau rngot. Gâp mra lăp tâm Ƀon Ueh Brah Ndu klơ maak ngăn!\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0354", "title": "MAAK HOM", "song_number": "354", "lyrics": "MAAK HOM\n\n\nVerse 1\nMaak hom! maak hom! Kay-lŏng he mprơ maak hom! maak hom! tâm rnê Brah Ndu. Yê-su rŏng âk ngăn he gĭt, maak hom he ma yor Păng rŏng, Yê-su rŏng he gĭt jêh. Pô ri mprơ tâm rnê ma Păng. Yê-su rŏng âk ngăn he gĭt. Maak hom yor ma Păng rŏng âk. Maak yor Păng rŏng âk.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0355", "title": "AƠ NAU GÂP ŬCH", "song_number": "355", "lyrics": "AƠ NAU GÂP ŬCH\n\n\nVerse 1\nAơ nau gâp ŭch jêng nâm bu Yê-su, aơ nau gâp ŭch jêng nâm bu Yê-su, Brah Huêng Ueh mbêng gâp, Nau rŏng Păng rmeh ler tâm lĕ kan gâp jêng nâm bu Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0356", "title": "NDÂK NGIH ĂP NAR", "song_number": "356", "lyrics": "NDÂK NGIH ĂP NAR\n\n\nVerse 1\nHên jêng phung druh ndăm ndâk ngih. Dôl hên pah kan jêh ri pâl. Hên mâu joi pâng me nôp ôh. Mâu dŏng ndruih dơi ot si ôh. Ngih hên gŭ ndâk mâu yor đah ti. Dôl hên tĭng ndỗ nau Brah Ndu Ngơi. Hên jêng phung druh ndăm ndâk ngih. Hên gŭ ndâk ăp rnôk n'ho ro.\n\nVerse 2\nPhung hên gŭ ndâk ngih ăp nar. Ma lŭ hên n'gân jêng kan ueh. Yê-su jêng Nơm ƀư rjăp hên. Ndâk ta Păng Nơm jêng nau ueh. Geh âk ngăn ngih rlâm lĕ tâm dâng. Ndâk ta neh choih nau tih djơh mhĭk. Nau Păng Ngơi hên nti djôt prăp. Knŏng Păng yơh jêng rplay lŭ klêr.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0357", "title": "DRUH NDĂM MPRƠ RĂM MAAK", "song_number": "357", "lyrics": "DRUH NDĂM MPRƠ RĂM MAAK\n\nTC 878\n\nVerse 1\nƠ druh ndăm mprơ hom ma nuih n'hâm răm maak. Răm rhơn ngăn gâp geh Yê-su Kon Brah Ndu. Nuih n'hâm he bêng nau chrêk rmah klơ bơh ri, bêng ma nau răm maak.\n\nChorus\nPhung druh ndăm ueh nâm kao si. Phung druh ndăm ang tâm ban mănh. Nâm bu klang ƀŭng lŭh năr mpăr hăn lam neh ntu. Phung druh ndăm ueh nâm nau mprơ. Nâm bu sail khôm dôl ơm ôi. Nh'hơr hom nuih n'hâm, săk jăn ma Yê-su, tât lôch nau rêh.\n\nVerse 2\nƠ druh ndăm he jêng nâm bu kao si ueh. Ŭch nkoch nau mhe mhan ueh ma lĕ rngôch bunuyh. Yê-su yơh Nơm ndrŏng ma nau rŏng toyh lơn, răm maak mâu dŭt ôh.\n\nChorus\nPhung druh ndăm ueh nâm kao si. Phung druh ndăm ang tâm ban mănh. Nâm bu klang ƀŭng lŭh năr mpăr hăn lam neh ntu. Phung druh ndăm ueh nâm nau mprơ. Nâm bu sail khôm dôl ơm ôi. Nh'hơr hom nuih n'hâm, săk jăn ma Yê-su, tât lôch nau rêh.\n\nVerse 3\nƠ druh ndăm mprơ hom gŭ rêh maak ƀa-ƀơ. Kăn dỡ he mra dơn nau nkhôm bơh Brah Ndu. Hăn hom he du nuih n'hâm njêng phung tâm kơl, răm maak rêh n'ho ro.\n\nChorus\nPhung druh ndăm ueh nâm kao si. Phung druh ndăm ang tâm ban mănh. Nâm bu klang ƀŭng lŭh năr mpăr hăn lam neh ntu. Phung druh ndăm ueh nâm nau mprơ. Nâm bu sail khôm dôl ơm ôi. Nh'hơr hom nuih n'hâm, săk jăn ma Yê-su, tât lôch nau rêh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0358", "title": "GĬT YÊ-SU, MBƠH AMOH PĂNG", "song_number": "358", "lyrics": "GĬT YÊ-SU, MBƠH AMOH PĂNG\n\nTC 841\n\nVerse 1\nRŏng Yê-su jao nau rêh ma Păng. Rŏng Yê-su, rêh ma Păng ƀa-ƀơ. He srôih hăn! Mbơh A-moh Yê-su. Gĭt Yê-su, rêh ma Păng, rŏng ma Păng.\nNau rŏng Yê-su mâu geh dơi tâm ntĭt. Păng rŏng he, Păng khĭt trok he. He srôih hăn! Mbơh A-moh Yê-su, gĭt Yê-su rêh ma Păng, rŏng ma Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0359", "title": "TI BRAH KING N'GANG GÂP", "song_number": "359", "lyrics": "TI BRAH KING N'GANG GÂP\n\nTC 278\n\nVerse 1\nĐăp mpăn ueh maak ngăn ntŭk gâp du krap. Nau rêh ni roh nau rŭng răng du jêh. Ơ Yê-su gâp geh nau răm maak ngăn! Ti Brah Păng yơh chiă mât gâp ƀa-ƀơ.\n\nChorus\nGâp maak ngăn gŭ rlu tâm ntŭk đăp mpăn! Gâp tâm Yê-su Păng nkhŭt âk nau ueh lăng, ăp nar Păng yơh bonh leng nkŭm ăn huêng gâp. Ti Brah Păng mât chiă uănh gâp đăp mpăn.\n\nVerse 2\nGâp văch ma Păng jao lĕ nau klân rvê. Nau Ngơi Păng bonh ƀư n'hao nuih n'hâm gâp. Ƀư mhe nuih n'hâm gâp ma ti Brah Păng. A-ƀaơ Păng njŭn leo ăp nhuat gâp hăn.\n\nChorus\nGâp maak ngăn gŭ rlu tâm ntŭk đăp mpăn! Gâp tâm Yê-su Păng nkhŭt âk nau ueh lăng, ăp nar Păng yơh bonh leng nkŭm ăn huêng gâp. Ti Brah Păng mât chiă uănh gâp đăp mpăn.\n\nVerse 3\nNđâp lah sa-tan nter ktang ƀư klach gâp. Mâu dơi ƀư ôh ntŭk gâp gŭ đăp mpăn. Nđâp âk nau mhĭk gâp gŭ rjăp ƀa-ƀơ. Đăp mpăn ngăn ngên tâm ti Brah Yê-su.\n\nChorus\nGâp maak ngăn gŭ rlu tâm ntŭk đăp mpăn! Gâp tâm Yê-su Păng nkhŭt âk nau ueh lăng, ăp nar Păng yơh bonh leng nkŭm ăn huêng gâp. Ti Brah Păng mât chiă uănh gâp đăp mpăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0360", "title": "ĂN LĔ RNGÔCH CHON KÔ-MÂK", "song_number": "360", "lyrics": "ĂN LĔ RNGÔCH CHON KÔ-MÂK\n\n\nVerse 1\nAƀaơ ri ăn lĕ rngôch chon mon, Păng mbah ma Nơm Tâm Rklaih. N'hêl nễ Păng hŏ tât măng aơ, Păng jêng Brah Krist Mê-si.\n\nVerse 2\nJao hom nuih n'hâm he ma Păng. Jêh ri tông bâr ma Păng. Nơm jêng Hađăch ma he n'ho ro, bu deh tâm ntŭk o ach.\n\nVerse 3\nRăm maak hom he bơh nar aơ. Păng dơm jêng rmăk ueh he. Nơm njŭn he tât ntŭk ueh maak, He mâu mra pưt ndơ ôh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0361", "title": "AMOH CHRÊK RMAH", "song_number": "361", "lyrics": "AMOH CHRÊK RMAH\n\n\nVerse 1\nMât ton tâm rnê Amoh Nơm tâm rklaih, yor lah Păng jêng Nơm blau yỗ. Amoh Păng khư yơk tâm lĕ rngôch rnôk, yor Amoh Păng bêng ma nau Brah.\n\nChorus\nAmoh Yê-su khlay ngăn, khlay ngăn. Amoh Yê-su khlay ngăn, khlay ngăn. A-moh nau chrêk rmah Yê-su. Amoh Yê-su khlay ngăn, khlay ngăn. Amoh Yê-su khlay ngăn, khlay ngăn. A-moh nau chrêk rmah Yê-su.\n\nVerse 2\nYê-su jêng Hađăch, Kôranh ma lĕ rngôch, Păng jêng nau ang tâm rnôk aơ. Nteh hom bâr mprơ tâm rnê Amoh Păng, phung tông mpăr ueh tâm klơ trôk.\n\nChorus\nAmoh Yê-su khlay ngăn, khlay ngăn. Amoh Yê-su khlay ngăn, khlay ngăn. A-moh nau chrêk rmah Yê-su. Amoh Yê-su khlay ngăn, khlay ngăn. Amoh Yê-su khlay ngăn, khlay ngăn. A-moh nau chrêk rmah Yê-su.\n\nVerse 3\nPăng lơi Ƀon Ueh chrêk rmah klơ trôk, dơn nau khĭt ta si tâm rkăng. Ntok lĕ rngôch bunuyh bơh nau khĭt ôm, ŭch tâm rgâl lĕ bunuyh tih mhĭk.\n\nChorus\nAmoh Yê-su khlay ngăn, khlay ngăn. Amoh Yê-su khlay ngăn, khlay ngăn. A-moh nau chrêk rmah Yê-su. Amoh Yê-su khlay ngăn, khlay ngăn. Amoh Yê-su khlay ngăn, khlay ngăn. A-moh nau chrêk rmah Yê-su.\n\nVerse 4\nAmoh Păng khlay ngăn ma lĕ rngôch Amoh, geh nau tâm rnê ta neh ntu. Kơl gâp dơi ƀư chrêk rmah Amoh May, jêh ri ăn gâp geh nau rŏng.\n\nChorus\nAmoh Yê-su khlay ngăn, khlay ngăn. Amoh Yê-su khlay ngăn, khlay ngăn. A-moh nau chrêk rmah Yê-su. Amoh Yê-su khlay ngăn, khlay ngăn. Amoh Yê-su khlay ngăn, khlay ngăn. A-moh nau chrêk rmah Yê-su.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0362", "title": "DĂN BRAH NDU MBỠ", "song_number": "362", "lyrics": "DĂN BRAH NDU MBỠ\n\n\nVerse 1\nDăn Brah Ndu Mbỡ Nơm rŏng nkŭm nuih n'hâm, ma nau rŏng mâu geh rgâl ôh. Jut lĕ dăk măt gâp ƀư bah nau rngot nuih n'hâm. Nhhơr ma Kôranh Brah lĕ rngôch nau gâp ŭch, dăn Brah Huêng Ueh gŭ tâm gâp. Chiă uănh njŭn leo gâp tâm ntŭk nau ueh đăp mpăn.\n\nChorus\nYê-su! Brah Yê-su! Gâp nhhơr lĕ nau rêh ma May! Yê-su! Dăn May lăp gŭ tâm nuih n'hâm gâp.\n\nVerse 2\nNhhơr hom ma Kôranh Brah nau mprơ tâm rnê, nau răm maak bêng tâm nuih n'hâm. Mât ton Mbỡ nau rŏng nhhơr ma Păng lĕ nau rêh. Jao ma Kôranh Brah lĕ nau jêr ăp nar, huêng srĭng he jêh ri nau rngot. Sŏk dơn nau rêh mhe Păng ăn tâm Amoh Yê-su.\n\nChorus\nYê-su! Brah Yê-su! Gâp nhhơr lĕ nau rêh ma May! Yê-su! Dăn May lăp gŭ tâm nuih n'hâm gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0363", "title": "NAU MPRƠ ƠM 19:7-10", "song_number": "363", "lyrics": "NAU MPRƠ ƠM 19:7-10\n\n\nVerse 1\nNau vay Yê-hô-va jêng ngăn. Păng ăn dâk rêh huêng\nNau Yê-hô-va mbơh jêng nanễ. Păng ăn blau phung rluk.\nBu ŭch ma khân păng âk lơn prăk maih âk lơn ma prăk maih... Nau Ngơi Păng njŭng lơn dak sŭt dak sŭt trŭh tă bơh mpơng.\n\nVerse 2\nNau Yê-hô-va ngơi jêng sŏng. Păng ƀư maak nuih n'hâm.\nNau Yê-hô-va ntĭnh jêng kloh, Păng ƀư ang măt bu.\nBu ŭch ma khân păng âk lơn prăk maih âk lơn ma prăk maih... Nau Ngơi Păng njŭng lơn dak sŭt dak sŭt trŭh tă bơh mpơng.\n\nVerse 3\nNau klach yơk Kôranh Brah jêng kloh. Gŭ ƀa-ƀơ n'ho ro.\nNau Yê-hô-va ntĭnh jêng nanễ. Jêh ri di da-dê.\nBu ŭch ma khân păng âk lơn prăk maih âk lơn ma prăk maih... Nau Ngơi Păng njŭng lơn dak sŭt dak sŭt trŭh tă bơh mpơng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0364", "title": "Ơ KÔRANH BRAH", "song_number": "364", "lyrics": "Ơ KÔRANH BRAH\n\n\nVerse 1\nƠ Kôranh Brah! Gâp ŭch jêng kon May tâm nuih n'hâm, nuih n'hâm gâp. Ơ Kôranh Brah! Gâp ŭch jêng kon May tâm nuih n'hâm.\n\nChorus\nTâm nuih n'hâm gâp! Tâm nuih n'hâm gâp! Ơ Kôranh Brah! Gâp ŭch jêng kon May tâm nuih n'hâm.\n\nVerse 2\nƠ Kôranh Brah! Gâp ŭch jêng kloh ueh tâm nuih n'hâm, nuih n'hâm gâp. Ơ Kôranh Brah! Gâp ŭch jêng kloh ueh tâm nuih n'hâm.\n\nChorus\nTâm nuih n'hâm gâp! Tâm nuih n'hâm gâp! Ơ Kôranh Brah! Gâp ŭch jêng kon May tâm nuih n'hâm.\n\nVerse 3\nƠ Kôranh Brah! Gâp ŭch jêng kon me tâm nuih n'hâm, nuih n'hâm gâp. Ơ Kôranh Brah! Gâp ŭch jêng kon me tâm nuih n'hâm.\n\nChorus\nTâm nuih n'hâm gâp! Tâm nuih n'hâm gâp! Ơ Kôranh Brah! Gâp ŭch jêng kon May tâm nuih n'hâm.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0365", "title": "HE MRA SAƠ", "song_number": "365", "lyrics": "HE MRA SAƠ\n\n\nVerse 1\nHe mra saơ muh măt Păng ueh, bơh ơm ôi, nchrat nâm maih lah ndâr ntŭk kloh lơ vơ n'hâm ndâr tŭk aih ƀhiau. Nau r-ngot mra rgâl jêng maak nuih n'hâm ji bah jêh, mâu hôm geh ngo saơ ang dơm, lah saơ muh măt Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0366", "title": "NKAH MA NAU GŬ NDREL JÊH", "song_number": "366", "lyrics": "NKAH MA NAU GŬ NDREL JÊH\n\n\nVerse 1\nOh nâu oh nur he nkah ôi ma ngih nti măng ma ngih biăp. Sĭt ndrel n'grŭp n'hanh tâm êp tâm rnglăp tâm nau rŏng Brah Yê-su.\n\nChorus\nNkah hom oh nâu oh nur lor tâm nkhah he. Tâm rgu hom ti. Khay nti lĕ jêh ăp nơm du sĭt. Kôranh Brah mra hăn ndrel n'grŭp.\n\nVerse 2\nOh nâu oh nur he nkah ôi ma ngih dak n'ho ma ngih sông. Pah kan dêh rhêt dơn nau nti tâm ntĭt nau rêh mhe yơk mbah.\n\nChorus\nNkah hom oh nâu oh nur lor tâm nkhah he. Tâm rgu hom ti. Khay nti lĕ jêh ăp nơm du sĭt. Kôranh Brah mra hăn ndrel n'grŭp.\n\nVerse 3\nOh nâu oh nur he nkah ôi taơ m'haơ măng gŭ nti tât ngo. Măt uănh kah gĭt tôr rkêng n'hêl nễ ŭch ma lăp nau gĭt rbăng.\n\nChorus\nNkah hom oh nâu oh nur lor tâm nkhah he. Tâm rgu hom ti. Khay nti lĕ jêh ăp nơm du sĭt. Kôranh Brah mra hăn ndrel n'grŭp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0367", "title": "SOL HOM GƠNH OI", "song_number": "367", "lyrics": "SOL HOM GƠNH OI\n\nTC 356\n\nVerse 1\nRi, uănh hom tâm ntŭk dak jru nđông mpưp âk huêng ŭnh Brah nây. Sol gơnh oi! Mâm he dĭng mâu chrê ma Nơm ôp kuăl păng nây, sol ăn ang.\n\nChorus\nSol lĕ puăn njônh. Sol hom gơnh Ăn bunuyh saơ nau yỗ toyh, Sol ăn gơnh Ma bunuyh tâm ntŭk ngo klĕng! Khân păng nter Tâm dak mƀŭt toyh blưi blưi, gŭ kâp he. Nhhơr prêh ka-lơ\n\nVerse 2\nNar aơ hôm rmưn rsen bunuyh gŭ kâp nau mhe ngăn, ŭnh Brah nây. Sol gơnh oi! Hăn joi hom khân păng lơi hôm ding njong ir nar, sol ăn ang.\n\nChorus\nSol lĕ puăn njônh. Sol hom gơnh Ăn bunuyh saơ nau yỗ toyh, Sol ăn gơnh Ma bunuyh tâm ntŭk ngo klĕng! Khân păng nter Tâm dak mƀŭt toyh blưi blưi, gŭ kâp he. Nhhơr prêh ka-lơ\n\nVerse 3\nYê-su đă he iăt hom nau mhe mhan ueh Păng, ŭnh Brah nây. Sol gơnh oi! He hŏ geh nau tâm chuai mâm dun nau Krist ntĭnh, sol ăn ang.\n\nChorus\nSol lĕ puăn njônh. Sol hom gơnh Ăn bunuyh saơ nau yỗ toyh, Sol ăn gơnh Ma bunuyh tâm ntŭk ngo klĕng! Khân păng nter Tâm dak mƀŭt toyh blưi blưi, gŭ kâp he. Nhhơr prêh ka-lơ\n\nVerse 4\nĂn he hăn mbơh ma Amoh Brah Yê-su ta klơ, ŭnh Brah nây. Sol gơnh oi! Mbơh nti nau rŏng gay tâm rklaih âk rbăn bu-nuyh, sol ăn ang.\n\nChorus\nSol lĕ puăn njônh. Sol hom gơnh Ăn bunuyh saơ nau yỗ toyh, Sol ăn gơnh Ma bunuyh tâm ntŭk ngo klĕng! Khân păng nter Tâm dak mƀŭt toyh blưi blưi, gŭ kâp he. Nhhơr prêh ka-lơ\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0368", "title": "MAAK YƠH TÂM NKOL", "song_number": "368", "lyrics": "MAAK YƠH TÂM NKOL\n\nTC 502\n\nVerse 1\nMaak yơh tâm nkol nau Brah Ndu Nơm tâm rnglăp. Tâm n'gar Ê-đen, tăng Brah Ndu nti n'hêl jêh. Maak yơh tâm nkol ma ur sai Brah Ndu rnglăp. Mprơ hom mât ton ma druh ma ndăm gŭ tâm nau kloh.\n\nChorus\nMaak kloh ueh, maak răm yơh. Maak yơh Brah Ndu tâm rnglăp. Sông sa ƀư maak ma ur sai mhe nơm Brah Ndu nđăp.\nA-men.\n\nVerse 2\nBar hê dơn kông nkol ta năp măt Brah Ndu. Nau rŏng toyh ngăn, prêh rlau yôk jru nâm dak. Bar hê dơn kông nkol ta năp măt Brah Ndu. Jao lĕ nau rêh bar hê tâm rŏng ƀa-ƀơ n'ho-ro.\n\nChorus\nMaak kloh ueh, maak răm yơh. Maak yơh Brah Ndu tâm rnglăp. Sông sa ƀư maak ma ur sai mhe nơm Brah Ndu nđăp.\nA-men.\n\nVerse 3\nNau rŏng prêh lơn nâm bu trôk prêh klơ ri. Dăn Brah Ndu Mbỡ, nkhŭt nau rh ma khân păng. Nau rŏng răp-jăp sŏk dơn nau Brah Ndu yỗ. Bar hê ur sai mhe geh nau rŏng tât lôch nau rêh.\n\nChorus\nMaak kloh ueh, maak răm yơh. Maak yơh Brah Ndu tâm rnglăp. Sông sa ƀư maak ma ur sai mhe nơm Brah Ndu nđăp.\nA-men.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0369", "title": "MPRƠ HOM DÔL NAR NCHRAT ANG", "song_number": "369", "lyrics": "MPRƠ HOM DÔL NAR NCHRAT ANG\n\n\nVerse 1\nMprơ hom dôl nar nchrat ang mprơ hom ta klong măng ngo ăn ăp nar. Tâm lĕ trong, kay he mprơ mprơ mprơ! mprơ hom dôl nar nchrat ang. Mprơ hom ta klong măng ngo ăn ăp nar. Tâm lĕ trong, kay he mprơ mprơ mprơ!\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0370", "title": "LAH GÂP SAƠ MHAM PĂNG", "song_number": "370", "lyrics": "LAH GÂP SAƠ MHAM PĂNG\n\n\nVerse 1\nKrist Nơm tâm rklaih he, khĭt yor nuyh tih, ta si-tâm rkăng ntrok lĕ rnon tih he. Rao nuih n'hâm tâm mham Kon Ƀiăp Brah Ndu.\n\nChorus\nGâp ŭch hăn tât, hăn hao tât ma Păng. Lah gâp saơ mham Păng. Lah gâp saơ mham Păng. Lah gâp saơ mham Păng. Gâp ŭch hao gâp ŭch hao tât ma Păng.\n\nVerse 2\nBu-nuyh tih mhĭk ngăn, Yê-su tâm rklaih, lĕ nau Păng ton jêh Păng ƀư ngăn ngên. Păm tâm mham khlay Păng nkhŭt yor tih he.\n\nChorus\nGâp ŭch hăn tât, hăn hao tât ma Păng. Lah gâp saơ mham Păng. Lah gâp saơ mham Păng. Lah gâp saơ mham Păng. Gâp ŭch hao gâp ŭch hao tât ma Păng.\n\nVerse 3\nTât nar Păng phat dôih, lĕ rngôch nuyh tih, ăp nơm dơn nau tâm rnê tĭng nâm kan. Păng ntrok ma mham khlay ƀư kloh nau tih.\n\nChorus\nGâp ŭch hăn tât, hăn hao tât ma Păng. Lah gâp saơ mham Păng. Lah gâp saơ mham Păng. Lah gâp saơ mham Păng. Gâp ŭch hao gâp ŭch hao tât ma Păng.\n\nVerse 4\nƠ nau yỗ toyh ngăn, nau rŏng khlay ngăn, ơ nau ueh maak răm rhơn hâu ngăn ngên. Sŏk dơn nau đăp mpăn tâm mham khlay Păng.\n\nChorus\nGâp ŭch hăn tât, hăn hao tât ma Păng. Lah gâp saơ mham Păng. Lah gâp saơ mham Păng. Lah gâp saơ mham Păng. Gâp ŭch hao gâp ŭch hao tât ma Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0371", "title": "TÔNG MPĂR UEH HŎ RLĂ JÊH LŬ", "song_number": "371", "lyrics": "TÔNG MPĂR UEH HŎ RLĂ JÊH LŬ\n\n\nVerse 1\nTông mpăr Ueh hŏ rlă jêh lŭ, mpôch khĭt mâu dơi ôh đah Păng. Uănh hom Kôranh Brah luh jêh bơh môch, Păng rêh chrêk ma lơp ƀa-ƀơ. Păng rêh chrêk ma lơp ƀa-ƀơ.\n\nVerse 2\nPhung bunuyh n'gơr măt uănh klơ trôk, uănh Kôranh Branh lŏ dâk rêh nây. Tâm nau mprơ tâm rnê Brah Ndu hên gŭ kâp gân Ƀon Ueh tâm trôk. Hên gŭ kâp Ƀon Ueh tâm trôk.\n\nVerse 3\nMpông sâng tâm Ƀon Ueh pơk jêh, rom dơi nơm đah nau tâm lơh. Păng lăp gŭ klơ sưng Ha-đăch, Păng Nơm mât mơh ƀa-ƀơ n'ho ro. Păng Nơm mât mơh ƀaƀơ n'ho ro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0372", "title": "MAAK TÂM KÔRANH BRAH", "song_number": "372", "lyrics": "MAAK TÂM KÔRANH BRAH\n\nTVCHH 183\n\nVerse 1\nMaak tâm Kôranh Brah yor geh Păng njŭn leo. Nđâp sail phŭt ktang đỗ gâp ngai bơh Brah Ndu Mbỡ. Păng ăt ntĭm trong njŭn gâp rgăn âk bơh nau jêr. Ƀư n'hao nuih gâp tâm nau rŏng Kôranh Brah.\n\nChorus\nNâm nar sĭm mpăr klơ trôk, geh nau hâk maak hâu ngăn, lĕ rngôch ndơ jêng bơh Brah Ndu Nơm. Nau ueh maak toyh rmeh ler Păng lŏ ăn âk rlau lơn nau rŏng Kôranh Brah toyh jru ngăn.\n\nVerse 2\nMaak tâm Kôranh Brah yor geh Păng chiă mât. Păng ăt uănh ndjôt phung kon biăp rêh ni ji kuet. Âk khay năm rlau Păng ăn nau rêh ueh đăp mpăn. Gâp maak ƀa ƀơ tâm nau rŏng Kôranh Brah.\n\nChorus\nNâm nar sĭm mpăr klơ trôk, geh nau hâk maak hâu ngăn, lĕ rngôch ndơ jêng bơh Brah Ndu Nơm. Nau ueh maak toyh rmeh ler Păng lŏ ăn âk rlau lơn nau rŏng Kôranh Brah toyh jru ngăn.\n\nVerse 3\nMaak tâm Kôranh Brah yor Păng ăt chiă mât. Nau rêh o ach gâp maak tâm nau rêh Brah Ndu. Ăp nar măng Kôranh Brah mât siăm nâm bu sĭm jễ. Nau chroh jru toyh tâm nau rŏng Kôranh Brah.\n\nChorus\nNâm nar sĭm mpăr klơ trôk, geh nau hâk maak hâu ngăn, lĕ rngôch ndơ jêng bơh Brah Ndu Nơm. Nau ueh maak toyh rmeh ler Păng lŏ ăn âk rlau lơn nau rŏng Kôranh Brah toyh jru ngăn.\n\nVerse 4\nMaak tâm Kôranh Brah yor geh Păng king gâp. Nđâp tâm nau rêh geh âk ntil tât nau rlong uănh. Nuih n'hâm đăp mpăn huêng ueh uĭn mât ton Kôranh Brah. Dơi đah nau jêr tâm r'nê Kôranh Brah Nơm.\n\nChorus\nNâm nar sĭm mpăr klơ trôk, geh nau hâk maak hâu ngăn, lĕ rngôch ndơ jêng bơh Brah Ndu Nơm. Nau ueh maak toyh rmeh ler Păng lŏ ăn âk rlau lơn nau rŏng Kôranh Brah toyh jru ngăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0373", "title": "LĂP TÂM NUIH N'HÂM GÂP", "song_number": "373", "lyrics": "LĂP TÂM NUIH N'HÂM GÂP\n\nTC 449\n\nVerse 1\nLăp tâm nuih n'hâm, lăp tâm nuih n'hâm. Lăp tâm nuih n'hâm gâp Brah Yê-su Lăp hom nar aơ, lăp gŭ ƀa-ƀơ, lăp tâm nuih n'hâm gâp Brah Yê-su.\n\nVerse 2\nLĕ nuih n'hâm gâp, lĕ nuih n'hâm gâp. Sŏk lĕ nuih n'hâm gâp Brah Yê-su Sŏk lĕ nar aơ, sŏk lĕ săk jăn, sŏk lĕ nau rêh gâp Brah Yê-su.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0374", "title": "PĂNG ĂT CHIĂ UĂNH", "song_number": "374", "lyrics": "PĂNG ĂT CHIĂ UĂNH\n\n\nVerse 1\nGâp chroh ma Păng nđâp geh mâp âk nau jêr. Tâm ntŭk đăp mpăn, mâu lah tâm dak rlai jru. Gâp rêh ăp nar, ma Păng gâp nsing. Mbỡ gâp tâm trôk ăt chiă uănh gâp ƀa-ƀơ.\n\nChorus\nGâp ŭch chroh ngăn, Kôranh Brah hăn ndrel ma gâp. Ta klơ yôk yang mâu lah tâm dak mƀŭt jru. Geh Kôranh Brah Nơm mra njŭn leo gâp, Mbỡ gâp tâm trôk ăt chiă uănh gâp ƀa-ƀơ.\n\nVerse 2\nMbỡ he tâm trôk chiă mât âk nkao si ueh. Păng ăt njŭn trong, he nâm bu phung sĭm jễ. Gâp chroh ma Păng, nkah yỗ ma gâp. Mbỡ gâp tâm trôk ăt chiă uănh gâp ƀa-ƀơ.\n\nChorus\nGâp ŭch chroh ngăn, Kôranh Brah hăn ndrel ma gâp. Ta klơ yôk yang mâu lah tâm dak mƀŭt jru. Geh Kôranh Brah Nơm mra njŭn leo gâp, Mbỡ gâp tâm trôk ăt chiă uănh gâp ƀa-ƀơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0375", "title": "ĐĂP MPĂN", "song_number": "375", "lyrics": "ĐĂP MPĂN\n\n\nVerse 1\nDăn mpôn kon tâm mpang ti Mbỡ. Nkrum ra-u kon tâm gui huêng Brah nau dơi. Nđâp phŭt sial krit kir vănh blông ndăch chueng. Dăn Kôranh Brah têk ndrêng rgăn nau rlong uănh. Ơ Kôranh Brah chrêk rmah Brah ma lĕ rngôch Brah. Kon mro đăp mpăn yor Kôranh Brah gŭ ndrel.\n\nVerse 2\nKon mro ŭch nsing tâm Yê-su. Nkrum ra-u kon tâm gui huêng Brah nau dơi. Nđâp phŭt sial krit kir vănh blông ndăch chueng. Dăn Kôranh Brah têk ndrêng rgăn nau rlong uănh. Ơ Kôranh Brah chrêk rmah Brah ma lĕ rngôch Brah. Kon mro đăp mpăn yor Kôranh Brah gŭ ndrel.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0376", "title": "LƠI RŬNG RĂNG, CHROH HOM", "song_number": "376", "lyrics": "LƠI RŬNG RĂNG, CHROH HOM\n\n\nVerse 1\nLơi may rŭng răng ôh, lơi hom nau rngot klâng. Jao hom nau jâk may ma Brah Yê-su. Nau maak mra tât ndal, nau ngo mra roh rai. Nau ang chrang gŭ jŭm, mprơh lĕ nau ngo. Nđâp neh ntu ngo klĕng, Lơi ta may rngot ôh. Kôranh Brah gŭ ndrel he, mâu pưt ndơ ôh. Nkah nau ton kăl-e, ê lor sĭt klơ trôk. Păng lah \"Lơi klach ôh, geh Gâp gŭ ndrel\"\n\nVerse 2\nUănh ma Nơm tâm rklaih, chroh hom ma Yê-su. Jao lĕ nau rêh may ma Păng ăp nar. Păng mâu gŭ ngai ôh, nđâp may mâu mâu saơ. Maak gŭ tâm Kôranh Brah, mprơ maak ăp nar. Păng ăn gŭ đăp mpăn. Nau rêh kloh, chrat ang. Yor chroh ma Yê-su, may gŭ tâm Păng. Lah mâp nau jêr-jok, mâu lah dôl klân rvê. May mra răm maak ngăn, geh Brah gŭ ndrel.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0377", "title": "NƠM TÂM CHUAI GÂP HÔM GŬ RÊH", "song_number": "377", "lyrics": "NƠM TÂM CHUAI GÂP HÔM GŬ RÊH\n\n\nVerse 1\nGâp gĭt Nơm Chuai gâp hôm e rêh, jêh ri Păng mbơh sơm ma gâp. Păng ăn nau mbên Păng đah nau rŏng, Păng ton ăn nau kon me.\n\nVerse 2\nPăng gay ăn gâp gŭ kloh ueh ngăn, ma Păng mâu geh ôh ndơ jêr. Ma nau rŏng Păng ƀư lĕ na-nễ nau Păng ntĭnh jêh ma gâp.\n\nVerse 3\nYê-su gâp nsing ma nau May Ngơi, gâp gŭ rjăp đah nau gâp chroh. May mra plỡ văch sŏk gâp Kôranh Brah, jêh ri sŏk dơn May Nơm.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0378", "title": "BRAH YÊ-SU PLỠ VĂCH", "song_number": "378", "lyrics": "BRAH YÊ-SU PLỠ VĂCH\n\n\nVerse 1\nHên leo djôt du nau khlay ngăn, hên mprơ du nau mprơ rnê nau mhe khlay ngăn bơh Ha-đăch trôk: Kôranh Brah Yê-su gơnh plỡ văch (plỡ văch)\n\nChorus\nYê-su bơi văch, Yê-su gơnh văch dăch kêng ơm ôi mâu lah măng, dăch kêng măng mâu lah a-ƀaơ ro. Yê-su gơnh văch Yê-su gơnh văch ô khlay ngăn, maak ngăn ngên nar nây mra tât! Kôranh Brah Yê-su bơi plỡ văch.\n\nVerse 2\nNđâp yôk, nđâp bri mra răm rhơn, nđâp kao tơm si mra mprơ maak. Neh ntu nđâp Ƀon Ueh mra kuăl: Kôranh Brah Yê-su gơnh plỡ văch (plỡ văch)\n\nChorus\nYê-su bơi văch, Yê-su gơnh văch dăch kêng ơm ôi mâu lah măng, dăch kêng măng mâu lah a-ƀaơ ro. Yê-su gơnh văch Yê-su gơnh văch ô khlay ngăn, maak ngăn ngên nar nây mra tât! Kôranh Brah Yê-su bơi plỡ văch.\n\nVerse 3\nNau gâp gŭ nsrâng pa năp Păng lĕ nau rngot he roh lĕ jêh. Sŏk dơn Ha-đăch ta jâng Păng: Kôranh Brah Yê-su gơnh plỡ văch (plỡ văch)\n\nChorus\nYê-su bơi văch, Yê-su gơnh văch dăch kêng ơm ôi mâu lah măng, dăch kêng măng mâu lah a-ƀaơ ro. Yê-su gơnh văch Yê-su gơnh văch ô khlay ngăn, maak ngăn ngên nar nây mra tât! Kôranh Brah Yê-su bơi plỡ văch.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0379", "title": "DĂN BRAH HUÊNG UEH TRŬNH", "song_number": "379", "lyrics": "DĂN BRAH HUÊNG UEH TRŬNH\n\n\nVerse 1\nBrah Huêng Ueh! dăn May trŭnh ma hên! Gay May ƀư rai lĕ nau tih mhĭk. a-ƀaơ ro, hơi Kôranh Brah văch gơnh oi. Hên gŭ kâp gân May tâm mpơl nau Brah.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0380", "title": "GÂP ŬCH TĬNG NDỖ NDREL MA YÊ-SU", "song_number": "380", "lyrics": "GÂP ŬCH TĬNG NDỖ NDREL MA YÊ-SU\n\n\nVerse 1\nGâp ŭch tĭng ndỗ ndrel ma Yê-su jêh ri Păng mât gâp ăp mông. Păng chuăt hăn ndrel ma gâp ăp nar. Kŏ tât gâp mra gŭ ta klơ, Păng dơi buay siăl vanh blông tât rngân, bunuyh ji kuet Păng blau ƀư bah. Păng hăn ta klơ dak, Păng jêng Kon Brah Ndu, Păng jêng Nơm gŭ ndrel ma gâp ƀa-ƀơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0381", "title": "NDROM SĂM-ƀŬT NAU BRAH NDU NGƠI", "song_number": "381", "lyrics": "NDROM SĂM-ƀŬT NAU BRAH NDU NGƠI\n\n\nVerse 1\nNdrom săm-ƀŭt Brah Ndu Ngơi jêng nau ueh lơn ma lĕ rngôch. Nau nkoch âk ngăn Păng bêng ma rup, geh nau mprơ tâm n'hao nuih. Păng nkoch nau rêh Yê-su Nơm gŭ ta ka-lơ yôk prêh. Nau Brah Ndu Ngơi ăn gâp gŭ kloh. Brah Ndu rŏng gâp.\n\nVerse 2\nNau Brah Ndu Ngơi geh âk săm-ƀŭt nau mhe ueh ma he. Nau Păng Ngơi lah nau Yê-su, jă lĕ kon se văch ma Păng. nau Păng Ngơi geh nti ueh, ăn he gĭt tâm rnê ma Păng. Ndrom săm-ƀŭt luh tă bơh Nơm rŏng ma he n'ho ro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0382", "title": "YÊ-SU GÂP ŬCH GŬ RJĂP NGĂN", "song_number": "382", "lyrics": "YÊ-SU GÂP ŬCH GŬ RJĂP NGĂN\n\n\nVerse 1\nYê-su gâp ŭch gŭ rjăp ngăn, ăn gâp nau Brah, ăn gâp nau Brah. Yê-su gâp ŭch hăn ndrel May. Ăp tỡ mông ndăch ăp tỡ mông ndăch.\n\nChorus\nTâm têl jâng May dơm jâng gâp. Tĭng nâm may ŭch, tĭng nâm May ŭch. Nđâp lah gâp mâp đah nau jêr, ăn ma gâp gŭ đăp mpăn.\n\nVerse 2\nYê-su gâp ŭch nkoch đah May, dôl hăn rŏ trong, dôl hăn rŏ trong. Răm rhơn saơ dôl May gơm rum. Ăp nar hâk răm, ăp nar hâk răm.\n\nChorus\nTâm têl jâng May dơm jâng gâp. Tĭng nâm may ŭch, tĭng nâm May ŭch. Nđâp lah gâp mâp đah nau jêr, ăn ma gâp gŭ đăp mpăn.\n\nVerse 3\nĂn ma gâp Kôranh nuih n'hâm rŏng, lăp gŭ tâm gâp, lăp gŭ tâm gâp. Ăn muh măt May Nơm Kôranh Brah. Rklaih bơh nau tih, rklaih bơh nau tih.\n\nChorus\nTâm têl jâng May dơm jâng gâp. Tĭng nâm may ŭch, tĭng nâm May ŭch. Nđâp lah gâp mâp đah nau jêr, ăn ma gâp gŭ đăp mpăn.\n\nVerse 4\nĂn kan gâp ăp nar mra jêng, tâm nau May ŭch, tâm nau May ŭch. Yê-su May dơm, May dơm yơh. mbêng ăn tâm gâp, mbêng ăn tâm gâp.\n\nChorus\nTâm têl jâng May dơm jâng gâp. Tĭng nâm may ŭch, tĭng nâm May ŭch. Nđâp lah gâp mâp đah nau jêr, ăn ma gâp gŭ đăp mpăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0383", "title": "NĔ AƠ, NĔ AƠ", "song_number": "383", "lyrics": "NĔ AƠ, NĔ AƠ\n\n\nVerse 1\nNĕ aơ, nĕ aơ, gâp dâk êp kêng meng mpông jêh ri goh, nĕ aơ, nĕ aơ. Gâp dâk êp kêng meng mpông jêh ri goh, lah geh du huê tăng bâr Gâp. Lah geh du huê tăng bâr Gâp, jêh ri pơk mpông, pơk mpông, pơk huy mpông, Gâp mra lăp ngih may.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0384", "title": "GÂP MÂP ƀƯ RNGOT ĐŎNG BRAH HUÊNG UEH?", "song_number": "384", "lyrics": "GÂP MÂP ƀƯ RNGOT ĐŎNG BRAH HUÊNG UEH?\n\n\nVerse 1\nGâp mâp ƀư rngot lĕ Brah Huêng Ueh? Gâp mâp buay lĕ nau Brah Păng? Lah geh mâp ơ Yê-su, yỗ ăn. Ƀư kloh gâp bơh lĕ nau tih.\n\nChorus\nGâp vơh vơl May, ơ Nơm Tâm Rklaih, văch nôk dôl gâp gŭ vơh vơl May. iăt hom gâp mbơh nau tih ma May. Yỗ an ƀư kloh, mbêng hom gâp.\n\nVerse 2\nGâp geh pưt lĕ nau yỗ Păng ăn? Gâp mâp leo lĕ bunuyh ma Păng? Mâm ƀư nau gâp nti mâu khlay ƀơh? Ăn nau Brah ƀư rai nau tih.\n\nChorus\nGâp vơh vơl May, ơ Nơm Tâm Rklaih, văch nôk dôl gâp gŭ vơh vơl May. iăt hom gâp mbơh nau tih ma May. Yỗ an ƀư kloh, mbêng hom gâp.\n\nVerse 3\nGâp mâp tŭp lĕ ma yor nau ndơm? Roh ƀơh nau Brah rdâng nau tih? Lah gâp rom ăn nau mhĭk ndơm lăp. Di lĕ gâp mprơh Brah Huêng Ueh?\n\nChorus\nGâp vơh vơl May, ơ Nơm Tâm Rklaih, văch nôk dôl gâp gŭ vơh vơl May. iăt hom gâp mbơh nau tih ma May. Yỗ an ƀư kloh, mbêng hom gâp.\n\nVerse 4\nKôranh Brah, gâp văch rmal nau tih gâp, Nhhơr lĕ nau rêh gâp ma May. Njêng gâp a-ƀơ ăn jêng ndơ May. Ndơ May ƀa-ƀơ ngăn n'ho ro.\n\nChorus\nGâp vơh vơl May, ơ Nơm Tâm Rklaih, văch nôk dôl gâp gŭ vơh vơl May. iăt hom gâp mbơh nau tih ma May. Yỗ an ƀư kloh, mbêng hom gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0385", "title": "NAU NGƠI KHLAY HÂU NGĂN", "song_number": "385", "lyrics": "NAU NGƠI KHLAY HÂU NGĂN\n\n\nVerse 1\nNau ngơi aơ khlay hâu ngăn ngên, Yê su lah jŏ năm jêh. Ƀiă lah dôl mprơ he saơ Păng jêng lŏ khlay lơn ƀa ƀơ. Păng kuăl phung bunuyh hŏ anh jâk jêh ri geh nuih n'hâm rgănh rgônh.\n\nChorus\nVăch hom ma Gâp ơ phung rgănh, văch hom Gâp ăn may rlu. iăt hom bâr Păng gŭ kuăl nar aơ. Lơi mbăk may tâm dâng jâng Kôranh Brah. Hăn ăn êp ta ntang tơh Păng rŏng. Văch ơ văch... jêh ri... Păng ăn may rlu.\n\nVerse 2\nNau ngơi aơ khlay hâu ngăn ngên, he djôt mât Păng ăp nar. Jêng du nau ang nar nchrang nchrat dôl geh ngo klĕng rŏ trong. Dăp hom ta Păng lĕ nau jâk he lĕ huăr hươi mâu dơi anh.\n\nChorus\nVăch hom ma Gâp ơ phung rgănh, văch hom Gâp ăn may rlu. iăt hom bâr Păng gŭ kuăl nar aơ. Lơi mbăk may tâm dâng jâng Kôranh Brah. Hăn ăn êp ta ntang tơh Păng rŏng. Văch ơ văch... jêh ri... Păng ăn may rlu.\n\nVerse 3\nNau ngơi aơ khlay hâu ngăn ngên, khlay kŏ tât mâu blau dŭt. Du nar he hao rlet Ƀon Ueh jêng răm maak chrêk ma lơp. He mra saơ lĕ nau ueh Păng mâp muh măt Kôranh Brah he.\n\nChorus\nVăch hom ma Gâp ơ phung rgănh, văch hom Gâp ăn may rlu. iăt hom bâr Păng gŭ kuăl nar aơ. Lơi mbăk may tâm dâng jâng Kôranh Brah. Hăn ăn êp ta ntang tơh Păng rŏng. Văch ơ văch... jêh ri... Păng ăn may rlu.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0386", "title": "GÂP NHHƠR GÂP NƠM NA-NỄ MA YÊ-SU", "song_number": "386", "lyrics": "GÂP NHHƠR GÂP NƠM NA-NỄ MA YÊ-SU\n\n\nVerse 1\nGâp gĭt nau Yê-su rŏng toyh ngăn. Păng cha lơi Ƀon chrêk ma lơp Păng. Văch jêh jêng Nơm Tâm Rklaih lĕ rngôch bunuyh ta neh ntu. Gâp nhhơr nau mĭn gâp ma Păng.\n\nVerse 2\nNtơm nar gâp tăng nau chroh n'hêl ngăn. Yor Păng jêng Nơm Tâm Rklaih jêh gâp. Gâp sŏk dơn jêh nau rêh bơh Păng nau rêh n'ho ro. Gâp nhhơr nuih n'hâm gâp ma Păng.\n\nVerse 3\nYor lah gâp geh jêh ndơ Păng ăn. Gâp ăt geh nau rŏng ma Păng đŏng. Jêh ri gŭ rêh tĭng nâm Păng ŭch ƀư maak ma Păng. Gâp nhhơr săk jăn gâp ma Păng.\n\nVerse 4\nGâp nhhơr jêh nau mĭn gâp ma Păng. Gâp nhhơr jêh nuih n'hâm gâp ma Păng. Nđâp săk jăn gâp jao jêh gay ma nhhơr ăn Păng dŏng. Bi may ŭch nhhơr lĕ ma Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0387", "title": "GÂP HŎ PIH AO", "song_number": "387", "lyrics": "GÂP HŎ PIH AO\n\n\nVerse 1\nKăl e nau tih ƀư ƀỡ ao gâp, gâp mâu gĭt ôh mâm ƀư dĭng kloh; kŏ tât bâr rdỡ rbăn lah pô aơ: Hăn pih Gâp ƀư nglang may nâm pler.\n\nChorus\nGâp hŏ pih jêh ma mham Yê-su Păng ăn gâp jêng nglang nâm bu pler, gâp hŏ pih ao ma mham Yê-su Păng ăn gâp jêng nglang nâm bu pler.\n\nVerse 2\nNau ton Păng ăn ma mbu nơm ŭch, Păng lah đŏng ma gâp a-ƀaơ pơ. Ntơm bơh gâp văch, gâp gĭt n'hêl ngăn. Mham Păng ƀư kloh gâp nglang nâm pler.\n\nChorus\nGâp hŏ pih jêh ma mham Yê-su Păng ăn gâp jêng nglang nâm bu pler, gâp hŏ pih ao ma mham Yê-su Păng ăn gâp jêng nglang nâm bu pler.\n\nVerse 3\nGâp mâu mĭn ôh mâu lĕ dơi lah, n'hêl ngăn Păng rao lĕ nau tih gâp. Yor lah Brah Ndu ngơi jêh pô aơ. Mham Păng ƀư kloh gâp nglang nâm pler.\n\nChorus\nGâp hŏ pih jêh ma mham Yê-su Păng ăn gâp jêng nglang nâm bu pler, gâp hŏ pih ao ma mham Yê-su Păng ăn gâp jêng nglang nâm bu pler.\n\nVerse 4\nMbu nơm ŭch pih ndơ a-ƀơ ro, kŏ tât Yê-su jut lĕ nau tih. Ma nau chroh dĭng may gĭt n'hêl ngăn. Ao may hŏ kloh nglang nâm bu pler.\n\nChorus\nGâp hŏ pih jêh ma mham Yê-su Păng ăn gâp jêng nglang nâm bu pler, gâp hŏ pih ao ma mham Yê-su Păng ăn gâp jêng nglang nâm bu pler.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0388", "title": "NAU TIH PĂNG JUT LĔ JÊH", "song_number": "388", "lyrics": "NAU TIH PĂNG JUT LĔ JÊH\n\n\nVerse 1\nMay ŭch ôp ma gâp pô aơ, mâm dĭng gâp ŭch gŭ maak? Păng jut lĕ jêh nau tih, Lah bu ŭch mưch rmot ma gâp. Ŭch ôp mbah nau tih hăn, gâp lah: \"Păng jut lĕ jêh\".\n\nChorus\nPăng jut jêh ma mham khlay hoch, ta si tâm rkăng Yê-su. Păng mƀăr ăn ngai đah gâp tâm dak klŏng jru, Păng rao nau tih tâm nuih n'hâm gâp, pô ri gâp mprơ tâm rnê Păng jut jêh lĕ nau tih\".\n\nVerse 2\nLah geh Sa-tan ŭch ndơm gâp, ăn gâp tŭp tâm nau tih, Gâp lah: \"Păng jut lĕ jêh\" Gâp mâu hôm klach brah mhĭk ôh. Yor lah Yê-su mprơh păng, gâp maak Păng jut lĕ jêh.\n\nChorus\nPăng jut jêh ma mham khlay hoch, ta si tâm rkăng Yê-su. Păng mƀăr ăn ngai đah gâp tâm dak klŏng jru, Păng rao nau tih tâm nuih n'hâm gâp, pô ri gâp mprơ tâm rnê Păng jut jêh lĕ nau tih\".\n\nVerse 3\nGâp ŭch pah kan ma Yê-su, răm maak ăp nar ăp măng. Păng jut jêh lĕ nau tih, Gâp ŭch mât ton ma Yê-su. Tâm rnê ma lĕ nuih n'hâm, Păng jut jêh lĕ nau tih.\n\nChorus\nPăng jut jêh ma mham khlay hoch, ta si tâm rkăng Yê-su. Păng mƀăr ăn ngai đah gâp tâm dak klŏng jru, Păng rao nau tih tâm nuih n'hâm gâp, pô ri gâp mprơ tâm rnê Păng jut jêh lĕ nau tih\".\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0389", "title": "Ơ MAAK NGĂN UĂNH PHUNG SĬM", "song_number": "389", "lyrics": "Ơ MAAK NGĂN UĂNH PHUNG SĬM\n\n\nVerse 1\nƠ maak ngăn mpôl sĭm hao mpăr dôl luh nar. Nau păng ndrau maak nâm bu mprơ. Nâm bu ntĭm nau mĭn gâp ma nau kâp gân. Nau kâp gân tât tâm nuih n'hâm. Nđâp geh jêr kđôi ăt geh Yê-su njŭn leo. Păng jêng Nơm nuih n'hâm gâp rŏng. Nđâp ma tâm Huêng srĭng geh Păng dơm khâl ƀa-ƀơ ăn ma gâp nau rŏng nau yỗ Păng.\n\nChorus\nKôranh Brah văch jêh joi gâp tâm ntŭk nau ngo... Gâp hăn ndrel Păng dôl nôk nuih n'hâm gâp djơh... Nar aơ nau rêh gâp maak. Kôranh Brah njŭn gâp lăp Ƀon Ueh. Gâp hăn ndrel Păng roh jêh lĕ nau klân rvê.\n\nVerse 2\nKah nôk sa-ơm gâp nkhah du ngai bơh Păng. Rêh tâm nau đêh nji nar măng. Nau rêh gâp nâm bu kao rŭng tâm yăn mih. Gŭ ntŭk ngo pưt nau rŏng Păng. Dôl gâp nkhah du mblêng, gâp tăng Brah Ndu kuăl. Bâr ngơi Păng ăn gâp răm rhơn. Gŭ ndrel ma Brah Ndu, nuih n'hâm gâp đăp rmên ngăn ngên, yor lah nau Păng rŏng n'ho ro.\n\nChorus\nKôranh Brah văch jêh joi gâp tâm ntŭk nau ngo... Gâp hăn ndrel Păng dôl nôk nuih n'hâm gâp djơh... Nar aơ nau rêh gâp maak. Kôranh Brah njŭn gâp lăp Ƀon Ueh. Gâp hăn ndrel Păng roh jêh lĕ nau klân rvê.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0390", "title": "NAU RŎNG KHLAY NDÂP", "song_number": "390", "lyrics": "NAU RŎNG KHLAY NDÂP\n\n\nVerse 1\nNuih n'hâm gâp nhhơr, ma Brah Yê-su. Yor May khĭt jêh, ta si tâm rkăng. Nuih n'hâm May ji, kŏ tât nkhŭt mham. Yor nau tih gâp May dơn nau jêr. Yor nau rŏng toyh, Kôranh Brah rklaih gâp. Mâu geh ôh Nơm jêng nâm bu May. Yor nau rŏng gâp gâp nhhơr ma May. Dăn Mbỡ chiă uănh lĕ nau rêh gâp.\n\nVerse 2\nNuih n'hâm huêng gâp, nhhơr ma Yê-su. May hŏ jao săk ŭch tâm chuai gâp. Dơn nau rêh ni ta yôk Gô-tha. Yor rŏng ma bunyuh, tih tâm neh ntu. Yor nau rŏng toyh, Kôranh Brah rklaih gâp. Mâu geh ôh Nơm jêng nâm bu May. Yor nau rŏng gâp gâp nhhơr ma May. Dăn Mbỡ chiă uănh lĕ nau rêh gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0391", "title": "MBƠH SƠM HOM", "song_number": "391", "lyrics": "MBƠH SƠM HOM\n\nKM 182, Mrô hđăp 250\n\nVerse 1\nĂn mbơh sơm hom dôl nar ntơm luh mbơh sơm hom dôl nar nklang bôk Ăn mbơh sơm hom dôl măng ngo tât! Yê-su iăt may ƀa-ƀơ.\n\nVerse 2\nKôranh Brah gŭ iăt nau may mbơh sơm, nôk ơm ôi nđâp klang bôk nar! Dôl măng ngo klĕng nkŭm văr jŭm may. Păng ăt ăn may đăp mpăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0392", "title": "TÂM RNÊ MA BRAH NDU", "song_number": "392", "lyrics": "TÂM RNÊ MA BRAH NDU\n\n\nVerse 1\nLĕ rngôch neh ntu khĭt tâm nau tih ngo klĕng. Neh ntu tih mhĭk, ƀiă lah Yê-su văch khĭt ta si tâm rkăng anh lĕ nau tih gâp, Brah Yê-su hoch mham nhhơr Păng nơm ma he.\n\nChorus\nTâm rnê May yor May rklaih huêng gâp. Rnê May yor nau rêh gâp rgâl ngăn. Tâm rnê May yor gay ăn gâp geh. Nau tâm rklaih May toyh aơ! khlay ngăn ngên.\n\nVerse 2\nPăng lơi Ƀon chrêk ma lơp văch ta neh ntu. Păng sân săk jăn khĭt gay tâm chuai bunuyh Păng ntrok ntŭk yor he anh lĕ nau rêh ni, gâp rŏng Păng rŏng ƀa-ƀơ n'ho ro mâu rgâl.\n\nChorus\nTâm rnê May yor May rklaih huêng gâp. Rnê May yor nau rêh gâp rgâl ngăn. Tâm rnê May yor gay ăn gâp geh. Nau tâm rklaih May toyh aơ! khlay ngăn ngên.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0393", "title": "BRAH YÊ-SU GŬ NDREL", "song_number": "393", "lyrics": "BRAH YÊ-SU GŬ NDREL\n\n\nVerse 1\nNau rêh gâp maak yor geh Brah Yê-su. ăp nhuat gâp chuat Păng ăn nâp ƀa-ƀơ. Mâp đah nau jêr mâu lah nau rngot rvê, Yê-su king n'gang tâm lĕ trong gâp hăn.\n\nChorus\nTâm rnê Păng, Kôranh Brah jêng Nơm rŏng gâp. Mbơh Amoh Păng ma lĕ rngôch bunuyh nhhơr ma Păng lĕ rngôch nau mprơ ueh uĭn, kah gĭt mbơh Amoh Păng lam ntŭk.\n\nVerse 2\nDôl gŭ êng du huê âk nau klân rvê, Păng mâu lơi ôh jêng rmăk mât mơh gâp. Nđâp lah gâp gŭ ta nklang phung djơh mhĭk, geh jêh Yê-su rmăk gâp gŭ đăp mpăn.\n\nChorus\nTâm rnê Păng, Kôranh Brah jêng Nơm rŏng gâp. Mbơh Amoh Păng ma lĕ rngôch bunuyh nhhơr ma Păng lĕ rngôch nau mprơ ueh uĭn, kah gĭt mbơh Amoh Păng lam ntŭk.\n\nVerse 3\nKđôi moh nau tât tâm rnôk kêng dŭt aơ, kđôi moh nau tât nau rêh ni ma gâp. Nđâp lah gâp gŭ ta nklang ŭnh hit kđôi, Yê-su Nơm king jêh ri Păng nkhôm gâp.\n\nChorus\nTâm rnê Păng, Kôranh Brah jêng Nơm rŏng gâp. Mbơh Amoh Păng ma lĕ rngôch bunuyh nhhơr ma Păng lĕ rngôch nau mprơ ueh uĭn, kah gĭt mbơh Amoh Păng lam ntŭk.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0394", "title": "VĂCH HOM HUÊNG GÂP VƠL MA MAY", "song_number": "394", "lyrics": "VĂCH HOM HUÊNG GÂP VƠL MA MAY\n\n\nVerse 1\nVăch hom huêng gâp vơh vơl ma May, yor lah May hŏ joi jêh gâp. Gâp tĭng ndỗ May, gâp jao nuih n'hâm, ndrel ma nau tih gâp ma May.\n\nChorus\nVăch hom huêng gâp vơh vơl ma May, lĕ nau maak gâp gŭ tâm May. Gâp mât ton May, gâp dăn ma May ơ Yê-su văch gŭ tâm gâp.\n\nVerse 2\nNgăn ka-nŏng păm nau yỗ May dơm, dơi jut tho nau tih mhĭk gâp. May yỗ ăn gâp, jêh nây ăn nau đăp mpăn bơh nau May sâm chuai.\n\nChorus\nVăch hom huêng gâp vơh vơl ma May, lĕ nau maak gâp gŭ tâm May. Gâp mât ton May, gâp dăn ma May ơ Yê-su văch gŭ tâm gâp.\n\nVerse 3\nTơ lah gâp geh đing tâm trong gâp, hăn rgăn êp kêng ntŭk nau ndơm. Mpang ti Brah May ƀư ăn nâp gâp, jêh ri ăn geh nau dơi ngăn.\n\nChorus\nVăch hom huêng gâp vơh vơl ma May, lĕ nau maak gâp gŭ tâm May. Gâp mât ton May, gâp dăn ma May ơ Yê-su văch gŭ tâm gâp.\n\nVerse 4\nGŭ hom tâm Gâp, ăn ma ăp mông, Nơm kơl gâp, Nơm king ăn gâp. Nau dơi ma gâp jêh nây nau maak Yê-su Krist, jêng Nơm Tâm Rklaih.\n\nChorus\nVăch hom huêng gâp vơh vơl ma May, lĕ nau maak gâp gŭ tâm May. Gâp mât ton May, gâp dăn ma May ơ Yê-su văch gŭ tâm gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0395", "title": "KÔRANH BRAH DƠM JÊNG NAU MAAK", "song_number": "395", "lyrics": "KÔRANH BRAH DƠM JÊNG NAU MAAK\n\n\nVerse 1\nRăm maak ngăn dơi gĭt năl Nơm Tâm Rklaih, jêh ri dơi gŭ ndrel tâm nau Păng yỗ. Păng hŏ tâm rgâl jêh nau gâp gŭ ngau, Kôranh Brah dơm jêng nau maak.\n\nChorus\nBrah! răm maak ngăn ngên, mâu hôm rvê ma nau rngot klâng. Yor lah gâp geh jêh Yê-su gŭ tâm nuih n'hâm. Kôranh Brah dơm jêng nau maak. Kôranh Brah dơm jêng nau maak.\n\nVerse 2\nRăm maak ngăn dơi jêng bunuyh hŏ rgâl mhe, Yê-su đah gâp hŏ tâm rnglăp n'hêl ngăn. Păng hŏ ăn jêh nau tâm rklaih ma gâp, Kôranh Brah dơm jêng nau maak.\n\nChorus\nBrah! răm maak ngăn ngên, mâu hôm rvê ma nau rngot klâng. Yor lah gâp geh jêh Yê-su gŭ tâm nuih n'hâm. Kôranh Brah dơm jêng nau maak. Kôranh Brah dơm jêng nau maak.\n\nVerse 3\nRăm maak ngăn nau tih gâp Păng yỗ jêh, jêh ri dơi gŭ rêh khư ta năp Păng. A-ƀơ, gâp hăn gay tât Ƀon Ueh Păng, Kôranh Brah dơm jêng nau maak.\n\nChorus\nBrah! răm maak ngăn ngên, mâu hôm rvê ma nau rngot klâng. Yor lah gâp geh jêh Yê-su gŭ tâm nuih n'hâm. Kôranh Brah dơm jêng nau maak. Kôranh Brah dơm jêng nau maak.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0396", "title": "PĂNG MRA SIĂM PHUNG BIĂP PĂNG", "song_number": "396", "lyrics": "PĂNG MRA SIĂM PHUNG BIĂP PĂNG\n\n\nVerse 1\nPăng mra siăm phung biăp Păng. Nâm bu Du Huê Rmăk Biăp Ueh. Păng mra rơ-u phung kon biăp jễ lễ tâm ntang ntơh Păng... Mât mơh ueh tâm... ntang ntơh Păng...\nPăng mra siăm phung biăp Păng nâm bu du huê phung Rmăk Biăp Ueh. Păng mra rơ-u phung kon biăp jễ lễ tâm ntang ntơh Păng. Mât mơh ueh tâm... ntang. ntơh... Păng Nơm.\nJêh ri chông leo khân păng... Tâm ntang ntơh... Păng jêh ri njŭn leo ma nau rdỡ rbăn lĕ rngôch phung me hŏ ntreo. Njŭn leo ma nau rdỡ rbăn. Njŭn leo... ma nau rdỡ rbăn lĕ rngôch me lĕ ntreo.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0397", "title": "NGƠI ĐAH YÊ-SU", "song_number": "397", "lyrics": "NGƠI ĐAH YÊ-SU\n\n\nVerse 1\nGâp roh jêh tâm nau tih. Ƀiă lah Yê-su chông gâp. nôk nây nau ang jễ lĕ bơh trôk mbêng ăn huêng gâp. Ma nuih n'hâm tâm nau rŏng n'ho chih amoh gâp ta klơ. Gâp gŭ nkoch bri đễ đah Yê-su Păng njêng di ngăn.\n\nChorus\nGŭ nkoch bri khâl đễ đah Yê-su. Mbơh ma Păng lĕ nau he uh ah tăng he nhĭm huêt rhôi plỡ sĭt lah ta-oi lah may ntơm dâk mbơh sơm đễ đễ. Gĭt saơ ŭnh jễ ntơm hit tâm may saơ nau ngơi đễ đah Yê-su Păng njêng ô-băl.\n\nVerse 2\nGâp geh nau rvê hôm klach. măt gâp bêng ma dak măt. Ƀiă lah Yê-su jêng mĭt jiăng chiă gâp măng nâm năr. Gâp hăn mbơh sơm ma Păng, Păng gĭt lĕ nau gâp chrê. Knŏng gŭ nkoch bri đễ đah Yê-su Păng njêng he sŏng.\n\nChorus\nGŭ nkoch bri khâl đễ đah Yê-su. Mbơh ma Păng lĕ nau he uh ah tăng he nhĭm huêt rhôi plỡ sĭt lah ta-oi lah may ntơm dâk mbơh sơm đễ đễ. Gĭt saơ ŭnh jễ ntơm hit tâm may saơ nau ngơi đễ đah Yê-su Păng njêng ô-băl.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0398", "title": "UĂNH TRENG YÊ-SU", "song_number": "398", "lyrics": "UĂNH TRENG YÊ-SU\n\n\nVerse 1\nUănh ma Yê-su dôl nôk ơm ôi, dôl măng ngo hŏ ntơm rlau jêh, Nhhơr ma Kôranh he lĕ nau klân rvê, Păng mra yỗ ăn lĕ nau tih. Nau mhĭk blem, nau mhĭk hŏ roh jêh. Yor si tâm rkăng Păng dơn jêh, Jêh ri mơ he mra văch mâp Păng. Ƀa-ƀơ rêh maak tâm ngih Mbỡ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0399", "title": "JRU LƠN, JRU LƠN", "song_number": "399", "lyrics": "JRU LƠN, JRU LƠN\n\n\nVerse 1\nJru lơn, jru lơn, Gâp lăp gay gĭt năl n'hêl nuih n'hâm Yê-su. Mâm Nau Păng rŏng jêh ma gâp, he mâu geh ôh nau khư. Păng jŭr gay chông gâp bơh ntŭk tih nâm tă bơh dak nung. Tâm rklaih huêng gâp ƀư bah jêh gâp, nơm hŏ nkhah du bơh trong Păng.\n\nVerse 2\nJru lơn, jru lơn, Gâp lăp joi ăn gĭt vât nau Yê-su ŭch. Mbơh sơm gay ăn Păng yỗ ăn, dơi tĭng ndỗ nau song Păng. Chon mon nhhơr ma Nơm ƀư rĭng ta năp Păng ma nau ueh. Vơl dăn Păng dơn njêng gâp ăn khư, tât Păng dơi dŏng nau rêh gâp.\n\nVerse 3\nJru lơn, jru lơn, Gâp lăp tâm ntŭk yôk kăl ver Yê-su khĭt. Tĭng Păng bơh Gêt-sê-ma-nê, tâm mâp đah phung rlăng mhĭk. Nhêt nkoch nau rngot ndrel ma Păng, nhĭm nhhiăng ma nuih n'hâm hươi. Ơ Nơm Tâm Rklaih kơl hom gâp ƀă! yỗ ăn ma nau hươi gâp aơ.\n\nVerse 4\nJru lơn, jru lơn, Gâp lăp tâm nau răm maak ndrel ma Yê-su. Ăt răm maak ta ntŭk rngot rvê, đăp mpăn tâm ntŭk rêh ni. Ăt răm maak tâm ntŭk rngot rvê đăp mpăn tâm ntŭk rêh ni. Yê-su mra ăn, Yê-su mra ăn, Păng mra mât mơh king ăn he.\n\nVerse 5\nJru lơn, jru lơn, Gâp lăp tâm nau rŏng Yê-su Nơm geh jêh. Tâm rnê ma Nơm njŭn gâp. hŏ luh jêh bơh nau rtăp rak. Dôl rnôk n'ho ro gâp mra mprơ ma nau kah gĭt ma Păng. Păng rŏng gâp ngăn, Păng rŏng gâp ngăn, Yê-su Kôranh Brah gâp, Hađăch gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0400", "title": "TÂM N'GAR KAO", "song_number": "400", "lyrics": "TÂM N'GAR KAO\n\n\nVerse 1\nGâp hăn du huê rlet ma n'gar kao, Ta ntŭk krêp dak ngom kăr ta kao gŭr jêh ri gâp tăng bâr kuăl ngơi ndrel ma gâp, jêng Kon Brah Ndu gay tâm mpơl.\n\nChorus\nPăng chuat hăn ndrel gâp. Păng nkoch bri ma gâp, jêh ri Păng lah gâp jêng Kon Păng. Hên maak hâu ngăn ngên nôk dôl gŭ ta nây. Ê geh ôh nơm mâp gĭt năl.\n\nVerse 2\nTăng bâr tă bơh trôm mbung Păng ngơi. Ueh reh tât sĭm och rlu đŏng nau ndrau jêh ri bâr Păng ngơi ueh reh gâp gŭ iăt, kŏ tât play nuih gâp râm sâr.\n\nChorus\nPăng chuat hăn ndrel gâp. Păng nkoch bri ma gâp, jêh ri Păng lah gâp jêng Kon Păng. Hên maak hâu ngăn ngên nôk dôl gŭ ta nây. Ê geh ôh nơm mâp gĭt năl.\n\nVerse 3\nGâp gŭ ndrel Păng tâm ntŭk n'gar kao. Kŏ tât măng ngo vêt vê nchuang jŭm gâp ma bâr nter nđêh nji Păng jă gâp hăn ndrel, Bâr Păng gŭ kuăl gâp vơk vơk.\n\nChorus\nPăng chuat hăn ndrel gâp. Păng nkoch bri ma gâp, jêh ri Păng lah gâp jêng Kon Păng. Hên maak hâu ngăn ngên nôk dôl gŭ ta nây. Ê geh ôh nơm mâp gĭt năl.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0401", "title": "JRU LƠN TÂM NAU RŎNG BRAH YÊ-SU", "song_number": "401", "lyrics": "JRU LƠN TÂM NAU RŎNG BRAH YÊ-SU\n\n\nVerse 1\nJru lơn, jru lơn, tâm nau rŏng Brah Yê-su, ăp nar ăn gâp hao. Prêh lơn prêh lơn tâm ngih nti nau blau mĭn, gay nti âk nau yỗ.\n\nChorus\nJru lơn yor gâp mbơh sơm jêh ri prêh lơn ăp nar jêh ri lơ jêng blau lơn ơ Kôranh Brah yor Nau May Ngơi.\n\nVerse 2\nJru lơn, jru lơn, Brah Huêng Ueh nau ueh uĭn. lăp jru lơn tâm gâp. Kŏ tât nau rêh gâp glŏm lĕ tâm Yê-su, nây jêng nau Păng ŭch.\n\nChorus\nJru lơn yor gâp mbơh sơm jêh ri prêh lơn ăp nar jêh ri lơ jêng blau lơn ơ Kôranh Brah yor Nau May Ngơi.\n\nVerse 3\nJru lơn, jru lơn, nđâp geh nau rlong uănh kđôi, jru lơn ăn gâp lăp. Njŭr reh tâm nau rŏng kloh ueh Brah Yê-su, gay ma geh play âk.\n\nChorus\nJru lơn yor gâp mbơh sơm jêh ri prêh lơn ăp nar jêh ri lơ jêng blau lơn ơ Kôranh Brah yor Nau May Ngơi.\n\nVerse 4\nJru lơn, jru lơn, prêh lơn Tâm Brah Yê-su, tât lôch nau tâm lơh. Saơ gâp dơi ngăn jêh ri jêng rup Păng Nơm, mâu geh nau pưt ôh.\n\nChorus\nJru lơn yor gâp mbơh sơm jêh ri prêh lơn ăp nar jêh ri lơ jêng blau lơn ơ Kôranh Brah yor Nau May Ngơi.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0402", "title": "DÔL YÊ-SU GŬ TÂM NUIH N'HÂM", "song_number": "402", "lyrics": "DÔL YÊ-SU GŬ TÂM NUIH N'HÂM\n\nTC 215\n\nVerse 1\nKhlay ngăn nau rêh gâp aƀaơ yor nau yỗ dơi rgâl jêh, yor Yê-su gŭ tâm nuih n'hâm aơ. Bơh kăl e tât ta-ri dĭng saơ nau ngơi ngăn aơ, Dôl geh Kôranh Brah gŭ tâm nuih n'hâm\n\nChorus\nBrah Yê-su gŭ tâm gâp rhơn ngăn! Brah Yê-su gŭ tâm gâp măng nar, nau răm maak mbêng ma gâp tâm ban dak mƀŭt dôl rbuh, nôk Yê-su gŭ lăp tâm nuih n'hâm.\n\nVerse 2\nA-ƀơ mâu hôm vĭ ôh, mâu lă lau nâm bu saơm, yor Yê-su gŭ tâm nuih n'hâm aơ. Lĕ nau tih ơm nâm mhĭng klo hŏ rao kloh nglang ƀhiau. Dôl geh Kôranh Brah gŭ tâm nuih n'hâm\n\nChorus\nBrah Yê-su gŭ tâm gâp rhơn ngăn! Brah Yê-su gŭ tâm gâp măng nar, nau răm maak mbêng ma gâp tâm ban dak mƀŭt dôl rbuh, nôk Yê-su gŭ lăp tâm nuih n'hâm.\n\nVerse 3\nNau rêh gâp aơ dơi nsing lơ nâp lơn mâu rngot ôh, yor Yê-su gŭ tâm nuih n'hâm aơ. Lĕ thŭl tŭk nkâm rai jêh, moh ndơ hôm king đŏng taơ. Dôl geh Kôranh Brah gŭ tâm nuih n'hâm\n\nChorus\nBrah Yê-su gŭ tâm gâp rhơn ngăn! Brah Yê-su gŭ tâm gâp măng nar, nau răm maak mbêng ma gâp tâm ban dak mƀŭt dôl rbuh, nôk Yê-su gŭ lăp tâm nuih n'hâm.\n\nVerse 4\nRi jâng nau nchrat dôl ang, sol tâm rlŭng nau rai yot, yor Yê-su gŭ tâm nuih n'hâm aơ. Uănh bơh ngai ri Ƀon Ueh nar aơ saơ dôl pơk mpông. Dôl geh Kôranh Brah gŭ tâm nuih n'hâm\n\nChorus\nBrah Yê-su gŭ tâm gâp rhơn ngăn! Brah Yê-su gŭ tâm gâp măng nar, nau răm maak mbêng ma gâp tâm ban dak mƀŭt dôl rbuh, nôk Yê-su gŭ lăp tâm nuih n'hâm.\n\nVerse 5\nNar kăn dỡ, rhơn răm ngăn! Dơi hao klơ Ƀon chrêk rmah, yor Yê-su gŭ tâm nuih n'hâm aơ. Nuih n'hâm maak ueh hâu ngăn dơi hăn tât ntŭk n'ho ro. Dôl geh Kôranh Brah gŭ tâm nuih n'hâm\n\nChorus\nBrah Yê-su gŭ tâm gâp rhơn ngăn! Brah Yê-su gŭ tâm gâp măng nar, nau răm maak mbêng ma gâp tâm ban dak mƀŭt dôl rbuh, nôk Yê-su gŭ lăp tâm nuih n'hâm.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0403", "title": "PHUNG SĬM SRAI MĂT PĂNG ĂT TRENG UĂNH", "song_number": "403", "lyrics": "PHUNG SĬM SRAI MĂT PĂNG ĂT TRENG UĂNH\n\nTC 390\n\nVerse 1\nLah geh Yê-su mĭt jiăng ueh nar măng gŭ êp ndrel gâp. Mâm gâp hôm rdja hôm vĭ vĕ. Mâm gâp hôm e nau đing. Mâm ƀư nuih n'hâm rngot rvê aơ, ŭch gŭ Ƀon Ueh klơ ro? Sĭm srai măt Păng ăt treng uănh, bi ma gâp Yê-su lơi lĕ? Sĭm srai măt Păng ăt treng uănh. Yor ri Păng mâu chuêl gâp ôh?\n\nChorus\nNuih n'hâm răm maak ŭch mprơ mro, nuih n'hâm răm maak ŭch mprơ; Phung sĭm srai măt Păng ăt treng uănh, yor ri Păng mâu chuêl gâp ôh?\n\nVerse 2\nIăt nau Păng rŏng sŭk nsôr gâp, lơi ta uh ah, ơ kon. Gâp nsing tâm năr nau yỗ Păng. Mâu hôm klach ôh, maak mro. Gâp gĭt ngăn Păng njŭn leo gâp, gâp saơ ăp nhuat gâp chuat; Sĭm srai măt Păng ăt treng uănh, bi ma gâp Yê-su lơi lĕ? Sĭm srai măt Păng ăt treng uănh. Yor ri Păng mâu chuêl gâp ôh?\n\nChorus\nNuih n'hâm răm maak ŭch mprơ mro, nuih n'hâm răm maak ŭch mprơ; Phung sĭm srai măt Păng ăt treng uănh, yor ri Păng mâu chuêl gâp ôh?\n\nVerse 3\nDôl geh nau ngo nchueng jŭm gâp, nôk nây sa-tan ndơm gâp; Nđâp lah bâr mprơ jêng nau nhĭm. Nau kâp gân gâp roh hêng, Gâp srôih gŭ dăch kêng Yê-su, rnơm Păng ƀư rai nau rngot; Sĭm srai măt Păng ăt treng uănh, bi ma gâp Yê-su lơi lĕ? Sĭm srai măt Păng ăt treng uănh. Yor ri Păng mâu chuêl gâp ôh?\n\nChorus\nNuih n'hâm răm maak ŭch mprơ mro, nuih n'hâm răm maak ŭch mprơ; Phung sĭm srai măt Păng ăt treng uănh, yor ri Păng mâu chuêl gâp ôh?\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0404", "title": "NAU ANG TÂM NUIH N'HÂM", "song_number": "404", "lyrics": "NAU ANG TÂM NUIH N'HÂM\n\nTC 460\n\nVerse 1\nRi nau nchrat ang mâu dơi blau ntĭt, ma nau Brah Păng sol ang. Aƀaơ nuih n'hâm gâp kloh ueh, ang rsang, yor geh Yê-su tho rao.\n\nChorus\nNau ang klu klâm! Nau nchrat ang ngăn! Tu nau rêh rdỡ rbăn ma nuih n'hâm gâp. Dôl Yê-su hĭk toyoi mbung gơm trunh, jêng nau ang sol tâm nuih n'hâm.\n\nVerse 2\nNgih nti mprơ nuih n'hâm gâp dôl nti, mprơ ndrel tâm rnê Kôranh Brah. Âk nau mprơ ueh Brah Krist ŭch iăt, nđâp lah gâp mâu lot mprơ.\n\nChorus\nNau ang klu klâm! Nau nchrat ang ngăn! Tu nau rêh rdỡ rbăn ma nuih n'hâm gâp. Dôl Yê-su hĭk toyoi mbung gơm trunh, jêng nau ang sol tâm nuih n'hâm.\n\nVerse 3\nAƀaơ geh yan kao nuih n'hâm ueh mhe, yor Kôranh Brah gŭ êp gâp. Rhơn nau đăp mpăn, ntơm dôl gŭ ndrau, kao nau yỗ dang ang nchrat.\n\nChorus\nNau ang klu klâm! Nau nchrat ang ngăn! Tu nau rêh rdỡ rbăn ma nuih n'hâm gâp. Dôl Yê-su hĭk toyoi mbung gơm trunh, jêng nau ang sol tâm nuih n'hâm.\n\nVerse 4\nDu njêh rêh gâp geh nau maak ngăn, tông yơk kâp gân, mât ton. Yor nau Păng yỗ gâp mâu dơi kơp, tâm kăn-dỡ saơ Ƀon ueh.\n\nChorus\nNau ang klu klâm! Nau nchrat ang ngăn! Tu nau rêh rdỡ rbăn ma nuih n'hâm gâp. Dôl Yê-su hĭk toyoi mbung gơm trunh, jêng nau ang sol tâm nuih n'hâm.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0405", "title": "MÂT TON TÂM RNÊ AMOH NƠM RKLAIH HE", "song_number": "405", "lyrics": "MÂT TON TÂM RNÊ AMOH NƠM RKLAIH HE\n\n\nVerse 1\nMât ton tâm rnê Amoh Nơm rklaih he, yor păng yỗ sâm rvê ma he. Amoh Păng khư yơk tâm lĕ rngôch ntŭk yor Amoh Păng bêng ma nau Brah.\n\nChorus\nA-moh khlay lơn A-moh khlay lơn. Chrêk r-mah tâm Brah Yê-su. A-moh khlay lơn. A-moh khlay lơn tâm amoh Brah Yê-su khlay lơn.\n\nVerse 2\nYê-su, Hađăch he, Kôranh ma lĕ ndơ, Păng jêng nau ang tâm rnôk aơ. Ma bâr ntêh ktang mprơ tâm rnê păng, ndrel phung tông păr ueh tâm trôk.\n\nChorus\nA-moh khlay lơn A-moh khlay lơn. Chrêk r-mah tâm Brah Yê-su. A-moh khlay lơn. A-moh khlay lơn tâm amoh Brah Yê-su khlay lơn.\n\nVerse 3\nPăng lơi Ƀon chrêk rmah klơ trôk, dơn nau bu pâng ta si tâm rkăng. Nđêh nji rêh ni khĭt yor ma bunuyh, ŭch tâm rgâl lĕ bunuyh tih mhĭk.\n\nChorus\nA-moh khlay lơn A-moh khlay lơn. Chrêk r-mah tâm Brah Yê-su. A-moh khlay lơn. A-moh khlay lơn tâm amoh Brah Yê-su khlay lơn.\n\nVerse 4\nAmoh Păng khlay lơn ma lĕ rngôch amoh. Geh nau tâm rnê ta neh ntu. Kơl gâp ƀư chrêk rmah ma Amoh May, jêh ri ăn gâp ma nau rŏng.\n\nChorus\nA-moh khlay lơn A-moh khlay lơn. Chrêk r-mah tâm Brah Yê-su. A-moh khlay lơn. A-moh khlay lơn tâm amoh Brah Yê-su khlay lơn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0406", "title": "MÂT TON MA BRAH NDU", "song_number": "406", "lyrics": "MÂT TON MA BRAH NDU\n\n\nVerse 1\nMât ton ma Brah Ndu, păng hŏ ƀư jêh nau khlay. Păng rŏng ma phung kon bunuyh tât ăn Kon Păng Nơm. Yê-su nhhơr nau rêh păng, tâm chuai he bơh tih. Păng pơk mpông jă he lăp tâm nau rêh n'ho ro.\n\nChorus\nRnê Kôranh Brah, rnê Kôranh Brah. Ăn neh ntu iăt bâr Păng. Rnê Kôranh Brah, rnê Kôranh Brah. Ăn lĕ bunuyh geh răm maak. Ơ văch hom ma Mbỡ he tâm Kon Păng Yê-su. Mât ton ma Brah Ndu, Păng hŏ ƀư jêh nau khlay.\n\nVerse 2\nDi ngăn nau tâm chuai nĕ, khĭt ntrok jêh dơm dam ma ăp nơm phung chroh he tĭng nau Păng hŏ ton. Nơm djơh mhĭk dŭt n'hâm, lah chroh ngăn ma Yê-su. sŏk dơn ro nau yỗ nđach. dơi rao kloh nau tih.\n\nChorus\nRnê Kôranh Brah, rnê Kôranh Brah. Ăn neh ntu iăt bâr Păng. Rnê Kôranh Brah, rnê Kôranh Brah. Ăn lĕ bunuyh geh răm maak. Ơ văch hom ma Mbỡ he tâm Kon Păng Yê-su. Mât ton ma Brah Ndu, Păng hŏ ƀư jêh nau khlay.\n\nVerse 3\nKhlay ngăn nau păng nti he, khlay ngăn nau păng ƀư, khlay ngăn yơh nau maak he yor klaih bơh nau tih. Ƀiă-lah nau khlay lơn, nau dŭt toyh, nau dŭt prêh, lah mâp jêh Brah Yê-su tâm ƀon ueh ta klơ\n\nChorus\nRnê Kôranh Brah, rnê Kôranh Brah. Ăn neh ntu iăt bâr Păng. Rnê Kôranh Brah, rnê Kôranh Brah. Ăn lĕ bunuyh geh răm maak. Ơ văch hom ma Mbỡ he tâm Kon Păng Yê-su. Mât ton ma Brah Ndu, Păng hŏ ƀư jêh nau khlay.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0407", "title": "MPRƠ RNÊ NCHRÊNG N'GÔR HA-LÊ-LU-YA", "song_number": "407", "lyrics": "MPRƠ RNÊ NCHRÊNG N'GÔR HA-LÊ-LU-YA\n\n\nVerse 1\nMprơ rnê nchrêng n'gôr Ha-lê-lu-ya. Nau yỗ Yê-su toyh jru hâu ngăn. Mprơ Ha-lê-lu-ya. Mprơ Ha-lê-lu-ya. Mprơ rnê nchrêng n'gôr Ha-lê-lu-ya.\n\nVerse 2\nYê-su jêng Hađăch lam neh lam trôk. Yê-su jêng Hađăch lam neh lam trôk. Mprơ Ha-lê-lu-ya. Mprơ Ha-lê-lu-ya. Mprơ rnê nchrêng n'gôr Ha-lê-lu-ya.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0408", "title": "DU NAR UEH MAAK", "song_number": "408", "lyrics": "DU NAR UEH MAAK\n\n\nVerse 1\nDu nar ueh maak du nar ueh maak Kôranh Brah hŏ ăn jêh, Kôranh Brah hŏ ăn jêh. He mra răm maak, he mra răm maak, jêh ri ƀư rhơn răm, jêh ri ƀư rhơn răm. Du nar ueh maak Kôranh Brah hŏ ăn jêh. He mra răm maak, jêh ri ƀư rhơn răm. Yor ma nar aơ yor ma nar aơ Kôranh Brah ăn ma he.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0409", "title": "YÊ-SU YƠH, NƠM RKLAIH GÂP", "song_number": "409", "lyrics": "YÊ-SU YƠH, NƠM RKLAIH GÂP\n\n\nVerse 1\nYê-su yơh Nơm rklaih gâp mâu geh nơm êng rlau ma May. Ăp nar gâp rêh gâp ŭch tâm rnê ma yor nau ueh May rŏng dŭt toyh.\n\nChorus\nNter ma Kôranh Brah lĕ phung bunuyh, mprơ hom he Nau dơi tâm rnê Brah Yê-su Hađăch jêng toyh. Yôk ăt chon mon nđâp dak mƀŭt mra n'gôr nteh ma bâr ngloh tâm Amoh May. Gâp mra răm rhơn lĕ kan pah bơh ti May. Gâp rŏng ma May ƀa-ƀơ n'ho ro tât lôch. Mâu dơi tâm rđĭl nau ton jêh gâp hŏ geh tâm May.\n\nVerse 2\nNơm bonh gâp, Nơm king gâp ntŭk gâp nde krap đah phung rlăng. Lĕ n'hâm gâp nsôr, lĕ nau gâp jêng, mâu rlu ôh yơk mbah ma May.\n\nChorus\nNter ma Kôranh Brah lĕ phung bunuyh, mprơ hom he Nau dơi tâm rnê Brah Yê-su Hađăch jêng toyh. Yôk ăt chon mon nđâp dak mƀŭt mra n'gôr nteh ma bâr ngloh tâm Amoh May. Gâp mra răm rhơn lĕ kan pah bơh ti May. Gâp rŏng ma May ƀa-ƀơ n'ho ro tât lôch. Mâu dơi tâm rđĭl nau ton jêh gâp hŏ geh tâm May.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0410", "title": "BRAH NDU HAĐĂCH TOYH", "song_number": "410", "lyrics": "BRAH NDU HAĐĂCH TOYH\n\n\nVerse 1\nBrah Ndu dŭt toyh Nơm khư jêng Brah. Brah Ndu tâm trôk gŭ rêh tâm gâp. Yê-su mĭt jiăng ueh, nơm rdỡ rbăn ngăn. Dơi tâm rklaih he bơh ntơm tât lôch. Gâp ŭch chon dăch ta sưng Ha-đăch May. May jêng Brah toyh Nơm khư bu yơk. Gâp ŭch jao nau rêh ta năp May. Ao jâr jong May, gâp mâu năng dơn. Gâp rêh ŭch kan ma Nơm Hađăch Brah.\n\nVerse 2\nTrôk nđâp neh ntu yơk ma may đŏng. Rŏng mâu blau lôch, di nau răp jăp. Mbu moh sâm tăk chuai huêng mpôl kon bunuyh. Djôt sĭt mplỡ nơm tih dăch ta sưng Hađăch. Ăn lĕ rngôch plỡ văch kuăl tâm rnê ma Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0411", "title": "AMOH PĂNG NƠM KHLAY NGĂN NGÊN", "song_number": "411", "lyrics": "AMOH PĂNG NƠM KHLAY NGĂN NGÊN\n\n\nVerse 1\nAmoh păng nơm khlay ngăn ngên. Amoh păng nơm khay ngăn ngên. Amoh păng nơm khlay ngăn ngên, Yê-su Kôranh gâp. Păng jêng Hađăch Brah toyh ngăn, Kôranh ma lĕ r-ngôch ndơ. Amoh Păng Nơm khlay ngăn ngên, Yê-su, Kôranh gâp. Păng jêng Rmăk Biăp toyh jêng rplay lŭ gŭ nâp mro. Brah Ndu geh lĕ nau Brah. Chon mon ta năp Păng, rŏng jêh ri yơk Păng. Amoh Păng Nơm khlay ngăn ngên, Yê-su, Kôranh gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0412", "title": "HĂN HOM, HE MPRƠ HUY KATANG", "song_number": "412", "lyrics": "HĂN HOM, HE MPRƠ HUY KATANG\n\n\nVerse 1\nHăn hom, he mprơ huy ktang. Yơk rnê kon se Yê-su, lơi Ƀon chrat ang tâm trôk, văch ta neh ntu. Mprơ hom, mprơ tâm rnê Yê-su. Văch hom, mbah yơk păng jêng Hađăch.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0413", "title": "GÂP RNÊ KÔRANH BRAH", "song_number": "413", "lyrics": "GÂP RNÊ KÔRANH BRAH\n\nTVCHH 241\n\nVerse 1\nGâp rnê Kôranh Brah yor Păng ăt mro rŏng gâp. Gâp rnê Kôranh Brah yor Păng Nơm mât uănh gâp. Gâp rnê Kôranh Brah yor dơi ƀư kon tâm Păng. Gâp rêh tâm Păng nuih n'hâm gâp mro aih maak. Văt lah năm khay nau rêh ăt hôm dơi găn. Văt lah sial rpuh, phŭt chuănh tâm nau rêh gâp. Nuih n'hâm gâp gĭt ngăn Păng rŏng gâp tât lôch. Tâm ăp nhuat trong ti may têk ndrêng gâp hăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0414", "title": "HĂN MBƠH AMOH BRAH YÊ-SU", "song_number": "414", "lyrics": "HĂN MBƠH AMOH BRAH YÊ-SU\n\n\nVerse 1\nHăn mbơh Amoh Brah Yê-su, iăt hom bâr Păng nti lah. Ƀư hom tĭng nau Păng ŭch, nsing tông ma Nơm rŏng. Uănh hom sambŭt Păng nchih jêh, iăt hom moh nau Păng lah. Ƀư hom ŭch ƀư maak păng, tĭng ndỗ lĕ nau bơh Mbỡ Păng. Rŏng Brah Yê-su yơh, Nơm tâm rklaih lĕ bu-nuyh. tĭng chroh ma Păng, tĭng tông Păng dơm.\n\nVerse 2\nPăng lah, \"Êp hom Yê-su. Păng nchih ăn may sŏk dơn. Rnê hom, tĭng nau Păng ŭch. Păng nchih ƀư ăn ma may. Nsing hom ma Brah Yê-su, tĭng ndỗ Păng hŏ ƀư jêh. Ăn Păng gai nau rêh may, bunuyh may jêng ndơ ma tât lôch. Rŏng Brah Yê-su yơh, Nơm tâm rklaih lĕ bu-nuyh. tĭng chroh ma Păng, tĭng tông Păng dơm.\n\nVerse 3\nPăng lah, \"Nđâp ma Yê-su.\" Păng nchih kâp may sŏk dơn. Rnê hom, tĭng nau Păng ŭch. Păng nchih ƀư ăn ma may. Nsing hom ma Brah Yê-su, tĭng kơt Păng hŏ ƀư jêh. Ăn Păng gai nau rêh may, bunuyh jao jêh nau rêh ma Păng. Rŏng Brah Yê-su yơh, Nơm tâm rklaih lĕ bu-nuyh. tĭng chroh ma Păng, tĭng tông Păng dơm.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0415", "title": "LAH GÂP GEH TI JỄ KAĐÔI", "song_number": "415", "lyrics": "LAH GÂP GEH TI JỄ KAĐÔI\n\n\nVerse 1\nLah gâp geh ti jễ kđôi, ŭch pah kan Kôranh Brah. Lah gâp geh jễ jâng kđôi, hăn mbơh Amoh Yê-su. Lah gâp geh mpiăt dơi mprơ, ŭch mprơ mât ton Păng. Nđâp lah geh trong jêr jŏt, gâp ăt chuat pa-năp.\n\nVerse 2\nTăng sĭm huach ta tơm si mbơh kan ti Kôranh Brah. Phung ka mâk re tâm dak, ti Kôranh Brah đŏng rhăk. Nar hao luh, nar hao nhâp, ti Kôranh Brah ƀĭt gai.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0416", "title": "GÂP GEH NGIH TÂM ƀON BRAH NDU", "song_number": "416", "lyrics": "GÂP GEH NGIH TÂM ƀON BRAH NDU\n\n\nVerse 1\nGâp geh ngih tâm ƀon Brah Ndu chrat ang lơn ma nar. Gâp geh ngih tâm ƀon Brah Ndu chrat ang lơn ma nar. Gâp geh ngih tâm ƀon Brah Ndu chrat ang lơn ma nar, ngai, ntŭk ngai lơn tâm trôk.\n\nChorus\nKôrah Brah ơi, Kôranh Brah, dăn may kah gĭt ma gâp. Kôranh Brah ơi, Kôranh Brah, dăn may kah gĭt ma gâp. Kôranh Brah ơi, Kôranh Brah, dăn may kah gĭt ma gâp, ngai, ntŭk ngai lơn tâm trôk.\n\nVerse 2\nGâp dơn jêh Yê-su tâm rklaih, ăn May ƀư tâm ban. Gâp dơn jêh Yê-su tâm rklaih, ăn May ƀư tâm ban. Gâp dơn jêh Yê-su tâm rklaih, ăn May ƀư tâm ban. Ri jêng nau Păng kuăl may.\n\nChorus\nKôrah Brah ơi, Kôranh Brah, dăn may kah gĭt ma gâp. Kôranh Brah ơi, Kôranh Brah, dăn may kah gĭt ma gâp. Kôranh Brah ơi, Kôranh Brah, dăn may kah gĭt ma gâp, ngai, ntŭk ngai lơn tâm trôk.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0417", "title": "NAR KANDỠ PHUNG HE MRA SAƠ HAĐĂCH", "song_number": "417", "lyrics": "NAR KANDỠ PHUNG HE MRA SAƠ HAĐĂCH\n\n\nVerse 1\nNar kan-dỡ phung he mra saơ Ha-đăch. Nar kan-dỡ phung he mra saơ Ha-đăch. Nar kan-dỡ phung he mra saơ Ha-đăch, jêng Kôranh ma lĕ rngôch Kôranh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0418", "title": "ĂN NƠM RDJA LAH, \"GÂP KATANG JÊH\"", "song_number": "418", "lyrics": "ĂN NƠM RDJA LAH, \"GÂP KATANG JÊH\"\n\n\nVerse 1\nĂn nơm rdja lah, \"Gâp ktang jêh,\" nơm o-ach lah, \"Gâp ndrŏng jêh,\" nơm chieh măt lah, \"Gâp dơi saơ, mâm Kôranh Brah ƀư an ma gâp.\" Ăn nơm rdja lah, \"Gâp ktang jêh,\" nơm o-ach lah, \"Gâp ndrŏng jêh,\" nơm chieh măt lah, \"Gâp dơi saơ. mâm Kôranh Brah ƀư an ma gâp.\"\n\nChorus\nHô-sa-na, Hô-sa-na, Kon Ƀiăp Păng khĭt jao ma he. Hô-sa-na, Hô-sa-na, Yê-su khĭt lŏ dâk rêh đŏng.\n\nVerse 2\nN'hơr dak jru gâp mra ntrăm ŭm. Nau tih gâp păng rao kloh ƀhiao. Tu nau yỗ jŭr tă bơh trôk. Nơm Tâm Rklaih rŏng gâp hâu ngăn. Gâp ngâm rmok tâm klŏng dak jru. Ti Brah Ndu nơm chông nklaih an. Gâp mprơ rnê nau mprơ tâm rklaih. Yê-su krist hŏ doh nklaih he.\n\nChorus\nHô-sa-na, Hô-sa-na, Kon Ƀiăp Păng khĭt jao ma he. Hô-sa-na, Hô-sa-na, Yê-su khĭt lŏ dâk rêh đŏng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0419", "title": "KLƠ MA LĔ NAU DƠI", "song_number": "419", "lyrics": "KLƠ MA LĔ NAU DƠI\n\nTVCHH 82\n\nVerse 1\nKlơ ma lĕ nau dơi, klơ ma lĕ bri ha-đăch. klơ ma lĕ ntil geh êng, lĕ ndơ njêng jêh rnôk aơ. Klơ lĕ phung gĭt mĭn, nau blau kon bunuyh ta neh ntu. May hŏ geh lor lơn ma neh ntu jêng. Klơ ma lĕ ƀon bri ha-đăch klơ ma lĕ sưng hađăch. Klơ ma lĕ nau hih r-hâl, nau neh ntu ê mâp gĭt năl. Klơ lĕ nau ndrŏng kuăng, ma lĕ drăp khlay ta neh ntu. Mâu hôm geh du ntil rlau lơn ma May. Pâng ndă Păng, dơn anh nau nđêh nji, Păng khĭt bu ntâp, bu mưch r-mot ô-băl. dun lơi Păng, mâu geh nơm rŏng ma Păng. Păng maak sŏk dơn, mĭn rvê ma gâp, yor ma gâp\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0420", "title": "Ơ SI NÔ-EL", "song_number": "420", "lyrics": "Ơ SI NÔ-EL\n\n\nVerse 1\nƠ si Nô-el ơ si Nô-el, may ăt chăt rêh nđâr ƀa-ƀơ. Ơ si Nô-el, ơ si Nô-el, may ăt chăt rêh nđâr ƀa-ƀơ. N'gâng may chăt rêh tâm ăp yăn khay. Nau ueh reh nđâr mra hao ƀa-ƀơ. Ơ si Nô-el, ơ si Nô-el, may ƀư maak nuih n'hâm gâp âk.\n\nVerse 2\nƠ si Nô-el, ơ si Nô-el, may jêng si ueh reh ngăn ngên. Ơ si Nô-el, ơ si Nô-el, may jêng si ueh reh ngăn ngên. Ăn hên nau ang nchrang ueh măt uănh. Nau ueh nchrat ang tâm nar Nô-el. Ơ si Nô-el, ơ si Nô-el, Brah Ndu prăp gâp ndrŏng n'hêl ngăn.\n\nVerse 3\nƠ si Nô-el ơ si Nô-el, dăn may nti gâp tâm Kôranh Brah. Ơ si Nô-el, ơ si Nô-el, ŭnh jrêng may nchrat ang rah vah. May yơh jêng nơm lơp nchat ang ngăn. Knŏng ŭnh jrêng may nchrat ang rah vah. Ơ si Nô-el, ơ si Nô-el, ŭnh jrêng may nchrat ang rah vah.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0421", "title": "RNÊ KÔRANH BRAH KHĬT YOR NAU RŎNG", "song_number": "421", "lyrics": "RNÊ KÔRANH BRAH KHĬT YOR NAU RŎNG\n\n\nVerse 1\nRnê Kôranh Brah, khĭt yor nau rŏng, yor rŏng gâp tât luh dak măt. N'hanh nau rŏng Păng sŏk dơn gâp, yor tih gâp tât Păng hoch mham. Yê-su ơi, mham khlay May hoch, ŭch tâm rklaih gâp. Yê-su ơi, dak măt May luh, yor ŭch tâm rklaih nau tih gâp. Yê-su ơi, May sân săk jăn ŭch tâm chuai gâp. Yê-su ơi, nau tih gâp aơ mâu geh bunuyh yỗ, knŏng May yơh yỗ nau tih gâp. Yê-su ơi, May nhhơr săk jăn ŭch tâm chuai gâp. Yê-su ơi, nau tih gâp aơ, mâu geh bunuyh rklaih, knŏng May yơh rklaih nau tih gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0422", "title": "GÂP MRA MPRƠ MA NƠM TÂM CHUAI GÂP", "song_number": "422", "lyrics": "GÂP MRA MPRƠ MA NƠM TÂM CHUAI GÂP\n\nTC 11\n\nVerse 1\nGâp mra mprơ ma Nơm tâm chuai gâp. khlay ngăn ngên Păng rŏng ma gâp. Klơ si tâm rkăng Păng dơn nau nđêh nji gay gâp klaih bơh nau rtăp rak\n\nChorus\nƠ mprơ hom ma Nơm tâm chuai gâp. Ma mham Păng sâm ntrok rgâl gâp. Si tâm rkăng Păng tăp pong tih gâp, rnon klaih jêh, gâp gŭ đăp mpăn.\n\nVerse 2\nGâp mra mbơh nau khlay nkoch bri aơ. Gâp roh jêh, Păng tĭng joi rklaih. Tâm nau rŏng toyh Păng nđâp nau yỗ, Păng tâm chuai ma he dơm dam\n\nChorus\nƠ mprơ hom ma Nơm tâm chuai gâp. Ma mham Păng sâm ntrok rgâl gâp. Si tâm rkăng Păng tăp pong tih gâp, rnon klaih jêh, gâp gŭ đăp mpăn.\n\nVerse 3\nGâp mra mprơ ma Nơm tâm chuai gâp, ŭch nkoch nau dơi, nau Brah Păng. Nau Păng ăn he dơi đah nau tih, dơi đah nau khĭt, dơi đah n'găr ŭnh\n\nChorus\nƠ mprơ hom ma Nơm tâm chuai gâp. Ma mham Păng sâm ntrok rgâl gâp. Si tâm rkăng Păng tăp pong tih gâp, rnon klaih jêh, gâp gŭ đăp mpăn.\n\nVerse 4\nGâp mra mprơ ma Nơm tâm chuai gâp, Ƀon ueh Păng prăp rŏng ma gâp. Păng djôt gâp tă khĭt ăn rêh tay, gŭ ndrel Kon Brah Ndu nơm ƀa-ƀơ.\n\nChorus\nƠ mprơ hom ma Nơm tâm chuai gâp. Ma mham Păng sâm ntrok rgâl gâp. Si tâm rkăng Păng tăp pong tih gâp, rnon klaih jêh, gâp gŭ đăp mpăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0423", "title": "ƀON LAN OH NÂU KÔNH VA", "song_number": "423", "lyrics": "ƀON LAN OH NÂU KÔNH VA\n\n\nVerse 1\nɃon lan oh nâu kônh va, mbu nơm ŭch geh nau tâm rkaih. Hăn hom ma Yê-su Krist. Păng yỗ an ay may dơm dam. Păng jêng Nơm rŏng lơn lĕ rngôch. Chroh hom gơnh a-ƀaơ ro. Ay may geh nau tâm rklaih ngăn.\n\nVerse 2\nƠ Mbỡ, dăn May yỗ gâp. rêh krit, gŭ krâm tâm r-huh. Nar khay rlao mâu dơi gĭt. Phung jông gông ngloh n'gôr tâm sial, tâm di jêh dăn Kôranh Brah rŏng. Ƀư kloh ăn tâm nuih n'hâm. Dăn Mbỡ iăt hom bâr gâp kuăl.\n\nVerse 3\nChĭng bơr tŭr nteh lơn ngăn. Phung sĭm mpăr mblêng mâu gĭt ntŭk. Kao si bri đơr rơt bơt. Mprơ rnê ndrel pe Brah jêng nguay, Nơm rŏng toyh ma lĕ rngôch he. Ơ ƀon lan yôk yang ơi, gơnh gơnh hom, Kôranh Brah kuăl jêh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0424", "title": "NÔ-EL, MĂNG KÔRANH BRAH DEH JÊH", "song_number": "424", "lyrics": "NÔ-EL, MĂNG KÔRANH BRAH DEH JÊH\n\n\nVerse 1\nNô-el, măng Kôranh Brah deh jêh, ŭch tâm rklaih neh ntu, răm maak ngăn ngên. Nô-el, măng ueh maak ƀa-ƀơ ma neh ntu, ma gâp, maak răm ngăn yơh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0425", "title": "NAU RÊH GÂP NÂM BU SĬM BRI", "song_number": "425", "lyrics": "NAU RÊH GÂP NÂM BU SĬM BRI\n\n\nVerse 1\nNau rêh gâp nâm bu sĭm bri ƀiă-lah mâu geh mbỡ ma nsing, rêh lă lêng tâm bri yôk, ntŭk rdah, nau jêr jŏt. Trong gâp hăn âk nau jêr, âk so bri dôl ŭch chuêng. Nau rêh gâp geh nau jêr jêh ri nau dăch rai.\n\nChorus\nBrah Yê-su bêng ma nau rŏng. Păng mâu nhhuach dơn nau rêh ni yor gâp. Păng joi gâp tât ŭch chông gâp. Păng djôt gâp sĭt ndrel gŭ ntŭk đăp mpăn. Păng mât rmai gâp đăp mpăn ngăn, njŭn gâp ta ntŭk pih nse, n'hor dak r-sang nđik ueh. Nau rêh gâp jêng kloh, gâp sa hơm nhêt mpay.\n\nVerse 2\nAƀaơ ri tâm huêng nau rêh gâp mâu hôm geh ntil nau rvê ôh, yor lah geh Brah Yê-su, păng mât rmai ăp nar. Nđâp lah geh nau ŭch ndơm mâu lah nau rêh ni tât, geh păng tâm chuai jêh gâp ma ti nau brah păng.\n\nChorus\nBrah Yê-su bêng ma nau rŏng. Păng mâu nhhuach dơn nau rêh ni yor gâp. Păng joi gâp tât ŭch chông gâp. Păng djôt gâp sĭt ndrel gŭ ntŭk đăp mpăn. Păng mât rmai gâp đăp mpăn ngăn, njŭn gâp ta ntŭk pih nse, n'hor dak r-sang nđik ueh. Nau rêh gâp jêng kloh, gâp sa hơm nhêt mpay.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0426", "title": "GEH DU HUÊ BUNUYH CHIEH MĂT", "song_number": "426", "lyrics": "GEH DU HUÊ BUNUYH CHIEH MĂT\n\n\nVerse 1\nGeh du huê bunuyh chieh măt gŭ ta meng trong. Nau rêh păng knŏng dăn, dăn prăk bu. Lah păng tăng bu nkoch geh Yê-su hăn rgăn tât ta nây, păng ntơm nter kuăl huy ma Brah Yê-su Yê-su ôp, \"Mâm nau may ŭch\" Bunuyh chieh măt lah, \"Ăn măt gâp dơi saơ ang\" Yê-su lah, \"Hăm hom may. Nau may rnơm ƀư bah an jêh măt may.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0427", "title": "DÔL RGĂN NEH NTU NGO AƠ", "song_number": "427", "lyrics": "DÔL RGĂN NEH NTU NGO AƠ\n\n\nVerse 1\nDôl rgăn neh ntu ngo aơ, gâp jêng dơm dam tơ-lah mâu geh nau rŏng. Nau rŏng Kôranh Brah toyh ngăn. Lơi ƀon chrêk rmah sân săk yor gâp. Ăn nau rŏng he chuat tâm Yê-su, nau rŏng mâu rgâl nar aơ jêh ri n'ho ro. Ăn nau rŏng he chuat tâm Yê-su, nau rŏng đăp mpăn yor geh Yê-su.\n\nVerse 2\nDôl rgăn neh ntu rngot aơ, gâp ăt ton hăn tâm nau rŏng Brah Yê-su. Păng mra ăn gâp đăp mpăn. Păng mâu mâp lơi gâp jêng kon đơi. Ăn nau rŏng he uănh ta Yê-su, nau rŏng mâu rgâl nar aơ jêh ri n'ho ro. Ăn nau rŏng he uănh ta Yê-su, nau rŏng đăp mpăn yor geh Yê-su.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0428", "title": "KĂL E JÂNG GÂP CHUAT", "song_number": "428", "lyrics": "KĂL E JÂNG GÂP CHUAT\n\n\nVerse 1\nKăl e jâng gâp chuat, gâp nkhah đah may, Ƀiă-lah Mbỡ rŏng joi kâp kơl gâp. Nau rêh gâp a-ƀaơ đăp mpăn ueh maak. Geh Brah Yê-su gŭ tâm gâp aơ.\n\nChorus\nYê-su rŏng gâp, Kôranh Brah mâu mbeh ôh. Păng rŏng ma gâp, Kôranh Brah rŏng mro. Aƀaơ gâp nhhơr nau rêh gâp ma may, Yor nau ang Kôranh Brah ăn jêh ma he.\n\nVerse 2\nNuih n'hâm gâp ton njŭn bunuyh ma Kôranh Brah, Dăn Mbỡ nau rŏng ndreng chuat mâu rlu. Nau rêh Brah Yê-su, nau rŏng mbêng ler, tâm nau gâp mprơ, nuih n'hâm maak mro.\n\nChorus\nYê-su rŏng gâp, Kôranh Brah mâu mbeh ôh. Păng rŏng ma gâp, Kôranh Brah rŏng mro. Aƀaơ gâp nhhơr nau rêh gâp ma may, Yor nau ang Kôranh Brah ăn jêh ma he.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0429", "title": "TÂM RNÊ MA NƠM RŎNG GÂP HÂU", "song_number": "429", "lyrics": "TÂM RNÊ MA NƠM RŎNG GÂP HÂU\n\n\nVerse 1\nTâm rnê ma Nơm rŏng gâp hâu ngăn ngên, jêng Nơm tâm rklaih gâp bơh nau rngot nau rvê neh ntu. Gâp răm maak. Nuih n'hâm gâp geh nau đăp mpăn, nuih n'hâm gâp geh nau May yỗ, nuih n'hâm gâp geh nau May rŏng. Yê-su ơi, lơi May gŭ ngai. Yê-su ơi, lơi May lơi gâp. Dăn May gŭ n'hanh gâp ƀa-ƀơ. Yê-su ơi, nuih n'hâm gâp maak. Yê-su ơi, nuih n'hâm gâp rŏng. Yê-su ơi, lơi May lơi gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0430", "title": "Ơ NƠM RŎNG GÂP ƠI", "song_number": "430", "lyrics": "Ơ NƠM RŎNG GÂP ƠI\n\n\nVerse 1\nƠ Nơm rŏng gâp ơi, gâp ŭch kâp saơ May ƀa-ƀơ. Knŏng May yơh gâp rŏng, gâp mâu ŭch May ngai đah gâp. Ơ Nơm rŏng gâp ơi. Knŏng May yơh jêng Nơm bonh gâp. Nđâp ta klăng nau rngot, gâp ăt maak tơ-lah geh May.\n\nChorus\nKnŏng May yơh jêng Nơm gâp rŏng. Knŏng May yơh jêng Nơm bonh gâp. Knŏng May yơh gâp nkah ƀa-ƀơ. Knŏng May yơh jêng Nơm gâp rnơm. Gâp mâu ŭch nau rŏng tâm nkhah. Gâp mâu ũch nau rŏng kro rngot. Ƀiă-lah nau rŏng ăt hâk maak, Ŭch nau rŏng hôm gŭ răp jăp.\n\nVerse 2\nƠ Kôranh Brah Yê-su, gâp ŭch kâp saơ May ƀa-ƀơ. Knŏng May yơh gâp rŏng, gâp mâu ŭch May ngai đah gâp. Ơ Kôranh Brah Yê-su, Knŏng May yơh jêng Nơm bonh gâp. Nđâp ta klăng nau rngot, gâp ăt maak tơ-lah geh May.\n\nChorus\nKnŏng May yơh jêng Nơm gâp rŏng. Knŏng May yơh jêng Nơm bonh gâp. Knŏng May yơh gâp nkah ƀa-ƀơ. Knŏng May yơh jêng Nơm gâp rnơm. Gâp mâu ŭch nau rŏng tâm nkhah. Gâp mâu ũch nau rŏng kro rngot. Ƀiă-lah nau rŏng ăt hâk maak, Ŭch nau rŏng hôm gŭ răp jăp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0431", "title": "RŎNG YÊ-SU, NHHƠR NAU RÊH MA PĂNG", "song_number": "431", "lyrics": "RŎNG YÊ-SU, NHHƠR NAU RÊH MA PĂNG\n\n\nVerse 1\nRŏng Yê-su, nhhơr nau rêh ma Păng. Rŏng Yê-su, rêh pah kan ma Păng. Hăn hom he, mbơh A-moh Yê-su. Gĭt Yê-su, rêh ma Păng, rŏng ma Păng. Nau rŏng Yê-su, mâu geh ndơ dơi ntĭt. Păng rŏng he ŭch khĭt rklaih he. Hăn hom he, mbơh A-moh Yê-su, gĭt Yê-su, rêh ma Păng, rŏng ma păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0432", "title": "YÊ-SU KRIST JÊNG TRONG NJŎ", "song_number": "432", "lyrics": "YÊ-SU KRIST JÊNG TRONG NJŎ\n\n\nVerse 1\nYê-su Krist jêng trong njŏ Yê-su jêng nau ngơi ngăn, Yê-su jêng nau rêh mro, Păng yơh jêng Kôranh ma gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0433", "title": "DÔL GÂP RŎNG BU", "song_number": "433", "lyrics": "DÔL GÂP RŎNG BU\n\n\nVerse 1\nDôl gâp rŏng bu, gâp vay nkah săk ƀa-ƀơ. Dôl gâp rŏng Păng, Amoh Păng djôt tâm nuih n'hâm. Kah gĭt mâu chuêl, Amoh Păng mâu hôm dơi roh. Nsrôih blau rom Păng ƀư Kôranh tâm nuih n'hâm gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0434", "title": "BRAH NDU KÔRANH BRAH JÊNG MĬT JIĂNG GÂP", "song_number": "434", "lyrics": "BRAH NDU KÔRANH BRAH JÊNG MĬT JIĂNG GÂP\n\n\nVerse 1\nBrah Ndu Kôranh Brah jêng mĭt jiăng rŏng gâp na-nễ. Rŏ trong tâm mir hên hăn, hên nkoch bri rjai. Bâr mbung hên mprơ, kuăn ti dŭt ma nau gơm răm. Brah Ndu ndrel gâp hăn nsong jŭm bri lam neh. Bâr mbung hên mprơ, kuăn ti ma nuih n'hâm gơm răm. Brah Ndu ndrel gâp hăn nsong jŭm bri lam neh.\n\nVerse 2\nBrah Ndu ndrel gâp, hên mra hăn nsong du ai ndrel. Nâm mĭt jiăng ueh hên hăn, hên nkoch bri rjai. Neh ntu mra roh, ma lĕ rngôch ndơ gŭ tâm Păng. Brah Ndu ndrel gâp hôm gŭ ƀa-ƀơ n'ho ro. Neh ntu mra roh, ma lĕ rngôch ndơ gŭ tâm Păng. Brah Ndu ndrel gâp hôm gŭ ƀa-ƀơ n'ho ro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0435", "title": "TRÔM MÔCH JRU YÊ-SU GŬ KHĬT", "song_number": "435", "lyrics": "TRÔM MÔCH JRU YÊ-SU GŬ KHĬT\n\n\nVerse 1\nTrôm môch jru Yê-su gŭ khĭt. Lôch pe nar Păng dâk rêh tay, gay tâm mpơl nau brah nau dơi, Păng tâm lơh đah brah sa-tan. Dơi Brah Yê-su jêh đah brah mhĭk.\n\nVerse 2\nTông păr ueh nklỡ jêh rplay lŭ. Nau khĭt mâu dơi đah Păng ôh, Uănh hom, Kôranh Brah luh bơh môch, Păng rêh chrêk r-mah n'ho ro. Păng rêh chrêk r-mah n'ho ro.\n\nVerse 3\nPhung bunuyh gŭ n'gơr uănh tâm trôk, uănh Kôranh Brah luh lŏ rêh jêh. Tâm nau mprơ tâm rnê Brah Ndu, he ŭch kâp ƀon ueh tâm trôk. He ŭch kâp ƀon ueh tâm trôk.\n\nVerse 4\nMpông pêr toyh ƀon ueh pơk jêh, rom nơm dơi đah nau tâm lơh. Păng lăp gŭ ta klơ sưng hađăch. Păng chiă uănh ƀa-ƀơ n'ho ro. Păng chiă uănh ƀa-ƀa n'ho ro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0436", "title": "MÂM JRU NGĂN NGÊN MBỠ RŎNG MA HE", "song_number": "436", "lyrics": "MÂM JRU NGĂN NGÊN MBỠ RŎNG MA HE\n\n\nVerse 1\nMâm jru ngăn ngên Mbỡ rŏng ma he toyh jru dŭt n'hâm mâu dơi veh, tât Păng sâm ăn Kon dul Păng Nơm, ŭch ƀư he jêng drăp khlay Păng. Dŭt ji ngăn ngên Păng Nơm tăch n'hâm, Mbỡ Păng ndôn măt ngai đah Păng. Păng dơn sôt rmanh dŭt krit mƀât ngăn djôt nau chrêk rmah ma kon bunuyh.\n\nVerse 2\nRi uănh bu pâng jêh Kôranh Brah he, anh nau tih gâp klơ mlik Păng. Nau prêng gâp tăng bâr mưch gâp nơm, Păng ndă ma dơn nau mưch rmot. Yor nau tih gâp Păng ƀư pô nây, gay ŭch ƀư lôch tâm kan Păng. Păng khĭt gay djôt nay rêh ma gâp. Gâp gĭt nau nĕ hŏ lôch jêh.\n\nVerse 3\nGâp mâu hôm rnê êng gâp nơm ôh, nau geh, nau dơi, nau gĭt mĭn. Knŏng gâp tâm rnê Brah Yê-su Krist, Păng khĭt jêh ri hŏ dâk rêh. Mâm ƀư gâp dơi Păng ăn dơm dam? Gâp mâu hôm blau mplỡ sĭt lah. Gâp gĭt nau aơ lĕ nuih n'hâm gâp. Rmanh Păng sâm chuai nau tih gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0437", "title": "DU HUÊ BRAH KRIST", "song_number": "437", "lyrics": "DU HUÊ BRAH KRIST\n\n\nVerse 1\nDu huê Brah Krist, ntŭk gâp nâp rnơm. Păng jêng nau ang, ƀư ktang đô he. Păng jêng lŭ nâp, ntŭk neh klĕr ktang, nđâp phŭt nar phang ăt nâp mâu rlâm. Nau rŏng dŭt prêh, nau đăp mpăn jru. Mâu hôm gâp klach, ăt gâp gŭ nâp. Yê-su bonh leng tâm lĕ ntil tât. Knŏng tâm nau rŏng Brah Krist gâp dơi.\n\nVerse 2\nDu huê Brah Krist, Nơm sŏk nglay săk. Brah Ndu Nơm ngăn, jan săk oh bê. Păng rŏng gâp hâu, ăn nau sŏng srăng. Păng văch sâm rklaih phung tâm mưch rmot. Yê-su dơn khĭt ta si tâm rkăng, ntrok an ma he nau Brah Ndu rmal. Lĕ nau tih he Păng tâm tang an. Brah Krist sâm khĭt, gâp dơi gŭ rêh.\n\nVerse 3\nBu hŏ tâp jêh săk Păng tâm môch. Nau ang ma neh ntu lĕ nkŭm jêh. Nau rtah mra tât tâm nau chrêk rmah. Păng dâk rêh jêh, luh tă bơh môch, Păng yor dơi jêh đah mpôch nau khĭt, nau tih mâu hôm dơi kuăn gâp ôh. Aƀaơ ri gâp jêng rêh knŏng ma Păng. Brah Krist rvăt gâp ma mham Păng Nơm.\n\nVerse 4\nMâu hôm tih mhĭk, mâu hôm klach krit, nau dơi Brah Krist ăn jêh ma gâp. Du bông gâp rêh tât nar tăch n'hâm, Yê-su ntĭng gâp ăp nar ăp năm. Brah mhĭk ndơm kđôi, bunuyh ƀai kđôi lĕ, mâu hôm geh nơm mphâk gâp bơh Păng. tâm nar Păng plỡ kuăl gâp hăn sĭt. Tâm nau dơi Brah Krist gâp mra dơi.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0438", "title": "YÊ-SU KRIST JÊNG MĬT JIĂNG GÂP", "song_number": "438", "lyrics": "YÊ-SU KRIST JÊNG MĬT JIĂNG GÂP\n\nTC 81\n\nVerse 1\nYê-su jêng mĭt jiăng gâp, Păng chiă uănh lĕ nau rêh gâp, Păng jêng ueh reh lơn ma âk rbăn rmưn phung êng. Gâp uănh Yê-su jêng kao ueh lơn, Ƀâu kah lĕ r-ngôch. Krist tâm rgâl nuih n'hâm tih gâp, an jêng kloh ueh. Geh nau rngot, Yê-su bonh leng; rŭng răng, Păng ăn đăp mpăn. Păng lah \"Jao lĕ ndơ jâk may, ăn Gâp anh.\" Yê-su jêng kao ueh lơn, Păng jêng mănh toyh sol tât ôi. Păng jêng ueh reh lơn ma âk rbăn rmưn phung êng.\n\nVerse 2\nYê-su anh nau tih gâp, rao kloh gâp ma mham khlay Păng. Si tâm rkăng jêng mpêr king n'gang gâp bơh brah mhĭk. Yor Krist gâp dun lĕ rngôch âk nau ndơm bơh rnglay săk kơnh. Păng ăn nau brah chiă uănh nuih n'hâm gâp đăp mpăn. Nđâp tơ-lah bu gơm mưch gâp, lah Sa-tan ndơm hâu ngăn, knŏng ti Yê-su Krist dơi king gâp đăp mpăn. Yê-su jêng kao ueh lơn, Păng jêng mănh toyh sol tât ôi. Păng jêng ueh reh lơn ma âk rbăn rmưn phung êng.\n\nVerse 3\nGâp rêh yor ma nau chroh tông bâr păng ma lĕ nuih n'hâm. Brah Yê-su păng mâu cha-lơi gâp gŭ êng ôh. Unh Brah Păng king n'gang gâp đăp mpăn ngăn mâu rung răng ôh. Yor Păng ăn Ma-na huêng gâp hơm ra-ơm ngăn. Gâp mra saơ muh măt Brah Yê-su tât tâm ƀon ueh Păng. Tâm ƀon ueh bêng ma nau răm maak hâu ngăn. Yê-su jêng kao ueh lơn, Păng jêng mănh toyh sol tât ôi. Păng jêng ueh reh lơn ma âk rbăn rmưn phung êng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0439", "title": "DÔL NEH NTU JI RÂM RMOK NGÂM", "song_number": "439", "lyrics": "DÔL NEH NTU JI RÂM RMOK NGÂM\n\n\nVerse 1\nDôl neh ntu ji râm r-mok ngâm, mâu hôm dơi saơ, klơ bâr mbung nau gơm. Klơ trôk prêh Yê-su mra tăng saơ. Păng văch djôt rklaih yỗ âk nơm. Ăn ma bunuyh nau rŏng ueh n'ho ro, nau đăp mpăn, bâr mprơ mro ăp yăn. Lôch nau rêh păng vơt âk bu-nuyh hao ƀon ueh, rbăn năm rêh n'hanh păng.\n\nVerse 2\nMprơ maak hom, Hađăch Yê-su văch jêh. Maak ƀư ha-đăch nuih n'hâm mbu dơn păng. Ăn đăp mpăn ma he mro mâu rlu. He klaih jêh đah nau rêh ni. Ăn ma bunuyh nau rŏng ueh n'ho ro, nau đăp mpăn, bâr mprơ mro ăp yăn. Lôch nau rêh păng vơt âk bu-nuyh hao ƀon ueh, rbăn năm rêh n'hanh păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0440", "title": "PHUNG KON SE MHE UEH", "song_number": "440", "lyrics": "PHUNG KON SE MHE UEH\n\n\nVerse 1\nPhung kon se mhe ueh prăp dơn Yê-su ăn. Phung kon se mhe ueh gŭ jŭm păng răm maak. Phung kon se mhe ueh mprơ jêh ri tông bâr. Dăn Kôranh Brah Nơm ăn nau rŏng ueh mbêng ler.\n\nVerse 2\nPhung kon se mhe ueh, kaƀah nau blau nau ktang. Ăn he srôih nti samƀŭt gay pah kan Kôranh Brah. Uănh nau Brah Ndu Ngơi, Lơi chuêl ôh mbơh sơm. Ăn he gơih nđơr hom, phung kon se mhe ueh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0441", "title": "GÂP RŎNG NAU NKOCH BRI", "song_number": "441", "lyrics": "GÂP RŎNG NAU NKOCH BRI\n\n\nVerse 1\nGâp rŏng nau nkoch bri khlay hâu ngăn, Nau Brah Ndu Ngơi nchih jêh. Brah Yê-su nơm rŏng yỗ nđach ma gâp, dơn nau khĭt ntrok an ma gâp.\n\nVerse 2\nDak rdu, du mlâm bĭ êp dak krong, oh bê Mô-ih hôm bêch. Tât du huê bu druh kon hađăch Ê-jip, ăn bu chông Mô-ih djôt sĭt.\n\nVerse 3\nĐa-niel jêh ri pe mĭt jiăng păng, bu klŭp tâm nklang ŭnh hit. Răp jăp mâu klach khĭt lĕ ntil nau tât, đăp mpăn chuat hăn dôl ŭnh hit.\n\nVerse 4\nYô-na mâu tông bâr nau Kôranh Brah, hăn nder du krap t'reh si. Kôranh Brah đă ka kuăng rnguăn Y-Yô-na tât pe nar ka jrih klơ kơh.\n\nVerse 5\nY-Pôl đăp mpăn bêch tâm ndrung n'gar, mprơ nteh ndrel Y-Si-laih. Tâm ndrung n'gar geh nau râm sâr krit kir, kôranh ndrung saơ chroh ma Yê-su.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0442", "title": "MAAK YĂN VAI MHE", "song_number": "442", "lyrics": "MAAK YĂN VAI MHE\n\n\nVerse 1\nMaak yăn vai mhe. Mprơ tâm rnê Kôranh Brah, yor Păng ăn gâp du năm rlau đăp mpăn. Nar jêh neh ntu bêng ma nau ueh uĭn. Kôranh Brah kơl gâp, rêh maak tâm r-nê. Maak yăn vai mhe. Mprơ yơk rnê Kôranh Brah, yor ăp năm khay bêng ma nau ƀâu kah. Maak yăn vai mhe, aơ nau Păng kơl gâp. Ŭch Kôranh Brah ăt tât njŭn leo gâp. Ŭch Kôranh Brah ăt tât njŭn leo gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0443", "title": "NAU TÂM RNÊ", "song_number": "443", "lyrics": "NAU TÂM RNÊ\n\nTC 678\n\nVerse 1\nNtoh bâr răm maak, tâm rnê Yê-su lôch njăr rêh. Ăn âk nau ueh, nau yỗ rlau lơn dak rlai. Kah gĭt ƀa-ƀơ ăp nar yor Kôranh Brah njŭn leo, têk ndrêng phung biăp tâm nau rŏng Păng ƀa-ƀơ.\n\nChorus\nNau tâm r-nê gâp nhhơr ma May tâm pot bâr mprơ Ha-lê-lu-ya! Nuih n'hâm tâm r-nê Ha-lê-lu-ya! ma nuih n'hâm nau yok, Nau tâm... Rnê vah vang klơ trôk, njăr rêh nhhơr ƀâu kah Ha-lê-lu-ya! Yơk mbah Kôranh Brah lôch njăr rêh.\n\nVerse 2\nDu năm rlau jêh, yor Mbỡ chiă uănh nau răp jăp. Nsĭt lah ma gâp nau ueh, ƀư bah nau ji. Kôranh Brah êp gâp, nuih n'hâm đăp mpăn, mâu rngot ôh, nâp rjăp ma Mbỡ, nar măng geh Păng njŭn leo.\n\nChorus\nNau tâm r-nê gâp nhhơr ma May tâm pot bâr mprơ Ha-lê-lu-ya! Nuih n'hâm tâm r-nê Ha-lê-lu-ya! ma nuih n'hâm nau yok, Nau tâm... Rnê vah vang klơ trôk, njăr rêh nhhơr ƀâu kah Ha-lê-lu-ya! Yơk mbah Kôranh Brah lôch njăr rêh.\n\nVerse 3\nKôranh Brah rŏng ơi, mâm gâp dơi tĭng nau tâm rnê. Tâm nau yỗ May ăn jêh ma gâp nar aơ. Nsrôih tĭng ndỗ May, ăp nar mbơh Amoh Brah Yê-su, njŭn sĭt neh ntu, plỡ ma nau rŏng Kôranh Brah.\n\nChorus\nNau tâm r-nê gâp nhhơr ma May tâm pot bâr mprơ Ha-lê-lu-ya! Nuih n'hâm tâm r-nê Ha-lê-lu-ya! ma nuih n'hâm nau yok, Nau tâm... Rnê vah vang klơ trôk, njăr rêh nhhơr ƀâu kah Ha-lê-lu-ya! Yơk mbah Kôranh Brah lôch njăr rêh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0444", "title": "NAU RŎNG BAR HÊ", "song_number": "444", "lyrics": "NAU RŎNG BAR HÊ\n\n\nVerse 1\nNau rŏng bar hê jêng rŏng n'hêl ngăn. Nau rŏng bar hê jêng ueh ngăn ngên. Ndruh ndăm răm maak tâm ngih bu jao, tâm nau rêh nơm Brah. Nau ton bar hê jêng ngăn ƀa-ƀơ. Lĕ nau rêh aơ mâu nkhah ngai ôh. Ƀư maak ƀa-ƀơ tâm nau kloh ueh, mbah ma Brah Ndu Mbỡ.\n\nChorus\nDăn ma Brah Ndu gŭ ndrel ma khân may. Nau rŏng ueh maak, mâu mâp rgâl ôh. Dăn ma Brah Ndu, nkhŭt âk nau ueh uĭn, tâm lĕ nau rêh mra ueh ƀa-ƀơ.\n\nVerse 2\nNau rêh bar hê tâm rnglăp jêng nguay. Nau rêh bar hê ƀư maak Brah Ndu. N'hanh nuih n'hâm maak tâm rnê Yê-su, Nơm ăn nau ƀun lap. Lơi ƀư lă lêng, tâm gop răp jăp, nđâp geh jêr tât, ăt rnê Brah Ndu. Nđâp geh nau dơi, jao ma Yê-su. Păng ăn nau răp jăp.\n\nChorus\nDăn ma Brah Ndu gŭ ndrel ma khân may. Nau rŏng ueh maak, mâu mâp rgâl ôh. Dăn ma Brah Ndu, nkhŭt âk nau ueh uĭn, tâm lĕ nau rêh mra ueh ƀa-ƀơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0445", "title": "KAN JÊNG UR SAI BUNUYH HE", "song_number": "445", "lyrics": "KAN JÊNG UR SAI BUNUYH HE\n\n\nVerse 1\nKan jêng ur sai bunuyh he luh bơh yê-hô-va. Yê-hô-va saơ bu klâu gŭ êng mâu maak ôh.\n\nChorus\nDăn ma Brah Yê-hô-va yỗ uănh ma bar hê aơ, jêh ri mât ton nau ueh uĭn ma ur sai mhe.\n\nVerse 2\nTâm n'gar Ê-đen ueh ri Yê-hô-va lŏ njêng păng jêng bar he, jêng ur sai Yê-hô-va njêng.\n\nChorus\nDăn ma Brah Yê-hô-va yỗ uănh ma bar hê aơ, jêh ri mât ton nau ueh uĭn ma ur sai mhe.\n\nVerse 3\nNơm kơl nây jêng bu ur, amoh păng H'-Ê-va, du huê nơm kơl gŭ ndrel đah Y A-đam yơh.\n\nChorus\nDăn ma Brah Yê-hô-va yỗ uănh ma bar hê aơ, jêh ri mât ton nau ueh uĭn ma ur sai mhe.\n\nVerse 4\nYê-hô-va geh nau maak gŭ ndrel n'hanh khân păng tâm n'gop ăn khân păng tâm nau rŏng n'ho ro ngăn.\n\nChorus\nDăn ma Brah Yê-hô-va yỗ uănh ma bar hê aơ, jêh ri mât ton nau ueh uĭn ma ur sai mhe.\n\nVerse 5\nUr sai Yê-hô-va dơn tâm gop yor nau rŏng mra geh nau mât ton, ndrel nau ueh uĭn n'hêl ngăn.\n\nChorus\nDăn ma Brah Yê-hô-va yỗ uănh ma bar hê aơ, jêh ri mât ton nau ueh uĭn ma ur sai mhe.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0446", "title": "Ơ YÊ-HÔ-VA ƠI", "song_number": "446", "lyrics": "Ơ YÊ-HÔ-VA ƠI\n\n\nVerse 1\nƠ Yê-hô-va ơi, gâp nhhơr huêng gâp ma May. Ơ Yê-hô-va ơi, gâp nhhơr huêng gâp ma May. Ơ Brah Ndu, gâp rnơm ma May. Lơi ta ăn gâp prêng ôh, lơi ta ăn phung rlăng mhĭk geh nau dơi đah gâp.\n\nVerse 2\nMbu gĭt nsing ma May geh nau rŭng răng mâu rdja. Mbu gĭt nsing ma May, geh nau rŭng răng mâu rdja. Ơ Brah Ndu, gâp rnơm ma May. Lơi ta ăn gâp prêng ôh, lơi ta ăn phung rlăng mhĭk geh nau dơi đah gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0447", "title": "RNÔK NÂY TÂM N'GAR Ê-ĐEN", "song_number": "447", "lyrics": "RNÔK NÂY TÂM N'GAR Ê-ĐEN\n\n\nVerse 1\nRnôk nây tâm n'gar Ê-đen kăl e Kôranh Brah tâm rnglăp bar hê. Rnôk nây geh rbăn phung sĭm mpăr her răm rhơn ma-ak râm trôk.\n\nChorus\nMât ton ma bar hê ăt rŏng ƀa-ƀơ. Mât ton bar hê tanh nau rŏng ueh maak. Rêh đăp mpăn tâm Kôranh Brah đah nau rŏng n'hêl ngăn. Nđâp rgăn nau jâk jêr ât mâu lĕ geh tâm nkhah.\n\nVerse 2\nKon Bunuyh ntơm bơh nar nây geh jêh nau rŏng tâm n'gar Ê-đen. Lĕ năm khay nar rlau jêh nau rŏng rdơ rbăn hôm maak ƀa-ƀơ.\n\nChorus\nMât ton ma bar hê ăt rŏng ƀa-ƀơ. Mât ton bar hê tanh nau rŏng ueh maak. Rêh đăp mpăn tâm Kôranh Brah đah nau rŏng n'hêl ngăn. Nđâp rgăn nau jâk jêr ât mâu lĕ geh tâm nkhah.\n\nVerse 3\nTâm ăp ntŭk rgăn jêh, pô ri tâm ntŭk nây geh âk ntŭk rgâl. Ƀiă lah geh âk nuih n'hâm rŭng răng, tâm nau rŏng ăt răp jăp.\n\nChorus\nMât ton ma bar hê ăt rŏng ƀa-ƀơ. Mât ton bar hê tanh nau rŏng ueh maak. Rêh đăp mpăn tâm Kôranh Brah đah nau rŏng n'hêl ngăn. Nđâp rgăn nau jâk jêr ât mâu lĕ geh tâm nkhah.\n\nVerse 4\nTâm nar rnôk ueh maak aơ jêng nar maak Kôranh Brah hŏ săch jêh. Nau rŏng khân păng bar hê hŏ ton jêh nklang ntŭk ma nau yơk.\n\nChorus\nMât ton ma bar hê ăt rŏng ƀa-ƀơ. Mât ton bar hê tanh nau rŏng ueh maak. Rêh đăp mpăn tâm Kôranh Brah đah nau rŏng n'hêl ngăn. Nđâp rgăn nau jâk jêr ât mâu lĕ geh tâm nkhah.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0448", "title": "NAU NKOCH BRI AƠ RNÔK Ê GEH MĂNH", "song_number": "448", "lyrics": "NAU NKOCH BRI AƠ RNÔK Ê GEH MĂNH\n\n\nVerse 1\nNau nkoch bri aơ rnôk ê geh mănh tâm trôk, ê yôk prêh, ê dak krong, neh ntu lŏng hŏng, ê saơ tŭk tâm klơ trôk. Kan nsih jêng tă Ndu Brah Nơm. Kôranh Brah ăn gâp rêh ta neh ntu. Păng ton gŭ ndrel n'hanh gâp ƀa-ƀơ. Păng rŏng ma gâp đah nau Păng rŏng n'ho ro, đăp mpăn răm maak tâm Kôranh Brah.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0449", "title": "TÂM AMOH BRAH YÊ-SU", "song_number": "449", "lyrics": "TÂM AMOH BRAH YÊ-SU\n\n\nVerse 1\nTâm amoh Brah-Yê su phung he jêng du oh nur ndrel. Tâm amoh Brah Yê-su, phung he jêng du rnăk vâl. Tâm Amoh Brah Yê-su, phung he jêng nglay săk tâm Krist. Rŏng tâm rnglăp jêng nguay, nâm Kôranh Brah hŏ nti ma he.\n\nVerse 2\nGơnh oi dâk hom he, hơi phung he jêng du oh nur ndrel. Ăn he kuăn ti ndrel, phung he jêng du rnăk vâl. Ăn he mbak klơ mlĭk, phung he jêng nglay săk tâm Krist. Rŏng tâm rnglăp jêng nguay, nâm Kôranh Brah hŏ nti ma he.\n\nVerse 3\nĂn he gơnh gŭ hom phung he jêng du oh nur ndrel. Lĕ rngôch ndra ti ndrel, phung he jêng du rnăk vâl. Bar hê tâm ŭt ndrel, phung he jêng nglay săk tâm Krist. Rŏng tâm rnglăp jêng nguay, nâm Kôranh Brah hŏ nti ma he.\n\nVerse 4\nƠ maak hâu ngăn ngên phung he jêng du oh nur ndrel. Ơ maak hâu ngăn ngên, phung he jêng du rnăk vâl. Ơ maak hâu ngăn ngên, phung he jêng nglay săk tâm Krist. Rŏng tâm rnglăp jêng nguay, nâm Kôranh Brah hŏ nti ma he.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0450", "title": "DĂN HUÊNG UEH MBÊNG LER", "song_number": "450", "lyrics": "DĂN HUÊNG UEH MBÊNG LER\n\n\nVerse 1\nDăn Huêng Ueh mbêng ler lăp tâm n'hâm kon mông aơ. Jut lơi âk nau tih, ƀư rêh mhe tâm n'hâm huêng. Đah n'hâm huêng răm maak huêng kon nchrêng mprơ rnê Mbỡ. Nhhơr săk kon tâm ti Mbỡ rêh Mbỡ ơi.\n\nVerse 2\nKŭnh dăn Mbỡ dêh rhêt ndrêng njŭn nhuat kon ăp nar. Kơl kon mro êp Mbỡ nsing tông nau Mbỡ hŏ ntĭm. Têk njŭn âk huêng bunuyh hôm mĭn rvê tâm nau tih. Văch êp Mbỡ dêh rhêt, dơn nau tâm rklaih.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0451", "title": "VĂCH TA AƠ, KÔRANH BRAH", "song_number": "451", "lyrics": "VĂCH TA AƠ, KÔRANH BRAH\n\n\nVerse 1\nVăch ta aơ, Kôranh Brah, văch ta aơ. Văch ta aơ, Kôranh Brah, văch ta aơ. Văch ta aơ, Kôranh Brah, văch ta aơ. Kôranh Brah, văch ta aơ.\n\nVerse 2\nHên mbơh sơm, Kôranh Brah, hên mbơh sơm. Hên mbơh sơm, Kôranh Brah, hên mbơh sơm. Hên mbơh sơm, Kôranh Brah, hên mbơh sơm. Kôranh Brah, hên mbơh sơm.\n\nVerse 3\nHên kâp gân, Kôranh Brah, hên kâp gân. Hên kâp gân, Kôranh Brah, hên kâp gân. Hên kâp gân, Kôranh Brah, hên kâp gân. Kôranh Brah, hên kâp gân.\n\nVerse 4\nPlỡ jŭr đŏng, Kôranh Brah, plỡ jŭr đŏng. Plỡ jŭr đŏng, Kôranh Brah, plỡ jŭr đŏng. Plỡ jŭr đŏng, Kôranh Brah, plỡ jŭr đŏng. Kôranh Brah, plỡ jŭr đŏng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0452", "title": "AƠ JÊNG NAU GÂP DŬT ŬCH", "song_number": "452", "lyrics": "AƠ JÊNG NAU GÂP DŬT ŬCH\n\n\nVerse 1\nAơ jêng nau gâp dŭt ŭch yơk mbah ma May. Kôranh Brah, lĕ nuih n'hâm gâp yơk mbah May. Lĕ nau geh gĭt tâm gâp gâp tâm rnê May. Lĕ nau gâp tâm rnê, knŏng ma May. Kôranh Brah, gâp jao lĕ nuih n'hâm huêng gâp ma May. Gâp rêh knŏng du huê May dơm. Ăp tỡ n'hâm gâp sŏk nsôr, tâm ăp tỡ gâp kah r-ngăl, dŏng gâp tâm Kôranh Brah Nơm.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0453", "title": "RGÂL AN NUIH N'HÂM GÂP", "song_number": "453", "lyrics": "RGÂL AN NUIH N'HÂM GÂP\n\n\nVerse 1\nRgâl an nuih n'hâm gâp, ƀư ăn păng di mro. Rgâl gâp, ơ Brah Ndu năng gâp jêng kơt May. Rgâl an nuih n'hâm gâp, ƀư ăn păng di mro. Rgâl gâp, ơ Brah Ndu năng gâp jêng kơt May. May jêng Nơm mon glah, gâp jêng nâm ŭk. Mon gâp jêh ri nser gâp, nĕ yơh nau gâp dăn. Rgâl an nuih n'hâm gâp, ƀư ăn păng di mro. Rgâl gâp, ơ Brah Ndu năng gâp jêng kơt May.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0454", "title": "KƠT BU UR GŬ TA NTU DAK", "song_number": "454", "lyrics": "KƠT BU UR GŬ TA NTU DAK\n\n\nVerse 1\nKơt bu ur gŭ ta ntu dak, gâp ŭch tĭng joi ma ndơ mâu dơi bah nau ji hir. Jêh ri gâp tăng bâr Nơm Tâm Rklaih lah: \"Nhêt dak bơh gâp, mâu hôm ji hir đŏng ôh.\"\n\nChorus\nMbêng an kachok gâp, gâp yor ma Kôranh Brah. Văch ăn hom rêh huêng dak gâp ji hir. Kpŭng Mbỡ bơh trôk, nsăm gâp tât mâu hôm ji ngot. Mbêng an kachok aơ, mbêng ler lĕ nuih, lĕ huêng.\n\nVerse 2\nRmưn rkeh kon bunuyh neh ntu aơ hôm ŭch âk ir ntil ndơ ŭch neh ntu mâu dơi dĭl ôh. Mâu hôm dơi tâm di tâm lĕ drăp khlay. Knŏng gâp hôm joi tâm Yê-su Krist, Kôranh Brah.\n\nChorus\nMbêng an kachok gâp, gâp yor ma Kôranh Brah. Văch ăn hom rêh huêng dak gâp ji hir. Kpŭng Mbỡ bơh trôk, nsăm gâp tât mâu hôm ji ngot. Mbêng an kachok aơ, mbêng ler lĕ nuih, lĕ huêng.\n\nVerse 3\nLah oh nâu geh lĕ ntil ndơ bơh neh ntu ăn, ăt hôm ji ngot, mâu geh bah ôh. Gâp geh nau ueh maak Kôranh Brah rklaih gâp. Njŭr săk may, chon kô-mâk mbơh sơm ma Păng.\n\nChorus\nMbêng an kachok gâp, gâp yor ma Kôranh Brah. Văch ăn hom rêh huêng dak gâp ji hir. Kpŭng Mbỡ bơh trôk, nsăm gâp tât mâu hôm ji ngot. Mbêng an kachok aơ, mbêng ler lĕ nuih, lĕ huêng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0455", "title": "MBỠ ƠI, IĂT HOM BÂR GÂP", "song_number": "455", "lyrics": "MBỠ ƠI, IĂT HOM BÂR GÂP\n\nTVCHH 111\n\nVerse 1\nMbỡ ơi, iăt hom bâr gâp, dôl kâp kuăl mbơh sơm maak. Tĭng nau rêh gâp geh âk nau jêr jŏt, gâp rêh ni. Mbỡ ơi, iăt hom bâr gâp. Geh nau klach, gâp nhĭm êng, jêh ri măt gâp mbêng ma dak măt dôl mbơh sơm. Kơl gâp, Kôranh Brah, gâp hăn êp May lơn. Rgâl nuih n'hâm gâp, ăn lŏ jêng mhe. Lĕ nuih n'hâm gâp lah ueh tâm r-nê. Dăn Brah Ndu Mbỡ Hađăch chiă uănh chrêk ma lơp. Mprơ hom răm maak, mprơ hom răm maak, ma lĕ nuih n'hâm tâm rnê Kôranh Brah. Mprơ hom răm maak, mprơ hom răm maak. Mprơ tâm rnê ma Păng ƀa-ƀơ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0456", "title": "ĂN HE JOI LOR LƠN", "song_number": "456", "lyrics": "ĂN HE JOI LOR LƠN\n\n\nVerse 1\nĂn he joi lor lơn bon bri Hađăch Brah Ndu jêh ri nau sŏng Păng. Lĕ rngôch ndơ nĕ, Păng mra ntop an ma may. Ha-lê-lu, ha-lê-lu-ya.\n\nVerse 2\nBunuyh gŭ rêh mâu di ôh knŏng ma kpŭng ndơ sa, ƀiă-lah ma nau Brah Ndu Ngơi. Luh ăn jêh tă bơh bâr mbung Brah Ndu Nơm. Ha-lê-lu, ha-lê-lu-ya.\n\nVerse 3\nDăn hom dĭng geh, bu mra ăn ndơ may. Joi ngăn hom, Păng mra saơ. Goh hom mpông pêr bu sâm pơk an ma may. Ha-lê-lu, ha-lê-lu-ya.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0457", "title": "PAH NUIH KON, MBỠ ƠI", "song_number": "457", "lyrics": "PAH NUIH KON, MBỠ ƠI\n\n\nVerse 1\nPah nuih kon, Mbỡ ơi, tâm mông aơ. Pah nuih kon, ăn kon mĭn ma Mbỡ. Pah nuih kon, Mbỡ ơi, tâm mông aơ. Pah nuih kon, ăn kon êp đah Mbỡ. Mpư kon dơi hao dơi klaih bơh ntŭk roh rai. Mpư kon dơi hao mâu tĭng ma nau rngot rvê. Ri kon ŭch mprơ tâm rnê ma Amoh Kôranh Brah. Dăn Brah Huêng Ueh tât pah nuih kon Mbỡ ơi.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0458", "title": "GÂP ŬCH KAN DU NTIL", "song_number": "458", "lyrics": "GÂP ŬCH KAN DU NTIL\n\n\nVerse 1\nGâp ŭch kan du ntil, chuêl lĕ ndơ pa-kơi. Gâp ŭch kan du ntil, gay rduh sŏk ndơ pa-năp. Gâp ŭch kan du ntil, ŭch chuat ntŭk tâm năl. Gâp ŭch kan du ntil, gay sŏk ndơ nkhôm Mbỡ ton.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0459", "title": "ĂN GÂP NHUAT TĬNG TRONG MAY", "song_number": "459", "lyrics": "ĂN GÂP NHUAT TĬNG TRONG MAY\n\n\nVerse 1\nĂn gâp nhuat tĭng trong May, nti gâp trong May. Ăn gâp nau ueh bơh May, nti gâp trong May. Kơl sâm nti gâp trong May. Gâp nsing ma May, Kôranh Brah. Sol hom nau ang bơh trôk. Nti gâp trong May.\n\nVerse 2\nTơ lah nuih n'hâm rngot rvê, nti gâp trong May. Lah nau maak lĕ roh jêh, nti gâp trong May. Lah hăn êng ta neh ntu, mâp âk rêh ni ji kuet, dơi mâu lah mâu lĕ kan, nti gâp trong May.\n\nVerse 3\nLah nau mĭn gâp hôm đing, nti gâp trong May. Lah phŭt sial chuănh nau rêh, nti gâp trong May. Lah nau ngo kleng, nau mhĭk găn lĕ rngôch nau jêr kanap, njŭn hom gâp tâm trong May, nti gâp trong May.\n\nVerse 4\nNđah nar n'găr ta neh ntu, nti gâp trong May. Tơ lah mâp nau klach krit, nti gâp trong May. Tât nar lôch dŭt neh ntu, tât nar ƀư lôch lĕ kan, nar gâp tâm mâp ma Mbỡ, nti gâp trong May.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0460", "title": "MĂNG NÂM NAR YÊSU NJŬN LEO GÂP", "song_number": "460", "lyrics": "MĂNG NÂM NAR YÊSU NJŬN LEO GÂP\n\nTC 272\n\nVerse 1\nMăng nâm nar Yê-su njŭn leo gâp. Mâu geh nau khlay lơn ma nây. Păng chiă uănh gâp ma nau mơih rmên, mâm ƀư mâu nsing mro ma Păng? Êp kêng Păng gâp geh nau bonh leng, nau đăp mpăn, nau răm maak ngăn. Yor gâp saơ, ŏng âk nau jêr jŏt, Yê-su njŭn gâp tâm trong ueh. Yor gâp saơ, ŏng âk nau jêr jŏt, Yê-su njŭn gâp tâm trong ueh.\n\nVerse 2\nMăng nâm nar Yê-su njŭn leo gâp. Nđâp trong hăn kue kuăt ngo klĕng, ăt Păng ăn nau dơi, nau nsrôih ngăn, ăt Păng ăn ka-pŭng nau rêh. Lah gâp rgănh, lah jâng ŭnh mbâr prah, lah ji ngot ji hir hâu ngăn. ăt geh dak rsang hoch bonh leng gâp, tă ti ueh Kôranh Brah nơm ăn. Ăt geh dak rsang hoch bonh leng gâp, tă ti ueh Kôranh Brah nơm ăn.\n\nVerse 3\nMăng nâm nar Yê-su njŭn leo gâp. Păng jêng Kôranh gâp mơih mên Ôi ta klak Păng ăn gâp rlu n'hanh, ta ƀon ueh klơ ndrel ma Păng. Rnôk ri huêng gâp mâu hôm rvê ôh. Gâp mpăr ran ntŭk hŏ nkra jêh. Gâp mra mprơ ta ri nau mprơ aơ: Yê-su hŏ njŭn leo gâp mro. Gâp mra mprơ ta ri nau mprơ aơ: Yê-su hŏ njŭn leo gâp mro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0461", "title": "MBU NÂM CHUAT TÂM NAU RŎNG YÊ-SU", "song_number": "461", "lyrics": "MBU NÂM CHUAT TÂM NAU RŎNG YÊ-SU\n\n\nVerse 1\nMbu nâm chuat tâm nau rŏng Yê-su geh Yê-su jêng rmăk ueh. Păng ăn nau đăp nau mpăn tâm nau rêh. Tâm nau jêr mâu lah nau r-ngot geh Yê-su jêng rmăk ueh. Păng mâu lơi mbu nâm rnơm ma Yê-su.\n\nChorus\nNau rêh maak geh Yê-su. Păng njŭn leo dôl chuat ndrel. Păng mâu lơi mbu gĭt rnơm ma Yê-su. Nau rŏng Yê-su mâu geh r-gâl, nđaơ, nar aơ, jêh ri ôi taơ, ma mbu nâm gĭt nau rnơm ma Yê-su.\n\nVerse 2\nMbu nâm chuat tâm nau rngot r-vê, ăn may hăn êp Yê-su. Păng jêng rmăk ueh, bonh leng nau rêh he. Dak lip nkŏch mâu lah sial r-puh, nau ji ngot, nau tâm lơh. Gâp mâu rvê, geh Yê-su jêng rmăk ueh.\n\nChorus\nNau rêh maak geh Yê-su. Păng njŭn leo dôl chuat ndrel. Păng mâu lơi mbu gĭt rnơm ma Yê-su. Nau rŏng Yê-su mâu geh r-gâl, nđaơ, nar aơ, jêh ri ôi taơ, ma mbu nâm gĭt nau rnơm ma Yê-su.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0462", "title": "DĂN YÊ-SU KƠL N'GANG", "song_number": "462", "lyrics": "DĂN YÊ-SU KƠL N'GANG\n\n\nVerse 1\nDăn Yê-su kơl n'gang, jâng gâp chuat ŭch gŭ răp jăp, lĕ trong hăn, nđâp ntŭk rlŭng jru. Gâp kuăl May ơ Kôranh Brah! Njŭn hom gâp ŭch gŭ răp jăp ơ Yê-su ơi! Njŭn hom gâp sĭt ma ngih.\n\nVerse 2\nDăn Yê-su văch dăch, dôl nau ngo ŭch ƀư nkŭm gâp, mpiăt ŭnh kđen, tâm gâp dăch khĭt. Gâp kuăl May ơ Kôranh Brah! Yỗ ăn gâp lơi đing cha lôt ơ Yê-su ơi! Njŭn hom gâp sĭt ma ngih.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0463", "title": "MBU RĂP JĂP TÂM LĔ RNGÔCH KAN JỄ", "song_number": "463", "lyrics": "MBU RĂP JĂP TÂM LĔ RNGÔCH KAN JỄ\n\n\nVerse 1\nMbu răp jăp tâm lĕ rngôch kan jễ, păng nây mra răp jăp tâm kan kuăng đŏng. Mbu nơm ndôt prăp nau Brah Ndu Ngơi, păng mra sŏk dơn nau ueh uĭn bơh kalơ trôk.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0464", "title": "NAU TÂM KOL NDRÔI", "song_number": "464", "lyrics": "NAU TÂM KOL NDRÔI\n\nTC 884\n\nVerse 1\nNau vơl dăn mbơh ma Kôranh Brah nau tâm kol ndrôi, tâm mông nar aơ. Ŭch ngăn ma nau rŏng kloh, lĕ nau rêh mâu tâm rgâl, bar huê păng mbơh Kôranh Brah, tơ lah geh âk nau rlong uănh tât, hôm du nuih n'hâm geh nau rŏng.\n\nChorus\nUeh ăn dăn nau rŏng tâm nkhah, năm khay mâu tâm r'gâl. Maak hom ƀa-ƀơ bar huê ma khân ay may. Ŭch dăn ngăn yơh jêng ur sai ma nau răm ueh maak, nchuat hăn tĭng nâm Mbỡ ŭch ƀa-ƀơ n'ho-ro.\n\nVerse 2\nNuih n'hâm rjăp lah geh nau êng tât, ăn nkah nau tâm nton êng ang. Ŭch ton ngăn nau kloh ueh, lĕ nuih n'hâm jao Kôranh Brah, mpơl nau rŏng lĕ dŭt n'hâm, kâp gân ndrel nar maak răm mra tât ngăn bar huê hŏ tâm ton jêh.\n\nChorus\nUeh ăn dăn nau rŏng tâm nkhah, năm khay mâu tâm r'gâl. Maak hom ƀa-ƀơ bar huê ma khân ay may. Ŭch dăn ngăn yơh jêng ur sai ma nau răm ueh maak, nchuat hăn tĭng nâm Mbỡ ŭch ƀa-ƀơ n'ho-ro.\n\nVerse 3\nGeh du nar he mra tâm nkol ngăn, nau nteh n'gông kloh dŭt maak ngăn. Lăp trôm nghih Brah kloh ueh, dăn nau ueh maak ma bar huê khân păng, mbêng nau ueh, ueh ngăn ngên nau rŏng tâm Brah Krist, ƀa-ƀơ ma nau mprơ răm maak.\n\nChorus\nUeh ăn dăn nau rŏng tâm nkhah, năm khay mâu tâm r'gâl. Maak hom ƀa-ƀơ bar huê ma khân ay may. Ŭch dăn ngăn yơh jêng ur sai ma nau răm ueh maak, nchuat hăn tĭng nâm Mbỡ ŭch ƀa-ƀơ n'ho-ro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0465", "title": "GÂP ŬCH YƠR AMOH MAY ĂN PRÊH", "song_number": "465", "lyrics": "GÂP ŬCH YƠR AMOH MAY ĂN PRÊH\n\n\nVerse 1\nGâp ŭch yơr amoh May ăn prêh Kôranh Brah, gâp rŏng mprơ tâm rnê ma May. Gâp răm ngăn May rêh tâm gâp, răm dŭt n'hâm May văch sâm rklaih hên. May văch bơh trôk jŭr ta neh nchŏng trong ma hên. Tât ta neh may dơn bu pâng trok rnon tih hên. Tă bu pâng bu tâp tâm môch tă bơh môch hao sĭt klơ trôk. Gâp ŭch yơr Amoh May ăn prêh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0466", "title": "MAY JÊNG N'HÂM SUAN MA GÂP DÔL HƯƠI", "song_number": "466", "lyrics": "MAY JÊNG N'HÂM SUAN MA GÂP DÔL HƯƠI\n\nTVCHH 199\n\nVerse 1\nMay jêng n'hâm suan ma gâp dôl hươi. May jêng drăp khlay ma gâp tĭng joi. May jêng lĕ rngôch ma gâp. Uănh tĭng joi may khlay lơn ma mah. Ŭch cha-lơi May jêng nau rluk mâl. May jêng lĕ rngôch ma gâp.\n\nChorus\nYê-su, Kon Biăp Brah Ndu, dŭt toyh ngăn Amoh May. Yê-su, Kon Biăp Brah Ndu, dŭt toyh ngăn Amoh May.\n\nVerse 2\nDjôt nau tih gâp ta si tâm rkăng. Lŏ dâk rêh đŏng, tâm rnê ma May. May jêng lĕ rngôch ma gâp. Lah gâp geh prah, May sâm rdâk tay. Dôl gâp ji hir, may ăn gâp nhêt. May jêng lĕ rngôch ma gâp.\n\nChorus\nYê-su, Kon Biăp Brah Ndu, dŭt toyh ngăn Amoh May. Yê-su, Kon Biăp Brah Ndu, dŭt toyh ngăn Amoh May.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0467", "title": "LAH UEH MA LĔ NUIH N'HÂM HE", "song_number": "467", "lyrics": "LAH UEH MA LĔ NUIH N'HÂM HE\n\nTC 682\n\nVerse 1\nLah ueh ma lĕ nuih n'hâm he. Lah ueh mât ton ma Brah Ndu. Lah ueh yor Păng ăn ma he Yê-su Krist, Kon Păng. Lah ueh ma lĕ nuih n'hâm he. Lah ueh mât ton ma Brah Ndu. Lah ueh yor Păng ăn ma he Yê-su Krist, Kon Păng.\n\nChorus\nA-ƀaơ ăn nơm hươi rgănh lah ktang jêh, nơm o-ach lah hŏ ndrŏng jêh, ma yor nau Kôranh Brah hŏ sâm ƀư ma he. A-ƀơ ăn nơm hươi rgănh la ktang jêh, nơm o-ach lah hŏ ndrŏng jêh, ma nau yor Kôranh Brah hŏ sâm ƀư ma he. Lah ueh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0468", "title": "VĂCH HOM MA PĂNG", "song_number": "468", "lyrics": "VĂCH HOM MA PĂNG\n\nTVCHH 69\n\nVerse 1\nVăch hom ma Păng, phung rŏng ma Kôranh Brah ăn he mprơ hom, tâm rnê amoh Păng. Ăn he mprơ huy, ntŭk ngih yơk mbah Păng ăn he mprơ rhơn, yor Păng jêng Hađăch he.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0469", "title": "GEH DU HUÊ NƠM RHĂK NJÊNG", "song_number": "469", "lyrics": "GEH DU HUÊ NƠM RHĂK NJÊNG\n\n\nVerse 1\nGeh du huê nơm rhăk njêng Păng sâm mon play nuih gâp. Ê lor nđâp mông ntơm jêng nau rêh gâp bơh mpang ti Păng\n\nChorus\nPăng gĭt a-moh săk gâp Păng gĭt lĕ nau gâp mĭn Păng saơ ăp dak măt hoch, kâp iăt dôl mông gâp kuăl\n\nVerse 2\nGeh du huê Mbỡ Kôranh Brah păng kuăl he jêng kon Păng. Păng mâu mâp cha-lơi gâp. Mâu rvê moh ntŭk gâp hăn\n\nChorus\nPăng gĭt a-moh săk gâp Păng gĭt lĕ nau gâp mĭn Păng saơ ăp dak măt hoch, kâp iăt dôl mông gâp kuăl\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0470", "title": "BUNUYH KAN KÔRANH BRAH", "song_number": "470", "lyrics": "BUNUYH KAN KÔRANH BRAH\n\n\nVerse 1\nBunuyh kan Kôranh Brah jêng phung Kôranh Brah săch kuăl. Kôranh Brah rong he; mâm he mâu kan ma păng? Ăn jao hom nau rêh he ma Kôranh Brah. Kơl hom gâp, ơ Kôranh Brah gĭt rŏng ma he.\n\nChorus\nĂn he njrăng hom, yor lah Kôranh Brah êp jêh. Ăn he dâk hom, pah kan Kôranh Brah. Păng mra nkhôm nkra ma mbu nơm kan răp jăp. Ăn he ƀư rĭng lĕ kan Kôranh Brah jao.\n\nVerse 2\nMbu nơm pah kan ma gâp, păng tĭng ndỗ gâp. Mbu nơm pah kan ma gâp, Mbỡ gâp rnê păng. Ăn nhhơr hom nau rêh may ma Kôranh Brah. Nhhơr hom drăp ndơ ay geh, ăn ma Kôranh Brah.\n\nChorus\nĂn he njrăng hom, yor lah Kôranh Brah êp jêh. Ăn he dâk hom, pah kan Kôranh Brah. Păng mra nkhôm nkra ma mbu nơm kan răp jăp. Ăn he ƀư rĭng lĕ kan Kôranh Brah jao.\n\nVerse 3\nĂn may ƀư hom lĕ rngôch ndơ ma nau rŏng. Ăn lĕ n'hâm suan gơih nđơr tâm kan Kôranh Brah. Ăp nơm he mbơh kan ta năp Kôranh Brah. Ăn ƀư lôch hom lĕ kan Kôranh Brah jao jêh.\n\nChorus\nĂn he njrăng hom, yor lah Kôranh Brah êp jêh. Ăn he dâk hom, pah kan Kôranh Brah. Păng mra nkhôm nkra ma mbu nơm kan răp jăp. Ăn he ƀư rĭng lĕ kan Kôranh Brah jao.\n\nVerse 4\nNĕ aơ gâp văch gơnh jêh ri djôt nau khôm, gay ăn ma ăp nơm tĭng kan may ƀư jêh. Lơi plỡ rŭch ôh, klach lah Kôranh mra văch. Dâk hom, or nur, yor mông Kôranh Brah êp jêh.\n\nChorus\nĂn he njrăng hom, yor lah Kôranh Brah êp jêh. Ăn he dâk hom, pah kan Kôranh Brah. Păng mra nkhôm nkra ma mbu nơm kan răp jăp. Ăn he ƀư rĭng lĕ kan Kôranh Brah jao.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0471", "title": "TÂM TI KÔRANH BRAH", "song_number": "471", "lyrics": "TÂM TI KÔRANH BRAH\n\nTVCHH 278\n\nVerse 1\nJŏ năm jêh gŭ tâm nau tih, lĕ nau rêh mâu geh khlay ôh, dôl gâp-ê hŏ rŏng ma Brah Yê-su tơ lah gâp lơi lĕ nau tih, Păng djôt ti njŭn leo trong gâp, ma nau Păng rŏng dơi rai nau rngot.\n\nChorus\nPăng nâm măt nar, sol ang lĕ, gâp rŏng Yê-su Kôranh gâp ueh ngăn. Ntơm bơh aƀaơ rmưn rbăn năm, mpang ti Kôranh Brah njŭn leo gâp hăn. Păng jêng nau ang, sol dôl măng, Yê-su rŏng ơ Kôranh Brah khlay ngăn. Ntơm bơh aƀaơ tât ka-ndỡ, tâm rnê Yê-su ƀa ƀơ n'ho ro.\n\nVerse 2\nGâp tăng jêh tâm ndrom sam-ƀŭt, yor rŏng gâp Kôranh Brah jŭr deh, mâu geh ntŭk njơh khĭt tâm nau nđêh nji Păng jêng Hađăch ma lĕ rngôch hađăch, nau Ngơi Păng dơi buay dak sial, mâm ƀư Kôranh Brah khĭt ta klơ yôk?\n\nChorus\nPăng nâm măt nar, sol ang lĕ, gâp rŏng Yê-su Kôranh gâp ueh ngăn. Ntơm bơh aƀaơ rmưn rbăn năm, mpang ti Kôranh Brah njŭn leo gâp hăn. Păng jêng nau ang, sol dôl măng, Yê-su rŏng ơ Kôranh Brah khlay ngăn. Ntơm bơh aƀaơ tât ka-ndỡ, tâm rnê Yê-su ƀa ƀơ n'ho ro.\n\nVerse 3\nAy may dôl hôm-e rêh mblêng, ăp nar neh ntu ƀư vĭ may, tăng lĕ nau Păng ŭch kuăl may nar aơ plỡ sĭt tâm jâng Yê-su ro, Păng mra jut lĕ dak măt may, lĕ rngôch nau jêr mra rgâl jêng maak.\n\nChorus\nPăng nâm măt nar, sol ang lĕ, gâp rŏng Yê-su Kôranh gâp ueh ngăn. Ntơm bơh aƀaơ rmưn rbăn năm, mpang ti Kôranh Brah njŭn leo gâp hăn. Păng jêng nau ang, sol dôl măng, Yê-su rŏng ơ Kôranh Brah khlay ngăn. Ntơm bơh aƀaơ tât ka-ndỡ, tâm rnê Yê-su ƀa ƀơ n'ho ro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0472", "title": "KON PLỠ SĬT", "song_number": "472", "lyrics": "KON PLỠ SĬT\n\n\nVerse 1\nN'hêl na nê Kôranh Brah ŭch may iăt. Aơ kon yor may Kôranh Brah ŭch jŭr. Khĭt trok bunuyh nji nđơt du huê Păng. Gŭ kalơ trôk hôm e kâp gân kon.\n\nChorus\nKon plỡ sĭt! chon mon tâm jâng Yê-su. Lĕ nuih n'hâm dăn ma Kôranh Brah yỗ an. Âk nau tih yor mâu chroh ma Kôranh Brah ŭch dăn du bông nau rêh rŏng Păng.\n\nVerse 2\nÂk hâu ngăn Kôranh Brah hŏ vah vơl. Aơ kon plỡ sĭt gơnh hom ma Gâp. Cha lơi hom trong ƀỡ ƀơch tih mbĭk. Gŭ rêh ndrel nau ueh maak an kon.\n\nChorus\nKon plỡ sĭt! chon mon tâm jâng Yê-su. Lĕ nuih n'hâm dăn ma Kôranh Brah yỗ an. Âk nau tih yor mâu chroh ma Kôranh Brah ŭch dăn du bông nau rêh rŏng Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0473", "title": "MĂNG SIĂL PŬH KĂL E", "song_number": "473", "lyrics": "MĂNG SIĂL PŬH KĂL E\n\nTC 573\n\nVerse 1\nMăng kăl e tâm n'grar ndrôk ngo klĕng. n'gul măng nĕ mănh mbing chrat ang. Ta klơ nteh n'gông tông mpăr tâm rnê. Kôranh Brah Yê-su bơh klơ jŭr deh. Đăp mpăn lam neh ntu, đăp mpăn ăn lam neh ntu, klơ trôk dŭt prêh Kôranh Brah lư n'grăr.\n\nChorus\nUeh uĭn! Kon Brah jŭr deh, nau mprơ nteh huy ta klơ. Maak Yê-su Krist jŭr deh rklaih he bơh ntŭk rêh ni. N'gul măng nĕ Kôranh Brah deh jêh, mông aơ dăn jŭr deh tâm gâp. Ăn nuih n'hâm rŏng Păng ƀa-ƀơ dăn Păng gŭ tâm nuih n'hâm aơ n'ho ro.\n\nVerse 2\nYor neh ntu rai yot yor rŏng neh ntu rai yot. Păng lơi sưng Hađăch Kon Brah jŭr deh. Tâm măng siăl pŭh Kôranh Brah jŭr deh, mâu n'huăch ƀon ueh jêng ntŭk chrêk rmah. Măng siăl pŭh nây geh mănh mbing chrat ang. Phung njêh tĭng joi ma nuih n'hâm maak răm.\n\nChorus\nUeh uĭn! Kon Brah jŭr deh, nau mprơ nteh huy ta klơ. Maak Yê-su Krist jŭr deh rklaih he bơh ntŭk rêh ni. N'gul măng nĕ Kôranh Brah deh jêh, mông aơ dăn jŭr deh tâm gâp. Ăn nuih n'hâm rŏng Păng ƀa-ƀơ dăn Păng gŭ tâm nuih n'hâm aơ n'ho ro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0474", "title": "DĂN MBỠ RGÂL NUIH N'HÂM", "song_number": "474", "lyrics": "DĂN MBỠ RGÂL NUIH N'HÂM\n\nTC 694\n\nVerse 1\nDăn Mbỡ rgâl nuih n'hâm, njêng huêng gâp kloh ueh. Dăn Mbỡ rgâl nuih n'hâm, njêng nâm bu Kôranh Brah. Kon jêng mruih neh aơ, mon tĭng Brah ŭch. Tĭng nâm nau Păng njêng, tĭng Mbỡ ŭch dơi jêng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0475", "title": "DĂN MBỠ TROCH ŬNH KA-ĐEN", "song_number": "475", "lyrics": "DĂN MBỠ TROCH ŬNH KA-ĐEN\n\nTC 617\n\nVerse 1\nDăn Mbỡ troch mbêng dak ŭnh gay ang kađen kon. Dăn Mbỡ ăn nuih n'hâm ang rah vah. Dăn Mbỡ troch mbêng dak ŭnh gay ang kađen kon. Huêng Kôranh Brah nsol ang kon dôl nar măng. Mprơ Hô-sa-na, mprơ Hô-sa-na, mprơ tâm rnê ma Hađăch n'ho ro chrat ang, mprơ Hô-sa-na, mprơ Hô-sa-na mprơ tâm rnê ma Hađăch lĕ Hađăch.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0476", "title": "GÂP GĬT NGĂN", "song_number": "476", "lyrics": "GÂP GĬT NGĂN\n\n\nVerse 1\nNơm tih mhĭk rok ntŭk nsing ran hom, mham Yê-su dơi tâm rgâl may. Păng tâm chuai lĕ kan dŭt mhĭk may, nâm bu Păng tâm chuai jêh gâp.\n\nChorus\nGâp gĭt jêh, gâp gĭt ngăn. Mham Yê-su dơi rgâl lĕ nau tih jêng kloh ƀhiau. Gâp gĭt jêh, gâp gĭt ngăn. Mham Yê-su dơi rgâl lĕ nau tih jêng kloh ƀhiau.\n\nVerse 2\nNơm huăr rganh Păng ntop ăn n'hâm suan, rgăn rlau yôk Păng mra ntim trong. Joi tât saơ tu dak tâm ndrêch r'dah, tâm rgâl măng dơi jêng luh ang.\n\nChorus\nGâp gĭt jêh, gâp gĭt ngăn. Mham Yê-su dơi rgâl lĕ nau tih jêng kloh ƀhiau. Gâp gĭt jêh, gâp gĭt ngăn. Mham Yê-su dơi rgâl lĕ nau tih jêng kloh ƀhiau.\n\nVerse 3\nMâp rlong uănh geh Kôranh Brah gŭ dăch, ƀư rai lĕ nau kan brah mhĭk. Njŭn leo may tât ntŭk đăp mpăn ngăn, rêh tâm nau yỗ Păng ăp nar.\n\nChorus\nGâp gĭt jêh, gâp gĭt ngăn. Mham Yê-su dơi rgâl lĕ nau tih jêng kloh ƀhiau. Gâp gĭt jêh, gâp gĭt ngăn. Mham Yê-su dơi rgâl lĕ nau tih jêng kloh ƀhiau.\n\nVerse 4\nPăng mra chĭa uănh may lĕ ăp r'nôk, mât mơh may kŏ tât n'ho ro. Nđâp neh ntu r'khang brah mhĭk tâm rmot, lĕ kan may mra ueh da dê.\n\nChorus\nGâp gĭt jêh, gâp gĭt ngăn. Mham Yê-su dơi rgâl lĕ nau tih jêng kloh ƀhiau. Gâp gĭt jêh, gâp gĭt ngăn. Mham Yê-su dơi rgâl lĕ nau tih jêng kloh ƀhiau.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0477", "title": "GÂP NĂL NƠM GÂP CHROH", "song_number": "477", "lyrics": "GÂP NĂL NƠM GÂP CHROH\n\nTC 262\n\nVerse 1\nMoh yor gâp dơi dơn nau yỗ aơ, ngăn yơh mâm ƀư blau rblang. Yor lah gâp jêng bu-nuyh djơh mhĭk, mham Krist hŏ tâm chuai gâp.\n\nChorus\nPô nây, gĭt rbăng ngăn Nơm Brah gâp chroh. Chroh n'hêl ngăn mâu prêng, nhhơr hom săk jăn aơ. Yor, Păng jêng Nơm Brah dơi mât mơh. Lĕ bông rêh tât nar kăn ndỡ.\n\nVerse 2\nMoh yor Kôranh Brah ăn nau chroh ngăn, gay gâp geh nau tâm rklaih. Nsing nau Păng Ngơi gâp đăp mpăn ngăn, mâm ƀư gâp dơi blau rblang.\n\nChorus\nPô nây, gĭt rbăng ngăn Nơm Brah gâp chroh. Chroh n'hêl ngăn mâu prêng, nhhơr hom săk jăn aơ. Yor, Păng jêng Nơm Brah dơi mât mơh. Lĕ bông rêh tât nar kăn ndỡ.\n\nVerse 3\nMâm gâp gĭt rbăng kan Brah Huêng Ueh, dơi njŭn bu-nuyh sĭt chroh. Mpơl Brah Yê-su bơh Brah Ndu Ngơi, ŭch ma nau chroh hao toyh.\n\nChorus\nPô nây, gĭt rbăng ngăn Nơm Brah gâp chroh. Chroh n'hêl ngăn mâu prêng, nhhơr hom săk jăn aơ. Yor, Păng jêng Nơm Brah dơi mât mơh. Lĕ bông rêh tât nar kăn ndỡ.\n\nVerse 4\nMâm ƀư gĭt rbăng nau mhĭk nau ueh, jêh ri moh nau mra tât. Tâm trong gâp hăn geh mâp nau jêr, mâu lah geh nau maak ngăn.\n\nChorus\nPô nây, gĭt rbăng ngăn Nơm Brah gâp chroh. Chroh n'hêl ngăn mâu prêng, nhhơr hom săk jăn aơ. Yor, Păng jêng Nơm Brah dơi mât mơh. Lĕ bông rêh tât nar kăn ndỡ.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0478", "title": "KÔRANH BRAH ÊP KÊNG GÂP", "song_number": "478", "lyrics": "KÔRANH BRAH ÊP KÊNG GÂP\n\nTVCHH 208\n\nVerse 1\nDôl hăn trong hom ngo đăp thŭl tŭk, jâng chuăt hăn klach khan tâm ntŭk trâp. Gâp hôm nsing tâm Kôranh Brah mbơh ăn Mbỡ, lĕ nau tât dăn Păng bơh klơ, njŭn leo lĕ nau rêh.\n\nChorus\nYê-su mro nar măng chiăp gâp, njŭn leo gâp tât ntŭk gỡ nse. Kôranh Brah hôm gŭ kêng gâp mro mrăng. Ô ueh ngăn bêng ler tâm he, kah gĭt hom ma Kôranh Brah toyh lĕ nau rêh n'ho ƀa-ƀơ rŏng Păng.\n\nVerse 2\nGay chuăt hăn du huê êng rvê ngăn, lŭh dak măt yor mĭt jiăng gŭ ngai. Yê-su gŭ dăch kêng gâp ut r'u gâp, Păng jut lĕ rngôch dak măt gâp, Yê-su mĭt jiăng ueh.\n\nChorus\nYê-su mro nar măng chiăp gâp, njŭn leo gâp tât ntŭk gỡ nse. Kôranh Brah hôm gŭ kêng gâp mro mrăng. Ô ueh ngăn bêng ler tâm he, kah gĭt hom ma Kôranh Brah toyh lĕ nau rêh n'ho ƀa-ƀơ rŏng Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0479", "title": "LAH UEH KÔRANH BRAH", "song_number": "479", "lyrics": "LAH UEH KÔRANH BRAH\n\nTVCHH 201\n\nVerse 1\nLah ueh Kôranh Brah, nđâp tơ lah geh âk nau rlong uănh. Păng ăn ma gâp nau ang rah vah, ăp nar chuăt gâp hăn. Lah ueh Kôranh Brah, geh nau rlong uănh ri mơ gĭt mbên, jêh nay hăn tât ta ntŭk rjăp lơn. Ăn ƀư ntĭng Mbỡ ŭch. Lah geh sial rpŭh nhhơr hom tâm nuih n'hâm nâm bu ŭnh hit toyh mâu dơi nking, gâp saơ ngăn jêh tĭng ndỗ lĕ nau hŏ ntĭm trong jêh. Dôl geh nau rlong uănh toyh tâm gâp geh nau Ngơi n'gông, n'hŏng ngăn jêh ri nau Ngơi Kôranh Brah nâm bu ngai mâu geh ngai ôh...\n\nVerse 2\n(Lah ueh Kôranh) Brah dôl mông rlong uănh gui Kôranh Brah nkŭm. Yor nau Ngơi Păng njŭn gâp dơi klaih, dơi rgăn lĕ nau jêr. Lah ueh Kôranh Brah, dôl geh nau rlong uănh tâm nau rêh, nsing ma Păng ăn gâp dơi klaih ngăn. Nuih n'hâm gâp rjăp ngăn. Lah geh sial rpŭh nhhơr hom tâm nuih n'hâm nâm bu ŭnh hit toyh mâu dơi nking, gâp saơ ngăn jêh tĭng ndỗ lĕ nau hŏ ntĭm trong jêh. Dôl geh nau rlong uănh toyh tâm gâp geh nau Ngơi n'gông, n'hŏng ngăn jêh ri nau Ngơi Kôranh Brah nâm bu ngai mâu geh ngai ôh...\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0480", "title": "MAAK KHAY JŬR DEH", "song_number": "480", "lyrics": "MAAK KHAY JŬR DEH\n\n\nVerse 1\nMăng ueh jŏ jêh Brah jŭr deh, bêch tâm n'gar ndrôk ntŭk o-ach. Mâu nhuach sưng Hđăch ntŭk ndrong kuăng, rŏng kon nuyh may maak jŭr deh. Ntông Păr munh mprơ mbơh nau maak, ntênh ăn ma phung rmak hăn uănh. Khân păng yơk mbah ndrel Pe Hađăch, maak yơh năr Kon Brah jŭr deh.\n\nVerse 2\nNuih n'hâm hâk răm vơt nô-el, khay nđik tơm tât ta ăp ntŭk. Âk bunuyh nđơr hôm kâp gân, ngăn nđơr kâp nau Kôranh Brah tâm rklaih Lam ntŭk n'gông nteh nau maak ktang kâp gân ndrel gay tâm rglăp mprơ. Ăn he mprơ maak nau Nô-el, yor maak năr Yê-su jŭr deh. Măng aơ Brah Yê-su jŭr deh, phung he maak mprơ ndrel. Ndrel n'grup nau maak lam neh ntu, rom Kôranh Brah lăp tâm nuih n'hâm.\n\nVerse 3\nƠ oh nâu mâm may hôm nhhơt? Nau maak rnôk aơ mra roh dơm. Năr mông maak rlưn gơnh roh rai, yor nây mâm may hôm mblêng r'ngot. Lơi hôm hăn mblêng ơ oh nâu, hăn hom he tĭng joi Yê-su. Kon Brah ăn nau lap đăp mpăn, nuih n'hâm may mra geh hâk răm. Geh maak toyh lơn nau kâp gân, nđăp mpăn bêng ler lam ăp ntŭk Kôranh Brah ăn bunuyh dơn nau maak, yor nau rŏng Kon Brah jŭr deh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0481", "title": "MAAK NAR TÂM KOL", "song_number": "481", "lyrics": "MAAK NAR TÂM KOL\n\n\nVerse 1\nUeh maak ngăn yơh lah geh nau đăp mpăn. Maak ndrel bar huê dôl mông nar tâm kol, ang ôi sĭm ndrâu nar ang kloh rah vah. Nar mho tât mănh mbing ang ka lơ trôk.\n\nChorus\nRăm maak hom, nar bar huê tâm kol, nau mĭn nuih n'hâm jêng du nglay. Răm maak hom, nar bar huê tâm kol, ueh ngăn ngên nâm bu kao si. Nau mprơ tâm rnê ăn ma phung tâm kol, dăn Kôranh Brah kơl geh nau đăp mpăn ngăn. Dăn ma bar huê geh nau tâm rŏng ngăn, ăn lĕ nuih n'hâm, nâm bu Kôranh Brah rŏng.\n\nVerse 2\nNar aơ bar huê mhe chuat hăn ndrel trong. Nau rêh ueh maak mâu lah geh rngot klân, geh dak măt ndrel, geh ndrel đŏng nau maak. Bơh mông aơ ro tât mâp Brah klơ trôk.\n\nChorus\nChuat hăn ndrel tât ntŭk ndrĭch ueh ngăn, lơi ăn gŭ ngai ma Kôranh Brah. Gŭ rêh ueh mpơl hom ăn ueh ntu, jêng tu nau ueh ăn âk bunuyh. Nar aơ tâm kol geh nau ueh maak ngăn, âk bunuyh maak ndrel ma bar huê khân păng. Tâm rŏng ƀa-ƀơ mâu hôm geh tâm nkhah, gŭ dăch Kôranh Brah, mra geh ueh maak ngăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0482", "title": "MBỠ ƠI, GÂP ŬCH MAY MRO", "song_number": "482", "lyrics": "MBỠ ƠI, GÂP ŬCH MAY MRO\n\nTC 262\n\nVerse 1\nMbỡ ơi, gâp ŭch May kơl, yor May ueh ngăn. Mơih rmên ngăn nau May Ngơi kơl gâp đăp mpăn. Ăp mông gâp ŭch Mbỡ kơl mro. Nsing mpang ti Brah Yê-su, ăn nau ueh maak mâu tăch yơt gâp văch aƀaơ ro.\n\nVerse 2\nMbỡ ơi, gâp ŭch May kơl, gŭ êp kêng May. Brah mhĭk mâu hôm dơi ndơm geh May gŭ ndrel. Ăp mông gâp ŭch Mbỡ kơl mro. Nsing mpang ti Brah Yê-su, ăn nau ueh maak mâu tăch yơt gâp văch aƀaơ ro.\n\nVerse 3\nMbỡ ơi, gâp ŭch May kơl, rngot mâu lah maak. Lah gâp rêh ngai đah May djơh mhĭk hâu ngăn. Ăp mông gâp ŭch Mbỡ kơl mro. Nsing mpang ti Brah Yê-su, ăn nau ueh maak mâu tăch yơt gâp văch aƀaơ ro.\n\nVerse 4\nMbỡ ơi, gâp ŭch May kơl, nau ngăn tâm May. Ăn gâp gŭ êp May mro ơi Mbỡ klơ trôk. Ăp mông gâp ŭch Mbỡ kơl mro. Nsing mpang ti Brah Yê-su, ăn nau ueh maak mâu tăch yơt gâp văch aƀaơ ro.\nA-Men.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0483", "title": "MPRƠ NAU RŎNG", "song_number": "483", "lyrics": "MPRƠ NAU RŎNG\n\n\nVerse 1\nTâm nar aơ he mprơ tâm rnê, chon mon ndrel ta năp Brah toyh. Nau tâm ton tâm nau rŏng rêh ndrel ƀa-ƀơ! Jêh-ri Păng rêh ndrel bar huê, maak lah rngot, geh ndrel bar huê. Dăn Kôranh Brah kơl ăp mông nau rŏng jru lơn. Ti khân Păng têk ndrel tâm nau rŏng, ăn tâm rnglăp đăp mpăn ma khân Păng, ma nơm păng rŏng, ăn lĕ nuih n'hâm, dăn Mbỡ chiă mât. Nâm nđăr sĭm nphăr ueh ngăn ta klơ, bar jêng nguay dŭt ueh jêng ngăn ngên, ƀa-ƀơ tâm rŏng, nđâp lah jêr tât, geh Kôranh Brah mât.\n\nVerse 2\nTâm nar aơ he mprơ tâm rnê, chon mon ndrel ta năp Brah toyh. Nau tâm ton tâm nau rŏng rêh ndrel ƀa-ƀơ! Jêh-ri Păng rêh ndrel bar huê, maak lah rngot, geh ndrel bar huê. Dăn Kôranh Brah kơl ăp mông nau rŏng jru lơn. Geh đŏng nar răm maak mâu lah rngot, bar huê kon lơi chuêl nau tâm ton, ăn tâm rŏng lơn, jêng nuyh gâp rŏng, ăn rŏng gâp lơn. Nau nđăp mpăn mbêng ler ăn khân păng, bar huê kon lơi chuêl nau tâm ton, nau mprơ lah ueh, dăn Brah Ndu Mbỡ nkŭm ăn phung kon.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0484", "title": "NAU RŎNG KÔRANH BRAH MRO MRĂNG", "song_number": "484", "lyrics": "NAU RŎNG KÔRANH BRAH MRO MRĂNG\n\nTVCHH 206\n\nVerse 1\nNau rŏng Păng prêh lơn rlau yôk prêh dŭt prêh. Nau rŏng Păng rlau lơn dak jru dŭt jru. Nau rŏng Păng dŭt jru ngăn ngên, mâu dơi ntĭt nau rŏng prêh ngăn ngên, nau Păng rŏng khlay ngăn.\n\nVerse 2\nNau yỗ Păng nuih n'hâm gâp bêng nau maak răm. Yor m'ham Păng nau tih gâp dơi rao kloh. Nau nđăp mpăn Kôranh Brah hŏ ăn jêh ma gâp bơh Mbỡ... nơm geh Kôranh Brah lĕ rngôch, ăp nar mhe lơn Păng gŭ tâm gâp, geh ngăn nau mhe yơh êng ang ngăn, jru ngăn Kôranh Brah rŏng. Nau rŏng Păng m'he lơn ăp nar mro mrăng m'he ƀa-ƀơ êng ang ngăn yơh jru ngăn Kôranh Brah rŏng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0485", "title": "NAU RŎNG MÂU DƠI NTĬT", "song_number": "485", "lyrics": "NAU RŎNG MÂU DƠI NTĬT\n\n\nVerse 1\nNuih n'hâm gâp aơ, nhhơr ma Yê-su. Păng hŏ khĭt trok ta si râm rkăng. Nuih Păng chah rai săk Păng luh mham. Yor nau tih gâp jêr jot May dơn.\n\nChorus\nMa yor nau rŏng May tâm chuai gâp. Mâu geh nau êng, ntĭt ma mham May. Yor nau rŏng nây aƀaơ gâp ŭch nhhơr. Dăn Mbỡ mât mơh du bông nau rêh gâp.\n\nVerse 2\nLĕ huêng suan gâp, aƀaơ nhhơr ta May. May hŏ dra ti, gây tâm rklaih gâp. Dơn nau bu pâng ta Gô-gô-tha. Yor lah May rŏng neh ntu tih mhĭk.\n\nChorus\nMa yor nau rŏng May tâm chuai gâp. Mâu geh nau êng, ntĭt ma mham May. Yor nau rŏng nây aƀaơ gâp ŭch nhhơr. Dăn Mbỡ mât mơh du bông nau rêh gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0486", "title": "NAU YỖ KHLAY NGĂN", "song_number": "486", "lyrics": "NAU YỖ KHLAY NGĂN\n\nTC 821\n\nVerse 1\nMprơ hom yor Păng ăn nau yỗ khlay ngăn. Nau rêh gâp bêng ma nau jêr. Jŏ năm gâp hŏ roh jêh, nhhơt mblêng tâm nau tih mhĭk, yor ma nau yỗ Păng Rklaih gâp.\n\nVerse 2\nNau rêh gâp mâp âk nau jêr klân rvê. Nau rngot hŏ ƀư roh nau chroh. Kôranh Brah hŏ tâm chuai gâp, ăn gâp rlu tâm ti Păng, nau yỗ Păng dŭt toyh jru ngăn.\n\nVerse 3\nGâp hŏ jŏ năm jêh gŭ tâm nau rngot. Bơh ntŭk ăn gâp saơ nau rêh? Nau yỗ Păng njŭn leo gâp, nau rŏng Păng ueh reh ngăn, mpang ti Brah Ndu Nơm mât gâp.\n\nVerse 4\nPăng plỡ văch gay djôt gâp sĭt klơ trôk. Nau maak mâm ƀư gâp dơi rblang? Dôl dâk ndrel phung kloh ueh, mprơ tâm rnê ma Brah Ndu, yor nau yỗ Păng tâm chuai gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0487", "title": "PHUNG TÂM RNGLĂP", "song_number": "487", "lyrics": "PHUNG TÂM RNGLĂP\n\nTVCHH 16\n\nVerse 1\nDôl nuih n'hâm ƀă geh nau rngot klâng, geh Kôranh Brah bêng ma nau dơi ngăn. Păng hăn ndrel têk ti gâp tâm mpang ti nau dơi gâp klaih jêh bơh ntŭk rai yot. Mĭn rjăp ngăn Păng gŭ ndrel ƀa-ƀơ. Phung he jêng mpôl nau tâm rnglăp. Mpang ti Păng mra têk leo he mra r'ngăn tât ntŭk dôl neh ntu bêng nau ngo nkŭm. He mâu dơi nkŭm nau ang rah vah bơh Kôranh Brah. Mâu geh ôh nking Kôranh Brah lăp tâm nuih n'hâm. Ăn lĕ phung he mbơh gơnh nau rŏng Kôranh Brah ăn dơm dam ngăn tâm Brah Yê-su Krist. Mbơh nau mhe mhan ăn lam ntŭk, klơ trôk ri jêng ƀon lan phung he mbơh ƀa-ƀơ nau Kôranh Brah rŏng ma he bơh nar aơ tât Kôranh Brah văch.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0488", "title": "PLỠ SĬT", "song_number": "488", "lyrics": "PLỠ SĬT\n\n\nVerse 1\nKlơ yôk kăl e rngot ngăn. neh ntu aơ roh rai ngăn du huê gâp nhhơt êng tâm ntŭk jêr mâu gĭt trong. Gơnh plỡ hom ndrel ma gâp. Nau ngơi păng n'gông n'hŏng ngăn, gâp mra leo may sĭt tât ta ngih ntŭk nau rŏng. Nkhah lơi bơh ntŭk ngo nay neh ntu bêng nau rngot rvê. Sĭt hom tâm trong ang, chrêk r'mah chrat ang ngăn. Mâu hôm geh dơi khan gâp. Tĭng têl Kôranh Brah hăn ndrel. kêng nh'hơr dak r sang, nau rŏng ueh mâu dơi ntĭt. Nkhah lơi bơh ntŭk ngo nay, ueh ngăn geh nau rŏng.\n\nVerse 2\nKlơ yôk kăl e rngot ngăn. neh ntu ntŭk nji nđơt ngăn Yê-su hŏ khĭt jêh ngăn gâp aơ jêng nuyh tih. Lơi ƀon ueh ta klơ trôk. Păng jur jêh ta neh ntu, nglay săk Păng lŭh m'ham khĭt yor gâp lĕ nuyh tih. Lơi ƀon ueh ta klơ trôk jŭr ta neh ntu he aơ. Păng hŏ joi ngăn gâp tâm ntŭk jêr, dôl gŭ rêh. Geh Kôranh Brah ueh maak ngăn. nau rêh jêng mâu khan ôh. chuăt hăn ndrel tĭng Păng măt n'gơr uănh ta Kôranh Brah Kôranh Brah hôm kâp gân ngăn ăn gơnh hom plỡ sĭt.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0489", "title": "BRAH NDU RŎNG MAY", "song_number": "489", "lyrics": "BRAH NDU RŎNG MAY\n\n\nVerse 1\nNau Brah Ndu rŏng toyh hâu ngăn, tât Păng ăn Kon Păng, văch jêh tâm neh ntu, ŭch tâm rklaih lĕ nuyh tih. Ƀiă lah he mâu chrê ma Păng, pâng Ô-băl ta si tâm rkăng. Păng yơh jêng Kon Brah Ndu, anh lĕ nau tih âk bunuyh. Srôih dơn tuy si tâm rkăng, ŭch văch ntŭk may jêh ri Gâp, ăn nau rêh ma mbu nơm chroh.\n\nVerse 2\nBâr Kôranh Brah kuăl may aƀaơ ro, ăn may sĭt hom ngăn, Kôranh Brah kâp gân may, ŭch may tĭng ndỗ trong Păng. Păng mra leo lĕ trong may hăn, ŭch may geh nau rêh n'ho ro. Knŏng chroh ma Brah Yê-su, Păng jêng Kôranh Brah nơm rklaih. Păng khĭt ntrok jêh ma may, Păng dơi yỗ ăn nau tih may, Kôranh Brah hôm gŭ kâp gân may.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0490", "title": "JAO NAU JÂK MA YÊ-SU", "song_number": "490", "lyrics": "JAO NAU JÂK MA YÊ-SU\n\n\nVerse 1\nNeh ntu, aơ tih mhĭk hâu ngăn, nâm bu dôl măng ngo. Nâm bu nklang bri brŏng? Nau tih nâm bu tu nâm siăm ƀư rai lĕ mir ba, kŏ tât mâu dơi play...\n\nChorus\nVăch... hom aơ lĕ rngôch bu nuyh anh jâk văch hom sĭt ma Brah Yê-su jao ma Păng nau jâk may. Mprơ hom nau mprơ kloh ma nau răm maak, nâm bu đăr sêm păr klơ trôk tâm rnê ma Yê-su.\n\nVerse 2\nKhay mih, dak kŏ tât bêng ler, nau djôh mhĭk ƀư rai. Ta ntŭk gâp dơi nsing? Gâp du krap tâm Brah Yê su đâp âk geh nau klach, nuih n'hâm gâp đăp mpăn.\n\nChorus\nVăch... hom aơ lĕ rngôch bu nuyh anh jâk văch hom sĭt ma Brah Yê-su jao ma Păng nau jâk may. Mprơ hom nau mprơ kloh ma nau răm maak, nâm bu đăr sêm păr klơ trôk tâm rnê ma Yê-su.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0491", "title": "N'GƠR UĂNH BRAH KLƠ TRÔK", "song_number": "491", "lyrics": "N'GƠR UĂNH BRAH KLƠ TRÔK\n\nTC 545\n\nVerse 1\nN'gơr uănh Brah klơ trôk, kon dăn n'hhơr lĕ nuih n'hâm. N'gơr uănh Brah klơ trôk, dăn n'hhơr mbỡ lĕ nuih n'hâm.\n\nVerse 2\nMbu nơm kâp gân Păng, mâu hôm rngot mâu hôm rvê. Mbu nâm kâp gân Păng, mâu hôm klach lĕ nau rngot. Brah kloh klơ trôk, kon chroh ma Păng. Dôl mông phung mhĭk ƀư rlăng nuih n'hâm dăn ma Mbỡ mât mơh kon nking n'gang kon.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0492", "title": "TĬNG NDỖ KÔRANH BRAH", "song_number": "492", "lyrics": "TĬNG NDỖ KÔRANH BRAH\n\nTVCHH 157\n\nVerse 1\nƠ Nơm rklaih, ŭch rŏng May mâu hôm r-ngơt ôh. Nđâp jêr jŏt, gâp ŭch tĭng ndỗ may lĕ nau rêh! Nđâp tơ lah, nuih n'hâm gâp geh âk nau rŭng răng. Dơm srôih rjăp, gâp ŭch tĭng may mau tăch yơt!\n\nVerse 2\nƠ Nơm rklaih, mâm may mâu plỡ lah ăn gâp maak? May gŭ klăk, nuih n'hâm gâp rngot rvê hâu ngăn ngên. Ơ nơm rklaih, mâm nau may rŏng gâp tât pô aơ? Kŏ may khĭt, huêng nau Brah mât rêh âk bunuyh. Gâp ŭch tĭng ndỗ may kŏ tât lôch nau rêh, gay tâm di ndrel ma nau Păng hŏ rŏng jêh gâp dăn lĕ nuih n'hâm lŏ du tỡ đŏng jêng gâp ŭch tĭng ndỗ May.\n\nVerse 3\nƠ Nơm rklaih, nuih n'hâm gâp gŭ rngeh njrăng ăp măng. Ŭch kâp gân, nâm bu mpa ji hir tĭng joi dak. Ơ nơm rklaih, dăn may gơnh oi hăn chop khâl gâp! Yor gâp aƀaơ, dôl kâp may tât tâm nuih n'hâm.\n\nVerse 4\nƠ Nơm rklaih, dăn May ăn nau ueh maak ma gâp! Lĕ nau tât, mâu lơi ôh Kôranh Brah hŏ ăn jêh. Nđâp ra-ai, nsing ma Kôranh Brah nơm dơi yỗ ăn. Nau Mbỡ rŏng, ôi nau rŏng mâu dơi rlât ôh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0493", "title": "YOR NAU TIH GÂP", "song_number": "493", "lyrics": "YOR NAU TIH GÂP\n\nTC 806\n\nVerse 1\nNơm tâm rklaih rŏng ma gâp, kŏ tât khĭt luh mham khlay mbu nâm gĭt Kôranh Brah dơn yor nau tih gâp, bơh nau ƀỡ ƀơch tâm gâp, mâu dơi klaih đah brah mhĭk jŭm gâp geh âk nau tih rêh tâm neh ntu.\n\nChorus\nƠ Brah Yê-su Nơm tâm rklaih tâm Yê-su gâp dơi klaih jêh rŏng gâp Yê-su hŏ trok khĭt, chuai nau tih gâp.\n\nVerse 2\nGâp nkah ƀa ƀơ gô-tha, geh nau ngo klĕng dŭt n'hâm Kôranh Brah Păng dơn nau nkhĭt yor nau tih gâp bơh tơm nau đêh nji ngăn, mbu nơm gĭt nau Păng rŏng bu ntâp ta pŭng vĕ Păng kŏ tât tăch n'hâm.\n\nChorus\nƠ Brah Yê-su Nơm tâm rklaih tâm Yê-su gâp dơi klaih jêh rŏng gâp Yê-su hŏ trok khĭt, chuai nau tih gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0494", "title": "RDÂK NJÊNG ĂP NAR", "song_number": "494", "lyrics": "RDÂK NJÊNG ĂP NAR\n\nTVCHH 153\n\nVerse 1\nTĭng ndỗ Păng nsrôih rdâk njêng, yor nar mông gơnh rlau. Nđâp mih n'hach sa găp lĕ, ăt nsrôih ngăn pah kan. Nuih n'hâm he ŭch ngăn pah kan gay ma rdâk njêng. Ôi! nau rdâk njêng ueh reh mra mâu blau roh ôh.\n\nChorus\nA-ƀaơ ro rdâk njêng hom yor lah năm khay gơnh rlau lôch jêh. Dăn Mbỡ sol ang gay he gơnh saơ moh ntil kan jŭm he nar aơ, rdâk njêng hom ndrel ma nau ngăn, he pah kan gay chrêk rmah ma Amoh Păng.\n\nVerse 2\nPah kan hom tĭng nau hŏ nsŭk nsôr jêh tâm he. Pah kan tât lôch tât jêng, gay ƀư maak Brah Ndu. Yê-su kơl he mro, Păng ntop n'hâm soan ăp nar. Gơih pah kan hom dôl hôm e geh nau duh nđơr.\n\nChorus\nA-ƀaơ ro rdâk njêng hom yor lah năm khay gơnh rlau lôch jêh. Dăn Mbỡ sol ang gay he gơnh saơ moh ntil kan jŭm he nar aơ, rdâk njêng hom ndrel ma nau ngăn, he pah kan gay chrêk rmah ma Amoh Păng.\n\nVerse 3\nDăn Brah Ndu vơt dơn nau kan he dôl rdâk njêng. Nđâp nau rêh gơnh rlau lôch, lơi ta rung răng ôh. Ŭch rêh ndrel Yê-su ăp năm khay ăp nar mông. Njêng nau chroh đah nau Păng Ngơi dơi rêh đăp rmên.\n\nChorus\nA-ƀaơ ro rdâk njêng hom yor lah năm khay gơnh rlau lôch jêh. Dăn Mbỡ sol ang gay he gơnh saơ moh ntil kan jŭm he nar aơ, rdâk njêng hom ndrel ma nau ngăn, he pah kan gay chrêk rmah ma Amoh Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0495", "title": "TÂM RNGLĂP ĐAH YÊ-SU", "song_number": "495", "lyrics": "TÂM RNGLĂP ĐAH YÊ-SU\n\nTVCHH 151\n\nVerse 1\nDôl gâp hăn ndrel păng pah kan mbơh kloh ueh. Nau rêh he aơ mâu ueh jêh ri sol ang tâm n'hâm gâp. Geh jêh đŏng mông nar nuih n'hâm geh Kôranh Brah. nsing r' nơm Brah Yê-su Păng ăn nau rêh ueh maak ngăn.\n\nChorus\nTâm rnglăp đah Yê-su dăn Mbỡ păng ngăn leo he. rêh ndrel đah Yê-su nuih n'hâm geh ueh maak. Tâm rnê Brah Yê-su Amoh Păng ƀa-ƀơ n'ho ro. nuih n'hâm n'hơr lĕ ăn Păng njôt nau rŏng mbơh lam ăp ntŭk.\n\nVerse 2\nNuih n'hâm gâp rŭng răng nâm bu sial dak rkĕch. Nuih n'hâm geh rngot klân rvê, nơm êng mâu dơi gĭt lĕ ôh. Mbơh ƀa-ƀơ Mbỡ gâp Păng dơn jêh rêh ni. nuih n'hâm dăn Brah Yê-su ăn nau ueh maak ăp nar mông.\n\nChorus\nTâm rnglăp đah Yê-su dăn Mbỡ păng ngăn leo he. rêh ndrel đah Yê-su nuih n'hâm geh ueh maak. Tâm rnê Brah Yê-su Amoh Păng ƀa-ƀơ n'ho ro. nuih n'hâm n'hơr lĕ ăn Păng njôt nau rŏng mbơh lam ăp ntŭk.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0496", "title": "DĂN BRAH HUÊNG UEH NSŬK SÔR GÂP", "song_number": "496", "lyrics": "DĂN BRAH HUÊNG UEH NSŬK SÔR GÂP\n\nTC 616\n\nVerse 1\nTâm trong nau rêh gâp, saơ âk geh nau rngot, tâm lam bri neh aơ mâu geh nau rêh. Dăn Brah Huêng ăn gâp, geh nau rŏng tă bơh Păng ăn phung rai yot, mbêng ler ăp ntŭk. Nđâp lah gâp hơi r'dja dăn Păng ntop n'hâm mhe, nhuat jâng geh nau chroh dơi nsing ma Păng. Măng nar dăn Brah Yê-su ăn Brah Huêng Ueh gay mbơh mhe mhan Păng ma bu-nuyh.\n\nChorus\nHăn gơnh oi hôm e ghe mông găl dơi mbơh ma bu. He mâu mbơh phung nây mra tup ngăn tâm nau rai yot. Lah neh ntu mưch gâp ka đôi, lah neh ntu rmot gâp di đŏng, yor nau rêh geh Yê-su nhuat tĭng hăn têl Păng, mbơh nau mhe mhan.\n\nVerse 2\nNau mhe mhan Brah Ndu, tât lam bri neh ntu, nau mhe mhan mbơh ăp lam bri neh aơ. Gâp ŭch hăn lam bri, nkoch mbơh nau tâm rklaih, Brah Yê-su ăn he ueh uĭn ngăn ngên. Nđâp geh nau jêr tât, nđâp âk phung tun jot, nuih n'hâm gâp maak ngăn mbơh nau mhe mhan. Măng nar dăn Brah Yê-su ăn Brah Huêng Ueh gay mbơh mhe mhan Pang ma bu-nuyh.\n\nChorus\nHăn gơnh oi hôm e ghe mông găl dơi mbơh ma bu. He mâu mbơh phung nây mra tup ngăn tâm nau rai yot. Lah neh ntu mưch gâp ka đôi, lah neh ntu rmot gâp di đŏng, yor nau rêh geh Yê-su nhuat tĭng hăn têl Păng, mbơh nau mhe mhan.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0497", "title": "NAU PĂNG NGƠI", "song_number": "497", "lyrics": "NAU PĂNG NGƠI\n\nTC 621\n\nVerse 1\nLah nuih n'hâm krit kir, uănh nâm bu roh trong. Păng hôm hăn êp kêng gâp ăp nar, gâp mâu mra rung răng, Kôranh Brah leo gâp ăp nhuat. Hăn dach gâp ƀa-ƀơ mro mrăng.\n\nChorus\nDăn Nau Ngơi May sol ang jâng gâp ăp nhuat, sol tâm trong hăn ma gâp.\n\nVerse 2\nNuih n'hâm gâp hôm e, nkah Kôranh Brah leo ăp nhuat, nđâp âk mông gâp hôm hăn trong mhĭk, dăn Yê-su ƀa-ƀơ njŭn gâp Păng kuăn ti gâp. Bơh mông aơ rŏng Păng mro mrăng.\n\nChorus\nDăn Nau Ngơi May sol ang jâng gâp ăp nhuat, sol tâm trong hăn ma gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0498", "title": "NKAH GĬT LAH UEH KÔRANH BRAH", "song_number": "498", "lyrics": "NKAH GĬT LAH UEH KÔRANH BRAH\n\nTC 675\n\nVerse 1\nDăn lah ueh Brah Ndu nơm klơ trôk, ăn nau ueh tâm nuih n'hâm gâp. Lĕ nuih n'hâm ŭch kah gĭt mro mrăng, ăp nar Păng gŭ êp kêng gâp. Lah ueh Kôranh Brah ăp ôi nar mhe, lah ueh Kôranh Brah dôl măng tât. Lah ueh Păng dôl gâp luh dak măt, Kôranh Brah ăn ueh uĭn huêng gâp.\n\nVerse 2\nDăn lah ueh Brah Ndu iăt nau gâp, mâu dun ôh nau gâp mbơh sơm. Dôl sial phŭt vanh blông tâm nau rêh, Kôranh Brah ăn đăp mpăn tâm gâp. Lah ueh Păng dôl maak mâu lah rngot, dơi bonh leng mpư gâp ăp nar. Lah ueh Păng, nau yỗ mâu blau dŭt, geh nau rŏng nơm êng dơi ban.\n\nVerse 3\nLah ueh Brah Ndu Nơm hăn ndrel gâp, nđâp lah geh mâp lok rŏ trong. Lah ueh Kôranh Brah ăn rnăk sa răm maak huêng gâp mprơ tâm rnê Păng. Lah ueh Păng mpư jâng ăp nhuat hăn, nar ôi klak tât ƀon chrêk rmah. Lah ueh Păng, nar kăn ndỡ mra tât, rêh kêng Kôranh Brah maak n'ho ro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0499", "title": "NHHƠR PĂNG LĔ BÔNG RÊH", "song_number": "499", "lyrics": "NHHƠR PĂNG LĔ BÔNG RÊH\n\nTC 687\n\nVerse 1\nDôl Păng njuăl hăn gâp ŭch tông ngăn, tĭng Păng lĕ trong njêng gâp jêng jễ. Mbơh nau mhe mhan ăn bu, nau maak Kôranh Brah n'ho ro; rklaih nơm rêh ni, leo phung nhhơt trong. Dŏng nuih n'hâm gâp nhhơr ăn ma Păng. Nhhơr nuih n'hâm ăn Păng jễ lễ dơm. Nđâp nau rlong uănh rvăn gâp, nđâp dơn âk nau jŏk jêr, răp jăp tâm nuih n'hâm rŏng Păng ngăn!\n\nChorus\nƠ Kôranh Brah ơi! Ơ Kôranh Brah ơi! Dăn Mbỡ ăn nau dơi ma gâp. Gâp mra hăn... Ơ Kôranh Brah ơi! Gâp nhhơr nau rêh.\n\nVerse 2\nNau Păng ăn gâp ŭch djôt ƀa-ƀơ, tât Păng dŏng gâp dơi rek ueh ngăn. Kơl ndâk n'hao âk kon bunuyh, gŭ êng tâm nau roh rai; djôt leo sĭt ntŭk nđăp mpăn ueh maak. Pă ăn nau rŏng mbơh A-moh Păng. Gâp mra hăn mir geh âk ngăn nkao. Mâu nđơr lư amoh gơnh roh, mâu mĭn drăp ndơ roh rai, răp jăp tĭng Păng klơ trong neh ntu!\n\nChorus\nƠ Kôranh Brah ơi! Ơ Kôranh Brah ơi! Dăn Mbỡ ăn nau dơi ma gâp. Gâp mra hăn... Ơ Kôranh Brah ơi! Gâp nhhơr nau rêh.\n\nVerse 3\n...hăn lam ăp ntŭk ng'gor. Srĭh nau mhe mhan n'hôl nau ƀâu kah. Ăn neh ntu gĭt Yê-su, Păng lăp anh nau rêh ni, ăn ma bu-nuyh maak dơn nau rŏng!\n\nChorus\nƠ Kôranh Brah ơi! Ơ Kôranh Brah ơi! Dăn Mbỡ ăn nau dơi ma gâp. Gâp mra hăn... Ơ Kôranh Brah ơi! Gâp nhhơr nau rêh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0500", "title": "NHHƠR KÔRANH BRAH NAU RÊH GÂP", "song_number": "500", "lyrics": "NHHƠR KÔRANH BRAH NAU RÊH GÂP\n\nTC 688\n\nVerse 1\nNar aơ ƀaơ ro, Kôranh Brah ăn ndơ ma gâp, mâu hôm jŏ Ha-đăch Yê-su Păng mra gơnh jŭr plỡ đŏng. Nhhơr Kôranh Brah khay năm nĕ, huêng soan nau mĭn aơ. lĕ rngôch ndơ khlay tâm Păng da-dê.\n\nChorus\nNar aơ gâp nhhơr May n'hâm soan nau mĭn gâp rvê. Ăp mông nar gâp gŭ rêh, Păng ăn ndơ khlay. Tâm nau rŏng Kôranh Brah, gâp nhhơr Păng lĕ nau rêh. Dăn Brah Huêng Ueh mbêng ler, Ha-lê-lu-ya!\n\nVerse 2\nNar aơ ...ƀaơ ro, mông găl roh mâu hôm saơ. Nuih n'hâm gâp ŭch dăn May maak kơl gâp gŭ rêh gĭt mĭn. Nhhơr lĕ ăn ma Kôranh Brah, rŏng âk ma bu-nuyh Ƀon ueh maak... vơt đon hađăch Păng ăn.\n\nChorus\nNar aơ gâp nhhơr May n'hâm soan nau mĭn gâp rvê. Ăp mông nar gâp gŭ rêh, Păng ăn ndơ khlay. Tâm nau rŏng Kôranh Brah, gâp nhhơr Păng lĕ nau rêh. Dăn Brah Huêng Ueh mbêng ler, Ha-lê-lu-ya!\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0501", "title": "NÂP NAU CHROH", "song_number": "501", "lyrics": "NÂP NAU CHROH\n\nTC 717\n\nVerse 1\nSăk jăn aơ vay uănh nâm jễ lễ. Mâu geh khư ta klang bunuyh âk. Păng bơh trôk măng nar treng uănh saơ. Ăp chuat gâp nđâp du njrăr rêh.\n\nChorus\nMbỡ nau rŏng ƀa-ƀơ leo trong. Mbỡ nau rŏng ƀa-ƀơ mât he. Nđâp nau rêh mâp âk phŭt sial, mâu pât nggơ răp jăp tĭng Păng. Ti nau rŏng Păng mro leo trong gâp mâu lơi. Păng mra njŭn trong leo nau rêh gâp.\n\nVerse 2\nPăng dêh rhêt vay iăt gâp mbơh sơm. Dôl gâp chon ta nkêng jâng Păng. Lĕ nau rngot rvê gâp mâu mpôn ôh. Văch ma Mbỡ mbơh lĕ ma Păng.\n\nChorus\nMbỡ nau rŏng ƀa-ƀơ leo trong. Mbỡ nau rŏng ƀa-ƀơ mât he. Nđâp nau rêh mâp âk phŭt sial, mâu pât nggơ răp jăp tĭng Păng. Ti nau rŏng Păng mro leo trong gâp mâu lơi. Păng mra njŭn trong leo nau rêh gâp.\n\nVerse 3\nLĕ kan tâm nau rêh gâp Mbỡ gĭt. Lĕ nau jêr Păng gĭt lĕ ƀhiău. Geh du nar Păng mra kuăl gâp sĭt. Rêh ndrel Mbỡ mâu hôm rngot rvê.\n\nChorus\nMbỡ nau rŏng ƀa-ƀơ leo trong. Mbỡ nau rŏng ƀa-ƀơ mât he. Nđâp nau rêh mâp âk phŭt sial, mâu pât nggơ răp jăp tĭng Păng. Ti nau rŏng Păng mro leo trong gâp mâu lơi. Păng mra njŭn trong leo nau rêh gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0502", "title": "ĂP NHUAT RŎ TRONG", "song_number": "502", "lyrics": "ĂP NHUAT RŎ TRONG\n\nTC 739\n\nVerse 1\nTrong hăn kue kuăch, ăp nhuat gâp treng uănh Păng. Kôranh Brah yơr ti nau rŏng leo gâp lĕ trong. Nđâp ntŭk vri rngol, răp jăp nsing ngăn ma Păng; nđâp mih n'hach, ăt nđăp mpăn mâu hôm rvê.\n\nChorus\nĂp nhuat rŏ trong, gâp gĭt Păng hăn ndrel ma gâp, nau rŏng Păng mât mơh chiă uănh nuih n'hâm gâp. Ôi taơ chrat ang, dôl gâp cha lơi ngai neh ntu, dŭt nhuat mprơ nteh: Gâp hŏ tât ntŭk ƀon ueh.\n\nVerse 2\nÂk tỡ nau jêr, njêng nau chroh jêng pât nggơ, nking lĕ trong hăn âk lơn rngot tâm nuih n'hâm. Hao sĭt ƀon ueh, joi saơ âk nau rêh maak; jâng nhuat nâp, lĕ njăr trong hăn dŭt ngai.\n\nChorus\nĂp nhuat rŏ trong, gâp gĭt Păng hăn ndrel ma gâp, nau rŏng Păng mât mơh chiă uănh nuih n'hâm gâp. Ôi taơ chrat ang, dôl gâp cha lơi ngai neh ntu, dŭt nhuat mprơ nteh: Gâp hŏ tât ntŭk ƀon ueh.\n\nVerse 3\nPăng ăn ma gâp, nau rêh mhe n'ho ro ngăn, Păng nhuat êp gâp ƀa-ƀơ măng nar mâu lơi. Păng djôt tâm ti khoă ƀon ueh nau chrêk rmah; ntŭk ueh maak, Păng njŭn leo gâp nhuat hăn.\n\nChorus\nĂp nhuat rŏ trong, gâp gĭt Păng hăn ndrel ma gâp, nau rŏng Păng mât mơh chiă uănh nuih n'hâm gâp. Ôi taơ chrat ang, dôl gâp cha lơi ngai neh ntu, dŭt nhuat mprơ nteh: Gâp hŏ tât ntŭk ƀon ueh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0503", "title": "DĂN KÔRANH BRAH KUĂN TI GÂP", "song_number": "503", "lyrics": "DĂN KÔRANH BRAH KUĂN TI GÂP\n\nTC 744\n\nVerse 1\nDăn May kuăn leo ti gâp tâm nau rêh neh ntu. Mâp geh âk nau ndơm, mra tât tâm nau rêh. Nau rêh gâp hăn ngai đah May cha lôt ro. Dăn May ăn gâp saơ nau rŏng May ăp nar.\n\nChorus\nŬch dăn Kôranh Brah kuăn leo trong nau rêh gâp. Yor lah Mbỡ ơi, neh ntu ngo klêng ngăn. Trong gâp hăn ngai ngăn, dăn May sol ang, ăp nhuat tâm nau rêh, dăn May kuăn ti gâp.\n\nVerse 2\nDăn May kuăn leo ti gâp tâm nau rêh rnăk sa. Mâp geh âk nau tât mra geh dăk măt nhĭm. Gâp uănh ta Kôranh Brah mbơh sơm dăn ma Mbỡ. Nau ueh răm maak tât he ŭch tâm rnê Păng.\n\nChorus\nŬch dăn Kôranh Brah kuăn leo trong nau rêh gâp. Yor lah Mbỡ ơi, neh ntu ngo klêng ngăn. Trong gâp hăn ngai ngăn, dăn May sol ang, ăp nhuat tâm nau rêh, dăn May kuăn ti gâp.\n\nVerse 3\nDăn May kơl gâp du bông rêh chroh răp jăp ngăn. Ăn gâp chroh răp jăp tât lôch du bông rêh. Lah geh âk nau ndơm tât tâm nau rêh gâp. Dăn nau rŏng May sol ang gâp mât mơh gâp.\n\nChorus\nŬch dăn Kôranh Brah kuăn leo trong nau rêh gâp. Yor lah Mbỡ ơi, neh ntu ngo klêng ngăn. Trong gâp hăn ngai ngăn, dăn May sol ang, ăp nhuat tâm nau rêh, dăn May kuăn ti gâp.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0504", "title": "TRONG HĂN GEH KÔRANH BRAH", "song_number": "504", "lyrics": "TRONG HĂN GEH KÔRANH BRAH\n\nTC 748\n\nVerse 1\nTrong gâp hăn geh âk ngăn lok rting bêng ler, nau krit kir ŭch ngăn rvăn jâng gâp. Dăn ma Kôranh Brah Yê-su plỡ lah gơnh ro, Păng njŭn trong rgăn nau jêr bông rêh.\n\nChorus\nNsing ngăn ma Păng ăn nhuat hăn tât, tĭng jâng Păng ngăn ăn nhuat hăn tât. Dăn Kôranh Brah ntop n'hâm, gâp nsing nâp ngăn ngên ntop nau dơi, ntop nau chroh tĭng Păng.\n\nVerse 2\nNeh ntu ŭch kuăn gâp ƀư tĭng gâp nơm ŭch, jêh ri njŭn tâm nau tih gơnh roh. Dăn ma nau rŏng Mbỡ kuăn gâp rgăn bŏk jru, kuăn leo tât ntŭk ueh maak đăp mpăn.\n\nChorus\nNsing ngăn ma Păng ăn nhuat hăn tât, tĭng jâng Păng ngăn ăn nhuat hăn tât. Dăn Kôranh Brah ntop n'hâm, gâp nsing nâp ngăn ngên ntop nau dơi, ntop nau chroh tĭng Păng.\n\nVerse 3\nPăng hăn trong lok ngăn gay sol trong rah vah, ndrel kơl gâp hăn rgăn nau ngo mbâl. Păng djôt ti leo trong ăp mông mnĭt mâu lơi, njŭn gâp sĭt kêng dak rngân đăp mpăn.\n\nChorus\nNsing ngăn ma Păng ăn nhuat hăn tât, tĭng jâng Păng ngăn ăn nhuat hăn tât. Dăn Kôranh Brah ntop n'hâm, gâp nsing nâp ngăn ngên ntop nau dơi, ntop nau chroh tĭng Păng.\nA-MEN.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0505", "title": "MPRƠ LĔ BÔNG RÊH", "song_number": "505", "lyrics": "MPRƠ LĔ BÔNG RÊH\n\nTC 799\n\nVerse 1\nPăng ăn nau ueh nâm mih toyh, tât ma ndrêch rdăh dôl ji hir. Hŏ jŏ nar kâp dak mih tŏ nđik, neh rhơn ngăn nuih n'hâm hên răm maak.\n\nChorus\nNau rŏng Kôranh Brah rmeh ler, huy nâm dak mƀŭt dak me, ngai rlau mănh mbing rbăn ntŭk prêh ngăn. Gâp rŏng Kôranh Brah hâu ngăn, dăn ăn răp jăp tông bâr; ton hăn ndrel Păng lĕ bông rêh mprơ. ...tĭng Păng.\n\nVerse 2\nĂp năm khay yor Mbỡ hăn uănh, hŏ njŭn leo tâm ăp nhuat hăn. Klơ trong hăn geh Păng hôm mât mơh, kơl ăn phung hên dôl mâp nau jêr.\n\nChorus\nNau rŏng Kôranh Brah rmeh ler, huy nâm dak mƀŭt dak me, ngai rlau mănh mbing rbăn ntŭk prêh ngăn. Gâp rŏng Kôranh Brah hâu ngăn, dăn ăn răp jăp tông bâr; ton hăn ndrel Păng lĕ bông rêh mprơ. ...tĭng Păng.\n\nVerse 3\nPăng mât mơh nau rêh đăp mpăn, ăt răm maak nar măng munh mprơ. Dôl hôm jễ dơi ntĭm nti mât mơh, tât toyh jêh Păng ăt hôm mât chiăp.\n\nChorus\nNau rŏng Kôranh Brah rmeh ler, huy nâm dak mƀŭt dak me, ngai rlau mănh mbing rbăn ntŭk prêh ngăn. Gâp rŏng Kôranh Brah hâu ngăn, dăn ăn răp jăp tông bâr; ton hăn ndrel Păng lĕ bông rêh mprơ. ...tĭng Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0506", "title": "MĬT JIĂNG GÂP RŎNG NGĂN", "song_number": "506", "lyrics": "MĬT JIĂNG GÂP RŎNG NGĂN\n\nTC 803\n\nVerse 1\nPăng ngơi ndrel ma gâp, gŭ ndrel tâm krêp nâm bu gui. Păng văch tâm nau rêh, anh ntrok lĕ rngôch r'ngot r'vê. Nau rŏng Păng khlay ngăn, Păng bêng nau rŏng ma gâp. Pă nau r'ngot maak, nđâp nau jêr tâm nau rêh.\n\nChorus\nMĭt jiăng gâp kah r'vê, mĭt jiăng gâp rŏng ngăn, bêng ler nau rŏng răp jăp, mra njŭn gâp tât ntŭk chrêk rmah. Mĭt jiăng gâp kah r'vê, jêng Yê-su nau rŏng. Păng dŏng nau rŏng răp jăp, chiă nuih n'hâm gâp răm maak.\n\nVerse 2\nPăng gâp mâu pưt ngai, êp ngăn hăn ndrel ta rbăn trong. Nklang neh ntu ngo klêng, ăn ma gâp nau bonh leng. Dôl geh nau krit kir, lĕ rngôch mĭt jiăng lơi gâp. Păng mâu lơi gâp, Păng mâu ăn gâp gŭ êng.\n\nChorus\nMĭt jiăng gâp kah r'vê, mĭt jiăng gâp rŏng ngăn, bêng ler nau rŏng răp jăp, mra njŭn gâp tât ntŭk chrêk rmah. Mĭt jiăng gâp kah r'vê, jêng Yê-su nau rŏng. Păng dŏng nau rŏng răp jăp, chiă nuih n'hâm gâp răm maak.\n\nVerse 3\nPăng mât gâp măng nar, nau tât mâu njêng ăn gâp klach. Geh Păng tâm nuih n'hâm, huêng gâp bêng ma hâk maak. Kŭnh uănh nau rŏng Păng, nơm mĭt jiăng mâu geh rgâl. Neh ntu mâu geh, răp jăp đah gâp kơt Păng.\n\nChorus\nMĭt jiăng gâp kah r'vê, mĭt jiăng gâp rŏng ngăn, bêng ler nau rŏng răp jăp, mra njŭn gâp tât ntŭk chrêk rmah. Mĭt jiăng gâp kah r'vê, jêng Yê-su nau rŏng. Păng dŏng nau rŏng răp jăp, chiă nuih n'hâm gâp răm maak.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0507", "title": "NHHƠR LĔ MA YÊ-SU", "song_number": "507", "lyrics": "NHHƠR LĔ MA YÊ-SU\n\nTC 805\n\nVerse 1\nDăn May yỗ ăn lĕ nau tih ƀỡ ƀơch. Dăn May leo gâp lĕ nhuat hăn; Nuih n'hâm gâp ŭch nhhơr lĕ ma Yê-su, gâp ŭch tĭng ndỗ May ƀa-ƀaơ. Păng leo trong gâp jêh ri rŏng gâp lĕ bông rêh tuy nau tih gâp săk Păng chah rai. Dăn mbêng nau Brah mhe nhuat gâp mâu rlu, ăn nau rêh gâp maak mro mrăng.\n\nVerse 2\nDôl May leo gâp ta nau rŏng jru huy. Gâp đah Brah Krist n'ho gŭ ndrel; Dôl mĭn rŭng răng Yê-su ƀư roh ro, gâp dơi gŭ ndrel Păng ƀa-ƀaơ. Păng leo trong gâp jêh ri rŏng gâp lĕ bông rêh tuy nau tih gâp săk Păng chah rai. Dăn mbêng nau Brah mhe nhuat gâp mâu rlu, ăn nau rêh gâp maak mro mrăng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0508", "title": "ŬCH RĂP JĂP NGĂN", "song_number": "508", "lyrics": "ŬCH RĂP JĂP NGĂN\n\nTC 827\n\nVerse 1\nChuăt tĭng Păng ăp nar gâp mâu hôm rvê; mih n'hach mâu rvê ôh, jŏk jêr mâu mĭn! Geh mông mâp âk khan ntil nau rngot klân, dơi rgăn lĕ rngôch yor geh Păng lăp gŭ.\n\nChorus\nHăn tĭng Brah Yê-su, Nơm gâp rŏng ngăn. Tĭng Păng lĕ bông rêh, ŭch răp jăp ngăn. Tĭng Kôranh Brah ăp nar, nuih n'hâm ueh maak. Rêh răm maak đăp mpăn, maak tâm Kôranh Brah.\n\nVerse 2\nNđâp lah geh nau o-ach mâu pât nggơ; neh ntu knŏng manh dơm, mâu geh rêh mro! Krit kir mâu klach ôh yor Păng ntop n'hâm, jao nau rêh ăn ma Păng bêng nau dơi.\n\nChorus\nHăn tĭng Brah Yê-su, Nơm gâp rŏng ngăn. Tĭng Păng lĕ bông rêh, ŭch răp jăp ngăn. Tĭng Kôranh Brah ăp nar, nuih n'hâm ueh maak. Rêh răm maak đăp mpăn, maak tâm Kôranh Brah.\n\nVerse 3\nLah mâp geh rdja nuih gâp dăn ma Păng; jut lĕ ƀhiau rgănh rgônh, gŭ dâk răp jăp! Nau ngo mra du ngai dôl nau ang tât, mâu hôm klach ôh yor geh Păng hăn ndrel.\n\nChorus\nHăn tĭng Brah Yê-su, Nơm gâp rŏng ngăn. Tĭng Păng lĕ bông rêh, ŭch răp jăp ngăn. Tĭng Kôranh Brah ăp nar, nuih n'hâm ueh maak. Rêh răm maak đăp mpăn, maak tâm Kôranh Brah.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0509", "title": "DÂK HĂN YOR AMOH PĂNG", "song_number": "509", "lyrics": "DÂK HĂN YOR AMOH PĂNG\n\nTC 838\n\nVerse 1\nTông hăn tĭng nau Păng kuăl he, gơnh hăn ăp ntŭk dăch ngai, nkoch mbơh nau mhe mhan Păng ăn. Tĭng ndrel phung oh mon kăl e hăn ndrel Kôranh Brah lam ntŭk mbơh nau mhe mhan ma bunuyh.\n\nChorus\nHăn ndrel tĭng Mbỡ nđâp lah dăch ngai, ăt srôih ngăn, răp jăp pah kan Mbỡ kloh. Mprơ tâm rnê... gay ma lư ăp ntŭk ƀa-ƀơ... Nsrôih mbơh nau mhe mhan.\n\nVerse 2\nUănh lam neh ntu dôl roh rai, neh ntu dôl nhhơt trong hăn, dĭng geh âk bu-nuyh rêh ni. Dôl nhĭm nhhiăng tâm nau tih mhĭk mâu lah ŭch iăng tâm nau maak ta neh ntu roh rai.\n\nChorus\nHăn ndrel tĭng Mbỡ nđâp lah dăch ngai, ăt srôih ngăn, răp jăp pah kan Mbỡ kloh. Mprơ tâm rnê... gay ma lư ăp ntŭk ƀa-ƀơ... Nsrôih mbơh nau mhe mhan.\n\nVerse 3\nNđâp klơ trong hăn mâu đăp mpăn, geh âk lok rting neh ntu, he ăt lĕ du nuih n'hâm chroh. Chroh ma Brah Yê-su nau dơi măt Păng uănh he ƀa-ƀơ dôl hăn klơ trong nau rêh.\n\nChorus\nHăn ndrel tĭng Mbỡ nđâp lah dăch ngai, ăt srôih ngăn, răp jăp pah kan Mbỡ kloh. Mprơ tâm rnê... gay ma lư ăp ntŭk ƀa-ƀơ... Nsrôih mbơh nau mhe mhan.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0510", "title": "NUIH N'HÂM ŬCH PAH KAN", "song_number": "510", "lyrics": "NUIH N'HÂM ŬCH PAH KAN\n\nTC 840\n\nVerse 1\nNâm bu ndâr tŭk ăn nđik nau rêh, gâp dơi gĭt rŏng bu-nuyh răp jăp. Nâm bu dak mih tŏ tơm si dôl hir dak. Djôt nau kâp gân pah kan ma Mbỡ âk lơn.\n\nChorus\nNhhơr nuih n'hâm âk lơn ma Păng, nhhơr nau rêh răp jăp ma Păng, tĭng ndỗ Kôranh Brah hăn rklaih bu-nuyh.\n\nVerse 2\nTôr gâp ŭch iăt tông nau Păng đă, jâng gâp ŭch tĭng ndỗ Păng răp jăp. Nuih n'hâm gâp ŭch ton gay tĭng pah kan kloh. Dăn ăn măt gâp uănh ta Kôranh Brah gay hăn.\n\nChorus\nNhhơr nuih n'hâm âk lơn ma Păng, nhhơr nau rêh răp jăp ma Păng, tĭng ndỗ Kôranh Brah hăn rklaih bu-nuyh.\n\nVerse 3\nJum gâp âk ngăn bu-nuyh rêh ni, dăn lĕ nuih n'hâm gay kơl khân păng. Mbu dôl rdja nuih yor mâu gĭt trong nau rêh. Gâp ŭch maak kơl khân păng sĭt ma Kôranh Brah.\n\nChorus\nNhhơr nuih n'hâm âk lơn ma Păng, nhhơr nau rêh răp jăp ma Păng, tĭng ndỗ Kôranh Brah hăn rklaih bu-nuyh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0511", "title": "NHHƠR KON SE MA KÔRANH BRAH", "song_number": "511", "lyrics": "NHHƠR KON SE MA KÔRANH BRAH\n\nTC 880\n\nVerse 1\nNjŭn kon se ta Mbỡ, dăn May chiă mât njŭn leo, ntơm bơh kon se dôl hôm oh bê tât ta ranh. Tâm ban n'ha kloh ng'lang, dăn nau Ngơi Yê-su chih. Geh Kôranh Brah jêng nơm chiă mât lĕ du bông rêh.\n\nChorus\nBơh kon se hôm oh bê, gĭt nkah nau Ngơi Mbỡ. Brah n'ho ro njŭn leo, nhuat jâng gâp tĭng ndỗ May.\n\nVerse 2\nNjŭn kon se ta Mbỡ, ut ra-u ma nau rŏng, ma nuih n'hâm rmơih rmên, nau kloh ueh lĕ bông rêh. Tâm ban ma rchuăl uk tâm ti Kôranh Brah Nơm mon. Nau ang Kôranh Brah leo trong hăn lĕ du bông rêh.\n\nChorus\nBơh kon se hôm oh bê, gĭt nkah nau Ngơi Mbỡ. Brah n'ho ro njŭn leo, nhuat jâng gâp tĭng ndỗ May.\n\nVerse 3\nNjŭn kon se ta Mbỡ, dăn May ăn ntop n'hâm soan, ăn kon se blau mĭn, rŏng May, rŏng ma bu-nuyh, đăp mpăn geh Yê-su, tâm Kôranh Brah geh ntŭk nsing. Rêh tâm dâng gui Kôranh Brah Nơm lĕ du njar rêh.\n\nChorus\nBơh kon se hôm oh bê, gĭt nkah nau Ngơi Mbỡ. Brah n'ho ro njŭn leo, nhuat jâng gâp tĭng ndỗ May.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0512", "title": "NAU MAAK UR SAI", "song_number": "512", "lyrics": "NAU MAAK UR SAI\n\nTC 885\n\nVerse 1\nDu nar tâm đang Ê-đen kăl-e Mbỡ kloh tâm nđăp ur sai, nar nay geh rmưn rsen phung sĭm mphăr tâm đang mprơ ndrâu hâk maak.\n\nChorus\nDăn nau rŏng gŭ tâm ur sai ƀa-ƀơ. Dăn nau rŏng bar hê bêng ma ƀâu kah; Rnăk sa maak tâm Kôranh Brah rêh răm maak tâm r'nglăp, nđâp nau rêh ni ji kuet mâu dơi khah khat ôh.\n\nVerse 2\nBu-nuyh dôl gŭ tâm đang Ê-đen kăl-e geh nau tâm rŏng, tanh njir lĕ nar răm khay nau rŏng đăp mpăn răm maak hâu ngăn.\n\nChorus\nDăn nau rŏng gŭ tâm ur sai ƀa-ƀơ. Dăn nau rŏng bar hê bêng ma ƀâu kah; Rnăk sa maak tâm Kôranh Brah rêh răm maak tâm r'nglăp, nđâp nau rêh ni ji kuet mâu dơi khah khat ôh.\n\nVerse 3\nRnôk aơ păng mra rlau lôch rnôk êng mra tât geh âk nau rgâl, ƀiă lah geh rbăn play nuih răm rhơn tâm nau rŏng mâu dơi roh.\n\nChorus\nDăn nau rŏng gŭ tâm ur sai ƀa-ƀơ. Dăn nau rŏng bar hê bêng ma ƀâu kah; Rnăk sa maak tâm Kôranh Brah rêh răm maak tâm r'nglăp, nđâp nau rêh ni ji kuet mâu dơi khah khat ôh.\n\nVerse 4\nNar aơ trôk ang bêng ma nau răm maak bar hê jêng ur sai, dăn Păng văch gŭ ta nkang ntŭk yơk mbah iăt nau khân păng ton.\n\nChorus\nDăn nau rŏng gŭ tâm ur sai ƀa-ƀơ. Dăn nau rŏng bar hê bêng ma ƀâu kah; Rnăk sa maak tâm Kôranh Brah rêh răm maak tâm r'nglăp, nđâp nau rêh ni ji kuet mâu dơi khah khat ôh.\n\nVerse 5\nNdrel ma gong rêng nteh r'êng maak nar Mbỡ nau rŏng nđăp bar hê, dăn văch mprơ maak bar hê ndâk njêng rnăk sa nđăp mpăn răm maak.\n\nChorus\nDăn nau rŏng gŭ tâm ur sai ƀa-ƀơ. Dăn nau rŏng bar hê bêng ma ƀâu kah; Rnăk sa maak tâm Kôranh Brah rêh răm maak tâm r'nglăp, nđâp nau rêh ni ji kuet mâu dơi khah khat ôh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0513", "title": "NAR MAAK UR SAI MHE", "song_number": "513", "lyrics": "NAR MAAK UR SAI MHE\n\nTC 887\n\nVerse 1\nNg'gông nteh ngăn nklang ngih Brah nar aơ răm maak! Nteh mŭnh mprơ mông nay yơh maak ngăn ngên. Ur sai mhe djôt kao si ueh tâm nar dŭt maak mông nay khlay hăn ndrel bu-nuyh nơm gâp rŏng.\n\nVerse 2\nNg'gông nteh ngăn nklang ngih Brah nar aơ răm maak! Nteh mŭnh mprơ mông nay yơh maak ngăn ngên. Geh bar hê chon kô mâk ndrel ma nau vơl dăn ueh nhhơr đŏng nau he tâm rŏng hôm ƀa-ƀơ.\n\nVerse 3\nMông nar ueh he hôm nkah mro tâm nuih n'hâm! Khân păng ntơm jêng bar a-ƀaơ jêng nguay. Lah ueh Kôranh Brah ăn nau đăp mpăn bơh klơ trôk, ăn phung he mpơl rêh ueh lư A-moh Păng.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0514", "title": "NĂM MHE TÂT KÊNG NGIH", "song_number": "514", "lyrics": "NĂM MHE TÂT KÊNG NGIH\n\nTC 889\n\nVerse 1\nRi uănh hom sĭm mpăr ndăch klang trôk, mbơh gĭt yan kao ueh maak lŏ plỡ, phung sĭm och ndrau mpăr tâm ăp ntŭk, maak vơt năm mhe lĕ tât jêh. Lĕ rngôch bu-nuyh răm maak mbung mprơ, gơm rnê ma năm mhe đăp mpăn. Kôranh Brah nkhŭt ăn nau ueh uĭn lĕ, nau rêh bêng ma nau ueh maak.\n\nChorus\nDăn Mbỡ nkhŭt nau ueh uĭn, ăn hên gŭ maak ƀa-ƀơ. Ăn ma hên nau đăp mpăn, ueh maak vơt năm mhe. Ri uănh du năm ơm rlau ngăch ngăn, du năm mhe ueh maak hŏ tât jêh, lơi lĕ nau rngot rvê tâm nuih n'hâm, ăn gâp tu nau ueh.\n\nVerse 2\nRi uănh hom kao si dang ueh reh, mbơh yan kao tât ma ăp rnăk vâl, yan kao lŏ plỡ âk nau ueh uĭn, du năm mhe bêng nau hơm răm. Lĕ rngôch ndơ bơh Brah Ndu Nơm ăn, Păng ăn du năm mhe ueh maak. Kôranh Brah yơh jêng kao ueh ƀâu kah, ăn ma he nau ueh rmeh ler.\n\nChorus\nDăn Mbỡ nkhŭt nau ueh uĭn, ăn hên gŭ maak ƀa-ƀơ. Ăn ma hên nau đăp mpăn, ueh maak vơt năm mhe. Ri uănh du năm ơm rlau ngăch ngăn, du năm mhe ueh maak hŏ tât jêh, lơi lĕ nau rngot rvê tâm nuih n'hâm, ăn gâp tu nau ueh.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0515", "title": "MAAK YAN KAO", "song_number": "515", "lyrics": "MAAK YAN KAO\n\nTC 891\n\nVerse 1\nMaak yan kao văch, Păng ăn nau ueh ta ndrêch gỡ nse, lĕ kao mra dang, ăn nau ƀâu kah leo nsong tâm lam neh ntu. Uănh ma sial tŭk, ĭr ang ueh ngăn, nđâp ndrêch lŏ mir n'ha si ĭr ngăn tâm ntŭk jâng trôk rbăn kao ueh vơt năm mhe.\n\nChorus\nSĭm och maak ndrau mpăr ta tơm si, maak mpăr ndăch vah vang trôk, lĕ rngôch nuyh mprơ bâr nteh ktang maak vơt du năm mhe. Năm mhe dăn Păng gŭ tâm nuih n'hâm nkhŭt nau ueh uĭn bơh trôk, maak ngăn lah geh Păng chiă uănh aơ ngăn yan kao.\n\nVerse 2\nDu năm ngăch rlau nâm bu tŭk tâm trôk maak năm mhe, mprơ lĕ nuih n'hâm, mprơ ma Kôranh Brah ăn he du năm đăp mpăn. Dăn Mbỡ nkhŭt ăn nau ueh rmeh ler, ŭch yan kao mhe he rêh răm maak, nâm bu kao ueh djôt nau maak ma lĕ bunuyh.\n\nChorus\nSĭm och maak ndrau mpăr ta tơm si, maak mpăr ndăch vah vang trôk, lĕ rngôch nuyh mprơ bâr nteh ktang maak vơt du năm mhe. Năm mhe dăn Păng gŭ tâm nuih n'hâm nkhŭt nau ueh uĭn bơh trôk, maak ngăn lah geh Păng chiă uănh aơ ngăn yan kao.\n\nVerse 3\nNdrel n'grŭp he mprơ nau mprơ n'ho ro rnê ma ăp nơm rêh maak ƀa-ƀơ, ăn he mprơ nteh ktang hom tâm rnê Brah Ndu. yor nau Mbỡ rŏng, ăn ăp bu-nuyh, nâm bu kao si ueh uĭn răm maak, nâm bu kao si dang nhuat lăp tâm nuih n'hâm.\n\nChorus\nSĭm och maak ndrau mpăr ta tơm si, maak mpăr ndăch vah vang trôk, lĕ rngôch nuyh mprơ bâr nteh ktang maak vơt du năm mhe. Năm mhe dăn Păng gŭ tâm nuih n'hâm nkhŭt nau ueh uĭn bơh trôk, maak ngăn lah geh Păng chiă uănh aơ ngăn yan kao.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0516", "title": "NHHƠR NAU RÊH PAH KAN KÔRANH BRAH", "song_number": "516", "lyrics": "NHHƠR NAU RÊH PAH KAN KÔRANH BRAH\n\nTC 896\n\nVerse 1\nNuih n'hâm gâp aak tăng bâr Păng kuăl, ba dŭm tâm mir dôl kâp rek. Nsŭk nsôr nuih n'hâm gâp gơnh hăn hom, gơnh oi tĭng têl Brah Yê-su. Tĭng ndỗ Păng jêng Nơm rmak ueh ngăn; bêng ma nau rŏng, nau dêh r'hêt. Mbêng hom ăn gâp bêng Brah Huêng Ueh, gay gâp dơi sol ang ma neh ntu.\n\nChorus\nNhhơr nau rêh gâp ma Brah Yê-su, ŭch tông bâr Păng a-ƀaơ ro. Nay jêng nau yỗ Păng ăn ma gâp, nsrôih pah kan Păng răp jăp ngăn.\n\nVerse 2\nÂk huêng bu-nuyh mâu hŏ gĭt Mbỡ, nuih n'hâm mâu geh nau nđăp mpăn. Gâp ŭch nhhơr nuih n'hâm gâp ma May, gay mbơh khân păng gĭt Kôranh Brah. Tuy si tâm rkăng tĭng ndỗ Yê-su; gĭt nhhơr nau rêh, gĭt yỗ bu. Maak tông bâr Kôranh Brah njuăl gâp hăn ntŭk phung ƀon lan dôl kâp gân gâp.\n\nChorus\nNhhơr nau rêh gâp ma Brah Yê-su, ŭch tông bâr Păng a-ƀaơ ro. Nay jêng nau yỗ Păng ăn ma gâp, nsrôih pah kan Păng răp jăp ngăn.\n\nVerse 3\nTông bâr Mbỡ đă hăn chiăp phung biăp, lĕ nuih n'hâm mâu rdja nuih ôh. Dăn May ăn nau ueh lăng âk ler, gay leo phung biăp lăp tâm ndrung. Mâu yor nau lư yor nau ndrŏng kuăng; nau ndrŏng tâm neh ntu mra roh. Ăn gâp nsrôih hăn mbơh nau mhe mhan, gay phung tih mhĭk sĭt chroh ma May.\n\nChorus\nNhhơr nau rêh gâp ma Brah Yê-su, ŭch tông bâr Păng a-ƀaơ ro. Nay jêng nau yỗ Păng ăn ma gâp, nsrôih pah kan Păng răp jăp ngăn.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0517", "title": "TĬNG NDỖ KÔRANH BRAH ĂP NAR", "song_number": "517", "lyrics": "TĬNG NDỖ KÔRANH BRAH ĂP NAR\n\n\nVerse 1\nN'hâm hươi jâng ti rgănh, bông rêh nau ngo nkŭm. Dăn Mbỡ njŭn leo ăn geh nau mĭn kloh ueh, lĕ du bông nau rêh. Ut r'u gâp ueh lơn. Mpư gâp prêh lơn. Gâp lĕ nuih n'hâm nhuat tĭng ndỗ Păng. Rŏng Kôranh Brah ăp nar.\n\nChorus\nDăn ăn tâm nar aơ, gâp vơh vơl. Nhuat ndrel ma Păng lĕ ăp mông. Dăn ma Păng njŭn leo, geh n'hâm soan rmeh ler, ƀa-ƀơ pah kan Păng. Năm khay mra lôch, mâu hôm ôh jêh ri neh ntu mra rlau lôch lĕ đŏng. Knong nau Brah Ndu Ngơi, sol ang ăn kon tĭng ndỗ Păng ăp nar.\n\nVerse 2\nNau rêh he mra rai, sư rlau lam ăp ntŭk. Ơ Brah Yê-su neh ntu aơ nâm dak rdu, iăng hêng tâm mhĭk blem. Ut r'u gâp mông aơ. N'ho ro mro mrăng. Uănh Păng ƀa-ƀơ nhuat tĭng Kôranh Brah. Rŏng Kôranh Brah ăp nar.\n\nChorus\nDăn ăn tâm nar aơ, gâp vơh vơl. Nhuat ndrel ma Păng lĕ ăp mông. Dăn ma Păng njŭn leo, geh n'hâm soan rmeh ler, ƀa-ƀơ pah kan Păng. Năm khay mra lôch, mâu hôm ôh jêh ri neh ntu mra rlau lôch lĕ đŏng. Knong nau Brah Ndu Ngơi, sol ang ăn kon tĭng ndỗ Păng ăp nar.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0518", "title": "NƠM BRAH RÊH N'HO RO", "song_number": "518", "lyrics": "NƠM BRAH RÊH N'HO RO\n\n\nVerse 1\nNĕ ntŭk rlŭng ngo păng gŭ nking ta klang aơ. Nđâp ma rbăn yôk prêh, gâp mâu dơi rgăn. Ta nklang bêng krit kir nuih n'hâm gâp n'gơr uănh, vơh vơl mbơh sơm dôl tâm klung măng. Jêh ri nau ngo roh nau ang sol dêh rhêt. Jut lĕ nau rngot tâm nuih n'hâm gâp, lĕ ntil hŏ tât dôl mông dŭt nau hŏ chih Yê-su Krist Nơm rêh n'ho ro.\n\nChorus\nHa-lê-lu-ya rnê Nơm hŏ joi rvuăt jêh gâp. Ha-lê-lu-ya nau khĭt mâu hôm dơi kât gâp. Păng ƀư rai lĕ se rvăk nĕ. Nau tâm rklaih yor tâm Amoh Păng Yê-su Krist Nơm rêh n'ho ro.\n\nVerse 2\nGeh bunuyh dơi dơn tu nau yỗ nđach toyh ngăn. Geh nuih n'hâm dơi gĭt nau yỗ êng ngăn. Păng jêng Brah lĕ Brah yor he Păng hŏ yŭr, gay trok nau tih, sŏk nau bêk prêng. Si rkăng ntŭk Păng khĭt yỗ lĕ rngôch nau tih. Brah lĕ rngôch Brah kuăl gâp mpôl Păng. Tâm rnê Nơm Tâm Rklaih ăn gâp jêng mpôl Păng. Yê-su Krist Nơm rêh n'ho ro.\n\nChorus\nHa-lê-lu-ya rnê Nơm hŏ joi rvuăt jêh gâp. Ha-lê-lu-ya nau khĭt mâu hôm dơi kât gâp. Păng ƀư rai lĕ se rvăk nĕ. Nau tâm rklaih yor tâm Amoh Păng Yê-su Krist Nơm rêh n'ho ro.\n\nVerse 3\nNar nau ang hŏ tât bơh ntŭk bu chuăng jêh. Mpôch nau khĭt roh rai Păng hŏ dâk rêh. Păng nter huy ntĕh ktang, rĭ yău Yu-Đa mbơh ăn brah mhĭk mâu hôm lơi lơh gâp... Yê-su ơi May dơi ngăn jêh!\n\nChorus\nHa-lê-lu-ya rnê Nơm hŏ joi rvuăt jêh gâp. Ha-lê-lu-ya nau khĭt mâu hôm dơi kât gâp. Păng ƀư rai lĕ se rvăk nĕ. Nau tâm rklaih yor tâm Amoh Păng Yê-su Krist Nơm rêh n'ho ro.\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0519", "title": "MÂT TON MA BRAH NDU", "song_number": "519", "lyrics": "MÂT TON MA BRAH NDU\n\nTC 23\n\nVerse 1\nVăch lĕ rngôch bunuyh mât ton Brah Ndu, Păng jêng Kôranh Brah toyh ta klơ trôk. Tâm rnê ma Amoh Brah Yê-su Krist jêh ri mât tom ma Brah Huêng Ueh\nA-MEN\n", "category": "", "language": "Bunong"}, {"local_id": "nau-mpro-0520", "title": "NƠM GŬ TA SƯNG H'ĐĂCH", "song_number": "520", "lyrics": "NƠM GŬ TA SƯNG H'ĐĂCH\n\nTC 26\n\nVerse 1\nNơm gŭ ta sưng Ha đăch, ndrel Kon Biăp, khư tâm rnê, nau yơk, chrêk rmah nau ka tang. Tâm lĕ r-nôk, tâm lĕ r-nôk A-men, A-men, A-men\n", "category": "", "language": "Bunong"}]$json$::jsonb) as x(
    local_id text, title text, song_number text, lyrics text, category text, language text)
)
insert into public.lyric_songs (owner_id, local_id, title, song_number, lyrics, category, language)
select null, src.local_id, src.title, src.song_number, src.lyrics, src.category, src.language
from src
where not exists (select 1 from public.lyric_songs l where l.local_id = src.local_id);
